INSERT INTO `hr_appraisal_main_questions` VALUES (4, 3, NULL, '<p>Menyempurnakan tugasan yang diberi dalam tempoh masa yang ditetapkan. </p>', NULL, NULL, '2024-01-09 16:37:30', '2024-01-09 16:37:30', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (5, 3, NULL, '<p>Cepat bertindak/bergerak dan tidak menolak tanggungjawab kerja dengan berpura-pura/berdiam diri walaupun tahu apa cara untuk membuat kerja/menyelesaikan masalah.</p>', NULL, NULL, '2024-01-09 16:37:30', '2024-01-09 16:37:30', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (6, 17, NULL, '<p>Tidak dapat melakukan kerja walaupun sudah dibimbing</p>', 1, NULL, '2024-01-09 16:37:30', '2024-01-09 16:37:30', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (7, 17, NULL, '<p>Dapat melakukan kerja jika telah dibimbing oleh orang lain</p>', 2, NULL, '2024-01-09 16:37:30', '2024-01-09 16:37:30', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (8, 17, NULL, '<p>Boleh melakukan kerja dengan baik dan memerlukan bimbingan kecil sahaja</p>', 3, NULL, '2024-01-09 16:37:30', '2024-01-09 16:37:30', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (9, 17, NULL, '<p>Boleh melakukan kerja dengan baik dan kecuali dalam keadaan yang luar biasa</p>', 4, NULL, '2024-01-09 16:37:30', '2024-01-09 16:37:30', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (10, 17, NULL, '<p>Boleh melakukan keseluruhan kerja dengan baik</p>', 5, NULL, '2024-01-09 16:37:31', '2024-01-09 16:37:31', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (41, 66, NULL, '<p>Kebolehan menganalisis dan mencari punca masalah.<br />\r\n(Kebolehan dan keupayaan meneliti, mentafsir dan mencerakin fakta, situasi, kejadian dan arah aliran kepada bentuk yang mudah dan realistik serta mengemukakan cadangan tindakan yang sesuai.)</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (42, 66, NULL, '<p>Kebolehan menyelesaikan masalah dan membuat keputusan (Kebolehan mengenal pasti masalah dalam organisasi dan mengemukakan pelbagai alternatif dan menyelesaikannya secara berkesan berdasarkan ilmu pengetahuan dan kemahiran dimiliki.)</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (43, 66, NULL, '<p>Kebolehan melakukan kerja dengan sistematik dan merekodkan kerja</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (44, 66, NULL, '<p>Komitmen terhadap kerja (Mempunyai komitmen dan daya usaha yang tinggi, berpandangan jauh dan mendorong ke arah peningkatan budaya kecemerlangan organisasi secara keseluruhannya.)</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (45, 66, NULL, '<p>Memotivasikan rakan sekerja supaya lebih bertungkus-lumus dalam kerja harian (cth: selalu bertegur sapa sesama rakan sekerja, menegur kesilapan rakan sekerja)</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (46, 67, NULL, '<p>Menyempurnakan tugasan yang diberi dalam tempoh masa yang ditetapkan.</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (47, 67, NULL, '<p>Cepat bertindak/bergerak dan tidak menolak tanggungjawab kerja dengan berpura-pura/berdiam diri walaupun tahu apa cara untuk membuat kerja/menyelesaikan masalah.</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (48, 68, NULL, '<p>Membuat kerja secara sistematik dengan tahu membezakan kerja yang penting dan kurang penting.</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (49, 68, NULL, '<p>Berhati-hati dalam menjalankan tugasan dan meminimumkan tahap kesilapan.</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (50, 68, NULL, '<p>Menghasilkan kerja yang tepat, kemas dan teliti.</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (51, 68, NULL, '<p>Tidak membazirkan/mengakibatkan kerosakan sumber syarikat atas sikap pengabaian individu.</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (52, 68, NULL, '<p>Ada pengetahuan dan tahu bagaimana serta kebolehan menjalankan kerja yang diberi dengan menggunakan peralatan yang sesuai.</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (53, 69, NULL, '<p>Memastikan/mengekalkan tempat kerja dalam keadaan yang bersih, kemas, teratur dan selamat.</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (54, 69, NULL, '<p>Penjagaan peralatan dan kemudahan syarikat dengan betul seperti memastikan tools/mesin dijaga dengan baik dan suis mesin ditutup selepas digunakan.</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (55, 69, NULL, '<p>Mengutamakan keselamatan termasuk keselamatan rakan sekerja.</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (56, 70, NULL, '<p>Boleh bekerja di bawah tekanan dan menyelesaikan tugasan yang diamanahkan dengan sempurna.</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (57, 70, NULL, '<p>Bertanggungjawab ke atas kesilapan dan menerima teguran secara positif tentang kelemahan dan kesilapan yang telah dilakukan.</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (58, 70, NULL, '<p>Minat dan tumpuan yang ditunjukkan terhadap kerja.</p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-08 17:18:34', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (59, 71, NULL, '<p>Mengikuti peraturan dan polisi syarikat seperti peraturan keselamatan, kawasan larangan merokok dan penggunaan telefon bimbit ketika waktu kerja.</p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-08 17:18:34', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (60, 71, NULL, '<p>Menunjukkan ketepatan masa semasa masuk kerja (pagi, petang, rehat, waktu lepas kerja)</p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-08 17:18:34', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (61, 71, NULL, '<p>Sikap kerja yang bersungguh-sungguh dan ringan tulang semasa menjalankan tugasan dan tidak selalu meninggalkan tempat kerja tanpa alasan munasabah.</p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-08 17:18:34', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (62, 71, NULL, '<p>Membersihkan kawasan production pada masa yang ditetapkan kecuali diawalkan atau dilewatkan dalam keadaan yang dibenarkan oleh Supervisor.</p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-08 17:18:34', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (63, 71, NULL, '<p>Sentiasa bersopan dan menghormati mahupun rakan sekerja atau pegawai atasan dalam segi percakapan, tingkah laku, gerak-geri badan. (cth: tidak bergaduh atau sengaja mencederakan rakan sekerja, tidak berkelakuan buruk, tidak bersikap kasar atau berbahasa kesat)</p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-08 17:18:34', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (64, 72, NULL, '<p>Akan berinisiatif untuk mendapatkan kepastian apabila arahan atau tugasan yang diberi oleh pegawai atasan tidak jelas atau ada kesilapan.</p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-08 17:18:34', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (65, 72, NULL, '<p>Mengikuti arahan dari pegawai atasan dengan menerima informasi dengan jelas dan tepat serta persefahaman yang sama dalam kerja.</p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-08 17:18:34', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (66, 73, NULL, '<p>Sudi membantu dan memberi pertolongan. Mempunyai semangat kerjasama antara rakan sekerja dan pegawai atasan dan melaksanakan tugas secara berpasukan dan mewujudkan hubungan yang harmoni dan mesra.</p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-08 17:18:34', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (67, 73, NULL, '<p>Sudi menerima tugasan tambahan atau di luar bidang.</p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-08 17:18:34', NULL);
