INSERT INTO `hr_appraisal_main_questions` VALUES (69, 87, NULL, '<p>Dapat melakukan kerja jika telah dibimbing oleh orang lain</p>', 2, NULL, '2024-11-08 17:18:34', '2024-11-08 17:23:13', NULL);
