INSERT INTO `hr_appraisal_main_questions` VALUES (71, 87, NULL, '<p>Boleh melakukan kerja dengan baik dan kecuali dalam keadaan yang luar biasa</p>', 4, NULL, '2024-11-08 17:18:34', '2024-11-08 17:18:34', NULL);
