INSERT INTO `hr_appraisal_main_questions` VALUES (191, 151, NULL, '<p>Tidak membazirkan/mengakibatkan kerosakan sumber syarikat atas sikap pengabaian individu.</p>', NULL, NULL, '2024-11-09 15:30:31', '2024-11-09 15:30:31', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (192, 151, NULL, '<p>Ada pengetahuan dan tahu bagaimana serta kebolehan menjalankan kerja yang diberi dengan menggunakan peralatan yang sesuai.</p>', NULL, NULL, '2024-11-09 15:31:52', '2024-11-09 15:31:52', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (193, 152, NULL, '<p>Memastikan/mengekalkan tempat kerja dalam keadaan yang bersih, kemas, teratur dan selamat.</p>', NULL, NULL, '2024-11-09 15:33:40', '2024-11-09 15:33:40', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (194, 152, NULL, '<p>Penjagaan peralatan dan kemudahan syarikat dengan betul seperti memastikan tools/mesin dijaga dengan baik dan suis mesin ditutup selepas digunakan.</p>', NULL, NULL, '2024-11-09 15:34:58', '2024-11-09 15:34:58', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (195, 152, NULL, '<p>Mengutamakan keselamatan termasuk keselamatan rakan sekerja.</p>', NULL, NULL, '2024-11-09 15:36:48', '2024-11-09 15:36:48', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (196, 153, NULL, '<p>Boleh bekerja di bawah tekanan dan menyelesaikan tugasan yang diamanahkan dengan sempurna.</p>', NULL, NULL, '2024-11-09 15:38:20', '2024-11-09 15:38:20', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (197, 153, NULL, '<p>Bertanggungjawab ke atas kesilapan dan menerima teguran secara positif tentang kelemahan dan kesilapan yang telah dilakukan.</p>', NULL, NULL, '2024-11-09 15:40:16', '2024-11-09 15:40:16', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (198, 153, NULL, '<p>Minat dan tumpuan yang ditunjukkan terhadap kerja.</p>', NULL, NULL, '2024-11-09 15:41:41', '2024-11-09 15:41:41', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (199, 154, NULL, '<p>Mengikuti peraturan dan polisi syarikat seperti peraturan keselamatan, kawasan larangan merokok dan penggunaan telefon bimbit ketika waktu kerja.</p>', NULL, NULL, '2024-11-09 15:43:04', '2024-11-09 15:43:04', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (200, 154, NULL, '<p>Menunjukkan ketepatan masa semasa masuk kerja (pagi, petang, rehat, waktu lepas kerja)</p>', NULL, NULL, '2024-11-09 15:44:23', '2024-11-09 15:44:23', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (201, 154, NULL, '<p>Sikap kerja yang bersungguh-sungguh dan ringan tulang semasa menjalankan tugasan dan tidak selalu meninggalkan tempat kerja tanpa alasan munasabah.</p>', NULL, NULL, '2024-11-09 15:46:08', '2024-11-09 15:46:08', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (202, 154, NULL, '<p>Membersihkan kawasan production pada masa yang ditetapkan kecuali diawalkan atau dilewatkan dalam keadaan yang dibenarkan oleh Supervisor.</p>', NULL, NULL, '2024-11-09 15:47:23', '2024-11-09 15:47:23', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (203, 154, NULL, '<p>Sentiasa bersopan dan menghormati mahupun rakan sekerja atau pegawai atasan dalam segi percakapan, tingkah laku, gerak-geri badan. (cth: tidak bergaduh atau sengaja mencederakan rakan sekerja, tidak berkelakuan buruk, tidak bersikap kasar atau berbahasa kesat)</p>', NULL, NULL, '2024-11-09 15:48:36', '2024-11-09 15:48:36', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (204, 155, NULL, '<p>Akan berinisiatif untuk mendapatkan kepastian apabila arahan atau tugasan yang diberi oleh pegawai atasan tidak jelas atau ada kesilapan.</p>', NULL, NULL, '2024-11-09 15:51:27', '2024-11-09 15:51:27', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (205, 155, NULL, '<p>Mengikuti arahan dari pegawai atasan dengan menerima informasi dengan jelas dan tepat serta persefahaman yang sama dalam kerja.</p>', NULL, NULL, '2024-11-09 15:52:45', '2024-11-09 15:52:45', NULL);
