INSERT INTO `hr_appraisal_main_questions` VALUES (431, 311, NULL, '<p>Memastikan/mengekalkan tempat kerja dalam keadaan yang bersih, kemas, teratur dan selamat.</p>', NULL, NULL, '2024-11-21 16:26:51', '2024-11-21 16:26:51', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (432, 311, NULL, '<p>Penjagaan peralatan dan kemudahan syarikat dengan betul seperti memastikan tools/mesin dijaga dengan baik dan suis mesin ditutup selepas digunakan.</p>', NULL, NULL, '2024-11-21 16:28:23', '2024-11-21 16:28:23', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (433, 311, NULL, '<p>Mengutamakan keselamatan termasuk keselamatan rakan sekerja.</p>', NULL, NULL, '2024-11-21 16:29:57', '2024-11-21 16:29:57', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (434, 312, NULL, '<p>Boleh bekerja di bawah tekanan dan menyelesaikan tugasan yang diamanahkan dengan sempurna.</p>', NULL, NULL, '2024-11-21 16:36:16', '2024-11-21 16:36:16', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (435, 312, NULL, '<p>Bertanggungjawab ke atas kesilapan dan menerima teguran secara positif tentang kelemahan dan kesilapan yang telah dilakukan.</p>', NULL, NULL, '2024-11-21 16:37:32', '2024-11-21 16:37:32', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (436, 312, NULL, '<p>Minat dan tumpuan yang ditunjukkan terhadap kerja.</p>', NULL, NULL, '2024-11-21 16:39:33', '2024-11-21 16:39:33', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (437, 313, NULL, '<p>Mengikuti peraturan dan polisi syarikat seperti peraturan keselamatan, kawasan larangan merokok dan penggunaan telefon bimbit ketika waktu kerja.</p>', NULL, NULL, '2024-11-21 16:41:14', '2024-11-21 16:41:14', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (438, 313, 1, '<p>Menunjukkan ketepatan masa semasa masuk kerja (pagi, petang, rehat, waktu lepas kerja)</p>', NULL, NULL, '2024-11-21 16:42:43', '2024-11-21 16:42:43', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (439, 313, 2, '<p>Sikap kerja yang bersungguh-sungguh dan ringan tulang semasa menjalankan tugasan dan tidak selalu meninggalkan tempat kerja tanpa alasan munasabah.</p>', NULL, NULL, '2024-11-21 16:44:30', '2024-11-21 16:44:41', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (440, 313, 3, '<p>Membersihkan kawasan production pada masa yang ditetapkan kecuali diawalkan atau dilewatkan dalam keadaan yang dibenarkan oleh Supervisor.</p>', NULL, NULL, '2024-11-21 16:46:05', '2024-11-21 16:46:12', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (441, 313, 4, '<p>Sentiasa bersopan dan menghormati mahupun rakan sekerja atau pegawai atasan dalam segi percakapan, tingkah laku, gerak-geri badan. (cth: tidak bergaduh atau sengaja mencederakan rakan sekerja, tidak berkelakuan buruk, tidak bersikap kasar atau berbahasa kesat)</p>', NULL, NULL, '2024-11-21 16:47:46', '2024-11-21 16:47:56', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (442, 314, NULL, '<p>Akan berinisiatif untuk mendapatkan kepastian apabila arahan atau tugasan yang diberi oleh pegawai atasan tidak jelas atau ada kesilapan.</p>', NULL, NULL, '2024-11-21 16:49:27', '2024-11-21 16:49:27', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (443, 314, NULL, '<p>Mengikuti arahan dari pegawai atasan dengan menerima informasi dengan jelas dan tepat serta persefahaman yang sama dalam kerja.</p>', NULL, NULL, '2024-11-21 16:52:28', '2024-11-21 16:52:28', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (444, 315, NULL, '<p>Sudi membantu dan memberi pertolongan. Mempunyai semangat kerjasama antara rakan sekerja dan pegawai atasan dan melaksanakan tugas secara berpasukan dan mewujudkan hubungan yang harmoni dan mesra.</p>', NULL, NULL, '2024-11-21 16:54:18', '2024-11-21 16:54:18', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (445, 315, NULL, '<p>Sudi menerima tugasan tambahan atau di luar bidang.</p>', NULL, NULL, '2024-11-21 16:55:41', '2024-11-21 16:55:41', NULL);
