INSERT INTO `hr_appraisal_main_questions` VALUES (603, 426, NULL, '<p>Mengutamakan keselamatan termasuk keselamatan rakan sekerja.</p>', NULL, NULL, '2024-11-23 16:18:12', '2024-11-23 16:18:12', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (604, 427, NULL, '<p>Boleh bekerja di bawah tekanan dan menyelesaikan tugasan yang diamanahkan dengan sempurna.</p>', NULL, NULL, '2024-11-23 16:19:39', '2024-11-23 16:19:39', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (605, 427, NULL, '<p>Bertanggungjawab ke atas kesilapan dan menerima teguran secara positif tentang kelemahan dan kesilapan yang telah dilakukan.</p>', NULL, NULL, '2024-11-23 16:20:51', '2024-11-23 16:20:51', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (606, 427, NULL, '<p>Minat dan tumpuan yang ditunjukkan terhadap kerja.</p>', NULL, NULL, '2024-11-23 16:22:27', '2024-11-23 16:22:27', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (607, 428, NULL, '<p>Mengikuti peraturan dan polisi syarikat seperti peraturan keselamatan, kawasan larangan merokok dan penggunaan telefon bimbit ketika waktu kerja.</p>', NULL, NULL, '2024-11-23 16:24:09', '2024-11-23 16:24:09', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (608, 428, NULL, '<p>Menunjukkan ketepatan masa semasa masuk kerja (pagi, petang, rehat, waktu lepas kerja)</p>', NULL, NULL, '2024-11-23 16:25:35', '2024-11-23 16:25:35', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (609, 428, 1, '<p>Sikap kerja yang bersungguh-sungguh dan ringan tulang semasa menjalankan tugasan dan tidak selalu meninggalkan tempat kerja tanpa alasan munasabah.</p>', NULL, NULL, '2024-11-23 16:27:24', '2024-11-23 16:27:24', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (610, 428, 2, '<p>Membersihkan kawasan production pada masa yang ditetapkan kecuali diawalkan atau dilewatkan dalam keadaan yang dibenarkan oleh Supervisor.</p>', NULL, NULL, '2024-11-23 16:31:34', '2024-11-23 16:31:41', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (611, 428, 3, '<p>Sentiasa bersopan dan menghormati mahupun rakan sekerja atau pegawai atasan dalam segi percakapan, tingkah laku, gerak-geri badan. (cth: tidak bergaduh atau sengaja mencederakan rakan sekerja, tidak berkelakuan buruk, tidak bersikap kasar atau berbahasa kesat)</p>', NULL, NULL, '2024-11-23 16:39:31', '2024-11-23 16:39:38', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (612, 429, NULL, '<p>Akan berinisiatif untuk mendapatkan kepastian apabila arahan atau tugasan yang diberi oleh pegawai atasan tidak jelas atau ada kesilapan.</p>', NULL, NULL, '2024-11-23 17:47:29', '2024-11-23 17:47:29', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (613, 429, NULL, '<p>Mengikuti arahan dari pegawai atasan dengan menerima informasi dengan jelas dan tepat serta persefahaman yang sama dalam kerja.</p>', NULL, NULL, '2024-11-23 17:48:28', '2024-11-23 17:48:28', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (614, 430, NULL, '<p>Sudi membantu dan memberi pertolongan. Mempunyai semangat kerjasama antara rakan sekerja dan pegawai atasan dan melaksanakan tugas secara berpasukan dan mewujudkan hubungan yang harmoni dan mesra.</p>', NULL, NULL, '2024-11-23 17:49:46', '2024-11-23 17:49:46', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (615, 430, NULL, '<p>Sudi menerima tugasan tambahan atau di luar bidang.</p>', NULL, NULL, '2024-11-23 17:50:54', '2024-11-23 17:50:54', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (616, 444, 1, '<p>Tidak dapat melakukan kerja walaupun sudah dibimbing</p>', NULL, NULL, '2024-11-25 08:47:10', '2024-11-25 08:47:10', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (617, 444, NULL, '<p>Dapat melakukan kerja jika telah dibimbing oleh orang lain</p>', NULL, NULL, '2024-11-25 08:47:18', '2024-11-25 08:47:18', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (618, 444, NULL, '<p>Boleh melakukan kerja dengan baik dan memerlukan bimbingan kecil sahaja</p>', NULL, NULL, '2024-11-25 08:47:26', '2024-11-25 08:47:26', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (619, 444, NULL, '<p>Boleh melakukan kerja dengan baik dan kecuali dalam keadaan yang luar biasa</p>', NULL, NULL, '2024-11-25 08:47:35', '2024-11-25 08:47:35', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (620, 444, NULL, '<p>Boleh melakukan keseluruhan kerja dengan baik</p>', NULL, NULL, '2024-11-25 08:47:44', '2024-11-25 08:47:44', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (621, 445, NULL, '<p>Sukar dikenalpasti</p>', NULL, NULL, '2024-11-25 08:48:09', '2024-11-25 08:48:15', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (622, 445, NULL, '<p>Sesuai terhadap tanggungjawab sekarang</p>', NULL, NULL, '2024-11-25 08:48:23', '2024-11-25 08:48:23', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (623, 445, NULL, '<p>Kemungkinan sesuai untuk diberi tanggungjawab berat</p>', NULL, NULL, '2024-11-25 08:48:30', '2024-11-25 08:48:30', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (624, 445, 4, '<p>Sesuai untuk tanggungjawab berat</p>', NULL, NULL, '2024-11-25 08:49:19', '2024-11-25 08:49:19', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (625, 446, NULL, '<p>Memang sesuai</p>', NULL, NULL, '2024-11-25 08:49:38', '2024-11-25 08:49:38', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (626, 446, NULL, '<p>Boleh dipertimbangkan</p>', NULL, NULL, '2024-11-25 08:49:47', '2024-11-25 08:49:47', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (627, 446, NULL, '<p>Tidak sesuai</p>', NULL, NULL, '2024-11-25 08:49:54', '2024-11-25 08:49:54', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (628, 447, NULL, '<p>Kebolehan menganalisis dan mencari punca masalah.<br />\n(Kebolehan dan keupayaan meneliti, mentafsir dan mencerakin fakta, situasi, kejadian dan arah aliran kepada bentuk yang mudah dan realistik serta mengemukakan cadangan tindakan yang sesuai.)</p>', NULL, NULL, '2024-11-27 16:17:35', '2024-11-27 16:17:35', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (629, 447, NULL, '<p>Kebolehan menyelesaikan masalah dan membuat keputusan (Kebolehan mengenal pasti masalah dalam organisasi dan mengemukakan pelbagai alternatif dan menyelesaikannya secara berkesan berdasarkan ilmu pengetahuan dan kemahiran dimiliki.)</p>', NULL, NULL, '2024-11-27 16:18:41', '2024-11-27 16:18:41', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (630, 447, NULL, '<p>Kebolehan melakukan kerja dengan sistematik dan merekodkan kerja</p>', NULL, NULL, '2024-11-27 16:19:47', '2024-11-27 16:19:47', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (631, 447, NULL, '<p>Komitmen terhadap kerja (Mempunyai komitmen dan daya usaha yang tinggi, berpandangan jauh dan mendorong ke arah peningkatan budaya kecemerlangan organisasi secara keseluruhannya.)</p>', NULL, NULL, '2024-11-27 16:21:15', '2024-11-27 16:21:15', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (632, 447, NULL, '<p>Memotivasikan rakan sekerja supaya lebih bertungkus-lumus dalam kerja harian (cth: selalu bertegur sapa sesama rakan sekerja, menegur kesilapan rakan sekerja)</p>', NULL, NULL, '2024-11-27 16:22:10', '2024-11-27 16:22:10', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (633, 448, NULL, '<p>Menyempurnakan tugasan yang diberi dalam tempoh masa yang ditetapkan.</p>', NULL, NULL, '2024-11-27 16:23:30', '2024-11-27 16:23:30', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (634, 448, NULL, '<p>Cepat bertindak/bergerak dan tidak menolak tanggungjawab kerja dengan berpura-pura/berdiam diri walaupun tahu apa cara untuk membuat kerja/menyelesaikan masalah.</p>', NULL, NULL, '2024-11-27 16:24:51', '2024-11-27 16:24:51', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (635, 449, NULL, '<p>Membuat kerja secara sistematik dengan tahu membezakan kerja yang penting dan kurang penting.</p>', NULL, NULL, '2024-11-27 16:26:34', '2024-11-27 16:26:34', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (636, 449, NULL, '<p>Berhati-hati dalam menjalankan tugasan dan meminimumkan tahap kesilapan.</p>', NULL, NULL, '2024-11-27 17:21:24', '2024-11-27 17:21:24', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (637, 449, NULL, '<p>Menghasilkan kerja yang tepat, kemas dan teliti.</p>', NULL, NULL, '2024-11-27 17:22:46', '2024-11-27 17:22:46', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (638, 449, NULL, '<p>Tidak membazirkan/mengakibatkan kerosakan sumber syarikat atas sikap pengabaian individu.</p>', NULL, NULL, '2024-11-27 17:24:22', '2024-11-27 17:24:22', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (639, 449, NULL, '<p>Ada pengetahuan dan tahu bagaimana serta kebolehan menjalankan kerja yang diberi dengan menggunakan peralatan yang sesuai.</p>', NULL, NULL, '2024-11-27 17:33:52', '2024-11-27 17:33:52', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (640, 450, NULL, '<p>Memastikan/mengekalkan tempat kerja dalam keadaan yang bersih, kemas, teratur dan selamat.</p>', NULL, NULL, '2024-11-27 17:41:58', '2024-11-27 17:41:58', NULL);
