INSERT INTO `hr_appraisal_main_questions` VALUES (683, 475, NULL, '<p>Bertanggungjawab ke atas kesilapan dan menerima teguran secara positif tentang kelemahan dan kesilapan yang telah dilakukan.</p>', NULL, NULL, '2024-12-04 09:59:15', '2024-12-04 09:59:15', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (684, 475, NULL, '<p>Minat dan tumpuan yang ditunjukkan terhadap kerja.</p>', NULL, NULL, '2024-12-04 10:00:18', '2024-12-04 10:00:18', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (685, 476, NULL, '<p>Mengikuti peraturan dan polisi syarikat seperti peraturan keselamatan, kawasan larangan merokok dan penggunaan telefon bimbit ketika waktu kerja.</p>', NULL, NULL, '2024-12-04 11:26:28', '2024-12-04 11:26:28', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (686, 476, NULL, '<p>Menunjukkan ketepatan masa semasa masuk kerja (pagi, petang, rehat, waktu lepas kerja)</p>', NULL, NULL, '2024-12-04 11:28:05', '2024-12-04 11:28:05', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (687, 476, NULL, '<p>Sikap kerja yang bersungguh-sungguh dan ringan tulang semasa menjalankan tugasan dan tidak selalu meninggalkan tempat kerja tanpa alasan munasabah.</p>', NULL, NULL, '2024-12-04 11:29:01', '2024-12-04 11:29:01', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (688, 476, NULL, '<p>Membersihkan kawasan production pada masa yang ditetapkan kecuali diawalkan atau dilewatkan dalam keadaan yang dibenarkan oleh Supervisor.</p>', NULL, NULL, '2024-12-04 11:29:59', '2024-12-04 11:29:59', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (689, 476, NULL, '<p>Sentiasa bersopan dan menghormati mahupun rakan sekerja atau pegawai atasan dalam segi percakapan, tingkah laku, gerak-geri badan. (cth: tidak bergaduh atau sengaja mencederakan rakan sekerja, tidak berkelakuan buruk, tidak bersikap kasar atau berbahasa kesat)</p>', NULL, NULL, '2024-12-04 11:30:57', '2024-12-04 11:30:57', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (690, 477, NULL, '<p>Akan berinisiatif untuk mendapatkan kepastian apabila arahan atau tugasan yang diberi oleh pegawai atasan tidak jelas atau ada kesilapan.</p>', NULL, NULL, '2024-12-04 11:35:54', '2024-12-04 11:35:54', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (691, 477, NULL, '<p>Mengikuti arahan dari pegawai atasan dengan menerima informasi dengan jelas dan tepat serta persefahaman yang sama dalam kerja.</p>', NULL, NULL, '2024-12-04 11:37:03', '2024-12-04 11:37:03', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (692, 478, NULL, '<p>Sudi membantu dan memberi pertolongan. Mempunyai semangat kerjasama antara rakan sekerja dan pegawai atasan dan melaksanakan tugas secara berpasukan dan mewujudkan hubungan yang harmoni dan mesra.</p>', NULL, NULL, '2024-12-04 11:38:11', '2024-12-04 11:38:11', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (693, 478, NULL, '<p>Sudi menerima tugasan tambahan atau di luar bidang.</p>', NULL, NULL, '2024-12-04 11:39:09', '2024-12-04 11:39:09', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (694, 492, NULL, '<p>Tidak dapat melakukan kerja walaupun sudah dibimbing</p>', NULL, NULL, '2024-12-04 11:42:17', '2024-12-04 11:42:17', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (695, 492, NULL, '<p>Dapat melakukan kerja jika telah dibimbing oleh orang lain</p>', NULL, NULL, '2024-12-04 11:42:25', '2024-12-04 11:42:25', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (696, 492, NULL, '<p>Boleh melakukan kerja dengan baik dan memerlukan bimbingan kecil sahaja</p>', NULL, NULL, '2024-12-04 11:42:32', '2024-12-04 11:42:32', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (697, 492, NULL, '<p>Boleh melakukan kerja dengan baik dan kecuali dalam keadaan yang luar biasa</p>', NULL, NULL, '2024-12-04 11:42:40', '2024-12-04 11:42:40', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (698, 492, 5, '<p>Boleh melakukan keseluruhan kerja dengan baik</p>', NULL, NULL, '2024-12-04 11:42:49', '2024-12-04 11:42:49', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (699, 493, NULL, '<p>Sukar dikenalpasti</p>', NULL, NULL, '2024-12-04 11:43:08', '2024-12-04 11:43:08', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (700, 493, NULL, '<p>Sesuai terhadap tanggungjawab sekarang</p>', NULL, NULL, '2024-12-04 11:43:16', '2024-12-04 11:43:16', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (701, 493, NULL, '<p>Kemungkinan sesuai untuk diberi tanggungjawab berat</p>', NULL, NULL, '2024-12-04 11:43:27', '2024-12-04 11:43:27', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (702, 493, NULL, '<p>Sesuai untuk tanggungjawab berat</p>', NULL, NULL, '2024-12-04 11:43:37', '2024-12-04 11:43:37', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (703, 494, NULL, '<p>Memang sesuai</p>', NULL, NULL, '2024-12-04 11:43:59', '2024-12-04 11:43:59', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (704, 494, NULL, '<p>Boleh dipertimbangkan</p>', NULL, NULL, '2024-12-04 11:44:08', '2024-12-04 11:44:08', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (705, 494, NULL, '<p>Tidak sesuai</p>', NULL, NULL, '2024-12-04 11:47:23', '2024-12-04 11:47:23', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (706, 495, NULL, '<p>Kebolehan menganalisis dan mencari punca masalah.<br />\n(Kebolehan dan keupayaan meneliti, mentafsir dan mencerakin fakta, situasi, kejadian dan arah aliran kepada bentuk yang mudah dan realistik serta mengemukakan cadangan tindakan yang sesuai.)</p>', NULL, NULL, '2024-12-04 11:49:19', '2024-12-04 11:49:19', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (707, 495, NULL, '<p>Kebolehan menyelesaikan masalah dan membuat keputusan (Kebolehan mengenal pasti masalah dalam organisasi dan mengemukakan pelbagai alternatif dan menyelesaikannya secara berkesan berdasarkan ilmu pengetahuan dan kemahiran dimiliki.)</p>', NULL, NULL, '2024-12-04 11:50:19', '2024-12-04 11:50:19', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (708, 495, NULL, '<p>Kebolehan melakukan kerja dengan sistematik dan merekodkan kerja</p>', NULL, NULL, '2024-12-04 11:52:12', '2024-12-04 11:52:12', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (709, 495, NULL, '<p>Komitmen terhadap kerja (Mempunyai komitmen dan daya usaha yang tinggi, berpandangan jauh dan mendorong ke arah peningkatan budaya kecemerlangan organisasi secara keseluruhannya.)</p>', NULL, NULL, '2024-12-04 11:53:23', '2024-12-04 11:53:23', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (710, 495, NULL, '<p>Memotivasikan rakan sekerja supaya lebih bertungkus-lumus dalam kerja harian (cth: selalu bertegur sapa sesama rakan sekerja, menegur kesilapan rakan sekerja)</p>', NULL, NULL, '2024-12-04 11:54:18', '2024-12-04 11:54:18', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (711, 496, NULL, '<p>Membuat kerja secara sistematik dengan tahu membezakan kerja yang penting dan kurang penting.</p>', NULL, NULL, '2024-12-04 11:55:44', '2024-12-04 11:55:44', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (712, 496, NULL, '<p>Berhati-hati dalam menjalankan tugasan dan meminimumkan tahap kesilapan.</p>', NULL, NULL, '2024-12-04 11:58:12', '2024-12-04 11:58:12', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (713, 496, NULL, '<p>Menghasilkan kerja yang tepat, kemas dan teliti.</p>', NULL, NULL, '2024-12-04 11:59:18', '2024-12-04 11:59:18', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (714, 496, NULL, '<p>Tidak membazirkan/mengakibatkan kerosakan sumber syarikat atas sikap pengabaian individu.</p>', NULL, NULL, '2024-12-04 12:00:15', '2024-12-04 12:00:15', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (715, 496, NULL, '<p>Ada pengetahuan dan tahu bagaimana serta kebolehan menjalankan kerja yang diberi dengan menggunakan peralatan yang sesuai.</p>', NULL, NULL, '2024-12-04 12:01:16', '2024-12-04 12:01:16', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (716, 497, NULL, '<p>Memastikan/mengekalkan tempat kerja dalam keadaan yang bersih, kemas, teratur dan selamat.</p>', NULL, NULL, '2024-12-04 12:02:28', '2024-12-04 12:02:28', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (717, 497, NULL, '<p>Penjagaan peralatan dan kemudahan syarikat dengan betul seperti memastikan tools/mesin dijaga dengan baik dan suis mesin ditutup selepas digunakan.</p>', NULL, NULL, '2024-12-04 12:05:18', '2024-12-04 12:05:18', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (718, 497, NULL, '<p>Mengutamakan keselamatan termasuk keselamatan rakan sekerja.</p>', NULL, NULL, '2024-12-04 12:07:52', '2024-12-04 12:07:52', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (719, 498, NULL, '<p>Boleh bekerja di bawah tekanan dan menyelesaikan tugasan yang diamanahkan dengan sempurna.</p>', NULL, NULL, '2024-12-04 12:09:39', '2024-12-04 12:09:39', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (720, 498, NULL, '<p>Bertanggungjawab ke atas kesilapan dan menerima teguran secara positif tentang kelemahan dan kesilapan yang telah dilakukan.</p>', NULL, NULL, '2024-12-04 12:13:09', '2024-12-04 12:13:09', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (721, 498, NULL, '<p>Minat dan tumpuan yang ditunjukkan terhadap kerja.</p>', NULL, NULL, '2024-12-04 12:14:17', '2024-12-04 12:14:17', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (722, 499, NULL, '<p>Mengikuti peraturan dan polisi syarikat seperti peraturan keselamatan, kawasan larangan merokok dan penggunaan telefon bimbit ketika waktu kerja.</p>', NULL, NULL, '2024-12-04 12:15:28', '2024-12-04 12:15:28', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (723, 499, NULL, '<p>Menunjukkan ketepatan masa semasa masuk kerja (pagi, petang, rehat, waktu lepas kerja)</p>', NULL, NULL, '2024-12-04 12:16:28', '2024-12-04 12:16:28', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (724, 499, NULL, '<p>Sikap kerja yang bersungguh-sungguh dan ringan tulang semasa menjalankan tugasan dan tidak selalu meninggalkan tempat kerja tanpa alasan munasabah.</p>', NULL, NULL, '2024-12-04 12:17:29', '2024-12-04 12:17:29', NULL);
INSERT INTO `hr_appraisal_main_questions` VALUES (725, 499, NULL, '<p>Membersihkan kawasan production pada masa yang ditetapkan kecuali diawalkan atau dilewatkan dalam keadaan yang dibenarkan oleh Supervisor.</p>', NULL, NULL, '2024-12-04 12:18:28', '2024-12-04 12:18:28', NULL);
