INSERT INTO `hr_appraisal_marks` VALUES (8003, 254, 108, 418, NULL, NULL, NULL, 'Mempunyai semangat berkerjasama apabila diminta. \r\nKebanyakan aktiviti boleh dilakukan tanpa bimbingan \r\nBoleh memberi pendapat dan cadangan apabila nampak product design yang boleh ganggu process painting.  \r\nBoleh membuat kerja lebih masa (OT).', '2024-12-16 09:00:16', '2024-12-16 09:00:16', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (8004, 254, 108, 419, NULL, NULL, NULL, 'Kekurangan pengetahuan tentang mengendalikan sisa cat (Scheduled waste)\r\nLeadership skill agar lemah.', '2024-12-16 09:00:16', '2024-12-16 09:00:16', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (8005, 254, 108, 420, NULL, NULL, NULL, 'Perlu tingkatkan komunikasi antara rakan sekerja \r\nPerlu melatih seorang anak buah yang boleh membuat powder coating.', '2024-12-16 09:00:16', '2024-12-16 09:00:16', NULL);
