INSERT INTO `hr_appraisal_marks` VALUES (8041, 256, 76, 232, NULL, NULL, NULL, 'Ada pengetahuan dalam kerja cutting seperti screen,  \r\nAda pengetahuan tentang penyediaan drawing, mengutip part dan lakukan penghantaran.\r\nMahir mengendali forklift dan lori.', '2024-12-16 09:01:16', '2024-12-16 09:01:16', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (8042, 256, 76, 233, NULL, NULL, NULL, 'Kelemahan dalam penghantaran barang, ambil masa yang agak lambat.\r\nTiada sifat inisiatif untuk memberi pertolongan apabila ada ruang masa.\r\nKadangkala berdiam diri walaupun tahu apa cara untuk membuat kerja.', '2024-12-16 09:01:16', '2024-12-16 09:01:16', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (8043, 256, 76, 234, NULL, NULL, NULL, 'Perlu tingkatkan sikap berinisiatif dan memberi pertolongan apabila ada ruang masa. \r\nPerlu berusaha tingkakan kelajuan penghantaran barang.', '2024-12-16 09:01:16', '2024-12-16 09:01:16', NULL);
