INSERT INTO `hr_appraisal_marks` VALUES (8079, 255, 108, 418, NULL, NULL, NULL, 'Boleh lakukan kerja dengan cepat apabila diminta.\r\nKemahiran pada wet spray dan powder coating.\r\nBoleh lakukan kerja tanpa bimbingan.', '2024-12-16 09:02:21', '2024-12-16 09:02:21', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (8080, 255, 108, 419, NULL, NULL, NULL, 'Kadangkala bersembang. \r\nTiada semangat berpasukan dan tak mahu berkomunikasi dengan leader.\r\nKadang kala berhenti kerja sebelum siren bunyi.', '2024-12-16 09:02:21', '2024-12-16 09:02:21', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (8081, 255, 108, 420, NULL, NULL, NULL, 'Sebagai leader perlu membaiki kelemahan dan tunjuk teladan elok kepada anak buah.\r\nKomunikasi dan kerjasama dengan leader adalah penting dan perlu diperbaiki.', '2024-12-16 09:02:21', '2024-12-16 09:02:21', NULL);
