INSERT INTO `hr_appraisal_marks` VALUES (8193, 252, 104, 395, NULL, NULL, NULL, 'Mempunyai semangat bekerjasama dan bertindak segera apabila diminta. \r\nAda pengetahuan mengendali CNC lathe dan milling. Boleh buat program mastercam.', '2024-12-16 09:05:13', '2024-12-16 09:05:13', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (8194, 252, 104, 396, NULL, NULL, NULL, 'Kurang kebolehan memantau dan atur kerja di bahagian machining. Part yang kritikal perlu dibuat oleh pekerja mahir.\r\nPengetahuan tentang repair dan maintenance mesin perlu cuba faham dan buat dulu sebelum minta tolong.\r\nKadangkala menolak tanggungjawab da', '2024-12-16 09:05:13', '2024-12-16 09:05:13', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (8195, 252, 104, 397, NULL, NULL, NULL, 'Perlu memantau dan atur kerja di bahagian machining ikut kesesuaian skill pekerja.  \r\nPerlu tingkatkan pengetahuan maintenance mesin faham dan buat dulu sebelum minta tolong.\r\nPerlu ada sifat untuk cuba cari jalan penyelesaiaan masalah.\r\nPerlu lakukan tam', '2024-12-16 09:05:13', '2024-12-16 09:05:13', NULL);
