INSERT INTO `hr_appraisal_marks` VALUES (8231, 247, 64, 167, NULL, NULL, NULL, '1. Terdapat pengetahuan pada kebanyakan mesin \r\n2. Boleh support OT, service dan repair.\r\n3. Start belajar pemasangan RTP dan RPM.\r\n4. Kadang kala memberi pendapat assembly tentang mesin.', '2024-12-16 09:05:25', '2024-12-16 09:05:25', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (8232, 247, 64, 168, NULL, NULL, NULL, '1. Kawsan kerja yang tidak kemas.\r\n2. Belum mahir lagi dengan RTP, RPM. \r\n3. Suara terlalu kuat semasa bercakap, kacau suasana kawasan kerja.', '2024-12-16 09:05:25', '2024-12-16 09:05:25', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (8233, 247, 64, 169, NULL, NULL, NULL, '1. Pelu jaga kekemasan tempat kerja. \r\n2. Perlu tingkatkan lagi pengetahuan pemasangan RTP dan RPM.', '2024-12-16 09:05:25', '2024-12-16 09:05:25', NULL);
