INSERT INTO `hr_appraisal_marks` VALUES (8269, 253, 104, 395, NULL, NULL, NULL, 'Ada kemahiran pada CNC lathe, CNC milling dan mesin manual.\r\nAda pengetahuan laksanakan kerja di bahagian machining . \r\nMempunyai idea untuk lakukan kerja.', '2024-12-16 09:06:14', '2024-12-16 09:06:14', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (8270, 253, 104, 396, NULL, NULL, NULL, 'Kadangkala banyak berjalan dan lakukan kerja dengan beremosi.\r\nSuara kuat semasa bercakap, kacau suasana kawasan kerja.', '2024-12-16 09:06:14', '2024-12-16 09:06:14', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (8271, 253, 104, 397, NULL, NULL, NULL, 'Boleh gunakan idea yang ada, cuba study program atau buat jig/fixture yang boleh tingkatkan efisen kerja di machining.\r\nPerlu lebih serius dengan kerja dan saling menghormati di antara rakan sekerja.', '2024-12-16 09:06:14', '2024-12-16 09:06:14', NULL);
