INSERT INTO `hr_appraisal_marks` VALUES (8383, 270, 112, 441, NULL, NULL, NULL, 'Mempunyai kemahiran yang baik di bahagian welding dan boleh buat product yang rumit.\r\nMempunyai semangat memberi bantuan dan berkerjasama antara rakan sekerja. \r\nSedang cuba untuk lakukan kerja leader.', '2024-12-16 09:13:48', '2024-12-16 09:13:48', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (8384, 270, 112, 442, NULL, NULL, NULL, 'Leadership skill perlu ditingkatkan lagi. \r\nKebanyakan masa tumpu pada kerja sendiri, perlu lebih bertumpu kepada kerja dan kualiti pekerja bawahan.', '2024-12-16 09:13:48', '2024-12-16 09:13:48', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (8385, 270, 112, 443, NULL, NULL, NULL, 'Perlu berusaha memberi dorongan kepada pekerja supaya menumpukan productivity dan hasil kerja yang kualiti.\r\nPerlu memantau dan memberi teguran jika didapati masalah displin pada pekerja. \r\nPerlu ambil lebih banyak masa untuk jaga process kerja pekerja ba', '2024-12-16 09:13:48', '2024-12-16 09:13:48', NULL);
