INSERT INTO `hr_appraisal_marks` VALUES (8421, 248, 64, 167, NULL, NULL, NULL, 'Kerap memberi cadangn dan buat ECR untuk tambahbaikan.\r\nTerdapat pengetahuan pemasangan pada product yang rumit. \r\nBuat kerja secara teliti dan selalu bersedia ditempat kerja dengan awal.\r\nAda inisiatif check semula lampu dan kunci pintu sebelum balik ker', '2024-12-16 09:14:43', '2024-12-16 09:14:43', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (8422, 248, 64, 168, NULL, NULL, NULL, 'Kadang kala terlalu tumpu pada benda yang tidak kritikal menyebabkan kerja jadi lambat. \r\nTerlalu terliti pada kerja yang ringkas sehingga buat kerja yang tidak setaraf dengan kepakaran.\r\nBelum mahir pada pemasangan automation.', '2024-12-16 09:14:43', '2024-12-16 09:14:43', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (8423, 248, 64, 169, NULL, NULL, NULL, 'Perlu atur pemasangan yang ringkas dibuat oleh anak buah dan hanya tumpu pada kerja yang kritikal.\r\nPerlu usaha melatih pekerja baru.', '2024-12-16 09:14:43', '2024-12-16 09:14:43', NULL);
