INSERT INTO `hr_appraisal_marks` VALUES (8687, 445, 96, 349, NULL, NULL, NULL, 'Ada nampak kemajuan kendalikan kerja bahagian dispatch & delivery.\r\nAda perningkatan check drawing sebelum penghantaran.\r\nSudah mahir membawa forklift berbanding dengan sebelum.', '2024-12-16 09:59:38', '2024-12-16 09:59:38', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (8688, 445, 96, 350, NULL, NULL, NULL, 'Kerap buat pindaan tempat terhadap barangan yang merugikan masa.   \r\nPengetahuan terhadap pemasangan mesin perlu tingkatkan lagi.  \r\nKebanyakan tumpu pada kerja pemasangan jarang buat rondaan jaga displin dan productivity pekerja.', '2024-12-16 09:59:38', '2024-12-16 09:59:38', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (8689, 445, 96, 351, NULL, NULL, NULL, 'Perlu ada perancangan untuk kawasan letak barang untuk elak dari dua kali kerja. \r\nPerlu belajar membuat ECR terhadap penambahbaikan product.\r\nPerlu tumpu pada kawalan terhadap displin dan productivity pekerja.', '2024-12-16 09:59:38', '2024-12-16 09:59:38', NULL);
