INSERT INTO `hr_appraisal_marks` VALUES (8915, 277, 112, 441, NULL, NULL, NULL, 'Ada minat untuk belajar dan boleh faham barang yang diberitahu.\r\nAda kemahiran pada welding. Kebanyakan buat rangka mesin yang ringkas.\r\nLibat diri dan belajar buat kerja receiver tank.', '2024-12-16 10:10:21', '2024-12-16 10:10:21', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (8916, 277, 112, 442, NULL, NULL, NULL, 'Kurang kemahiran lagi membuat mesin yang rumit. \r\nKelajuan kerja yang sederhana.', '2024-12-16 10:10:21', '2024-12-16 10:10:21', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (8917, 277, 112, 443, NULL, NULL, NULL, 'Perlu lagi bimbingan untuk tingkatkan pengetahuan.\r\nKelajuan kerja boleh ditingkatkan lagi.', '2024-12-16 10:10:21', '2024-12-16 10:10:21', NULL);
