INSERT INTO `hr_appraisal_marks` VALUES (8991, 262, 92, 326, NULL, NULL, NULL, 'Ada peningkatan kemahiran mengendalikan mesin lasercut SG, APM.\r\nAda inisiatif belajar bawa forklift, welding, plasma, Blade cutting, Deburr mesin untuk membantu process kerja. Boleh bantu bending.\r\nMembuat order raw meterial yang tak cukup dan penerimaan', '2024-12-16 10:13:52', '2024-12-16 10:13:52', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (8992, 262, 92, 327, NULL, NULL, NULL, 'Kurang lagi kemahiran membawa anak buah.\r\nAda peningkatan tetapi belum menguasai dengan penuh drawing Tubest dan NEST. \r\nBelum boleh komunikasi dengan vendor tentang masalah mesin.', '2024-12-16 10:13:52', '2024-12-16 10:13:52', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (8993, 262, 92, 328, NULL, NULL, NULL, 'Perlu belajar menjadi ketua untuk melatih pekerja baru cara pengendalian laser.\r\nPerlu belajar untuk komunikasi dengan vendor tentang masalah mesin.', '2024-12-16 10:13:52', '2024-12-16 10:13:52', NULL);
