INSERT INTO `hr_appraisal_marks` VALUES (9029, 263, 92, 326, NULL, NULL, NULL, 'Ada peningkatan dan sudah ada kemahiran basic di Laser SG. Boleh mengendali process kerja bahagian loading dan unloading plate.\r\nRela meneriam tugasan tambahan dan boleh membantu bending. Ada inisiatif minta untuk sediakan plate bagi job seterus supaya me', '2024-12-16 10:14:51', '2024-12-16 10:14:51', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (9030, 263, 92, 327, NULL, NULL, NULL, 'Belum ada kemahiran di Laser APM. \r\nMenepati masa masuk tempat kerja agar lemah tetapi telah menunjukkan usaha memperbaiki.', '2024-12-16 10:14:51', '2024-12-16 10:14:51', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (9031, 263, 92, 328, NULL, NULL, NULL, 'Akan beri perluang untuk belajar laser APM.', '2024-12-16 10:14:51', '2024-12-16 10:14:51', NULL);
