INSERT INTO `hr_appraisal_marks` VALUES (9785, 259, 92, 326, NULL, NULL, NULL, 'Akan cuba menerima tugasan tambahan atau di luar bidang. \r\nBoleh memberi support kepada bahagian laser dan juga kerja maintenance untuk bahagian department lain.\r\nBoleh buat macam macam tetapi perlu pantau dengan kerap.', '2024-12-17 12:19:14', '2024-12-17 12:19:14', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (9786, 259, 92, 327, NULL, NULL, NULL, 'Kadangkala kerja yang dibuat tidak selaras dengan spesifikasi yang diberi. \r\nKekemasan tempat kerja yang agar lemah.', '2024-12-17 12:19:14', '2024-12-17 12:19:14', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (9787, 259, 92, 328, NULL, NULL, NULL, 'Perlu berinisiatif untuk memastikan fahaman kerja dengan jelas sebelum lakukan kerja. \r\nKekemasan kawasan kerja perlu ditingkatkan.', '2024-12-17 12:19:14', '2024-12-17 12:19:14', NULL);
