INSERT INTO `hr_appraisal_marks` VALUES (10456, 261, 92, 326, NULL, NULL, NULL, 'Sudah ada kemahiran basic di Laser SG dan APM. Ada kemahiran yang lebih di Laser SG.\r\nSudah mahir mengendali process kerja bahagian loading dan unloading plate.\r\nMempunyai sikap bekerjasama antara pasukan.  \r\nSudah mahir mengenali jenis plate AL, SUS, GI.', '2024-12-17 16:20:19', '2024-12-17 16:20:19', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (10457, 261, 92, 327, NULL, NULL, NULL, 'Kurang kemahiran Laser APM terutamanya bahagian pipe cutting. \r\nKebersihan sekitar kawasan kerja perlu dipertingkatkan lagi.', '2024-12-17 16:20:19', '2024-12-17 16:20:19', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (10458, 261, 92, 328, NULL, NULL, NULL, 'Kurang mahir melukis part yang ringkas.\r\nPerlu pertingkatkan lagi kemahiran mengendali APM terutama jalan pipe.', '2024-12-17 16:20:19', '2024-12-17 16:20:19', NULL);
