INSERT INTO `hr_appraisal_marks` VALUES (10570, 275, 112, 441, NULL, NULL, NULL, 'Ada menunjukkan kemahiran pada kerja dan mula buat bahagian mesin.  \r\nMudah faham apabila diajar dan tumpu pada kerja. \r\nAda kemahiran menarik skru conveyer dengan baik.', '2024-12-17 16:21:11', '2024-12-17 16:21:11', NULL);
