INSERT INTO `hr_appraisal_marks` VALUES (10572, 275, 112, 443, NULL, NULL, NULL, 'Kurang berkomunikasi, perlu tingkatkan dan bersedia komunikasi dengan leader tentang process kerja.\r\nPerlu tingkakan kemahiran buat part mesin yang rumit.', '2024-12-17 16:21:11', '2024-12-17 16:21:11', NULL);
