INSERT INTO `hr_appraisal_marks` VALUES (30545, 533, 84, 303, NULL, NULL, NULL, '1.  Untuk kerja pembaikan machine ,kemahiran yang di berikan mengikut penyelesian masalah seperti peratusan  berikut: RP 40%,SAB 40%,DS 60%,RW 30%,RS 70%,CG600 60%,GS 0%,PC70 0%,FC 0% peratusan yang di berikan ini mengikut  kemampuan pekerja ini menyelesian masalah di tempat customer.\r\n2.  Ada usaha untuk belajar dan peratusan mengikut seperti  berikut : WELDING 50%,BOLEH BACA DRAWING 60%,KENALI BARANG(PART)70%,\r\n3. Ada usaha meningkatkan diri tapi kadang kadang hilang fokus', '2025-12-02 21:55:37', '2025-12-02 21:55:37', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (30546, 533, 84, 304, NULL, NULL, NULL, '1. Kurang agresif terhadap kerja, kadang kadang kerja jadi lambat\r\n2. Tambahan cuti lebihan seleas balik dari outside seperti cuti tambahan selepas tarikah pemohonan.\r\n3. Sembunyikan masalah atau buat kerja tidak jelas,menyebabkan masalah berulang\r\n4. Report yang diberikan kurang jelas semasa report harian', '2025-12-02 21:55:37', '2025-12-02 21:55:37', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (30547, 533, 84, 305, NULL, NULL, NULL, '1. Beri peluang kepada beliau untuk berubah\r\n2. Banyakkan pendedehan tentang pemasangan dan  kerja kerja repair', '2025-12-02 21:55:37', '2025-12-02 21:55:37', NULL);
