INSERT INTO `hr_appraisal_marks` VALUES (31568, 520, 59, 145, NULL, NULL, NULL, '1. Kurang keyakinan terhadap diri untuk selesaikan masalah seperti  kata tak boleh buat tapi belum cuba buat\r\n2. Report yang diberikan kurang jelas semasa report harian\r\n3. Kehadiran ke tempat kerja kadang kadang lambat,tapi ada speed up pada kerja', '2025-12-03 21:23:14', '2025-12-03 21:23:14', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (31569, 520, 59, 146, NULL, NULL, NULL, 'Perlu lebih usaha untuk bersaing dengan rakan sekerja,Nampak ketinggalan dari semua segi, banyak selesa dengan cara kerja yang sedia ada,', '2025-12-03 21:23:14', '2025-12-03 21:23:14', NULL);
