INSERT INTO `hr_appraisal_marks` VALUES (31834, 546, 59, 145, NULL, NULL, NULL, '1. Tidak kemas selepas balik dari outside,tidak asingkan kekotoran dan campur semua barang yang elok dan rosak\r\n2. Tambahan cuti lebihan seleas balik dari outside seperti cuti tambahanselepas tarikah pemohonan\r\n3. Report yang diberikan kurang jelas semasa report harian', '2025-12-03 21:41:45', '2025-12-03 21:41:45', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (31835, 546, 59, 146, NULL, NULL, NULL, 'Banyakkan pendedehan tentang pemasangan dan  kerja kerja repair', '2025-12-03 21:41:45', '2025-12-03 21:41:45', NULL);
