INSERT INTO `hr_appraisal_marks` VALUES (33802, 516, 4, 14, NULL, NULL, NULL, '1. Ada peningkatan dari segi pemahaman machine, boleh bercerita tentang bab maintenance pada customer dan boleh serba sedikit menyelesaikan masalah dengan customer .\r\n2. feedback dengan customer baik dan pengaturan dengan customer baik\r\n3. boleh bercerita tentang drawing atau kenali part dan boleh compare dengan drawing semasa buka cocs\r\n4. follow up dengan customer baik', '2025-12-12 11:23:44', '2025-12-12 11:23:44', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (33803, 516, 4, 15, NULL, NULL, NULL, '1. perlu lebih detil lagi dengan ambilan order dengan customer bagi mengelakkan kesilapan order\r\n2. perlu lebih lagi image gambar ke betuk lukisan atau drawing untuk lebih mudah di fahami semasa buka com\r\n3. ada sedikit delay semasa buat kerja terutamanya berkaitan feedback ,mungkin maklumat tidak lengkap \r\n4.\r\n4', '2025-12-12 11:23:44', '2025-12-12 11:23:44', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (33804, 516, 4, 16, NULL, NULL, NULL, 'tambahkan lagi ilmu untuk machine yang lain, jangan selesa pada keadaan semasa, perlu cuba perkara yang baru untuk yakinkan customer dengan product ipma', '2025-12-12 11:23:44', '2025-12-12 11:23:44', NULL);
