INSERT INTO `hr_appraisal_marks` VALUES (39696, 562, 64, 167, NULL, NULL, NULL, '1. Mempunyai banyak pengalaman dan pegetahuan pada mesin.\r\n2. Sudi berbincang, memberi maklumat, pendapat dan dapat memberi pertolongan bila diminta.\r\n3. Boleh support untuk kerja customer service.\r\n4. Ada pengalaman dan kemahiran memasang RTP.', '2025-12-27 12:35:03', '2025-12-27 12:35:03', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (39697, 562, 64, 168, NULL, NULL, NULL, '1. Suara selalu kuat dan kacau suasana kerja.\r\n2. Alat dan barang pemasangan letak merata dan tidak kemas.\r\n3. Hanya mahu kerja secara sendri. Tidak tahu melatih orang bawahan.', '2025-12-27 12:35:03', '2025-12-27 12:35:03', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (39698, 562, 64, 169, NULL, NULL, NULL, '1. Perlu tingkatkan semangat untuk melatih pekerja bawahan. \r\n2. Pegalaman RPM perlu tingkatkan lagi. Perlu banyak libat pada pemasangan mesin tersebut.\r\n3. Kekemasan tempat kerja perlu tingkatkan.', '2025-12-27 12:35:03', '2025-12-27 12:35:03', NULL);
