INSERT INTO `hr_appraisal_marks` VALUES (39735, 563, 108, 419, NULL, NULL, NULL, '1. Kekurangan leadership untuk bawa anak buah.\r\n2. Kekurangan pada menjaga maintenance peralatan. \r\n3. Kurang komunikasi antara anak buah.', '2025-12-27 12:35:17', '2025-12-27 12:35:17', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (39736, 563, 108, 420, NULL, NULL, NULL, '1. Perlu tingkatkan skill leadership.\r\n2. Perlu eratkan hubungan antara rakan sekerja bahagian painting.\r\n3. Perlu melatih anak buah yang boleh lakukan powder coating.', '2025-12-27 12:35:17', '2025-12-27 12:35:17', NULL);
