INSERT INTO `hr_appraisal_marks` VALUES (39772, 550, 76, 232, NULL, NULL, NULL, '1. Mahir pengendalian forklif dan lori.\r\n2. Berpengalaman kutip barang berpandukan drawing.\r\n3. Mempunyai pengetahuan pengenalan part fabrication di bahagian production A.\r\n4. Mengikut SOP penghantaran barang dari A ke B.', '2025-12-27 12:35:34', '2025-12-27 12:35:34', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (39773, 550, 76, 233, NULL, NULL, NULL, '1. Aktiviti kerja agar lambat dari segi panghantaran. \r\n2. Kadang kala tidak jaga kebersihan kenderaan.\r\n3. Kekurangan inisiatif memberi bantuan apabila ada ruang masa.', '2025-12-27 12:35:34', '2025-12-27 12:35:34', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (39774, 550, 76, 234, NULL, NULL, NULL, '1. Tingkatkan kelajuan kerja tanpa membazir masa.\r\n2. Perlu berinisiatif menjaga kebersihan kenderaan.\r\n3. Perlu berinisiatif beri bantuan demi productivity kerja.', '2025-12-27 12:35:34', '2025-12-27 12:35:34', NULL);
