INSERT INTO `hr_appraisal_marks` VALUES (39810, 564, 108, 418, NULL, NULL, NULL, '1. Mempunyai pengalaman dan kemahiran kerja pada bahagian painting.\r\n2. Boleh beri kerjasama apabila diminta untuk lakukan kerja yang urgent.', '2025-12-27 12:35:43', '2025-12-27 12:35:43', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (39811, 564, 108, 419, NULL, NULL, NULL, '1. Kekurangan semangat berpasukan antara rakan sekerja.\r\n2. Kekurangan faham dan jarang menjaga maintenance peralatan.\r\n3. Kurang fahaman pada pengendalian schedule waste.\r\n4. Kadangkala bersembang dan berhanti kerja sebelum siren bunyi.\r\n5. Banyak alasan dan tidak mengaku kesilapan.', '2025-12-27 12:35:43', '2025-12-27 12:35:43', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (39812, 564, 108, 420, NULL, NULL, NULL, '1. Perlu tingkatkan semangat berpasukan antara leader.\r\n2. Tingkatkan maintenance peralatan.\r\n3. Perlu turut melatih anak buah yang boleh lakukan powder coating.\r\n4. Tingkatkan sikap ikhlas dan jujur.', '2025-12-27 12:35:43', '2025-12-27 12:35:43', NULL);
