INSERT INTO `hr_appraisal_marks` VALUES (39962, 556, 112, 441, NULL, NULL, NULL, '1. Pengetahuan dalam welding dan boleh buat kebanyakan mesin yang rumit. Cth GS / RP / RPM /RTP / TKC.\r\n2. Boleh bawa forklif.\r\n3. Ada kesabaran buat tugasan yang rumit dan berat.', '2025-12-27 12:38:08', '2025-12-27 12:38:08', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (39963, 556, 112, 442, NULL, NULL, NULL, '1. Boleh buat tugasan yang berat tapi kadangkala hasil kerja sedikit kasar.\r\n2. Productivity kadangkala lambat sebab langkah kerja yang kurang efisian.   \r\n3. Tempat kerja kurang kemas.', '2025-12-27 12:38:08', '2025-12-27 12:38:08', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (39964, 556, 112, 443, NULL, NULL, NULL, '1. Perlu jaga hasil kerja.\r\n2. Perlu cari idea spt buat jig untuk tingkatkan productiviti kerja.\r\n3. Tempat kerja kurang kemas.', '2025-12-27 12:38:08', '2025-12-27 12:38:08', NULL);
