INSERT INTO `hr_appraisal_marks` VALUES (40000, 557, 112, 441, NULL, NULL, NULL, '1. Mempunyai kemahiran di bahagian welding.\r\n2. Tidak menolak dan mengambil alih tanggungjawab kerja leader.\r\n3. Mempunyai sikap kerjasama dan dispiln kerja yang baik. \r\n4. Boleh bawa forklift.', '2025-12-27 12:38:28', '2025-12-27 12:38:28', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (40001, 557, 112, 442, NULL, NULL, NULL, '1. Kekurangan focus pada productivity, hasil dan displin pekerja.\r\n2. Plan kerja untuk setiap pekerja perlu tingkakatkan. \r\n3. Kadangkala terlalu focus pada kerja sendiri dan tidak dapat tumpa pada hal displin dan agihan kerja.', '2025-12-27 12:38:28', '2025-12-27 12:38:28', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (40002, 557, 112, 443, NULL, NULL, NULL, '1. Perlu usaha memberi dorongan kepada pekerja tentang productivity dan hasil pekerja.\r\n2. Perlu memantau dan memberi teguran jika didapati masalah displin pada pekerja.', '2025-12-27 12:38:28', '2025-12-27 12:38:28', NULL);
