INSERT INTO `hr_appraisal_marks` VALUES (40038, 558, 112, 441, NULL, NULL, NULL, '1. Mempunyai pengalaman dalam bahagian welding. Boleh buat pelbagai mesin yang rumit. Cth : Hot water heater / RPM / RP / RTP.\r\n2. Boleh memberi kerjasama. Cepat bertindak apabila diminta.\r\n3. Boleh bawa forklift / lori / Crane. Ada lesen lori.\r\n4. Boleh support kerja di luar kilang. Cth : Pasang platform IPMA C, Pokok Sena dan Penang.', '2025-12-27 12:39:56', '2025-12-27 12:39:56', NULL);
