INSERT INTO `hr_appraisal_marks` VALUES (40190, 570, 92, 326, NULL, NULL, NULL, '1. Sudi menerima tugasan di luar bidang kerja.\r\n2. Akan cuba buat dan tidak menolak apabila diminta.\r\n3. Mempunyai skill tersendiri, mampu welding dan repair barang.  \r\n4. Boleh bantu pengagihan material dalam prod.\r\n5. Membantu mengendali schedule waste.', '2025-12-27 12:41:22', '2025-12-27 12:41:22', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (40191, 570, 92, 327, NULL, NULL, NULL, '1. Hasil kerja tidak tentu dan tidak selaras dengan spec. \r\n2. Lakukan kerja tanpa fahaman yang jelas.', '2025-12-27 12:41:22', '2025-12-27 12:41:22', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (40192, 570, 92, 328, NULL, NULL, NULL, '1. Perlu pastikan hasil kerja menepati spec.\r\n2. Faham dengan jelas sebelum lakukan tugasan. Perlu tanya jika tidak pasti.', '2025-12-27 12:41:22', '2025-12-27 12:41:22', NULL);
