INSERT INTO `hr_appraisal_marks` VALUES (40418, 576, 112, 441, NULL, NULL, NULL, '1. Ada kemahiran pada welding dan berminat belajar apabila diberi perluang.\r\n2. Sedang berusaha tingkatkan kemahiran di laser welding. \r\n3. Hasil kerja TIG dan laser welding yang agar elok.\r\n4. Mempunyai pengalaman membuat receiver tank.', '2025-12-27 12:44:17', '2025-12-27 12:44:17', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (40419, 576, 112, 442, NULL, NULL, NULL, '1. Pengetahuan mesin masih karang.\r\n2. Kurang berkomunikasi.\r\n3. Kelajuan kerja yang sederhana.', '2025-12-27 12:44:17', '2025-12-27 12:44:17', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (40420, 576, 112, 443, NULL, NULL, NULL, '1. Perlu banyak focus pada membuat mesin daripada membuat platform dan hopper. \r\n2. Perlu tingkatkan berkomunikasi dengan leader tentang process kerja.\r\n3. Perlu tingkatkan lagi kelajuan kerja.', '2025-12-27 12:44:17', '2025-12-27 12:44:17', NULL);
