INSERT INTO `hr_appraisal_marks` VALUES (40494, 579, 92, 326, NULL, NULL, NULL, '1. Sudah mahir mengendali Laser SG dan APM.\r\n2. Ada inisiatif belajar. Sudah boleh bawa forklift, welding dan cutting.\r\n3. Ambil alih tugas menjaga material dan gas.\r\n4. Berminat untuk belajar dan tidak menolak jika diminta.\r\n5. Sudah mahir dengan process kerja di bahagian laser dan boleh buat persediaan material untuk job.\r\n6. Ada nampak peningkatan prestasi pada tahun ini.', '2025-12-27 12:44:49', '2025-12-27 12:44:49', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (40495, 579, 92, 327, NULL, NULL, NULL, '1. Kurang mahir lagi untuk membawa anak buah.', '2025-12-27 12:44:49', '2025-12-27 12:44:49', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (40496, 579, 92, 328, NULL, NULL, NULL, '1. Perlu berusaha belajar untuk membawa anak buah.\r\n2. Perlu boleh komunikasi dengan vendor tentang masalah mesin.', '2025-12-27 12:44:49', '2025-12-27 12:44:49', NULL);
