INSERT INTO `hr_appraisal_marks` VALUES (40647, 818, 92, 327, NULL, NULL, NULL, '1. Separuh mahir di SG.\r\n2. Belum mahir di APM.\r\n3. Tidak boleh bawa forklift.', '2025-12-27 12:45:35', '2025-12-27 12:45:35', NULL);
