INSERT INTO `hr_appraisal_marks` VALUES (40684, 577, 112, 441, NULL, NULL, NULL, '1. Ada kemahiran jalankan kerja bending, welding, rolling, tapping dan spot weld.\r\n2. Berminat pada kerja dan boleh kerjasama dan bertindak cepat .   \r\n3. Boleh beri tunjuk ajar kepada orang baru.\r\n4. Tahu tentang pada perocess kerja dan boleh bertindak dengan sendiri.', '2025-12-27 12:45:43', '2025-12-27 12:45:43', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (40685, 577, 112, 442, NULL, NULL, NULL, '1. Tempat kerja tidak kemas.', '2025-12-27 12:45:43', '2025-12-27 12:45:43', NULL);
