INSERT INTO `hr_appraisal_marks` VALUES (40790, 554, 104, 395, NULL, NULL, NULL, '1. Ada kemahiran pada CNC lathe, milling dan mesin manual.\r\n2. Mempunyai idea untuk lakukan kerja.\r\n3. Boleh bertindak cepat apabila diminta.', '2025-12-27 12:47:39', '2025-12-27 12:47:39', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (40791, 554, 104, 396, NULL, NULL, NULL, '1. Kadangkalan banyak berjalan dan lakukan kerja dengan beremosi.\r\n2. Suara kuat semasa bercakap, kacau suasana kawasan kerja. \r\n3. Ada sedikit negatif mind set apabila diminta buat kerja yang tidak pernah lakukan.\r\n4. Tiada initiative untuk buat kerja lain semasa menunggu mesin jalan. \r\n5. Kekurang kekemasan dan kerbersihan kawasan machining.', '2025-12-27 12:47:39', '2025-12-27 12:47:39', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (40792, 554, 104, 397, NULL, NULL, NULL, '1. Perlu serious dengan kerja dan menghormati rakan sekerja.\r\n2. Cuba study program dan buat jig yang boleh tingkatkan productiviti dan efisen kerja.\r\n3. Tingkatkan kekemasan dan kerbersihan kawasan machining.', '2025-12-27 12:47:39', '2025-12-27 12:47:39', NULL);
