INSERT INTO `hr_appraisal_marks` VALUES (41094, 566, 64, 167, NULL, NULL, NULL, '1. Mempunyai pengalaman kerja dan pengetahuan product yang baik.\r\n2. Buat kerja dengan teliti. Hasil kerja yang bagus.\r\n3. Boleh membuat record dengan elok dan turut membuat NCR dan ECR.', '2025-12-27 14:22:21', '2025-12-27 14:22:21', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (41095, 566, 64, 168, NULL, NULL, NULL, '1. Terlalu teliti pada benda yang tidak kritikal menyebabkan kerja ambil masa yang panjang untuk siap. \r\n2. Kerja yang senang dan ringkas selalu di buat sendiri. \r\n3. Kekurangan minat untuk melatih pekerja baru.', '2025-12-27 14:22:21', '2025-12-27 14:22:21', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (41096, 566, 64, 169, NULL, NULL, NULL, '1. Jangan terlalu buang masa pada kerja yang tidak kritikal. \r\n2. Kerja yang senang dan ringkas perlu melatih dan serah kepada anak buah.\r\n3. Perlu usaha melatih pekerja baru dan memberi keyakinan kepada anak buah.', '2025-12-27 14:22:21', '2025-12-27 14:22:21', NULL);
