INSERT INTO `hr_appraisal_marks` VALUES (41132, 568, 96, 349, NULL, NULL, NULL, '1. Sudah mahir kendalikan kerja bahagian dispatch dan delivery.\r\n2. Kemahiran check items yang perlu untuk delivery.\r\n3. Ada kemahiran pemasangan product palletizer dan set up layout untuk FAT.', '2025-12-27 14:23:26', '2025-12-27 14:23:26', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (41133, 568, 96, 350, NULL, NULL, NULL, '1. Leadership skill masih kurang.\r\n2. Kurang semangat majukan diri ke tahap yang lebih tinggi.\r\n3. Kurang focus pada productivity dan displin anak buah. \r\n4. Susunan barangan di production kurang teratur.', '2025-12-27 14:23:26', '2025-12-27 14:23:26', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (41134, 568, 96, 351, NULL, NULL, NULL, '1. Perlu berusaha tingkatkan diri sendiri.\r\n2. Memberi teguran pada pekerja yang tidak patuhi displin.\r\n3. Perlu ada perancangan meletak barang di production.', '2025-12-27 14:23:26', '2025-12-27 14:23:26', NULL);
