INSERT INTO `hr_appraisal_marks` VALUES (43737, 490, 4, 14, NULL, NULL, NULL, 'Sentiasa memberi sokongan yang tinggi dalam menyokong kelancaran operasi harian HR.', '2026-01-03 12:57:41', '2026-01-03 12:57:41', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (43738, 490, 4, 15, NULL, NULL, NULL, 'Perlu meningkatkan tahap kesabaran dan memastikan pengesahan dibuat terlebih dahulu sebelum melaksanakan tugasan bagi mengelakkan kesilapan.', '2026-01-03 12:57:41', '2026-01-03 12:57:41', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (43739, 490, 4, 16, NULL, NULL, NULL, 'Mempunyai potensi untuk berkembang dan telah diberi pendedahan untuk berhubung serta berurusan dengan agensi seperti JTK, JKKP dan PERKESO bagi meningkatkan pengetahuan dan pengalaman kerja.', '2026-01-03 12:57:41', '2026-01-03 12:57:41', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (43740, 490, 5, NULL, 9, NULL, NULL, NULL, '2026-01-03 12:57:41', '2026-01-03 12:57:41', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (43741, 490, 5, NULL, 734, NULL, NULL, NULL, '2026-01-03 12:57:41', '2026-01-03 12:57:41', NULL);
INSERT INTO `hr_appraisal_marks` VALUES (43742, 490, 5, NULL, 735, NULL, NULL, NULL, '2026-01-03 12:57:41', '2026-01-03 12:57:41', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (16, 4, 1, '<p>Tidak dapat menyiapkan tugasan mengikut masa yang ditetapkan dan selalu dibuat semula oleh rakan sekerja yang lain dan menyebabkan kelewatan.</p><p><br /><em>Contoh: Kerja yang sepatutnya boleh disiapkan dalam sehari tetapi dia selalu tidak hadir bekerja dan kerjanya perlu disambung / dibuat semula oleh rakan sekerja yang lain dan menyebabkan kelewatan.</em></p>', NULL, NULL, '2024-01-09 16:37:30', '2024-11-09 11:22:08', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (17, 4, 2, '<p>Selalu mengambil masa yang panjang untuk menyiapkan kerja walaupun bimbingan sudah diberi.<br /><br /><em>Contoh: Kerja yang sepatutnya boleh disiapkan dalam sehari tetapi dia mengambil masa yang panjang walaupun bimbingan sudah diberi.</em></p>', NULL, NULL, '2024-01-09 16:37:30', '2024-11-09 11:44:54', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (18, 4, 3, '<p>Tugasan biasanya dapat disiapkan dengan sedikit bimbingan dan siap dalam masa yang ditetapkan mahupun lebih awal dan hasil kerja yang masih boleh diterima.<br /><br /><em>Contoh: Boleh menghasilkan kerja dalam masa yang ditetapkan tetapi masih perlu dalam pengawasan/bimbingan.</em></p>', NULL, NULL, '2024-01-09 16:37:30', '2024-11-09 11:21:51', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (19, 4, 4, '<p>Tugasan sentiasa disiapkan tanpa bimbingan dan mengikut jadual mahupun lebih awal dan hasil kerja yang agar memuaskan.<br /><br /><em>Contoh: Boleh menghasilkan kerja dalam masa yang pendek dan tanpa sebarang pengawasan/bimbingan seperti dia cuma perlu 5 jam untuk menghasilkan kerja yang dijangka siap dalam sehari dan dia boleh menghasilkan lebih dalam satu hari.</em></p>', NULL, NULL, '2024-01-09 16:37:30', '2024-11-09 11:21:40', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (20, 4, 5, '<p>Mengutamakan masa dan pantas dalam menyiapkan tugasan yang diberi dan hasil kerja sangat bagus dan boleh diharapkan.<br /><br /><em>Contoh:Boleh membuat apa kerja yang dirancang dan menepati masa yang ditetapkan atau lebih awal tanpa pengawasan/bimbingan. Individu yang teliti dan prihatin dan menguasa masa dan memberi hasil kerja yang sangat bagus dan halus.</em></p>', NULL, NULL, '2024-01-09 16:37:30', '2024-11-09 11:21:24', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (21, 5, 1, '<p>Suka menolak tanggungjawab kerja dan berpura-pura/berdiam diri walaupun tahu apa cara untuk membuat kerja/menyelesaikan masalah.<br /><br /><em>Contoh: Langsung tidak bergerak dan pakai duduk dan tunggu sahaja walaupun sudah diberi penjelasan dalam pelan kerja.</em></p>', NULL, NULL, '2024-01-09 16:37:30', '2024-11-09 11:21:16', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (22, 5, 2, '<p>Kadangkala menolak tanggungjawab kerja dan berpura-pura/berdiam diri walaupun tahu apa cara untuk membuat kerja/menyelesaikan masalah.<br/><br/><em>Contoh: Tidak berusaha untuk belajar dan memahami pembacaan pelan kerja dan ukuran serta memerlukan seseorang mengawasi di tepi dan selalu memberi penjelasan boleh baru dapat menghasilkan kerja yang ditugaskan.</em></p>', NULL, NULL, '2024-01-09 16:37:30', '2024-01-09 16:37:30', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (23, 5, 3, '<p>Sudah faham dan boleh terus bertindak/bergerak ke atas kerja yang telah diselesaikan.<br/><br/><em>Contoh: Sudah tahu membuat kerja/menyelesaikan masalah dan tidak menolak tanggungjawab.</em></p>', NULL, NULL, '2024-01-09 16:37:30', '2024-01-09 16:37:30', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (24, 5, 4, '<p>Sudah faham dan boleh bertindak cepat ke atas semua tugasan serta tidak perlu pengawasan/bimbingan dan akan lapor balik apabila kerja telah siap.<br/><br/><em>Contoh: Bertanggungjawab dan tidak berpura-pura atau berdiam diri dalam membuat kerja/menyelesaikan masalah dan tidak perlu pengawasan/bimbingan dan akan bertindak/bergerak ke atas kerja yang ditugaskan serta lapor balik apabila kerja telah siap.</em></p>', NULL, NULL, '2024-01-09 16:37:30', '2024-01-09 16:37:30', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (25, 5, 5, '<p>Sudah faham dan boleh bertindak cepat ke atas semua tugasan serta tidak perlu pengawasan/bimbingan dan akan lapor balik apabila kerja telah siap. Selain itu, dapat memberi nasihat kepada rakan sekerja yang lain supaya cepat bertindak dalam kerja.<br/><br/><em>Contoh: Bertanggungjawab dan tidak berpura-pura atau berdiam diri dalam membuat kerja/menyelesaikan masalah dan tidak perlu pengawasan/bimbingan dan akan bertindak/bergerak ke atas kerja yang ditugaskan serta lapor balik apabila kerja telah siap. Selain itu, juga memotivasikan rakan sekerja supaya tidak berpura-pura/berdiam diri dalam membuat kerja/menyelesaikan masalah.</em></p>', NULL, NULL, '2024-01-09 16:37:30', '2024-01-09 16:37:30', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (68, 41, 1, '<p>Tidak dapat membuat apa-apa analisis dengan data yang ada dan tidak dapat mengenal pasti masalah-masalah.</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (69, 41, 2, '<p>Dapat menganalisis data yand ada dan kadang-kala dapat mencari punca masalah.</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (70, 41, 3, '<p>Dapat menganalisis data yang ada dan mencari punca masalah yang sering berlaku dan cuba memberi cadangan kepada pihak berkenaan untuk menyelesaikan masalah.</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (71, 41, 4, '<p>Dapat menganalisis data yang diperoleh, mengenal pasti masalah dengan tepat dan dapat memberi cadangan dan berusaha melaksanakan pembetulan supaya masalah tidak berlaku lagi.</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (72, 41, 5, '<p>Dapat berfikir untuk mendapat data untuk dianalisis dan menggunakan data yang diperoleh untuk mengkaji punca masalah dan membuat satu piawaian dan memastikan piawaian dapat diikut dan masalah tidak berlaku lagi.</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (73, 42, 1, '<p>Tidak dapat menyelesaikan masalah dan perlu selalu merujuk kepada senior.</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (74, 42, 2, '<p>Hanya dapat menyelesaikan masalah yang ringkas dan tidak dapat membuat keputusan dan perlu merujuk kepada senior.</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (75, 42, 3, '<p>Dapat menyelesaikan masalah-masalah yang dihadapi dengan cermat dan membuat keputusan yang betul untuk menyelesaikan masalah dalam masa tersingkat.</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (76, 42, 4, '<p>Dapat mengambil keputusan untuk menyelesaikan masalah-masalah yang dihadapi dalam masa tersingkat dan &ldquo;follow up&rdquo; supaya dapat memastikan tiada lagi masalah yang tertimbul sehingga masalah diselesaikan dan melaporkan kepada pihak atasan tentang masalah tersebut.</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (77, 42, 5, '<p>Dapat mengambil keputusan untuk menyelesaikan masalah-masalah yang dihadapi dalam masa tersingkat dan &ldquo;follow up&rdquo; sehingga masalah diselesaikan dan melaporkan kepada pihak atasan tentang masalah yang dihadapi. Di samping itu, dapat memberi pendapat dan cadangan supaya perkara tersebut tidak berlaku lagi.</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (78, 43, 1, '<p>Kerja tidak sistematik dan selalu terlupa kerja yang diberikan. Rekod kerja juga tidak dibuat dan tidak dapat kesan balik rekod kerja.</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (79, 43, 2, '<p>Kerja dilakukan tidak bersistematik dan kadang-kala terlupa akan kerja yang diberikan. Di samping itu, kerja yang dibuat tidak di rekod dengan teliti dan susah untuk dikesan balik.</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (80, 43, 3, '<p>Dapat melakukan kerja dengan sistematik, satu demi satu dan merekodkan semua kerja yang diberikan.</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (81, 43, 4, '<p>Dapat melakukan kerja dengan sistematik, merekodkan semua kerja yang diberikan dan dapat dikesan balik setiap rekod. Di samping itu, &ldquo;follow up&rdquo; setiap rekod dan pastikan setiap rekod sempurna.</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (82, 43, 5, '<p>Dapat merancang kerja sendiri dengan sistematik, mencipta dan membuat rekod dan sistem sendiri untuk pastikan kerja direkodkan dan dapat dikesan balik apabila diperlukan.</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (83, 44, 1, '<p>Seorang yang tidak bertanggungjawab dan tidak berusaha dalam kerjayanya.</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (84, 44, 2, '<p>Seorang yang bertanggungjawab tetapi tidak berkepercayaan kuat terhadap setiap tujuan dan hala organisasi.</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (85, 44, 3, '<p>Seorang yang bersikap positif dan bertanggungjawab. Berkepercayaan kuat terhadap setiap tujuan dan hala organisasi dan berkemahuan berusaha untuk kepentingan organisasi dan berkeinginan yang kuat (loyalty) untuk mempertahankan kedudukan sebagai anggota organisasi.</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (86, 44, 4, '<p>Seorang yang bersikap positif dan bertanggungjawab. Berkepercayaan kuat terhadap setiap tujuan dan hala organisasi dan berkemahuan berusaha untuk kepentingan organisasi dan berkeinginan yang kuat (loyalty) untuk mempertahankan kedudukan sebagai anggota organisasi. Selain itu, turut memberi nasihat jika terdapat rakan sekerja yang tidak sehaluan dengan pihak syarikat.</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (87, 44, 5, '<p>Seorang yang bersikap positif dan bertanggungjawab. Berkepercayaan kuat terhadap setiap tujuan dan hala organisasi dan berkemahuan berusaha untuk kepentingan organisasi dan berkeinginan yang kuat (loyalty) untuk mempertahankan kedudukan sebagai anggota organisasi. Selain itu, turut memberi nasihat jika terdapat rakan sekerja yang tidak sehaluan dengan pihak syarikat dan sentiasa mempengaruhi rakan sekerja yang lain komitmen terhadap kerja demi kebaikan bersama.</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (88, 45, 1, '<p>Bersikap negatif dan sentiasa mengadu dan membawa pengaruh negatif di kalangan rakan sekerja.</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (89, 45, 2, '<p>Memerlukan motivasi daripada rakan sekerja tetapi tidak pernah membawa pengaruh negatif di kalangan rakan sekerja.</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (90, 45, 3, '<p>Boleh memotivasikan rakan sekerja tetapi hasilnya tidak begitu besar.</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (91, 45, 4, '<p>Boleh memotivasikan rakan sekerja dengan membawa hasil yang baik di mana tahu menggunakan keadaan dan kandungan kerja sebagai panduan memotivasikan orang lain.</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (92, 45, 5, '<p>Boleh memotivasikan rakan sekerja dengan membawa hasil yang baik di mana tahu menggunakan keadaan dan kandungan kerja sebagai panduan memotivasikan orang lain. Selain itu akan melaporkan kesilapan rakan sekerja yang tidak mematuhi peraturan syarikat demi kebaikan bersama supaya tidak membawa pengaruh negatif kepada rakan sekerja yang lain.</p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (93, 46, 1, '<p>Tidak dapat menyiapkan tugasan mengikut masa yang ditetapkan dan selalu dibuat semula oleh rakan sekerja yang lain dan menyebabkan kelewatan.<br /><br /><em>Contoh: Kerja yang sepatutnya boleh disiapkan dalam sehari tetapi dia selalu tidak hadir bekerja dan kerjanya perlu disambung / dibuat semula oleh rakan sekerja yang lain dan menyebabkan kelewatan.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-25 08:52:02', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (94, 46, 2, '<p>Selalu mengambil masa yang panjang untuk menyiapkan kerja walaupun bimbingan sudah diberi.<br /><br /><em>Contoh: Kerja yang sepatutnya boleh disiapkan dalam sehari tetapi dia mengambil masa yang panjang walaupun bimbingan sudah diberi.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-25 08:52:17', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (95, 46, 3, '<p>Tugasan biasanya dapat disiapkan dengan sedikit bimbingan dan siap dalam masa yang ditetapkan mahupun lebih awal dan hasil kerja yang masih boleh diterima.<br /><br /><em>Contoh: Boleh menghasilkan kerja dalam masa yang ditetapkan tetapi masih perlu dalam pengawasan/bimbingan.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-25 08:52:29', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (96, 46, 4, '<p>Tugasan sentiasa disiapkan tanpa bimbingan dan mengikut jadual mahupun lebih awal dan hasil kerja yang agar memuaskan.<br /><br /><em>Contoh: Boleh menghasilkan kerja dalam masa yang pendek dan tanpa sebarang pengawasan/bimbingan seperti dia cuma perlu 5 jam untuk menghasilkan kerja yang dijangka siap dalam sehari dan dia boleh menghasilkan lebih dalam satu hari.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-25 08:52:41', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (97, 46, 5, '<p>Mengutamakan masa dan pantas dalam menyiapkan tugasan yang diberi dan hasil kerja sangat bagus dan boleh diharapkan.<br /><br /><em>Contoh:Boleh membuat apa kerja yang dirancang dan menepati masa yang ditetapkan atau lebih awal tanpa pengawasan/bimbingan. Individu yang teliti dan prihatin dan menguasa masa dan memberi hasil kerja yang sangat bagus dan halus.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-25 08:53:02', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (98, 47, 1, '<p>Suka menolak tanggungjawab kerja dan berpura-pura/berdiam diri walaupun tahu apa cara untuk membuat kerja/menyelesaikan masalah.<br /><br /><em>Contoh: Langsung tidak bergerak dan pakai duduk dan tunggu sahaja walaupun sudah diberi penjelasan dalam pelan kerja.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-25 08:53:17', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (99, 47, 2, '<p>Kadangkala menolak tanggungjawab kerja dan berpura-pura/berdiam diri walaupun tahu apa cara untuk membuat kerja/menyelesaikan masalah.<br /><br /><em>Contoh: Tidak berusaha untuk belajar dan memahami pembacaan pelan kerja dan ukuran serta memerlukan seseorang mengawasi di tepi dan selalu memberi penjelasan boleh baru dapat menghasilkan kerja yang ditugaskan.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-25 08:53:29', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (100, 47, 3, '<p>Sudah faham dan boleh terus bertindak/bergerak ke atas kerja yang telah diselesaikan.&nbsp;<br /><br /><em>Contoh: Sudah tahu membuat kerja/menyelesaikan masalah dan tidak menolak tanggungjawab.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-25 09:02:04', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (101, 47, 4, '<p>Sudah faham dan boleh bertindak cepat ke atas semua tugasan serta tidak perlu pengawasan/bimbingan dan akan lapor balik apabila kerja telah siap.<br /><br /><em>Contoh: Bertanggungjawab dan tidak berpura-pura atau berdiam diri dalam membuat kerja/menyelesaikan masalah dan tidak perlu pengawasan/bimbingan dan akan bertindak/bergerak ke atas kerja yang ditugaskan serta lapor balik apabila kerja telah siap.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-25 09:02:25', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (102, 47, 5, '<p>Sudah faham dan boleh bertindak cepat ke atas semua tugasan serta tidak perlu pengawasan/bimbingan dan akan lapor balik apabila kerja telah siap. Selain itu, dapat memberi nasihat kepada rakan sekerja yang lain supaya cepat bertindak dalam kerja.<br /><br /><em>Contoh: Bertanggungjawab dan tidak berpura-pura atau berdiam diri dalam membuat kerja/menyelesaikan masalah dan tidak perlu pengawasan/bimbingan dan akan bertindak/bergerak ke atas kerja yang ditugaskan serta lapor balik apabila kerja telah siap. Selain itu, juga memotivasikan rakan sekerja supaya tidak berpura-pura/berdiam diri dalam &nbsp;membuat kerja/menyelesaikan masalah.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-25 09:02:37', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (103, 48, 1, '<p>Tidak membuat kerja secara sistematik dan tidak tahu membezakan kepentingan kerja.<br /><br /><em>Contoh: Tidak tahu membezakan kepentingan kerja dan tidak buat perancangan kerja.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-25 09:02:51', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (104, 48, 2, '<p>Kadangkala ada membuat kerja secara sistematik dan kadangkala tahu membezakan kepentingan kerja tetapi keadaan tidak ketara.<br /><br /><em>Contoh: Kadangkala tahu membezakan kepentingan kerja dan buat perancangan kerja tetapi tidak selalu dan ikut mood sendiri.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-25 09:06:40', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (105, 48, 3, '<p>Tidak perlu seseorang mengawasi di tepi dan tahu membuat kerja secara sistematik dan tahu membezakan kepentingan kerja dengan penjelasan yang ringkas sahaja.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan memerlukan penjelasan kerja yang ringkas sahaja.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-25 09:06:50', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (106, 48, 4, '<p>Hanya memerlukan penjelasan yang ringkas dan tahu membuat kerja secara sistematik dan tahu membezakan kepentingan kerja. Berhati-hati dan tiada kesilapan dalam kerja yang dihasilkan.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan hanya memerlukan penjelasan kerja yang ringkas sahaja dan memberi tumpuan dalam kerja dan mengeluarkan hasil kerja yang baik.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-25 09:25:37', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (107, 48, 5, '<p>Hanya memerlukan penjelasan yang sangat ringkas sahaja untuk membuat kerja secara sistematik dan tahu membezakan kepentingan kerja dan dapat memberi tunjuk ajar kepada rakan sekerja.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan hanya memerlukan penjelasan kerja yang ringkas sahaja dan memberi tumpuan dalam kerja dan mengeluarkan hasil kerja yang baik dan turut memberi tunjuk ajar kepada rakan sekerja.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-25 09:25:48', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (108, 49, 1, '<p>Hasil kerja yang tidak boleh diterima dan selalu membuat kesilapan.<br /><br /><em>Contoh: Tidak menumpu perhatian semasa bekerja dan selalu membuat kesilapan yang sama. Tidak pernah berubah walaupun &nbsp;sudah diberi bimbingan/teguran seperti selalu mengulangi kesilapan yang sama walaupun sudah banyak kali memasang mesin yang sama model.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-25 09:26:04', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (109, 49, 2, '<p>Cuai dan mengakibatkan kesilapan kerja.<br /><br /><em>Contoh: Kadangkala cuai semasa bekerja dan mengakibatkan kesilapan kerja kerana tindakan yang lambat untuk berubah setelah diberi bimbingan/teguran.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-25 09:26:17', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (110, 49, 3, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan meminimumkan tahap kesilapan kepada yang terendah.<br /><br /><em>Contoh: Kadangkala ada membuat kesilapan tetapi mengambil tindakan yang cepat untuk berubah setelah diberi bimbingan/teguran.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-25 09:26:29', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (111, 49, 4, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan apa-apa kesilapan dalam kerja harian.<br /><br /><em>Contoh: Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan. Selain itu, juga berinisiatif untuk menjaga barangan/bahan dan tidak membazir.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-25 09:26:40', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (112, 49, 5, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan kerja dan berinisiatif untuk memberi pendapat dan memperbaiki cara kerja yang lebih baik untuk meminimumkan tahap kesilapan kerja.<br /><br /><em>Contoh: Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan dan berinisiatif untuk memberi pendapat dan memperbaiki cara kerja untuk meminimumkan tahap kesilapan kerja seperti berinisiatif untuk mengetahui masalah semasa pemasangan mesin dan turut memberi pendapat untuk memperbaiki cara kerja/menyelesaikan masalah.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-25 09:26:52', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (113, 50, 1, '<p>Langsung tidak memahami permintaan kualiti kerja dan tidak memberi perhatian kepada kerja yang dilakukan.<br /><br /><em>Contoh: Langsung tidak memahami permintaan kualiti kerja dan tidak memberi perhatian terhadap semua kerja yang dilakukan seperti membuat pemasangan Control Panel tetapi langsung tidak mengikut diagram yang diberi.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-25 09:28:12', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (114, 50, 2, '<p>Kadangkala tidak faham spesifikasi kerja yang diberi dan tidak berinisiatif mengambil langkah untuk mengetahui untuk menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Tidak berinisiatif untuk bertanya/kurang bertanya apabila tidak tahu semasa memasang Control Panel dan pasang ikut sendiri dan tidak ikut cara kerja yang betul.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-25 09:28:23', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (115, 50, 3, '<p>Memahami permintaan kualiti kerja dan dapat menghasilkan kerja yang berkualiti secara individu tanpa pengawasan pegawai atasan tetapi tidak mengambil perhatian dan abaikan kerja yang remeh temeh serta tidak mengambil perhatian terhadap kekemasan hasil kerja.<br /><br /><em>Contoh: Tahu pasang Control Panel tetapi tidak terfikir tentang kekemasan. Wayar sudah ditarik dengan betul tetapi tidak diikat dengan cable tie/tidak tersusun/tidak label semasa membuat pemasangan.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-25 09:28:35', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (116, 50, 4, '<p>Faham tentang kualiti dan dapat menghasilkan kerja yang berkualiti dan memenuhi kehendak syarikat dan dapat memastikan kerja yang dihasilkan tidak bermasalah.<br /><br /><em>Contoh: Faham tentang kualiti kerja dan ikut semua spesifikasi yang diminta. Boleh berfikir dan nampak (meramalkan) ke hadapan dan memastikan kerja yang dihasilkan tidak bermasalah seperti tahu pasang Control Panel dan semua litar boleh berfungsi dengan baik dan pemasangan yang kemas dan melaporkan keadaan kepada Leader/Supervisor apabila litar tidak berfungsi/bernyala.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-25 09:28:45', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (117, 50, 5, '<p>Sangat faham tentang kualiti kerja dan dapat menghasilkan kerja yang berkualiti dan memenuhi kehendak syarikat dan dapat memastikan kerja yang dihasilkan tidak bermasalah serta turut memberi tunjuk ajar kepada rakan kerja yang lain.&nbsp;<br /><br /><em>Contoh: Sangat faham tentang kualiti kerja dan ikut semua spesifikasi yang diminta. Boleh berfikir dan nampak (meramalkan) ke hadapan dan memastikan kerja yang dihasilkan tidak bermasalah. Selain itu, juga dapat memberi tunjuk ajar kepada rakan sekerja yang lain seperti tahu pasang Control Panel dan semua litar boleh berfungsi dengan baik dan pemasangan yang kemas dan melaporkan keadaan kepada Leader/Supervisor apabila litar tidak berfungsi/bernyala. Selain itu, dia juga memberi tunjuk ajar kepada rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-25 09:28:56', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (118, 51, 1, '<p>Sentiasa membazirkan/merosakkan sumber syarikat.<br /><br /><em>Contoh: Tidak pernah berhati-hati dalam spesifikasi kerja yang diberi dan sentiasa mengakibatkan pembaziran bahan.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-25 09:32:28', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (119, 51, 2, '<p>Ada bersikap mahu menjimatkan sumber syarikat tetapi kadangkala menyebabkan pembaziran di atas kecuaiannya.<br /><br /><em>Contoh: Cuai dalam pembacaan spesifikasi kerja yang diberi dan silap ambil bahan dan menyebabkan kesilapan dan membazirkan bahan serta perlu &ldquo;rework&rdquo;.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-25 09:32:44', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (120, 51, 3, '<p>Berhati-hati semasa bekerja dan menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dan memastikan betul supaya tidak berlaku kesilapan yang mengakibatkan pembaziran bahan dan buang masa.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-25 09:32:54', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (121, 51, 4, '<p>Berhati-hati semasa bekerja dan berinisiatif menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya. Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dengan pelan kerja dan memastikan semua barang yang ambil adalah betul. Ada pemikiran tidak membazir seperti dalam menghasilkan sesuatu barang yang sangat kecil, dia akan cari scrap dahulu dan tidak guna bahan yang baru atau bahan yang besar.Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-25 09:33:46', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (122, 51, 5, '<p>Berhati-hati semasa bekerja dan berinisiatif menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya. Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan dan juga menyedarkan dan membetulkan kesilapan rakan sekerja yang lain.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dengan pelan kerja dan memastikan semua barang yang ambil adalah betul. Ada pemikiran tidak membazir seperti dalam menghasilkan sesuatu barang yang sangat kecil, dia akan cari scrap dahulu dan tidak guna bahan yang baru atau bahan yang besar.Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan dan menyedarkan dan membetulkan kesilapan rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-25 09:34:04', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (123, 52, 1, '<p>Pengetahuan atau kemahiran adalah terhad dan tidak dapat menyelesaikan tugasan dan menggunakan masa yang panjang untuk mempelajari pengetahuan dan cara kerja yang agak senang.<br /><br /><em>Contoh: Tidak ada pengetahuan dan kemahiran kerja dan menggunakan masa yang panjang untuk mempelajari cara kerja yang senang walaupun bimbingan telah diberi seperti membuat kerja kimpalan yang paling senang iaitu mengimpal besi dalam kedudukan rata.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-25 09:58:49', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (124, 52, 2, '<p>Kurang pengetahuan atau kemahiran yang cukup untuk mengendalikan tugasan.<br /><br /><em>Contoh: Hasil kimpalan yang teruk dan bimbingan masih diperlukan walaupun diminta menghasilkan kerja kimpalan yang agak senang seperti mengimpal besi dalam kedudukan rata dan mendatar.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-25 09:58:59', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (125, 52, 3, '<p>Mempunyai pengetahuan dan kemahiran untuk mengendalikan tugasan dan mempunyai sikap mahu belajar dan mempelajari pengetahuan kerja yang baru dalam masa yang singkat dan mengimplikasikan dalam kerja harian.<br /><br /><em>Contoh: Ada pengetahuan dan kemahiran kimpalan tetapi tidak dapat meneruskan kerja apabila menghadapi kerja yang tidak biasa dan memerlukan bimbingan seperti: boleh mengimpal besi yang nipis tetapi tidak apabila diminta mengimpal besi yang lagi nipis / boleh mengimpal dalam kedudukan rata, mendatar dan menegak tetapi tidak apabila dalam keadaan overhead atau dalam keadaan 45 darjah.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-25 09:59:11', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (126, 52, 4, '<p>Boleh menguasai pengetahuan dan kemahiran untuk mengendalikan tugasan dan pencapaian yang agak memuaskan dan dapat menggunakan pengetahuannya untuk meningkatkan kualiti kerja.<br /><br /><em>Contoh: Mempunyai pengetahuan dan kemahiran yang luas serta jelas dengan semua keperluan/permintaan kerja seperti memilih kaedah yang bersesuaian untuk menghasilkan kerja dan tahu mengawal had api untuk mencegah hasil kerja dari kerosakan.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-25 09:59:22', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (127, 52, 5, '<p>Menguasai pengetahuan dan kemahiran untuk mengendalikan tugasan dan boleh menggabungkan pengetahuan untuk meningkatkan kualiti kerja serta mencari cara kerja baru untuk menyelesaikan masalah kerja dengan pengetahuannya.<br /><br /><em>Contoh: Mempunyai pengetahuan dan kemahiran yang luas serta jelas dengan semua keperluan/permintaan kerja dan berinisiatif memberi cadangan untuk menyelesaikan masalah kerja.&nbsp;</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-25 09:59:34', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (128, 53, 1, '<p>Tidak pernah mengemas dan membersihkan tempat kerja sendiri dan sentiasa mengotorkan tempat kerja sendiri dan rakan sekerja yang lain.<br /><br /><em>Contoh: Tidak pernah terfikir kebaikan bersama dan terus membuang sisa kerja ke lantai dan menganggap ini kerja cleaner untuk membersihkan.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-25 09:59:53', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (129, 53, 2, '<p>Kadangkala ada mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya tidak kemas.<br /><br /><em>Contoh: Tidak selalu mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya tidak kemas seperti kadangkala ada membersihkan tempat kerja dan kadangkala tidak.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-25 10:00:03', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (130, 53, 3, '<p>Berinisiatif untuk mengemas dan membersihkan tempat kerja dan kebanyakan masa tempat kerjanya adalah kemas dan bersih.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-26 16:15:03', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (131, 53, 4, '<p>Selalu mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya kemas dan selalu menolong membersihkan kawasan bahagiannya (division) dan kilang.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai serta tolong membersihkan kawasan yang lain.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-26 16:15:14', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (132, 53, 5, '<p>Selalu mengemas dan membersihkan tempat kerja dan tempat kerjanya kelihatan kemas dan bersih. Juga selalu menjaga kebersihan seluruh kawasan kilang dan dapat menegur rakan sekerja untuk menjaga kebersihan kilang.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai serta tolong menjaga kebersihan kawasan yang lain dan menegur rakan sekerja yang tidak menjaga kebersihan kilang.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-26 16:15:32', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (133, 54, 1, '<p>Tidak menjaga peralatan dan kemudahan syarikat.<br /><br /><em>Contoh: Tidak menjaga peralatan dan kemudahan syarikat seperti tidak menjaga forklift dan tidak pernah meletakkkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-26 16:15:47', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (134, 54, 2, '<p>Kadangkala bersikap cuai dalam mengendali peralatan dan kemudahan syarikat dan mengakibatkan kerosakan.<br /><br /><em>Contoh: Tidak selalu menjaga peralatan dan kemudahan syarikat dan mengakibatkan kerosakan seperti forklift terus jalan setelah enjin dihidupkan. Tidak mengambil berat tentang barang yang diangkat dan masuk ke ruang yang kecil. Selalu tidak meletakkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-26 16:16:00', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (135, 54, 3, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat dengan cara yang betul.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-26 16:16:14', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (136, 54, 4, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat demi kebaikan bersama. Selain itu, &nbsp;melaporkan kepada pihak atasan bila nampak rakan sekerja salahguna dan memberi cara penyelesaian yang bermanfaat.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna dan melapor jika ada kerosakan dan memberi cadangan untuk memperbaiki cara penggunaan dan penjagaan alatan.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-26 16:16:28', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (137, 54, 5, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat demi kebaikan bersama. Selain itu, &nbsp;melaporkan kepada pihak atasan bila nampak pekerja salahguna dan memberi cara penyelesaian yang bermanfaat. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna dan melapor jika ada kerosakan dan memberi cadangan untuk memperbaiki cara penggunaan dan penjagaan alatan.Selain itu, akan menyedarkan dan menasihati rakan sekerja yang tidak menjaga forklift semasa mengguna.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-26 16:16:40', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (138, 55, 1, '<p>Tidak mengutamakan keselamatan semasa bekerja.<br /><br /><em>Contoh: Tidak mengutamakan keselamatan semasa bekerja seperti tidak memakai PPE semasa bekerja.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-26 16:16:52', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (139, 55, 2, '<p>Ada sikap mengutamakan keselamatan tetapi kadangkala tidak.<br /><br /><em>Contoh: Ada memakai PPE semasa bekerja tetapi kadangkala tidak.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-26 16:17:05', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (140, 55, 3, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-26 16:17:18', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (141, 55, 4, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-26 16:17:30', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (142, 55, 5, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja dan melaporkan kepada pihak atasan serta turut memberi cara atau cara penyelesaian yang bermanfaat.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan serta turut memberi cara atau cara penyelesaian yang bermanfaat.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-26 16:17:41', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (143, 56, 1, '<p>Menerima tugasan tetapi tidak memikul tanggungjawab kerja dan tidak dapat bekerja di bawah tekanan.<br /><br /><em>Contoh: Dia terima kerja yang diberi tetapi sentiasa bersembang dengan rakan sekerja dan tidak buat kerja sehingga tidak nampak hasil kerja.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-26 16:23:52', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (144, 56, 2, '<p>Boleh menerima dan memikul tanggungjawab dan cuba untuk bekerja di bawah tekanan tetapi kadangkala tidak dapat menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Dia boleh buat kerja dan cuba elakkan diri dari tidak masuk kerja/tidak memberi alasan untuk bercuti tetapi kadangkala masih perlu dalam bimbingan.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-26 16:24:03', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (145, 56, 3, '<p>Boleh menerima dan memikul tanggungjawab dan dapat menghabiskan setiap kerja yang diamanahkan dengan baik di bawah tekanan dan melaporkan kerja yang telah dilakukan kepada pegawai atasan.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia masih menepati target dan ikut piawai kerja yang ditetapkan oleh syarikat. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia juga akan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-26 16:24:16', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (146, 56, 4, '<p>Rela menerima dan memikul tanggungjawab dan sentiasa dapat menghasilkan kerja yang berkualiti di bawah tekanan dan dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang dilakukan kepada pegawai atasan.Boleh buat kerja lebih masa sehingga kerja siap.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia akan menawarkan diri secara sukarela untuk kerja tersebut serta menepati target dan ikut piawai kerja yang ditetapkan oleh syarikat. Boleh buat kerja lebih masa sehingga kerja siap. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-26 16:24:27', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (147, 56, 5, '<p>Rela menerima dan memikul tanggungjawab serta tahu kepentingan dan deadline kerja. Dapat memanggil rakan sekerja untuk menyiapkan kerja bersama. Sentiasa dapat menghasilkan kerja yang berkualiti di bawah tekanan dan dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang dilakukan kepada pegawai atasan.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia tahu kepentingan dan deadline kerja tersebut serta dapat memanggil rakan sekerja untuk menyiapkan kerja bersama. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-26 16:24:38', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (148, 57, 1, '<p>Tidak rela mengaku kesilapan dan suka menolak tanggungjawab kepada orang lain.<br /><br /><em>Contoh: Telah melakukan kesilapan seperti tidak mengikuti spesifikasi kerja yang diberi oleh Leader / tidak tanya Leader apabila tidak faham / tanya rakan sekerja yang tidak dipertanggungjawabkan dan tidak pernah mengakui kesilapan apabila ditegur oleh Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-26 16:24:53', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (149, 57, 2, '<p>Kadangkala tidak rela mengaku kesilapan dan suka membuat perbandingan diri dengan orang lain dalam kesilapan yang telah dibuat.<br /><br /><em>Contoh: Telah melakukan kesilapan seperti tidak mengikuti spesifikasi kerja yang diberi oleh Leader / tidak tanya Leader apabila tidak faham / tanya rakan sekerja yang tidak dipertanggungjawabkan dan kadangkala tidak mengakui kesilapan apabila ditegur oleh Leader/Supervisor malah menyatakan Leader/Supervisor ada prasangka terhadap dia.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 16:25:05', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (150, 57, 3, '<p>Mengaku kesilapan dan tidak menolak tanggungjawab kepada orang lain.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan. Dia terima dan mengakui kesilapan.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 16:44:02', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (151, 57, 4, '<p>Tidak melarikan diri dari tanggungjawab dan terus berjumpa dengan pihak atasan untuk mengakui kesilapan dan berinisiatif untuk memperbaiki kesilapan yang telah dilakukan.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan. Dia tidak melarikan diri dari tanggungjawab dan terus berjumpa dengan Leader/Supervisor dan mengakui kesilapan. Selain itu, dia juga memberi cadangan dan sama-sama memperbaiki kesilapan yang telah dilakukan.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 16:44:14', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (152, 57, 5, '<p>Berani mengaku kesilapan dan tidak menolak tanggungjawab dan memastikan kesilapan tidak berlaku lagi. Berinisiatif untuk memperbetulkan kesilapan dan dapat memberi cadangan yang bermanfaat untuk mengelakkan kesilapan berlaku lagi.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan yang agak besar. Dia berani mengakui kesilapan dan terus berjumpa dengan Leader/Supervisor untuk mengakui kesilapan. Dia mengambil pengalaman tersebut sebagai satu pengajaran dan tidak mengulangi kesilapan tersebut lagi. Selain itu, dia &nbsp;memberi cadangan dan sama-sama memperbaiki kesilapan yang telah dilakukan serta memberi cadangan yang bermanfaat untuk mengelakkan kesilapan berlaku lagi.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 16:44:25', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (153, 58, 1, '<p>Membuat kerja alah kadar dan setakat membuat kerja sahaja dan tidak menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Tidak menunjukkan sikap ingin belajar dan tidak menumpukan perhatian semasa bekerja seperti dia boleh mengambil masa yang panjang untuk memasang beberapa nut pada mesin.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 16:44:39', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (154, 58, 2, '<p>Boleh membuat kerja tetapi mudah dipengaruhi orang lain dan kadangkala tidak dapat menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Dia boleh pasang nut pada mesin tetapi mudah dipengaruhi oleh rakan sekerja yang lain seperti dia akan melambatkan proses kerjanya dan sambil kerja sambil bersembang apabila ada rakan sekerja yang bersembang dengannya semasa bekerja.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 16:44:49', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (155, 58, 3, '<p>Lebih agresif dan sikap kerja juga serius dan dapat menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak mengangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 16:45:01', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (156, 58, 4, '<p>Bersemangat kerja dan menumpukan perhatian sepenuhnya dalam kerja. Sentiasa mengutamakan kualiti kerja dan menghasilkan kerja yang halus dan teliti dan tidak melakukan kesilapan.<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak menggangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja. Dia sentiasa mengutamakan kualiti kerja dan memastikan nut yang dipasang itu betul dan kemas.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 16:45:13', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (157, 58, 5, '<p>Matlamat untuk berjaya sangat jelas. Menumpukan perhatian sepenuhnya dalam kerja. Sentiasa mengutamakan kualiti kerja dan menghasilkan kerja yang halus dan teliti dan tidak melakukan kesilapan. Selain itu turut memberi cadangan dan cara kerja untuk memastikan kerja berkualiti dihasilkan setiap kali.&nbsp;<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak menggangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja. Dia sentiasa mengutamakan kualiti kerja dan memastikan nut yang dipasang itu betul dan kemas. Selain itu, dia juga akan memberi cadangan untuk memastikan kerja berkualiti dapat dihasilkan.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 16:45:23', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (158, 59, 1, '<p>Langsung tidak mahu memahami dan menerima peraturan dan polisi syarikat dan sentiasa membuat aduan terhadap dasar syarikat.<br /><br /><em>Contoh: Selalu tidak menutup lampu setelah mengguna tandas dan membuat aduan apabila pihak syarikat mengambil tindakan.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 16:45:39', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (159, 59, 2, '<p>Kadangkala sahaja mahu menerima dan mematuhi peraturan dan polisi syarikat.<br /><br /><em>Contoh: Kadangkala ada menutup lampu setelah mengguna tandas kadangkala tidak.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 16:45:50', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (160, 59, 3, '<p>Menerima dan mematuhi setiap peraturan dan polisi syarikat.<br /><br /><em>Contoh: Setiap kali akan menutup lampu setelah mengguna tandas.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 16:46:01', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (161, 59, 4, '<p>Tidak melanggar peraturan dan sentiasa dapat menasihatkan rakan sekerja untuk menerima dan mematuhi peraturan dan polisi syarikat untuk kebaikan bersama.<br /><br /><em>Contoh: Sentiasa menutup lampu setelah mengguna tandas dan &nbsp;menasihati dan menerang kepada rakan sekerja yang tidak mematuhi peraturan.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 16:46:10', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (162, 59, 5, '<p>Memahami dan menerima setiap peraturan dan polisi syarikat dan sentiasa menasihatkan rakan sekerja yang melanggar peraturan serta melaporkan masalah disiplin kepada pegawai atasan untuk kebaikan bersama.<br /><br /><em>Contoh: &nbsp;Sentiasa menutup lampu setelah mengguna tandas dan &nbsp;menasihati dan menerang kepada rakan sekerja yang tidak mematuhi peraturan. Selain itu, juga akan melaporkan nama pekerja yang tidak menutup lampu setelah mengguna tandas.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 16:46:22', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (163, 60, 1, '<p>Selalu tidak tepat masuk kerja dan menunjukkan kedatangan yang tidak baik.<br /><br /><em>Contoh: Masih berada di tempat berehat semasa siren berbunyi dan jalan perlahan ke tempat kerja.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 16:46:35', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (164, 60, 2, '<p>Kadangkala ada masuk kerja pada masa yang ditetapkan tetapi keadaan tidak ketara.<br /><br /><em>Contoh: Kadangkala ada tepat masuk kerja semasa siren berbunyi tetapi kebanyakan masa tidak masuk kerja pada masa yang tepat.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 16:46:47', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (165, 60, 3, '<p>Kebanyakan masa masuk kerja pada masa yang ditetapkan tetapi kadangkala ada lewat juga.<br /><br /><em>Contoh: Kebanyakan masa masuk kerja semasa siren berbunyi tetapi sekali kala masih lewat masuk kerja.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 16:46:57', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (166, 60, 4, '<p>Mementingkan ketepatan masa masuk kerja dan masuk kerja tepat pada masa atau lebih awal.<br /><br /><em>Contoh: Sentiasa masa masuk kerja sebelum siren berbunyi atau lebih awal.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 16:47:10', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (167, 60, 5, '<p>Mementingkan ketepatan masa masuk kerja dan masuk kerja tepat pada masa atau lebih awal serta memberi nasihat kepada rakan sekerja yang lewat.<br /><br /><em>Contoh: Sentiasa masa masuk kerja sebelum siren berbunyi atau lebih awal serta memberi nasihat kepada rakan sekerja yang lewat.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 16:47:20', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (168, 61, 1, '<p>Disiplin diri yang tidak memuaskan dan sering meninggalkan tempat kerja dengan berkeliaran tanpa tujuan dan sering membazirkan masa serta curi tulang.<br /><br /><em>Contoh: Sering meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja (banyak kali sehari) dan mengambil masa yang panjang dalam tandas serta membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 16:48:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (169, 61, 2, '<p>Kadangkala membazirkan masa dan curi tulang serta meninggalkan tempat kerja dengan berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Kadangkala meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja (banyak kali sehari) dan mengambil masa yang panjang dalam tandas serta membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 16:48:21', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (170, 61, 3, '<p>Tidak membazirkan masa dan ringan tulang serta menumpukan perhatian semasa bekerja. Tidak meninggalkan tempat kerja dengan berkeliaran tanpa tujuan.<br /><br /><em>Contoh: Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 16:48:31', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (171, 61, 4, '<p>Teladan yang baik dan tumpuan perhatian sepenuhnya semasa bekerja. Tidak berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Seorang teladan yang baik dan memberi tumpuan sepenuhnya semasa bekerja. Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 16:48:43', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (172, 61, 5, '<p>Teladan yang baik dan tumpuan perhatian sepenuhnya semasa bekerja dan juga selalu memberi nasihat kepada rakan sekerja supaya melahirkan keadaan kerja yang lebih agresif. Tidak berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Seorang teladan yang baik dan memberi tumpuan sepenuhnya semasa bekerja. Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja. Selalu memberi nasihat kepada rakan sekerja yang selalu pergi ke tandas sebagai alasan.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 16:48:54', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (173, 62, 1, '<p>Tidak pernah berada di tempat kerja semasa pembersihan kawasan dijalankan.<br /><br /><em>Contoh: Tidak berada di tempat kerja dan pergi ke tandas semasa pembersihan kawasan dijalankan.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 16:49:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (174, 62, 2, '<p>Memulakan kerja pembersihan kawasan walaupun masa yang ditetapkan belum sampai lagi.<br /><br /><em>Contoh: Memulakan kerja pembersihan kawasan walaupun masa yang ditetapkan belum sampai lagi dan rakan sekerja yang lain masih bekerja lagi.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 16:49:20', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (175, 62, 3, '<p>Kebanyakan masa membersihkan kawasan production pada masa yang ditetapkan.</p><p>Kadangkala membersihkan kawasan production pada masa yang ditetapkan tetapi keadaan tidak ketara.</p><p><br />\nContoh: Kadangkala ada berada di production semasa pembersihan kawasan dijalankan tetapi kebanyakan masa tidak nampak orang.</p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 16:49:32', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (176, 62, 4, '<p>Sentiasa mengutamakan dan membersihkan kawasan production pada masa yang ditetapkan.<br /><br /><em>Contoh: Sentiasa membersihkan kawasan production pada masa yang ditetapkan.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 16:49:43', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (177, 62, 5, '<p>Mengutamakan dan membersihkan kawasan production pada masa yang ditetapkan serta memberi nasihat kepada rakan sekerja yang tidak berbuat demikian.<br /><br /><em>Contoh: Sentiasa membersihkan kawasan production pada masa yang ditetapkan dan memberi nasihat kepada rakan sekerja yang tidak berbuat demikian.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 16:50:15', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (178, 63, 1, '<p>Hanya menghormati pegawai atasan dan tidak bersopan dengan rakan sekerja.<br /><br /><em>Contoh: Hanya menghormati Leader/Supervisor atau pangkat kerja yang lebih tinggi tetapi tidak bersopan dengan rakan sekerja yang berpangkat rendah/masih baru.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 16:50:53', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (179, 63, 2, '<p>Biasanya akan bersopan dan menghormati orang lain tetapi kadangkala beremosi.<br /><br /><em>Contoh: Biasanya bersopan dan menghormati rakan sekerja yang lain tetapi kadangkala beremosi dan lawan cakap.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 16:51:04', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (180, 63, 3, '<p>Sering bersopan dan menghormati orang lain dan tidak bertindak mengikut perasaan.<br /><br /><em>Contoh: Sering bersopan dan menghormati rakan sekerja lain dan tidak bertindak mengikut perasaan.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 16:51:16', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (181, 63, 4, '<p>Bersopan dan menghormati orang lain pada setiap masa dan tidak bertindak mengikut perasaan dan berbahasa sopan.<br /><br /><em>Contoh: Bersopan dan setiap masa menghormati rakan sekerja yang lain dan tidak bertindak mengikut perasaan dan berbahasa sopan serta jaga perasaan rakan lain.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 16:51:27', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (182, 63, 5, '<p>Bersopan dan menghormati orang lain pada setiap masa dan masih bercakap dengan sopan walaupun sendiri telah dipersalahkan dalam proses penyelesaian masalah.<br /><br /><em>Contoh: Bersopan dan setiap masa menghormati rakan sekerja yang lain dan masih bercakap dengan sopan walaupun sendiri telah dipersalahkan dalam proses penyelesaian masalah.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-12-04 11:35:20', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (183, 64, 1, '<p>Memang mengetahui arahan yang diberi mempunyai kesilapan tetapi tidak mendapatkan kepastian kerana berpendapat itu adalah tanggungjawab pegawai atasan.<br /><br /><em>Contoh: Tidak mendapatkan kepastian daripada Leader/Supervisor tentang spesifikasi kerja yang diberi walaupun sudah tahu arahan yang diberi mempunyai kesilapan/tidak jelas dan beranggap itu adalah tanggungjawab Leader/Supervisor dan bukan dia.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 17:33:39', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (184, 64, 2, '<p>Jarang berinisiatif untuk mendapatkan kepastian daripada pegawai atasan walaupun arahan yang diberi tidak jelas atau silap.<br /><br /><em>Contoh: Menunjukkan sikap sudah tahu tetapi tidak ingin peduli dan tidak mendapatkan kepastian daripada Leader/Supervisor walapun arahan yang diberi ada kesilapan/kurang jelas.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 17:35:51', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (185, 64, 3, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap tetapi tidak pernah melapor balik kepada pegawai atasan tentang tugasan tersebut.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi ada kesilapan/tidak jelas tetapi tidak pernah melapor balik tugasan tersebut.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 17:36:00', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (186, 64, 4, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi tidak jelas/silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 17:36:12', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (187, 64, 5, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut serta memberi pendapat yang bermanfaat.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi tidak jelas/silap dan selalu melapor balik kepada Leader/Supervisor dan turut mengambil bahagian untuk memberi pendapat yang bermanfaat. </em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 17:36:22', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (188, 65, 1, '<p>Degil dan berpegang teguh dengan pendapat sendiri dan tidak menuruti arahan pegawai atasan.<br /><br /><em>Contoh: Tidak menerima dan melawan percakapan Leader/Supervisor semasa diberi tugasan.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 17:36:36', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (189, 65, 2, '<p>Kebanyakan masa akan menuruti arahan pegawai atasan tetapi kadangkala akan beremosi dan meluahkan ketidakpuasan.<br /><br /><em>Contoh: Kebanyakan masa akan menerima tugasan Leader/Supervisor dengan baik tetapi kadangkala tidak.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 17:36:47', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (190, 65, 3, '<p>Mengambil berat dan menuruti arahan pegawai atasan dan tidak pernah membuat hal sesuka hati.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati dan akan bertanya jika tidak faham.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 17:36:58', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (191, 65, 4, '<p>Mengambil berat dan menuruti arahan pegawai atasan dan tidak pernah membuat hal sesuka hati. Kadangkala turut memberikan pendapat yang bermanfaat dalan kerja yang diberi.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati dan akan bertanya jika tidak faham. Kadangkala turut memberi cadangan/pandangan dalam kerja yang diberi.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 17:37:08', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (192, 65, 5, '<p>Bersikap positif dan menuruti semua arahan pegawai atasan, tidak membuat hal malah dapat menyampaikan objektif dan kehendak arahan secara positif kepada semua rakan sekerja.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati. Turut menyampaikan maksud dan kehendak mengikuti arahan Leader/Supervisor secara positif kepada rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 17:37:18', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (193, 66, 1, '<p>Ego dan tidak sudi berbincang tugasan sesama rakan sekerja dan pegawai atasan, sangat keras kepala dan tidak dapat menerima cadangan orang lain.<br /><br /><em>Contoh: Buat kerja tanpa ikut pelan kerja seperti menebuk drill pada kelajuan yang tinggi dan telah membesarkan lubang 3mm kepada 3.20 mm. Dia tidak dapat menerima apabila diminta buat semula pada kelajuan drill yang rendah.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 17:37:32', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (194, 66, 2, '<p>Jarang berbincang tugasan sesama rakan sekerja dan pegawai atasan dan tidak begitu rela berkongsi maklumat, kadangkala keras kepala dan tidak dapat menerima cadangan orang lain.<br /><br /><em>Contoh: Dia menunjukkan sikap yang tidak begitu gembira apabila diminta buat semula pada kelajuan drill yang rendah.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 17:37:43', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (195, 66, 3, '<p>Sudi berbincang dan menerima cadangan rakan sekerja dan pegawai atasan, dapat memberi pertolongan apabila diminta.<br /><br /><em>Contoh: Dia sudi membuat semula pada kelajuan drill yang rendah setelah berbincang dan diminta berubah.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 17:37:54', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (196, 66, 4, '<p>Sudi berbincang dan berinisiatif memberi pertolongan sesama rakan sekerja dan pegawai atasan dengan tidak berkira kerja. Boleh menerima cadangan orang lain dan tidak berkeras kepala.<br /><br /><em>Contoh: Dia sudi membuat semula pada kelajuan drill yang rendah dan dia turut memberi cadangan untuk mengatasi masalah tersebut. </em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 17:38:08', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (197, 66, 5, '<p>Sudi berbincang dan berinisiatif memberi pertolongan sesama rakan sekerja dan pegawai atasan dengan tidak berkira kerja. Boleh menerima cadangan orang lain dan tidak berkeras kepala. Selain itu, turut boleh memanggil rakan sekerja untuk sama-sama menyiapkan kerja tersebut.<br /><br /><em>Contoh: Dia ialah orang yang sangat agresif dan sudi membuat semula dan dia turut boleh meminta rakan sekerja untuk sama-sama menyiapkan kerja.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 17:38:20', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (198, 67, 1, '<p>Menolak tugasan selain dari bidang sendiri dan langsung tidak dapat menerima tugasan tambahan atau di luar bidang kerja, amat mementingkan diri sendiri.<br /><br /><em>Contoh: Tidak mahu backup rakan sekerja yang bercuti dan selalu dipengaruhi oleh rakan sekerja yang lain dimana orang yang berbuat banyak tidak dapat apa-apa.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 17:38:39', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (199, 67, 2, '<p>Kadangkala menerima tugasan tambahan atau di luar bidang kerja tetapi dengan hati yang tidak rela dan mementingkan kepentingan diri sendiri.<br /><br /><em>Contoh: Kadangkala akan diminta untuk backup rakan sekerja yang bercuti tetapi dia akan membuat kerja secara tidak rela / memberi alasan bahawa dia tidak tahu buat kerja tersebut.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 17:38:51', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (200, 67, 3, '<p>Rela menerima tugasan tambahan atau di luar bidang dan tidak menolak apabila tugas diberi.<br /><br /><em>Contoh: Rela backup rakan sekerja yang bercuti dan tidak menolak apabila tugas diberi oleh Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 17:39:00', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (201, 67, 4, '<p>Rela menerima tugasan tambahan atau di luar bidang dan tidak menolak apabila tugas diberi serta cuba mencari cara untuk menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Rela backup rakan sekerja yang bercuti dan tidak menolak apabila tugas diberi oleh Leader / Supervisor. Selain itu, dia juga cari jalan untuk mengeluarkan hasil kerja yang baik / membuat kerja tersebut dengan bersungguh-sungguh.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 17:39:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (202, 67, 5, '<p>Amat rela menerima tugasan tambahan atau di luar bidang dan menerimanya sebagai satu cabaran. Berusaha dan bertanggungjawab sepenuhnya sehingga tugasan selesai dengan sempurna.<br /><br /><em>Contoh: Sangat rela backup rakan sekerja yang bercuti dan menganggap tugas yang diberi tersebut sebagai satu cabaran / tugas sendiri. Dia membuat kerja dengan sepenuh hati dan mengambil tanggungjawab sehingga tugasan tersebut selesai dengan sempurnanya.</em></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-26 17:39:20', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (504, 152, 1, '<p>Tidak dapat menyiapkan tugasan mengikut masa yang ditetapkan dan selalu dibuat semula oleh rakan sekerja yang lain dan menyebabkan kelewatan.<br /><br /><em>Contoh: Kerja yang sepatutnya boleh disiapkan dalam sehari tetapi dia selalu tidak hadir bekerja dan kerjanya perlu disambung / dibuat semula oleh rakan sekerja yang lain dan menyebabkan kelewatan.</em></p>', NULL, NULL, '2024-11-09 12:25:39', '2024-11-09 12:25:39', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (505, 152, 2, '<p>Selalu mengambil masa yang panjang untuk menyiapkan kerja walaupun bimbingan sudah diberi.<br /><br /><em>Contoh: Kerja yang sepatutnya boleh disiapkan dalam sehari tetapi dia mengambil masa yang panjang walaupun bimbingan sudah diberi.</em></p>', NULL, NULL, '2024-11-09 12:25:39', '2024-11-09 12:25:39', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (506, 152, 3, '<p>Tugasan biasanya dapat disiapkan dengan sedikit bimbingan dan siap dalam masa yang ditetapkan mahupun lebih awal dan hasil kerja yang masih boleh diterima.<br /><br /><em>Contoh: Boleh menghasilkan kerja dalam masa yang ditetapkan tetapi masih perlu dalam pengawasan/bimbingan.</em></p>', NULL, NULL, '2024-11-09 12:25:39', '2024-11-09 12:25:39', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (507, 152, 4, '<p>Tugasan sentiasa disiapkan tanpa bimbingan dan mengikut jadual mahupun lebih awal dan hasil kerja yang agar memuaskan.<br /><br /><em>Contoh: Boleh menghasilkan kerja dalam masa yang pendek dan tanpa sebarang pengawasan/bimbingan seperti dia cuma perlu 5 jam untuk menghasilkan kerja yang dijangka siap dalam sehari dan dia boleh menghasilkan lebih dalam satu hari.</em></p>', NULL, NULL, '2024-11-09 12:25:39', '2024-11-09 12:25:39', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (508, 152, 5, '<p>Mengutamakan masa dan pantas dalam menyiapkan tugasan yang diberi dan hasil kerja sangat bagus dan boleh diharapkan.<br /><br /><em>Contoh:Boleh membuat apa kerja yang dirancang dan menepati masa yang ditetapkan atau lebih awal tanpa pengawasan/bimbingan. Individu yang teliti dan prihatin dan menguasa masa dan memberi hasil kerja yang sangat bagus dan halus.</em></p>', NULL, NULL, '2024-11-09 12:25:39', '2024-11-09 12:25:39', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (509, 153, 1, '<p>Suka menolak tanggungjawab kerja dan berpura-pura/berdiam diri walaupun tahu apa cara untuk membuat kerja/menyelesaikan masalah.<br /><br /><em>Contoh: Langsung tidak bergerak dan pakai duduk dan tunggu sahaja walaupun sudah diberi penjelasan dalam pelan kerja.</em></p>', NULL, NULL, '2024-11-09 12:27:34', '2024-11-09 12:27:34', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (510, 153, 2, '<p>Kadangkala menolak tanggungjawab kerja dan berpura-pura/berdiam diri walaupun tahu apa cara untuk membuat kerja/menyelesaikan masalah.<br /><br /><em>Contoh: Tidak berusaha untuk belajar dan memahami pembacaan pelan kerja dan ukuran serta memerlukan seseorang mengawasi di tepi dan selalu memberi penjelasan boleh baru dapat menghasilkan kerja yang ditugaskan.</em></p>', NULL, NULL, '2024-11-09 12:28:07', '2024-11-09 12:28:07', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (511, 153, 3, '<p>Sudah faham dan boleh terus bertindak/bergerak ke atas kerja yang telah diselesaikan.&nbsp;<br /><br /><em>Contoh: Sudah tahu membuat kerja/menyelesaikan masalah dan tidak menolak tanggungjawab.</em></p>', NULL, NULL, '2024-11-09 12:28:39', '2024-11-09 12:28:39', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (512, 153, 4, '<p>Sudah faham dan boleh bertindak cepat ke atas semua tugasan serta tidak perlu pengawasan/bimbingan dan akan lapor balik apabila kerja telah siap.<br /><br /><em>Contoh: Bertanggungjawab dan tidak berpura-pura atau berdiam diri dalam membuat kerja/menyelesaikan masalah dan tidak perlu pengawasan/bimbingan dan akan bertindak/bergerak ke atas kerja yang ditugaskan serta lapor balik apabila kerja telah siap.</em></p>', NULL, NULL, '2024-11-09 12:29:12', '2024-11-09 12:29:12', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (513, 153, 5, '<p>Sudah faham dan boleh bertindak cepat ke atas semua tugasan serta tidak perlu pengawasan/bimbingan dan akan lapor balik apabila kerja telah siap. Selain itu, dapat memberi nasihat kepada rakan sekerja yang lain supaya cepat bertindak dalam kerja.<br /><br /><em>Contoh: Bertanggungjawab dan tidak berpura-pura atau berdiam diri dalam membuat kerja/menyelesaikan masalah dan tidak perlu pengawasan/bimbingan dan akan bertindak/bergerak ke atas kerja yang ditugaskan serta lapor balik apabila kerja telah siap. Selain itu, juga memotivasikan rakan sekerja supaya tidak berpura-pura/berdiam diri dalam &nbsp;membuat kerja/menyelesaikan masalah.</em></p>', NULL, NULL, '2024-11-09 12:29:45', '2024-11-09 12:29:45', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (514, 154, 1, '<p>Tidak membuat kerja secara sistematik dan tidak tahu membezakan kepentingan kerja.<br /><br /><em>Contoh: Tidak tahu membezakan kepentingan kerja dan tidak buat perancangan kerja.</em></p>', NULL, NULL, '2024-11-09 12:38:15', '2024-11-09 12:38:15', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (515, 154, 2, '<p>Kadangkala ada membuat kerja secara sistematik dan kadangkala tahu membezakan kepentingan kerja tetapi keadaan tidak ketara.<br /><br /><em>Contoh: Kadangkala tahu membezakan kepentingan kerja dan buat perancangan kerja tetapi tidak selalu dan ikut mood sendiri.</em></p>', NULL, NULL, '2024-11-09 12:39:15', '2024-11-09 12:39:15', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (516, 154, 3, '<p>Tidak perlu seseorang mengawasi di tepi dan tahu membuat kerja secara sistematik dan tahu membezakan kepentingan kerja dengan penjelasan yang ringkas sahaja.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan memerlukan penjelasan kerja yang ringkas sahaja.</em></p>', NULL, NULL, '2024-11-09 12:39:38', '2024-11-09 12:39:38', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (517, 154, 4, '<p>Hanya memerlukan penjelasan yang ringkas dan tahu membuat kerja secara sistematik dan tahu membezakan kepentingan kerja. Berhati-hati dan tiada kesilapan dalam kerja yang dihasilkan.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan hanya memerlukan penjelasan kerja yang ringkas sahaja dan memberi tumpuan dalam kerja dan mengeluarkan hasil kerja yang baik.</em></p>', NULL, NULL, '2024-11-09 12:40:05', '2024-11-09 12:40:05', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (518, 154, 5, '<p>Hanya memerlukan penjelasan yang sangat ringkas sahaja untuk membuat kerja secara sistematik dan tahu membezakan kepentingan kerja dan dapat memberi tunjuk ajar kepada rakan sekerja.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan hanya memerlukan penjelasan kerja yang ringkas sahaja dan memberi tumpuan dalam kerja dan mengeluarkan hasil kerja yang baik dan turut memberi tunjuk ajar kepada rakan sekerja.</em></p>', NULL, NULL, '2024-11-09 12:40:44', '2024-11-09 12:40:44', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (519, 155, 1, '<p>Hasil kerja yang tidak boleh diterima dan selalu membuat kesilapan.<br /><br /><em>Contoh: Tidak menumpu perhatian semasa bekerja dan selalu membuat kesilapan yang sama. Tidak pernah berubah walaupun &nbsp;sudah diberi bimbingan/teguran seperti selalu mengulangi kesilapan yang sama walaupun sudah banyak kali memasang mesin yang sama model.</em></p>', NULL, NULL, '2024-11-09 12:41:58', '2024-11-09 12:41:58', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (520, 155, 2, '<p>Cuai dan mengakibatkan kesilapan kerja.<br /><br /><em>Contoh: Kadangkala cuai semasa bekerja dan mengakibatkan kesilapan kerja kerana tindakan yang lambat untuk berubah setelah diberi bimbingan/teguran.</em></p>', NULL, NULL, '2024-11-09 12:42:34', '2024-11-09 12:42:34', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (521, 155, 3, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan meminimumkan tahap kesilapan kepada yang terendah.<br /><br /><em>Contoh: Kadangkala ada membuat kesilapan tetapi mengambil tindakan yang cepat untuk berubah setelah diberi bimbingan/teguran.</em></p>', NULL, NULL, '2024-11-09 12:43:05', '2024-11-09 12:43:05', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (522, 155, 4, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan apa-apa kesilapan dalam kerja harian.<br /><br /><em>Contoh: Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan. Selain itu, juga berinisiatif untuk menjaga barangan/bahan dan tidak membazir.</em></p>', NULL, NULL, '2024-11-09 12:43:35', '2024-11-09 12:43:35', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (523, 155, 5, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan kerja dan berinisiatif untuk memberi pendapat dan memperbaiki cara kerja yang lebih baik untuk meminimumkan tahap kesilapan kerja.<br /><br /><em>Contoh: Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan dan berinisiatif untuk memberi pendapat dan memperbaiki cara kerja untuk meminimumkan tahap kesilapan kerja seperti berinisiatif untuk mengetahui masalah semasa pemasangan mesin dan turut memberi pendapat untuk memperbaiki cara kerja/menyelesaikan masalah.</em></p>', NULL, NULL, '2024-11-09 12:44:04', '2024-11-09 12:44:04', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (524, 156, 1, '<p>Langsung tidak memahami permintaan kualiti kerja dan tidak memberi perhatian kepada kerja yang dilakukan.<br /><br /><em>Contoh: Langsung tidak memahami permintaan kualiti kerja dan tidak memberi perhatian terhadap semua kerja yang dilakukan seperti membuat pemasangan Control Panel tetapi langsung tidak mengikut diagram yang diberi.</em></p>', NULL, NULL, '2024-11-09 12:44:56', '2024-11-09 12:44:56', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (525, 156, 2, '<p>Kadangkala tidak faham spesifikasi kerja yang diberi dan tidak berinisiatif mengambil langkah untuk mengetahui untuk menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Tidak berinisiatif untuk bertanya/kurang bertanya apabila tidak tahu semasa memasang Control Panel dan pasang ikut sendiri dan tidak ikut cara kerja yang betul.</em></p>', NULL, NULL, '2024-11-09 12:45:24', '2024-11-09 12:45:24', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (526, 156, 3, '<p>Memahami permintaan kualiti kerja dan dapat menghasilkan kerja yang berkualiti secara individu tanpa pengawasan pegawai atasan tetapi tidak mengambil perhatian dan abaikan kerja yang remeh temeh serta tidak mengambil perhatian terhadap kekemasan hasil kerja.<br /><br /><em>Contoh: Tahu pasang Control Panel tetapi tidak terfikir tentang kekemasan. Wayar sudah ditarik dengan betul tetapi tidak diikat dengan cable tie/tidak tersusun/tidak label semasa membuat pemasangan.</em></p>', NULL, NULL, '2024-11-09 12:45:48', '2024-11-09 12:45:48', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (527, 156, 4, '<p>Faham tentang kualiti dan dapat menghasilkan kerja yang berkualiti dan memenuhi kehendak syarikat dan dapat memastikan kerja yang dihasilkan tidak bermasalah.<br /><br /><em>Contoh: Faham tentang kualiti kerja dan ikut semua spesifikasi yang diminta. Boleh berfikir dan nampak (meramalkan) ke hadapan dan memastikan kerja yang dihasilkan tidak bermasalah seperti tahu pasang Control Panel dan semua litar boleh berfungsi dengan baik dan pemasangan yang kemas dan melaporkan keadaan kepada Leader/Supervisor apabila litar tidak berfungsi/bernyala.</em></p>', NULL, NULL, '2024-11-09 12:46:25', '2024-11-09 12:46:25', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (528, 156, 5, '<p>Sangat faham tentang kualiti kerja dan dapat menghasilkan kerja yang berkualiti dan memenuhi kehendak syarikat dan dapat memastikan kerja yang dihasilkan tidak bermasalah serta turut memberi tunjuk ajar kepada rakan kerja yang lain.&nbsp;<br /><br /><em>Contoh: Sangat faham tentang kualiti kerja dan ikut semua spesifikasi yang diminta. Boleh berfikir dan nampak (meramalkan) ke hadapan dan memastikan kerja yang dihasilkan tidak bermasalah. Selain itu, juga dapat memberi tunjuk ajar kepada rakan sekerja yang lain seperti tahu pasang Control Panel dan semua litar boleh berfungsi dengan baik dan pemasangan yang kemas dan melaporkan keadaan kepada Leader/Supervisor apabila litar tidak berfungsi/bernyala. Selain itu, dia juga memberi tunjuk ajar kepada rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-09 12:46:53', '2024-11-09 12:46:53', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (529, 157, 1, '<p>Sentiasa membazirkan/merosakkan sumber syarikat.<br /><br /><em>Contoh: Tidak pernah berhati-hati dalam spesifikasi kerja yang diberi dan sentiasa mengakibatkan pembaziran bahan.</em></p>', NULL, NULL, '2024-11-09 12:48:04', '2024-11-09 12:48:04', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (530, 157, 2, '<p>Ada bersikap mahu menjimatkan sumber syarikat tetapi kadangkala menyebabkan pembaziran di atas kecuaiannya.<br /><br /><em>Contoh: Cuai dalam pembacaan spesifikasi kerja yang diberi dan silap ambil bahan dan menyebabkan kesilapan dan membazirkan bahan serta perlu &ldquo;rework&rdquo;.</em></p>', NULL, NULL, '2024-11-09 12:48:27', '2024-11-09 12:48:27', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (531, 157, 3, '<p>Berhati-hati semasa bekerja dan menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dan memastikan betul supaya tidak berlaku kesilapan yang mengakibatkan pembaziran bahan dan buang masa.</em></p>', NULL, NULL, '2024-11-09 12:48:52', '2024-11-09 12:48:52', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (532, 157, 4, '<p>Berhati-hati semasa bekerja dan berinisiatif menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya. Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dengan pelan kerja dan memastikan semua barang yang ambil adalah betul. Ada pemikiran tidak membazir seperti dalam menghasilkan sesuatu barang yang sangat kecil, dia akan cari scrap dahulu dan tidak guna bahan yang baru atau bahan yang besar.Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan.</em></p>', NULL, NULL, '2024-11-09 12:49:26', '2024-11-09 12:49:26', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (533, 157, 5, '<p>Berhati-hati semasa bekerja dan berinisiatif menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya. Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan dan juga menyedarkan dan membetulkan kesilapan rakan sekerja yang lain.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dengan pelan kerja dan memastikan semua barang yang ambil adalah betul. Ada pemikiran tidak membazir seperti dalam menghasilkan sesuatu barang yang sangat kecil, dia akan cari scrap dahulu dan tidak guna bahan yang baru atau bahan yang besar.Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan dan menyedarkan dan membetulkan kesilapan rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-09 12:49:55', '2024-11-09 12:49:55', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (534, 158, 1, '<p>Pengetahuan atau kemahiran adalah terhad dan tidak dapat menyelesaikan tugasan dan menggunakan masa yang panjang untuk mempelajari pengetahuan dan cara kerja yang agak senang.<br /><br /><em>Contoh: Tidak ada pengetahuan dan kemahiran kerja dan menggunakan masa yang panjang untuk mempelajari cara kerja yang senang walaupun bimbingan telah diberi seperti membuat kerja kimpalan yang paling senang iaitu mengimpal besi dalam kedudukan rata.</em></p>', NULL, NULL, '2024-11-09 12:50:55', '2024-11-09 12:50:55', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (535, 158, 2, '<p>Kurang pengetahuan atau kemahiran yang cukup untuk mengendalikan tugasan.<br /><br /><em>Contoh: Hasil kimpalan yang teruk dan bimbingan masih diperlukan walaupun diminta menghasilkan kerja kimpalan yang agak senang seperti mengimpal besi dalam kedudukan rata dan mendatar.</em></p>', NULL, NULL, '2024-11-09 12:51:31', '2024-11-09 12:51:31', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (536, 158, 3, '<p>Mempunyai pengetahuan dan kemahiran untuk mengendalikan tugasan dan mempunyai sikap mahu belajar dan mempelajari pengetahuan kerja yang baru dalam masa yang singkat dan mengimplikasikan dalam kerja harian.<br /><br /><em>Contoh: Ada pengetahuan dan kemahiran kimpalan tetapi tidak dapat meneruskan kerja apabila menghadapi kerja yang tidak biasa dan memerlukan bimbingan seperti: boleh mengimpal besi yang nipis tetapi tidak apabila diminta mengimpal besi yang lagi nipis / boleh mengimpal dalam kedudukan rata, mendatar dan menegak tetapi tidak apabila dalam keadaan overhead atau dalam keadaan 45 darjah.</em></p>', NULL, NULL, '2024-11-09 12:51:55', '2024-11-09 12:51:55', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (537, 158, 4, '<p>Boleh menguasai pengetahuan dan kemahiran untuk mengendalikan tugasan dan pencapaian yang agak memuaskan dan dapat menggunakan pengetahuannya untuk meningkatkan kualiti kerja.<br /><br /><em>Contoh: Mempunyai pengetahuan dan kemahiran yang luas serta jelas dengan semua keperluan/permintaan kerja seperti memilih kaedah yang bersesuaian untuk menghasilkan kerja dan tahu mengawal had api untuk mencegah hasil kerja dari kerosakan.</em></p>', NULL, NULL, '2024-11-09 12:52:22', '2024-11-09 12:52:22', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (538, 158, 5, '<p>Menguasai pengetahuan dan kemahiran untuk mengendalikan tugasan dan boleh menggabungkan pengetahuan untuk meningkatkan kualiti kerja serta mencari cara kerja baru untuk menyelesaikan masalah kerja dengan pengetahuannya.<br /><br /><em>Contoh: Mempunyai pengetahuan dan kemahiran yang luas serta jelas dengan semua keperluan/permintaan kerja dan berinisiatif memberi cadangan untuk menyelesaikan masalah kerja.&nbsp;</em></p>', NULL, NULL, '2024-11-09 12:52:54', '2024-11-09 12:52:54', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (539, 159, 1, '<p>Tidak pernah mengemas dan membersihkan tempat kerja sendiri dan sentiasa mengotorkan tempat kerja sendiri dan rakan sekerja yang lain.<br /><br /><em>Contoh: Tidak pernah terfikir kebaikan bersama dan terus membuang sisa kerja ke lantai dan menganggap ini kerja cleaner untuk membersihkan.</em></p>', NULL, NULL, '2024-11-09 12:54:09', '2024-11-09 12:54:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (540, 159, 2, '<p>Kadangkala ada mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya tidak kemas.<br /><br /><em>Contoh: Tidak selalu mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya tidak kemas seperti kadangkala ada membersihkan tempat kerja dan kadangkala tidak.</em></p>', NULL, NULL, '2024-11-09 12:54:33', '2024-11-09 12:54:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (541, 159, 3, '<p>Berinisiatif untuk mengemas dan membersihkan tempat kerja dan kebanyakan masa tempat kerjanya adalah kemas dan bersih.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai.</em></p>', NULL, NULL, '2024-11-09 12:54:55', '2024-11-09 12:54:55', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (542, 159, 4, '<p>Selalu mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya kemas dan selalu menolong membersihkan kawasan bahagiannya (division) dan kilang.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai serta tolong membersihkan kawasan yang lain.</em></p>', NULL, NULL, '2024-11-09 12:55:20', '2024-11-09 12:55:20', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (543, 159, 5, '<p>Selalu mengemas dan membersihkan tempat kerja dan tempat kerjanya kelihatan kemas dan bersih. Juga selalu menjaga kebersihan seluruh kawasan kilang dan dapat menegur rakan sekerja untuk menjaga kebersihan kilang.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai serta tolong menjaga kebersihan kawasan yang lain dan menegur rakan sekerja yang tidak menjaga kebersihan kilang.</em></p>', NULL, NULL, '2024-11-09 12:55:58', '2024-11-09 12:55:58', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (544, 160, 1, '<p>Tidak menjaga peralatan dan kemudahan syarikat.<br /><br /><em>Contoh: Tidak menjaga peralatan dan kemudahan syarikat seperti tidak menjaga forklift dan tidak pernah meletakkkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-09 12:56:47', '2024-11-09 12:56:47', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (545, 160, 2, '<p>Kadangkala bersikap cuai dalam mengendali peralatan dan kemudahan syarikat dan mengakibatkan kerosakan.<br /><br /><em>Contoh: Tidak selalu menjaga peralatan dan kemudahan syarikat dan mengakibatkan kerosakan seperti forklift terus jalan setelah enjin dihidupkan. Tidak mengambil berat tentang barang yang diangkat dan masuk ke ruang yang kecil. Selalu tidak meletakkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-09 12:57:15', '2024-11-09 12:57:15', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (546, 160, 3, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat dengan cara yang betul.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-09 12:57:48', '2024-11-09 12:57:48', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (547, 160, 4, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat demi kebaikan bersama. Selain itu, &nbsp;melaporkan kepada pihak atasan bila nampak rakan sekerja salahguna dan memberi cara penyelesaian yang bermanfaat.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna dan melapor jika ada kerosakan dan memberi cadangan untuk memperbaiki cara penggunaan dan penjagaan alatan.</em></p>', NULL, NULL, '2024-11-09 12:58:25', '2024-11-09 12:58:25', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (548, 160, 5, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat demi kebaikan bersama. Selain itu, &nbsp;melaporkan kepada pihak atasan bila nampak pekerja salahguna dan memberi cara penyelesaian yang bermanfaat. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna dan melapor jika ada kerosakan dan memberi cadangan untuk memperbaiki cara penggunaan dan penjagaan alatan.Selain itu, akan menyedarkan dan menasihati rakan sekerja yang tidak menjaga forklift semasa mengguna.</em></p>', NULL, NULL, '2024-11-09 12:58:57', '2024-11-09 12:58:57', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (549, 161, 1, '<p>Tidak mengutamakan keselamatan semasa bekerja.<br /><br /><em>Contoh: Tidak mengutamakan keselamatan semasa bekerja seperti tidak memakai PPE semasa bekerja.</em></p>', NULL, NULL, '2024-11-09 14:05:57', '2024-11-09 14:05:57', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (550, 161, 2, '<p>Ada sikap mengutamakan keselamatan tetapi kadangkala tidak.<br /><br /><em>Contoh: Ada memakai PPE semasa bekerja tetapi kadangkala tidak.</em></p>', NULL, NULL, '2024-11-09 14:06:20', '2024-11-09 14:06:20', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (551, 161, 3, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja.</em></p>', NULL, NULL, '2024-11-09 14:06:44', '2024-11-09 14:06:44', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (552, 161, 4, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan.</em></p>', NULL, NULL, '2024-11-09 14:07:09', '2024-11-09 14:07:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (553, 161, 5, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja dan melaporkan kepada pihak atasan serta turut memberi cara atau cara penyelesaian yang bermanfaat.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan serta turut memberi cara atau cara penyelesaian yang bermanfaat.</em></p>', NULL, NULL, '2024-11-09 14:07:35', '2024-11-09 14:07:35', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (554, 162, 1, '<p>Menerima tugasan tetapi tidak memikul tanggungjawab kerja dan tidak dapat bekerja di bawah tekanan.<br /><br /><em>Contoh: Dia terima kerja yang diberi tetapi sentiasa bersembang dengan rakan sekerja dan tidak buat kerja sehingga tidak nampak hasil kerja.</em></p>', NULL, NULL, '2024-11-09 14:08:50', '2024-11-09 14:08:50', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (555, 162, 2, '<p>Boleh menerima dan memikul tanggungjawab dan cuba untuk bekerja di bawah tekanan tetapi kadangkala tidak dapat menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Dia boleh buat kerja dan cuba elakkan diri dari tidak masuk kerja/tidak memberi alasan untuk bercuti tetapi kadangkala masih perlu dalam bimbingan.</em></p>', NULL, NULL, '2024-11-09 14:09:19', '2024-11-09 14:09:19', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (556, 162, 3, '<p>Boleh menerima dan memikul tanggungjawab dan dapat menghabiskan setiap kerja yang diamanahkan dengan baik di bawah tekanan dan melaporkan kerja yang telah dilakukan kepada pegawai atasan.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia masih menepati target dan ikut piawai kerja yang ditetapkan oleh syarikat. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia juga akan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-09 14:09:43', '2024-11-09 14:09:43', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (557, 162, 4, '<p>Rela menerima dan memikul tanggungjawab dan sentiasa dapat menghasilkan kerja yang berkualiti di bawah tekanan dan dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang dilakukan kepada pegawai atasan.Boleh buat kerja lebih masa sehingga kerja siap.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia akan menawarkan diri secara sukarela untuk kerja tersebut serta menepati target dan ikut piawai kerja yang ditetapkan oleh syarikat. Boleh buat kerja lebih masa sehingga kerja siap. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-09 14:10:13', '2024-11-09 14:10:13', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (558, 162, 5, '<p>Rela menerima dan memikul tanggungjawab serta tahu kepentingan dan deadline kerja. Dapat memanggil rakan sekerja untuk menyiapkan kerja bersama. Sentiasa dapat menghasilkan kerja yang berkualiti di bawah tekanan dan dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang dilakukan kepada pegawai atasan.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia tahu kepentingan dan deadline kerja tersebut serta dapat memanggil rakan sekerja untuk menyiapkan kerja bersama. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-09 14:10:42', '2024-11-09 14:10:42', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (559, 163, 1, '<p>Tidak rela mengaku kesilapan dan suka menolak tanggungjawab kepada orang lain.<br /><br /><em>Contoh: Telah melakukan kesilapan seperti tidak mengikuti spesifikasi kerja yang diberi oleh Leader / tidak tanya Leader apabila tidak faham / tanya rakan sekerja yang tidak dipertanggungjawabkan dan tidak pernah mengakui kesilapan apabila ditegur oleh Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-09 14:11:29', '2024-11-09 14:11:29', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (560, 163, 2, '<p>Kadangkala tidak rela mengaku kesilapan dan suka membuat perbandingan diri dengan orang lain dalam kesilapan yang telah dibuat.<br /><br /><em>Contoh: Telah melakukan kesilapan seperti tidak mengikuti spesifikasi kerja yang diberi oleh Leader / tidak tanya Leader apabila tidak faham / tanya rakan sekerja yang tidak dipertanggungjawabkan dan kadangkala tidak mengakui kesilapan apabila ditegur oleh Leader/Supervisor malah menyatakan Leader/Supervisor ada prasangka terhadap dia.</em></p>', NULL, NULL, '2024-11-09 14:11:57', '2024-11-09 14:11:57', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (561, 163, 3, '<p>Mengaku kesilapan dan tidak menolak tanggungjawab kepada orang lain.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan. Dia terima dan mengakui kesilapan.</em></p>', NULL, NULL, '2024-11-09 14:12:20', '2024-11-09 14:12:20', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (562, 163, 4, '<p>Tidak melarikan diri dari tanggungjawab dan terus berjumpa dengan pihak atasan untuk mengakui kesilapan dan berinisiatif untuk memperbaiki kesilapan yang telah dilakukan.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan. Dia tidak melarikan diri dari tanggungjawab dan terus berjumpa dengan Leader/Supervisor dan mengakui kesilapan. Selain itu, dia juga memberi cadangan dan sama-sama memperbaiki kesilapan yang telah dilakukan.</em></p>', NULL, NULL, '2024-11-09 14:12:46', '2024-11-09 14:12:46', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (563, 163, 5, '<p>Berani mengaku kesilapan dan tidak menolak tanggungjawab dan memastikan kesilapan tidak berlaku lagi. Berinisiatif untuk memperbetulkan kesilapan dan dapat memberi cadangan yang bermanfaat untuk mengelakkan kesilapan berlaku lagi.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan yang agak besar. Dia berani mengakui kesilapan dan terus berjumpa dengan Leader/Supervisor untuk mengakui kesilapan. Dia mengambil pengalaman tersebut sebagai satu pengajaran dan tidak mengulangi kesilapan tersebut lagi. Selain itu, dia &nbsp;memberi cadangan dan sama-sama memperbaiki kesilapan yang telah dilakukan serta memberi cadangan yang bermanfaat untuk mengelakkan kesilapan berlaku lagi.</em></p>', NULL, NULL, '2024-11-09 14:13:14', '2024-11-09 14:13:14', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (564, 164, 1, '<p>Membuat kerja alah kadar dan setakat membuat kerja sahaja dan tidak menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Tidak menunjukkan sikap ingin belajar dan tidak menumpukan perhatian semasa bekerja seperti dia boleh mengambil masa yang panjang untuk memasang beberapa nut pada mesin.</em></p>', NULL, NULL, '2024-11-09 14:14:16', '2024-11-09 14:14:16', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (565, 164, 2, '<p>Boleh membuat kerja tetapi mudah dipengaruhi orang lain dan kadangkala tidak dapat menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Dia boleh pasang nut pada mesin tetapi mudah dipengaruhi oleh rakan sekerja yang lain seperti dia akan melambatkan proses kerjanya dan sambil kerja sambil bersembang apabila ada rakan sekerja yang bersembang dengannya semasa bekerja.</em></p>', NULL, NULL, '2024-11-09 14:14:41', '2024-11-09 14:14:41', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (566, 164, 3, '<p>Lebih agresif dan sikap kerja juga serius dan dapat menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak mengangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja.</em></p>', NULL, NULL, '2024-11-09 14:15:08', '2024-11-09 14:15:08', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (567, 164, 4, '<p>Bersemangat kerja dan menumpukan perhatian sepenuhnya dalam kerja. Sentiasa mengutamakan kualiti kerja dan menghasilkan kerja yang halus dan teliti dan tidak melakukan kesilapan.<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak menggangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja. Dia sentiasa mengutamakan kualiti kerja dan memastikan nut yang dipasang itu betul dan kemas.</em></p>', NULL, NULL, '2024-11-09 14:15:35', '2024-11-09 14:15:35', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (568, 164, 5, '<p>Matlamat untuk berjaya sangat jelas. Menumpukan perhatian sepenuhnya dalam kerja. Sentiasa mengutamakan kualiti kerja dan menghasilkan kerja yang halus dan teliti dan tidak melakukan kesilapan. Selain itu turut memberi cadangan dan cara kerja untuk memastikan kerja berkualiti dihasilkan setiap kali.&nbsp;<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak menggangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja. Dia sentiasa mengutamakan kualiti kerja dan memastikan nut yang dipasang itu betul dan kemas. Selain itu, dia juga akan memberi cadangan untuk memastikan kerja berkualiti dapat dihasilkan.</em></p>', NULL, NULL, '2024-11-09 14:16:07', '2024-11-09 14:16:07', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (569, 165, 1, '<p>Langsung tidak mahu memahami dan menerima peraturan dan polisi syarikat dan sentiasa membuat aduan terhadap dasar syarikat.<br /><br /><em>Contoh: Selalu tidak menutup lampu setelah mengguna tandas dan membuat aduan apabila pihak syarikat mengambil tindakan.</em></p>', NULL, NULL, '2024-11-09 14:17:13', '2024-11-09 14:17:13', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (570, 165, 2, '<p>Kadangkala sahaja mahu menerima dan mematuhi peraturan dan polisi syarikat.<br /><br /><em>Contoh: Kadangkala ada menutup lampu setelah mengguna tandas kadangkala tidak.</em></p>', NULL, NULL, '2024-11-09 14:18:02', '2024-11-09 14:18:02', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (571, 165, 3, '<p>Menerima dan mematuhi setiap peraturan dan polisi syarikat.<br /><br /><em>Contoh: Setiap kali akan menutup lampu setelah mengguna tandas.</em></p>', NULL, NULL, '2024-11-09 14:18:30', '2024-11-09 14:18:30', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (572, 165, 4, '<p>Tidak melanggar peraturan dan sentiasa dapat menasihatkan rakan sekerja untuk menerima dan mematuhi peraturan dan polisi syarikat untuk kebaikan bersama.<br /><br /><em>Contoh: Sentiasa menutup lampu setelah mengguna tandas dan &nbsp;menasihati dan menerang kepada rakan sekerja yang tidak mematuhi peraturan.</em></p>', NULL, NULL, '2024-11-09 14:19:06', '2024-11-09 14:19:06', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (573, 165, 5, '<p>Memahami dan menerima setiap peraturan dan polisi syarikat dan sentiasa menasihatkan rakan sekerja yang melanggar peraturan serta melaporkan masalah disiplin kepada pegawai atasan untuk kebaikan bersama.<br /><br /><em>Contoh: &nbsp;Sentiasa menutup lampu setelah mengguna tandas dan &nbsp;menasihati dan menerang kepada rakan sekerja yang tidak mematuhi peraturan. Selain itu, juga akan melaporkan nama pekerja yang tidak menutup lampu setelah mengguna tandas.</em></p>', NULL, NULL, '2024-11-09 14:19:39', '2024-11-09 14:19:39', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (574, 166, 1, '<p>Selalu tidak tepat masuk kerja dan menunjukkan kedatangan yang tidak baik.<br /><br /><em>Contoh: Masih berada di tempat berehat semasa siren berbunyi dan jalan perlahan ke tempat kerja.</em></p>', NULL, NULL, '2024-11-09 14:20:40', '2024-11-09 14:20:40', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (575, 166, 2, '<p>Kadangkala ada masuk kerja pada masa yang ditetapkan tetapi keadaan tidak ketara.<br /><br /><em>Contoh: Kadangkala ada tepat masuk kerja semasa siren berbunyi tetapi kebanyakan masa tidak masuk kerja pada masa yang tepat.</em></p>', NULL, NULL, '2024-11-09 14:21:09', '2024-11-09 14:21:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (576, 166, 3, '<p>Kebanyakan masa masuk kerja pada masa yang ditetapkan tetapi kadangkala ada lewat juga.<br /><br /><em>Contoh: Kebanyakan masa masuk kerja semasa siren berbunyi tetapi sekali kala masih lewat masuk kerja.</em></p>', NULL, NULL, '2024-11-09 14:21:31', '2024-11-09 14:21:31', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (577, 166, 4, '<p>Mementingkan ketepatan masa masuk kerja dan masuk kerja tepat pada masa atau lebih awal.<br /><br /><em>Contoh: Sentiasa masa masuk kerja sebelum siren berbunyi atau lebih awal.</em></p>', NULL, NULL, '2024-11-09 14:22:16', '2024-11-09 14:22:16', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (578, 166, 5, '<p>Mementingkan ketepatan masa masuk kerja dan masuk kerja tepat pada masa atau lebih awal serta memberi nasihat kepada rakan sekerja yang lewat.<br /><br /><em>Contoh: Sentiasa masa masuk kerja sebelum siren berbunyi atau lebih awal serta memberi nasihat kepada rakan sekerja yang lewat.</em></p>', NULL, NULL, '2024-11-09 14:22:47', '2024-11-09 14:22:47', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (579, 167, 1, '<p>Disiplin diri yang tidak memuaskan dan sering meninggalkan tempat kerja dengan berkeliaran tanpa tujuan dan sering membazirkan masa serta curi tulang.<br /><br /><em>Contoh: Sering meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja (banyak kali sehari) dan mengambil masa yang panjang dalam tandas serta membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-09 14:23:36', '2024-11-09 14:23:36', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (580, 167, 2, '<p>Kadangkala membazirkan masa dan curi tulang serta meninggalkan tempat kerja dengan berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Kadangkala meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja (banyak kali sehari) dan mengambil masa yang panjang dalam tandas serta membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-09 14:24:00', '2024-11-09 14:24:00', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (581, 167, 3, '<p>Tidak membazirkan masa dan ringan tulang serta menumpukan perhatian semasa bekerja. Tidak meninggalkan tempat kerja dengan berkeliaran tanpa tujuan.<br /><br /><em>Contoh: Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-09 14:24:24', '2024-11-09 14:24:24', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (582, 167, 4, '<p>Teladan yang baik dan tumpuan perhatian sepenuhnya semasa bekerja. Tidak berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Seorang teladan yang baik dan memberi tumpuan sepenuhnya semasa bekerja. Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-09 14:24:50', '2024-11-09 14:24:50', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (583, 167, 5, '<p>Teladan yang baik dan tumpuan perhatian sepenuhnya semasa bekerja dan juga selalu memberi nasihat kepada rakan sekerja supaya melahirkan keadaan kerja yang lebih agresif. Tidak berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Seorang teladan yang baik dan memberi tumpuan sepenuhnya semasa bekerja. Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja. Selalu memberi nasihat kepada rakan sekerja yang selalu pergi ke tandas sebagai alasan.</em></p>', NULL, NULL, '2024-11-09 14:25:15', '2024-11-09 14:25:15', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (584, 168, 1, '<p>Tidak pernah berada di tempat kerja semasa pembersihan kawasan dijalankan.<br /><br /><em>Contoh: Tidak berada di tempat kerja dan pergi ke tandas semasa pembersihan kawasan dijalankan.</em></p>', NULL, NULL, '2024-11-09 14:26:04', '2024-11-09 14:26:04', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (585, 168, 2, '<p>Memulakan kerja pembersihan kawasan walaupun masa yang ditetapkan belum sampai lagi.<br /><br /><em>Contoh: Memulakan kerja pembersihan kawasan walaupun masa yang ditetapkan belum sampai lagi dan rakan sekerja yang lain masih bekerja lagi.</em></p>', NULL, NULL, '2024-11-09 14:26:30', '2024-11-09 14:26:30', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (586, 168, 3, '<p>Kebanyakan masa membersihkan kawasan production pada masa yang ditetapkan.</p><p>Kadangkala membersihkan kawasan production pada masa yang ditetapkan tetapi keadaan tidak ketara.</p><p><br />\nContoh: Kadangkala ada berada di production semasa pembersihan kawasan dijalankan tetapi kebanyakan masa tidak nampak orang.</p>', NULL, NULL, '2024-11-09 14:27:14', '2024-11-09 14:27:14', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (587, 168, 4, '<p>Sentiasa mengutamakan dan membersihkan kawasan production pada masa yang ditetapkan.<br /><br /><em>Contoh: Sentiasa membersihkan kawasan production pada masa yang ditetapkan.</em></p>', NULL, NULL, '2024-11-09 14:27:56', '2024-11-09 14:27:56', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (588, 168, 5, '<p>Mengutamakan dan membersihkan kawasan production pada masa yang ditetapkan serta memberi nasihat kepada rakan sekerja yang tidak berbuat demikian.<br /><br /><em>Contoh: Sentiasa membersihkan kawasan production pada masa yang ditetapkan dan memberi nasihat kepada rakan sekerja yang tidak berbuat demikian.</em></p>', NULL, NULL, '2024-11-09 14:28:24', '2024-11-09 14:28:24', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (589, 169, 1, '<p>Hanya menghormati pegawai atasan dan tidak bersopan dengan rakan sekerja.<br /><br /><em>Contoh: Hanya menghormati Leader/Supervisor atau pangkat kerja yang lebih tinggi tetapi tidak bersopan dengan rakan sekerja yang berpangkat rendah/masih baru.</em></p>', NULL, NULL, '2024-11-09 14:29:50', '2024-11-09 14:29:50', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (590, 169, 2, '<p>Biasanya akan bersopan dan menghormati orang lain tetapi kadangkala beremosi.<br /><br /><em>Contoh: Biasanya bersopan dan menghormati rakan sekerja yang lain tetapi kadangkala beremosi dan lawan cakap.</em></p>', NULL, NULL, '2024-11-09 14:30:14', '2024-11-09 14:30:14', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (591, 169, 3, '<p>Sering bersopan dan menghormati orang lain dan tidak bertindak mengikut perasaan.<br /><br /><em>Contoh: Sering bersopan dan menghormati rakan sekerja lain dan tidak bertindak mengikut perasaan.</em></p>', NULL, NULL, '2024-11-09 14:30:40', '2024-11-09 14:30:40', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (592, 169, 4, '<p>Bersopan dan menghormati orang lain pada setiap masa dan tidak bertindak mengikut perasaan dan berbahasa sopan.<br /><br /><em>Contoh: Bersopan dan setiap masa menghormati rakan sekerja yang lain dan tidak bertindak mengikut perasaan dan berbahasa sopan serta jaga perasaan rakan lain.</em></p>', NULL, NULL, '2024-11-09 14:31:01', '2024-11-09 14:31:01', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (593, 169, 5, '<p>Bersopan dan menghormati orang lain pada setiap masa dan masih bercakap dengan sopan walaupun sendiri telah dipersalahkan dalam proses penyelesaian masalah.<br /><br /><em>Contoh: Bersopan dan setiap masa menghormati rakan sekerja yang lain dan masih bercakap dengan sopan walaupun sendiri telah dipersalahkan dalam proses penyelesaian masalah.</em></p>', NULL, NULL, '2024-11-09 14:31:40', '2024-11-09 14:31:40', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (594, 170, 1, '<p>Memang mengetahui arahan yang diberi mempunyai kesilapan tetapi tidak mendapatkan kepastian kerana berpendapat itu adalah tanggungjawab pegawai atasan.<br /><br /><em>Contoh: Tidak mendapatkan kepastian daripada Leader/Supervisor tentang spesifikasi kerja yang diberi walaupun sudah tahu arahan yang diberi mempunyai kesilapan/tidak jelas dan beranggap itu adalah tanggungjawab Leader/Supervisor dan bukan dia.</em></p>', NULL, NULL, '2024-11-09 14:33:12', '2024-11-09 14:33:12', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (595, 170, 2, '<p>Jarang berinisiatif untuk mendapatkan kepastian daripada pegawai atasan walaupun arahan yang diberi tidak jelas atau silap.<br /><br /><em>Contoh: Menunjukkan sikap sudah tahu tetapi tidak ingin peduli dan tidak mendapatkan kepastian daripada Leader/Supervisor walapun arahan yang diberi ada kesilapan/kurang jelas.</em></p>', NULL, NULL, '2024-11-09 14:33:38', '2024-11-09 14:33:38', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (596, 170, 3, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap tetapi tidak pernah melapor balik kepada pegawai atasan tentang tugasan tersebut.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi ada kesilapan/tidak jelas tetapi tidak pernah melapor balik tugasan tersebut.</em></p>', NULL, NULL, '2024-11-09 14:43:47', '2024-11-09 14:43:47', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (597, 170, 4, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi tidak jelas/silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut.</em></p>', NULL, NULL, '2024-11-09 14:53:10', '2024-11-09 14:53:10', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (598, 170, 5, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut serta memberi pendapat yang bermanfaat.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi tidak jelas/silap dan selalu melapor balik kepada Leader/Supervisor dan turut mengambil bahagian untuk memberi pendapat yang bermanfaat.</em></p>', NULL, NULL, '2024-11-09 14:53:37', '2024-11-09 14:53:37', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (599, 171, 1, '<p>Degil dan berpegang teguh dengan pendapat sendiri dan tidak menuruti arahan pegawai atasan.<br /><br /><em>Contoh: Tidak menerima dan melawan percakapan Leader/Supervisor semasa diberi tugasan.</em></p>', NULL, NULL, '2024-11-09 14:54:25', '2024-11-09 14:54:25', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (600, 171, 2, '<p>Kebanyakan masa akan menuruti arahan pegawai atasan tetapi kadangkala akan beremosi dan meluahkan ketidakpuasan.<br /><br /><em>Contoh: Kebanyakan masa akan menerima tugasan Leader/Supervisor dengan baik tetapi kadangkala tidak.</em></p>', NULL, NULL, '2024-11-09 14:54:46', '2024-11-09 14:54:46', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (601, 171, 3, '<p>Mengambil berat dan menuruti arahan pegawai atasan dan tidak pernah membuat hal sesuka hati.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati dan akan bertanya jika tidak faham.</em></p>', NULL, NULL, '2024-11-09 14:55:21', '2024-11-09 14:55:21', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (602, 171, 4, '<p>Mengambil berat dan menuruti arahan pegawai atasan dan tidak pernah membuat hal sesuka hati. Kadangkala turut memberikan pendapat yang bermanfaat dalan kerja yang diberi.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati dan akan bertanya jika tidak faham. Kadangkala turut memberi cadangan/pandangan dalam kerja yang diberi.</em></p>', NULL, NULL, '2024-11-09 14:55:47', '2024-11-09 14:55:47', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (603, 171, 5, '<p>Bersikap positif dan menuruti semua arahan pegawai atasan, tidak membuat hal malah dapat menyampaikan objektif dan kehendak arahan secara positif kepada semua rakan sekerja.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati. Turut menyampaikan maksud dan kehendak mengikuti arahan Leader/Supervisor secara positif kepada rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-09 14:56:09', '2024-11-09 14:56:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (604, 172, 1, '<p>Ego dan tidak sudi berbincang tugasan sesama rakan sekerja dan pegawai atasan, sangat keras kepala dan tidak dapat menerima cadangan orang lain.<br /><br /><em>Contoh: Buat kerja tanpa ikut pelan kerja seperti menebuk drill pada kelajuan yang tinggi dan telah membesarkan lubang 3mm kepada 3.20 mm. Dia tidak dapat menerima apabila diminta buat semula pada kelajuan drill yang rendah.</em></p>', NULL, NULL, '2024-11-09 14:57:19', '2024-11-09 14:57:19', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (605, 172, 2, '<p>Jarang berbincang tugasan sesama rakan sekerja dan pegawai atasan dan tidak begitu rela berkongsi maklumat, kadangkala keras kepala dan tidak dapat menerima cadangan orang lain.<br /><br /><em>Contoh: Dia menunjukkan sikap yang tidak begitu gembira apabila diminta buat semula pada kelajuan drill yang rendah.</em></p>', NULL, NULL, '2024-11-09 14:57:45', '2024-11-09 14:57:45', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (606, 172, 3, '<p>Sudi berbincang dan menerima cadangan rakan sekerja dan pegawai atasan, dapat memberi pertolongan apabila diminta.<br /><br /><em>Contoh: Dia sudi membuat semula pada kelajuan drill yang rendah setelah berbincang dan diminta berubah.</em></p>', NULL, NULL, '2024-11-09 14:58:07', '2024-11-09 14:58:07', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (607, 172, 4, '<p>Sudi berbincang dan berinisiatif memberi pertolongan sesama rakan sekerja dan pegawai atasan dengan tidak berkira kerja. Boleh menerima cadangan orang lain dan tidak berkeras kepala.<br /><br /><em>Contoh: Dia sudi membuat semula pada kelajuan drill yang rendah dan dia turut memberi cadangan untuk mengatasi masalah tersebut.</em></p>', NULL, NULL, '2024-11-09 14:58:31', '2024-11-09 14:58:31', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (608, 172, 5, '<p>Sudi berbincang dan berinisiatif memberi pertolongan sesama rakan sekerja dan pegawai atasan dengan tidak berkira kerja. Boleh menerima cadangan orang lain dan tidak berkeras kepala. Selain itu, turut boleh memanggil rakan sekerja untuk sama-sama menyiapkan kerja tersebut.<br /><br /><em>Contoh: Dia ialah orang yang sangat agresif dan sudi membuat semula dan dia turut boleh meminta rakan sekerja untuk sama-sama menyiapkan kerja.</em></p>', NULL, NULL, '2024-11-09 14:59:11', '2024-11-09 14:59:11', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (609, 173, 1, '<p>Menolak tugasan selain dari bidang sendiri dan langsung tidak dapat menerima tugasan tambahan atau di luar bidang kerja, amat mementingkan diri sendiri.<br /><br /><em>Contoh: Tidak mahu backup rakan sekerja yang bercuti dan selalu dipengaruhi oleh rakan sekerja yang lain dimana orang yang berbuat banyak tidak dapat apa-apa.</em></p>', NULL, NULL, '2024-11-09 15:01:17', '2024-11-09 15:01:17', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (610, 173, 2, '<p>Kadangkala menerima tugasan tambahan atau di luar bidang kerja tetapi dengan hati yang tidak rela dan mementingkan kepentingan diri sendiri.<br /><br /><em>Contoh: Kadangkala akan diminta untuk backup rakan sekerja yang bercuti tetapi dia akan membuat kerja secara tidak rela / memberi alasan bahawa dia tidak tahu buat kerja tersebut.</em></p>', NULL, NULL, '2024-11-09 15:01:40', '2024-11-09 15:01:40', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (611, 173, 3, '<p>Rela menerima tugasan tambahan atau di luar bidang dan tidak menolak apabila tugas diberi.<br /><br /><em>Contoh: Rela backup rakan sekerja yang bercuti dan tidak menolak apabila tugas diberi oleh Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-09 15:02:07', '2024-11-09 15:02:07', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (612, 173, 4, '<p>Rela menerima tugasan tambahan atau di luar bidang dan tidak menolak apabila tugas diberi serta cuba mencari cara untuk menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Rela backup rakan sekerja yang bercuti dan tidak menolak apabila tugas diberi oleh Leader / Supervisor. Selain itu, dia juga cari jalan untuk mengeluarkan hasil kerja yang baik / membuat kerja tersebut dengan bersungguh-sungguh.</em></p>', NULL, NULL, '2024-11-09 15:02:27', '2024-11-09 15:02:27', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (613, 173, 5, '<p>Amat rela menerima tugasan tambahan atau di luar bidang dan menerimanya sebagai satu cabaran. Berusaha dan bertanggungjawab sepenuhnya sehingga tugasan selesai dengan sempurna.<br /><br /><em>Contoh: Sangat rela backup rakan sekerja yang bercuti dan menganggap tugas yang diberi tersebut sebagai satu cabaran / tugas sendiri. Dia membuat kerja dengan sepenuh hati dan mengambil tanggungjawab sehingga tugasan tersebut selesai dengan sempurnanya.</em></p>', NULL, NULL, '2024-11-09 15:02:47', '2024-11-09 15:02:47', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (614, 186, 1, '<p>Tidak dapat menyiapkan tugasan mengikut masa yang ditetapkan dan selalu dibuat semula oleh rakan sekerja yang lain dan menyebabkan kelewatan.<br /><br /><em>Contoh: Kerja yang sepatutnya boleh disiapkan dalam sehari tetapi dia selalu tidak hadir bekerja dan kerjanya perlu disambung / dibuat semula oleh rakan sekerja yang lain dan menyebabkan kelewatan.</em></p>', NULL, NULL, '2024-11-09 15:15:55', '2024-11-09 15:15:55', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (615, 186, 2, '<p>Selalu mengambil masa yang panjang untuk menyiapkan kerja walaupun bimbingan sudah diberi.<br /><br /><em>Contoh: Kerja yang sepatutnya boleh disiapkan dalam sehari tetapi dia mengambil masa yang panjang walaupun bimbingan sudah diberi.</em></p>', NULL, NULL, '2024-11-09 15:16:11', '2024-11-09 15:16:11', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (616, 186, 3, '<p>Tugasan biasanya dapat disiapkan dengan sedikit bimbingan dan siap dalam masa yang ditetapkan mahupun lebih awal dan hasil kerja yang masih boleh diterima.<br /><br /><em>Contoh: Boleh menghasilkan kerja dalam masa yang ditetapkan tetapi masih perlu dalam pengawasan/bimbingan.</em></p>', NULL, NULL, '2024-11-09 15:16:24', '2024-11-09 15:16:24', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (617, 186, 4, '<p>Tugasan sentiasa disiapkan tanpa bimbingan dan mengikut jadual mahupun lebih awal dan hasil kerja yang agar memuaskan.<br /><br /><em>Contoh: Boleh menghasilkan kerja dalam masa yang pendek dan tanpa sebarang pengawasan/bimbingan seperti dia cuma perlu 5 jam untuk menghasilkan kerja yang dijangka siap dalam sehari dan dia boleh menghasilkan lebih dalam satu hari.</em></p>', NULL, NULL, '2024-11-09 15:16:44', '2024-11-09 15:16:44', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (618, 186, 5, '<p>Mengutamakan masa dan pantas dalam menyiapkan tugasan yang diberi dan hasil kerja sangat bagus dan boleh diharapkan.<br /><br /><em>Contoh:Boleh membuat apa kerja yang dirancang dan menepati masa yang ditetapkan atau lebih awal tanpa pengawasan/bimbingan. Individu yang teliti dan prihatin dan menguasa masa dan memberi hasil kerja yang sangat bagus dan halus.</em></p>', NULL, NULL, '2024-11-09 15:17:01', '2024-11-09 15:17:01', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (619, 187, 1, '<p>Suka menolak tanggungjawab kerja dan berpura-pura/berdiam diri walaupun tahu apa cara untuk membuat kerja/menyelesaikan masalah.<br /><br /><em>Contoh: Langsung tidak bergerak dan pakai duduk dan tunggu sahaja walaupun sudah diberi penjelasan dalam pelan kerja.</em></p>', NULL, NULL, '2024-11-09 15:23:45', '2024-11-09 15:23:45', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (620, 187, 2, '<p>Kadangkala menolak tanggungjawab kerja dan berpura-pura/berdiam diri walaupun tahu apa cara untuk membuat kerja/menyelesaikan masalah.<br /><br /><em>Contoh: Tidak berusaha untuk belajar dan memahami pembacaan pelan kerja dan ukuran serta memerlukan seseorang mengawasi di tepi dan selalu memberi penjelasan boleh baru dapat menghasilkan kerja yang ditugaskan.</em></p>', NULL, NULL, '2024-11-09 15:23:58', '2024-11-09 15:23:58', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (621, 187, 3, '<p>Sudah faham dan boleh terus bertindak/bergerak ke atas kerja yang telah diselesaikan.&nbsp;<br /><br /><em>Contoh: Sudah tahu membuat kerja/menyelesaikan masalah dan tidak menolak tanggungjawab.</em></p>', NULL, NULL, '2024-11-09 15:24:09', '2024-11-09 15:24:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (622, 187, 4, '<p>Sudah faham dan boleh bertindak cepat ke atas semua tugasan serta tidak perlu pengawasan/bimbingan dan akan lapor balik apabila kerja telah siap.<br /><br /><em>Contoh: Bertanggungjawab dan tidak berpura-pura atau berdiam diri dalam membuat kerja/menyelesaikan masalah dan tidak perlu pengawasan/bimbingan dan akan bertindak/bergerak ke atas kerja yang ditugaskan serta lapor balik apabila kerja telah siap.</em></p>', NULL, NULL, '2024-11-09 15:24:20', '2024-11-09 15:24:20', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (623, 187, 5, '<p>Sudah faham dan boleh bertindak cepat ke atas semua tugasan serta tidak perlu pengawasan/bimbingan dan akan lapor balik apabila kerja telah siap. Selain itu, dapat memberi nasihat kepada rakan sekerja yang lain supaya cepat bertindak dalam kerja.<br /><br /><em>Contoh: Bertanggungjawab dan tidak berpura-pura atau berdiam diri dalam membuat kerja/menyelesaikan masalah dan tidak perlu pengawasan/bimbingan dan akan bertindak/bergerak ke atas kerja yang ditugaskan serta lapor balik apabila kerja telah siap. Selain itu, juga memotivasikan rakan sekerja supaya tidak berpura-pura/berdiam diri dalam &nbsp;membuat kerja/menyelesaikan masalah.</em></p>', NULL, NULL, '2024-11-09 15:24:35', '2024-11-09 15:24:35', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (624, 188, 1, '<p>Tidak membuat kerja secara sistematik dan tidak tahu membezakan kepentingan kerja.<br /><br /><em>Contoh: Tidak tahu membezakan kepentingan kerja dan tidak buat perancangan kerja.</em></p>', NULL, NULL, '2024-11-09 15:25:31', '2024-11-09 15:25:31', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (625, 188, 2, '<p>Kadangkala ada membuat kerja secara sistematik dan kadangkala tahu membezakan kepentingan kerja tetapi keadaan tidak ketara.<br /><br /><em>Contoh: Kadangkala tahu membezakan kepentingan kerja dan buat perancangan kerja tetapi tidak selalu dan ikut mood sendiri.</em></p>', NULL, NULL, '2024-11-09 15:25:42', '2024-11-09 15:25:42', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (626, 188, 3, '<p>Tidak perlu seseorang mengawasi di tepi dan tahu membuat kerja secara sistematik dan tahu membezakan kepentingan kerja dengan penjelasan yang ringkas sahaja.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan memerlukan penjelasan kerja yang ringkas sahaja.</em></p>', NULL, NULL, '2024-11-09 15:25:52', '2024-11-09 15:25:52', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (627, 188, 4, '<p>Hanya memerlukan penjelasan yang ringkas dan tahu membuat kerja secara sistematik dan tahu membezakan kepentingan kerja. Berhati-hati dan tiada kesilapan dalam kerja yang dihasilkan.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan hanya memerlukan penjelasan kerja yang ringkas sahaja dan memberi tumpuan dalam kerja dan mengeluarkan hasil kerja yang baik.</em></p>', NULL, NULL, '2024-11-09 15:26:03', '2024-11-09 15:26:03', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (628, 188, 5, '<p>Hanya memerlukan penjelasan yang sangat ringkas sahaja untuk membuat kerja secara sistematik dan tahu membezakan kepentingan kerja dan dapat memberi tunjuk ajar kepada rakan sekerja.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan hanya memerlukan penjelasan kerja yang ringkas sahaja dan memberi tumpuan dalam kerja dan mengeluarkan hasil kerja yang baik dan turut memberi tunjuk ajar kepada rakan sekerja.</em></p>', NULL, NULL, '2024-11-09 15:26:17', '2024-11-09 15:26:17', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (629, 189, 1, '<p>Hasil kerja yang tidak boleh diterima dan selalu membuat kesilapan.<br /><br /><em>Contoh: Tidak menumpu perhatian semasa bekerja dan selalu membuat kesilapan yang sama. Tidak pernah berubah walaupun &nbsp;sudah diberi bimbingan/teguran seperti selalu mengulangi kesilapan yang sama walaupun sudah banyak kali memasang mesin yang sama model.</em></p>', NULL, NULL, '2024-11-09 15:27:31', '2024-11-09 15:27:31', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (630, 189, 2, '<p>Cuai dan mengakibatkan kesilapan kerja.<br /><br /><em>Contoh: Kadangkala cuai semasa bekerja dan mengakibatkan kesilapan kerja kerana tindakan yang lambat untuk berubah setelah diberi bimbingan/teguran.</em></p>', NULL, NULL, '2024-11-09 15:27:40', '2024-11-09 15:27:40', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (631, 189, 3, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan meminimumkan tahap kesilapan kepada yang terendah.<br /><br /><em>Contoh: Kadangkala ada membuat kesilapan tetapi mengambil tindakan yang cepat untuk berubah setelah diberi bimbingan/teguran.</em></p>', NULL, NULL, '2024-11-09 15:27:56', '2024-11-09 15:27:56', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (632, 189, 4, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan apa-apa kesilapan dalam kerja harian.<br /><br /><em>Contoh: Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan. Selain itu, juga berinisiatif untuk menjaga barangan/bahan dan tidak membazir.</em></p>', NULL, NULL, '2024-11-09 15:28:07', '2024-11-09 15:28:07', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (633, 189, 5, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan kerja dan berinisiatif untuk memberi pendapat dan memperbaiki cara kerja yang lebih baik untuk meminimumkan tahap kesilapan kerja.<br /><br /><em>Contoh: Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan dan berinisiatif untuk memberi pendapat dan memperbaiki cara kerja untuk meminimumkan tahap kesilapan kerja seperti berinisiatif untuk mengetahui masalah semasa pemasangan mesin dan turut memberi pendapat untuk memperbaiki cara kerja/menyelesaikan masalah.</em></p>', NULL, NULL, '2024-11-09 15:28:19', '2024-11-09 15:28:19', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (634, 190, 1, '<p>Langsung tidak memahami permintaan kualiti kerja dan tidak memberi perhatian kepada kerja yang dilakukan.<br /><br /><em>Contoh: Langsung tidak memahami permintaan kualiti kerja dan tidak memberi perhatian terhadap semua kerja yang dilakukan seperti membuat pemasangan Control Panel tetapi langsung tidak mengikut diagram yang diberi.</em></p>', NULL, NULL, '2024-11-09 15:29:32', '2024-11-09 15:29:32', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (635, 190, 2, '<p>Kadangkala tidak faham spesifikasi kerja yang diberi dan tidak berinisiatif mengambil langkah untuk mengetahui untuk menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Tidak berinisiatif untuk bertanya/kurang bertanya apabila tidak tahu semasa memasang Control Panel dan pasang ikut sendiri dan tidak ikut cara kerja yang betul.</em></p>', NULL, NULL, '2024-11-09 15:29:44', '2024-11-09 15:29:44', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (636, 190, 3, '<p>Memahami permintaan kualiti kerja dan dapat menghasilkan kerja yang berkualiti secara individu tanpa pengawasan pegawai atasan tetapi tidak mengambil perhatian dan abaikan kerja yang remeh temeh serta tidak mengambil perhatian terhadap kekemasan hasil kerja.<br /><br /><em>Contoh: Tahu pasang Control Panel tetapi tidak terfikir tentang kekemasan. Wayar sudah ditarik dengan betul tetapi tidak diikat dengan cable tie/tidak tersusun/tidak label semasa membuat pemasangan.</em></p>', NULL, NULL, '2024-11-09 15:29:55', '2024-11-09 15:29:55', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (637, 190, 4, '<p>Faham tentang kualiti dan dapat menghasilkan kerja yang berkualiti dan memenuhi kehendak syarikat dan dapat memastikan kerja yang dihasilkan tidak bermasalah.<br /><br /><em>Contoh: Faham tentang kualiti kerja dan ikut semua spesifikasi yang diminta. Boleh berfikir dan nampak (meramalkan) ke hadapan dan memastikan kerja yang dihasilkan tidak bermasalah seperti tahu pasang Control Panel dan semua litar boleh berfungsi dengan baik dan pemasangan yang kemas dan melaporkan keadaan kepada Leader/Supervisor apabila litar tidak berfungsi/bernyala.</em></p>', NULL, NULL, '2024-11-09 15:30:05', '2024-11-09 15:30:05', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (638, 190, 5, '<p>Sangat faham tentang kualiti kerja dan dapat menghasilkan kerja yang berkualiti dan memenuhi kehendak syarikat dan dapat memastikan kerja yang dihasilkan tidak bermasalah serta turut memberi tunjuk ajar kepada rakan kerja yang lain.&nbsp;<br /><br /><em>Contoh: Sangat faham tentang kualiti kerja dan ikut semua spesifikasi yang diminta. Boleh berfikir dan nampak (meramalkan) ke hadapan dan memastikan kerja yang dihasilkan tidak bermasalah. Selain itu, juga dapat memberi tunjuk ajar kepada rakan sekerja yang lain seperti tahu pasang Control Panel dan semua litar boleh berfungsi dengan baik dan pemasangan yang kemas dan melaporkan keadaan kepada Leader/Supervisor apabila litar tidak berfungsi/bernyala. Selain itu, dia juga memberi tunjuk ajar kepada rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-09 15:30:16', '2024-11-09 15:30:16', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (639, 191, 1, '<p>Sentiasa membazirkan/merosakkan sumber syarikat.<br /><br /><em>Contoh: Tidak pernah berhati-hati dalam spesifikasi kerja yang diberi dan sentiasa mengakibatkan pembaziran bahan.</em></p>', NULL, NULL, '2024-11-09 15:30:42', '2024-11-09 15:30:42', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (640, 191, 2, '<p>Ada bersikap mahu menjimatkan sumber syarikat tetapi kadangkala menyebabkan pembaziran di atas kecuaiannya.<br /><br /><em>Contoh: Cuai dalam pembacaan spesifikasi kerja yang diberi dan silap ambil bahan dan menyebabkan kesilapan dan membazirkan bahan serta perlu &ldquo;rework&rdquo;.</em></p>', NULL, NULL, '2024-11-09 15:30:54', '2024-11-09 15:30:54', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (641, 191, 3, '<p>Berhati-hati semasa bekerja dan menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dan memastikan betul supaya tidak berlaku kesilapan yang mengakibatkan pembaziran bahan dan buang masa.</em></p>', NULL, NULL, '2024-11-09 15:31:05', '2024-11-09 15:31:05', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (642, 191, 4, '<p>Berhati-hati semasa bekerja dan berinisiatif menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya. Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dengan pelan kerja dan memastikan semua barang yang ambil adalah betul. Ada pemikiran tidak membazir seperti dalam menghasilkan sesuatu barang yang sangat kecil, dia akan cari scrap dahulu dan tidak guna bahan yang baru atau bahan yang besar.Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan.</em></p>', NULL, NULL, '2024-11-09 15:31:17', '2024-11-09 15:31:17', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (643, 191, 5, '<p>Berhati-hati semasa bekerja dan berinisiatif menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya. Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan dan juga menyedarkan dan membetulkan kesilapan rakan sekerja yang lain.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dengan pelan kerja dan memastikan semua barang yang ambil adalah betul. Ada pemikiran tidak membazir seperti dalam menghasilkan sesuatu barang yang sangat kecil, dia akan cari scrap dahulu dan tidak guna bahan yang baru atau bahan yang besar.Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan dan menyedarkan dan membetulkan kesilapan rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-09 15:31:30', '2024-11-09 15:31:30', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (644, 192, 1, '<p>Pengetahuan atau kemahiran adalah terhad dan tidak dapat menyelesaikan tugasan dan menggunakan masa yang panjang untuk mempelajari pengetahuan dan cara kerja yang agak senang.<br /><br /><em>Contoh: Tidak ada pengetahuan dan kemahiran kerja dan menggunakan masa yang panjang untuk mempelajari cara kerja yang senang walaupun bimbingan telah diberi seperti membuat kerja kimpalan yang paling senang iaitu mengimpal besi dalam kedudukan rata.</em></p>', NULL, NULL, '2024-11-09 15:32:04', '2024-11-09 15:32:04', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (645, 192, 2, '<p>Kurang pengetahuan atau kemahiran yang cukup untuk mengendalikan tugasan.<br /><br /><em>Contoh: Hasil kimpalan yang teruk dan bimbingan masih diperlukan walaupun diminta menghasilkan kerja kimpalan yang agak senang seperti mengimpal besi dalam kedudukan rata dan mendatar.</em></p>', NULL, NULL, '2024-11-09 15:32:18', '2024-11-09 15:32:18', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (646, 192, 3, '<p>Mempunyai pengetahuan dan kemahiran untuk mengendalikan tugasan dan mempunyai sikap mahu belajar dan mempelajari pengetahuan kerja yang baru dalam masa yang singkat dan mengimplikasikan dalam kerja harian.<br /><br /><em>Contoh: Ada pengetahuan dan kemahiran kimpalan tetapi tidak dapat meneruskan kerja apabila menghadapi kerja yang tidak biasa dan memerlukan bimbingan seperti: boleh mengimpal besi yang nipis tetapi tidak apabila diminta mengimpal besi yang lagi nipis / boleh mengimpal dalam kedudukan rata, mendatar dan menegak tetapi tidak apabila dalam keadaan overhead atau dalam keadaan 45 darjah.</em></p>', NULL, NULL, '2024-11-09 15:32:31', '2024-11-09 15:32:31', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (647, 192, 4, '<p>Boleh menguasai pengetahuan dan kemahiran untuk mengendalikan tugasan dan pencapaian yang agak memuaskan dan dapat menggunakan pengetahuannya untuk meningkatkan kualiti kerja.<br /><br /><em>Contoh: Mempunyai pengetahuan dan kemahiran yang luas serta jelas dengan semua keperluan/permintaan kerja seperti memilih kaedah yang bersesuaian untuk menghasilkan kerja dan tahu mengawal had api untuk mencegah hasil kerja dari kerosakan.</em></p>', NULL, NULL, '2024-11-09 15:32:45', '2024-11-09 15:32:45', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (648, 192, 5, '<p>Menguasai pengetahuan dan kemahiran untuk mengendalikan tugasan dan boleh menggabungkan pengetahuan untuk meningkatkan kualiti kerja serta mencari cara kerja baru untuk menyelesaikan masalah kerja dengan pengetahuannya.<br /><br /><em>Contoh: Mempunyai pengetahuan dan kemahiran yang luas serta jelas dengan semua keperluan/permintaan kerja dan berinisiatif memberi cadangan untuk menyelesaikan masalah kerja.&nbsp;</em></p>', NULL, NULL, '2024-11-09 15:33:02', '2024-11-09 15:33:02', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (649, 193, 1, '<p>Tidak pernah mengemas dan membersihkan tempat kerja sendiri dan sentiasa mengotorkan tempat kerja sendiri dan rakan sekerja yang lain.<br /><br /><em>Contoh: Tidak pernah terfikir kebaikan bersama dan terus membuang sisa kerja ke lantai dan menganggap ini kerja cleaner untuk membersihkan.</em></p>', NULL, NULL, '2024-11-09 15:33:55', '2024-11-09 15:33:55', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (650, 193, 2, '<p>Kadangkala ada mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya tidak kemas.<br /><br /><em>Contoh: Tidak selalu mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya tidak kemas seperti kadangkala ada membersihkan tempat kerja dan kadangkala tidak.</em></p>', NULL, NULL, '2024-11-09 15:34:05', '2024-11-09 15:34:05', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (651, 193, 3, '<p>Berinisiatif untuk mengemas dan membersihkan tempat kerja dan kebanyakan masa tempat kerjanya adalah kemas dan bersih.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai.</em></p>', NULL, NULL, '2024-11-09 15:34:17', '2024-11-09 15:34:17', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (652, 193, 4, '<p>Selalu mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya kemas dan selalu menolong membersihkan kawasan bahagiannya (division) dan kilang.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai serta tolong membersihkan kawasan yang lain.</em></p>', NULL, NULL, '2024-11-09 15:34:30', '2024-11-09 15:34:30', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (653, 193, 5, '<p>Selalu mengemas dan membersihkan tempat kerja dan tempat kerjanya kelihatan kemas dan bersih. Juga selalu menjaga kebersihan seluruh kawasan kilang dan dapat menegur rakan sekerja untuk menjaga kebersihan kilang.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai serta tolong menjaga kebersihan kawasan yang lain dan menegur rakan sekerja yang tidak menjaga kebersihan kilang.</em></p>', NULL, NULL, '2024-11-09 15:34:42', '2024-11-09 15:34:42', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (654, 194, 1, '<p>Tidak menjaga peralatan dan kemudahan syarikat.<br /><br /><em>Contoh: Tidak menjaga peralatan dan kemudahan syarikat seperti tidak menjaga forklift dan tidak pernah meletakkkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-09 15:35:09', '2024-11-09 15:35:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (655, 194, 2, '<p>Kadangkala bersikap cuai dalam mengendali peralatan dan kemudahan syarikat dan mengakibatkan kerosakan.<br /><br /><em>Contoh: Tidak selalu menjaga peralatan dan kemudahan syarikat dan mengakibatkan kerosakan seperti forklift terus jalan setelah enjin dihidupkan. Tidak mengambil berat tentang barang yang diangkat dan masuk ke ruang yang kecil. Selalu tidak meletakkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-09 15:35:17', '2024-11-09 15:35:35', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (656, 194, 3, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat dengan cara yang betul.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-09 15:35:47', '2024-11-09 15:35:47', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (657, 194, 4, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat demi kebaikan bersama. Selain itu, &nbsp;melaporkan kepada pihak atasan bila nampak rakan sekerja salahguna dan memberi cara penyelesaian yang bermanfaat.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna dan melapor jika ada kerosakan dan memberi cadangan untuk memperbaiki cara penggunaan dan penjagaan alatan.</em></p>', NULL, NULL, '2024-11-09 15:35:58', '2024-11-09 15:35:58', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (658, 194, 5, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat demi kebaikan bersama. Selain itu, &nbsp;melaporkan kepada pihak atasan bila nampak pekerja salahguna dan memberi cara penyelesaian yang bermanfaat. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna dan melapor jika ada kerosakan dan memberi cadangan untuk memperbaiki cara penggunaan dan penjagaan alatan.Selain itu, akan menyedarkan dan menasihati rakan sekerja yang tidak menjaga forklift semasa mengguna.</em></p>', NULL, NULL, '2024-11-09 15:36:12', '2024-11-09 15:36:12', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (659, 195, 1, '<p>Tidak mengutamakan keselamatan semasa bekerja.<br /><br /><em>Contoh: Tidak mengutamakan keselamatan semasa bekerja seperti tidak memakai PPE semasa bekerja.</em></p>', NULL, NULL, '2024-11-09 15:36:59', '2024-11-09 15:36:59', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (660, 195, 2, '<p>Ada sikap mengutamakan keselamatan tetapi kadangkala tidak.<br /><br /><em>Contoh: Ada memakai PPE semasa bekerja tetapi kadangkala tidak.</em></p>', NULL, NULL, '2024-11-09 15:37:10', '2024-11-09 15:37:10', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (661, 195, 3, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja.</em></p>', NULL, NULL, '2024-11-09 15:37:20', '2024-11-09 15:37:20', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (662, 195, 4, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan.</em></p>', NULL, NULL, '2024-11-09 15:37:31', '2024-11-09 15:37:31', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (663, 195, 5, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja dan melaporkan kepada pihak atasan serta turut memberi cara atau cara penyelesaian yang bermanfaat.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan serta turut memberi cara atau cara penyelesaian yang bermanfaat.</em></p>', NULL, NULL, '2024-11-09 15:37:45', '2024-11-09 15:37:45', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (664, 196, 1, '<p>Menerima tugasan tetapi tidak memikul tanggungjawab kerja dan tidak dapat bekerja di bawah tekanan.<br /><br /><em>Contoh: Dia terima kerja yang diberi tetapi sentiasa bersembang dengan rakan sekerja dan tidak buat kerja sehingga tidak nampak hasil kerja.</em></p>', NULL, NULL, '2024-11-09 15:39:09', '2024-11-09 15:39:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (665, 196, 2, '<p>Boleh menerima dan memikul tanggungjawab dan cuba untuk bekerja di bawah tekanan tetapi kadangkala tidak dapat menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Dia boleh buat kerja dan cuba elakkan diri dari tidak masuk kerja/tidak memberi alasan untuk bercuti tetapi kadangkala masih perlu dalam bimbingan.</em></p>', NULL, NULL, '2024-11-09 15:39:21', '2024-11-09 15:39:21', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (666, 196, 3, '<p>Boleh menerima dan memikul tanggungjawab dan dapat menghabiskan setiap kerja yang diamanahkan dengan baik di bawah tekanan dan melaporkan kerja yang telah dilakukan kepada pegawai atasan.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia masih menepati target dan ikut piawai kerja yang ditetapkan oleh syarikat. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia juga akan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-09 15:39:33', '2024-11-09 15:39:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (667, 196, 4, '<p>Rela menerima dan memikul tanggungjawab dan sentiasa dapat menghasilkan kerja yang berkualiti di bawah tekanan dan dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang dilakukan kepada pegawai atasan.Boleh buat kerja lebih masa sehingga kerja siap.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia akan menawarkan diri secara sukarela untuk kerja tersebut serta menepati target dan ikut piawai kerja yang ditetapkan oleh syarikat. Boleh buat kerja lebih masa sehingga kerja siap. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-09 15:39:44', '2024-11-09 15:39:44', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (668, 196, 5, '<p>Rela menerima dan memikul tanggungjawab serta tahu kepentingan dan deadline kerja. Dapat memanggil rakan sekerja untuk menyiapkan kerja bersama. Sentiasa dapat menghasilkan kerja yang berkualiti di bawah tekanan dan dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang dilakukan kepada pegawai atasan.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia tahu kepentingan dan deadline kerja tersebut serta dapat memanggil rakan sekerja untuk menyiapkan kerja bersama. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-09 15:39:59', '2024-11-09 15:39:59', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (669, 197, 1, '<p>Tidak rela mengaku kesilapan dan suka menolak tanggungjawab kepada orang lain.<br /><br /><em>Contoh: Telah melakukan kesilapan seperti tidak mengikuti spesifikasi kerja yang diberi oleh Leader / tidak tanya Leader apabila tidak faham / tanya rakan sekerja yang tidak dipertanggungjawabkan dan tidak pernah mengakui kesilapan apabila ditegur oleh Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-09 15:40:28', '2024-11-09 15:40:28', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (670, 197, 2, '<p>Kadangkala tidak rela mengaku kesilapan dan suka membuat perbandingan diri dengan orang lain dalam kesilapan yang telah dibuat.<br /><br /><em>Contoh: Telah melakukan kesilapan seperti tidak mengikuti spesifikasi kerja yang diberi oleh Leader / tidak tanya Leader apabila tidak faham / tanya rakan sekerja yang tidak dipertanggungjawabkan dan kadangkala tidak mengakui kesilapan apabila ditegur oleh Leader/Supervisor malah menyatakan Leader/Supervisor ada prasangka terhadap dia.</em></p>', NULL, NULL, '2024-11-09 15:40:40', '2024-11-09 15:40:40', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (671, 197, 3, '<p>Mengaku kesilapan dan tidak menolak tanggungjawab kepada orang lain.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan. Dia terima dan mengakui kesilapan.</em></p>', NULL, NULL, '2024-11-09 15:40:53', '2024-11-09 15:40:53', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (672, 197, 4, '<p>Tidak melarikan diri dari tanggungjawab dan terus berjumpa dengan pihak atasan untuk mengakui kesilapan dan berinisiatif untuk memperbaiki kesilapan yang telah dilakukan.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan. Dia tidak melarikan diri dari tanggungjawab dan terus berjumpa dengan Leader/Supervisor dan mengakui kesilapan. Selain itu, dia juga memberi cadangan dan sama-sama memperbaiki kesilapan yang telah dilakukan.</em></p>', NULL, NULL, '2024-11-09 15:41:05', '2024-11-09 15:41:05', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (673, 197, 5, '<p>Berani mengaku kesilapan dan tidak menolak tanggungjawab dan memastikan kesilapan tidak berlaku lagi. Berinisiatif untuk memperbetulkan kesilapan dan dapat memberi cadangan yang bermanfaat untuk mengelakkan kesilapan berlaku lagi.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan yang agak besar. Dia berani mengakui kesilapan dan terus berjumpa dengan Leader/Supervisor untuk mengakui kesilapan. Dia mengambil pengalaman tersebut sebagai satu pengajaran dan tidak mengulangi kesilapan tersebut lagi. Selain itu, dia &nbsp;memberi cadangan dan sama-sama memperbaiki kesilapan yang telah dilakukan serta memberi cadangan yang bermanfaat untuk mengelakkan kesilapan berlaku lagi.</em></p>', NULL, NULL, '2024-11-09 15:41:18', '2024-11-09 15:41:18', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (674, 198, 1, '<p>Membuat kerja alah kadar dan setakat membuat kerja sahaja dan tidak menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Tidak menunjukkan sikap ingin belajar dan tidak menumpukan perhatian semasa bekerja seperti dia boleh mengambil masa yang panjang untuk memasang beberapa nut pada mesin.</em></p>', NULL, NULL, '2024-11-09 15:41:51', '2024-11-09 15:41:51', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (675, 198, 2, '<p>Boleh membuat kerja tetapi mudah dipengaruhi orang lain dan kadangkala tidak dapat menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Dia boleh pasang nut pada mesin tetapi mudah dipengaruhi oleh rakan sekerja yang lain seperti dia akan melambatkan proses kerjanya dan sambil kerja sambil bersembang apabila ada rakan sekerja yang bersembang dengannya semasa bekerja.</em></p>', NULL, NULL, '2024-11-09 15:42:03', '2024-11-09 15:42:03', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (676, 198, 3, '<p>Lebih agresif dan sikap kerja juga serius dan dapat menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak mengangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja.</em></p>', NULL, NULL, '2024-11-09 15:42:14', '2024-11-09 15:42:14', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (677, 198, 4, '<p>Bersemangat kerja dan menumpukan perhatian sepenuhnya dalam kerja. Sentiasa mengutamakan kualiti kerja dan menghasilkan kerja yang halus dan teliti dan tidak melakukan kesilapan.<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak menggangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja. Dia sentiasa mengutamakan kualiti kerja dan memastikan nut yang dipasang itu betul dan kemas.</em></p>', NULL, NULL, '2024-11-09 15:42:27', '2024-11-09 15:42:27', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (678, 198, 5, '<p>Matlamat untuk berjaya sangat jelas. Menumpukan perhatian sepenuhnya dalam kerja. Sentiasa mengutamakan kualiti kerja dan menghasilkan kerja yang halus dan teliti dan tidak melakukan kesilapan. Selain itu turut memberi cadangan dan cara kerja untuk memastikan kerja berkualiti dihasilkan setiap kali.&nbsp;<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak menggangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja. Dia sentiasa mengutamakan kualiti kerja dan memastikan nut yang dipasang itu betul dan kemas. Selain itu, dia juga akan memberi cadangan untuk memastikan kerja berkualiti dapat dihasilkan.</em></p>', NULL, NULL, '2024-11-09 15:42:43', '2024-11-09 15:42:43', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (679, 199, 1, '<p>Langsung tidak mahu memahami dan menerima peraturan dan polisi syarikat dan sentiasa membuat aduan terhadap dasar syarikat.<br /><br /><em>Contoh: Selalu tidak menutup lampu setelah mengguna tandas dan membuat aduan apabila pihak syarikat mengambil tindakan.</em></p>', NULL, NULL, '2024-11-09 15:43:17', '2024-11-09 15:43:17', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (680, 199, 2, '<p>Kadangkala sahaja mahu menerima dan mematuhi peraturan dan polisi syarikat.<br /><br /><em>Contoh: Kadangkala ada menutup lampu setelah mengguna tandas kadangkala tidak.</em></p>', NULL, NULL, '2024-11-09 15:43:28', '2024-11-09 15:43:28', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (681, 199, 3, '<p>Menerima dan mematuhi setiap peraturan dan polisi syarikat.<br /><br /><em>Contoh: Setiap kali akan menutup lampu setelah mengguna tandas.</em></p>', NULL, NULL, '2024-11-09 15:43:42', '2024-11-09 15:43:42', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (682, 199, 4, '<p>Tidak melanggar peraturan dan sentiasa dapat menasihatkan rakan sekerja untuk menerima dan mematuhi peraturan dan polisi syarikat untuk kebaikan bersama.<br /><br /><em>Contoh: Sentiasa menutup lampu setelah mengguna tandas dan &nbsp;menasihati dan menerang kepada rakan sekerja yang tidak mematuhi peraturan.</em></p>', NULL, NULL, '2024-11-09 15:43:54', '2024-11-09 15:43:54', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (683, 199, 5, '<p>Memahami dan menerima setiap peraturan dan polisi syarikat dan sentiasa menasihatkan rakan sekerja yang melanggar peraturan serta melaporkan masalah disiplin kepada pegawai atasan untuk kebaikan bersama.<br /><br /><em>Contoh: &nbsp;Sentiasa menutup lampu setelah mengguna tandas dan &nbsp;menasihati dan menerang kepada rakan sekerja yang tidak mematuhi peraturan. Selain itu, juga akan melaporkan nama pekerja yang tidak menutup lampu setelah mengguna tandas.</em></p>', NULL, NULL, '2024-11-09 15:44:05', '2024-11-09 15:44:05', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (684, 200, 1, '<p>Selalu tidak tepat masuk kerja dan menunjukkan kedatangan yang tidak baik.<br /><br /><em>Contoh: Masih berada di tempat berehat semasa siren berbunyi dan jalan perlahan ke tempat kerja.</em></p>', NULL, NULL, '2024-11-09 15:44:33', '2024-11-09 15:44:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (685, 200, 2, '<p>Kadangkala ada masuk kerja pada masa yang ditetapkan tetapi keadaan tidak ketara.<br /><br /><em>Contoh: Kadangkala ada tepat masuk kerja semasa siren berbunyi tetapi kebanyakan masa tidak masuk kerja pada masa yang tepat.</em></p>', NULL, NULL, '2024-11-09 15:44:45', '2024-11-09 15:44:45', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (686, 200, 3, '<p>Kebanyakan masa masuk kerja pada masa yang ditetapkan tetapi kadangkala ada lewat juga.<br /><br /><em>Contoh: Kebanyakan masa masuk kerja semasa siren berbunyi tetapi sekali kala masih lewat masuk kerja.</em></p>', NULL, NULL, '2024-11-09 15:44:57', '2024-11-09 15:44:57', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (687, 200, 4, '<p>Mementingkan ketepatan masa masuk kerja dan masuk kerja tepat pada masa atau lebih awal.<br /><br /><em>Contoh: Sentiasa masa masuk kerja sebelum siren berbunyi atau lebih awal.</em></p>', NULL, NULL, '2024-11-09 15:45:08', '2024-11-09 15:45:08', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (688, 200, 5, '<p>Mementingkan ketepatan masa masuk kerja dan masuk kerja tepat pada masa atau lebih awal serta memberi nasihat kepada rakan sekerja yang lewat.<br /><br /><em>Contoh: Sentiasa masa masuk kerja sebelum siren berbunyi atau lebih awal serta memberi nasihat kepada rakan sekerja yang lewat.</em></p>', NULL, NULL, '2024-11-09 15:45:24', '2024-11-09 15:45:24', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (689, 201, 1, '<p>Disiplin diri yang tidak memuaskan dan sering meninggalkan tempat kerja dengan berkeliaran tanpa tujuan dan sering membazirkan masa serta curi tulang.<br /><br /><em>Contoh: Sering meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja (banyak kali sehari) dan mengambil masa yang panjang dalam tandas serta membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-09 15:46:19', '2024-11-09 15:46:19', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (690, 201, 2, '<p>Kadangkala membazirkan masa dan curi tulang serta meninggalkan tempat kerja dengan berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Kadangkala meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja (banyak kali sehari) dan mengambil masa yang panjang dalam tandas serta membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-09 15:46:30', '2024-11-09 15:46:30', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (691, 201, 3, '<p>Tidak membazirkan masa dan ringan tulang serta menumpukan perhatian semasa bekerja. Tidak meninggalkan tempat kerja dengan berkeliaran tanpa tujuan.<br /><br /><em>Contoh: Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-09 15:46:41', '2024-11-09 15:46:41', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (692, 201, 4, '<p>Teladan yang baik dan tumpuan perhatian sepenuhnya semasa bekerja. Tidak berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Seorang teladan yang baik dan memberi tumpuan sepenuhnya semasa bekerja. Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-09 15:46:53', '2024-11-09 15:46:53', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (693, 201, 5, '<p>Teladan yang baik dan tumpuan perhatian sepenuhnya semasa bekerja dan juga selalu memberi nasihat kepada rakan sekerja supaya melahirkan keadaan kerja yang lebih agresif. Tidak berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Seorang teladan yang baik dan memberi tumpuan sepenuhnya semasa bekerja. Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja. Selalu memberi nasihat kepada rakan sekerja yang selalu pergi ke tandas sebagai alasan.</em></p>', NULL, NULL, '2024-11-09 15:47:06', '2024-11-09 15:47:06', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (694, 202, 1, '<p>Tidak pernah berada di tempat kerja semasa pembersihan kawasan dijalankan.<br /><br /><em>Contoh: Tidak berada di tempat kerja dan pergi ke tandas semasa pembersihan kawasan dijalankan.</em></p>', NULL, NULL, '2024-11-09 15:47:33', '2024-11-09 15:47:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (695, 202, 2, '<p>Memulakan kerja pembersihan kawasan walaupun masa yang ditetapkan belum sampai lagi.<br /><br /><em>Contoh: Memulakan kerja pembersihan kawasan walaupun masa yang ditetapkan belum sampai lagi dan rakan sekerja yang lain masih bekerja lagi.</em></p>', NULL, NULL, '2024-11-09 15:47:48', '2024-11-09 15:47:48', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (696, 202, 3, '<p>Kebanyakan masa membersihkan kawasan production pada masa yang ditetapkan.</p><p>Kadangkala membersihkan kawasan production pada masa yang ditetapkan tetapi keadaan tidak ketara.</p><p><br />\nContoh: Kadangkala ada berada di production semasa pembersihan kawasan dijalankan tetapi kebanyakan masa tidak nampak orang.</p>', NULL, NULL, '2024-11-09 15:48:01', '2024-11-09 15:48:01', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (697, 202, 4, '<p>Sentiasa mengutamakan dan membersihkan kawasan production pada masa yang ditetapkan.<br /><br /><em>Contoh: Sentiasa membersihkan kawasan production pada masa yang ditetapkan.</em></p>', NULL, NULL, '2024-11-09 15:48:13', '2024-11-09 15:48:13', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (698, 202, 5, '<p>Mengutamakan dan membersihkan kawasan production pada masa yang ditetapkan serta memberi nasihat kepada rakan sekerja yang tidak berbuat demikian.<br /><br /><em>Contoh: Sentiasa membersihkan kawasan production pada masa yang ditetapkan dan memberi nasihat kepada rakan sekerja yang tidak berbuat demikian.</em></p>', NULL, NULL, '2024-11-09 15:48:25', '2024-11-09 15:48:25', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (699, 203, 1, '<p>Hanya menghormati pegawai atasan dan tidak bersopan dengan rakan sekerja.<br /><br /><em>Contoh: Hanya menghormati Leader/Supervisor atau pangkat kerja yang lebih tinggi tetapi tidak bersopan dengan rakan sekerja yang berpangkat rendah/masih baru.</em></p>', NULL, NULL, '2024-11-09 15:48:46', '2024-11-09 15:48:46', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (700, 203, 2, '<p>Biasanya akan bersopan dan menghormati orang lain tetapi kadangkala beremosi.<br /><br /><em>Contoh: Biasanya bersopan dan menghormati rakan sekerja yang lain tetapi kadangkala beremosi dan lawan cakap.</em></p>', NULL, NULL, '2024-11-09 15:49:00', '2024-11-09 15:49:00', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (701, 203, 3, '<p>Sering bersopan dan menghormati orang lain dan tidak bertindak mengikut perasaan.<br /><br /><em>Contoh: Sering bersopan dan menghormati rakan sekerja lain dan tidak bertindak mengikut perasaan.</em></p>', NULL, NULL, '2024-11-09 15:49:31', '2024-11-09 15:49:31', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (702, 203, 4, '<p>Bersopan dan menghormati orang lain pada setiap masa dan tidak bertindak mengikut perasaan dan berbahasa sopan.<br /><br /><em>Contoh: Bersopan dan setiap masa menghormati rakan sekerja yang lain dan tidak bertindak mengikut perasaan dan berbahasa sopan serta jaga perasaan rakan lain.</em></p>', NULL, NULL, '2024-11-09 15:49:55', '2024-11-09 15:49:55', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (703, 203, 5, '<p>Bersopan dan menghormati orang lain pada setiap masa dan masih bercakap dengan sopan walaupun sendiri telah dipersalahkan dalam proses penyelesaian masalah.<br /><br /><em>Contoh: Bersopan dan setiap masa menghormati rakan sekerja yang lain dan masih bercakap dengan sopan walaupun sendiri telah dipersalahkan dalam proses penyelesaian masalah.</em></p>', NULL, NULL, '2024-11-09 15:50:09', '2024-11-09 15:50:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (704, 204, 1, '<p>Memang mengetahui arahan yang diberi mempunyai kesilapan tetapi tidak mendapatkan kepastian kerana berpendapat itu adalah tanggungjawab pegawai atasan.<br /><br /><em>Contoh: Tidak mendapatkan kepastian daripada Leader/Supervisor tentang spesifikasi kerja yang diberi walaupun sudah tahu arahan yang diberi mempunyai kesilapan/tidak jelas dan beranggap itu adalah tanggungjawab Leader/Supervisor dan bukan dia.</em></p>', NULL, NULL, '2024-11-09 15:51:38', '2024-11-09 15:51:38', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (705, 204, 2, '<p>Jarang berinisiatif untuk mendapatkan kepastian daripada pegawai atasan walaupun arahan yang diberi tidak jelas atau silap.<br /><br /><em>Contoh: Menunjukkan sikap sudah tahu tetapi tidak ingin peduli dan tidak mendapatkan kepastian daripada Leader/Supervisor walapun arahan yang diberi ada kesilapan/kurang jelas.</em></p>', NULL, NULL, '2024-11-09 15:51:48', '2024-11-09 15:51:48', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (706, 204, 3, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap tetapi tidak pernah melapor balik kepada pegawai atasan tentang tugasan tersebut.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi ada kesilapan/tidak jelas tetapi tidak pernah melapor balik tugasan tersebut.</em></p>', NULL, NULL, '2024-11-09 15:51:58', '2024-11-09 15:51:58', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (707, 204, 4, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi tidak jelas/silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut.</em></p>', NULL, NULL, '2024-11-09 15:52:09', '2024-11-09 15:52:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (708, 204, 5, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut serta memberi pendapat yang bermanfaat.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi tidak jelas/silap dan selalu melapor balik kepada Leader/Supervisor dan turut mengambil bahagian untuk memberi pendapat yang bermanfaat.</em></p>', NULL, NULL, '2024-11-09 15:52:25', '2024-11-09 15:52:25', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (709, 205, 1, '<p>Degil dan berpegang teguh dengan pendapat sendiri dan tidak menuruti arahan pegawai atasan.<br /><br /><em>Contoh: Tidak menerima dan melawan percakapan Leader/Supervisor semasa diberi tugasan.</em></p>', NULL, NULL, '2024-11-09 15:52:57', '2024-11-09 15:52:57', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (710, 205, 2, '<p>Kebanyakan masa akan menuruti arahan pegawai atasan tetapi kadangkala akan beremosi dan meluahkan ketidakpuasan.<br /><br /><em>Contoh: Kebanyakan masa akan menerima tugasan Leader/Supervisor dengan baik tetapi kadangkala tidak.</em></p>', NULL, NULL, '2024-11-09 15:53:07', '2024-11-09 15:53:07', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (711, 205, 3, '<p>Mengambil berat dan menuruti arahan pegawai atasan dan tidak pernah membuat hal sesuka hati.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati dan akan bertanya jika tidak faham.</em></p>', NULL, NULL, '2024-11-09 15:53:24', '2024-11-09 15:53:24', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (712, 205, 4, '<p>Mengambil berat dan menuruti arahan pegawai atasan dan tidak pernah membuat hal sesuka hati. Kadangkala turut memberikan pendapat yang bermanfaat dalan kerja yang diberi.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati dan akan bertanya jika tidak faham. Kadangkala turut memberi cadangan/pandangan dalam kerja yang diberi.</em></p>', NULL, NULL, '2024-11-09 15:53:42', '2024-11-09 15:53:42', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (713, 205, 5, '<p>Bersikap positif dan menuruti semua arahan pegawai atasan, tidak membuat hal malah dapat menyampaikan objektif dan kehendak arahan secara positif kepada semua rakan sekerja.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati. Turut menyampaikan maksud dan kehendak mengikuti arahan Leader/Supervisor secara positif kepada rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-09 15:53:55', '2024-11-09 15:53:55', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (714, 206, 1, '<p>Ego dan tidak sudi berbincang tugasan sesama rakan sekerja dan pegawai atasan, sangat keras kepala dan tidak dapat menerima cadangan orang lain.<br /><br /><em>Contoh: Buat kerja tanpa ikut pelan kerja seperti menebuk drill pada kelajuan yang tinggi dan telah membesarkan lubang 3mm kepada 3.20 mm. Dia tidak dapat menerima apabila diminta buat semula pada kelajuan drill yang rendah.</em></p>', NULL, NULL, '2024-11-09 15:54:33', '2024-11-09 15:54:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (715, 206, 2, '<p>Jarang berbincang tugasan sesama rakan sekerja dan pegawai atasan dan tidak begitu rela berkongsi maklumat, kadangkala keras kepala dan tidak dapat menerima cadangan orang lain.<br /><br /><em>Contoh: Dia menunjukkan sikap yang tidak begitu gembira apabila diminta buat semula pada kelajuan drill yang rendah.</em></p>', NULL, NULL, '2024-11-09 15:54:46', '2024-11-09 15:54:46', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (716, 206, 3, '<p>Sudi berbincang dan menerima cadangan rakan sekerja dan pegawai atasan, dapat memberi pertolongan apabila diminta.<br /><br /><em>Contoh: Dia sudi membuat semula pada kelajuan drill yang rendah setelah berbincang dan diminta berubah.</em></p>', NULL, NULL, '2024-11-09 15:54:58', '2024-11-09 15:54:58', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (717, 206, 4, '<p>Sudi berbincang dan berinisiatif memberi pertolongan sesama rakan sekerja dan pegawai atasan dengan tidak berkira kerja. Boleh menerima cadangan orang lain dan tidak berkeras kepala.<br /><br /><em>Contoh: Dia sudi membuat semula pada kelajuan drill yang rendah dan dia turut memberi cadangan untuk mengatasi masalah tersebut.</em></p>', NULL, NULL, '2024-11-09 15:55:09', '2024-11-09 15:55:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (718, 206, 5, '<p>Sudi berbincang dan berinisiatif memberi pertolongan sesama rakan sekerja dan pegawai atasan dengan tidak berkira kerja. Boleh menerima cadangan orang lain dan tidak berkeras kepala. Selain itu, turut boleh memanggil rakan sekerja untuk sama-sama menyiapkan kerja tersebut.<br /><br /><em>Contoh: Dia ialah orang yang sangat agresif dan sudi membuat semula dan dia turut boleh meminta rakan sekerja untuk sama-sama menyiapkan kerja.</em></p>', NULL, NULL, '2024-11-09 15:55:20', '2024-11-09 15:55:20', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (719, 207, 1, '<p>Menolak tugasan selain dari bidang sendiri dan langsung tidak dapat menerima tugasan tambahan atau di luar bidang kerja, amat mementingkan diri sendiri.<br /><br /><em>Contoh: Tidak mahu backup rakan sekerja yang bercuti dan selalu dipengaruhi oleh rakan sekerja yang lain dimana orang yang berbuat banyak tidak dapat apa-apa.</em></p>', NULL, NULL, '2024-11-09 15:55:47', '2024-11-09 15:55:47', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (720, 207, 2, '<p>Kadangkala menerima tugasan tambahan atau di luar bidang kerja tetapi dengan hati yang tidak rela dan mementingkan kepentingan diri sendiri.<br /><br /><em>Contoh: Kadangkala akan diminta untuk backup rakan sekerja yang bercuti tetapi dia akan membuat kerja secara tidak rela / memberi alasan bahawa dia tidak tahu buat kerja tersebut.</em></p>', NULL, NULL, '2024-11-09 15:56:00', '2024-11-09 15:56:00', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (721, 207, 3, '<p>Rela menerima tugasan tambahan atau di luar bidang dan tidak menolak apabila tugas diberi.<br /><br /><em>Contoh: Rela backup rakan sekerja yang bercuti dan tidak menolak apabila tugas diberi oleh Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-09 15:56:12', '2024-11-09 15:56:12', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (722, 207, 4, '<p>Rela menerima tugasan tambahan atau di luar bidang dan tidak menolak apabila tugas diberi serta cuba mencari cara untuk menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Rela backup rakan sekerja yang bercuti dan tidak menolak apabila tugas diberi oleh Leader / Supervisor. Selain itu, dia juga cari jalan untuk mengeluarkan hasil kerja yang baik / membuat kerja tersebut dengan bersungguh-sungguh.</em></p>', NULL, NULL, '2024-11-09 15:56:23', '2024-11-09 15:56:23', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (723, 207, 5, '<p>Amat rela menerima tugasan tambahan atau di luar bidang dan menerimanya sebagai satu cabaran. Berusaha dan bertanggungjawab sepenuhnya sehingga tugasan selesai dengan sempurna.<br /><br /><em>Contoh: Sangat rela backup rakan sekerja yang bercuti dan menganggap tugas yang diberi tersebut sebagai satu cabaran / tugas sendiri. Dia membuat kerja dengan sepenuh hati dan mengambil tanggungjawab sehingga tugasan tersebut selesai dengan sempurnanya.</em></p>', NULL, NULL, '2024-11-09 15:56:37', '2024-11-09 15:56:37', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (724, 220, 1, '<p>Tidak dapat menyiapkan tugasan mengikut masa yang ditetapkan dan selalu dibuat semula oleh rakan sekerja yang lain dan menyebabkan kelewatan.<br /><br /><em>Contoh: Kerja yang sepatutnya boleh disiapkan dalam sehari tetapi dia selalu tidak hadir bekerja dan kerjanya perlu disambung / dibuat semula oleh rakan sekerja yang lain dan menyebabkan kelewatan.</em></p>', NULL, NULL, '2024-11-14 17:15:18', '2024-11-14 17:15:18', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (725, 220, 2, '<p>Selalu mengambil masa yang panjang untuk menyiapkan kerja walaupun bimbingan sudah diberi.<br /><br /><em>Contoh: Kerja yang sepatutnya boleh disiapkan dalam sehari tetapi dia mengambil masa yang panjang walaupun bimbingan sudah diberi.</em></p>', NULL, NULL, '2024-11-14 17:15:32', '2024-11-14 17:15:32', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (726, 220, 3, '<p>Tugasan biasanya dapat disiapkan dengan sedikit bimbingan dan siap dalam masa yang ditetapkan mahupun lebih awal dan hasil kerja yang masih boleh diterima.<br /><br /><em>Contoh: Boleh menghasilkan kerja dalam masa yang ditetapkan tetapi masih perlu dalam pengawasan/bimbingan.</em></p>', NULL, NULL, '2024-11-14 17:15:47', '2024-11-14 17:15:47', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (727, 220, 4, '<p>Tugasan sentiasa disiapkan tanpa bimbingan dan mengikut jadual mahupun lebih awal dan hasil kerja yang agar memuaskan.<br /><br /><em>Contoh: Boleh menghasilkan kerja dalam masa yang pendek dan tanpa sebarang pengawasan/bimbingan seperti dia cuma perlu 5 jam untuk menghasilkan kerja yang dijangka siap dalam sehari dan dia boleh menghasilkan lebih dalam satu hari.</em></p>', NULL, NULL, '2024-11-14 17:16:01', '2024-11-14 17:16:01', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (728, 220, 5, '<p>Mengutamakan masa dan pantas dalam menyiapkan tugasan yang diberi dan hasil kerja sangat bagus dan boleh diharapkan.<br /><br /><em>Contoh:Boleh membuat apa kerja yang dirancang dan menepati masa yang ditetapkan atau lebih awal tanpa pengawasan/bimbingan. Individu yang teliti dan prihatin dan menguasa masa dan memberi hasil kerja yang sangat bagus dan halus.</em></p>', NULL, NULL, '2024-11-14 17:16:23', '2024-11-14 17:16:23', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (729, 221, 1, '<p>Suka menolak tanggungjawab kerja dan berpura-pura/berdiam diri walaupun tahu apa cara untuk membuat kerja/menyelesaikan masalah.<br /><br /><em>Contoh: Langsung tidak bergerak dan pakai duduk dan tunggu sahaja walaupun sudah diberi penjelasan dalam pelan kerja.</em></p>', NULL, NULL, '2024-11-14 17:17:23', '2024-11-14 17:17:23', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (730, 221, 2, '<p>Kadangkala menolak tanggungjawab kerja dan berpura-pura/berdiam diri walaupun tahu apa cara untuk membuat kerja/menyelesaikan masalah.<br /><br /><em>Contoh: Tidak berusaha untuk belajar dan memahami pembacaan pelan kerja dan ukuran serta memerlukan seseorang mengawasi di tepi dan selalu memberi penjelasan boleh baru dapat menghasilkan kerja yang ditugaskan.</em></p>', NULL, NULL, '2024-11-14 17:17:39', '2024-11-14 17:17:39', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (731, 221, 3, '<p>Sudah faham dan boleh terus bertindak/bergerak ke atas kerja yang telah diselesaikan.&nbsp;<br /><br /><em>Contoh: Sudah tahu membuat kerja/menyelesaikan masalah dan tidak menolak tanggungjawab.</em></p>', NULL, NULL, '2024-11-14 17:17:54', '2024-11-14 17:17:54', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (732, 221, 4, '<p>Sudah faham dan boleh bertindak cepat ke atas semua tugasan serta tidak perlu pengawasan/bimbingan dan akan lapor balik apabila kerja telah siap.<br /><br /><em>Contoh: Bertanggungjawab dan tidak berpura-pura atau berdiam diri dalam membuat kerja/menyelesaikan masalah dan tidak perlu pengawasan/bimbingan dan akan bertindak/bergerak ke atas kerja yang ditugaskan serta lapor balik apabila kerja telah siap.</em></p>', NULL, NULL, '2024-11-14 17:18:07', '2024-11-14 17:18:07', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (733, 221, 5, '<p>Sudah faham dan boleh bertindak cepat ke atas semua tugasan serta tidak perlu pengawasan/bimbingan dan akan lapor balik apabila kerja telah siap. Selain itu, dapat memberi nasihat kepada rakan sekerja yang lain supaya cepat bertindak dalam kerja.<br /><br /><em>Contoh: Bertanggungjawab dan tidak berpura-pura atau berdiam diri dalam membuat kerja/menyelesaikan masalah dan tidak perlu pengawasan/bimbingan dan akan bertindak/bergerak ke atas kerja yang ditugaskan serta lapor balik apabila kerja telah siap. Selain itu, juga memotivasikan rakan sekerja supaya tidak berpura-pura/berdiam diri dalam &nbsp;membuat kerja/menyelesaikan masalah.</em></p>', NULL, NULL, '2024-11-14 17:19:09', '2024-11-14 17:19:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (734, 222, 1, '<p>Tidak membuat kerja secara sistematik dan tidak tahu membezakan kepentingan kerja.<br /><br /><em>Contoh: Tidak tahu membezakan kepentingan kerja dan tidak buat perancangan kerja.</em></p>', NULL, NULL, '2024-11-14 17:22:18', '2024-11-14 17:22:18', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (735, 222, 2, '<p>Kadangkala ada membuat kerja secara sistematik dan kadangkala tahu membezakan kepentingan kerja tetapi keadaan tidak ketara.<br /><br /><em>Contoh: Kadangkala tahu membezakan kepentingan kerja dan buat perancangan kerja tetapi tidak selalu dan ikut mood sendiri.</em></p>', NULL, NULL, '2024-11-14 17:24:17', '2024-11-14 17:24:17', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (736, 222, 3, '<p>Tidak perlu seseorang mengawasi di tepi dan tahu membuat kerja secara sistematik dan tahu membezakan kepentingan kerja dengan penjelasan yang ringkas sahaja.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan memerlukan penjelasan kerja yang ringkas sahaja.</em></p>', NULL, NULL, '2024-11-14 17:24:33', '2024-11-14 17:24:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (737, 222, 4, '<p>Hanya memerlukan penjelasan yang ringkas dan tahu membuat kerja secara sistematik dan tahu membezakan kepentingan kerja. Berhati-hati dan tiada kesilapan dalam kerja yang dihasilkan.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan hanya memerlukan penjelasan kerja yang ringkas sahaja dan memberi tumpuan dalam kerja dan mengeluarkan hasil kerja yang baik.</em></p>', NULL, NULL, '2024-11-14 17:24:54', '2024-11-14 17:24:54', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (738, 222, 5, '<p>Hanya memerlukan penjelasan yang sangat ringkas sahaja untuk membuat kerja secara sistematik dan tahu membezakan kepentingan kerja dan dapat memberi tunjuk ajar kepada rakan sekerja.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan hanya memerlukan penjelasan kerja yang ringkas sahaja dan memberi tumpuan dalam kerja dan mengeluarkan hasil kerja yang baik dan turut memberi tunjuk ajar kepada rakan sekerja.</em></p>', NULL, NULL, '2024-11-14 17:25:08', '2024-11-14 17:25:08', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (739, 223, 1, '<p>Hasil kerja yang tidak boleh diterima dan selalu membuat kesilapan.<br /><br /><em>Contoh: Tidak menumpu perhatian semasa bekerja dan selalu membuat kesilapan yang sama. Tidak pernah berubah walaupun &nbsp;sudah diberi bimbingan/teguran seperti selalu mengulangi kesilapan yang sama walaupun sudah banyak kali memasang mesin yang sama model.</em></p>', NULL, NULL, '2024-11-14 17:26:18', '2024-11-14 17:26:18', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (740, 223, 2, '<p>Cuai dan mengakibatkan kesilapan kerja.<br /><br /><em>Contoh: Kadangkala cuai semasa bekerja dan mengakibatkan kesilapan kerja kerana tindakan yang lambat untuk berubah setelah diberi bimbingan/teguran.</em></p>', NULL, NULL, '2024-11-14 17:26:29', '2024-11-14 17:26:29', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (741, 223, 3, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan meminimumkan tahap kesilapan kepada yang terendah.<br /><br /><em>Contoh: Kadangkala ada membuat kesilapan tetapi mengambil tindakan yang cepat untuk berubah setelah diberi bimbingan/teguran.</em></p>', NULL, NULL, '2024-11-14 17:26:55', '2024-11-14 17:26:55', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (742, 223, 4, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan apa-apa kesilapan dalam kerja harian.<br /><br /><em>Contoh: Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan. Selain itu, juga berinisiatif untuk menjaga barangan/bahan dan tidak membazir.</em></p>', NULL, NULL, '2024-11-14 17:29:42', '2024-11-14 17:29:42', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (743, 223, 5, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan kerja dan berinisiatif untuk memberi pendapat dan memperbaiki cara kerja yang lebih baik untuk meminimumkan tahap kesilapan kerja.<br /><br /><em>Contoh: Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan dan berinisiatif untuk memberi pendapat dan memperbaiki cara kerja untuk meminimumkan tahap kesilapan kerja seperti berinisiatif untuk mengetahui masalah semasa pemasangan mesin dan turut memberi pendapat untuk memperbaiki cara kerja/menyelesaikan masalah.</em></p>', NULL, NULL, '2024-11-14 17:29:55', '2024-11-14 17:29:55', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (744, 224, 1, '<p>Langsung tidak memahami permintaan kualiti kerja dan tidak memberi perhatian kepada kerja yang dilakukan.<br /><br /><em>Contoh: Langsung tidak memahami permintaan kualiti kerja dan tidak memberi perhatian terhadap semua kerja yang dilakukan seperti membuat pemasangan Control Panel tetapi langsung tidak mengikut diagram yang diberi.</em></p>', NULL, NULL, '2024-11-14 17:30:49', '2024-11-14 17:30:49', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (745, 224, 2, '<p>Kadangkala tidak faham spesifikasi kerja yang diberi dan tidak berinisiatif mengambil langkah untuk mengetahui untuk menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Tidak berinisiatif untuk bertanya/kurang bertanya apabila tidak tahu semasa memasang Control Panel dan pasang ikut sendiri dan tidak ikut cara kerja yang betul.</em></p>', NULL, NULL, '2024-11-14 17:30:59', '2024-11-14 17:30:59', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (746, 224, 3, '<p>Memahami permintaan kualiti kerja dan dapat menghasilkan kerja yang berkualiti secara individu tanpa pengawasan pegawai atasan tetapi tidak mengambil perhatian dan abaikan kerja yang remeh temeh serta tidak mengambil perhatian terhadap kekemasan hasil kerja.<br /><br /><em>Contoh: Tahu pasang Control Panel tetapi tidak terfikir tentang kekemasan. Wayar sudah ditarik dengan betul tetapi tidak diikat dengan cable tie/tidak tersusun/tidak label semasa membuat pemasangan.</em></p>', NULL, NULL, '2024-11-14 17:31:11', '2024-11-14 17:31:11', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (747, 224, 4, '<p>Faham tentang kualiti dan dapat menghasilkan kerja yang berkualiti dan memenuhi kehendak syarikat dan dapat memastikan kerja yang dihasilkan tidak bermasalah.<br /><br /><em>Contoh: Faham tentang kualiti kerja dan ikut semua spesifikasi yang diminta. Boleh berfikir dan nampak (meramalkan) ke hadapan dan memastikan kerja yang dihasilkan tidak bermasalah seperti tahu pasang Control Panel dan semua litar boleh berfungsi dengan baik dan pemasangan yang kemas dan melaporkan keadaan kepada Leader/Supervisor apabila litar tidak berfungsi/bernyala.</em></p>', NULL, NULL, '2024-11-14 17:31:23', '2024-11-14 17:31:23', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (748, 224, 5, '<p>Sangat faham tentang kualiti kerja dan dapat menghasilkan kerja yang berkualiti dan memenuhi kehendak syarikat dan dapat memastikan kerja yang dihasilkan tidak bermasalah serta turut memberi tunjuk ajar kepada rakan kerja yang lain.&nbsp;<br /><br /><em>Contoh: Sangat faham tentang kualiti kerja dan ikut semua spesifikasi yang diminta. Boleh berfikir dan nampak (meramalkan) ke hadapan dan memastikan kerja yang dihasilkan tidak bermasalah. Selain itu, juga dapat memberi tunjuk ajar kepada rakan sekerja yang lain seperti tahu pasang Control Panel dan semua litar boleh berfungsi dengan baik dan pemasangan yang kemas dan melaporkan keadaan kepada Leader/Supervisor apabila litar tidak berfungsi/bernyala. Selain itu, dia juga memberi tunjuk ajar kepada rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-14 17:31:35', '2024-11-14 17:31:35', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (749, 225, 1, '<p>Sentiasa membazirkan/merosakkan sumber syarikat.<br /><br /><em>Contoh: Tidak pernah berhati-hati dalam spesifikasi kerja yang diberi dan sentiasa mengakibatkan pembaziran bahan.</em></p>', NULL, NULL, '2024-11-14 17:32:19', '2024-11-14 17:32:19', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (750, 225, 2, '<p>Ada bersikap mahu menjimatkan sumber syarikat tetapi kadangkala menyebabkan pembaziran di atas kecuaiannya.<br /><br /><em>Contoh: Cuai dalam pembacaan spesifikasi kerja yang diberi dan silap ambil bahan dan menyebabkan kesilapan dan membazirkan bahan serta perlu &ldquo;rework&rdquo;.</em></p>', NULL, NULL, '2024-11-14 17:32:36', '2024-11-14 17:32:36', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (751, 225, 3, '<p>Berhati-hati semasa bekerja dan menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dan memastikan betul supaya tidak berlaku kesilapan yang mengakibatkan pembaziran bahan dan buang masa.</em></p>', NULL, NULL, '2024-11-14 17:33:02', '2024-11-14 17:33:02', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (752, 225, 4, '<p>Berhati-hati semasa bekerja dan berinisiatif menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya. Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dengan pelan kerja dan memastikan semua barang yang ambil adalah betul. Ada pemikiran tidak membazir seperti dalam menghasilkan sesuatu barang yang sangat kecil, dia akan cari scrap dahulu dan tidak guna bahan yang baru atau bahan yang besar.Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan.</em></p>', NULL, NULL, '2024-11-14 17:33:49', '2024-11-14 17:33:49', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (753, 225, 5, '<p>Berhati-hati semasa bekerja dan berinisiatif menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya. Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan dan juga menyedarkan dan membetulkan kesilapan rakan sekerja yang lain.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dengan pelan kerja dan memastikan semua barang yang ambil adalah betul. Ada pemikiran tidak membazir seperti dalam menghasilkan sesuatu barang yang sangat kecil, dia akan cari scrap dahulu dan tidak guna bahan yang baru atau bahan yang besar.Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan dan menyedarkan dan membetulkan kesilapan rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-14 17:41:45', '2024-11-14 17:41:45', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (754, 226, 1, '<p>Pengetahuan atau kemahiran adalah terhad dan tidak dapat menyelesaikan tugasan dan menggunakan masa yang panjang untuk mempelajari pengetahuan dan cara kerja yang agak senang.<br /><br /><em>Contoh: Tidak ada pengetahuan dan kemahiran kerja dan menggunakan masa yang panjang untuk mempelajari cara kerja yang senang walaupun bimbingan telah diberi seperti membuat kerja kimpalan yang paling senang iaitu mengimpal besi dalam kedudukan rata.</em></p>', NULL, NULL, '2024-11-14 17:43:47', '2024-11-14 17:43:47', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (755, 226, 2, '<p>Kurang pengetahuan atau kemahiran yang cukup untuk mengendalikan tugasan.<br /><br /><em>Contoh: Hasil kimpalan yang teruk dan bimbingan masih diperlukan walaupun diminta menghasilkan kerja kimpalan yang agak senang seperti mengimpal besi dalam kedudukan rata dan mendatar.</em></p>', NULL, NULL, '2024-11-14 17:43:58', '2024-11-14 17:43:58', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (756, 226, 3, '<p>Mempunyai pengetahuan dan kemahiran untuk mengendalikan tugasan dan mempunyai sikap mahu belajar dan mempelajari pengetahuan kerja yang baru dalam masa yang singkat dan mengimplikasikan dalam kerja harian.<br /><br /><em>Contoh: Ada pengetahuan dan kemahiran kimpalan tetapi tidak dapat meneruskan kerja apabila menghadapi kerja yang tidak biasa dan memerlukan bimbingan seperti: boleh mengimpal besi yang nipis tetapi tidak apabila diminta mengimpal besi yang lagi nipis / boleh mengimpal dalam kedudukan rata, mendatar dan menegak tetapi tidak apabila dalam keadaan overhead atau dalam keadaan 45 darjah.</em></p>', NULL, NULL, '2024-11-14 17:44:09', '2024-11-14 17:44:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (757, 226, 4, '<p>Boleh menguasai pengetahuan dan kemahiran untuk mengendalikan tugasan dan pencapaian yang agak memuaskan dan dapat menggunakan pengetahuannya untuk meningkatkan kualiti kerja.<br /><br /><em>Contoh: Mempunyai pengetahuan dan kemahiran yang luas serta jelas dengan semua keperluan/permintaan kerja seperti memilih kaedah yang bersesuaian untuk menghasilkan kerja dan tahu mengawal had api untuk mencegah hasil kerja dari kerosakan.</em></p>', NULL, NULL, '2024-11-14 17:44:31', '2024-11-14 17:44:31', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (758, 226, 5, '<p>Menguasai pengetahuan dan kemahiran untuk mengendalikan tugasan dan boleh menggabungkan pengetahuan untuk meningkatkan kualiti kerja serta mencari cara kerja baru untuk menyelesaikan masalah kerja dengan pengetahuannya.<br /><br /><em>Contoh: Mempunyai pengetahuan dan kemahiran yang luas serta jelas dengan semua keperluan/permintaan kerja dan berinisiatif memberi cadangan untuk menyelesaikan masalah kerja.&nbsp;</em></p>', NULL, NULL, '2024-11-14 17:44:45', '2024-11-14 17:44:45', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (759, 227, 1, '<p>Tidak pernah mengemas dan membersihkan tempat kerja sendiri dan sentiasa mengotorkan tempat kerja sendiri dan rakan sekerja yang lain.<br /><br /><em>Contoh: Tidak pernah terfikir kebaikan bersama dan terus membuang sisa kerja ke lantai dan menganggap ini kerja cleaner untuk membersihkan.</em></p>', NULL, NULL, '2024-11-14 17:45:19', '2024-11-14 17:45:19', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (760, 227, 2, '<p>Kadangkala ada mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya tidak kemas.<br /><br /><em>Contoh: Tidak selalu mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya tidak kemas seperti kadangkala ada membersihkan tempat kerja dan kadangkala tidak.</em></p>', NULL, NULL, '2024-11-14 17:45:29', '2024-11-14 17:45:29', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (761, 227, 3, '<p>Berinisiatif untuk mengemas dan membersihkan tempat kerja dan kebanyakan masa tempat kerjanya adalah kemas dan bersih.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai.</em></p>', NULL, NULL, '2024-11-14 17:45:41', '2024-11-14 17:45:41', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (762, 227, 4, '<p>Selalu mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya kemas dan selalu menolong membersihkan kawasan bahagiannya (division) dan kilang.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai serta tolong membersihkan kawasan yang lain.</em></p>', NULL, NULL, '2024-11-14 17:46:01', '2024-11-14 17:46:01', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (763, 227, 5, '<p>Selalu mengemas dan membersihkan tempat kerja dan tempat kerjanya kelihatan kemas dan bersih. Juga selalu menjaga kebersihan seluruh kawasan kilang dan dapat menegur rakan sekerja untuk menjaga kebersihan kilang.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai serta tolong menjaga kebersihan kawasan yang lain dan menegur rakan sekerja yang tidak menjaga kebersihan kilang.</em></p>', NULL, NULL, '2024-11-14 17:48:44', '2024-11-14 17:48:44', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (764, 228, 1, '<p>Tidak menjaga peralatan dan kemudahan syarikat.<br /><br /><em>Contoh: Tidak menjaga peralatan dan kemudahan syarikat seperti tidak menjaga forklift dan tidak pernah meletakkkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-14 17:49:37', '2024-11-14 17:49:37', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (765, 228, 2, '<p>Kadangkala bersikap cuai dalam mengendali peralatan dan kemudahan syarikat dan mengakibatkan kerosakan.<br /><br /><em>Contoh: Tidak selalu menjaga peralatan dan kemudahan syarikat dan mengakibatkan kerosakan seperti forklift terus jalan setelah enjin dihidupkan. Tidak mengambil berat tentang barang yang diangkat dan masuk ke ruang yang kecil. Selalu tidak meletakkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-14 17:49:49', '2024-11-14 17:49:49', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (766, 228, 3, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat dengan cara yang betul.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-14 17:50:00', '2024-11-14 17:50:00', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (767, 228, 4, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat demi kebaikan bersama. Selain itu, &nbsp;melaporkan kepada pihak atasan bila nampak rakan sekerja salahguna dan memberi cara penyelesaian yang bermanfaat.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna dan melapor jika ada kerosakan dan memberi cadangan untuk memperbaiki cara penggunaan dan penjagaan alatan.</em></p>', NULL, NULL, '2024-11-14 17:50:12', '2024-11-14 17:50:12', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (768, 228, 5, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat demi kebaikan bersama. Selain itu, &nbsp;melaporkan kepada pihak atasan bila nampak pekerja salahguna dan memberi cara penyelesaian yang bermanfaat. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna dan melapor jika ada kerosakan dan memberi cadangan untuk memperbaiki cara penggunaan dan penjagaan alatan.Selain itu, akan menyedarkan dan menasihati rakan sekerja yang tidak menjaga forklift semasa mengguna.</em></p>', NULL, NULL, '2024-11-14 17:50:23', '2024-11-14 17:50:23', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (769, 229, 1, '<p>Tidak mengutamakan keselamatan semasa bekerja.<br /><br /><em>Contoh: Tidak mengutamakan keselamatan semasa bekerja seperti tidak memakai PPE semasa bekerja.</em></p>', NULL, NULL, '2024-11-14 17:51:10', '2024-11-14 17:51:10', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (770, 229, 2, '<p>Ada sikap mengutamakan keselamatan tetapi kadangkala tidak.<br /><br /><em>Contoh: Ada memakai PPE semasa bekerja tetapi kadangkala tidak.</em></p>', NULL, NULL, '2024-11-14 17:51:21', '2024-11-14 17:51:21', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (771, 229, 3, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja.</em></p>', NULL, NULL, '2024-11-14 17:51:34', '2024-11-14 17:51:34', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (772, 229, 4, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan.</em></p>', NULL, NULL, '2024-11-14 17:51:45', '2024-11-14 17:51:45', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (773, 229, 5, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja dan melaporkan kepada pihak atasan serta turut memberi cara atau cara penyelesaian yang bermanfaat.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan serta turut memberi cara atau cara penyelesaian yang bermanfaat.</em></p>', NULL, NULL, '2024-11-14 17:52:04', '2024-11-14 17:52:04', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (774, 230, 1, '<p>Menerima tugasan tetapi tidak memikul tanggungjawab kerja dan tidak dapat bekerja di bawah tekanan.<br /><br /><em>Contoh: Dia terima kerja yang diberi tetapi sentiasa bersembang dengan rakan sekerja dan tidak buat kerja sehingga tidak nampak hasil kerja.</em></p>', NULL, NULL, '2024-11-14 17:53:59', '2024-11-14 17:53:59', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (775, 230, 2, '<p>Boleh menerima dan memikul tanggungjawab dan cuba untuk bekerja di bawah tekanan tetapi kadangkala tidak dapat menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Dia boleh buat kerja dan cuba elakkan diri dari tidak masuk kerja/tidak memberi alasan untuk bercuti tetapi kadangkala masih perlu dalam bimbingan.</em></p>', NULL, NULL, '2024-11-14 17:54:11', '2024-11-14 17:54:11', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (776, 230, 3, '<p>Boleh menerima dan memikul tanggungjawab dan dapat menghabiskan setiap kerja yang diamanahkan dengan baik di bawah tekanan dan melaporkan kerja yang telah dilakukan kepada pegawai atasan.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia masih menepati target dan ikut piawai kerja yang ditetapkan oleh syarikat. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia juga akan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-14 17:54:21', '2024-11-14 17:54:21', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (777, 230, 4, '<p>Rela menerima dan memikul tanggungjawab dan sentiasa dapat menghasilkan kerja yang berkualiti di bawah tekanan dan dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang dilakukan kepada pegawai atasan.Boleh buat kerja lebih masa sehingga kerja siap.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia akan menawarkan diri secara sukarela untuk kerja tersebut serta menepati target dan ikut piawai kerja yang ditetapkan oleh syarikat. Boleh buat kerja lebih masa sehingga kerja siap. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-14 17:54:31', '2024-11-14 17:54:31', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (778, 230, 5, '<p>Rela menerima dan memikul tanggungjawab serta tahu kepentingan dan deadline kerja. Dapat memanggil rakan sekerja untuk menyiapkan kerja bersama. Sentiasa dapat menghasilkan kerja yang berkualiti di bawah tekanan dan dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang dilakukan kepada pegawai atasan.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia tahu kepentingan dan deadline kerja tersebut serta dapat memanggil rakan sekerja untuk menyiapkan kerja bersama. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-14 17:54:43', '2024-11-14 17:54:43', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (779, 231, 1, '<p>Tidak rela mengaku kesilapan dan suka menolak tanggungjawab kepada orang lain.<br /><br /><em>Contoh: Telah melakukan kesilapan seperti tidak mengikuti spesifikasi kerja yang diberi oleh Leader / tidak tanya Leader apabila tidak faham / tanya rakan sekerja yang tidak dipertanggungjawabkan dan tidak pernah mengakui kesilapan apabila ditegur oleh Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-14 17:56:19', '2024-11-14 17:56:19', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (780, 231, 2, '<p>Kadangkala tidak rela mengaku kesilapan dan suka membuat perbandingan diri dengan orang lain dalam kesilapan yang telah dibuat.<br /><br /><em>Contoh: Telah melakukan kesilapan seperti tidak mengikuti spesifikasi kerja yang diberi oleh Leader / tidak tanya Leader apabila tidak faham / tanya rakan sekerja yang tidak dipertanggungjawabkan dan kadangkala tidak mengakui kesilapan apabila ditegur oleh Leader/Supervisor malah menyatakan Leader/Supervisor ada prasangka terhadap dia.</em></p>', NULL, NULL, '2024-11-14 17:56:31', '2024-11-14 17:56:31', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (781, 231, 3, '<p>Mengaku kesilapan dan tidak menolak tanggungjawab kepada orang lain.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan. Dia terima dan mengakui kesilapan.</em></p>', NULL, NULL, '2024-11-14 17:56:47', '2024-11-14 17:56:47', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (782, 231, 4, '<p>Tidak melarikan diri dari tanggungjawab dan terus berjumpa dengan pihak atasan untuk mengakui kesilapan dan berinisiatif untuk memperbaiki kesilapan yang telah dilakukan.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan. Dia tidak melarikan diri dari tanggungjawab dan terus berjumpa dengan Leader/Supervisor dan mengakui kesilapan. Selain itu, dia juga memberi cadangan dan sama-sama memperbaiki kesilapan yang telah dilakukan.</em></p>', NULL, NULL, '2024-11-14 17:56:59', '2024-11-14 17:57:25', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (783, 231, 5, '<p>Berani mengaku kesilapan dan tidak menolak tanggungjawab dan memastikan kesilapan tidak berlaku lagi. Berinisiatif untuk memperbetulkan kesilapan dan dapat memberi cadangan yang bermanfaat untuk mengelakkan kesilapan berlaku lagi.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan yang agak besar. Dia berani mengakui kesilapan dan terus berjumpa dengan Leader/Supervisor untuk mengakui kesilapan. Dia mengambil pengalaman tersebut sebagai satu pengajaran dan tidak mengulangi kesilapan tersebut lagi. Selain itu, dia &nbsp;memberi cadangan dan sama-sama memperbaiki kesilapan yang telah dilakukan serta memberi cadangan yang bermanfaat untuk mengelakkan kesilapan berlaku lagi.</em></p>', NULL, NULL, '2024-11-14 17:57:52', '2024-11-14 17:57:52', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (784, 232, 1, '<p>Membuat kerja alah kadar dan setakat membuat kerja sahaja dan tidak menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Tidak menunjukkan sikap ingin belajar dan tidak menumpukan perhatian semasa bekerja seperti dia boleh mengambil masa yang panjang untuk memasang beberapa nut pada mesin.</em></p>', NULL, NULL, '2024-11-14 17:58:44', '2024-11-14 17:58:44', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (785, 232, 2, '<p>Boleh membuat kerja tetapi mudah dipengaruhi orang lain dan kadangkala tidak dapat menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Dia boleh pasang nut pada mesin tetapi mudah dipengaruhi oleh rakan sekerja yang lain seperti dia akan melambatkan proses kerjanya dan sambil kerja sambil bersembang apabila ada rakan sekerja yang bersembang dengannya semasa bekerja.</em></p>', NULL, NULL, '2024-11-14 17:58:56', '2024-11-14 17:58:56', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (786, 232, 3, '<p>Lebih agresif dan sikap kerja juga serius dan dapat menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak mengangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja.</em></p>', NULL, NULL, '2024-11-14 17:59:08', '2024-11-14 17:59:08', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (787, 232, 4, '<p>Bersemangat kerja dan menumpukan perhatian sepenuhnya dalam kerja. Sentiasa mengutamakan kualiti kerja dan menghasilkan kerja yang halus dan teliti dan tidak melakukan kesilapan.<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak menggangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja. Dia sentiasa mengutamakan kualiti kerja dan memastikan nut yang dipasang itu betul dan kemas.</em></p>', NULL, NULL, '2024-11-14 17:59:20', '2024-11-14 17:59:20', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (788, 232, 5, '<p>Matlamat untuk berjaya sangat jelas. Menumpukan perhatian sepenuhnya dalam kerja. Sentiasa mengutamakan kualiti kerja dan menghasilkan kerja yang halus dan teliti dan tidak melakukan kesilapan. Selain itu turut memberi cadangan dan cara kerja untuk memastikan kerja berkualiti dihasilkan setiap kali.&nbsp;<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak menggangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja. Dia sentiasa mengutamakan kualiti kerja dan memastikan nut yang dipasang itu betul dan kemas. Selain itu, dia juga akan memberi cadangan untuk memastikan kerja berkualiti dapat dihasilkan.</em></p>', NULL, NULL, '2024-11-14 17:59:36', '2024-11-14 17:59:36', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (789, 233, 1, '<p>Langsung tidak mahu memahami dan menerima peraturan dan polisi syarikat dan sentiasa membuat aduan terhadap dasar syarikat.<br /><br /><em>Contoh: Selalu tidak menutup lampu setelah mengguna tandas dan membuat aduan apabila pihak syarikat mengambil tindakan.</em></p>', NULL, NULL, '2024-11-15 15:53:29', '2024-11-15 15:53:29', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (790, 233, 2, '<p>Kadangkala sahaja mahu menerima dan mematuhi peraturan dan polisi syarikat.<br /><br /><em>Contoh: Kadangkala ada menutup lampu setelah mengguna tandas kadangkala tidak.</em></p>', NULL, NULL, '2024-11-15 15:53:42', '2024-11-15 15:53:42', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (791, 233, 3, '<p>Menerima dan mematuhi setiap peraturan dan polisi syarikat.<br /><br /><em>Contoh: Setiap kali akan menutup lampu setelah mengguna tandas.</em></p>', NULL, NULL, '2024-11-15 15:53:53', '2024-11-15 15:53:53', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (792, 233, 4, '<p>Tidak melanggar peraturan dan sentiasa dapat menasihatkan rakan sekerja untuk menerima dan mematuhi peraturan dan polisi syarikat untuk kebaikan bersama.<br /><br /><em>Contoh: Sentiasa menutup lampu setelah mengguna tandas dan &nbsp;menasihati dan menerang kepada rakan sekerja yang tidak mematuhi peraturan.</em></p>', NULL, NULL, '2024-11-15 15:54:06', '2024-11-15 15:54:06', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (793, 233, 5, '<p>Memahami dan menerima setiap peraturan dan polisi syarikat dan sentiasa menasihatkan rakan sekerja yang melanggar peraturan serta melaporkan masalah disiplin kepada pegawai atasan untuk kebaikan bersama.<br /><br /><em>Contoh: &nbsp;Sentiasa menutup lampu setelah mengguna tandas dan &nbsp;menasihati dan menerang kepada rakan sekerja yang tidak mematuhi peraturan. Selain itu, juga akan melaporkan nama pekerja yang tidak menutup lampu setelah mengguna tandas.</em></p>', NULL, NULL, '2024-11-15 15:54:18', '2024-11-15 15:54:18', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (794, 234, 1, '<p>Selalu tidak tepat masuk kerja dan menunjukkan kedatangan yang tidak baik.<br /><br /><em>Contoh: Masih berada di tempat berehat semasa siren berbunyi dan jalan perlahan ke tempat kerja.</em></p>', NULL, NULL, '2024-11-15 15:54:47', '2024-11-15 15:54:47', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (795, 234, 2, '<p>Kadangkala ada masuk kerja pada masa yang ditetapkan tetapi keadaan tidak ketara.<br /><br /><em>Contoh: Kadangkala ada tepat masuk kerja semasa siren berbunyi tetapi kebanyakan masa tidak masuk kerja pada masa yang tepat.</em></p>', NULL, NULL, '2024-11-15 15:54:59', '2024-11-15 15:54:59', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (796, 234, 3, '<p>Kebanyakan masa masuk kerja pada masa yang ditetapkan tetapi kadangkala ada lewat juga.<br /><br /><em>Contoh: Kebanyakan masa masuk kerja semasa siren berbunyi tetapi sekali kala masih lewat masuk kerja.</em></p>', NULL, NULL, '2024-11-15 15:55:10', '2024-11-15 15:55:10', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (797, 234, 4, '<p>Mementingkan ketepatan masa masuk kerja dan masuk kerja tepat pada masa atau lebih awal.<br /><br /><em>Contoh: Sentiasa masa masuk kerja sebelum siren berbunyi atau lebih awal.</em></p>', NULL, NULL, '2024-11-15 15:55:23', '2024-11-15 15:55:23', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (798, 234, 5, '<p>Mementingkan ketepatan masa masuk kerja dan masuk kerja tepat pada masa atau lebih awal serta memberi nasihat kepada rakan sekerja yang lewat.<br /><br /><em>Contoh: Sentiasa masa masuk kerja sebelum siren berbunyi atau lebih awal serta memberi nasihat kepada rakan sekerja yang lewat.</em></p>', NULL, NULL, '2024-11-15 15:55:36', '2024-11-15 15:55:36', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (799, 235, 1, '<p>Disiplin diri yang tidak memuaskan dan sering meninggalkan tempat kerja dengan berkeliaran tanpa tujuan dan sering membazirkan masa serta curi tulang.<br /><br /><em>Contoh: Sering meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja (banyak kali sehari) dan mengambil masa yang panjang dalam tandas serta membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-15 15:58:47', '2024-11-15 15:58:47', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (800, 235, 2, '<p>Kadangkala membazirkan masa dan curi tulang serta meninggalkan tempat kerja dengan berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Kadangkala meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja (banyak kali sehari) dan mengambil masa yang panjang dalam tandas serta membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-15 15:59:00', '2024-11-15 15:59:00', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (801, 235, 3, '<p>Tidak membazirkan masa dan ringan tulang serta menumpukan perhatian semasa bekerja. Tidak meninggalkan tempat kerja dengan berkeliaran tanpa tujuan.<br /><br /><em>Contoh: Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-15 15:59:10', '2024-11-15 15:59:10', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (802, 235, 4, '<p>Teladan yang baik dan tumpuan perhatian sepenuhnya semasa bekerja. Tidak berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Seorang teladan yang baik dan memberi tumpuan sepenuhnya semasa bekerja. Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-15 15:59:26', '2024-11-15 15:59:26', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (803, 235, 5, '<p>Teladan yang baik dan tumpuan perhatian sepenuhnya semasa bekerja dan juga selalu memberi nasihat kepada rakan sekerja supaya melahirkan keadaan kerja yang lebih agresif. Tidak berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Seorang teladan yang baik dan memberi tumpuan sepenuhnya semasa bekerja. Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja. Selalu memberi nasihat kepada rakan sekerja yang selalu pergi ke tandas sebagai alasan.</em></p>', NULL, NULL, '2024-11-15 15:59:37', '2024-11-15 15:59:37', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (804, 236, 1, '<p>Tidak pernah berada di tempat kerja semasa pembersihan kawasan dijalankan.<br /><br /><em>Contoh: Tidak berada di tempat kerja dan pergi ke tandas semasa pembersihan kawasan dijalankan.</em></p>', NULL, NULL, '2024-11-15 15:59:59', '2024-11-15 15:59:59', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (805, 236, 2, '<p>Memulakan kerja pembersihan kawasan walaupun masa yang ditetapkan belum sampai lagi.<br /><br /><em>Contoh: Memulakan kerja pembersihan kawasan walaupun masa yang ditetapkan belum sampai lagi dan rakan sekerja yang lain masih bekerja lagi.</em></p>', NULL, NULL, '2024-11-15 16:00:09', '2024-11-15 16:00:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (806, 236, 3, '<p>Kebanyakan masa membersihkan kawasan production pada masa yang ditetapkan.</p><p>Kadangkala membersihkan kawasan production pada masa yang ditetapkan tetapi keadaan tidak ketara.</p><p><br />\nContoh: Kadangkala ada berada di production semasa pembersihan kawasan dijalankan tetapi kebanyakan masa tidak nampak orang.</p>', NULL, NULL, '2024-11-15 16:00:24', '2024-11-15 16:00:24', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (807, 236, 4, '<p>Sentiasa mengutamakan dan membersihkan kawasan production pada masa yang ditetapkan.<br /><br /><em>Contoh: Sentiasa membersihkan kawasan production pada masa yang ditetapkan.</em></p>', NULL, NULL, '2024-11-15 16:00:36', '2024-11-15 16:00:36', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (808, 236, 5, '<p>Mengutamakan dan membersihkan kawasan production pada masa yang ditetapkan serta memberi nasihat kepada rakan sekerja yang tidak berbuat demikian.<br /><br /><em>Contoh: Sentiasa membersihkan kawasan production pada masa yang ditetapkan dan memberi nasihat kepada rakan sekerja yang tidak berbuat demikian.</em></p>', NULL, NULL, '2024-11-15 16:00:48', '2024-11-15 16:00:48', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (809, 237, 1, '<p>Hanya menghormati pegawai atasan dan tidak bersopan dengan rakan sekerja.<br /><br /><em>Contoh: Hanya menghormati Leader/Supervisor atau pangkat kerja yang lebih tinggi tetapi tidak bersopan dengan rakan sekerja yang berpangkat rendah/masih baru.</em></p>', NULL, NULL, '2024-11-15 16:01:12', '2024-11-15 16:01:12', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (810, 237, 2, '<p>Biasanya akan bersopan dan menghormati orang lain tetapi kadangkala beremosi.<br /><br /><em>Contoh: Biasanya bersopan dan menghormati rakan sekerja yang lain tetapi kadangkala beremosi dan lawan cakap.</em></p>', NULL, NULL, '2024-11-15 16:01:23', '2024-11-15 16:01:23', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (811, 237, 3, '<p>Sering bersopan dan menghormati orang lain dan tidak bertindak mengikut perasaan.<br /><br /><em>Contoh: Sering bersopan dan menghormati rakan sekerja lain dan tidak bertindak mengikut perasaan.</em></p>', NULL, NULL, '2024-11-15 16:01:35', '2024-11-15 16:01:35', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (812, 237, 4, '<p>Bersopan dan menghormati orang lain pada setiap masa dan tidak bertindak mengikut perasaan dan berbahasa sopan.<br /><br /><em>Contoh: Bersopan dan setiap masa menghormati rakan sekerja yang lain dan tidak bertindak mengikut perasaan dan berbahasa sopan serta jaga perasaan rakan lain.</em></p>', NULL, NULL, '2024-11-15 16:01:46', '2024-11-15 16:01:46', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (813, 237, 5, '<p>Bersopan dan menghormati orang lain pada setiap masa dan masih bercakap dengan sopan walaupun sendiri telah dipersalahkan dalam proses penyelesaian masalah.<br /><br /><em>Contoh: Bersopan dan setiap masa menghormati rakan sekerja yang lain dan masih bercakap dengan sopan walaupun sendiri telah dipersalahkan dalam proses penyelesaian masalah.</em></p>', NULL, NULL, '2024-11-15 16:02:01', '2024-11-15 16:02:01', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (814, 238, 1, '<p>Memang mengetahui arahan yang diberi mempunyai kesilapan tetapi tidak mendapatkan kepastian kerana berpendapat itu adalah tanggungjawab pegawai atasan.<br /><br /><em>Contoh: Tidak mendapatkan kepastian daripada Leader/Supervisor tentang spesifikasi kerja yang diberi walaupun sudah tahu arahan yang diberi mempunyai kesilapan/tidak jelas dan beranggap itu adalah tanggungjawab Leader/Supervisor dan bukan dia.</em></p>', NULL, NULL, '2024-11-15 16:02:45', '2024-11-15 16:02:45', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (815, 238, 2, '<p>Jarang berinisiatif untuk mendapatkan kepastian daripada pegawai atasan walaupun arahan yang diberi tidak jelas atau silap.<br /><br /><em>Contoh: Menunjukkan sikap sudah tahu tetapi tidak ingin peduli dan tidak mendapatkan kepastian daripada Leader/Supervisor walapun arahan yang diberi ada kesilapan/kurang jelas.</em></p>', NULL, NULL, '2024-11-15 16:02:55', '2024-11-15 16:02:55', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (816, 238, 3, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap tetapi tidak pernah melapor balik kepada pegawai atasan tentang tugasan tersebut.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi ada kesilapan/tidak jelas tetapi tidak pernah melapor balik tugasan tersebut.</em></p>', NULL, NULL, '2024-11-15 16:03:06', '2024-11-15 16:03:06', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (817, 238, 4, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi tidak jelas/silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut.</em></p>', NULL, NULL, '2024-11-15 16:03:18', '2024-11-15 16:03:18', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (818, 238, 5, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut serta memberi pendapat yang bermanfaat.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi tidak jelas/silap dan selalu melapor balik kepada Leader/Supervisor dan turut mengambil bahagian untuk memberi pendapat yang bermanfaat.</em></p>', NULL, NULL, '2024-11-15 16:03:30', '2024-11-15 16:03:30', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (819, 239, 1, '<p>Degil dan berpegang teguh dengan pendapat sendiri dan tidak menuruti arahan pegawai atasan.<br /><br /><em>Contoh: Tidak menerima dan melawan percakapan Leader/Supervisor semasa diberi tugasan.</em></p>', NULL, NULL, '2024-11-15 16:03:54', '2024-11-15 16:03:54', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (820, 239, 2, '<p>Kebanyakan masa akan menuruti arahan pegawai atasan tetapi kadangkala akan beremosi dan meluahkan ketidakpuasan.<br /><br /><em>Contoh: Kebanyakan masa akan menerima tugasan Leader/Supervisor dengan baik tetapi kadangkala tidak.</em></p>', NULL, NULL, '2024-11-15 16:04:08', '2024-11-15 16:04:08', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (821, 239, 3, '<p>Mengambil berat dan menuruti arahan pegawai atasan dan tidak pernah membuat hal sesuka hati.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati dan akan bertanya jika tidak faham.</em></p>', NULL, NULL, '2024-11-15 16:04:21', '2024-11-15 16:04:21', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (822, 239, 4, '<p>Mengambil berat dan menuruti arahan pegawai atasan dan tidak pernah membuat hal sesuka hati. Kadangkala turut memberikan pendapat yang bermanfaat dalan kerja yang diberi.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati dan akan bertanya jika tidak faham. Kadangkala turut memberi cadangan/pandangan dalam kerja yang diberi.</em></p>', NULL, NULL, '2024-11-15 16:04:34', '2024-11-15 16:04:34', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (823, 239, 5, '<p>Bersikap positif dan menuruti semua arahan pegawai atasan, tidak membuat hal malah dapat menyampaikan objektif dan kehendak arahan secara positif kepada semua rakan sekerja.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati. Turut menyampaikan maksud dan kehendak mengikuti arahan Leader/Supervisor secara positif kepada rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-15 16:04:47', '2024-11-15 16:04:47', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (824, 240, 1, '<p>Ego dan tidak sudi berbincang tugasan sesama rakan sekerja dan pegawai atasan, sangat keras kepala dan tidak dapat menerima cadangan orang lain.<br /><br /><em>Contoh: Buat kerja tanpa ikut pelan kerja seperti menebuk drill pada kelajuan yang tinggi dan telah membesarkan lubang 3mm kepada 3.20 mm. Dia tidak dapat menerima apabila diminta buat semula pada kelajuan drill yang rendah.</em></p>', NULL, NULL, '2024-11-15 16:05:50', '2024-11-15 16:05:50', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (825, 240, 2, '<p>Jarang berbincang tugasan sesama rakan sekerja dan pegawai atasan dan tidak begitu rela berkongsi maklumat, kadangkala keras kepala dan tidak dapat menerima cadangan orang lain.<br /><br /><em>Contoh: Dia menunjukkan sikap yang tidak begitu gembira apabila diminta buat semula pada kelajuan drill yang rendah.</em></p>', NULL, NULL, '2024-11-15 16:06:02', '2024-11-15 16:06:02', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (826, 240, 3, '<p>Sudi berbincang dan menerima cadangan rakan sekerja dan pegawai atasan, dapat memberi pertolongan apabila diminta.<br /><br /><em>Contoh: Dia sudi membuat semula pada kelajuan drill yang rendah setelah berbincang dan diminta berubah.</em></p>', NULL, NULL, '2024-11-15 16:06:13', '2024-11-15 16:06:13', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (827, 240, 4, '<p>Sudi berbincang dan berinisiatif memberi pertolongan sesama rakan sekerja dan pegawai atasan dengan tidak berkira kerja. Boleh menerima cadangan orang lain dan tidak berkeras kepala.<br /><br /><em>Contoh: Dia sudi membuat semula pada kelajuan drill yang rendah dan dia turut memberi cadangan untuk mengatasi masalah tersebut.</em></p>', NULL, NULL, '2024-11-15 16:06:24', '2024-11-15 16:06:24', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (828, 240, 5, '<p>Sudi berbincang dan berinisiatif memberi pertolongan sesama rakan sekerja dan pegawai atasan dengan tidak berkira kerja. Boleh menerima cadangan orang lain dan tidak berkeras kepala. Selain itu, turut boleh memanggil rakan sekerja untuk sama-sama menyiapkan kerja tersebut.<br /><br /><em>Contoh: Dia ialah orang yang sangat agresif dan sudi membuat semula dan dia turut boleh meminta rakan sekerja untuk sama-sama menyiapkan kerja.</em></p>', NULL, NULL, '2024-11-15 16:06:38', '2024-11-15 16:06:38', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (829, 241, 1, '<p>Menolak tugasan selain dari bidang sendiri dan langsung tidak dapat menerima tugasan tambahan atau di luar bidang kerja, amat mementingkan diri sendiri.<br /><br /><em>Contoh: Tidak mahu backup rakan sekerja yang bercuti dan selalu dipengaruhi oleh rakan sekerja yang lain dimana orang yang berbuat banyak tidak dapat apa-apa.</em></p>', NULL, NULL, '2024-11-15 16:07:07', '2024-11-15 16:07:07', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (830, 241, 2, '<p>Kadangkala menerima tugasan tambahan atau di luar bidang kerja tetapi dengan hati yang tidak rela dan mementingkan kepentingan diri sendiri.<br /><br /><em>Contoh: Kadangkala akan diminta untuk backup rakan sekerja yang bercuti tetapi dia akan membuat kerja secara tidak rela / memberi alasan bahawa dia tidak tahu buat kerja tersebut.</em></p>', NULL, NULL, '2024-11-15 16:07:18', '2024-11-15 16:07:18', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (831, 241, 3, '<p>Rela menerima tugasan tambahan atau di luar bidang dan tidak menolak apabila tugas diberi.<br /><br /><em>Contoh: Rela backup rakan sekerja yang bercuti dan tidak menolak apabila tugas diberi oleh Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-15 16:07:30', '2024-11-15 16:07:30', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (832, 241, 4, '<p>Rela menerima tugasan tambahan atau di luar bidang dan tidak menolak apabila tugas diberi serta cuba mencari cara untuk menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Rela backup rakan sekerja yang bercuti dan tidak menolak apabila tugas diberi oleh Leader / Supervisor. Selain itu, dia juga cari jalan untuk mengeluarkan hasil kerja yang baik / membuat kerja tersebut dengan bersungguh-sungguh.</em></p>', NULL, NULL, '2024-11-15 16:07:42', '2024-11-15 16:07:42', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (833, 241, 5, '<p>Amat rela menerima tugasan tambahan atau di luar bidang dan menerimanya sebagai satu cabaran. Berusaha dan bertanggungjawab sepenuhnya sehingga tugasan selesai dengan sempurna.<br /><br /><em>Contoh: Sangat rela backup rakan sekerja yang bercuti dan menganggap tugas yang diberi tersebut sebagai satu cabaran / tugas sendiri. Dia membuat kerja dengan sepenuh hati dan mengambil tanggungjawab sehingga tugasan tersebut selesai dengan sempurnanya.</em></p>', NULL, NULL, '2024-11-15 16:07:58', '2024-11-15 16:07:58', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (834, 254, 1, '<p>Tidak dapat menyiapkan tugasan mengikut masa yang ditetapkan dan selalu dibuat semula oleh rakan sekerja yang lain dan menyebabkan kelewatan.<br /><br /><em>Contoh: Kerja yang sepatutnya boleh disiapkan dalam sehari tetapi dia selalu tidak hadir bekerja dan kerjanya perlu disambung / dibuat semula oleh rakan sekerja yang lain dan menyebabkan kelewatan.</em></p>', NULL, NULL, '2024-11-18 12:33:20', '2024-11-18 12:33:20', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (835, 254, 2, '<p>Selalu mengambil masa yang panjang untuk menyiapkan kerja walaupun bimbingan sudah diberi.<br /><br /><em>Contoh: Kerja yang sepatutnya boleh disiapkan dalam sehari tetapi dia mengambil masa yang panjang walaupun bimbingan sudah diberi.</em></p>', NULL, NULL, '2024-11-18 12:33:30', '2024-11-18 12:33:30', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (836, 254, 3, '<p>Tugasan biasanya dapat disiapkan dengan sedikit bimbingan dan siap dalam masa yang ditetapkan mahupun lebih awal dan hasil kerja yang masih boleh diterima.<br /><br /><em>Contoh: Boleh menghasilkan kerja dalam masa yang ditetapkan tetapi masih perlu dalam pengawasan/bimbingan.</em></p>', NULL, NULL, '2024-11-18 12:33:41', '2024-11-18 12:33:41', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (837, 254, 4, '<p>Tugasan sentiasa disiapkan tanpa bimbingan dan mengikut jadual mahupun lebih awal dan hasil kerja yang agar memuaskan.<br /><br /><em>Contoh: Boleh menghasilkan kerja dalam masa yang pendek dan tanpa sebarang pengawasan/bimbingan seperti dia cuma perlu 5 jam untuk menghasilkan kerja yang dijangka siap dalam sehari dan dia boleh menghasilkan lebih dalam satu hari.</em></p>', NULL, NULL, '2024-11-18 12:34:16', '2024-11-18 12:34:16', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (838, 254, 5, '<p>Mengutamakan masa dan pantas dalam menyiapkan tugasan yang diberi dan hasil kerja sangat bagus dan boleh diharapkan.<br /><br /><em>Contoh:Boleh membuat apa kerja yang dirancang dan menepati masa yang ditetapkan atau lebih awal tanpa pengawasan/bimbingan. Individu yang teliti dan prihatin dan menguasa masa dan memberi hasil kerja yang sangat bagus dan halus.</em></p>', NULL, NULL, '2024-11-18 12:34:25', '2024-11-18 12:34:25', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (839, 255, 1, '<p>Suka menolak tanggungjawab kerja dan berpura-pura/berdiam diri walaupun tahu apa cara untuk membuat kerja/menyelesaikan masalah.<br /><br /><em>Contoh: Langsung tidak bergerak dan pakai duduk dan tunggu sahaja walaupun sudah diberi penjelasan dalam pelan kerja.</em></p>', NULL, NULL, '2024-11-18 12:35:12', '2024-11-18 12:35:12', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (840, 255, 2, '<p>Kadangkala menolak tanggungjawab kerja dan berpura-pura/berdiam diri walaupun tahu apa cara untuk membuat kerja/menyelesaikan masalah.<br /><br /><em>Contoh: Tidak berusaha untuk belajar dan memahami pembacaan pelan kerja dan ukuran serta memerlukan seseorang mengawasi di tepi dan selalu memberi penjelasan boleh baru dapat menghasilkan kerja yang ditugaskan.</em></p>', NULL, NULL, '2024-11-18 12:35:22', '2024-11-18 12:35:22', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (841, 255, 3, '<p>Sudah faham dan boleh terus bertindak/bergerak ke atas kerja yang telah diselesaikan.&nbsp;<br /><br /><em>Contoh: Sudah tahu membuat kerja/menyelesaikan masalah dan tidak menolak tanggungjawab.</em></p>', NULL, NULL, '2024-11-18 12:35:33', '2024-11-18 12:35:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (842, 255, 4, '<p>Sudah faham dan boleh bertindak cepat ke atas semua tugasan serta tidak perlu pengawasan/bimbingan dan akan lapor balik apabila kerja telah siap.<br /><br /><em>Contoh: Bertanggungjawab dan tidak berpura-pura atau berdiam diri dalam membuat kerja/menyelesaikan masalah dan tidak perlu pengawasan/bimbingan dan akan bertindak/bergerak ke atas kerja yang ditugaskan serta lapor balik apabila kerja telah siap.</em></p>', NULL, NULL, '2024-11-18 12:35:44', '2024-11-18 12:35:44', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (843, 255, 5, '<p>Sudah faham dan boleh bertindak cepat ke atas semua tugasan serta tidak perlu pengawasan/bimbingan dan akan lapor balik apabila kerja telah siap. Selain itu, dapat memberi nasihat kepada rakan sekerja yang lain supaya cepat bertindak dalam kerja.<br /><br /><em>Contoh: Bertanggungjawab dan tidak berpura-pura atau berdiam diri dalam membuat kerja/menyelesaikan masalah dan tidak perlu pengawasan/bimbingan dan akan bertindak/bergerak ke atas kerja yang ditugaskan serta lapor balik apabila kerja telah siap. Selain itu, juga memotivasikan rakan sekerja supaya tidak berpura-pura/berdiam diri dalam &nbsp;membuat kerja/menyelesaikan masalah.</em></p>', NULL, NULL, '2024-11-18 12:35:55', '2024-11-18 12:35:55', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (844, 256, 1, '<p>Tidak membuat kerja secara sistematik dan tidak tahu membezakan kepentingan kerja.<br /><br /><em>Contoh: Tidak tahu membezakan kepentingan kerja dan tidak buat perancangan kerja.</em></p>', NULL, NULL, '2024-11-18 12:37:24', '2024-11-18 12:37:24', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (845, 256, 2, '<p>Kadangkala ada membuat kerja secara sistematik dan kadangkala tahu membezakan kepentingan kerja tetapi keadaan tidak ketara.<br /><br /><em>Contoh: Kadangkala tahu membezakan kepentingan kerja dan buat perancangan kerja tetapi tidak selalu dan ikut mood sendiri.</em></p>', NULL, NULL, '2024-11-18 12:37:34', '2024-11-18 12:37:34', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (846, 256, 3, '<p>Tidak perlu seseorang mengawasi di tepi dan tahu membuat kerja secara sistematik dan tahu membezakan kepentingan kerja dengan penjelasan yang ringkas sahaja.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan memerlukan penjelasan kerja yang ringkas sahaja.</em></p>', NULL, NULL, '2024-11-18 12:37:44', '2024-11-18 12:37:44', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (847, 256, 4, '<p>Hanya memerlukan penjelasan yang ringkas dan tahu membuat kerja secara sistematik dan tahu membezakan kepentingan kerja. Berhati-hati dan tiada kesilapan dalam kerja yang dihasilkan.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan hanya memerlukan penjelasan kerja yang ringkas sahaja dan memberi tumpuan dalam kerja dan mengeluarkan hasil kerja yang baik.</em></p>', NULL, NULL, '2024-11-18 12:37:53', '2024-11-18 12:37:53', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (848, 256, 5, '<p>Hanya memerlukan penjelasan yang sangat ringkas sahaja untuk membuat kerja secara sistematik dan tahu membezakan kepentingan kerja dan dapat memberi tunjuk ajar kepada rakan sekerja.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan hanya memerlukan penjelasan kerja yang ringkas sahaja dan memberi tumpuan dalam kerja dan mengeluarkan hasil kerja yang baik dan turut memberi tunjuk ajar kepada rakan sekerja.</em></p>', NULL, NULL, '2024-11-18 12:38:12', '2024-11-18 12:38:12', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (849, 257, 1, '<p>Hasil kerja yang tidak boleh diterima dan selalu membuat kesilapan.<br /><br /><em>Contoh: Tidak menumpu perhatian semasa bekerja dan selalu membuat kesilapan yang sama. Tidak pernah berubah walaupun &nbsp;sudah diberi bimbingan/teguran seperti selalu mengulangi kesilapan yang sama walaupun sudah banyak kali memasang mesin yang sama model.</em></p>', NULL, NULL, '2024-11-18 12:38:51', '2024-11-18 12:38:51', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (850, 257, 2, '<p>Cuai dan mengakibatkan kesilapan kerja.<br /><br /><em>Contoh: Kadangkala cuai semasa bekerja dan mengakibatkan kesilapan kerja kerana tindakan yang lambat untuk berubah setelah diberi bimbingan/teguran.</em></p>', NULL, NULL, '2024-11-18 12:39:02', '2024-11-18 12:39:02', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (851, 257, 3, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan meminimumkan tahap kesilapan kepada yang terendah.<br /><br /><em>Contoh: Kadangkala ada membuat kesilapan tetapi mengambil tindakan yang cepat untuk berubah setelah diberi bimbingan/teguran.</em></p>', NULL, NULL, '2024-11-18 12:39:13', '2024-11-18 12:39:13', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (852, 257, 4, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan apa-apa kesilapan dalam kerja harian.<br /><br /><em>Contoh: Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan. Selain itu, juga berinisiatif untuk menjaga barangan/bahan dan tidak membazir.</em></p>', NULL, NULL, '2024-11-18 12:40:35', '2024-11-18 12:40:35', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (853, 257, 5, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan kerja dan berinisiatif untuk memberi pendapat dan memperbaiki cara kerja yang lebih baik untuk meminimumkan tahap kesilapan kerja.<br /><br /><em>Contoh: Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan dan berinisiatif untuk memberi pendapat dan memperbaiki cara kerja untuk meminimumkan tahap kesilapan kerja seperti berinisiatif untuk mengetahui masalah semasa pemasangan mesin dan turut memberi pendapat untuk memperbaiki cara kerja/menyelesaikan masalah.</em></p>', NULL, NULL, '2024-11-18 12:40:45', '2024-11-18 12:40:45', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (854, 258, 1, '<p>Langsung tidak memahami permintaan kualiti kerja dan tidak memberi perhatian kepada kerja yang dilakukan.<br /><br /><em>Contoh: Langsung tidak memahami permintaan kualiti kerja dan tidak memberi perhatian terhadap semua kerja yang dilakukan seperti membuat pemasangan Control Panel tetapi langsung tidak mengikut diagram yang diberi.</em></p>', NULL, NULL, '2024-11-18 12:41:11', '2024-11-18 12:41:11', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (855, 258, 2, '<p>Kadangkala tidak faham spesifikasi kerja yang diberi dan tidak berinisiatif mengambil langkah untuk mengetahui untuk menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Tidak berinisiatif untuk bertanya/kurang bertanya apabila tidak tahu semasa memasang Control Panel dan pasang ikut sendiri dan tidak ikut cara kerja yang betul.</em></p>', NULL, NULL, '2024-11-18 12:41:49', '2024-11-18 12:41:49', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (856, 258, 3, '<p>Memahami permintaan kualiti kerja dan dapat menghasilkan kerja yang berkualiti secara individu tanpa pengawasan pegawai atasan tetapi tidak mengambil perhatian dan abaikan kerja yang remeh temeh serta tidak mengambil perhatian terhadap kekemasan hasil kerja.<br /><br /><em>Contoh: Tahu pasang Control Panel tetapi tidak terfikir tentang kekemasan. Wayar sudah ditarik dengan betul tetapi tidak diikat dengan cable tie/tidak tersusun/tidak label semasa membuat pemasangan.</em></p>', NULL, NULL, '2024-11-18 12:42:01', '2024-11-18 12:42:01', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (857, 258, 4, '<p>Faham tentang kualiti dan dapat menghasilkan kerja yang berkualiti dan memenuhi kehendak syarikat dan dapat memastikan kerja yang dihasilkan tidak bermasalah.<br /><br /><em>Contoh: Faham tentang kualiti kerja dan ikut semua spesifikasi yang diminta. Boleh berfikir dan nampak (meramalkan) ke hadapan dan memastikan kerja yang dihasilkan tidak bermasalah seperti tahu pasang Control Panel dan semua litar boleh berfungsi dengan baik dan pemasangan yang kemas dan melaporkan keadaan kepada Leader/Supervisor apabila litar tidak berfungsi/bernyala.</em></p>', NULL, NULL, '2024-11-18 12:42:11', '2024-11-18 12:42:11', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (858, 258, 5, '<p>Sangat faham tentang kualiti kerja dan dapat menghasilkan kerja yang berkualiti dan memenuhi kehendak syarikat dan dapat memastikan kerja yang dihasilkan tidak bermasalah serta turut memberi tunjuk ajar kepada rakan kerja yang lain.&nbsp;<br /><br /><em>Contoh: Sangat faham tentang kualiti kerja dan ikut semua spesifikasi yang diminta. Boleh berfikir dan nampak (meramalkan) ke hadapan dan memastikan kerja yang dihasilkan tidak bermasalah. Selain itu, juga dapat memberi tunjuk ajar kepada rakan sekerja yang lain seperti tahu pasang Control Panel dan semua litar boleh berfungsi dengan baik dan pemasangan yang kemas dan melaporkan keadaan kepada Leader/Supervisor apabila litar tidak berfungsi/bernyala. Selain itu, dia juga memberi tunjuk ajar kepada rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-18 12:42:22', '2024-11-18 12:42:22', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (859, 259, 1, '<p>Sentiasa membazirkan/merosakkan sumber syarikat.<br /><br /><em>Contoh: Tidak pernah berhati-hati dalam spesifikasi kerja yang diberi dan sentiasa mengakibatkan pembaziran bahan.</em></p>', NULL, NULL, '2024-11-18 12:42:45', '2024-11-18 12:42:45', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (860, 259, 2, '<p>Ada bersikap mahu menjimatkan sumber syarikat tetapi kadangkala menyebabkan pembaziran di atas kecuaiannya.<br /><br /><em>Contoh: Cuai dalam pembacaan spesifikasi kerja yang diberi dan silap ambil bahan dan menyebabkan kesilapan dan membazirkan bahan serta perlu &ldquo;rework&rdquo;.</em></p>', NULL, NULL, '2024-11-18 12:42:56', '2024-11-18 12:42:56', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (861, 259, 3, '<p>Berhati-hati semasa bekerja dan menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dan memastikan betul supaya tidak berlaku kesilapan yang mengakibatkan pembaziran bahan dan buang masa.</em></p>', NULL, NULL, '2024-11-18 12:43:07', '2024-11-18 12:43:07', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (862, 259, 4, '<p>Berhati-hati semasa bekerja dan berinisiatif menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya. Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dengan pelan kerja dan memastikan semua barang yang ambil adalah betul. Ada pemikiran tidak membazir seperti dalam menghasilkan sesuatu barang yang sangat kecil, dia akan cari scrap dahulu dan tidak guna bahan yang baru atau bahan yang besar.Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan.</em></p>', NULL, NULL, '2024-11-18 12:43:17', '2024-11-18 12:43:17', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (863, 259, 5, '<p>Berhati-hati semasa bekerja dan berinisiatif menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya. Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan dan juga menyedarkan dan membetulkan kesilapan rakan sekerja yang lain.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dengan pelan kerja dan memastikan semua barang yang ambil adalah betul. Ada pemikiran tidak membazir seperti dalam menghasilkan sesuatu barang yang sangat kecil, dia akan cari scrap dahulu dan tidak guna bahan yang baru atau bahan yang besar.Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan dan menyedarkan dan membetulkan kesilapan rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-18 12:43:29', '2024-11-18 12:43:29', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (864, 260, 1, '<p>Pengetahuan atau kemahiran adalah terhad dan tidak dapat menyelesaikan tugasan dan menggunakan masa yang panjang untuk mempelajari pengetahuan dan cara kerja yang agak senang.<br /><br /><em>Contoh: Tidak ada pengetahuan dan kemahiran kerja dan menggunakan masa yang panjang untuk mempelajari cara kerja yang senang walaupun bimbingan telah diberi seperti membuat kerja kimpalan yang paling senang iaitu mengimpal besi dalam kedudukan rata.</em></p>', NULL, NULL, '2024-11-18 12:43:59', '2024-11-18 12:43:59', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (865, 260, 2, '<p>Kurang pengetahuan atau kemahiran yang cukup untuk mengendalikan tugasan.<br /><br /><em>Contoh: Hasil kimpalan yang teruk dan bimbingan masih diperlukan walaupun diminta menghasilkan kerja kimpalan yang agak senang seperti mengimpal besi dalam kedudukan rata dan mendatar.</em></p>', NULL, NULL, '2024-11-18 12:44:08', '2024-11-18 12:44:08', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (866, 260, 3, '<p>Mempunyai pengetahuan dan kemahiran untuk mengendalikan tugasan dan mempunyai sikap mahu belajar dan mempelajari pengetahuan kerja yang baru dalam masa yang singkat dan mengimplikasikan dalam kerja harian.<br /><br /><em>Contoh: Ada pengetahuan dan kemahiran kimpalan tetapi tidak dapat meneruskan kerja apabila menghadapi kerja yang tidak biasa dan memerlukan bimbingan seperti: boleh mengimpal besi yang nipis tetapi tidak apabila diminta mengimpal besi yang lagi nipis / boleh mengimpal dalam kedudukan rata, mendatar dan menegak tetapi tidak apabila dalam keadaan overhead atau dalam keadaan 45 darjah.</em></p>', NULL, NULL, '2024-11-18 12:44:18', '2024-11-18 12:44:18', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (867, 260, 4, '<p>Boleh menguasai pengetahuan dan kemahiran untuk mengendalikan tugasan dan pencapaian yang agak memuaskan dan dapat menggunakan pengetahuannya untuk meningkatkan kualiti kerja.<br /><br /><em>Contoh: Mempunyai pengetahuan dan kemahiran yang luas serta jelas dengan semua keperluan/permintaan kerja seperti memilih kaedah yang bersesuaian untuk menghasilkan kerja dan tahu mengawal had api untuk mencegah hasil kerja dari kerosakan.</em></p>', NULL, NULL, '2024-11-18 12:44:27', '2024-11-18 12:44:27', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (868, 260, 5, '<p>Menguasai pengetahuan dan kemahiran untuk mengendalikan tugasan dan boleh menggabungkan pengetahuan untuk meningkatkan kualiti kerja serta mencari cara kerja baru untuk menyelesaikan masalah kerja dengan pengetahuannya.<br /><br /><em>Contoh: Mempunyai pengetahuan dan kemahiran yang luas serta jelas dengan semua keperluan/permintaan kerja dan berinisiatif memberi cadangan untuk menyelesaikan masalah kerja.&nbsp;</em></p>', NULL, NULL, '2024-11-18 12:44:44', '2024-11-18 12:44:44', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (869, 261, 1, '<p>Tidak pernah mengemas dan membersihkan tempat kerja sendiri dan sentiasa mengotorkan tempat kerja sendiri dan rakan sekerja yang lain.<br /><br /><em>Contoh: Tidak pernah terfikir kebaikan bersama dan terus membuang sisa kerja ke lantai dan menganggap ini kerja cleaner untuk membersihkan.</em></p>', NULL, NULL, '2024-11-18 12:45:27', '2024-11-18 12:45:27', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (870, 261, 2, '<p>Kadangkala ada mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya tidak kemas.<br /><br /><em>Contoh: Tidak selalu mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya tidak kemas seperti kadangkala ada membersihkan tempat kerja dan kadangkala tidak.</em></p>', NULL, NULL, '2024-11-18 12:45:38', '2024-11-18 12:45:38', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (871, 261, 3, '<p>Berinisiatif untuk mengemas dan membersihkan tempat kerja dan kebanyakan masa tempat kerjanya adalah kemas dan bersih.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai.</em></p>', NULL, NULL, '2024-11-18 12:45:49', '2024-11-18 12:45:49', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (872, 261, 4, '<p>Selalu mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya kemas dan selalu menolong membersihkan kawasan bahagiannya (division) dan kilang.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai serta tolong membersihkan kawasan yang lain.</em></p>', NULL, NULL, '2024-11-18 12:46:01', '2024-11-18 12:46:01', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (873, 261, 5, '<p>Selalu mengemas dan membersihkan tempat kerja dan tempat kerjanya kelihatan kemas dan bersih. Juga selalu menjaga kebersihan seluruh kawasan kilang dan dapat menegur rakan sekerja untuk menjaga kebersihan kilang.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai serta tolong menjaga kebersihan kawasan yang lain dan menegur rakan sekerja yang tidak menjaga kebersihan kilang.</em></p>', NULL, NULL, '2024-11-18 12:46:17', '2024-11-18 12:46:17', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (874, 262, 1, '<p>Tidak menjaga peralatan dan kemudahan syarikat.<br /><br /><em>Contoh: Tidak menjaga peralatan dan kemudahan syarikat seperti tidak menjaga forklift dan tidak pernah meletakkkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-18 14:23:42', '2024-11-18 14:23:42', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (875, 262, 2, '<p>Kadangkala bersikap cuai dalam mengendali peralatan dan kemudahan syarikat dan mengakibatkan kerosakan.<br /><br /><em>Contoh: Tidak selalu menjaga peralatan dan kemudahan syarikat dan mengakibatkan kerosakan seperti forklift terus jalan setelah enjin dihidupkan. Tidak mengambil berat tentang barang yang diangkat dan masuk ke ruang yang kecil. Selalu tidak meletakkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-18 14:23:54', '2024-11-18 14:23:54', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (876, 262, 3, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat dengan cara yang betul.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-18 14:24:05', '2024-11-18 14:24:05', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (877, 262, 4, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat demi kebaikan bersama. Selain itu, &nbsp;melaporkan kepada pihak atasan bila nampak rakan sekerja salahguna dan memberi cara penyelesaian yang bermanfaat.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna dan melapor jika ada kerosakan dan memberi cadangan untuk memperbaiki cara penggunaan dan penjagaan alatan.</em></p>', NULL, NULL, '2024-11-18 14:24:14', '2024-11-18 14:24:14', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (878, 262, 5, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat demi kebaikan bersama. Selain itu, &nbsp;melaporkan kepada pihak atasan bila nampak pekerja salahguna dan memberi cara penyelesaian yang bermanfaat. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna dan melapor jika ada kerosakan dan memberi cadangan untuk memperbaiki cara penggunaan dan penjagaan alatan.Selain itu, akan menyedarkan dan menasihati rakan sekerja yang tidak menjaga forklift semasa mengguna.</em></p>', NULL, NULL, '2024-11-18 14:24:28', '2024-11-18 14:24:28', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (879, 263, 1, '<p>Tidak mengutamakan keselamatan semasa bekerja.<br /><br /><em>Contoh: Tidak mengutamakan keselamatan semasa bekerja seperti tidak memakai PPE semasa bekerja.</em></p>', NULL, NULL, '2024-11-18 14:24:56', '2024-11-18 14:25:01', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (880, 263, 2, '<p>Ada sikap mengutamakan keselamatan tetapi kadangkala tidak.<br /><br /><em>Contoh: Ada memakai PPE semasa bekerja tetapi kadangkala tidak.</em></p>', NULL, NULL, '2024-11-18 14:25:14', '2024-11-18 14:25:14', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (881, 263, 3, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja.</em></p>', NULL, NULL, '2024-11-18 14:25:24', '2024-11-18 14:25:24', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (882, 263, 4, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan.</em></p>', NULL, NULL, '2024-11-18 14:25:37', '2024-11-18 14:25:37', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (883, 263, 5, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja dan melaporkan kepada pihak atasan serta turut memberi cara atau cara penyelesaian yang bermanfaat.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan serta turut memberi cara atau cara penyelesaian yang bermanfaat.</em></p>', NULL, NULL, '2024-11-18 14:25:51', '2024-11-18 14:25:51', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (884, 264, 1, '<p>Menerima tugasan tetapi tidak memikul tanggungjawab kerja dan tidak dapat bekerja di bawah tekanan.<br /><br /><em>Contoh: Dia terima kerja yang diberi tetapi sentiasa bersembang dengan rakan sekerja dan tidak buat kerja sehingga tidak nampak hasil kerja.</em></p>', NULL, NULL, '2024-11-18 14:26:26', '2024-11-18 14:26:26', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (885, 264, 2, '<p>Boleh menerima dan memikul tanggungjawab dan cuba untuk bekerja di bawah tekanan tetapi kadangkala tidak dapat menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Dia boleh buat kerja dan cuba elakkan diri dari tidak masuk kerja/tidak memberi alasan untuk bercuti tetapi kadangkala masih perlu dalam bimbingan.</em></p>', NULL, NULL, '2024-11-18 14:26:39', '2024-11-18 14:26:39', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (886, 264, 3, '<p>Boleh menerima dan memikul tanggungjawab dan dapat menghabiskan setiap kerja yang diamanahkan dengan baik di bawah tekanan dan melaporkan kerja yang telah dilakukan kepada pegawai atasan.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia masih menepati target dan ikut piawai kerja yang ditetapkan oleh syarikat. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia juga akan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-18 14:26:53', '2024-11-18 14:26:53', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (887, 264, 4, '<p>Rela menerima dan memikul tanggungjawab dan sentiasa dapat menghasilkan kerja yang berkualiti di bawah tekanan dan dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang dilakukan kepada pegawai atasan.Boleh buat kerja lebih masa sehingga kerja siap.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia akan menawarkan diri secara sukarela untuk kerja tersebut serta menepati target dan ikut piawai kerja yang ditetapkan oleh syarikat. Boleh buat kerja lebih masa sehingga kerja siap. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-18 14:27:04', '2024-11-18 14:27:04', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (888, 264, 5, '<p>Rela menerima dan memikul tanggungjawab serta tahu kepentingan dan deadline kerja. Dapat memanggil rakan sekerja untuk menyiapkan kerja bersama. Sentiasa dapat menghasilkan kerja yang berkualiti di bawah tekanan dan dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang dilakukan kepada pegawai atasan.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia tahu kepentingan dan deadline kerja tersebut serta dapat memanggil rakan sekerja untuk menyiapkan kerja bersama. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-18 14:27:18', '2024-11-18 14:27:18', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (889, 265, 1, '<p>Tidak rela mengaku kesilapan dan suka menolak tanggungjawab kepada orang lain.<br /><br /><em>Contoh: Telah melakukan kesilapan seperti tidak mengikuti spesifikasi kerja yang diberi oleh Leader / tidak tanya Leader apabila tidak faham / tanya rakan sekerja yang tidak dipertanggungjawabkan dan tidak pernah mengakui kesilapan apabila ditegur oleh Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-18 14:27:42', '2024-11-18 14:27:42', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (890, 265, 2, '<p>Kadangkala tidak rela mengaku kesilapan dan suka membuat perbandingan diri dengan orang lain dalam kesilapan yang telah dibuat.<br /><br /><em>Contoh: Telah melakukan kesilapan seperti tidak mengikuti spesifikasi kerja yang diberi oleh Leader / tidak tanya Leader apabila tidak faham / tanya rakan sekerja yang tidak dipertanggungjawabkan dan kadangkala tidak mengakui kesilapan apabila ditegur oleh Leader/Supervisor malah menyatakan Leader/Supervisor ada prasangka terhadap dia.</em></p>', NULL, NULL, '2024-11-18 14:27:52', '2024-11-18 14:27:52', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (891, 265, 3, '<p>Mengaku kesilapan dan tidak menolak tanggungjawab kepada orang lain.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan. Dia terima dan mengakui kesilapan.</em></p>', NULL, NULL, '2024-11-18 14:28:17', '2024-11-18 14:28:17', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (892, 265, 4, '<p>Tidak melarikan diri dari tanggungjawab dan terus berjumpa dengan pihak atasan untuk mengakui kesilapan dan berinisiatif untuk memperbaiki kesilapan yang telah dilakukan.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan. Dia tidak melarikan diri dari tanggungjawab dan terus berjumpa dengan Leader/Supervisor dan mengakui kesilapan. Selain itu, dia juga memberi cadangan dan sama-sama memperbaiki kesilapan yang telah dilakukan.</em></p>', NULL, NULL, '2024-11-18 14:28:30', '2024-11-18 14:28:30', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (893, 265, 5, '<p>Berani mengaku kesilapan dan tidak menolak tanggungjawab dan memastikan kesilapan tidak berlaku lagi. Berinisiatif untuk memperbetulkan kesilapan dan dapat memberi cadangan yang bermanfaat untuk mengelakkan kesilapan berlaku lagi.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan yang agak besar. Dia berani mengakui kesilapan dan terus berjumpa dengan Leader/Supervisor untuk mengakui kesilapan. Dia mengambil pengalaman tersebut sebagai satu pengajaran dan tidak mengulangi kesilapan tersebut lagi. Selain itu, dia &nbsp;memberi cadangan dan sama-sama memperbaiki kesilapan yang telah dilakukan serta memberi cadangan yang bermanfaat untuk mengelakkan kesilapan berlaku lagi.</em></p>', NULL, NULL, '2024-11-18 14:28:45', '2024-11-18 14:28:45', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (894, 266, 1, '<p>Membuat kerja alah kadar dan setakat membuat kerja sahaja dan tidak menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Tidak menunjukkan sikap ingin belajar dan tidak menumpukan perhatian semasa bekerja seperti dia boleh mengambil masa yang panjang untuk memasang beberapa nut pada mesin.</em></p>', NULL, NULL, '2024-11-18 14:29:11', '2024-11-18 14:29:11', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (895, 266, 2, '<p>Boleh membuat kerja tetapi mudah dipengaruhi orang lain dan kadangkala tidak dapat menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Dia boleh pasang nut pada mesin tetapi mudah dipengaruhi oleh rakan sekerja yang lain seperti dia akan melambatkan proses kerjanya dan sambil kerja sambil bersembang apabila ada rakan sekerja yang bersembang dengannya semasa bekerja.</em></p>', NULL, NULL, '2024-11-18 14:29:21', '2024-11-18 14:29:21', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (896, 266, 3, '<p>Lebih agresif dan sikap kerja juga serius dan dapat menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak mengangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja.</em></p>', NULL, NULL, '2024-11-18 14:29:30', '2024-11-18 14:29:30', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (897, 266, 4, '<p>Bersemangat kerja dan menumpukan perhatian sepenuhnya dalam kerja. Sentiasa mengutamakan kualiti kerja dan menghasilkan kerja yang halus dan teliti dan tidak melakukan kesilapan.<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak menggangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja. Dia sentiasa mengutamakan kualiti kerja dan memastikan nut yang dipasang itu betul dan kemas.</em></p>', NULL, NULL, '2024-11-18 14:29:42', '2024-11-18 14:29:42', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (898, 266, 5, '<p>Matlamat untuk berjaya sangat jelas. Menumpukan perhatian sepenuhnya dalam kerja. Sentiasa mengutamakan kualiti kerja dan menghasilkan kerja yang halus dan teliti dan tidak melakukan kesilapan. Selain itu turut memberi cadangan dan cara kerja untuk memastikan kerja berkualiti dihasilkan setiap kali.&nbsp;<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak menggangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja. Dia sentiasa mengutamakan kualiti kerja dan memastikan nut yang dipasang itu betul dan kemas. Selain itu, dia juga akan memberi cadangan untuk memastikan kerja berkualiti dapat dihasilkan.</em></p>', NULL, NULL, '2024-11-18 14:29:53', '2024-11-18 14:29:53', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (899, 267, 1, '<p>Langsung tidak mahu memahami dan menerima peraturan dan polisi syarikat dan sentiasa membuat aduan terhadap dasar syarikat.<br /><br /><em>Contoh: Selalu tidak menutup lampu setelah mengguna tandas dan membuat aduan apabila pihak syarikat mengambil tindakan.</em></p>', NULL, NULL, '2024-11-18 14:30:29', '2024-11-18 14:30:29', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (900, 267, 2, '<p>Kadangkala sahaja mahu menerima dan mematuhi peraturan dan polisi syarikat.<br /><br /><em>Contoh: Kadangkala ada menutup lampu setelah mengguna tandas kadangkala tidak.</em></p>', NULL, NULL, '2024-11-18 14:30:39', '2024-11-18 14:30:39', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (901, 267, 3, '<p>Menerima dan mematuhi setiap peraturan dan polisi syarikat.<br /><br /><em>Contoh: Setiap kali akan menutup lampu setelah mengguna tandas.</em></p>', NULL, NULL, '2024-11-18 14:30:54', '2024-11-18 14:30:54', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (902, 267, 4, '<p>Tidak melanggar peraturan dan sentiasa dapat menasihatkan rakan sekerja untuk menerima dan mematuhi peraturan dan polisi syarikat untuk kebaikan bersama.<br /><br /><em>Contoh: Sentiasa menutup lampu setelah mengguna tandas dan &nbsp;menasihati dan menerang kepada rakan sekerja yang tidak mematuhi peraturan.</em></p>', NULL, NULL, '2024-11-18 14:31:06', '2024-11-18 14:31:06', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (903, 267, 5, '<p>Memahami dan menerima setiap peraturan dan polisi syarikat dan sentiasa menasihatkan rakan sekerja yang melanggar peraturan serta melaporkan masalah disiplin kepada pegawai atasan untuk kebaikan bersama.<br /><br /><em>Contoh: &nbsp;Sentiasa menutup lampu setelah mengguna tandas dan &nbsp;menasihati dan menerang kepada rakan sekerja yang tidak mematuhi peraturan. Selain itu, juga akan melaporkan nama pekerja yang tidak menutup lampu setelah mengguna tandas.</em></p>', NULL, NULL, '2024-11-18 14:31:19', '2024-11-18 14:31:19', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (904, 268, 1, '<p>Selalu tidak tepat masuk kerja dan menunjukkan kedatangan yang tidak baik.<br /><br /><em>Contoh: Masih berada di tempat berehat semasa siren berbunyi dan jalan perlahan ke tempat kerja.</em></p>', NULL, NULL, '2024-11-18 14:31:43', '2024-11-18 14:31:43', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (905, 268, 2, '<p>Kadangkala ada masuk kerja pada masa yang ditetapkan tetapi keadaan tidak ketara.<br /><br /><em>Contoh: Kadangkala ada tepat masuk kerja semasa siren berbunyi tetapi kebanyakan masa tidak masuk kerja pada masa yang tepat.</em></p>', NULL, NULL, '2024-11-18 14:31:55', '2024-11-18 14:31:55', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (906, 268, 3, '<p>Kebanyakan masa masuk kerja pada masa yang ditetapkan tetapi kadangkala ada lewat juga.<br /><br /><em>Contoh: Kebanyakan masa masuk kerja semasa siren berbunyi tetapi sekali kala masih lewat masuk kerja.</em></p>', NULL, NULL, '2024-11-18 14:32:07', '2024-11-18 14:32:07', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (907, 268, 4, '<p>Mementingkan ketepatan masa masuk kerja dan masuk kerja tepat pada masa atau lebih awal.<br /><br /><em>Contoh: Sentiasa masa masuk kerja sebelum siren berbunyi atau lebih awal.</em></p>', NULL, NULL, '2024-11-18 14:32:18', '2024-11-18 14:32:18', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (908, 268, 5, '<p>Mementingkan ketepatan masa masuk kerja dan masuk kerja tepat pada masa atau lebih awal serta memberi nasihat kepada rakan sekerja yang lewat.<br /><br /><em>Contoh: Sentiasa masa masuk kerja sebelum siren berbunyi atau lebih awal serta memberi nasihat kepada rakan sekerja yang lewat.</em></p>', NULL, NULL, '2024-11-18 14:32:32', '2024-11-18 14:32:32', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (909, 269, 1, '<p>Disiplin diri yang tidak memuaskan dan sering meninggalkan tempat kerja dengan berkeliaran tanpa tujuan dan sering membazirkan masa serta curi tulang.<br /><br /><em>Contoh: Sering meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja (banyak kali sehari) dan mengambil masa yang panjang dalam tandas serta membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-18 14:32:57', '2024-11-18 14:32:57', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (910, 269, 2, '<p>Kadangkala membazirkan masa dan curi tulang serta meninggalkan tempat kerja dengan berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Kadangkala meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja (banyak kali sehari) dan mengambil masa yang panjang dalam tandas serta membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-18 14:33:09', '2024-11-18 14:33:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (911, 269, 3, '<p>Tidak membazirkan masa dan ringan tulang serta menumpukan perhatian semasa bekerja. Tidak meninggalkan tempat kerja dengan berkeliaran tanpa tujuan.<br /><br /><em>Contoh: Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-18 14:33:22', '2024-11-18 14:33:22', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (912, 269, 4, '<p>Teladan yang baik dan tumpuan perhatian sepenuhnya semasa bekerja. Tidak berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Seorang teladan yang baik dan memberi tumpuan sepenuhnya semasa bekerja. Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-18 14:33:34', '2024-11-18 14:33:34', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (913, 269, 5, '<p>Teladan yang baik dan tumpuan perhatian sepenuhnya semasa bekerja dan juga selalu memberi nasihat kepada rakan sekerja supaya melahirkan keadaan kerja yang lebih agresif. Tidak berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Seorang teladan yang baik dan memberi tumpuan sepenuhnya semasa bekerja. Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja. Selalu memberi nasihat kepada rakan sekerja yang selalu pergi ke tandas sebagai alasan.</em></p>', NULL, NULL, '2024-11-18 14:34:17', '2024-11-18 14:34:17', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (914, 270, 1, '<p>Tidak pernah berada di tempat kerja semasa pembersihan kawasan dijalankan.<br /><br /><em>Contoh: Tidak berada di tempat kerja dan pergi ke tandas semasa pembersihan kawasan dijalankan.</em></p>', NULL, NULL, '2024-11-18 15:04:56', '2024-11-18 15:04:56', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (915, 270, 2, '<p>Memulakan kerja pembersihan kawasan walaupun masa yang ditetapkan belum sampai lagi.<br /><br /><em>Contoh: Memulakan kerja pembersihan kawasan walaupun masa yang ditetapkan belum sampai lagi dan rakan sekerja yang lain masih bekerja lagi.</em></p>', NULL, NULL, '2024-11-18 15:05:10', '2024-11-18 15:05:10', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (916, 270, 3, '<p>Kebanyakan masa membersihkan kawasan production pada masa yang ditetapkan.</p><p>Kadangkala membersihkan kawasan production pada masa yang ditetapkan tetapi keadaan tidak ketara.</p><p><br />\nContoh: Kadangkala ada berada di production semasa pembersihan kawasan dijalankan tetapi kebanyakan masa tidak nampak orang.</p>', NULL, NULL, '2024-11-18 15:05:26', '2024-11-18 15:05:26', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (917, 270, 4, '<p>Sentiasa mengutamakan dan membersihkan kawasan production pada masa yang ditetapkan.<br /><br /><em>Contoh: Sentiasa membersihkan kawasan production pada masa yang ditetapkan.</em></p>', NULL, NULL, '2024-11-18 15:05:47', '2024-11-18 15:05:47', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (918, 270, 5, '<p>Mengutamakan dan membersihkan kawasan production pada masa yang ditetapkan serta memberi nasihat kepada rakan sekerja yang tidak berbuat demikian.<br /><br /><em>Contoh: Sentiasa membersihkan kawasan production pada masa yang ditetapkan dan memberi nasihat kepada rakan sekerja yang tidak berbuat demikian.</em></p>', NULL, NULL, '2024-11-18 15:06:07', '2024-11-18 15:06:07', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (919, 271, 1, '<p>Hanya menghormati pegawai atasan dan tidak bersopan dengan rakan sekerja.<br /><br /><em>Contoh: Hanya menghormati Leader/Supervisor atau pangkat kerja yang lebih tinggi tetapi tidak bersopan dengan rakan sekerja yang berpangkat rendah/masih baru.</em></p>', NULL, NULL, '2024-11-18 15:06:35', '2024-11-18 15:06:35', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (920, 271, 2, '<p>Biasanya akan bersopan dan menghormati orang lain tetapi kadangkala beremosi.<br /><br /><em>Contoh: Biasanya bersopan dan menghormati rakan sekerja yang lain tetapi kadangkala beremosi dan lawan cakap.</em></p>', NULL, NULL, '2024-11-18 15:06:48', '2024-11-18 15:06:48', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (921, 271, 3, '<p>Sering bersopan dan menghormati orang lain dan tidak bertindak mengikut perasaan.<br /><br /><em>Contoh: Sering bersopan dan menghormati rakan sekerja lain dan tidak bertindak mengikut perasaan.</em></p>', NULL, NULL, '2024-11-18 15:06:59', '2024-11-18 15:06:59', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (922, 271, 4, '<p>Bersopan dan menghormati orang lain pada setiap masa dan tidak bertindak mengikut perasaan dan berbahasa sopan.<br /><br /><em>Contoh: Bersopan dan setiap masa menghormati rakan sekerja yang lain dan tidak bertindak mengikut perasaan dan berbahasa sopan serta jaga perasaan rakan lain.</em></p>', NULL, NULL, '2024-11-18 15:07:08', '2024-11-18 15:07:08', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (923, 271, 5, '<p>Bersopan dan menghormati orang lain pada setiap masa dan masih bercakap dengan sopan walaupun sendiri telah dipersalahkan dalam proses penyelesaian masalah.<br /><br /><em>Contoh: Bersopan dan setiap masa menghormati rakan sekerja yang lain dan masih bercakap dengan sopan walaupun sendiri telah dipersalahkan dalam proses penyelesaian masalah.</em></p>', NULL, NULL, '2024-11-18 15:09:07', '2024-11-18 15:09:07', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (924, 272, 1, '<p>Memang mengetahui arahan yang diberi mempunyai kesilapan tetapi tidak mendapatkan kepastian kerana berpendapat itu adalah tanggungjawab pegawai atasan.<br /><br /><em>Contoh: Tidak mendapatkan kepastian daripada Leader/Supervisor tentang spesifikasi kerja yang diberi walaupun sudah tahu arahan yang diberi mempunyai kesilapan/tidak jelas dan beranggap itu adalah tanggungjawab Leader/Supervisor dan bukan dia.</em></p>', NULL, NULL, '2024-11-18 15:12:12', '2024-11-18 15:12:12', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (925, 272, 2, '<p>Jarang berinisiatif untuk mendapatkan kepastian daripada pegawai atasan walaupun arahan yang diberi tidak jelas atau silap.<br /><br /><em>Contoh: Menunjukkan sikap sudah tahu tetapi tidak ingin peduli dan tidak mendapatkan kepastian daripada Leader/Supervisor walapun arahan yang diberi ada kesilapan/kurang jelas.</em></p>', NULL, NULL, '2024-11-18 15:12:23', '2024-11-18 15:12:23', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (926, 272, 3, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap tetapi tidak pernah melapor balik kepada pegawai atasan tentang tugasan tersebut.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi ada kesilapan/tidak jelas tetapi tidak pernah melapor balik tugasan tersebut.</em></p>', NULL, NULL, '2024-11-18 15:12:34', '2024-11-18 15:12:34', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (927, 272, 4, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi tidak jelas/silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut.</em></p>', NULL, NULL, '2024-11-18 15:12:51', '2024-11-18 15:12:51', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (928, 272, 5, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut serta memberi pendapat yang bermanfaat.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi tidak jelas/silap dan selalu melapor balik kepada Leader/Supervisor dan turut mengambil bahagian untuk memberi pendapat yang bermanfaat.</em></p>', NULL, NULL, '2024-11-18 15:13:03', '2024-11-18 15:13:03', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (929, 273, 1, '<p>Degil dan berpegang teguh dengan pendapat sendiri dan tidak menuruti arahan pegawai atasan.<br /><br /><em>Contoh: Tidak menerima dan melawan percakapan Leader/Supervisor semasa diberi tugasan.</em></p>', NULL, NULL, '2024-11-18 15:13:45', '2024-11-18 15:13:45', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (930, 273, 2, '<p>Kebanyakan masa akan menuruti arahan pegawai atasan tetapi kadangkala akan beremosi dan meluahkan ketidakpuasan.<br /><br /><em>Contoh: Kebanyakan masa akan menerima tugasan Leader/Supervisor dengan baik tetapi kadangkala tidak.</em></p>', NULL, NULL, '2024-11-18 15:13:55', '2024-11-18 15:13:55', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (931, 273, 3, '<p>Mengambil berat dan menuruti arahan pegawai atasan dan tidak pernah membuat hal sesuka hati.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati dan akan bertanya jika tidak faham.</em></p>', NULL, NULL, '2024-11-18 15:14:04', '2024-11-18 15:14:04', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (932, 273, 4, '<p>Mengambil berat dan menuruti arahan pegawai atasan dan tidak pernah membuat hal sesuka hati. Kadangkala turut memberikan pendapat yang bermanfaat dalan kerja yang diberi.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati dan akan bertanya jika tidak faham. Kadangkala turut memberi cadangan/pandangan dalam kerja yang diberi.</em></p>', NULL, NULL, '2024-11-18 15:14:14', '2024-11-18 15:14:14', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (933, 273, 5, '<p>Bersikap positif dan menuruti semua arahan pegawai atasan, tidak membuat hal malah dapat menyampaikan objektif dan kehendak arahan secara positif kepada semua rakan sekerja.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati. Turut menyampaikan maksud dan kehendak mengikuti arahan Leader/Supervisor secara positif kepada rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-18 15:14:24', '2024-11-18 15:14:24', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (934, 274, 1, '<p>Ego dan tidak sudi berbincang tugasan sesama rakan sekerja dan pegawai atasan, sangat keras kepala dan tidak dapat menerima cadangan orang lain.<br /><br /><em>Contoh: Buat kerja tanpa ikut pelan kerja seperti menebuk drill pada kelajuan yang tinggi dan telah membesarkan lubang 3mm kepada 3.20 mm. Dia tidak dapat menerima apabila diminta buat semula pada kelajuan drill yang rendah.</em></p>', NULL, NULL, '2024-11-18 15:15:24', '2024-11-18 15:15:24', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (935, 274, 2, '<p>Jarang berbincang tugasan sesama rakan sekerja dan pegawai atasan dan tidak begitu rela berkongsi maklumat, kadangkala keras kepala dan tidak dapat menerima cadangan orang lain.<br /><br /><em>Contoh: Dia menunjukkan sikap yang tidak begitu gembira apabila diminta buat semula pada kelajuan drill yang rendah.</em></p>', NULL, NULL, '2024-11-18 15:15:35', '2024-11-18 15:15:35', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (936, 274, 3, '<p>Sudi berbincang dan menerima cadangan rakan sekerja dan pegawai atasan, dapat memberi pertolongan apabila diminta.<br /><br /><em>Contoh: Dia sudi membuat semula pada kelajuan drill yang rendah setelah berbincang dan diminta berubah.</em></p>', NULL, NULL, '2024-11-18 15:15:46', '2024-11-18 15:15:46', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (937, 274, 4, '<p>Sudi berbincang dan berinisiatif memberi pertolongan sesama rakan sekerja dan pegawai atasan dengan tidak berkira kerja. Boleh menerima cadangan orang lain dan tidak berkeras kepala.<br /><br /><em>Contoh: Dia sudi membuat semula pada kelajuan drill yang rendah dan dia turut memberi cadangan untuk mengatasi masalah tersebut.</em></p>', NULL, NULL, '2024-11-18 15:15:56', '2024-11-18 15:15:56', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (938, 274, 5, '<p>Sudi berbincang dan berinisiatif memberi pertolongan sesama rakan sekerja dan pegawai atasan dengan tidak berkira kerja. Boleh menerima cadangan orang lain dan tidak berkeras kepala. Selain itu, turut boleh memanggil rakan sekerja untuk sama-sama menyiapkan kerja tersebut.<br /><br /><em>Contoh: Dia ialah orang yang sangat agresif dan sudi membuat semula dan dia turut boleh meminta rakan sekerja untuk sama-sama menyiapkan kerja.</em></p>', NULL, NULL, '2024-11-18 15:16:08', '2024-11-18 15:16:08', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (939, 275, 1, '<p>Menolak tugasan selain dari bidang sendiri dan langsung tidak dapat menerima tugasan tambahan atau di luar bidang kerja, amat mementingkan diri sendiri.<br /><br /><em>Contoh: Tidak mahu backup rakan sekerja yang bercuti dan selalu dipengaruhi oleh rakan sekerja yang lain dimana orang yang berbuat banyak tidak dapat apa-apa.</em></p>', NULL, NULL, '2024-11-18 15:17:02', '2024-11-18 15:17:02', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (940, 275, 2, '<p>Kadangkala menerima tugasan tambahan atau di luar bidang kerja tetapi dengan hati yang tidak rela dan mementingkan kepentingan diri sendiri.<br /><br /><em>Contoh: Kadangkala akan diminta untuk backup rakan sekerja yang bercuti tetapi dia akan membuat kerja secara tidak rela / memberi alasan bahawa dia tidak tahu buat kerja tersebut.</em></p>', NULL, NULL, '2024-11-18 15:17:21', '2024-11-18 15:17:21', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (941, 275, 3, '<p>Rela menerima tugasan tambahan atau di luar bidang dan tidak menolak apabila tugas diberi.<br /><br /><em>Contoh: Rela backup rakan sekerja yang bercuti dan tidak menolak apabila tugas diberi oleh Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-18 15:17:32', '2024-11-18 15:17:32', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (942, 275, 4, '<p>Rela menerima tugasan tambahan atau di luar bidang dan tidak menolak apabila tugas diberi serta cuba mencari cara untuk menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Rela backup rakan sekerja yang bercuti dan tidak menolak apabila tugas diberi oleh Leader / Supervisor. Selain itu, dia juga cari jalan untuk mengeluarkan hasil kerja yang baik / membuat kerja tersebut dengan bersungguh-sungguh.</em></p>', NULL, NULL, '2024-11-18 15:17:42', '2024-11-18 15:17:42', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (943, 275, 5, '<p>Amat rela menerima tugasan tambahan atau di luar bidang dan menerimanya sebagai satu cabaran. Berusaha dan bertanggungjawab sepenuhnya sehingga tugasan selesai dengan sempurna.<br /><br /><em>Contoh: Sangat rela backup rakan sekerja yang bercuti dan menganggap tugas yang diberi tersebut sebagai satu cabaran / tugas sendiri. Dia membuat kerja dengan sepenuh hati dan mengambil tanggungjawab sehingga tugasan tersebut selesai dengan sempurnanya.</em></p>', NULL, NULL, '2024-11-18 15:17:57', '2024-11-18 15:17:57', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (944, 288, 1, '<p>Tidak dapat menyiapkan tugasan mengikut masa yang ditetapkan dan selalu dibuat semula oleh rakan sekerja yang lain dan menyebabkan kelewatan.<br /><br /><em>Contoh: Kerja yang sepatutnya boleh disiapkan dalam sehari tetapi dia selalu tidak hadir bekerja dan kerjanya perlu disambung / dibuat semula oleh rakan sekerja yang lain dan menyebabkan kelewatan.</em></p>', NULL, NULL, '2024-11-18 15:32:09', '2024-11-18 15:32:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (945, 288, 2, '<p>Selalu mengambil masa yang panjang untuk menyiapkan kerja walaupun bimbingan sudah diberi.<br /><br /><em>Contoh: Kerja yang sepatutnya boleh disiapkan dalam sehari tetapi dia mengambil masa yang panjang walaupun bimbingan sudah diberi.</em></p>', NULL, NULL, '2024-11-18 15:32:21', '2024-11-18 15:32:21', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (946, 288, 3, '<p>Tugasan biasanya dapat disiapkan dengan sedikit bimbingan dan siap dalam masa yang ditetapkan mahupun lebih awal dan hasil kerja yang masih boleh diterima.<br /><br /><em>Contoh: Boleh menghasilkan kerja dalam masa yang ditetapkan tetapi masih perlu dalam pengawasan/bimbingan.</em></p>', NULL, NULL, '2024-11-18 15:32:33', '2024-11-18 15:32:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (947, 288, 4, '<p>Tugasan sentiasa disiapkan tanpa bimbingan dan mengikut jadual mahupun lebih awal dan hasil kerja yang agar memuaskan.<br /><br /><em>Contoh: Boleh menghasilkan kerja dalam masa yang pendek dan tanpa sebarang pengawasan/bimbingan seperti dia cuma perlu 5 jam untuk menghasilkan kerja yang dijangka siap dalam sehari dan dia boleh menghasilkan lebih dalam satu hari.</em></p>', NULL, NULL, '2024-11-18 15:32:49', '2024-11-18 15:32:49', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (948, 288, 5, '<p>Mengutamakan masa dan pantas dalam menyiapkan tugasan yang diberi dan hasil kerja sangat bagus dan boleh diharapkan.<br /><br /><em>Contoh:Boleh membuat apa kerja yang dirancang dan menepati masa yang ditetapkan atau lebih awal tanpa pengawasan/bimbingan. Individu yang teliti dan prihatin dan menguasa masa dan memberi hasil kerja yang sangat bagus dan halus.</em></p>', NULL, NULL, '2024-11-18 15:33:06', '2024-11-18 15:33:06', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (949, 289, 1, '<p>Suka menolak tanggungjawab kerja dan berpura-pura/berdiam diri walaupun tahu apa cara untuk membuat kerja/menyelesaikan masalah.<br /><br /><em>Contoh: Langsung tidak bergerak dan pakai duduk dan tunggu sahaja walaupun sudah diberi penjelasan dalam pelan kerja.</em></p>', NULL, NULL, '2024-11-18 15:36:29', '2024-11-18 15:36:29', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (950, 289, 2, '<p>Kadangkala menolak tanggungjawab kerja dan berpura-pura/berdiam diri walaupun tahu apa cara untuk membuat kerja/menyelesaikan masalah.<br /><br /><em>Contoh: Tidak berusaha untuk belajar dan memahami pembacaan pelan kerja dan ukuran serta memerlukan seseorang mengawasi di tepi dan selalu memberi penjelasan boleh baru dapat menghasilkan kerja yang ditugaskan.</em></p>', NULL, NULL, '2024-11-18 15:36:41', '2024-11-18 15:36:41', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (951, 289, 3, '<p>Sudah faham dan boleh terus bertindak/bergerak ke atas kerja yang telah diselesaikan.&nbsp;<br /><br /><em>Contoh: Sudah tahu membuat kerja/menyelesaikan masalah dan tidak menolak tanggungjawab.</em></p>', NULL, NULL, '2024-11-18 15:36:55', '2024-11-18 15:36:55', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (952, 289, 4, '<p>Sudah faham dan boleh bertindak cepat ke atas semua tugasan serta tidak perlu pengawasan/bimbingan dan akan lapor balik apabila kerja telah siap.<br /><br /><em>Contoh: Bertanggungjawab dan tidak berpura-pura atau berdiam diri dalam membuat kerja/menyelesaikan masalah dan tidak perlu pengawasan/bimbingan dan akan bertindak/bergerak ke atas kerja yang ditugaskan serta lapor balik apabila kerja telah siap.</em></p>', NULL, NULL, '2024-11-18 15:37:05', '2024-11-18 15:37:05', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (953, 289, 5, '<p>Sudah faham dan boleh bertindak cepat ke atas semua tugasan serta tidak perlu pengawasan/bimbingan dan akan lapor balik apabila kerja telah siap. Selain itu, dapat memberi nasihat kepada rakan sekerja yang lain supaya cepat bertindak dalam kerja.<br /><br /><em>Contoh: Bertanggungjawab dan tidak berpura-pura atau berdiam diri dalam membuat kerja/menyelesaikan masalah dan tidak perlu pengawasan/bimbingan dan akan bertindak/bergerak ke atas kerja yang ditugaskan serta lapor balik apabila kerja telah siap. Selain itu, juga memotivasikan rakan sekerja supaya tidak berpura-pura/berdiam diri dalam &nbsp;membuat kerja/menyelesaikan masalah.</em></p>', NULL, NULL, '2024-11-18 15:37:22', '2024-11-18 15:37:22', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (954, 290, 1, '<p>Tidak membuat kerja secara sistematik dan tidak tahu membezakan kepentingan kerja.<br /><br /><em>Contoh: Tidak tahu membezakan kepentingan kerja dan tidak buat perancangan kerja.</em></p>', NULL, NULL, '2024-11-18 15:38:04', '2024-11-18 15:38:04', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (955, 290, 2, '<p>Kadangkala ada membuat kerja secara sistematik dan kadangkala tahu membezakan kepentingan kerja tetapi keadaan tidak ketara.<br /><br /><em>Contoh: Kadangkala tahu membezakan kepentingan kerja dan buat perancangan kerja tetapi tidak selalu dan ikut mood sendiri.</em></p>', NULL, NULL, '2024-11-18 15:38:14', '2024-11-18 15:38:14', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (956, 290, 3, '<p>Tidak perlu seseorang mengawasi di tepi dan tahu membuat kerja secara sistematik dan tahu membezakan kepentingan kerja dengan penjelasan yang ringkas sahaja.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan memerlukan penjelasan kerja yang ringkas sahaja.</em></p>', NULL, NULL, '2024-11-18 15:38:29', '2024-11-18 15:38:29', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (957, 290, 4, '<p>Hanya memerlukan penjelasan yang ringkas dan tahu membuat kerja secara sistematik dan tahu membezakan kepentingan kerja. Berhati-hati dan tiada kesilapan dalam kerja yang dihasilkan.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan hanya memerlukan penjelasan kerja yang ringkas sahaja dan memberi tumpuan dalam kerja dan mengeluarkan hasil kerja yang baik.</em></p>', NULL, NULL, '2024-11-18 15:38:51', '2024-11-18 15:38:51', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (958, 290, 5, '<p>Hanya memerlukan penjelasan yang sangat ringkas sahaja untuk membuat kerja secara sistematik dan tahu membezakan kepentingan kerja dan dapat memberi tunjuk ajar kepada rakan sekerja.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan hanya memerlukan penjelasan kerja yang ringkas sahaja dan memberi tumpuan dalam kerja dan mengeluarkan hasil kerja yang baik dan turut memberi tunjuk ajar kepada rakan sekerja.</em></p>', NULL, NULL, '2024-11-18 15:39:04', '2024-11-18 15:39:04', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (959, 291, 1, '<p>Hasil kerja yang tidak boleh diterima dan selalu membuat kesilapan.<br /><br /><em>Contoh: Tidak menumpu perhatian semasa bekerja dan selalu membuat kesilapan yang sama. Tidak pernah berubah walaupun &nbsp;sudah diberi bimbingan/teguran seperti selalu mengulangi kesilapan yang sama walaupun sudah banyak kali memasang mesin yang sama model.</em></p>', NULL, NULL, '2024-11-18 15:39:46', '2024-11-18 15:39:46', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (960, 291, 2, '<p>Cuai dan mengakibatkan kesilapan kerja.<br /><br /><em>Contoh: Kadangkala cuai semasa bekerja dan mengakibatkan kesilapan kerja kerana tindakan yang lambat untuk berubah setelah diberi bimbingan/teguran.</em></p>', NULL, NULL, '2024-11-18 15:39:58', '2024-11-18 15:39:58', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (961, 291, 3, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan meminimumkan tahap kesilapan kepada yang terendah.<br /><br /><em>Contoh: Kadangkala ada membuat kesilapan tetapi mengambil tindakan yang cepat untuk berubah setelah diberi bimbingan/teguran.</em></p>', NULL, NULL, '2024-11-18 15:40:15', '2024-11-18 15:40:15', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (962, 291, 4, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan apa-apa kesilapan dalam kerja harian.<br /><br /><em>Contoh: Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan. Selain itu, juga berinisiatif untuk menjaga barangan/bahan dan tidak membazir.</em></p>', NULL, NULL, '2024-11-18 15:40:29', '2024-11-18 15:40:29', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (963, 291, 5, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan kerja dan berinisiatif untuk memberi pendapat dan memperbaiki cara kerja yang lebih baik untuk meminimumkan tahap kesilapan kerja.<br /><br /><em>Contoh: Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan dan berinisiatif untuk memberi pendapat dan memperbaiki cara kerja untuk meminimumkan tahap kesilapan kerja seperti berinisiatif untuk mengetahui masalah semasa pemasangan mesin dan turut memberi pendapat untuk memperbaiki cara kerja/menyelesaikan masalah.</em></p>', NULL, NULL, '2024-11-18 15:40:47', '2024-11-18 15:40:47', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (964, 292, 1, '<p>Langsung tidak memahami permintaan kualiti kerja dan tidak memberi perhatian kepada kerja yang dilakukan.<br /><br /><em>Contoh: Langsung tidak memahami permintaan kualiti kerja dan tidak memberi perhatian terhadap semua kerja yang dilakukan seperti membuat pemasangan Control Panel tetapi langsung tidak mengikut diagram yang diberi.</em></p>', NULL, NULL, '2024-11-18 15:48:41', '2024-11-18 15:48:41', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (965, 292, 2, '<p>Kadangkala tidak faham spesifikasi kerja yang diberi dan tidak berinisiatif mengambil langkah untuk mengetahui untuk menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Tidak berinisiatif untuk bertanya/kurang bertanya apabila tidak tahu semasa memasang Control Panel dan pasang ikut sendiri dan tidak ikut cara kerja yang betul.</em></p>', NULL, NULL, '2024-11-18 15:48:53', '2024-11-18 15:48:53', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (966, 292, 3, '<p>Memahami permintaan kualiti kerja dan dapat menghasilkan kerja yang berkualiti secara individu tanpa pengawasan pegawai atasan tetapi tidak mengambil perhatian dan abaikan kerja yang remeh temeh serta tidak mengambil perhatian terhadap kekemasan hasil kerja.<br /><br /><em>Contoh: Tahu pasang Control Panel tetapi tidak terfikir tentang kekemasan. Wayar sudah ditarik dengan betul tetapi tidak diikat dengan cable tie/tidak tersusun/tidak label semasa membuat pemasangan.</em></p>', NULL, NULL, '2024-11-18 15:49:05', '2024-11-18 15:49:05', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (967, 292, 4, '<p>Faham tentang kualiti dan dapat menghasilkan kerja yang berkualiti dan memenuhi kehendak syarikat dan dapat memastikan kerja yang dihasilkan tidak bermasalah.<br /><br /><em>Contoh: Faham tentang kualiti kerja dan ikut semua spesifikasi yang diminta. Boleh berfikir dan nampak (meramalkan) ke hadapan dan memastikan kerja yang dihasilkan tidak bermasalah seperti tahu pasang Control Panel dan semua litar boleh berfungsi dengan baik dan pemasangan yang kemas dan melaporkan keadaan kepada Leader/Supervisor apabila litar tidak berfungsi/bernyala.</em></p>', NULL, NULL, '2024-11-18 15:49:16', '2024-11-18 15:49:16', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (968, 292, 5, '<p>Sangat faham tentang kualiti kerja dan dapat menghasilkan kerja yang berkualiti dan memenuhi kehendak syarikat dan dapat memastikan kerja yang dihasilkan tidak bermasalah serta turut memberi tunjuk ajar kepada rakan kerja yang lain.&nbsp;<br /><br /><em>Contoh: Sangat faham tentang kualiti kerja dan ikut semua spesifikasi yang diminta. Boleh berfikir dan nampak (meramalkan) ke hadapan dan memastikan kerja yang dihasilkan tidak bermasalah. Selain itu, juga dapat memberi tunjuk ajar kepada rakan sekerja yang lain seperti tahu pasang Control Panel dan semua litar boleh berfungsi dengan baik dan pemasangan yang kemas dan melaporkan keadaan kepada Leader/Supervisor apabila litar tidak berfungsi/bernyala. Selain itu, dia juga memberi tunjuk ajar kepada rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-18 15:49:27', '2024-11-18 15:49:27', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (969, 293, 1, '<p>Sentiasa membazirkan/merosakkan sumber syarikat.<br /><br /><em>Contoh: Tidak pernah berhati-hati dalam spesifikasi kerja yang diberi dan sentiasa mengakibatkan pembaziran bahan.</em></p>', NULL, NULL, '2024-11-18 15:50:01', '2024-11-18 15:50:01', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (970, 293, 2, '<p>Ada bersikap mahu menjimatkan sumber syarikat tetapi kadangkala menyebabkan pembaziran di atas kecuaiannya.<br /><br /><em>Contoh: Cuai dalam pembacaan spesifikasi kerja yang diberi dan silap ambil bahan dan menyebabkan kesilapan dan membazirkan bahan serta perlu &ldquo;rework&rdquo;.</em></p>', NULL, NULL, '2024-11-18 15:50:13', '2024-11-18 15:50:13', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (971, 293, 3, '<p>Berhati-hati semasa bekerja dan menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dan memastikan betul supaya tidak berlaku kesilapan yang mengakibatkan pembaziran bahan dan buang masa.</em></p>', NULL, NULL, '2024-11-18 15:50:24', '2024-11-18 15:50:24', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (972, 293, 4, '<p>Berhati-hati semasa bekerja dan berinisiatif menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya. Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dengan pelan kerja dan memastikan semua barang yang ambil adalah betul. Ada pemikiran tidak membazir seperti dalam menghasilkan sesuatu barang yang sangat kecil, dia akan cari scrap dahulu dan tidak guna bahan yang baru atau bahan yang besar.Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan.</em></p>', NULL, NULL, '2024-11-18 15:50:34', '2024-11-18 15:50:34', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (973, 293, 5, '<p>Berhati-hati semasa bekerja dan berinisiatif menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya. Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan dan juga menyedarkan dan membetulkan kesilapan rakan sekerja yang lain.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dengan pelan kerja dan memastikan semua barang yang ambil adalah betul. Ada pemikiran tidak membazir seperti dalam menghasilkan sesuatu barang yang sangat kecil, dia akan cari scrap dahulu dan tidak guna bahan yang baru atau bahan yang besar.Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan dan menyedarkan dan membetulkan kesilapan rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-18 15:50:45', '2024-11-18 15:50:45', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (974, 294, 1, '<p>Pengetahuan atau kemahiran adalah terhad dan tidak dapat menyelesaikan tugasan dan menggunakan masa yang panjang untuk mempelajari pengetahuan dan cara kerja yang agak senang.<br /><br /><em>Contoh: Tidak ada pengetahuan dan kemahiran kerja dan menggunakan masa yang panjang untuk mempelajari cara kerja yang senang walaupun bimbingan telah diberi seperti membuat kerja kimpalan yang paling senang iaitu mengimpal besi dalam kedudukan rata.</em></p>', NULL, NULL, '2024-11-18 15:51:12', '2024-11-18 15:51:12', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (975, 294, 2, '<p>Kurang pengetahuan atau kemahiran yang cukup untuk mengendalikan tugasan.<br /><br /><em>Contoh: Hasil kimpalan yang teruk dan bimbingan masih diperlukan walaupun diminta menghasilkan kerja kimpalan yang agak senang seperti mengimpal besi dalam kedudukan rata dan mendatar.</em></p>', NULL, NULL, '2024-11-18 15:51:21', '2024-11-18 15:52:03', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (976, 294, 3, '<p>Mempunyai pengetahuan dan kemahiran untuk mengendalikan tugasan dan mempunyai sikap mahu belajar dan mempelajari pengetahuan kerja yang baru dalam masa yang singkat dan mengimplikasikan dalam kerja harian.<br /><br /><em>Contoh: Ada pengetahuan dan kemahiran kimpalan tetapi tidak dapat meneruskan kerja apabila menghadapi kerja yang tidak biasa dan memerlukan bimbingan seperti: boleh mengimpal besi yang nipis tetapi tidak apabila diminta mengimpal besi yang lagi nipis / boleh mengimpal dalam kedudukan rata, mendatar dan menegak tetapi tidak apabila dalam keadaan overhead atau dalam keadaan 45 darjah.</em></p>', NULL, NULL, '2024-11-18 15:53:40', '2024-11-18 15:53:40', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (977, 294, 4, '<p>Boleh menguasai pengetahuan dan kemahiran untuk mengendalikan tugasan dan pencapaian yang agak memuaskan dan dapat menggunakan pengetahuannya untuk meningkatkan kualiti kerja.<br /><br /><em>Contoh: Mempunyai pengetahuan dan kemahiran yang luas serta jelas dengan semua keperluan/permintaan kerja seperti memilih kaedah yang bersesuaian untuk menghasilkan kerja dan tahu mengawal had api untuk mencegah hasil kerja dari kerosakan.</em></p>', NULL, NULL, '2024-11-18 15:53:52', '2024-11-18 15:53:52', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (978, 294, 5, '<p>Menguasai pengetahuan dan kemahiran untuk mengendalikan tugasan dan boleh menggabungkan pengetahuan untuk meningkatkan kualiti kerja serta mencari cara kerja baru untuk menyelesaikan masalah kerja dengan pengetahuannya.<br /><br /><em>Contoh: Mempunyai pengetahuan dan kemahiran yang luas serta jelas dengan semua keperluan/permintaan kerja dan berinisiatif memberi cadangan untuk menyelesaikan masalah kerja.&nbsp;</em></p>', NULL, NULL, '2024-11-18 15:54:02', '2024-11-18 15:54:02', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (979, 295, 1, '<p>Tidak pernah mengemas dan membersihkan tempat kerja sendiri dan sentiasa mengotorkan tempat kerja sendiri dan rakan sekerja yang lain.<br /><br /><em>Contoh: Tidak pernah terfikir kebaikan bersama dan terus membuang sisa kerja ke lantai dan menganggap ini kerja cleaner untuk membersihkan.</em></p>', NULL, NULL, '2024-11-18 16:05:03', '2024-11-18 16:05:03', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (980, 295, 2, '<p>Kadangkala ada mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya tidak kemas.<br /><br /><em>Contoh: Tidak selalu mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya tidak kemas seperti kadangkala ada membersihkan tempat kerja dan kadangkala tidak.</em></p>', NULL, NULL, '2024-11-18 16:05:14', '2024-11-18 16:05:14', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (981, 295, 3, '<p>Berinisiatif untuk mengemas dan membersihkan tempat kerja dan kebanyakan masa tempat kerjanya adalah kemas dan bersih.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai.</em></p>', NULL, NULL, '2024-11-18 16:05:25', '2024-11-18 16:05:25', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (982, 295, 4, '<p>Selalu mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya kemas dan selalu menolong membersihkan kawasan bahagiannya (division) dan kilang.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai serta tolong membersihkan kawasan yang lain.</em></p>', NULL, NULL, '2024-11-18 16:05:53', '2024-11-18 16:05:53', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (983, 295, 5, '<p>Selalu mengemas dan membersihkan tempat kerja dan tempat kerjanya kelihatan kemas dan bersih. Juga selalu menjaga kebersihan seluruh kawasan kilang dan dapat menegur rakan sekerja untuk menjaga kebersihan kilang.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai serta tolong menjaga kebersihan kawasan yang lain dan menegur rakan sekerja yang tidak menjaga kebersihan kilang.</em></p>', NULL, NULL, '2024-11-18 16:06:09', '2024-11-18 16:06:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (984, 296, 1, '<p>Tidak menjaga peralatan dan kemudahan syarikat.<br /><br /><em>Contoh: Tidak menjaga peralatan dan kemudahan syarikat seperti tidak menjaga forklift dan tidak pernah meletakkkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-18 16:06:30', '2024-11-18 16:06:30', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (985, 296, 2, '<p>Kadangkala bersikap cuai dalam mengendali peralatan dan kemudahan syarikat dan mengakibatkan kerosakan.<br /><br /><em>Contoh: Tidak selalu menjaga peralatan dan kemudahan syarikat dan mengakibatkan kerosakan seperti forklift terus jalan setelah enjin dihidupkan. Tidak mengambil berat tentang barang yang diangkat dan masuk ke ruang yang kecil. Selalu tidak meletakkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-18 16:06:55', '2024-11-18 16:06:55', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (986, 296, 3, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat dengan cara yang betul.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-18 16:07:05', '2024-11-18 16:07:05', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (987, 296, 4, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat demi kebaikan bersama. Selain itu, &nbsp;melaporkan kepada pihak atasan bila nampak rakan sekerja salahguna dan memberi cara penyelesaian yang bermanfaat.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna dan melapor jika ada kerosakan dan memberi cadangan untuk memperbaiki cara penggunaan dan penjagaan alatan.</em></p>', NULL, NULL, '2024-11-18 16:07:25', '2024-11-18 16:07:25', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (988, 296, 5, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat demi kebaikan bersama. Selain itu, &nbsp;melaporkan kepada pihak atasan bila nampak pekerja salahguna dan memberi cara penyelesaian yang bermanfaat. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna dan melapor jika ada kerosakan dan memberi cadangan untuk memperbaiki cara penggunaan dan penjagaan alatan.Selain itu, akan menyedarkan dan menasihati rakan sekerja yang tidak menjaga forklift semasa mengguna.</em></p>', NULL, NULL, '2024-11-18 16:07:47', '2024-11-18 16:07:47', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (989, 297, 1, '<p>Tidak mengutamakan keselamatan semasa bekerja.<br /><br /><em>Contoh: Tidak mengutamakan keselamatan semasa bekerja seperti tidak memakai PPE semasa bekerja.</em></p>', NULL, NULL, '2024-11-18 16:08:15', '2024-11-18 16:08:15', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (990, 297, 2, '<p>Ada sikap mengutamakan keselamatan tetapi kadangkala tidak.<br /><br /><em>Contoh: Ada memakai PPE semasa bekerja tetapi kadangkala tidak.</em></p>', NULL, NULL, '2024-11-18 16:08:28', '2024-11-18 16:08:51', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (991, 297, 3, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja.</em></p>', NULL, NULL, '2024-11-18 16:09:04', '2024-11-18 16:09:04', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (992, 297, 4, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan.</em></p>', NULL, NULL, '2024-11-18 16:09:14', '2024-11-18 16:09:14', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (993, 297, 5, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja dan melaporkan kepada pihak atasan serta turut memberi cara atau cara penyelesaian yang bermanfaat.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan serta turut memberi cara atau cara penyelesaian yang bermanfaat.</em></p>', NULL, NULL, '2024-11-18 16:09:23', '2024-11-18 16:09:23', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (994, 298, 1, '<p>Menerima tugasan tetapi tidak memikul tanggungjawab kerja dan tidak dapat bekerja di bawah tekanan.<br /><br /><em>Contoh: Dia terima kerja yang diberi tetapi sentiasa bersembang dengan rakan sekerja dan tidak buat kerja sehingga tidak nampak hasil kerja.</em></p>', NULL, NULL, '2024-11-18 16:10:11', '2024-11-18 16:10:11', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (995, 298, 2, '<p>Boleh menerima dan memikul tanggungjawab dan cuba untuk bekerja di bawah tekanan tetapi kadangkala tidak dapat menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Dia boleh buat kerja dan cuba elakkan diri dari tidak masuk kerja/tidak memberi alasan untuk bercuti tetapi kadangkala masih perlu dalam bimbingan.</em></p>', NULL, NULL, '2024-11-18 16:10:25', '2024-11-18 16:10:25', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (996, 298, 3, '<p>Boleh menerima dan memikul tanggungjawab dan dapat menghabiskan setiap kerja yang diamanahkan dengan baik di bawah tekanan dan melaporkan kerja yang telah dilakukan kepada pegawai atasan.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia masih menepati target dan ikut piawai kerja yang ditetapkan oleh syarikat. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia juga akan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-18 16:10:33', '2024-11-18 16:10:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (997, 298, 4, '<p>Rela menerima dan memikul tanggungjawab dan sentiasa dapat menghasilkan kerja yang berkualiti di bawah tekanan dan dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang dilakukan kepada pegawai atasan.Boleh buat kerja lebih masa sehingga kerja siap.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia akan menawarkan diri secara sukarela untuk kerja tersebut serta menepati target dan ikut piawai kerja yang ditetapkan oleh syarikat. Boleh buat kerja lebih masa sehingga kerja siap. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-18 16:10:44', '2024-11-18 16:10:44', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (998, 298, 5, '<p>Rela menerima dan memikul tanggungjawab serta tahu kepentingan dan deadline kerja. Dapat memanggil rakan sekerja untuk menyiapkan kerja bersama. Sentiasa dapat menghasilkan kerja yang berkualiti di bawah tekanan dan dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang dilakukan kepada pegawai atasan.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia tahu kepentingan dan deadline kerja tersebut serta dapat memanggil rakan sekerja untuk menyiapkan kerja bersama. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-18 16:11:16', '2024-11-18 16:11:16', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (999, 299, 1, '<p>Tidak rela mengaku kesilapan dan suka menolak tanggungjawab kepada orang lain.<br /><br /><em>Contoh: Telah melakukan kesilapan seperti tidak mengikuti spesifikasi kerja yang diberi oleh Leader / tidak tanya Leader apabila tidak faham / tanya rakan sekerja yang tidak dipertanggungjawabkan dan tidak pernah mengakui kesilapan apabila ditegur oleh Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-18 16:11:48', '2024-11-18 16:11:48', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1000, 299, 2, '<p>Kadangkala tidak rela mengaku kesilapan dan suka membuat perbandingan diri dengan orang lain dalam kesilapan yang telah dibuat.<br /><br /><em>Contoh: Telah melakukan kesilapan seperti tidak mengikuti spesifikasi kerja yang diberi oleh Leader / tidak tanya Leader apabila tidak faham / tanya rakan sekerja yang tidak dipertanggungjawabkan dan kadangkala tidak mengakui kesilapan apabila ditegur oleh Leader/Supervisor malah menyatakan Leader/Supervisor ada prasangka terhadap dia.</em></p>', NULL, NULL, '2024-11-18 16:12:03', '2024-11-18 16:12:03', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1001, 299, 3, '<p>Mengaku kesilapan dan tidak menolak tanggungjawab kepada orang lain.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan. Dia terima dan mengakui kesilapan.</em></p>', NULL, NULL, '2024-11-18 16:12:13', '2024-11-18 16:12:13', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1002, 299, 4, '<p>Tidak melarikan diri dari tanggungjawab dan terus berjumpa dengan pihak atasan untuk mengakui kesilapan dan berinisiatif untuk memperbaiki kesilapan yang telah dilakukan.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan. Dia tidak melarikan diri dari tanggungjawab dan terus berjumpa dengan Leader/Supervisor dan mengakui kesilapan. Selain itu, dia juga memberi cadangan dan sama-sama memperbaiki kesilapan yang telah dilakukan.</em></p>', NULL, NULL, '2024-11-18 16:12:22', '2024-11-18 16:12:22', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1003, 299, 5, '<p>Berani mengaku kesilapan dan tidak menolak tanggungjawab dan memastikan kesilapan tidak berlaku lagi. Berinisiatif untuk memperbetulkan kesilapan dan dapat memberi cadangan yang bermanfaat untuk mengelakkan kesilapan berlaku lagi.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan yang agak besar. Dia berani mengakui kesilapan dan terus berjumpa dengan Leader/Supervisor untuk mengakui kesilapan. Dia mengambil pengalaman tersebut sebagai satu pengajaran dan tidak mengulangi kesilapan tersebut lagi. Selain itu, dia &nbsp;memberi cadangan dan sama-sama memperbaiki kesilapan yang telah dilakukan serta memberi cadangan yang bermanfaat untuk mengelakkan kesilapan berlaku lagi.</em></p>', NULL, NULL, '2024-11-18 16:12:32', '2024-11-18 16:12:32', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1004, 300, 1, '<p>Membuat kerja alah kadar dan setakat membuat kerja sahaja dan tidak menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Tidak menunjukkan sikap ingin belajar dan tidak menumpukan perhatian semasa bekerja seperti dia boleh mengambil masa yang panjang untuk memasang beberapa nut pada mesin.</em></p>', NULL, NULL, '2024-11-18 16:13:07', '2024-11-18 16:13:07', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1005, 300, 2, '<p>Boleh membuat kerja tetapi mudah dipengaruhi orang lain dan kadangkala tidak dapat menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Dia boleh pasang nut pada mesin tetapi mudah dipengaruhi oleh rakan sekerja yang lain seperti dia akan melambatkan proses kerjanya dan sambil kerja sambil bersembang apabila ada rakan sekerja yang bersembang dengannya semasa bekerja.</em></p>', NULL, NULL, '2024-11-18 16:13:16', '2024-11-18 16:13:16', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1006, 300, 3, '<p>Lebih agresif dan sikap kerja juga serius dan dapat menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak mengangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja.</em></p>', NULL, NULL, '2024-11-18 16:13:25', '2024-11-18 16:13:25', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1007, 300, 4, '<p>Bersemangat kerja dan menumpukan perhatian sepenuhnya dalam kerja. Sentiasa mengutamakan kualiti kerja dan menghasilkan kerja yang halus dan teliti dan tidak melakukan kesilapan.<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak menggangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja. Dia sentiasa mengutamakan kualiti kerja dan memastikan nut yang dipasang itu betul dan kemas.</em></p>', NULL, NULL, '2024-11-18 16:13:35', '2024-11-18 16:13:35', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1008, 300, 5, '<p>Matlamat untuk berjaya sangat jelas. Menumpukan perhatian sepenuhnya dalam kerja. Sentiasa mengutamakan kualiti kerja dan menghasilkan kerja yang halus dan teliti dan tidak melakukan kesilapan. Selain itu turut memberi cadangan dan cara kerja untuk memastikan kerja berkualiti dihasilkan setiap kali.&nbsp;<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak menggangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja. Dia sentiasa mengutamakan kualiti kerja dan memastikan nut yang dipasang itu betul dan kemas. Selain itu, dia juga akan memberi cadangan untuk memastikan kerja berkualiti dapat dihasilkan.</em></p>', NULL, NULL, '2024-11-18 16:13:46', '2024-11-18 16:13:46', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1009, 301, 1, '<p>Langsung tidak mahu memahami dan menerima peraturan dan polisi syarikat dan sentiasa membuat aduan terhadap dasar syarikat.<br /><br /><em>Contoh: Selalu tidak menutup lampu setelah mengguna tandas dan membuat aduan apabila pihak syarikat mengambil tindakan.</em></p>', NULL, NULL, '2024-11-18 16:14:33', '2024-11-18 16:14:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1010, 301, 2, '<p>Kadangkala sahaja mahu menerima dan mematuhi peraturan dan polisi syarikat.<br /><br /><em>Contoh: Kadangkala ada menutup lampu setelah mengguna tandas kadangkala tidak.</em></p>', NULL, NULL, '2024-11-18 16:14:42', '2024-11-18 16:14:42', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1011, 301, 3, '<p>Menerima dan mematuhi setiap peraturan dan polisi syarikat.<br /><br /><em>Contoh: Setiap kali akan menutup lampu setelah mengguna tandas.</em></p>', NULL, NULL, '2024-11-18 16:14:53', '2024-11-18 16:14:53', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1012, 301, 4, '<p>Tidak melanggar peraturan dan sentiasa dapat menasihatkan rakan sekerja untuk menerima dan mematuhi peraturan dan polisi syarikat untuk kebaikan bersama.<br /><br /><em>Contoh: Sentiasa menutup lampu setelah mengguna tandas dan &nbsp;menasihati dan menerang kepada rakan sekerja yang tidak mematuhi peraturan.</em></p>', NULL, NULL, '2024-11-18 16:15:13', '2024-11-18 16:15:13', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1013, 301, 5, '<p>Memahami dan menerima setiap peraturan dan polisi syarikat dan sentiasa menasihatkan rakan sekerja yang melanggar peraturan serta melaporkan masalah disiplin kepada pegawai atasan untuk kebaikan bersama.<br /><br /><em>Contoh: &nbsp;Sentiasa menutup lampu setelah mengguna tandas dan &nbsp;menasihati dan menerang kepada rakan sekerja yang tidak mematuhi peraturan. Selain itu, juga akan melaporkan nama pekerja yang tidak menutup lampu setelah mengguna tandas.</em></p>', NULL, NULL, '2024-11-18 16:15:22', '2024-11-18 16:15:22', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1014, 302, 1, '<p>Selalu tidak tepat masuk kerja dan menunjukkan kedatangan yang tidak baik.<br /><br /><em>Contoh: Masih berada di tempat berehat semasa siren berbunyi dan jalan perlahan ke tempat kerja.</em></p>', NULL, NULL, '2024-11-18 16:15:46', '2024-11-18 16:15:46', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1015, 302, 2, '<p>Kadangkala ada masuk kerja pada masa yang ditetapkan tetapi keadaan tidak ketara.<br /><br /><em>Contoh: Kadangkala ada tepat masuk kerja semasa siren berbunyi tetapi kebanyakan masa tidak masuk kerja pada masa yang tepat.</em></p>', NULL, NULL, '2024-11-18 16:15:57', '2024-11-18 16:15:57', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1016, 302, 3, '<p>Kebanyakan masa masuk kerja pada masa yang ditetapkan tetapi kadangkala ada lewat juga.<br /><br /><em>Contoh: Kebanyakan masa masuk kerja semasa siren berbunyi tetapi sekali kala masih lewat masuk kerja.</em></p>', NULL, NULL, '2024-11-18 16:16:06', '2024-11-18 16:16:06', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1017, 302, 4, '<p>Mementingkan ketepatan masa masuk kerja dan masuk kerja tepat pada masa atau lebih awal.<br /><br /><em>Contoh: Sentiasa masa masuk kerja sebelum siren berbunyi atau lebih awal.</em></p>', NULL, NULL, '2024-11-18 16:16:16', '2024-11-18 16:16:16', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1018, 302, 5, '<p>Mementingkan ketepatan masa masuk kerja dan masuk kerja tepat pada masa atau lebih awal serta memberi nasihat kepada rakan sekerja yang lewat.<br /><br /><em>Contoh: Sentiasa masa masuk kerja sebelum siren berbunyi atau lebih awal serta memberi nasihat kepada rakan sekerja yang lewat.</em></p>', NULL, NULL, '2024-11-18 16:16:28', '2024-11-18 16:16:28', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1019, 303, 1, '<p>Disiplin diri yang tidak memuaskan dan sering meninggalkan tempat kerja dengan berkeliaran tanpa tujuan dan sering membazirkan masa serta curi tulang.<br /><br /><em>Contoh: Sering meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja (banyak kali sehari) dan mengambil masa yang panjang dalam tandas serta membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-18 16:17:26', '2024-11-18 16:17:26', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1020, 303, 2, '<p>Kadangkala membazirkan masa dan curi tulang serta meninggalkan tempat kerja dengan berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Kadangkala meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja (banyak kali sehari) dan mengambil masa yang panjang dalam tandas serta membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-18 16:17:35', '2024-11-18 16:17:35', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1021, 303, 3, '<p>Tidak membazirkan masa dan ringan tulang serta menumpukan perhatian semasa bekerja. Tidak meninggalkan tempat kerja dengan berkeliaran tanpa tujuan.<br /><br /><em>Contoh: Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-18 16:17:48', '2024-11-18 16:17:48', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1022, 303, 4, '<p>Teladan yang baik dan tumpuan perhatian sepenuhnya semasa bekerja. Tidak berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Seorang teladan yang baik dan memberi tumpuan sepenuhnya semasa bekerja. Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-18 16:18:00', '2024-11-18 16:18:00', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1023, 303, 5, '<p>Teladan yang baik dan tumpuan perhatian sepenuhnya semasa bekerja dan juga selalu memberi nasihat kepada rakan sekerja supaya melahirkan keadaan kerja yang lebih agresif. Tidak berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Seorang teladan yang baik dan memberi tumpuan sepenuhnya semasa bekerja. Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja. Selalu memberi nasihat kepada rakan sekerja yang selalu pergi ke tandas sebagai alasan.</em></p>', NULL, NULL, '2024-11-18 16:18:14', '2024-11-18 16:18:14', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1024, 304, 1, '<p>Tidak pernah berada di tempat kerja semasa pembersihan kawasan dijalankan.<br /><br /><em>Contoh: Tidak berada di tempat kerja dan pergi ke tandas semasa pembersihan kawasan dijalankan.</em></p>', NULL, NULL, '2024-11-18 16:18:51', '2024-11-18 16:18:51', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1025, 304, 2, '<p>Memulakan kerja pembersihan kawasan walaupun masa yang ditetapkan belum sampai lagi.<br /><br /><em>Contoh: Memulakan kerja pembersihan kawasan walaupun masa yang ditetapkan belum sampai lagi dan rakan sekerja yang lain masih bekerja lagi.</em></p>', NULL, NULL, '2024-11-18 16:19:01', '2024-11-18 16:19:01', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1026, 304, 3, '<p>Kebanyakan masa membersihkan kawasan production pada masa yang ditetapkan.</p><p>Kadangkala membersihkan kawasan production pada masa yang ditetapkan tetapi keadaan tidak ketara.</p><p><br />\nContoh: Kadangkala ada berada di production semasa pembersihan kawasan dijalankan tetapi kebanyakan masa tidak nampak orang.</p>', NULL, NULL, '2024-11-18 16:19:11', '2024-11-18 16:19:11', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1027, 304, 4, '<p>Sentiasa mengutamakan dan membersihkan kawasan production pada masa yang ditetapkan.<br /><br /><em>Contoh: Sentiasa membersihkan kawasan production pada masa yang ditetapkan.</em></p>', NULL, NULL, '2024-11-18 16:19:21', '2024-11-18 16:19:21', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1028, 304, 5, '<p>Mengutamakan dan membersihkan kawasan production pada masa yang ditetapkan serta memberi nasihat kepada rakan sekerja yang tidak berbuat demikian.<br /><br /><em>Contoh: Sentiasa membersihkan kawasan production pada masa yang ditetapkan dan memberi nasihat kepada rakan sekerja yang tidak berbuat demikian.</em></p>', NULL, NULL, '2024-11-18 16:19:31', '2024-11-18 16:19:31', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1029, 305, 1, '<p>Hanya menghormati pegawai atasan dan tidak bersopan dengan rakan sekerja.<br /><br /><em>Contoh: Hanya menghormati Leader/Supervisor atau pangkat kerja yang lebih tinggi tetapi tidak bersopan dengan rakan sekerja yang berpangkat rendah/masih baru.</em></p>', NULL, NULL, '2024-11-18 16:20:42', '2024-11-18 16:20:42', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1030, 305, 2, '<p>Biasanya akan bersopan dan menghormati orang lain tetapi kadangkala beremosi.<br /><br /><em>Contoh: Biasanya bersopan dan menghormati rakan sekerja yang lain tetapi kadangkala beremosi dan lawan cakap.</em></p>', NULL, NULL, '2024-11-18 16:25:10', '2024-11-18 16:25:10', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1031, 305, 3, '<p>Sering bersopan dan menghormati orang lain dan tidak bertindak mengikut perasaan.<br /><br /><em>Contoh: Sering bersopan dan menghormati rakan sekerja lain dan tidak bertindak mengikut perasaan.</em></p>', NULL, NULL, '2024-11-18 16:25:27', '2024-11-18 16:25:27', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1032, 305, 4, '<p>Bersopan dan menghormati orang lain pada setiap masa dan tidak bertindak mengikut perasaan dan berbahasa sopan.<br /><br /><em>Contoh: Bersopan dan setiap masa menghormati rakan sekerja yang lain dan tidak bertindak mengikut perasaan dan berbahasa sopan serta jaga perasaan rakan lain.</em></p>', NULL, NULL, '2024-11-18 16:25:38', '2024-11-18 16:25:38', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1033, 305, 5, '<p>Bersopan dan menghormati orang lain pada setiap masa dan masih bercakap dengan sopan walaupun sendiri telah dipersalahkan dalam proses penyelesaian masalah.<br /><br /><em>Contoh: Bersopan dan setiap masa menghormati rakan sekerja yang lain dan masih bercakap dengan sopan walaupun sendiri telah dipersalahkan dalam proses penyelesaian masalah.</em></p>', NULL, NULL, '2024-11-18 16:25:52', '2024-11-18 16:25:52', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1034, 306, 1, '<p>Memang mengetahui arahan yang diberi mempunyai kesilapan tetapi tidak mendapatkan kepastian kerana berpendapat itu adalah tanggungjawab pegawai atasan.<br /><br /><em>Contoh: Tidak mendapatkan kepastian daripada Leader/Supervisor tentang spesifikasi kerja yang diberi walaupun sudah tahu arahan yang diberi mempunyai kesilapan/tidak jelas dan beranggap itu adalah tanggungjawab Leader/Supervisor dan bukan dia.</em></p>', NULL, NULL, '2024-11-18 17:42:51', '2024-11-18 17:42:51', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1035, 306, 2, '<p>Jarang berinisiatif untuk mendapatkan kepastian daripada pegawai atasan walaupun arahan yang diberi tidak jelas atau silap.<br /><br /><em>Contoh: Menunjukkan sikap sudah tahu tetapi tidak ingin peduli dan tidak mendapatkan kepastian daripada Leader/Supervisor walapun arahan yang diberi ada kesilapan/kurang jelas.</em></p>', NULL, NULL, '2024-11-18 17:43:01', '2024-11-18 17:43:01', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1036, 306, 3, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap tetapi tidak pernah melapor balik kepada pegawai atasan tentang tugasan tersebut.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi ada kesilapan/tidak jelas tetapi tidak pernah melapor balik tugasan tersebut.</em></p>', NULL, NULL, '2024-11-18 17:43:10', '2024-11-18 17:43:10', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1037, 306, 4, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi tidak jelas/silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut.</em></p>', NULL, NULL, '2024-11-18 17:43:19', '2024-11-18 17:43:19', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1038, 306, 5, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut serta memberi pendapat yang bermanfaat.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi tidak jelas/silap dan selalu melapor balik kepada Leader/Supervisor dan turut mengambil bahagian untuk memberi pendapat yang bermanfaat.</em></p>', NULL, NULL, '2024-11-18 17:43:32', '2024-11-18 17:43:32', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1039, 307, 1, '<p>Degil dan berpegang teguh dengan pendapat sendiri dan tidak menuruti arahan pegawai atasan.<br /><br /><em>Contoh: Tidak menerima dan melawan percakapan Leader/Supervisor semasa diberi tugasan.</em></p>', NULL, NULL, '2024-11-18 17:46:34', '2024-11-18 17:46:34', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1040, 307, 2, '<p>Kebanyakan masa akan menuruti arahan pegawai atasan tetapi kadangkala akan beremosi dan meluahkan ketidakpuasan.<br /><br /><em>Contoh: Kebanyakan masa akan menerima tugasan Leader/Supervisor dengan baik tetapi kadangkala tidak.</em></p>', NULL, NULL, '2024-11-18 17:46:46', '2024-11-18 17:46:46', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1041, 307, 3, '<p>Mengambil berat dan menuruti arahan pegawai atasan dan tidak pernah membuat hal sesuka hati.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati dan akan bertanya jika tidak faham.</em></p>', NULL, NULL, '2024-11-18 17:47:03', '2024-11-18 17:47:03', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1042, 307, 4, '<p>Mengambil berat dan menuruti arahan pegawai atasan dan tidak pernah membuat hal sesuka hati. Kadangkala turut memberikan pendapat yang bermanfaat dalan kerja yang diberi.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati dan akan bertanya jika tidak faham. Kadangkala turut memberi cadangan/pandangan dalam kerja yang diberi.</em></p>', NULL, NULL, '2024-11-18 17:47:14', '2024-11-18 17:47:14', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1043, 307, 5, '<p>Bersikap positif dan menuruti semua arahan pegawai atasan, tidak membuat hal malah dapat menyampaikan objektif dan kehendak arahan secara positif kepada semua rakan sekerja.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati. Turut menyampaikan maksud dan kehendak mengikuti arahan Leader/Supervisor secara positif kepada rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-18 17:47:27', '2024-11-18 17:47:27', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1044, 308, 1, '<p>Ego dan tidak sudi berbincang tugasan sesama rakan sekerja dan pegawai atasan, sangat keras kepala dan tidak dapat menerima cadangan orang lain.<br /><br /><em>Contoh: Buat kerja tanpa ikut pelan kerja seperti menebuk drill pada kelajuan yang tinggi dan telah membesarkan lubang 3mm kepada 3.20 mm. Dia tidak dapat menerima apabila diminta buat semula pada kelajuan drill yang rendah.</em></p>', NULL, NULL, '2024-11-18 17:48:54', '2024-11-18 17:48:54', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1045, 308, 2, '<p>Jarang berbincang tugasan sesama rakan sekerja dan pegawai atasan dan tidak begitu rela berkongsi maklumat, kadangkala keras kepala dan tidak dapat menerima cadangan orang lain.<br /><br /><em>Contoh: Dia menunjukkan sikap yang tidak begitu gembira apabila diminta buat semula pada kelajuan drill yang rendah.</em></p>', NULL, NULL, '2024-11-18 17:49:05', '2024-11-18 17:49:05', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1046, 308, 3, '<p>Sudi berbincang dan menerima cadangan rakan sekerja dan pegawai atasan, dapat memberi pertolongan apabila diminta.<br /><br /><em>Contoh: Dia sudi membuat semula pada kelajuan drill yang rendah setelah berbincang dan diminta berubah.</em></p>', NULL, NULL, '2024-11-18 17:49:15', '2024-11-18 17:49:15', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1047, 308, 4, '<p>Sudi berbincang dan berinisiatif memberi pertolongan sesama rakan sekerja dan pegawai atasan dengan tidak berkira kerja. Boleh menerima cadangan orang lain dan tidak berkeras kepala.<br /><br /><em>Contoh: Dia sudi membuat semula pada kelajuan drill yang rendah dan dia turut memberi cadangan untuk mengatasi masalah tersebut.</em></p>', NULL, NULL, '2024-11-18 17:49:25', '2024-11-18 17:49:25', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1048, 308, 5, '<p>Sudi berbincang dan berinisiatif memberi pertolongan sesama rakan sekerja dan pegawai atasan dengan tidak berkira kerja. Boleh menerima cadangan orang lain dan tidak berkeras kepala. Selain itu, turut boleh memanggil rakan sekerja untuk sama-sama menyiapkan kerja tersebut.<br /><br /><em>Contoh: Dia ialah orang yang sangat agresif dan sudi membuat semula dan dia turut boleh meminta rakan sekerja untuk sama-sama menyiapkan kerja.</em></p>', NULL, NULL, '2024-11-18 17:49:36', '2024-11-18 17:49:36', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1049, 309, 1, '<p>Menolak tugasan selain dari bidang sendiri dan langsung tidak dapat menerima tugasan tambahan atau di luar bidang kerja, amat mementingkan diri sendiri.<br /><br /><em>Contoh: Tidak mahu backup rakan sekerja yang bercuti dan selalu dipengaruhi oleh rakan sekerja yang lain dimana orang yang berbuat banyak tidak dapat apa-apa.</em></p>', NULL, NULL, '2024-11-18 17:50:13', '2024-11-18 17:50:13', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1050, 309, 2, '<p>Kadangkala menerima tugasan tambahan atau di luar bidang kerja tetapi dengan hati yang tidak rela dan mementingkan kepentingan diri sendiri.<br /><br /><em>Contoh: Kadangkala akan diminta untuk backup rakan sekerja yang bercuti tetapi dia akan membuat kerja secara tidak rela / memberi alasan bahawa dia tidak tahu buat kerja tersebut.</em></p>', NULL, NULL, '2024-11-18 17:50:26', '2024-11-18 17:50:26', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1051, 309, 3, '<p>Rela menerima tugasan tambahan atau di luar bidang dan tidak menolak apabila tugas diberi.<br /><br /><em>Contoh: Rela backup rakan sekerja yang bercuti dan tidak menolak apabila tugas diberi oleh Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-18 17:50:58', '2024-11-18 17:50:58', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1052, 309, 4, '<p>Rela menerima tugasan tambahan atau di luar bidang dan tidak menolak apabila tugas diberi serta cuba mencari cara untuk menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Rela backup rakan sekerja yang bercuti dan tidak menolak apabila tugas diberi oleh Leader / Supervisor. Selain itu, dia juga cari jalan untuk mengeluarkan hasil kerja yang baik / membuat kerja tersebut dengan bersungguh-sungguh.</em></p>', NULL, NULL, '2024-11-18 17:51:11', '2024-11-18 17:51:11', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1053, 309, 5, '<p>Amat rela menerima tugasan tambahan atau di luar bidang dan menerimanya sebagai satu cabaran. Berusaha dan bertanggungjawab sepenuhnya sehingga tugasan selesai dengan sempurna.<br /><br /><em>Contoh: Sangat rela backup rakan sekerja yang bercuti dan menganggap tugas yang diberi tersebut sebagai satu cabaran / tugas sendiri. Dia membuat kerja dengan sepenuh hati dan mengambil tanggungjawab sehingga tugasan tersebut selesai dengan sempurnanya.</em></p>', NULL, NULL, '2024-11-18 17:52:27', '2024-11-18 17:52:27', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1164, 356, 1, '<p>Tidak dapat menyiapkan tugasan mengikut masa yang ditetapkan dan selalu dibuat semula oleh rakan sekerja yang lain dan menyebabkan kelewatan.<br /><br /><em>Contoh: Kerja yang sepatutnya boleh disiapkan dalam sehari tetapi dia selalu tidak hadir bekerja dan kerjanya perlu disambung / dibuat semula oleh rakan sekerja yang lain dan menyebabkan kelewatan.</em></p>', NULL, NULL, '2024-11-20 12:52:15', '2024-11-20 12:52:15', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1165, 356, 2, '<p>Selalu mengambil masa yang panjang untuk menyiapkan kerja walaupun bimbingan sudah diberi.<br /><br /><em>Contoh: Kerja yang sepatutnya boleh disiapkan dalam sehari tetapi dia mengambil masa yang panjang walaupun bimbingan sudah diberi.</em></p>', NULL, NULL, '2024-11-20 12:52:25', '2024-11-20 12:52:25', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1166, 356, 3, '<p>Tugasan biasanya dapat disiapkan dengan sedikit bimbingan dan siap dalam masa yang ditetapkan mahupun lebih awal dan hasil kerja yang masih boleh diterima.<br /><br /><em>Contoh: Boleh menghasilkan kerja dalam masa yang ditetapkan tetapi masih perlu dalam pengawasan/bimbingan.</em></p>', NULL, NULL, '2024-11-20 12:52:34', '2024-11-20 12:52:34', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1167, 356, 4, '<p>Tugasan sentiasa disiapkan tanpa bimbingan dan mengikut jadual mahupun lebih awal dan hasil kerja yang agar memuaskan.<br /><br /><em>Contoh: Boleh menghasilkan kerja dalam masa yang pendek dan tanpa sebarang pengawasan/bimbingan seperti dia cuma perlu 5 jam untuk menghasilkan kerja yang dijangka siap dalam sehari dan dia boleh menghasilkan lebih dalam satu hari.</em></p>', NULL, NULL, '2024-11-20 12:52:44', '2024-11-20 12:52:44', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1168, 356, 5, '<p>Mengutamakan masa dan pantas dalam menyiapkan tugasan yang diberi dan hasil kerja sangat bagus dan boleh diharapkan.<br /><br /><em>Contoh:Boleh membuat apa kerja yang dirancang dan menepati masa yang ditetapkan atau lebih awal tanpa pengawasan/bimbingan. Individu yang teliti dan prihatin dan menguasa masa dan memberi hasil kerja yang sangat bagus dan halus.</em></p>', NULL, NULL, '2024-11-20 12:52:54', '2024-11-20 12:52:54', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1169, 357, 1, '<p>Suka menolak tanggungjawab kerja dan berpura-pura/berdiam diri walaupun tahu apa cara untuk membuat kerja/menyelesaikan masalah.<br /><br /><em>Contoh: Langsung tidak bergerak dan pakai duduk dan tunggu sahaja walaupun sudah diberi penjelasan dalam pelan kerja.</em></p>', NULL, NULL, '2024-11-20 12:53:22', '2024-11-20 12:53:22', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1170, 357, 2, '<p>Kadangkala menolak tanggungjawab kerja dan berpura-pura/berdiam diri walaupun tahu apa cara untuk membuat kerja/menyelesaikan masalah.<br /><br /><em>Contoh: Tidak berusaha untuk belajar dan memahami pembacaan pelan kerja dan ukuran serta memerlukan seseorang mengawasi di tepi dan selalu memberi penjelasan boleh baru dapat menghasilkan kerja yang ditugaskan.</em></p>', NULL, NULL, '2024-11-20 12:53:43', '2024-11-20 12:53:43', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1171, 357, 3, '<p>Sudah faham dan boleh terus bertindak/bergerak ke atas kerja yang telah diselesaikan.&nbsp;<br /><br /><em>Contoh: Sudah tahu membuat kerja/menyelesaikan masalah dan tidak menolak tanggungjawab.</em></p>', NULL, NULL, '2024-11-20 12:53:53', '2024-11-20 12:53:53', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1172, 357, 4, '<p>Sudah faham dan boleh bertindak cepat ke atas semua tugasan serta tidak perlu pengawasan/bimbingan dan akan lapor balik apabila kerja telah siap.<br /><br /><em>Contoh: Bertanggungjawab dan tidak berpura-pura atau berdiam diri dalam membuat kerja/menyelesaikan masalah dan tidak perlu pengawasan/bimbingan dan akan bertindak/bergerak ke atas kerja yang ditugaskan serta lapor balik apabila kerja telah siap.</em></p>', NULL, NULL, '2024-11-20 12:54:04', '2024-11-20 12:54:04', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1173, 357, 5, '<p>Sudah faham dan boleh bertindak cepat ke atas semua tugasan serta tidak perlu pengawasan/bimbingan dan akan lapor balik apabila kerja telah siap. Selain itu, dapat memberi nasihat kepada rakan sekerja yang lain supaya cepat bertindak dalam kerja.<br /><br /><em>Contoh: Bertanggungjawab dan tidak berpura-pura atau berdiam diri dalam membuat kerja/menyelesaikan masalah dan tidak perlu pengawasan/bimbingan dan akan bertindak/bergerak ke atas kerja yang ditugaskan serta lapor balik apabila kerja telah siap. Selain itu, juga memotivasikan rakan sekerja supaya tidak berpura-pura/berdiam diri dalam &nbsp;membuat kerja/menyelesaikan masalah.</em></p>', NULL, NULL, '2024-11-20 12:54:13', '2024-11-20 12:54:13', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1174, 358, 2, '<p>Cuai dan mengakibatkan kesilapan kerja.<br /><br /><em>Contoh: Kadangkala cuai semasa bekerja dan mengakibatkan kesilapan kerja kerana tindakan yang lambat untuk berubah setelah diberi bimbingan/teguran.</em></p>', NULL, NULL, '2024-11-20 12:55:03', '2024-11-20 16:44:39', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1175, 358, 1, '<p>Hasil kerja yang tidak boleh diterima dan selalu membuat kesilapan.<br /><br /><em>Contoh: Tidak menumpu perhatian semasa bekerja dan selalu membuat kesilapan yang sama. Tidak pernah berubah walaupun &nbsp;sudah diberi bimbingan/teguran seperti selalu mengulangi kesilapan yang sama walaupun sudah banyak kali memasang mesin yang sama model.</em></p>', NULL, NULL, '2024-11-20 16:40:04', '2024-11-20 16:44:18', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1176, 358, 3, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan meminimumkan tahap kesilapan kepada yang terendah.<br /><br /><em>Contoh: Kadangkala ada membuat kesilapan tetapi mengambil tindakan yang cepat untuk berubah setelah diberi bimbingan/teguran.</em></p>', NULL, NULL, '2024-11-20 16:41:03', '2024-11-20 16:44:53', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1177, 358, 4, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan apa-apa kesilapan dalam kerja harian.<br /><br /><em>Contoh: Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan. Selain itu, juga berinisiatif untuk menjaga barangan/bahan dan tidak membazir.</em></p>', NULL, NULL, '2024-11-20 16:41:14', '2024-11-20 16:45:11', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1178, 358, 5, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan kerja dan berinisiatif untuk memberi pendapat dan memperbaiki cara kerja yang lebih baik untuk meminimumkan tahap kesilapan kerja.<br /><br /><em>Contoh: Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan dan berinisiatif untuk memberi pendapat dan memperbaiki cara kerja untuk meminimumkan tahap kesilapan kerja seperti berinisiatif untuk mengetahui masalah semasa pemasangan mesin dan turut memberi pendapat untuk memperbaiki cara kerja/menyelesaikan masalah.</em></p>', NULL, NULL, '2024-11-20 16:41:24', '2024-11-20 16:45:45', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1179, 359, 1, '<p>Tidak membuat kerja secara sistematik dan tidak tahu membezakan kepentingan kerja.<br /><br /><em>Contoh: Tidak tahu membezakan kepentingan kerja dan tidak buat perancangan kerja.</em></p>', NULL, NULL, '2024-11-20 16:42:49', '2024-11-20 16:42:49', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1180, 359, 2, '<p>Kadangkala ada membuat kerja secara sistematik dan kadangkala tahu membezakan kepentingan kerja tetapi keadaan tidak ketara.<br /><br /><em>Contoh: Kadangkala tahu membezakan kepentingan kerja dan buat perancangan kerja tetapi tidak selalu dan ikut mood sendiri.</em></p>', NULL, NULL, '2024-11-20 16:42:58', '2024-11-20 16:42:58', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1181, 359, 3, '<p>Tidak perlu seseorang mengawasi di tepi dan tahu membuat kerja secara sistematik dan tahu membezakan kepentingan kerja dengan penjelasan yang ringkas sahaja.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan memerlukan penjelasan kerja yang ringkas sahaja.</em></p>', NULL, NULL, '2024-11-20 16:43:08', '2024-11-20 16:43:08', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1182, 359, 4, '<p>Hanya memerlukan penjelasan yang ringkas dan tahu membuat kerja secara sistematik dan tahu membezakan kepentingan kerja. Berhati-hati dan tiada kesilapan dalam kerja yang dihasilkan.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan hanya memerlukan penjelasan kerja yang ringkas sahaja dan memberi tumpuan dalam kerja dan mengeluarkan hasil kerja yang baik.</em></p>', NULL, NULL, '2024-11-20 16:43:19', '2024-11-20 16:43:19', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1183, 359, 5, '<p>Hanya memerlukan penjelasan yang sangat ringkas sahaja untuk membuat kerja secara sistematik dan tahu membezakan kepentingan kerja dan dapat memberi tunjuk ajar kepada rakan sekerja.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan hanya memerlukan penjelasan kerja yang ringkas sahaja dan memberi tumpuan dalam kerja dan mengeluarkan hasil kerja yang baik dan turut memberi tunjuk ajar kepada rakan sekerja.</em></p>', NULL, NULL, '2024-11-20 16:43:34', '2024-11-20 16:43:34', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1184, 360, 1, '<p>Langsung tidak memahami permintaan kualiti kerja dan tidak memberi perhatian kepada kerja yang dilakukan.<br /><br /><em>Contoh: Langsung tidak memahami permintaan kualiti kerja dan tidak memberi perhatian terhadap semua kerja yang dilakukan seperti membuat pemasangan Control Panel tetapi langsung tidak mengikut diagram yang diberi.</em></p>', NULL, NULL, '2024-11-20 16:46:34', '2024-11-20 16:46:34', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1185, 360, 2, '<p>Kadangkala tidak faham spesifikasi kerja yang diberi dan tidak berinisiatif mengambil langkah untuk mengetahui untuk menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Tidak berinisiatif untuk bertanya/kurang bertanya apabila tidak tahu semasa memasang Control Panel dan pasang ikut sendiri dan tidak ikut cara kerja yang betul.</em></p>', NULL, NULL, '2024-11-20 16:46:45', '2024-11-20 16:46:45', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1186, 360, 3, '<p>Memahami permintaan kualiti kerja dan dapat menghasilkan kerja yang berkualiti secara individu tanpa pengawasan pegawai atasan tetapi tidak mengambil perhatian dan abaikan kerja yang remeh temeh serta tidak mengambil perhatian terhadap kekemasan hasil kerja.<br /><br /><em>Contoh: Tahu pasang Control Panel tetapi tidak terfikir tentang kekemasan. Wayar sudah ditarik dengan betul tetapi tidak diikat dengan cable tie/tidak tersusun/tidak label semasa membuat pemasangan.</em></p>', NULL, NULL, '2024-11-20 16:46:59', '2024-11-20 16:46:59', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1187, 360, 4, '<p>Faham tentang kualiti dan dapat menghasilkan kerja yang berkualiti dan memenuhi kehendak syarikat dan dapat memastikan kerja yang dihasilkan tidak bermasalah.<br /><br /><em>Contoh: Faham tentang kualiti kerja dan ikut semua spesifikasi yang diminta. Boleh berfikir dan nampak (meramalkan) ke hadapan dan memastikan kerja yang dihasilkan tidak bermasalah seperti tahu pasang Control Panel dan semua litar boleh berfungsi dengan baik dan pemasangan yang kemas dan melaporkan keadaan kepada Leader/Supervisor apabila litar tidak berfungsi/bernyala.</em></p>', NULL, NULL, '2024-11-20 16:47:11', '2024-11-20 16:47:11', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1188, 360, 5, '<p>Sangat faham tentang kualiti kerja dan dapat menghasilkan kerja yang berkualiti dan memenuhi kehendak syarikat dan dapat memastikan kerja yang dihasilkan tidak bermasalah serta turut memberi tunjuk ajar kepada rakan kerja yang lain.&nbsp;<br /><br /><em>Contoh: Sangat faham tentang kualiti kerja dan ikut semua spesifikasi yang diminta. Boleh berfikir dan nampak (meramalkan) ke hadapan dan memastikan kerja yang dihasilkan tidak bermasalah. Selain itu, juga dapat memberi tunjuk ajar kepada rakan sekerja yang lain seperti tahu pasang Control Panel dan semua litar boleh berfungsi dengan baik dan pemasangan yang kemas dan melaporkan keadaan kepada Leader/Supervisor apabila litar tidak berfungsi/bernyala. Selain itu, dia juga memberi tunjuk ajar kepada rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-20 16:47:25', '2024-11-20 16:47:25', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1189, 361, 1, '<p>Sentiasa membazirkan/merosakkan sumber syarikat.<br /><br /><em>Contoh: Tidak pernah berhati-hati dalam spesifikasi kerja yang diberi dan sentiasa mengakibatkan pembaziran bahan.</em></p>', NULL, NULL, '2024-11-20 16:48:11', '2024-11-20 16:48:11', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1190, 361, 2, '<p>Ada bersikap mahu menjimatkan sumber syarikat tetapi kadangkala menyebabkan pembaziran di atas kecuaiannya.<br /><br /><em>Contoh: Cuai dalam pembacaan spesifikasi kerja yang diberi dan silap ambil bahan dan menyebabkan kesilapan dan membazirkan bahan serta perlu &ldquo;rework&rdquo;.</em></p>', NULL, NULL, '2024-11-20 16:48:22', '2024-11-20 16:48:22', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1191, 361, 3, '<p>Berhati-hati semasa bekerja dan menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dan memastikan betul supaya tidak berlaku kesilapan yang mengakibatkan pembaziran bahan dan buang masa.</em></p>', NULL, NULL, '2024-11-20 16:48:40', '2024-11-20 16:48:40', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1192, 361, 4, '<p>Berhati-hati semasa bekerja dan berinisiatif menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya. Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dengan pelan kerja dan memastikan semua barang yang ambil adalah betul. Ada pemikiran tidak membazir seperti dalam menghasilkan sesuatu barang yang sangat kecil, dia akan cari scrap dahulu dan tidak guna bahan yang baru atau bahan yang besar.Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan.</em></p>', NULL, NULL, '2024-11-20 16:48:51', '2024-11-20 16:48:51', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1193, 361, 5, '<p>Berhati-hati semasa bekerja dan berinisiatif menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya. Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan dan juga menyedarkan dan membetulkan kesilapan rakan sekerja yang lain.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dengan pelan kerja dan memastikan semua barang yang ambil adalah betul. Ada pemikiran tidak membazir seperti dalam menghasilkan sesuatu barang yang sangat kecil, dia akan cari scrap dahulu dan tidak guna bahan yang baru atau bahan yang besar.Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan dan menyedarkan dan membetulkan kesilapan rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-20 16:49:02', '2024-11-20 16:49:02', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1194, 362, 1, '<p>Pengetahuan atau kemahiran adalah terhad dan tidak dapat menyelesaikan tugasan dan menggunakan masa yang panjang untuk mempelajari pengetahuan dan cara kerja yang agak senang.<br /><br /><em>Contoh: Tidak ada pengetahuan dan kemahiran kerja dan menggunakan masa yang panjang untuk mempelajari cara kerja yang senang walaupun bimbingan telah diberi seperti membuat kerja kimpalan yang paling senang iaitu mengimpal besi dalam kedudukan rata.</em></p>', NULL, NULL, '2024-11-20 16:50:03', '2024-11-20 16:50:03', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1195, 362, 2, '<p>Kurang pengetahuan atau kemahiran yang cukup untuk mengendalikan tugasan.<br /><br /><em>Contoh: Hasil kimpalan yang teruk dan bimbingan masih diperlukan walaupun diminta menghasilkan kerja kimpalan yang agak senang seperti mengimpal besi dalam kedudukan rata dan mendatar.</em></p>', NULL, NULL, '2024-11-20 16:50:13', '2024-11-20 16:50:13', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1196, 362, 3, '<p>Mempunyai pengetahuan dan kemahiran untuk mengendalikan tugasan dan mempunyai sikap mahu belajar dan mempelajari pengetahuan kerja yang baru dalam masa yang singkat dan mengimplikasikan dalam kerja harian.<br /><br /><em>Contoh: Ada pengetahuan dan kemahiran kimpalan tetapi tidak dapat meneruskan kerja apabila menghadapi kerja yang tidak biasa dan memerlukan bimbingan seperti: boleh mengimpal besi yang nipis tetapi tidak apabila diminta mengimpal besi yang lagi nipis / boleh mengimpal dalam kedudukan rata, mendatar dan menegak tetapi tidak apabila dalam keadaan overhead atau dalam keadaan 45 darjah.</em></p>', NULL, NULL, '2024-11-20 16:50:25', '2024-11-20 16:50:25', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1197, 362, 4, '<p>Boleh menguasai pengetahuan dan kemahiran untuk mengendalikan tugasan dan pencapaian yang agak memuaskan dan dapat menggunakan pengetahuannya untuk meningkatkan kualiti kerja.<br /><br /><em>Contoh: Mempunyai pengetahuan dan kemahiran yang luas serta jelas dengan semua keperluan/permintaan kerja seperti memilih kaedah yang bersesuaian untuk menghasilkan kerja dan tahu mengawal had api untuk mencegah hasil kerja dari kerosakan.</em></p>', NULL, NULL, '2024-11-20 16:50:35', '2024-11-20 16:50:35', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1198, 362, 5, '<p>Menguasai pengetahuan dan kemahiran untuk mengendalikan tugasan dan boleh menggabungkan pengetahuan untuk meningkatkan kualiti kerja serta mencari cara kerja baru untuk menyelesaikan masalah kerja dengan pengetahuannya.<br /><br /><em>Contoh: Mempunyai pengetahuan dan kemahiran yang luas serta jelas dengan semua keperluan/permintaan kerja dan berinisiatif memberi cadangan untuk menyelesaikan masalah kerja.&nbsp;</em></p>', NULL, NULL, '2024-11-20 16:50:48', '2024-11-20 16:50:48', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1199, 363, 1, '<p>Tidak pernah mengemas dan membersihkan tempat kerja sendiri dan sentiasa mengotorkan tempat kerja sendiri dan rakan sekerja yang lain.<br /><br /><em>Contoh: Tidak pernah terfikir kebaikan bersama dan terus membuang sisa kerja ke lantai dan menganggap ini kerja cleaner untuk membersihkan.</em></p>', NULL, NULL, '2024-11-20 16:51:31', '2024-11-20 16:51:31', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1200, 363, 2, '<p>Kadangkala ada mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya tidak kemas.<br /><br /><em>Contoh: Tidak selalu mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya tidak kemas seperti kadangkala ada membersihkan tempat kerja dan kadangkala tidak.</em></p>', NULL, NULL, '2024-11-20 16:51:40', '2024-11-20 16:51:40', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1201, 363, 3, '<p>Berinisiatif untuk mengemas dan membersihkan tempat kerja dan kebanyakan masa tempat kerjanya adalah kemas dan bersih.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai.</em></p>', NULL, NULL, '2024-11-20 16:51:50', '2024-11-20 16:51:50', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1202, 363, 4, '<p>Selalu mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya kemas dan selalu menolong membersihkan kawasan bahagiannya (division) dan kilang.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai serta tolong membersihkan kawasan yang lain.</em></p>', NULL, NULL, '2024-11-20 16:52:00', '2024-11-20 16:52:00', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1203, 363, 5, '<p>Selalu mengemas dan membersihkan tempat kerja dan tempat kerjanya kelihatan kemas dan bersih. Juga selalu menjaga kebersihan seluruh kawasan kilang dan dapat menegur rakan sekerja untuk menjaga kebersihan kilang.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai serta tolong menjaga kebersihan kawasan yang lain dan menegur rakan sekerja yang tidak menjaga kebersihan kilang.</em></p>', NULL, NULL, '2024-11-20 16:52:10', '2024-11-20 16:52:10', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1204, 364, 1, '<p>Tidak menjaga peralatan dan kemudahan syarikat.<br /><br /><em>Contoh: Tidak menjaga peralatan dan kemudahan syarikat seperti tidak menjaga forklift dan tidak pernah meletakkkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-20 16:52:44', '2024-11-20 16:52:44', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1205, 364, 2, '<p>Kadangkala bersikap cuai dalam mengendali peralatan dan kemudahan syarikat dan mengakibatkan kerosakan.<br /><br /><em>Contoh: Tidak selalu menjaga peralatan dan kemudahan syarikat dan mengakibatkan kerosakan seperti forklift terus jalan setelah enjin dihidupkan. Tidak mengambil berat tentang barang yang diangkat dan masuk ke ruang yang kecil. Selalu tidak meletakkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-20 16:52:54', '2024-11-20 16:52:54', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1206, 364, 3, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat dengan cara yang betul.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-20 16:53:10', '2024-11-20 16:53:10', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1207, 364, 4, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat demi kebaikan bersama. Selain itu, &nbsp;melaporkan kepada pihak atasan bila nampak rakan sekerja salahguna dan memberi cara penyelesaian yang bermanfaat.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna dan melapor jika ada kerosakan dan memberi cadangan untuk memperbaiki cara penggunaan dan penjagaan alatan.</em></p>', NULL, NULL, '2024-11-20 16:53:21', '2024-11-20 16:53:21', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1208, 364, 5, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat demi kebaikan bersama. Selain itu, &nbsp;melaporkan kepada pihak atasan bila nampak pekerja salahguna dan memberi cara penyelesaian yang bermanfaat. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna dan melapor jika ada kerosakan dan memberi cadangan untuk memperbaiki cara penggunaan dan penjagaan alatan.Selain itu, akan menyedarkan dan menasihati rakan sekerja yang tidak menjaga forklift semasa mengguna.</em></p>', NULL, NULL, '2024-11-20 16:53:33', '2024-11-20 16:53:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1209, 365, 1, '<p>Tidak mengutamakan keselamatan semasa bekerja.<br /><br /><em>Contoh: Tidak mengutamakan keselamatan semasa bekerja seperti tidak memakai PPE semasa bekerja.</em></p>', NULL, NULL, '2024-11-20 16:54:03', '2024-11-20 16:54:03', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1210, 365, 2, '<p>Ada sikap mengutamakan keselamatan tetapi kadangkala tidak.<br /><br /><em>Contoh: Ada memakai PPE semasa bekerja tetapi kadangkala tidak.</em></p>', NULL, NULL, '2024-11-20 16:54:12', '2024-11-20 16:54:12', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1211, 365, 3, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja.</em></p>', NULL, NULL, '2024-11-20 16:54:43', '2024-11-20 16:54:43', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1212, 365, 4, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan.</em></p>', NULL, NULL, '2024-11-20 16:54:54', '2024-11-20 16:54:54', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1213, 365, 5, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja dan melaporkan kepada pihak atasan serta turut memberi cara atau cara penyelesaian yang bermanfaat.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan serta turut memberi cara atau cara penyelesaian yang bermanfaat.</em></p>', NULL, NULL, '2024-11-20 16:55:05', '2024-11-20 16:55:05', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1214, 366, 1, '<p>Menerima tugasan tetapi tidak memikul tanggungjawab kerja dan tidak dapat bekerja di bawah tekanan.<br /><br /><em>Contoh: Dia terima kerja yang diberi tetapi sentiasa bersembang dengan rakan sekerja dan tidak buat kerja sehingga tidak nampak hasil kerja.</em></p>', NULL, NULL, '2024-11-20 16:55:47', '2024-11-20 16:55:47', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1215, 366, 2, '<p>Boleh menerima dan memikul tanggungjawab dan cuba untuk bekerja di bawah tekanan tetapi kadangkala tidak dapat menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Dia boleh buat kerja dan cuba elakkan diri dari tidak masuk kerja/tidak memberi alasan untuk bercuti tetapi kadangkala masih perlu dalam bimbingan.</em></p>', NULL, NULL, '2024-11-20 16:55:57', '2024-11-20 16:55:57', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1216, 366, 3, '<p>Boleh menerima dan memikul tanggungjawab dan dapat menghabiskan setiap kerja yang diamanahkan dengan baik di bawah tekanan dan melaporkan kerja yang telah dilakukan kepada pegawai atasan.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia masih menepati target dan ikut piawai kerja yang ditetapkan oleh syarikat. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia juga akan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-20 16:56:06', '2024-11-20 17:00:19', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1217, 366, 4, '<p>Rela menerima dan memikul tanggungjawab dan sentiasa dapat menghasilkan kerja yang berkualiti di bawah tekanan dan dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang dilakukan kepada pegawai atasan.Boleh buat kerja lebih masa sehingga kerja siap.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia akan menawarkan diri secara sukarela untuk kerja tersebut serta menepati target dan ikut piawai kerja yang ditetapkan oleh syarikat. Boleh buat kerja lebih masa sehingga kerja siap. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-20 16:56:16', '2024-11-20 16:56:16', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1218, 366, 5, '<p>Rela menerima dan memikul tanggungjawab serta tahu kepentingan dan deadline kerja. Dapat memanggil rakan sekerja untuk menyiapkan kerja bersama. Sentiasa dapat menghasilkan kerja yang berkualiti di bawah tekanan dan dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang dilakukan kepada pegawai atasan.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia tahu kepentingan dan deadline kerja tersebut serta dapat memanggil rakan sekerja untuk menyiapkan kerja bersama. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-20 16:56:30', '2024-11-20 16:56:30', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1219, 367, 1, '<p>Tidak rela mengaku kesilapan dan suka menolak tanggungjawab kepada orang lain.<br /><br /><em>Contoh: Telah melakukan kesilapan seperti tidak mengikuti spesifikasi kerja yang diberi oleh Leader / tidak tanya Leader apabila tidak faham / tanya rakan sekerja yang tidak dipertanggungjawabkan dan tidak pernah mengakui kesilapan apabila ditegur oleh Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-20 17:01:41', '2024-11-20 17:01:41', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1220, 367, 2, '<p>Kadangkala tidak rela mengaku kesilapan dan suka membuat perbandingan diri dengan orang lain dalam kesilapan yang telah dibuat.<br /><br /><em>Contoh: Telah melakukan kesilapan seperti tidak mengikuti spesifikasi kerja yang diberi oleh Leader / tidak tanya Leader apabila tidak faham / tanya rakan sekerja yang tidak dipertanggungjawabkan dan kadangkala tidak mengakui kesilapan apabila ditegur oleh Leader/Supervisor malah menyatakan Leader/Supervisor ada prasangka terhadap dia.</em></p>', NULL, NULL, '2024-11-20 17:01:52', '2024-11-20 17:01:52', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1221, 367, 3, '<p>Mengaku kesilapan dan tidak menolak tanggungjawab kepada orang lain.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan. Dia terima dan mengakui kesilapan.</em></p>', NULL, NULL, '2024-11-20 17:02:08', '2024-11-20 17:02:08', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1222, 367, 4, '<p>Tidak melarikan diri dari tanggungjawab dan terus berjumpa dengan pihak atasan untuk mengakui kesilapan dan berinisiatif untuk memperbaiki kesilapan yang telah dilakukan.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan. Dia tidak melarikan diri dari tanggungjawab dan terus berjumpa dengan Leader/Supervisor dan mengakui kesilapan. Selain itu, dia juga memberi cadangan dan sama-sama memperbaiki kesilapan yang telah dilakukan.</em></p>', NULL, NULL, '2024-11-20 17:02:25', '2024-11-20 17:02:25', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1223, 367, 5, '<p>Berani mengaku kesilapan dan tidak menolak tanggungjawab dan memastikan kesilapan tidak berlaku lagi. Berinisiatif untuk memperbetulkan kesilapan dan dapat memberi cadangan yang bermanfaat untuk mengelakkan kesilapan berlaku lagi.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan yang agak besar. Dia berani mengakui kesilapan dan terus berjumpa dengan Leader/Supervisor untuk mengakui kesilapan. Dia mengambil pengalaman tersebut sebagai satu pengajaran dan tidak mengulangi kesilapan tersebut lagi. Selain itu, dia &nbsp;memberi cadangan dan sama-sama memperbaiki kesilapan yang telah dilakukan serta memberi cadangan yang bermanfaat untuk mengelakkan kesilapan berlaku lagi.</em></p>', NULL, NULL, '2024-11-20 17:02:38', '2024-11-20 17:02:38', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1224, 368, 1, '<p>Membuat kerja alah kadar dan setakat membuat kerja sahaja dan tidak menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Tidak menunjukkan sikap ingin belajar dan tidak menumpukan perhatian semasa bekerja seperti dia boleh mengambil masa yang panjang untuk memasang beberapa nut pada mesin.</em></p>', NULL, NULL, '2024-11-20 17:03:04', '2024-11-20 17:03:04', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1225, 368, 2, '<p>Boleh membuat kerja tetapi mudah dipengaruhi orang lain dan kadangkala tidak dapat menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Dia boleh pasang nut pada mesin tetapi mudah dipengaruhi oleh rakan sekerja yang lain seperti dia akan melambatkan proses kerjanya dan sambil kerja sambil bersembang apabila ada rakan sekerja yang bersembang dengannya semasa bekerja.</em></p>', NULL, NULL, '2024-11-20 17:03:18', '2024-11-20 17:03:18', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1226, 368, 3, '<p>Lebih agresif dan sikap kerja juga serius dan dapat menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak mengangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja.</em></p>', NULL, NULL, '2024-11-20 17:03:32', '2024-11-20 17:03:32', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1227, 368, 4, '<p>Bersemangat kerja dan menumpukan perhatian sepenuhnya dalam kerja. Sentiasa mengutamakan kualiti kerja dan menghasilkan kerja yang halus dan teliti dan tidak melakukan kesilapan.<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak menggangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja. Dia sentiasa mengutamakan kualiti kerja dan memastikan nut yang dipasang itu betul dan kemas.</em></p>', NULL, NULL, '2024-11-20 17:03:42', '2024-11-20 17:03:42', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1228, 368, 5, '<p>Matlamat untuk berjaya sangat jelas. Menumpukan perhatian sepenuhnya dalam kerja. Sentiasa mengutamakan kualiti kerja dan menghasilkan kerja yang halus dan teliti dan tidak melakukan kesilapan. Selain itu turut memberi cadangan dan cara kerja untuk memastikan kerja berkualiti dihasilkan setiap kali.&nbsp;<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak menggangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja. Dia sentiasa mengutamakan kualiti kerja dan memastikan nut yang dipasang itu betul dan kemas. Selain itu, dia juga akan memberi cadangan untuk memastikan kerja berkualiti dapat dihasilkan.</em></p>', NULL, NULL, '2024-11-20 17:03:52', '2024-11-20 17:03:52', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1229, 369, 1, '<p>Langsung tidak mahu memahami dan menerima peraturan dan polisi syarikat dan sentiasa membuat aduan terhadap dasar syarikat.<br /><br /><em>Contoh: Selalu tidak menutup lampu setelah mengguna tandas dan membuat aduan apabila pihak syarikat mengambil tindakan.</em></p>', NULL, NULL, '2024-11-20 17:04:36', '2024-11-20 17:04:36', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1230, 369, 2, '<p>Kadangkala sahaja mahu menerima dan mematuhi peraturan dan polisi syarikat.<br /><br /><em>Contoh: Kadangkala ada menutup lampu setelah mengguna tandas kadangkala tidak.</em></p>', NULL, NULL, '2024-11-20 17:09:09', '2024-11-20 17:09:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1231, 369, 3, '<p>Menerima dan mematuhi setiap peraturan dan polisi syarikat.<br /><br /><em>Contoh: Setiap kali akan menutup lampu setelah mengguna tandas.</em></p>', NULL, NULL, '2024-11-20 17:09:18', '2024-11-20 17:09:18', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1232, 369, 4, '<p>Tidak melanggar peraturan dan sentiasa dapat menasihatkan rakan sekerja untuk menerima dan mematuhi peraturan dan polisi syarikat untuk kebaikan bersama.<br /><br /><em>Contoh: Sentiasa menutup lampu setelah mengguna tandas dan &nbsp;menasihati dan menerang kepada rakan sekerja yang tidak mematuhi peraturan.</em></p>', NULL, NULL, '2024-11-20 17:09:27', '2024-11-20 17:09:27', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1233, 369, 5, '<p>Memahami dan menerima setiap peraturan dan polisi syarikat dan sentiasa menasihatkan rakan sekerja yang melanggar peraturan serta melaporkan masalah disiplin kepada pegawai atasan untuk kebaikan bersama.<br /><br /><em>Contoh: &nbsp;Sentiasa menutup lampu setelah mengguna tandas dan &nbsp;menasihati dan menerang kepada rakan sekerja yang tidak mematuhi peraturan. Selain itu, juga akan melaporkan nama pekerja yang tidak menutup lampu setelah mengguna tandas.</em></p>', NULL, NULL, '2024-11-20 17:09:37', '2024-11-20 17:09:37', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1234, 370, 1, '<p>Selalu tidak tepat masuk kerja dan menunjukkan kedatangan yang tidak baik.<br /><br /><em>Contoh: Masih berada di tempat berehat semasa siren berbunyi dan jalan perlahan ke tempat kerja.</em></p>', NULL, NULL, '2024-11-20 17:11:39', '2024-11-20 17:11:39', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1235, 370, 2, '<p>Kadangkala ada masuk kerja pada masa yang ditetapkan tetapi keadaan tidak ketara.<br /><br /><em>Contoh: Kadangkala ada tepat masuk kerja semasa siren berbunyi tetapi kebanyakan masa tidak masuk kerja pada masa yang tepat.</em></p>', NULL, NULL, '2024-11-20 17:11:49', '2024-11-20 17:11:49', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1236, 370, 3, '<p>Kebanyakan masa masuk kerja pada masa yang ditetapkan tetapi kadangkala ada lewat juga.<br /><br /><em>Contoh: Kebanyakan masa masuk kerja semasa siren berbunyi tetapi sekali kala masih lewat masuk kerja.</em></p>', NULL, NULL, '2024-11-20 17:11:59', '2024-11-20 17:11:59', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1237, 370, 4, '<p>Mementingkan ketepatan masa masuk kerja dan masuk kerja tepat pada masa atau lebih awal.<br /><br /><em>Contoh: Sentiasa masa masuk kerja sebelum siren berbunyi atau lebih awal.</em></p>', NULL, NULL, '2024-11-20 17:12:08', '2024-11-20 17:12:08', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1238, 370, 5, '<p>Mementingkan ketepatan masa masuk kerja dan masuk kerja tepat pada masa atau lebih awal serta memberi nasihat kepada rakan sekerja yang lewat.<br /><br /><em>Contoh: Sentiasa masa masuk kerja sebelum siren berbunyi atau lebih awal serta memberi nasihat kepada rakan sekerja yang lewat.</em></p>', NULL, NULL, '2024-11-20 17:12:18', '2024-11-20 17:12:18', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1239, 371, 1, '<p>Disiplin diri yang tidak memuaskan dan sering meninggalkan tempat kerja dengan berkeliaran tanpa tujuan dan sering membazirkan masa serta curi tulang.<br /><br /><em>Contoh: Sering meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja (banyak kali sehari) dan mengambil masa yang panjang dalam tandas serta membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-20 17:15:17', '2024-11-20 17:15:17', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1240, 371, 2, '<p>Kadangkala membazirkan masa dan curi tulang serta meninggalkan tempat kerja dengan berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Kadangkala meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja (banyak kali sehari) dan mengambil masa yang panjang dalam tandas serta membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-20 17:20:09', '2024-11-20 17:20:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1241, 371, 3, '<p>Tidak membazirkan masa dan ringan tulang serta menumpukan perhatian semasa bekerja. Tidak meninggalkan tempat kerja dengan berkeliaran tanpa tujuan.<br /><br /><em>Contoh: Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-20 17:20:34', '2024-11-20 17:20:34', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1242, 371, 4, '<p>Teladan yang baik dan tumpuan perhatian sepenuhnya semasa bekerja. Tidak berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Seorang teladan yang baik dan memberi tumpuan sepenuhnya semasa bekerja. Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-20 17:20:44', '2024-11-20 17:20:44', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1243, 371, 5, '<p>Teladan yang baik dan tumpuan perhatian sepenuhnya semasa bekerja dan juga selalu memberi nasihat kepada rakan sekerja supaya melahirkan keadaan kerja yang lebih agresif. Tidak berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Seorang teladan yang baik dan memberi tumpuan sepenuhnya semasa bekerja. Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja. Selalu memberi nasihat kepada rakan sekerja yang selalu pergi ke tandas sebagai alasan.</em></p>', NULL, NULL, '2024-11-20 17:20:54', '2024-11-20 17:20:54', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1244, 372, 1, '<p>Tidak pernah berada di tempat kerja semasa pembersihan kawasan dijalankan.<br /><br /><em>Contoh: Tidak berada di tempat kerja dan pergi ke tandas semasa pembersihan kawasan dijalankan.</em></p>', NULL, NULL, '2024-11-20 17:21:56', '2024-11-20 17:21:56', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1245, 372, 2, '<p>Memulakan kerja pembersihan kawasan walaupun masa yang ditetapkan belum sampai lagi.<br /><br /><em>Contoh: Memulakan kerja pembersihan kawasan walaupun masa yang ditetapkan belum sampai lagi dan rakan sekerja yang lain masih bekerja lagi.</em></p>', NULL, NULL, '2024-11-20 17:22:28', '2024-11-20 17:22:28', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1246, 372, 3, '<p>Kebanyakan masa membersihkan kawasan production pada masa yang ditetapkan.</p><p>Kadangkala membersihkan kawasan production pada masa yang ditetapkan tetapi keadaan tidak ketara.</p><p><br />\nContoh: Kadangkala ada berada di production semasa pembersihan kawasan dijalankan tetapi kebanyakan masa tidak nampak orang.</p>', NULL, NULL, '2024-11-21 15:50:24', '2024-11-21 15:50:24', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1247, 372, 4, '<p>Sentiasa mengutamakan dan membersihkan kawasan production pada masa yang ditetapkan.<br /><br /><em>Contoh: Sentiasa membersihkan kawasan production pada masa yang ditetapkan.</em></p>', NULL, NULL, '2024-11-21 15:51:25', '2024-11-21 15:51:25', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1248, 372, 5, '<p>Mengutamakan dan membersihkan kawasan production pada masa yang ditetapkan serta memberi nasihat kepada rakan sekerja yang tidak berbuat demikian.<br /><br /><em>Contoh: Sentiasa membersihkan kawasan production pada masa yang ditetapkan dan memberi nasihat kepada rakan sekerja yang tidak berbuat demikian.</em></p>', NULL, NULL, '2024-11-21 15:51:40', '2024-11-21 15:51:40', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1249, 373, 1, '<p>Hanya menghormati pegawai atasan dan tidak bersopan dengan rakan sekerja.<br /><br /><em>Contoh: Hanya menghormati Leader/Supervisor atau pangkat kerja yang lebih tinggi tetapi tidak bersopan dengan rakan sekerja yang berpangkat rendah/masih baru.</em></p>', NULL, NULL, '2024-11-21 15:52:06', '2024-11-21 15:52:06', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1250, 373, 2, '<p>Biasanya akan bersopan dan menghormati orang lain tetapi kadangkala beremosi.<br /><br /><em>Contoh: Biasanya bersopan dan menghormati rakan sekerja yang lain tetapi kadangkala beremosi dan lawan cakap.</em></p>', NULL, NULL, '2024-11-21 15:52:19', '2024-11-21 15:52:19', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1251, 373, 3, '<p>Sering bersopan dan menghormati orang lain dan tidak bertindak mengikut perasaan.<br /><br /><em>Contoh: Sering bersopan dan menghormati rakan sekerja lain dan tidak bertindak mengikut perasaan.</em></p>', NULL, NULL, '2024-11-21 15:52:32', '2024-11-21 15:52:32', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1252, 373, 4, '<p>Bersopan dan menghormati orang lain pada setiap masa dan tidak bertindak mengikut perasaan dan berbahasa sopan.<br /><br /><em>Contoh: Bersopan dan setiap masa menghormati rakan sekerja yang lain dan tidak bertindak mengikut perasaan dan berbahasa sopan serta jaga perasaan rakan lain.</em></p>', NULL, NULL, '2024-11-21 15:52:42', '2024-11-21 15:52:42', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1253, 373, 5, '<p>Bersopan dan menghormati orang lain pada setiap masa dan masih bercakap dengan sopan walaupun sendiri telah dipersalahkan dalam proses penyelesaian masalah.<br /><br /><em>Contoh: Bersopan dan setiap masa menghormati rakan sekerja yang lain dan masih bercakap dengan sopan walaupun sendiri telah dipersalahkan dalam proses penyelesaian masalah.</em></p>', NULL, NULL, '2024-11-21 15:52:54', '2024-11-21 15:52:54', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1254, 374, 1, '<p>Memang mengetahui arahan yang diberi mempunyai kesilapan tetapi tidak mendapatkan kepastian kerana berpendapat itu adalah tanggungjawab pegawai atasan.<br /><br /><em>Contoh: Tidak mendapatkan kepastian daripada Leader/Supervisor tentang spesifikasi kerja yang diberi walaupun sudah tahu arahan yang diberi mempunyai kesilapan/tidak jelas dan beranggap itu adalah tanggungjawab Leader/Supervisor dan bukan dia.</em></p>', NULL, NULL, '2024-11-21 15:53:57', '2024-11-21 15:53:57', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1255, 374, 2, '<p>Jarang berinisiatif untuk mendapatkan kepastian daripada pegawai atasan walaupun arahan yang diberi tidak jelas atau silap.<br /><br /><em>Contoh: Menunjukkan sikap sudah tahu tetapi tidak ingin peduli dan tidak mendapatkan kepastian daripada Leader/Supervisor walapun arahan yang diberi ada kesilapan/kurang jelas.</em></p>', NULL, NULL, '2024-11-21 15:54:16', '2024-11-21 15:54:16', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1256, 374, 3, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap tetapi tidak pernah melapor balik kepada pegawai atasan tentang tugasan tersebut.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi ada kesilapan/tidak jelas tetapi tidak pernah melapor balik tugasan tersebut.</em></p>', NULL, NULL, '2024-11-21 15:54:26', '2024-11-21 15:54:26', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1257, 374, 4, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi tidak jelas/silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut.</em></p>', NULL, NULL, '2024-11-21 15:54:37', '2024-11-21 15:54:37', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1258, 374, 5, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut serta memberi pendapat yang bermanfaat.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi tidak jelas/silap dan selalu melapor balik kepada Leader/Supervisor dan turut mengambil bahagian untuk memberi pendapat yang bermanfaat.</em></p>', NULL, NULL, '2024-11-21 15:54:49', '2024-11-21 15:54:49', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1259, 375, 1, '<p>Degil dan berpegang teguh dengan pendapat sendiri dan tidak menuruti arahan pegawai atasan.<br /><br /><em>Contoh: Tidak menerima dan melawan percakapan Leader/Supervisor semasa diberi tugasan.</em></p>', NULL, NULL, '2024-11-21 15:55:40', '2024-11-21 15:55:40', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1260, 375, 2, '<p>Kebanyakan masa akan menuruti arahan pegawai atasan tetapi kadangkala akan beremosi dan meluahkan ketidakpuasan.<br /><br /><em>Contoh: Kebanyakan masa akan menerima tugasan Leader/Supervisor dengan baik tetapi kadangkala tidak.</em></p>', NULL, NULL, '2024-11-21 15:55:50', '2024-11-21 15:55:50', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1261, 375, 3, '<p>Mengambil berat dan menuruti arahan pegawai atasan dan tidak pernah membuat hal sesuka hati.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati dan akan bertanya jika tidak faham.</em></p>', NULL, NULL, '2024-11-21 15:56:00', '2024-11-21 15:56:00', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1262, 375, 4, '<p>Mengambil berat dan menuruti arahan pegawai atasan dan tidak pernah membuat hal sesuka hati. Kadangkala turut memberikan pendapat yang bermanfaat dalan kerja yang diberi.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati dan akan bertanya jika tidak faham. Kadangkala turut memberi cadangan/pandangan dalam kerja yang diberi.</em></p>', NULL, NULL, '2024-11-21 15:56:09', '2024-11-21 15:56:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1263, 375, 5, '<p>Bersikap positif dan menuruti semua arahan pegawai atasan, tidak membuat hal malah dapat menyampaikan objektif dan kehendak arahan secara positif kepada semua rakan sekerja.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati. Turut menyampaikan maksud dan kehendak mengikuti arahan Leader/Supervisor secara positif kepada rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-21 15:56:20', '2024-11-21 15:56:20', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1264, 376, 1, '<p>Ego dan tidak sudi berbincang tugasan sesama rakan sekerja dan pegawai atasan, sangat keras kepala dan tidak dapat menerima cadangan orang lain.<br /><br /><em>Contoh: Buat kerja tanpa ikut pelan kerja seperti menebuk drill pada kelajuan yang tinggi dan telah membesarkan lubang 3mm kepada 3.20 mm. Dia tidak dapat menerima apabila diminta buat semula pada kelajuan drill yang rendah.</em></p>', NULL, NULL, '2024-11-21 15:57:10', '2024-11-21 15:57:10', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1265, 376, 2, '<p>Jarang berbincang tugasan sesama rakan sekerja dan pegawai atasan dan tidak begitu rela berkongsi maklumat, kadangkala keras kepala dan tidak dapat menerima cadangan orang lain.<br /><br /><em>Contoh: Dia menunjukkan sikap yang tidak begitu gembira apabila diminta buat semula pada kelajuan drill yang rendah.</em></p>', NULL, NULL, '2024-11-21 15:57:25', '2024-11-21 15:57:25', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1266, 376, 3, '<p>Sudi berbincang dan menerima cadangan rakan sekerja dan pegawai atasan, dapat memberi pertolongan apabila diminta.<br /><br /><em>Contoh: Dia sudi membuat semula pada kelajuan drill yang rendah setelah berbincang dan diminta berubah.</em></p>', NULL, NULL, '2024-11-21 15:57:36', '2024-11-21 15:57:36', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1267, 376, 4, '<p>Sudi berbincang dan berinisiatif memberi pertolongan sesama rakan sekerja dan pegawai atasan dengan tidak berkira kerja. Boleh menerima cadangan orang lain dan tidak berkeras kepala.<br /><br /><em>Contoh: Dia sudi membuat semula pada kelajuan drill yang rendah dan dia turut memberi cadangan untuk mengatasi masalah tersebut.</em></p>', NULL, NULL, '2024-11-21 15:57:50', '2024-11-21 15:57:50', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1268, 376, 5, '<p>Sudi berbincang dan berinisiatif memberi pertolongan sesama rakan sekerja dan pegawai atasan dengan tidak berkira kerja. Boleh menerima cadangan orang lain dan tidak berkeras kepala. Selain itu, turut boleh memanggil rakan sekerja untuk sama-sama menyiapkan kerja tersebut.<br /><br /><em>Contoh: Dia ialah orang yang sangat agresif dan sudi membuat semula dan dia turut boleh meminta rakan sekerja untuk sama-sama menyiapkan kerja.</em></p>', NULL, NULL, '2024-11-21 15:58:02', '2024-11-21 15:58:02', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1269, 377, 1, '<p>Menolak tugasan selain dari bidang sendiri dan langsung tidak dapat menerima tugasan tambahan atau di luar bidang kerja, amat mementingkan diri sendiri.<br /><br /><em>Contoh: Tidak mahu backup rakan sekerja yang bercuti dan selalu dipengaruhi oleh rakan sekerja yang lain dimana orang yang berbuat banyak tidak dapat apa-apa.</em></p>', NULL, NULL, '2024-11-21 15:58:43', '2024-11-21 15:58:43', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1270, 377, 2, '<p>Kadangkala menerima tugasan tambahan atau di luar bidang kerja tetapi dengan hati yang tidak rela dan mementingkan kepentingan diri sendiri.<br /><br /><em>Contoh: Kadangkala akan diminta untuk backup rakan sekerja yang bercuti tetapi dia akan membuat kerja secara tidak rela / memberi alasan bahawa dia tidak tahu buat kerja tersebut.</em></p>', NULL, NULL, '2024-11-21 15:58:53', '2024-11-21 15:58:53', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1271, 377, 3, '<p>Rela menerima tugasan tambahan atau di luar bidang dan tidak menolak apabila tugas diberi.<br /><br /><em>Contoh: Rela backup rakan sekerja yang bercuti dan tidak menolak apabila tugas diberi oleh Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-21 15:59:04', '2024-11-21 15:59:04', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1273, 377, 4, '<p>Rela menerima tugasan tambahan atau di luar bidang dan tidak menolak apabila tugas diberi serta cuba mencari cara untuk menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Rela backup rakan sekerja yang bercuti dan tidak menolak apabila tugas diberi oleh Leader / Supervisor. Selain itu, dia juga cari jalan untuk mengeluarkan hasil kerja yang baik / membuat kerja tersebut dengan bersungguh-sungguh.</em></p>', NULL, NULL, '2024-11-21 16:01:41', '2024-11-21 16:01:41', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1274, 377, 5, '<p>Amat rela menerima tugasan tambahan atau di luar bidang dan menerimanya sebagai satu cabaran. Berusaha dan bertanggungjawab sepenuhnya sehingga tugasan selesai dengan sempurna.<br /><br /><em>Contoh: Sangat rela backup rakan sekerja yang bercuti dan menganggap tugas yang diberi tersebut sebagai satu cabaran / tugas sendiri. Dia membuat kerja dengan sepenuh hati dan mengambil tanggungjawab sehingga tugasan tersebut selesai dengan sempurnanya.</em></p>', NULL, NULL, '2024-11-21 16:01:59', '2024-11-21 16:01:59', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1386, 424, 1, '<p>Tidak dapat menyiapkan tugasan mengikut masa yang ditetapkan dan selalu dibuat semula oleh rakan sekerja yang lain dan menyebabkan kelewatan.<br /><br /><em>Contoh: Kerja yang sepatutnya boleh disiapkan dalam sehari tetapi dia selalu tidak hadir bekerja dan kerjanya perlu disambung / dibuat semula oleh rakan sekerja yang lain dan menyebabkan kelewatan.</em></p>', NULL, NULL, '2024-11-21 16:15:27', '2024-11-21 16:15:27', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1387, 424, 2, '<p>Selalu mengambil masa yang panjang untuk menyiapkan kerja walaupun bimbingan sudah diberi.<br /><br /><em>Contoh: Kerja yang sepatutnya boleh disiapkan dalam sehari tetapi dia mengambil masa yang panjang walaupun bimbingan sudah diberi.</em></p>', NULL, NULL, '2024-11-21 16:15:37', '2024-11-21 16:15:37', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1388, 424, 3, '<p>Tugasan biasanya dapat disiapkan dengan sedikit bimbingan dan siap dalam masa yang ditetapkan mahupun lebih awal dan hasil kerja yang masih boleh diterima.<br /><br /><em>Contoh: Boleh menghasilkan kerja dalam masa yang ditetapkan tetapi masih perlu dalam pengawasan/bimbingan.</em></p>', NULL, NULL, '2024-11-21 16:15:47', '2024-11-21 16:15:47', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1389, 424, 4, '<p>Tugasan sentiasa disiapkan tanpa bimbingan dan mengikut jadual mahupun lebih awal dan hasil kerja yang agar memuaskan.<br /><br /><em>Contoh: Boleh menghasilkan kerja dalam masa yang pendek dan tanpa sebarang pengawasan/bimbingan seperti dia cuma perlu 5 jam untuk menghasilkan kerja yang dijangka siap dalam sehari dan dia boleh menghasilkan lebih dalam satu hari.</em></p>', NULL, NULL, '2024-11-21 16:15:59', '2024-11-21 16:15:59', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1390, 424, 5, '<p>Mengutamakan masa dan pantas dalam menyiapkan tugasan yang diberi dan hasil kerja sangat bagus dan boleh diharapkan.<br /><br /><em>Contoh:Boleh membuat apa kerja yang dirancang dan menepati masa yang ditetapkan atau lebih awal tanpa pengawasan/bimbingan. Individu yang teliti dan prihatin dan menguasa masa dan memberi hasil kerja yang sangat bagus dan halus.</em></p>', NULL, NULL, '2024-11-21 16:16:10', '2024-11-21 16:16:10', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1391, 425, 1, '<p>Suka menolak tanggungjawab kerja dan berpura-pura/berdiam diri walaupun tahu apa cara untuk membuat kerja/menyelesaikan masalah.<br /><br /><em>Contoh: Langsung tidak bergerak dan pakai duduk dan tunggu sahaja walaupun sudah diberi penjelasan dalam pelan kerja.</em></p>', NULL, NULL, '2024-11-21 16:16:57', '2024-11-21 16:16:57', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1392, 425, 2, '<p>Kadangkala menolak tanggungjawab kerja dan berpura-pura/berdiam diri walaupun tahu apa cara untuk membuat kerja/menyelesaikan masalah.<br /><br /><em>Contoh: Tidak berusaha untuk belajar dan memahami pembacaan pelan kerja dan ukuran serta memerlukan seseorang mengawasi di tepi dan selalu memberi penjelasan boleh baru dapat menghasilkan kerja yang ditugaskan.</em></p>', NULL, NULL, '2024-11-21 16:17:10', '2024-11-21 16:17:10', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1393, 425, 3, '<p>Sudah faham dan boleh terus bertindak/bergerak ke atas kerja yang telah diselesaikan.&nbsp;<br /><br /><em>Contoh: Sudah tahu membuat kerja/menyelesaikan masalah dan tidak menolak tanggungjawab.</em></p>', NULL, NULL, '2024-11-21 16:17:20', '2024-11-21 16:17:20', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1394, 425, 4, '<p>Sudah faham dan boleh bertindak cepat ke atas semua tugasan serta tidak perlu pengawasan/bimbingan dan akan lapor balik apabila kerja telah siap.<br /><br /><em>Contoh: Bertanggungjawab dan tidak berpura-pura atau berdiam diri dalam membuat kerja/menyelesaikan masalah dan tidak perlu pengawasan/bimbingan dan akan bertindak/bergerak ke atas kerja yang ditugaskan serta lapor balik apabila kerja telah siap.</em></p>', NULL, NULL, '2024-11-21 16:17:26', '2024-11-21 16:17:46', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1395, 425, 5, '<p>Sudah faham dan boleh bertindak cepat ke atas semua tugasan serta tidak perlu pengawasan/bimbingan dan akan lapor balik apabila kerja telah siap. Selain itu, dapat memberi nasihat kepada rakan sekerja yang lain supaya cepat bertindak dalam kerja.<br /><br /><em>Contoh: Bertanggungjawab dan tidak berpura-pura atau berdiam diri dalam membuat kerja/menyelesaikan masalah dan tidak perlu pengawasan/bimbingan dan akan bertindak/bergerak ke atas kerja yang ditugaskan serta lapor balik apabila kerja telah siap. Selain itu, juga memotivasikan rakan sekerja supaya tidak berpura-pura/berdiam diri dalam &nbsp;membuat kerja/menyelesaikan masalah.</em></p>', NULL, NULL, '2024-11-21 16:18:03', '2024-11-21 16:18:03', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1396, 426, 1, '<p>Tidak membuat kerja secara sistematik dan tidak tahu membezakan kepentingan kerja.<br /><br /><em>Contoh: Tidak tahu membezakan kepentingan kerja dan tidak buat perancangan kerja.</em></p>', NULL, NULL, '2024-11-21 16:19:35', '2024-11-21 16:19:35', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1397, 426, 2, '<p>Kadangkala ada membuat kerja secara sistematik dan kadangkala tahu membezakan kepentingan kerja tetapi keadaan tidak ketara.<br /><br /><em>Contoh: Kadangkala tahu membezakan kepentingan kerja dan buat perancangan kerja tetapi tidak selalu dan ikut mood sendiri.</em></p>', NULL, NULL, '2024-11-21 16:19:46', '2024-11-21 16:19:46', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1398, 426, 3, '<p>Tidak perlu seseorang mengawasi di tepi dan tahu membuat kerja secara sistematik dan tahu membezakan kepentingan kerja dengan penjelasan yang ringkas sahaja.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan memerlukan penjelasan kerja yang ringkas sahaja.</em></p>', NULL, NULL, '2024-11-21 16:19:58', '2024-11-21 16:19:58', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1399, 426, 4, '<p>Hanya memerlukan penjelasan yang ringkas dan tahu membuat kerja secara sistematik dan tahu membezakan kepentingan kerja. Berhati-hati dan tiada kesilapan dalam kerja yang dihasilkan.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan hanya memerlukan penjelasan kerja yang ringkas sahaja dan memberi tumpuan dalam kerja dan mengeluarkan hasil kerja yang baik.</em></p>', NULL, NULL, '2024-11-21 16:20:08', '2024-11-21 16:20:08', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1400, 426, 5, '<p>Hanya memerlukan penjelasan yang sangat ringkas sahaja untuk membuat kerja secara sistematik dan tahu membezakan kepentingan kerja dan dapat memberi tunjuk ajar kepada rakan sekerja.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan hanya memerlukan penjelasan kerja yang ringkas sahaja dan memberi tumpuan dalam kerja dan mengeluarkan hasil kerja yang baik dan turut memberi tunjuk ajar kepada rakan sekerja.</em></p>', NULL, NULL, '2024-11-21 16:20:20', '2024-11-21 16:20:20', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1401, 427, 1, '<p>Hasil kerja yang tidak boleh diterima dan selalu membuat kesilapan.<br /><br /><em>Contoh: Tidak menumpu perhatian semasa bekerja dan selalu membuat kesilapan yang sama. Tidak pernah berubah walaupun &nbsp;sudah diberi bimbingan/teguran seperti selalu mengulangi kesilapan yang sama walaupun sudah banyak kali memasang mesin yang sama model.</em></p>', NULL, NULL, '2024-11-21 16:21:08', '2024-11-21 16:21:08', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1402, 427, 2, '<p>Cuai dan mengakibatkan kesilapan kerja.<br /><br /><em>Contoh: Kadangkala cuai semasa bekerja dan mengakibatkan kesilapan kerja kerana tindakan yang lambat untuk berubah setelah diberi bimbingan/teguran.</em></p>', NULL, NULL, '2024-11-21 16:21:18', '2024-11-21 16:21:18', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1403, 427, 3, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan meminimumkan tahap kesilapan kepada yang terendah.<br /><br /><em>Contoh: Kadangkala ada membuat kesilapan tetapi mengambil tindakan yang cepat untuk berubah setelah diberi bimbingan/teguran.</em></p>', NULL, NULL, '2024-11-21 16:21:28', '2024-11-21 16:21:28', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1404, 427, 4, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan apa-apa kesilapan dalam kerja harian.<br /><br /><em>Contoh: Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan. Selain itu, juga berinisiatif untuk menjaga barangan/bahan dan tidak membazir.</em></p>', NULL, NULL, '2024-11-21 16:21:37', '2024-11-21 16:21:37', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1405, 427, 5, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan kerja dan berinisiatif untuk memberi pendapat dan memperbaiki cara kerja yang lebih baik untuk meminimumkan tahap kesilapan kerja.<br /><br /><em>Contoh: Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan dan berinisiatif untuk memberi pendapat dan memperbaiki cara kerja untuk meminimumkan tahap kesilapan kerja seperti berinisiatif untuk mengetahui masalah semasa pemasangan mesin dan turut memberi pendapat untuk memperbaiki cara kerja/menyelesaikan masalah.</em></p>', NULL, NULL, '2024-11-21 16:21:57', '2024-11-21 16:21:57', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1406, 428, 1, '<p>Langsung tidak memahami permintaan kualiti kerja dan tidak memberi perhatian kepada kerja yang dilakukan.<br /><br /><em>Contoh: Langsung tidak memahami permintaan kualiti kerja dan tidak memberi perhatian terhadap semua kerja yang dilakukan seperti membuat pemasangan Control Panel tetapi langsung tidak mengikut diagram yang diberi.</em></p>', NULL, NULL, '2024-11-21 16:22:21', '2024-11-21 16:22:21', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1407, 428, 2, '<p>Kadangkala tidak faham spesifikasi kerja yang diberi dan tidak berinisiatif mengambil langkah untuk mengetahui untuk menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Tidak berinisiatif untuk bertanya/kurang bertanya apabila tidak tahu semasa memasang Control Panel dan pasang ikut sendiri dan tidak ikut cara kerja yang betul.</em></p>', NULL, NULL, '2024-11-21 16:22:31', '2024-11-21 16:22:31', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1408, 428, 3, '<p>Memahami permintaan kualiti kerja dan dapat menghasilkan kerja yang berkualiti secara individu tanpa pengawasan pegawai atasan tetapi tidak mengambil perhatian dan abaikan kerja yang remeh temeh serta tidak mengambil perhatian terhadap kekemasan hasil kerja.<br /><br /><em>Contoh: Tahu pasang Control Panel tetapi tidak terfikir tentang kekemasan. Wayar sudah ditarik dengan betul tetapi tidak diikat dengan cable tie/tidak tersusun/tidak label semasa membuat pemasangan.</em></p>', NULL, NULL, '2024-11-21 16:22:41', '2024-11-21 16:22:41', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1409, 428, 4, '<p>Faham tentang kualiti dan dapat menghasilkan kerja yang berkualiti dan memenuhi kehendak syarikat dan dapat memastikan kerja yang dihasilkan tidak bermasalah.<br /><br /><em>Contoh: Faham tentang kualiti kerja dan ikut semua spesifikasi yang diminta. Boleh berfikir dan nampak (meramalkan) ke hadapan dan memastikan kerja yang dihasilkan tidak bermasalah seperti tahu pasang Control Panel dan semua litar boleh berfungsi dengan baik dan pemasangan yang kemas dan melaporkan keadaan kepada Leader/Supervisor apabila litar tidak berfungsi/bernyala.</em></p>', NULL, NULL, '2024-11-21 16:22:51', '2024-11-21 16:22:51', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1410, 428, 5, '<p>Sangat faham tentang kualiti kerja dan dapat menghasilkan kerja yang berkualiti dan memenuhi kehendak syarikat dan dapat memastikan kerja yang dihasilkan tidak bermasalah serta turut memberi tunjuk ajar kepada rakan kerja yang lain.&nbsp;<br /><br /><em>Contoh: Sangat faham tentang kualiti kerja dan ikut semua spesifikasi yang diminta. Boleh berfikir dan nampak (meramalkan) ke hadapan dan memastikan kerja yang dihasilkan tidak bermasalah. Selain itu, juga dapat memberi tunjuk ajar kepada rakan sekerja yang lain seperti tahu pasang Control Panel dan semua litar boleh berfungsi dengan baik dan pemasangan yang kemas dan melaporkan keadaan kepada Leader/Supervisor apabila litar tidak berfungsi/bernyala. Selain itu, dia juga memberi tunjuk ajar kepada rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-21 16:23:00', '2024-11-21 16:23:00', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1411, 429, 1, '<p>Sentiasa membazirkan/merosakkan sumber syarikat.<br /><br /><em>Contoh: Tidak pernah berhati-hati dalam spesifikasi kerja yang diberi dan sentiasa mengakibatkan pembaziran bahan.</em></p>', NULL, NULL, '2024-11-21 16:23:40', '2024-11-21 16:23:40', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1412, 429, 2, '<p>Ada bersikap mahu menjimatkan sumber syarikat tetapi kadangkala menyebabkan pembaziran di atas kecuaiannya.<br /><br /><em>Contoh: Cuai dalam pembacaan spesifikasi kerja yang diberi dan silap ambil bahan dan menyebabkan kesilapan dan membazirkan bahan serta perlu &ldquo;rework&rdquo;.</em></p>', NULL, NULL, '2024-11-21 16:23:52', '2024-11-21 16:23:52', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1413, 429, 3, '<p>Berhati-hati semasa bekerja dan menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dan memastikan betul supaya tidak berlaku kesilapan yang mengakibatkan pembaziran bahan dan buang masa.</em></p>', NULL, NULL, '2024-11-21 16:24:04', '2024-11-21 16:24:04', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1414, 429, 4, '<p>Berhati-hati semasa bekerja dan berinisiatif menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya. Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dengan pelan kerja dan memastikan semua barang yang ambil adalah betul. Ada pemikiran tidak membazir seperti dalam menghasilkan sesuatu barang yang sangat kecil, dia akan cari scrap dahulu dan tidak guna bahan yang baru atau bahan yang besar.Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan.</em></p>', NULL, NULL, '2024-11-21 16:24:18', '2024-11-21 16:24:18', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1415, 429, 5, '<p>Berhati-hati semasa bekerja dan berinisiatif menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya. Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan dan juga menyedarkan dan membetulkan kesilapan rakan sekerja yang lain.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dengan pelan kerja dan memastikan semua barang yang ambil adalah betul. Ada pemikiran tidak membazir seperti dalam menghasilkan sesuatu barang yang sangat kecil, dia akan cari scrap dahulu dan tidak guna bahan yang baru atau bahan yang besar.Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan dan menyedarkan dan membetulkan kesilapan rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-21 16:24:32', '2024-11-21 16:24:32', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1416, 430, 1, '<p>Pengetahuan atau kemahiran adalah terhad dan tidak dapat menyelesaikan tugasan dan menggunakan masa yang panjang untuk mempelajari pengetahuan dan cara kerja yang agak senang.<br /><br /><em>Contoh: Tidak ada pengetahuan dan kemahiran kerja dan menggunakan masa yang panjang untuk mempelajari cara kerja yang senang walaupun bimbingan telah diberi seperti membuat kerja kimpalan yang paling senang iaitu mengimpal besi dalam kedudukan rata.</em></p>', NULL, NULL, '2024-11-21 16:25:26', '2024-11-21 16:25:26', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1417, 430, 2, '<p>Kurang pengetahuan atau kemahiran yang cukup untuk mengendalikan tugasan.<br /><br /><em>Contoh: Hasil kimpalan yang teruk dan bimbingan masih diperlukan walaupun diminta menghasilkan kerja kimpalan yang agak senang seperti mengimpal besi dalam kedudukan rata dan mendatar.</em></p>', NULL, NULL, '2024-11-21 16:25:36', '2024-11-21 16:25:36', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1418, 430, 3, '<p>Mempunyai pengetahuan dan kemahiran untuk mengendalikan tugasan dan mempunyai sikap mahu belajar dan mempelajari pengetahuan kerja yang baru dalam masa yang singkat dan mengimplikasikan dalam kerja harian.<br /><br /><em>Contoh: Ada pengetahuan dan kemahiran kimpalan tetapi tidak dapat meneruskan kerja apabila menghadapi kerja yang tidak biasa dan memerlukan bimbingan seperti: boleh mengimpal besi yang nipis tetapi tidak apabila diminta mengimpal besi yang lagi nipis / boleh mengimpal dalam kedudukan rata, mendatar dan menegak tetapi tidak apabila dalam keadaan overhead atau dalam keadaan 45 darjah.</em></p>', NULL, NULL, '2024-11-21 16:25:45', '2024-11-21 16:25:45', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1419, 430, 4, '<p>Boleh menguasai pengetahuan dan kemahiran untuk mengendalikan tugasan dan pencapaian yang agak memuaskan dan dapat menggunakan pengetahuannya untuk meningkatkan kualiti kerja.<br /><br /><em>Contoh: Mempunyai pengetahuan dan kemahiran yang luas serta jelas dengan semua keperluan/permintaan kerja seperti memilih kaedah yang bersesuaian untuk menghasilkan kerja dan tahu mengawal had api untuk mencegah hasil kerja dari kerosakan.</em></p>', NULL, NULL, '2024-11-21 16:25:55', '2024-11-21 16:25:55', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1420, 430, 5, '<p>Menguasai pengetahuan dan kemahiran untuk mengendalikan tugasan dan boleh menggabungkan pengetahuan untuk meningkatkan kualiti kerja serta mencari cara kerja baru untuk menyelesaikan masalah kerja dengan pengetahuannya.<br /><br /><em>Contoh: Mempunyai pengetahuan dan kemahiran yang luas serta jelas dengan semua keperluan/permintaan kerja dan berinisiatif memberi cadangan untuk menyelesaikan masalah kerja.&nbsp;</em></p>', NULL, NULL, '2024-11-21 16:26:05', '2024-11-21 16:26:05', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1421, 431, 1, '<p>Tidak pernah mengemas dan membersihkan tempat kerja sendiri dan sentiasa mengotorkan tempat kerja sendiri dan rakan sekerja yang lain.<br /><br /><em>Contoh: Tidak pernah terfikir kebaikan bersama dan terus membuang sisa kerja ke lantai dan menganggap ini kerja cleaner untuk membersihkan.</em></p>', NULL, NULL, '2024-11-21 16:27:00', '2024-11-21 16:27:00', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1422, 431, 2, '<p>Kadangkala ada mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya tidak kemas.<br /><br /><em>Contoh: Tidak selalu mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya tidak kemas seperti kadangkala ada membersihkan tempat kerja dan kadangkala tidak.</em></p>', NULL, NULL, '2024-11-21 16:27:15', '2024-11-21 16:27:15', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1423, 431, 3, '<p>Berinisiatif untuk mengemas dan membersihkan tempat kerja dan kebanyakan masa tempat kerjanya adalah kemas dan bersih.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai.</em></p>', NULL, NULL, '2024-11-21 16:27:25', '2024-11-21 16:27:25', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1424, 431, 4, '<p>Selalu mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya kemas dan selalu menolong membersihkan kawasan bahagiannya (division) dan kilang.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai serta tolong membersihkan kawasan yang lain.</em></p>', NULL, NULL, '2024-11-21 16:27:35', '2024-11-21 16:27:35', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1425, 431, 5, '<p>Selalu mengemas dan membersihkan tempat kerja dan tempat kerjanya kelihatan kemas dan bersih. Juga selalu menjaga kebersihan seluruh kawasan kilang dan dapat menegur rakan sekerja untuk menjaga kebersihan kilang.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai serta tolong menjaga kebersihan kawasan yang lain dan menegur rakan sekerja yang tidak menjaga kebersihan kilang.</em></p>', NULL, NULL, '2024-11-21 16:27:46', '2024-11-21 16:27:46', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1426, 432, 1, '<p>Tidak menjaga peralatan dan kemudahan syarikat.<br /><br /><em>Contoh: Tidak menjaga peralatan dan kemudahan syarikat seperti tidak menjaga forklift dan tidak pernah meletakkkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-21 16:28:33', '2024-11-21 16:28:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1427, 432, 2, '<p>Kadangkala bersikap cuai dalam mengendali peralatan dan kemudahan syarikat dan mengakibatkan kerosakan.<br /><br /><em>Contoh: Tidak selalu menjaga peralatan dan kemudahan syarikat dan mengakibatkan kerosakan seperti forklift terus jalan setelah enjin dihidupkan. Tidak mengambil berat tentang barang yang diangkat dan masuk ke ruang yang kecil. Selalu tidak meletakkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-21 16:28:43', '2024-11-21 16:28:43', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1428, 432, 3, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat dengan cara yang betul.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-21 16:28:53', '2024-11-21 16:28:53', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1429, 432, 4, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat demi kebaikan bersama. Selain itu, &nbsp;melaporkan kepada pihak atasan bila nampak rakan sekerja salahguna dan memberi cara penyelesaian yang bermanfaat.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna dan melapor jika ada kerosakan dan memberi cadangan untuk memperbaiki cara penggunaan dan penjagaan alatan.</em></p>', NULL, NULL, '2024-11-21 16:29:04', '2024-11-21 16:29:04', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1430, 432, 5, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat demi kebaikan bersama. Selain itu, &nbsp;melaporkan kepada pihak atasan bila nampak pekerja salahguna dan memberi cara penyelesaian yang bermanfaat. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna dan melapor jika ada kerosakan dan memberi cadangan untuk memperbaiki cara penggunaan dan penjagaan alatan.Selain itu, akan menyedarkan dan menasihati rakan sekerja yang tidak menjaga forklift semasa mengguna.</em></p>', NULL, NULL, '2024-11-21 16:29:17', '2024-11-21 16:29:17', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1431, 433, 1, '<p>Tidak mengutamakan keselamatan semasa bekerja.<br /><br /><em>Contoh: Tidak mengutamakan keselamatan semasa bekerja seperti tidak memakai PPE semasa bekerja.</em></p>', NULL, NULL, '2024-11-21 16:30:06', '2024-11-21 16:30:06', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1432, 433, 2, '<p>Ada sikap mengutamakan keselamatan tetapi kadangkala tidak.<br /><br /><em>Contoh: Ada memakai PPE semasa bekerja tetapi kadangkala tidak.</em></p>', NULL, NULL, '2024-11-21 16:30:17', '2024-11-21 16:30:17', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1433, 433, 3, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja.</em></p>', NULL, NULL, '2024-11-21 16:30:29', '2024-11-21 16:30:29', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1434, 433, 4, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan.</em></p>', NULL, NULL, '2024-11-21 16:30:40', '2024-11-21 16:30:40', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1435, 433, 5, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja dan melaporkan kepada pihak atasan serta turut memberi cara atau cara penyelesaian yang bermanfaat.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan serta turut memberi cara atau cara penyelesaian yang bermanfaat.</em></p>', NULL, NULL, '2024-11-21 16:30:51', '2024-11-21 16:30:51', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1436, 434, 1, '<p>Menerima tugasan tetapi tidak memikul tanggungjawab kerja dan tidak dapat bekerja di bawah tekanan.<br /><br /><em>Contoh: Dia terima kerja yang diberi tetapi sentiasa bersembang dengan rakan sekerja dan tidak buat kerja sehingga tidak nampak hasil kerja.</em></p>', NULL, NULL, '2024-11-21 16:36:26', '2024-11-21 16:36:26', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1437, 434, 2, '<p>Boleh menerima dan memikul tanggungjawab dan cuba untuk bekerja di bawah tekanan tetapi kadangkala tidak dapat menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Dia boleh buat kerja dan cuba elakkan diri dari tidak masuk kerja/tidak memberi alasan untuk bercuti tetapi kadangkala masih perlu dalam bimbingan.</em></p>', NULL, NULL, '2024-11-21 16:36:45', '2024-11-21 16:36:45', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1438, 434, 3, '<p>Boleh menerima dan memikul tanggungjawab dan dapat menghabiskan setiap kerja yang diamanahkan dengan baik di bawah tekanan dan melaporkan kerja yang telah dilakukan kepada pegawai atasan.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia masih menepati target dan ikut piawai kerja yang ditetapkan oleh syarikat. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia juga akan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-21 16:36:54', '2024-11-21 16:36:54', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1439, 434, 4, '<p>Rela menerima dan memikul tanggungjawab dan sentiasa dapat menghasilkan kerja yang berkualiti di bawah tekanan dan dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang dilakukan kepada pegawai atasan.Boleh buat kerja lebih masa sehingga kerja siap.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia akan menawarkan diri secara sukarela untuk kerja tersebut serta menepati target dan ikut piawai kerja yang ditetapkan oleh syarikat. Boleh buat kerja lebih masa sehingga kerja siap. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-21 16:37:04', '2024-11-21 16:37:04', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1440, 434, 5, '<p>Rela menerima dan memikul tanggungjawab serta tahu kepentingan dan deadline kerja. Dapat memanggil rakan sekerja untuk menyiapkan kerja bersama. Sentiasa dapat menghasilkan kerja yang berkualiti di bawah tekanan dan dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang dilakukan kepada pegawai atasan.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia tahu kepentingan dan deadline kerja tersebut serta dapat memanggil rakan sekerja untuk menyiapkan kerja bersama. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-21 16:37:15', '2024-11-21 16:37:15', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1441, 435, 1, '<p>Tidak rela mengaku kesilapan dan suka menolak tanggungjawab kepada orang lain.<br /><br /><em>Contoh: Telah melakukan kesilapan seperti tidak mengikuti spesifikasi kerja yang diberi oleh Leader / tidak tanya Leader apabila tidak faham / tanya rakan sekerja yang tidak dipertanggungjawabkan dan tidak pernah mengakui kesilapan apabila ditegur oleh Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-21 16:37:42', '2024-11-21 16:37:42', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1442, 435, 2, '<p>Kadangkala tidak rela mengaku kesilapan dan suka membuat perbandingan diri dengan orang lain dalam kesilapan yang telah dibuat.<br /><br /><em>Contoh: Telah melakukan kesilapan seperti tidak mengikuti spesifikasi kerja yang diberi oleh Leader / tidak tanya Leader apabila tidak faham / tanya rakan sekerja yang tidak dipertanggungjawabkan dan kadangkala tidak mengakui kesilapan apabila ditegur oleh Leader/Supervisor malah menyatakan Leader/Supervisor ada prasangka terhadap dia.</em></p>', NULL, NULL, '2024-11-21 16:37:52', '2024-11-21 16:37:52', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1443, 435, 3, '<p>Mengaku kesilapan dan tidak menolak tanggungjawab kepada orang lain.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan. Dia terima dan mengakui kesilapan.</em></p>', NULL, NULL, '2024-11-21 16:38:09', '2024-11-21 16:38:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1444, 435, 4, '<p>Tidak melarikan diri dari tanggungjawab dan terus berjumpa dengan pihak atasan untuk mengakui kesilapan dan berinisiatif untuk memperbaiki kesilapan yang telah dilakukan.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan. Dia tidak melarikan diri dari tanggungjawab dan terus berjumpa dengan Leader/Supervisor dan mengakui kesilapan. Selain itu, dia juga memberi cadangan dan sama-sama memperbaiki kesilapan yang telah dilakukan.</em></p>', NULL, NULL, '2024-11-21 16:38:21', '2024-11-21 16:38:21', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1445, 435, 5, '<p>Berani mengaku kesilapan dan tidak menolak tanggungjawab dan memastikan kesilapan tidak berlaku lagi. Berinisiatif untuk memperbetulkan kesilapan dan dapat memberi cadangan yang bermanfaat untuk mengelakkan kesilapan berlaku lagi.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan yang agak besar. Dia berani mengakui kesilapan dan terus berjumpa dengan Leader/Supervisor untuk mengakui kesilapan. Dia mengambil pengalaman tersebut sebagai satu pengajaran dan tidak mengulangi kesilapan tersebut lagi. Selain itu, dia &nbsp;memberi cadangan dan sama-sama memperbaiki kesilapan yang telah dilakukan serta memberi cadangan yang bermanfaat untuk mengelakkan kesilapan berlaku lagi.</em></p>', NULL, NULL, '2024-11-21 16:38:32', '2024-11-21 16:38:32', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1446, 436, 1, '<p>Membuat kerja alah kadar dan setakat membuat kerja sahaja dan tidak menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Tidak menunjukkan sikap ingin belajar dan tidak menumpukan perhatian semasa bekerja seperti dia boleh mengambil masa yang panjang untuk memasang beberapa nut pada mesin.</em></p>', NULL, NULL, '2024-11-21 16:39:43', '2024-11-21 16:39:43', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1447, 436, 2, '<p>Boleh membuat kerja tetapi mudah dipengaruhi orang lain dan kadangkala tidak dapat menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Dia boleh pasang nut pada mesin tetapi mudah dipengaruhi oleh rakan sekerja yang lain seperti dia akan melambatkan proses kerjanya dan sambil kerja sambil bersembang apabila ada rakan sekerja yang bersembang dengannya semasa bekerja.</em></p>', NULL, NULL, '2024-11-21 16:39:54', '2024-11-21 16:39:54', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1448, 436, 3, '<p>Lebih agresif dan sikap kerja juga serius dan dapat menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak mengangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja.</em></p>', NULL, NULL, '2024-11-21 16:40:06', '2024-11-21 16:40:06', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1449, 436, 4, '<p>Bersemangat kerja dan menumpukan perhatian sepenuhnya dalam kerja. Sentiasa mengutamakan kualiti kerja dan menghasilkan kerja yang halus dan teliti dan tidak melakukan kesilapan.<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak menggangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja. Dia sentiasa mengutamakan kualiti kerja dan memastikan nut yang dipasang itu betul dan kemas.</em></p>', NULL, NULL, '2024-11-21 16:40:20', '2024-11-21 16:40:20', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1450, 436, 5, '<p>Matlamat untuk berjaya sangat jelas. Menumpukan perhatian sepenuhnya dalam kerja. Sentiasa mengutamakan kualiti kerja dan menghasilkan kerja yang halus dan teliti dan tidak melakukan kesilapan. Selain itu turut memberi cadangan dan cara kerja untuk memastikan kerja berkualiti dihasilkan setiap kali.&nbsp;<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak menggangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja. Dia sentiasa mengutamakan kualiti kerja dan memastikan nut yang dipasang itu betul dan kemas. Selain itu, dia juga akan memberi cadangan untuk memastikan kerja berkualiti dapat dihasilkan.</em></p>', NULL, NULL, '2024-11-21 16:40:46', '2024-11-21 16:40:46', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1451, 437, 1, '<p>Langsung tidak mahu memahami dan menerima peraturan dan polisi syarikat dan sentiasa membuat aduan terhadap dasar syarikat.<br /><br /><em>Contoh: Selalu tidak menutup lampu setelah mengguna tandas dan membuat aduan apabila pihak syarikat mengambil tindakan.</em></p>', NULL, NULL, '2024-11-21 16:41:26', '2024-11-21 16:41:26', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1452, 437, 2, '<p>Kadangkala sahaja mahu menerima dan mematuhi peraturan dan polisi syarikat.<br /><br /><em>Contoh: Kadangkala ada menutup lampu setelah mengguna tandas kadangkala tidak.</em></p>', NULL, NULL, '2024-11-21 16:41:37', '2024-11-21 16:41:37', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1453, 437, 3, '<p>Menerima dan mematuhi setiap peraturan dan polisi syarikat.<br /><br /><em>Contoh: Setiap kali akan menutup lampu setelah mengguna tandas.</em></p>', NULL, NULL, '2024-11-21 16:41:47', '2024-11-21 16:41:47', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1454, 437, 4, '<p>Tidak melanggar peraturan dan sentiasa dapat menasihatkan rakan sekerja untuk menerima dan mematuhi peraturan dan polisi syarikat untuk kebaikan bersama.<br /><br /><em>Contoh: Sentiasa menutup lampu setelah mengguna tandas dan &nbsp;menasihati dan menerang kepada rakan sekerja yang tidak mematuhi peraturan.</em></p>', NULL, NULL, '2024-11-21 16:41:58', '2024-11-21 16:41:58', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1455, 437, 5, '<p>Memahami dan menerima setiap peraturan dan polisi syarikat dan sentiasa menasihatkan rakan sekerja yang melanggar peraturan serta melaporkan masalah disiplin kepada pegawai atasan untuk kebaikan bersama.<br /><br /><em>Contoh: &nbsp;Sentiasa menutup lampu setelah mengguna tandas dan &nbsp;menasihati dan menerang kepada rakan sekerja yang tidak mematuhi peraturan. Selain itu, juga akan melaporkan nama pekerja yang tidak menutup lampu setelah mengguna tandas.</em></p>', NULL, NULL, '2024-11-21 16:42:10', '2024-11-21 16:42:10', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1456, 438, 1, '<p>Selalu tidak tepat masuk kerja dan menunjukkan kedatangan yang tidak baik.<br /><br /><em>Contoh: Masih berada di tempat berehat semasa siren berbunyi dan jalan perlahan ke tempat kerja.</em></p>', NULL, NULL, '2024-11-21 16:43:02', '2024-11-21 16:43:02', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1457, 438, 2, '<p>Kadangkala ada masuk kerja pada masa yang ditetapkan tetapi keadaan tidak ketara.<br /><br /><em>Contoh: Kadangkala ada tepat masuk kerja semasa siren berbunyi tetapi kebanyakan masa tidak masuk kerja pada masa yang tepat.</em></p>', NULL, NULL, '2024-11-21 16:43:16', '2024-11-21 16:43:16', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1458, 438, 3, '<p>Kebanyakan masa masuk kerja pada masa yang ditetapkan tetapi kadangkala ada lewat juga.<br /><br /><em>Contoh: Kebanyakan masa masuk kerja semasa siren berbunyi tetapi sekali kala masih lewat masuk kerja.</em></p>', NULL, NULL, '2024-11-21 16:43:30', '2024-11-21 16:43:30', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1459, 438, 4, '<p>Mementingkan ketepatan masa masuk kerja dan masuk kerja tepat pada masa atau lebih awal.<br /><br /><em>Contoh: Sentiasa masa masuk kerja sebelum siren berbunyi atau lebih awal.</em></p>', NULL, NULL, '2024-11-21 16:43:42', '2024-11-21 16:43:42', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1460, 438, 5, '<p>Mementingkan ketepatan masa masuk kerja dan masuk kerja tepat pada masa atau lebih awal serta memberi nasihat kepada rakan sekerja yang lewat.<br /><br /><em>Contoh: Sentiasa masa masuk kerja sebelum siren berbunyi atau lebih awal serta memberi nasihat kepada rakan sekerja yang lewat.</em></p>', NULL, NULL, '2024-11-21 16:43:52', '2024-11-21 16:43:52', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1461, 439, 1, '<p>Disiplin diri yang tidak memuaskan dan sering meninggalkan tempat kerja dengan berkeliaran tanpa tujuan dan sering membazirkan masa serta curi tulang.<br /><br /><em>Contoh: Sering meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja (banyak kali sehari) dan mengambil masa yang panjang dalam tandas serta membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-21 16:44:52', '2024-11-21 16:44:52', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1462, 439, 2, '<p>Kadangkala membazirkan masa dan curi tulang serta meninggalkan tempat kerja dengan berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Kadangkala meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja (banyak kali sehari) dan mengambil masa yang panjang dalam tandas serta membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-21 16:45:05', '2024-11-21 16:45:05', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1463, 439, 3, '<p>Tidak membazirkan masa dan ringan tulang serta menumpukan perhatian semasa bekerja. Tidak meninggalkan tempat kerja dengan berkeliaran tanpa tujuan.<br /><br /><em>Contoh: Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-21 16:45:22', '2024-11-21 16:45:22', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1464, 439, 4, '<p>Teladan yang baik dan tumpuan perhatian sepenuhnya semasa bekerja. Tidak berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Seorang teladan yang baik dan memberi tumpuan sepenuhnya semasa bekerja. Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-21 16:45:35', '2024-11-21 16:45:35', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1465, 439, 5, '<p>Teladan yang baik dan tumpuan perhatian sepenuhnya semasa bekerja dan juga selalu memberi nasihat kepada rakan sekerja supaya melahirkan keadaan kerja yang lebih agresif. Tidak berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Seorang teladan yang baik dan memberi tumpuan sepenuhnya semasa bekerja. Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja. Selalu memberi nasihat kepada rakan sekerja yang selalu pergi ke tandas sebagai alasan.</em></p>', NULL, NULL, '2024-11-21 16:45:49', '2024-11-21 16:45:49', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1466, 440, 1, '<p>Tidak pernah berada di tempat kerja semasa pembersihan kawasan dijalankan.<br /><br /><em>Contoh: Tidak berada di tempat kerja dan pergi ke tandas semasa pembersihan kawasan dijalankan.</em></p>', NULL, NULL, '2024-11-21 16:46:27', '2024-11-21 16:46:27', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1467, 440, 2, '<p>Memulakan kerja pembersihan kawasan walaupun masa yang ditetapkan belum sampai lagi.<br /><br /><em>Contoh: Memulakan kerja pembersihan kawasan walaupun masa yang ditetapkan belum sampai lagi dan rakan sekerja yang lain masih bekerja lagi.</em></p>', NULL, NULL, '2024-11-21 16:46:37', '2024-11-21 16:46:37', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1468, 440, 3, '<p>Kebanyakan masa membersihkan kawasan production pada masa yang ditetapkan.</p><p>Kadangkala membersihkan kawasan production pada masa yang ditetapkan tetapi keadaan tidak ketara.</p><p><br />\nContoh: Kadangkala ada berada di production semasa pembersihan kawasan dijalankan tetapi kebanyakan masa tidak nampak orang.</p>', NULL, NULL, '2024-11-21 16:46:47', '2024-11-21 16:46:47', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1469, 440, 4, '<p>Sentiasa mengutamakan dan membersihkan kawasan production pada masa yang ditetapkan.<br /><br /><em>Contoh: Sentiasa membersihkan kawasan production pada masa yang ditetapkan.</em></p>', NULL, NULL, '2024-11-21 16:46:58', '2024-11-21 16:46:58', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1470, 440, 5, '<p>Mengutamakan dan membersihkan kawasan production pada masa yang ditetapkan serta memberi nasihat kepada rakan sekerja yang tidak berbuat demikian.<br /><br /><em>Contoh: Sentiasa membersihkan kawasan production pada masa yang ditetapkan dan memberi nasihat kepada rakan sekerja yang tidak berbuat demikian.</em></p>', NULL, NULL, '2024-11-21 16:47:11', '2024-11-21 16:47:11', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1471, 441, 1, '<p>Hanya menghormati pegawai atasan dan tidak bersopan dengan rakan sekerja.<br /><br /><em>Contoh: Hanya menghormati Leader/Supervisor atau pangkat kerja yang lebih tinggi tetapi tidak bersopan dengan rakan sekerja yang berpangkat rendah/masih baru.</em></p>', NULL, NULL, '2024-11-21 16:48:09', '2024-11-21 16:48:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1472, 441, 2, '<p>Biasanya akan bersopan dan menghormati orang lain tetapi kadangkala beremosi.<br /><br /><em>Contoh: Biasanya bersopan dan menghormati rakan sekerja yang lain tetapi kadangkala beremosi dan lawan cakap.</em></p>', NULL, NULL, '2024-11-21 16:48:18', '2024-11-21 16:48:18', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1473, 441, 3, '<p>Sering bersopan dan menghormati orang lain dan tidak bertindak mengikut perasaan.<br /><br /><em>Contoh: Sering bersopan dan menghormati rakan sekerja lain dan tidak bertindak mengikut perasaan.</em></p>', NULL, NULL, '2024-11-21 16:48:28', '2024-11-21 16:48:28', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1474, 441, 4, '<p>Bersopan dan menghormati orang lain pada setiap masa dan tidak bertindak mengikut perasaan dan berbahasa sopan.<br /><br /><em>Contoh: Bersopan dan setiap masa menghormati rakan sekerja yang lain dan tidak bertindak mengikut perasaan dan berbahasa sopan serta jaga perasaan rakan lain.</em></p>', NULL, NULL, '2024-11-21 16:48:41', '2024-11-21 16:48:41', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1475, 441, 5, '<p>Bersopan dan menghormati orang lain pada setiap masa dan masih bercakap dengan sopan walaupun sendiri telah dipersalahkan dalam proses penyelesaian masalah.<br /><br /><em>Contoh: Bersopan dan setiap masa menghormati rakan sekerja yang lain dan masih bercakap dengan sopan walaupun sendiri telah dipersalahkan dalam proses penyelesaian masalah.</em></p>', NULL, NULL, '2024-11-21 16:48:52', '2024-11-21 16:48:52', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1476, 442, 1, '<p>Memang mengetahui arahan yang diberi mempunyai kesilapan tetapi tidak mendapatkan kepastian kerana berpendapat itu adalah tanggungjawab pegawai atasan.<br /><br /><em>Contoh: Tidak mendapatkan kepastian daripada Leader/Supervisor tentang spesifikasi kerja yang diberi walaupun sudah tahu arahan yang diberi mempunyai kesilapan/tidak jelas dan beranggap itu adalah tanggungjawab Leader/Supervisor dan bukan dia.</em></p>', NULL, NULL, '2024-11-21 16:49:38', '2024-11-21 16:49:38', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1477, 442, 2, '<p>Jarang berinisiatif untuk mendapatkan kepastian daripada pegawai atasan walaupun arahan yang diberi tidak jelas atau silap.<br /><br /><em>Contoh: Menunjukkan sikap sudah tahu tetapi tidak ingin peduli dan tidak mendapatkan kepastian daripada Leader/Supervisor walapun arahan yang diberi ada kesilapan/kurang jelas.</em></p>', NULL, NULL, '2024-11-21 16:49:56', '2024-11-21 16:49:56', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1478, 442, 3, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap tetapi tidak pernah melapor balik kepada pegawai atasan tentang tugasan tersebut.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi ada kesilapan/tidak jelas tetapi tidak pernah melapor balik tugasan tersebut.</em></p>', NULL, NULL, '2024-11-21 16:50:10', '2024-11-21 16:50:10', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1479, 442, 4, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap tetapi tidak pernah melapor balik kepada pegawai atasan tentang tugasan tersebut.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi ada kesilapan/tidak jelas tetapi tidak pernah melapor balik tugasan tersebut.</em></p>', NULL, NULL, '2024-11-21 16:51:01', '2024-11-21 16:51:01', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1480, 442, 5, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut serta memberi pendapat yang bermanfaat.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi tidak jelas/silap dan selalu melapor balik kepada Leader/Supervisor dan turut mengambil bahagian untuk memberi pendapat yang bermanfaat.</em></p>', NULL, NULL, '2024-11-21 16:51:36', '2024-11-21 16:51:36', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1481, 443, 1, '<p>Degil dan berpegang teguh dengan pendapat sendiri dan tidak menuruti arahan pegawai atasan.<br /><br /><em>Contoh: Tidak menerima dan melawan percakapan Leader/Supervisor semasa diberi tugasan.</em></p>', NULL, NULL, '2024-11-21 16:52:42', '2024-11-21 16:52:42', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1482, 443, 2, '<p>Kebanyakan masa akan menuruti arahan pegawai atasan tetapi kadangkala akan beremosi dan meluahkan ketidakpuasan.<br /><br /><em>Contoh: Kebanyakan masa akan menerima tugasan Leader/Supervisor dengan baik tetapi kadangkala tidak.</em></p>', NULL, NULL, '2024-11-21 16:52:54', '2024-11-21 16:52:54', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1483, 443, 3, '<p>Mengambil berat dan menuruti arahan pegawai atasan dan tidak pernah membuat hal sesuka hati.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati dan akan bertanya jika tidak faham.</em></p>', NULL, NULL, '2024-11-21 16:53:11', '2024-11-21 16:53:11', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1484, 443, 4, '<p>Mengambil berat dan menuruti arahan pegawai atasan dan tidak pernah membuat hal sesuka hati. Kadangkala turut memberikan pendapat yang bermanfaat dalan kerja yang diberi.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati dan akan bertanya jika tidak faham. Kadangkala turut memberi cadangan/pandangan dalam kerja yang diberi.</em></p>', NULL, NULL, '2024-11-21 16:53:21', '2024-11-21 16:53:21', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1485, 443, 5, '<p>Bersikap positif dan menuruti semua arahan pegawai atasan, tidak membuat hal malah dapat menyampaikan objektif dan kehendak arahan secara positif kepada semua rakan sekerja.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati. Turut menyampaikan maksud dan kehendak mengikuti arahan Leader/Supervisor secara positif kepada rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-21 16:53:32', '2024-11-21 16:53:32', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1486, 444, 1, '<p>Ego dan tidak sudi berbincang tugasan sesama rakan sekerja dan pegawai atasan, sangat keras kepala dan tidak dapat menerima cadangan orang lain.<br /><br /><em>Contoh: Buat kerja tanpa ikut pelan kerja seperti menebuk drill pada kelajuan yang tinggi dan telah membesarkan lubang 3mm kepada 3.20 mm. Dia tidak dapat menerima apabila diminta buat semula pada kelajuan drill yang rendah.</em></p>', NULL, NULL, '2024-11-21 16:54:28', '2024-11-21 16:54:28', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1487, 444, 2, '<p>Jarang berbincang tugasan sesama rakan sekerja dan pegawai atasan dan tidak begitu rela berkongsi maklumat, kadangkala keras kepala dan tidak dapat menerima cadangan orang lain.<br /><br /><em>Contoh: Dia menunjukkan sikap yang tidak begitu gembira apabila diminta buat semula pada kelajuan drill yang rendah.</em></p>', NULL, NULL, '2024-11-21 16:54:39', '2024-11-21 16:54:39', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1488, 444, 3, '<p>Sudi berbincang dan menerima cadangan rakan sekerja dan pegawai atasan, dapat memberi pertolongan apabila diminta.<br /><br /><em>Contoh: Dia sudi membuat semula pada kelajuan drill yang rendah setelah berbincang dan diminta berubah.</em></p>', NULL, NULL, '2024-11-21 16:54:49', '2024-11-21 16:54:49', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1489, 444, 4, '<p>Sudi berbincang dan berinisiatif memberi pertolongan sesama rakan sekerja dan pegawai atasan dengan tidak berkira kerja. Boleh menerima cadangan orang lain dan tidak berkeras kepala.<br /><br /><em>Contoh: Dia sudi membuat semula pada kelajuan drill yang rendah dan dia turut memberi cadangan untuk mengatasi masalah tersebut.</em></p>', NULL, NULL, '2024-11-21 16:55:11', '2024-11-21 16:55:11', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1490, 444, 5, '<p>Sudi berbincang dan berinisiatif memberi pertolongan sesama rakan sekerja dan pegawai atasan dengan tidak berkira kerja. Boleh menerima cadangan orang lain dan tidak berkeras kepala. Selain itu, turut boleh memanggil rakan sekerja untuk sama-sama menyiapkan kerja tersebut.<br /><br /><em>Contoh: Dia ialah orang yang sangat agresif dan sudi membuat semula dan dia turut boleh meminta rakan sekerja untuk sama-sama menyiapkan kerja.</em></p>', NULL, NULL, '2024-11-21 16:55:28', '2024-11-21 16:55:28', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1491, 445, 1, '<p>Menolak tugasan selain dari bidang sendiri dan langsung tidak dapat menerima tugasan tambahan atau di luar bidang kerja, amat mementingkan diri sendiri.<br /><br /><em>Contoh: Tidak mahu backup rakan sekerja yang bercuti dan selalu dipengaruhi oleh rakan sekerja yang lain dimana orang yang berbuat banyak tidak dapat apa-apa.</em></p>', NULL, NULL, '2024-11-21 16:55:51', '2024-11-21 16:55:51', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1492, 445, 2, '<p>Kadangkala menerima tugasan tambahan atau di luar bidang kerja tetapi dengan hati yang tidak rela dan mementingkan kepentingan diri sendiri.<br /><br /><em>Contoh: Kadangkala akan diminta untuk backup rakan sekerja yang bercuti tetapi dia akan membuat kerja secara tidak rela / memberi alasan bahawa dia tidak tahu buat kerja tersebut.</em></p>', NULL, NULL, '2024-11-21 16:56:04', '2024-11-21 16:56:04', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1493, 445, 3, '<p>Rela menerima tugasan tambahan atau di luar bidang dan tidak menolak apabila tugas diberi.<br /><br /><em>Contoh: Rela backup rakan sekerja yang bercuti dan tidak menolak apabila tugas diberi oleh Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-21 16:56:13', '2024-11-21 16:56:13', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1494, 445, 4, '<p>Rela menerima tugasan tambahan atau di luar bidang dan tidak menolak apabila tugas diberi serta cuba mencari cara untuk menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Rela backup rakan sekerja yang bercuti dan tidak menolak apabila tugas diberi oleh Leader / Supervisor. Selain itu, dia juga cari jalan untuk mengeluarkan hasil kerja yang baik / membuat kerja tersebut dengan bersungguh-sungguh.</em></p>', NULL, NULL, '2024-11-21 16:56:24', '2024-11-21 16:56:24', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1495, 445, 5, '<p>Amat rela menerima tugasan tambahan atau di luar bidang dan menerimanya sebagai satu cabaran. Berusaha dan bertanggungjawab sepenuhnya sehingga tugasan selesai dengan sempurna.<br /><br /><em>Contoh: Sangat rela backup rakan sekerja yang bercuti dan menganggap tugas yang diberi tersebut sebagai satu cabaran / tugas sendiri. Dia membuat kerja dengan sepenuh hati dan mengambil tanggungjawab sehingga tugasan tersebut selesai dengan sempurnanya.</em></p>', NULL, NULL, '2024-11-21 16:56:45', '2024-11-21 16:56:45', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1496, 458, 1, '<p>Tidak dapat menyiapkan tugasan mengikut masa yang ditetapkan dan selalu dibuat semula oleh rakan sekerja yang lain dan menyebabkan kelewatan.<br /><br /><em>Contoh: Kerja yang sepatutnya boleh disiapkan dalam sehari tetapi dia selalu tidak hadir bekerja dan kerjanya perlu disambung / dibuat semula oleh rakan sekerja yang lain dan menyebabkan kelewatan.</em></p>', NULL, NULL, '2024-11-21 17:34:13', '2024-11-21 17:34:13', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1497, 458, 2, '<p>Selalu mengambil masa yang panjang untuk menyiapkan kerja walaupun bimbingan sudah diberi.<br /><br /><em>Contoh: Kerja yang sepatutnya boleh disiapkan dalam sehari tetapi dia mengambil masa yang panjang walaupun bimbingan sudah diberi.</em></p>', NULL, NULL, '2024-11-21 17:34:26', '2024-11-21 17:34:26', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1498, 458, 3, '<p>Tugasan biasanya dapat disiapkan dengan sedikit bimbingan dan siap dalam masa yang ditetapkan mahupun lebih awal dan hasil kerja yang masih boleh diterima.<br /><br /><em>Contoh: Boleh menghasilkan kerja dalam masa yang ditetapkan tetapi masih perlu dalam pengawasan/bimbingan.</em></p>', NULL, NULL, '2024-11-21 17:34:38', '2024-11-21 17:34:38', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1499, 458, 4, '<p>Tugasan sentiasa disiapkan tanpa bimbingan dan mengikut jadual mahupun lebih awal dan hasil kerja yang agar memuaskan.<br /><br /><em>Contoh: Boleh menghasilkan kerja dalam masa yang pendek dan tanpa sebarang pengawasan/bimbingan seperti dia cuma perlu 5 jam untuk menghasilkan kerja yang dijangka siap dalam sehari dan dia boleh menghasilkan lebih dalam satu hari.</em></p>', NULL, NULL, '2024-11-21 17:34:49', '2024-11-21 17:34:49', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1500, 458, 5, '<p>Mengutamakan masa dan pantas dalam menyiapkan tugasan yang diberi dan hasil kerja sangat bagus dan boleh diharapkan.<br /><br /><em>Contoh:Boleh membuat apa kerja yang dirancang dan menepati masa yang ditetapkan atau lebih awal tanpa pengawasan/bimbingan. Individu yang teliti dan prihatin dan menguasa masa dan memberi hasil kerja yang sangat bagus dan halus.</em></p>', NULL, NULL, '2024-11-21 17:35:03', '2024-11-21 17:35:03', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1501, 459, 1, '<p>Suka menolak tanggungjawab kerja dan berpura-pura/berdiam diri walaupun tahu apa cara untuk membuat kerja/menyelesaikan masalah.<br /><br /><em>Contoh: Langsung tidak bergerak dan pakai duduk dan tunggu sahaja walaupun sudah diberi penjelasan dalam pelan kerja.</em></p>', NULL, NULL, '2024-11-21 17:35:46', '2024-11-21 17:35:46', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1502, 459, 2, '<p>Kadangkala menolak tanggungjawab kerja dan berpura-pura/berdiam diri walaupun tahu apa cara untuk membuat kerja/menyelesaikan masalah.<br /><br /><em>Contoh: Tidak berusaha untuk belajar dan memahami pembacaan pelan kerja dan ukuran serta memerlukan seseorang mengawasi di tepi dan selalu memberi penjelasan boleh baru dapat menghasilkan kerja yang ditugaskan.</em></p>', NULL, NULL, '2024-11-21 17:35:59', '2024-11-21 17:35:59', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1503, 459, 3, '<p>Sudah faham dan boleh terus bertindak/bergerak ke atas kerja yang telah diselesaikan.&nbsp;<br /><br /><em>Contoh: Sudah tahu membuat kerja/menyelesaikan masalah dan tidak menolak tanggungjawab.</em></p>', NULL, NULL, '2024-11-21 17:36:14', '2024-11-21 17:36:14', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1504, 459, 4, '<p>Sudah faham dan boleh bertindak cepat ke atas semua tugasan serta tidak perlu pengawasan/bimbingan dan akan lapor balik apabila kerja telah siap.<br /><br /><em>Contoh: Bertanggungjawab dan tidak berpura-pura atau berdiam diri dalam membuat kerja/menyelesaikan masalah dan tidak perlu pengawasan/bimbingan dan akan bertindak/bergerak ke atas kerja yang ditugaskan serta lapor balik apabila kerja telah siap.</em></p>', NULL, NULL, '2024-11-21 17:36:32', '2024-11-21 17:36:32', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1505, 459, 5, '<p>Sudah faham dan boleh bertindak cepat ke atas semua tugasan serta tidak perlu pengawasan/bimbingan dan akan lapor balik apabila kerja telah siap. Selain itu, dapat memberi nasihat kepada rakan sekerja yang lain supaya cepat bertindak dalam kerja.<br /><br /><em>Contoh: Bertanggungjawab dan tidak berpura-pura atau berdiam diri dalam membuat kerja/menyelesaikan masalah dan tidak perlu pengawasan/bimbingan dan akan bertindak/bergerak ke atas kerja yang ditugaskan serta lapor balik apabila kerja telah siap. Selain itu, juga memotivasikan rakan sekerja supaya tidak berpura-pura/berdiam diri dalam &nbsp;membuat kerja/menyelesaikan masalah.</em></p>', NULL, NULL, '2024-11-21 17:36:49', '2024-11-21 17:36:49', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1506, 460, 1, '<p>Tidak membuat kerja secara sistematik dan tidak tahu membezakan kepentingan kerja.<br /><br /><em>Contoh: Tidak tahu membezakan kepentingan kerja dan tidak buat perancangan kerja.</em></p>', NULL, NULL, '2024-11-21 17:37:37', '2024-11-21 17:37:37', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1507, 460, 2, '<p>Kadangkala ada membuat kerja secara sistematik dan kadangkala tahu membezakan kepentingan kerja tetapi keadaan tidak ketara.<br /><br /><em>Contoh: Kadangkala tahu membezakan kepentingan kerja dan buat perancangan kerja tetapi tidak selalu dan ikut mood sendiri.</em></p>', NULL, NULL, '2024-11-21 17:37:48', '2024-11-21 17:37:48', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1508, 460, 3, '<p>Tidak perlu seseorang mengawasi di tepi dan tahu membuat kerja secara sistematik dan tahu membezakan kepentingan kerja dengan penjelasan yang ringkas sahaja.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan memerlukan penjelasan kerja yang ringkas sahaja.</em></p>', NULL, NULL, '2024-11-21 17:38:00', '2024-11-21 17:38:00', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1509, 460, 4, '<p>Hanya memerlukan penjelasan yang ringkas dan tahu membuat kerja secara sistematik dan tahu membezakan kepentingan kerja. Berhati-hati dan tiada kesilapan dalam kerja yang dihasilkan.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan hanya memerlukan penjelasan kerja yang ringkas sahaja dan memberi tumpuan dalam kerja dan mengeluarkan hasil kerja yang baik.</em></p>', NULL, NULL, '2024-11-21 17:38:14', '2024-11-21 17:38:14', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1510, 460, 5, '<p>Hanya memerlukan penjelasan yang sangat ringkas sahaja untuk membuat kerja secara sistematik dan tahu membezakan kepentingan kerja dan dapat memberi tunjuk ajar kepada rakan sekerja.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan hanya memerlukan penjelasan kerja yang ringkas sahaja dan memberi tumpuan dalam kerja dan mengeluarkan hasil kerja yang baik dan turut memberi tunjuk ajar kepada rakan sekerja.</em></p>', NULL, NULL, '2024-11-21 17:38:25', '2024-11-21 17:38:25', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1511, 461, 1, '<p>Hasil kerja yang tidak boleh diterima dan selalu membuat kesilapan.<br /><br /><em>Contoh: Tidak menumpu perhatian semasa bekerja dan selalu membuat kesilapan yang sama. Tidak pernah berubah walaupun &nbsp;sudah diberi bimbingan/teguran seperti selalu mengulangi kesilapan yang sama walaupun sudah banyak kali memasang mesin yang sama model.</em></p>', NULL, NULL, '2024-11-21 17:39:17', '2024-11-21 17:39:17', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1512, 461, 2, '<p>Cuai dan mengakibatkan kesilapan kerja.<br /><br /><em>Contoh: Kadangkala cuai semasa bekerja dan mengakibatkan kesilapan kerja kerana tindakan yang lambat untuk berubah setelah diberi bimbingan/teguran.</em></p>', NULL, NULL, '2024-11-21 17:39:28', '2024-11-21 17:39:28', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1513, 461, 3, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan meminimumkan tahap kesilapan kepada yang terendah.<br /><br /><em>Contoh: Kadangkala ada membuat kesilapan tetapi mengambil tindakan yang cepat untuk berubah setelah diberi bimbingan/teguran.</em></p>', NULL, NULL, '2024-11-21 17:39:38', '2024-11-21 17:39:38', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1514, 461, 4, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan apa-apa kesilapan dalam kerja harian.<br /><br /><em>Contoh: Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan. Selain itu, juga berinisiatif untuk menjaga barangan/bahan dan tidak membazir.</em></p>', NULL, NULL, '2024-11-21 17:39:48', '2024-11-21 17:39:48', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1515, 461, 5, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan kerja dan berinisiatif untuk memberi pendapat dan memperbaiki cara kerja yang lebih baik untuk meminimumkan tahap kesilapan kerja.<br /><br /><em>Contoh: Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan dan berinisiatif untuk memberi pendapat dan memperbaiki cara kerja untuk meminimumkan tahap kesilapan kerja seperti berinisiatif untuk mengetahui masalah semasa pemasangan mesin dan turut memberi pendapat untuk memperbaiki cara kerja/menyelesaikan masalah.</em></p>', NULL, NULL, '2024-11-21 17:40:00', '2024-11-21 17:40:00', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1516, 462, 1, '<p>Langsung tidak memahami permintaan kualiti kerja dan tidak memberi perhatian kepada kerja yang dilakukan.<br /><br /><em>Contoh: Langsung tidak memahami permintaan kualiti kerja dan tidak memberi perhatian terhadap semua kerja yang dilakukan seperti membuat pemasangan Control Panel tetapi langsung tidak mengikut diagram yang diberi.</em></p>', NULL, NULL, '2024-11-21 17:40:30', '2024-11-21 17:40:30', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1517, 462, 2, '<p>Kadangkala tidak faham spesifikasi kerja yang diberi dan tidak berinisiatif mengambil langkah untuk mengetahui untuk menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Tidak berinisiatif untuk bertanya/kurang bertanya apabila tidak tahu semasa memasang Control Panel dan pasang ikut sendiri dan tidak ikut cara kerja yang betul.</em></p>', NULL, NULL, '2024-11-21 17:40:41', '2024-11-21 17:40:41', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1518, 462, 3, '<p>Memahami permintaan kualiti kerja dan dapat menghasilkan kerja yang berkualiti secara individu tanpa pengawasan pegawai atasan tetapi tidak mengambil perhatian dan abaikan kerja yang remeh temeh serta tidak mengambil perhatian terhadap kekemasan hasil kerja.<br /><br /><em>Contoh: Tahu pasang Control Panel tetapi tidak terfikir tentang kekemasan. Wayar sudah ditarik dengan betul tetapi tidak diikat dengan cable tie/tidak tersusun/tidak label semasa membuat pemasangan.</em></p>', NULL, NULL, '2024-11-21 17:40:51', '2024-11-21 17:40:51', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1519, 462, 4, '<p>Faham tentang kualiti dan dapat menghasilkan kerja yang berkualiti dan memenuhi kehendak syarikat dan dapat memastikan kerja yang dihasilkan tidak bermasalah.<br /><br /><em>Contoh: Faham tentang kualiti kerja dan ikut semua spesifikasi yang diminta. Boleh berfikir dan nampak (meramalkan) ke hadapan dan memastikan kerja yang dihasilkan tidak bermasalah seperti tahu pasang Control Panel dan semua litar boleh berfungsi dengan baik dan pemasangan yang kemas dan melaporkan keadaan kepada Leader/Supervisor apabila litar tidak berfungsi/bernyala.</em></p>', NULL, NULL, '2024-11-21 17:41:09', '2024-11-21 17:41:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1520, 462, 5, '<p>Sangat faham tentang kualiti kerja dan dapat menghasilkan kerja yang berkualiti dan memenuhi kehendak syarikat dan dapat memastikan kerja yang dihasilkan tidak bermasalah serta turut memberi tunjuk ajar kepada rakan kerja yang lain.&nbsp;<br /><br /><em>Contoh: Sangat faham tentang kualiti kerja dan ikut semua spesifikasi yang diminta. Boleh berfikir dan nampak (meramalkan) ke hadapan dan memastikan kerja yang dihasilkan tidak bermasalah. Selain itu, juga dapat memberi tunjuk ajar kepada rakan sekerja yang lain seperti tahu pasang Control Panel dan semua litar boleh berfungsi dengan baik dan pemasangan yang kemas dan melaporkan keadaan kepada Leader/Supervisor apabila litar tidak berfungsi/bernyala. Selain itu, dia juga memberi tunjuk ajar kepada rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-21 17:42:49', '2024-11-21 17:42:49', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1521, 463, 1, '<p>Sentiasa membazirkan/merosakkan sumber syarikat.<br /><br /><em>Contoh: Tidak pernah berhati-hati dalam spesifikasi kerja yang diberi dan sentiasa mengakibatkan pembaziran bahan.</em></p>', NULL, NULL, '2024-11-21 17:43:20', '2024-11-21 17:43:20', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1522, 463, 2, '<p>Ada bersikap mahu menjimatkan sumber syarikat tetapi kadangkala menyebabkan pembaziran di atas kecuaiannya.<br /><br /><em>Contoh: Cuai dalam pembacaan spesifikasi kerja yang diberi dan silap ambil bahan dan menyebabkan kesilapan dan membazirkan bahan serta perlu &ldquo;rework&rdquo;.</em></p>', NULL, NULL, '2024-11-21 17:43:32', '2024-11-21 17:43:32', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1523, 463, 3, '<p>Berhati-hati semasa bekerja dan menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dan memastikan betul supaya tidak berlaku kesilapan yang mengakibatkan pembaziran bahan dan buang masa.</em></p>', NULL, NULL, '2024-11-21 17:43:41', '2024-11-21 17:43:41', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1524, 463, 4, '<p>Berhati-hati semasa bekerja dan berinisiatif menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya. Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dengan pelan kerja dan memastikan semua barang yang ambil adalah betul. Ada pemikiran tidak membazir seperti dalam menghasilkan sesuatu barang yang sangat kecil, dia akan cari scrap dahulu dan tidak guna bahan yang baru atau bahan yang besar.Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan.</em></p>', NULL, NULL, '2024-11-21 17:43:56', '2024-11-21 17:43:56', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1525, 463, 5, '<p>Berhati-hati semasa bekerja dan berinisiatif menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya. Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan dan juga menyedarkan dan membetulkan kesilapan rakan sekerja yang lain.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dengan pelan kerja dan memastikan semua barang yang ambil adalah betul. Ada pemikiran tidak membazir seperti dalam menghasilkan sesuatu barang yang sangat kecil, dia akan cari scrap dahulu dan tidak guna bahan yang baru atau bahan yang besar.Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan dan menyedarkan dan membetulkan kesilapan rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-21 17:44:12', '2024-11-21 17:44:12', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1526, 464, 1, '<p>Pengetahuan atau kemahiran adalah terhad dan tidak dapat menyelesaikan tugasan dan menggunakan masa yang panjang untuk mempelajari pengetahuan dan cara kerja yang agak senang.<br /><br /><em>Contoh: Tidak ada pengetahuan dan kemahiran kerja dan menggunakan masa yang panjang untuk mempelajari cara kerja yang senang walaupun bimbingan telah diberi seperti membuat kerja kimpalan yang paling senang iaitu mengimpal besi dalam kedudukan rata.</em></p>', NULL, NULL, '2024-11-21 17:44:57', '2024-11-21 17:44:57', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1527, 464, 2, '<p>Kurang pengetahuan atau kemahiran yang cukup untuk mengendalikan tugasan.<br /><br /><em>Contoh: Hasil kimpalan yang teruk dan bimbingan masih diperlukan walaupun diminta menghasilkan kerja kimpalan yang agak senang seperti mengimpal besi dalam kedudukan rata dan mendatar.</em></p>', NULL, NULL, '2024-11-21 17:45:07', '2024-11-21 17:45:07', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1528, 464, 3, '<p>Mempunyai pengetahuan dan kemahiran untuk mengendalikan tugasan dan mempunyai sikap mahu belajar dan mempelajari pengetahuan kerja yang baru dalam masa yang singkat dan mengimplikasikan dalam kerja harian.<br /><br /><em>Contoh: Ada pengetahuan dan kemahiran kimpalan tetapi tidak dapat meneruskan kerja apabila menghadapi kerja yang tidak biasa dan memerlukan bimbingan seperti: boleh mengimpal besi yang nipis tetapi tidak apabila diminta mengimpal besi yang lagi nipis / boleh mengimpal dalam kedudukan rata, mendatar dan menegak tetapi tidak apabila dalam keadaan overhead atau dalam keadaan 45 darjah.</em></p>', NULL, NULL, '2024-11-21 17:45:21', '2024-11-21 17:45:21', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1529, 464, 4, '<p>Boleh menguasai pengetahuan dan kemahiran untuk mengendalikan tugasan dan pencapaian yang agak memuaskan dan dapat menggunakan pengetahuannya untuk meningkatkan kualiti kerja.<br /><br /><em>Contoh: Mempunyai pengetahuan dan kemahiran yang luas serta jelas dengan semua keperluan/permintaan kerja seperti memilih kaedah yang bersesuaian untuk menghasilkan kerja dan tahu mengawal had api untuk mencegah hasil kerja dari kerosakan.</em></p>', NULL, NULL, '2024-11-21 17:45:35', '2024-11-21 17:45:35', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1530, 464, 5, '<p>Menguasai pengetahuan dan kemahiran untuk mengendalikan tugasan dan boleh menggabungkan pengetahuan untuk meningkatkan kualiti kerja serta mencari cara kerja baru untuk menyelesaikan masalah kerja dengan pengetahuannya.<br /><br /><em>Contoh: Mempunyai pengetahuan dan kemahiran yang luas serta jelas dengan semua keperluan/permintaan kerja dan berinisiatif memberi cadangan untuk menyelesaikan masalah kerja.&nbsp;</em></p>', NULL, NULL, '2024-11-21 17:45:45', '2024-11-21 17:45:45', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1531, 465, 1, '<p>Tidak pernah mengemas dan membersihkan tempat kerja sendiri dan sentiasa mengotorkan tempat kerja sendiri dan rakan sekerja yang lain.<br /><br /><em>Contoh: Tidak pernah terfikir kebaikan bersama dan terus membuang sisa kerja ke lantai dan menganggap ini kerja cleaner untuk membersihkan.</em></p>', NULL, NULL, '2024-11-21 17:46:31', '2024-11-21 17:46:31', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1532, 465, 2, '<p>Kadangkala ada mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya tidak kemas.<br /><br /><em>Contoh: Tidak selalu mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya tidak kemas seperti kadangkala ada membersihkan tempat kerja dan kadangkala tidak.</em></p>', NULL, NULL, '2024-11-21 17:46:41', '2024-11-21 17:46:41', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1533, 465, 3, '<p>Berinisiatif untuk mengemas dan membersihkan tempat kerja dan kebanyakan masa tempat kerjanya adalah kemas dan bersih.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai.</em></p>', NULL, NULL, '2024-11-21 17:47:03', '2024-11-21 17:47:03', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1534, 465, 4, '<p>Selalu mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya kemas dan selalu menolong membersihkan kawasan bahagiannya (division) dan kilang.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai serta tolong membersihkan kawasan yang lain.</em></p>', NULL, NULL, '2024-11-21 17:47:16', '2024-11-21 17:47:16', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1535, 465, 5, '<p>Selalu mengemas dan membersihkan tempat kerja dan tempat kerjanya kelihatan kemas dan bersih. Juga selalu menjaga kebersihan seluruh kawasan kilang dan dapat menegur rakan sekerja untuk menjaga kebersihan kilang.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai serta tolong menjaga kebersihan kawasan yang lain dan menegur rakan sekerja yang tidak menjaga kebersihan kilang.</em></p>', NULL, NULL, '2024-11-21 17:47:29', '2024-11-21 17:47:29', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1536, 466, 1, '<p>Tidak menjaga peralatan dan kemudahan syarikat.<br /><br /><em>Contoh: Tidak menjaga peralatan dan kemudahan syarikat seperti tidak menjaga forklift dan tidak pernah meletakkkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-21 17:47:49', '2024-11-21 17:47:49', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1537, 466, 2, '<p>Kadangkala bersikap cuai dalam mengendali peralatan dan kemudahan syarikat dan mengakibatkan kerosakan.<br /><br /><em>Contoh: Tidak selalu menjaga peralatan dan kemudahan syarikat dan mengakibatkan kerosakan seperti forklift terus jalan setelah enjin dihidupkan. Tidak mengambil berat tentang barang yang diangkat dan masuk ke ruang yang kecil. Selalu tidak meletakkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-21 17:48:04', '2024-11-21 17:48:04', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1538, 466, 3, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat dengan cara yang betul.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-21 17:48:20', '2024-11-21 17:48:37', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1539, 466, 4, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat demi kebaikan bersama. Selain itu, &nbsp;melaporkan kepada pihak atasan bila nampak rakan sekerja salahguna dan memberi cara penyelesaian yang bermanfaat.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna dan melapor jika ada kerosakan dan memberi cadangan untuk memperbaiki cara penggunaan dan penjagaan alatan.</em></p>', NULL, NULL, '2024-11-21 17:48:57', '2024-11-21 17:48:57', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1540, 466, 5, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat demi kebaikan bersama. Selain itu, &nbsp;melaporkan kepada pihak atasan bila nampak pekerja salahguna dan memberi cara penyelesaian yang bermanfaat. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna dan melapor jika ada kerosakan dan memberi cadangan untuk memperbaiki cara penggunaan dan penjagaan alatan.Selain itu, akan menyedarkan dan menasihati rakan sekerja yang tidak menjaga forklift semasa mengguna.</em></p>', NULL, NULL, '2024-11-21 17:49:08', '2024-11-21 17:49:08', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1541, 467, 1, '<p>Tidak mengutamakan keselamatan semasa bekerja.<br /><br /><em>Contoh: Tidak mengutamakan keselamatan semasa bekerja seperti tidak memakai PPE semasa bekerja.</em></p>', NULL, NULL, '2024-11-21 17:49:51', '2024-11-21 17:49:51', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1542, 467, 2, '<p>Ada sikap mengutamakan keselamatan tetapi kadangkala tidak.<br /><br /><em>Contoh: Ada memakai PPE semasa bekerja tetapi kadangkala tidak.</em></p>', NULL, NULL, '2024-11-21 17:50:00', '2024-11-21 17:50:00', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1543, 467, 3, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja.</em></p>', NULL, NULL, '2024-11-21 17:50:11', '2024-11-21 17:50:11', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1544, 467, 4, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan.</em></p>', NULL, NULL, '2024-11-21 17:50:27', '2024-11-21 17:50:27', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1545, 467, 5, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja dan melaporkan kepada pihak atasan serta turut memberi cara atau cara penyelesaian yang bermanfaat.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan serta turut memberi cara atau cara penyelesaian yang bermanfaat.</em></p>', NULL, NULL, '2024-11-21 17:50:45', '2024-11-21 17:50:45', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1546, 468, 1, '<p>Menerima tugasan tetapi tidak memikul tanggungjawab kerja dan tidak dapat bekerja di bawah tekanan.<br /><br /><em>Contoh: Dia terima kerja yang diberi tetapi sentiasa bersembang dengan rakan sekerja dan tidak buat kerja sehingga tidak nampak hasil kerja.</em></p>', NULL, NULL, '2024-11-21 17:51:24', '2024-11-21 17:51:24', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1547, 468, 2, '<p>Boleh menerima dan memikul tanggungjawab dan cuba untuk bekerja di bawah tekanan tetapi kadangkala tidak dapat menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Dia boleh buat kerja dan cuba elakkan diri dari tidak masuk kerja/tidak memberi alasan untuk bercuti tetapi kadangkala masih perlu dalam bimbingan.</em></p>', NULL, NULL, '2024-11-21 17:51:36', '2024-11-21 17:51:36', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1548, 468, 3, '<p>Boleh menerima dan memikul tanggungjawab dan dapat menghabiskan setiap kerja yang diamanahkan dengan baik di bawah tekanan dan melaporkan kerja yang telah dilakukan kepada pegawai atasan.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia masih menepati target dan ikut piawai kerja yang ditetapkan oleh syarikat. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia juga akan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-21 17:51:46', '2024-11-21 17:51:46', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1549, 468, 4, '<p>Rela menerima dan memikul tanggungjawab dan sentiasa dapat menghasilkan kerja yang berkualiti di bawah tekanan dan dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang dilakukan kepada pegawai atasan.Boleh buat kerja lebih masa sehingga kerja siap.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia akan menawarkan diri secara sukarela untuk kerja tersebut serta menepati target dan ikut piawai kerja yang ditetapkan oleh syarikat. Boleh buat kerja lebih masa sehingga kerja siap. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-21 17:52:01', '2024-11-21 17:52:01', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1550, 468, 5, '<p>Rela menerima dan memikul tanggungjawab serta tahu kepentingan dan deadline kerja. Dapat memanggil rakan sekerja untuk menyiapkan kerja bersama. Sentiasa dapat menghasilkan kerja yang berkualiti di bawah tekanan dan dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang dilakukan kepada pegawai atasan.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia tahu kepentingan dan deadline kerja tersebut serta dapat memanggil rakan sekerja untuk menyiapkan kerja bersama. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-21 17:52:11', '2024-11-21 17:52:11', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1551, 469, 1, '<p>Tidak rela mengaku kesilapan dan suka menolak tanggungjawab kepada orang lain.<br /><br /><em>Contoh: Telah melakukan kesilapan seperti tidak mengikuti spesifikasi kerja yang diberi oleh Leader / tidak tanya Leader apabila tidak faham / tanya rakan sekerja yang tidak dipertanggungjawabkan dan tidak pernah mengakui kesilapan apabila ditegur oleh Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-21 17:53:08', '2024-11-21 17:53:08', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1552, 469, 2, '<p>Kadangkala tidak rela mengaku kesilapan dan suka membuat perbandingan diri dengan orang lain dalam kesilapan yang telah dibuat.<br /><br /><em>Contoh: Telah melakukan kesilapan seperti tidak mengikuti spesifikasi kerja yang diberi oleh Leader / tidak tanya Leader apabila tidak faham / tanya rakan sekerja yang tidak dipertanggungjawabkan dan kadangkala tidak mengakui kesilapan apabila ditegur oleh Leader/Supervisor malah menyatakan Leader/Supervisor ada prasangka terhadap dia.</em></p>', NULL, NULL, '2024-11-21 17:53:18', '2024-11-21 17:53:18', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1553, 469, 3, '<p>Mengaku kesilapan dan tidak menolak tanggungjawab kepada orang lain.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan. Dia terima dan mengakui kesilapan.</em></p>', NULL, NULL, '2024-11-21 17:53:28', '2024-11-21 17:53:28', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1554, 469, 4, '<p>Tidak melarikan diri dari tanggungjawab dan terus berjumpa dengan pihak atasan untuk mengakui kesilapan dan berinisiatif untuk memperbaiki kesilapan yang telah dilakukan.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan. Dia tidak melarikan diri dari tanggungjawab dan terus berjumpa dengan Leader/Supervisor dan mengakui kesilapan. Selain itu, dia juga memberi cadangan dan sama-sama memperbaiki kesilapan yang telah dilakukan.</em></p>', NULL, NULL, '2024-11-21 17:53:40', '2024-11-21 17:53:40', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1555, 469, 5, '<p>Berani mengaku kesilapan dan tidak menolak tanggungjawab dan memastikan kesilapan tidak berlaku lagi. Berinisiatif untuk memperbetulkan kesilapan dan dapat memberi cadangan yang bermanfaat untuk mengelakkan kesilapan berlaku lagi.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan yang agak besar. Dia berani mengakui kesilapan dan terus berjumpa dengan Leader/Supervisor untuk mengakui kesilapan. Dia mengambil pengalaman tersebut sebagai satu pengajaran dan tidak mengulangi kesilapan tersebut lagi. Selain itu, dia &nbsp;memberi cadangan dan sama-sama memperbaiki kesilapan yang telah dilakukan serta memberi cadangan yang bermanfaat untuk mengelakkan kesilapan berlaku lagi.</em></p>', NULL, NULL, '2024-11-21 17:53:52', '2024-11-21 17:53:52', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1556, 470, 1, '<p>Membuat kerja alah kadar dan setakat membuat kerja sahaja dan tidak menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Tidak menunjukkan sikap ingin belajar dan tidak menumpukan perhatian semasa bekerja seperti dia boleh mengambil masa yang panjang untuk memasang beberapa nut pada mesin.</em></p>', NULL, NULL, '2024-11-21 17:54:32', '2024-11-21 17:54:32', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1557, 470, 2, '<p>Boleh membuat kerja tetapi mudah dipengaruhi orang lain dan kadangkala tidak dapat menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Dia boleh pasang nut pada mesin tetapi mudah dipengaruhi oleh rakan sekerja yang lain seperti dia akan melambatkan proses kerjanya dan sambil kerja sambil bersembang apabila ada rakan sekerja yang bersembang dengannya semasa bekerja.</em></p>', NULL, NULL, '2024-11-21 17:54:44', '2024-11-21 17:54:44', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1558, 470, 3, '<p>Lebih agresif dan sikap kerja juga serius dan dapat menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak mengangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja.</em></p>', NULL, NULL, '2024-11-21 17:54:55', '2024-11-21 17:54:55', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1559, 470, 4, '<p>Bersemangat kerja dan menumpukan perhatian sepenuhnya dalam kerja. Sentiasa mengutamakan kualiti kerja dan menghasilkan kerja yang halus dan teliti dan tidak melakukan kesilapan.<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak menggangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja. Dia sentiasa mengutamakan kualiti kerja dan memastikan nut yang dipasang itu betul dan kemas.</em></p>', NULL, NULL, '2024-11-21 17:55:07', '2024-11-21 17:55:07', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1560, 470, 5, '<p>Matlamat untuk berjaya sangat jelas. Menumpukan perhatian sepenuhnya dalam kerja. Sentiasa mengutamakan kualiti kerja dan menghasilkan kerja yang halus dan teliti dan tidak melakukan kesilapan. Selain itu turut memberi cadangan dan cara kerja untuk memastikan kerja berkualiti dihasilkan setiap kali.&nbsp;<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak menggangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja. Dia sentiasa mengutamakan kualiti kerja dan memastikan nut yang dipasang itu betul dan kemas. Selain itu, dia juga akan memberi cadangan untuk memastikan kerja berkualiti dapat dihasilkan.</em></p>', NULL, NULL, '2024-11-21 17:55:19', '2024-11-21 17:55:19', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1561, 471, 1, '<p>Langsung tidak mahu memahami dan menerima peraturan dan polisi syarikat dan sentiasa membuat aduan terhadap dasar syarikat.<br /><br /><em>Contoh: Selalu tidak menutup lampu setelah mengguna tandas dan membuat aduan apabila pihak syarikat mengambil tindakan.</em></p>', NULL, NULL, '2024-11-21 17:56:18', '2024-11-21 17:56:18', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1562, 471, 2, '<p>Kadangkala sahaja mahu menerima dan mematuhi peraturan dan polisi syarikat.<br /><br /><em>Contoh: Kadangkala ada menutup lampu setelah mengguna tandas kadangkala tidak.</em></p>', NULL, NULL, '2024-11-21 17:56:32', '2024-11-21 17:56:32', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1563, 471, 3, '<p>Menerima dan mematuhi setiap peraturan dan polisi syarikat.<br /><br /><em>Contoh: Setiap kali akan menutup lampu setelah mengguna tandas.</em></p>', NULL, NULL, '2024-11-21 17:56:42', '2024-11-21 17:57:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1564, 471, 4, '<p>Tidak melanggar peraturan dan sentiasa dapat menasihatkan rakan sekerja untuk menerima dan mematuhi peraturan dan polisi syarikat untuk kebaikan bersama.<br /><br /><em>Contoh: Sentiasa menutup lampu setelah mengguna tandas dan &nbsp;menasihati dan menerang kepada rakan sekerja yang tidak mematuhi peraturan.</em></p>', NULL, NULL, '2024-11-21 17:56:52', '2024-11-21 17:56:52', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1565, 471, 5, '<p>Memahami dan menerima setiap peraturan dan polisi syarikat dan sentiasa menasihatkan rakan sekerja yang melanggar peraturan serta melaporkan masalah disiplin kepada pegawai atasan untuk kebaikan bersama.<br /><br /><em>Contoh: &nbsp;Sentiasa menutup lampu setelah mengguna tandas dan &nbsp;menasihati dan menerang kepada rakan sekerja yang tidak mematuhi peraturan. Selain itu, juga akan melaporkan nama pekerja yang tidak menutup lampu setelah mengguna tandas.</em></p>', NULL, NULL, '2024-11-21 17:57:02', '2024-11-21 17:57:02', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1566, 472, 1, '<p>Selalu tidak tepat masuk kerja dan menunjukkan kedatangan yang tidak baik.<br /><br /><em>Contoh: Masih berada di tempat berehat semasa siren berbunyi dan jalan perlahan ke tempat kerja.</em></p>', NULL, NULL, '2024-11-21 17:58:06', '2024-11-21 17:58:06', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1567, 472, 2, '<p>Kadangkala ada masuk kerja pada masa yang ditetapkan tetapi keadaan tidak ketara.<br /><br /><em>Contoh: Kadangkala ada tepat masuk kerja semasa siren berbunyi tetapi kebanyakan masa tidak masuk kerja pada masa yang tepat.</em></p>', NULL, NULL, '2024-11-21 17:58:16', '2024-11-21 17:58:16', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1568, 472, 3, '<p>Kebanyakan masa masuk kerja pada masa yang ditetapkan tetapi kadangkala ada lewat juga.<br /><br /><em>Contoh: Kebanyakan masa masuk kerja semasa siren berbunyi tetapi sekali kala masih lewat masuk kerja.</em></p>', NULL, NULL, '2024-11-21 17:58:49', '2024-11-21 17:58:49', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1569, 472, 4, '<p>Mementingkan ketepatan masa masuk kerja dan masuk kerja tepat pada masa atau lebih awal.<br /><br /><em>Contoh: Sentiasa masa masuk kerja sebelum siren berbunyi atau lebih awal.</em></p>', NULL, NULL, '2024-11-21 17:58:58', '2024-11-21 17:58:58', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1570, 472, 5, '<p>Mementingkan ketepatan masa masuk kerja dan masuk kerja tepat pada masa atau lebih awal serta memberi nasihat kepada rakan sekerja yang lewat.<br /><br /><em>Contoh: Sentiasa masa masuk kerja sebelum siren berbunyi atau lebih awal serta memberi nasihat kepada rakan sekerja yang lewat.</em></p>', NULL, NULL, '2024-11-21 17:59:09', '2024-11-21 17:59:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1571, 473, 1, '<p>Disiplin diri yang tidak memuaskan dan sering meninggalkan tempat kerja dengan berkeliaran tanpa tujuan dan sering membazirkan masa serta curi tulang.<br /><br /><em>Contoh: Sering meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja (banyak kali sehari) dan mengambil masa yang panjang dalam tandas serta membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-21 17:59:55', '2024-11-21 17:59:55', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1572, 473, 2, '<p>Kadangkala membazirkan masa dan curi tulang serta meninggalkan tempat kerja dengan berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Kadangkala meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja (banyak kali sehari) dan mengambil masa yang panjang dalam tandas serta membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-21 18:00:04', '2024-11-21 18:00:04', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1573, 473, 3, '<p>Tidak membazirkan masa dan ringan tulang serta menumpukan perhatian semasa bekerja. Tidak meninggalkan tempat kerja dengan berkeliaran tanpa tujuan.<br /><br /><em>Contoh: Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-21 18:00:13', '2024-11-21 18:00:13', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1574, 473, 4, '<p>Teladan yang baik dan tumpuan perhatian sepenuhnya semasa bekerja. Tidak berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Seorang teladan yang baik dan memberi tumpuan sepenuhnya semasa bekerja. Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-21 18:00:24', '2024-11-21 18:00:24', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1575, 473, 5, '<p>Teladan yang baik dan tumpuan perhatian sepenuhnya semasa bekerja dan juga selalu memberi nasihat kepada rakan sekerja supaya melahirkan keadaan kerja yang lebih agresif. Tidak berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Seorang teladan yang baik dan memberi tumpuan sepenuhnya semasa bekerja. Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja. Selalu memberi nasihat kepada rakan sekerja yang selalu pergi ke tandas sebagai alasan.</em></p>', NULL, NULL, '2024-11-21 18:00:35', '2024-11-21 18:00:35', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1576, 474, 1, '<p>Tidak pernah berada di tempat kerja semasa pembersihan kawasan dijalankan.<br /><br /><em>Contoh: Tidak berada di tempat kerja dan pergi ke tandas semasa pembersihan kawasan dijalankan.</em></p>', NULL, NULL, '2024-11-21 18:01:08', '2024-11-21 18:01:08', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1577, 474, 2, '<p>Memulakan kerja pembersihan kawasan walaupun masa yang ditetapkan belum sampai lagi.<br /><br /><em>Contoh: Memulakan kerja pembersihan kawasan walaupun masa yang ditetapkan belum sampai lagi dan rakan sekerja yang lain masih bekerja lagi.</em></p>', NULL, NULL, '2024-11-21 18:01:23', '2024-11-21 18:01:23', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1578, 474, 3, '<p>Kebanyakan masa membersihkan kawasan production pada masa yang ditetapkan.</p><p>Kadangkala membersihkan kawasan production pada masa yang ditetapkan tetapi keadaan tidak ketara.</p><p><br />\nContoh: Kadangkala ada berada di production semasa pembersihan kawasan dijalankan tetapi kebanyakan masa tidak nampak orang.</p>', NULL, NULL, '2024-11-21 18:01:33', '2024-11-21 18:01:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1579, 474, 4, '<p>Sentiasa mengutamakan dan membersihkan kawasan production pada masa yang ditetapkan.<br /><br /><em>Contoh: Sentiasa membersihkan kawasan production pada masa yang ditetapkan.</em></p>', NULL, NULL, '2024-11-21 18:01:43', '2024-11-21 18:01:43', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1580, 474, 5, '<p>Mengutamakan dan membersihkan kawasan production pada masa yang ditetapkan serta memberi nasihat kepada rakan sekerja yang tidak berbuat demikian.<br /><br /><em>Contoh: Sentiasa membersihkan kawasan production pada masa yang ditetapkan dan memberi nasihat kepada rakan sekerja yang tidak berbuat demikian.</em></p>', NULL, NULL, '2024-11-21 18:01:54', '2024-11-21 18:01:54', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1581, 475, 1, '<p>Hanya menghormati pegawai atasan dan tidak bersopan dengan rakan sekerja.<br /><br /><em>Contoh: Hanya menghormati Leader/Supervisor atau pangkat kerja yang lebih tinggi tetapi tidak bersopan dengan rakan sekerja yang berpangkat rendah/masih baru.</em></p>', NULL, NULL, '2024-11-21 18:02:26', '2024-11-21 18:02:26', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1582, 475, 2, '<p>Biasanya akan bersopan dan menghormati orang lain tetapi kadangkala beremosi.<br /><br /><em>Contoh: Biasanya bersopan dan menghormati rakan sekerja yang lain tetapi kadangkala beremosi dan lawan cakap.</em></p>', NULL, NULL, '2024-11-21 18:02:35', '2024-11-21 18:02:35', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1583, 475, 3, '<p>Sering bersopan dan menghormati orang lain dan tidak bertindak mengikut perasaan.<br /><br /><em>Contoh: Sering bersopan dan menghormati rakan sekerja lain dan tidak bertindak mengikut perasaan.</em></p>', NULL, NULL, '2024-11-21 18:02:46', '2024-11-21 18:02:46', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1584, 475, 4, '<p>Bersopan dan menghormati orang lain pada setiap masa dan tidak bertindak mengikut perasaan dan berbahasa sopan.<br /><br /><em>Contoh: Bersopan dan setiap masa menghormati rakan sekerja yang lain dan tidak bertindak mengikut perasaan dan berbahasa sopan serta jaga perasaan rakan lain.</em></p>', NULL, NULL, '2024-11-21 18:02:58', '2024-11-21 18:02:58', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1585, 475, 5, '<p>Bersopan dan menghormati orang lain pada setiap masa dan masih bercakap dengan sopan walaupun sendiri telah dipersalahkan dalam proses penyelesaian masalah.<br /><br /><em>Contoh: Bersopan dan setiap masa menghormati rakan sekerja yang lain dan masih bercakap dengan sopan walaupun sendiri telah dipersalahkan dalam proses penyelesaian masalah.</em></p>', NULL, NULL, '2024-11-21 18:03:13', '2024-11-21 18:03:13', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1586, 476, 1, '<p>Memang mengetahui arahan yang diberi mempunyai kesilapan tetapi tidak mendapatkan kepastian kerana berpendapat itu adalah tanggungjawab pegawai atasan.<br /><br /><em>Contoh: Tidak mendapatkan kepastian daripada Leader/Supervisor tentang spesifikasi kerja yang diberi walaupun sudah tahu arahan yang diberi mempunyai kesilapan/tidak jelas dan beranggap itu adalah tanggungjawab Leader/Supervisor dan bukan dia.</em></p>', NULL, NULL, '2024-11-21 18:04:21', '2024-11-21 18:04:21', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1587, 476, 2, '<p>Jarang berinisiatif untuk mendapatkan kepastian daripada pegawai atasan walaupun arahan yang diberi tidak jelas atau silap.<br /><br /><em>Contoh: Menunjukkan sikap sudah tahu tetapi tidak ingin peduli dan tidak mendapatkan kepastian daripada Leader/Supervisor walapun arahan yang diberi ada kesilapan/kurang jelas.</em></p>', NULL, NULL, '2024-11-21 18:04:31', '2024-11-21 18:04:31', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1588, 476, 3, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap tetapi tidak pernah melapor balik kepada pegawai atasan tentang tugasan tersebut.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi ada kesilapan/tidak jelas tetapi tidak pernah melapor balik tugasan tersebut.</em></p>', NULL, NULL, '2024-11-21 18:04:42', '2024-11-21 18:04:42', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1589, 476, 4, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi tidak jelas/silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut.</em></p>', NULL, NULL, '2024-11-21 18:04:53', '2024-11-21 18:04:53', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1590, 476, 5, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut serta memberi pendapat yang bermanfaat.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi tidak jelas/silap dan selalu melapor balik kepada Leader/Supervisor dan turut mengambil bahagian untuk memberi pendapat yang bermanfaat.</em></p>', NULL, NULL, '2024-11-21 18:05:05', '2024-11-21 18:05:05', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1591, 477, 1, '<p>Degil dan berpegang teguh dengan pendapat sendiri dan tidak menuruti arahan pegawai atasan.<br /><br /><em>Contoh: Tidak menerima dan melawan percakapan Leader/Supervisor semasa diberi tugasan.</em></p>', NULL, NULL, '2024-11-22 10:17:53', '2024-11-22 10:17:53', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1592, 477, 2, '<p>Kebanyakan masa akan menuruti arahan pegawai atasan tetapi kadangkala akan beremosi dan meluahkan ketidakpuasan.<br /><br /><em>Contoh: Kebanyakan masa akan menerima tugasan Leader/Supervisor dengan baik tetapi kadangkala tidak.</em></p>', NULL, NULL, '2024-11-22 10:18:05', '2024-11-22 10:18:05', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1593, 477, 3, '<p>Mengambil berat dan menuruti arahan pegawai atasan dan tidak pernah membuat hal sesuka hati.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati dan akan bertanya jika tidak faham.</em></p>', NULL, NULL, '2024-11-22 10:18:14', '2024-11-22 10:18:14', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1594, 477, 4, '<p>Mengambil berat dan menuruti arahan pegawai atasan dan tidak pernah membuat hal sesuka hati. Kadangkala turut memberikan pendapat yang bermanfaat dalan kerja yang diberi.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati dan akan bertanya jika tidak faham. Kadangkala turut memberi cadangan/pandangan dalam kerja yang diberi.</em></p>', NULL, NULL, '2024-11-22 10:18:23', '2024-11-22 10:18:23', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1595, 477, 5, '<p>Bersikap positif dan menuruti semua arahan pegawai atasan, tidak membuat hal malah dapat menyampaikan objektif dan kehendak arahan secara positif kepada semua rakan sekerja.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati. Turut menyampaikan maksud dan kehendak mengikuti arahan Leader/Supervisor secara positif kepada rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-22 10:18:35', '2024-11-22 10:18:35', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1596, 478, 1, '<p>Ego dan tidak sudi berbincang tugasan sesama rakan sekerja dan pegawai atasan, sangat keras kepala dan tidak dapat menerima cadangan orang lain.<br /><br /><em>Contoh: Buat kerja tanpa ikut pelan kerja seperti menebuk drill pada kelajuan yang tinggi dan telah membesarkan lubang 3mm kepada 3.20 mm. Dia tidak dapat menerima apabila diminta buat semula pada kelajuan drill yang rendah.</em></p>', NULL, NULL, '2024-11-22 10:19:23', '2024-11-22 10:19:23', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1597, 478, 2, '<p>Jarang berbincang tugasan sesama rakan sekerja dan pegawai atasan dan tidak begitu rela berkongsi maklumat, kadangkala keras kepala dan tidak dapat menerima cadangan orang lain.<br /><br /><em>Contoh: Dia menunjukkan sikap yang tidak begitu gembira apabila diminta buat semula pada kelajuan drill yang rendah.</em></p>', NULL, NULL, '2024-11-22 10:19:32', '2024-11-22 10:19:32', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1598, 478, 3, '<p>Sudi berbincang dan menerima cadangan rakan sekerja dan pegawai atasan, dapat memberi pertolongan apabila diminta.<br /><br /><em>Contoh: Dia sudi membuat semula pada kelajuan drill yang rendah setelah berbincang dan diminta berubah.</em></p>', NULL, NULL, '2024-11-22 10:19:42', '2024-11-22 10:19:42', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1599, 478, 4, '<p>Sudi berbincang dan berinisiatif memberi pertolongan sesama rakan sekerja dan pegawai atasan dengan tidak berkira kerja. Boleh menerima cadangan orang lain dan tidak berkeras kepala.<br /><br /><em>Contoh: Dia sudi membuat semula pada kelajuan drill yang rendah dan dia turut memberi cadangan untuk mengatasi masalah tersebut.</em></p>', NULL, NULL, '2024-11-22 10:19:52', '2024-11-22 10:19:52', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1600, 478, 5, '<p>Sudi berbincang dan berinisiatif memberi pertolongan sesama rakan sekerja dan pegawai atasan dengan tidak berkira kerja. Boleh menerima cadangan orang lain dan tidak berkeras kepala. Selain itu, turut boleh memanggil rakan sekerja untuk sama-sama menyiapkan kerja tersebut.<br /><br /><em>Contoh: Dia ialah orang yang sangat agresif dan sudi membuat semula dan dia turut boleh meminta rakan sekerja untuk sama-sama menyiapkan kerja.</em></p>', NULL, NULL, '2024-11-22 10:22:02', '2024-11-22 10:22:02', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1601, 479, 1, '<p>Menolak tugasan selain dari bidang sendiri dan langsung tidak dapat menerima tugasan tambahan atau di luar bidang kerja, amat mementingkan diri sendiri.<br /><br /><em>Contoh: Tidak mahu backup rakan sekerja yang bercuti dan selalu dipengaruhi oleh rakan sekerja yang lain dimana orang yang berbuat banyak tidak dapat apa-apa.</em></p>', NULL, NULL, '2024-11-22 10:22:59', '2024-11-22 10:22:59', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1602, 479, 2, '<p>Kadangkala menerima tugasan tambahan atau di luar bidang kerja tetapi dengan hati yang tidak rela dan mementingkan kepentingan diri sendiri.<br /><br /><em>Contoh: Kadangkala akan diminta untuk backup rakan sekerja yang bercuti tetapi dia akan membuat kerja secara tidak rela / memberi alasan bahawa dia tidak tahu buat kerja tersebut.</em></p>', NULL, NULL, '2024-11-22 10:23:08', '2024-11-22 10:23:08', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1603, 479, 3, '<p>Rela menerima tugasan tambahan atau di luar bidang dan tidak menolak apabila tugas diberi.<br /><br /><em>Contoh: Rela backup rakan sekerja yang bercuti dan tidak menolak apabila tugas diberi oleh Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-22 10:23:18', '2024-11-22 10:23:18', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1604, 479, 4, '<p>Rela menerima tugasan tambahan atau di luar bidang dan tidak menolak apabila tugas diberi serta cuba mencari cara untuk menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Rela backup rakan sekerja yang bercuti dan tidak menolak apabila tugas diberi oleh Leader / Supervisor. Selain itu, dia juga cari jalan untuk mengeluarkan hasil kerja yang baik / membuat kerja tersebut dengan bersungguh-sungguh.</em></p>', NULL, NULL, '2024-11-22 10:23:30', '2024-11-22 10:23:30', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1605, 479, 5, '<p>Amat rela menerima tugasan tambahan atau di luar bidang dan menerimanya sebagai satu cabaran. Berusaha dan bertanggungjawab sepenuhnya sehingga tugasan selesai dengan sempurna.<br /><br /><em>Contoh: Sangat rela backup rakan sekerja yang bercuti dan menganggap tugas yang diberi tersebut sebagai satu cabaran / tugas sendiri. Dia membuat kerja dengan sepenuh hati dan mengambil tanggungjawab sehingga tugasan tersebut selesai dengan sempurnanya.</em></p>', NULL, NULL, '2024-11-22 10:23:51', '2024-11-22 10:23:51', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1606, 492, 1, '<p>Tidak dapat menyiapkan tugasan mengikut masa yang ditetapkan dan selalu dibuat semula oleh rakan sekerja yang lain dan menyebabkan kelewatan.<br /><br /><em>Contoh: Kerja yang sepatutnya boleh disiapkan dalam sehari tetapi dia selalu tidak hadir bekerja dan kerjanya perlu disambung / dibuat semula oleh rakan sekerja yang lain dan menyebabkan kelewatan.</em></p>', NULL, NULL, '2024-11-22 10:58:44', '2024-11-22 10:58:44', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1607, 492, 2, '<p>Selalu mengambil masa yang panjang untuk menyiapkan kerja walaupun bimbingan sudah diberi.<br /><br /><em>Contoh: Kerja yang sepatutnya boleh disiapkan dalam sehari tetapi dia mengambil masa yang panjang walaupun bimbingan sudah diberi.</em></p>', NULL, NULL, '2024-11-22 10:58:54', '2024-11-22 10:58:54', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1608, 492, 3, '<p>Tugasan biasanya dapat disiapkan dengan sedikit bimbingan dan siap dalam masa yang ditetapkan mahupun lebih awal dan hasil kerja yang masih boleh diterima.<br /><br /><em>Contoh: Boleh menghasilkan kerja dalam masa yang ditetapkan tetapi masih perlu dalam pengawasan/bimbingan.</em></p>', NULL, NULL, '2024-11-22 10:59:04', '2024-11-22 10:59:04', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1609, 492, 4, '<p>Tugasan sentiasa disiapkan tanpa bimbingan dan mengikut jadual mahupun lebih awal dan hasil kerja yang agar memuaskan.<br /><br /><em>Contoh: Boleh menghasilkan kerja dalam masa yang pendek dan tanpa sebarang pengawasan/bimbingan seperti dia cuma perlu 5 jam untuk menghasilkan kerja yang dijangka siap dalam sehari dan dia boleh menghasilkan lebih dalam satu hari.</em></p>', NULL, NULL, '2024-11-22 10:59:15', '2024-11-22 10:59:15', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1610, 492, 5, '<p>Mengutamakan masa dan pantas dalam menyiapkan tugasan yang diberi dan hasil kerja sangat bagus dan boleh diharapkan.<br /><br /><em>Contoh:Boleh membuat apa kerja yang dirancang dan menepati masa yang ditetapkan atau lebih awal tanpa pengawasan/bimbingan. Individu yang teliti dan prihatin dan menguasa masa dan memberi hasil kerja yang sangat bagus dan halus.</em></p>', NULL, NULL, '2024-11-22 10:59:25', '2024-11-22 10:59:25', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1611, 493, 1, '<p>Suka menolak tanggungjawab kerja dan berpura-pura/berdiam diri walaupun tahu apa cara untuk membuat kerja/menyelesaikan masalah.<br /><br /><em>Contoh: Langsung tidak bergerak dan pakai duduk dan tunggu sahaja walaupun sudah diberi penjelasan dalam pelan kerja.</em></p>', NULL, NULL, '2024-11-22 10:59:46', '2024-11-22 10:59:46', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1612, 493, 2, '<p>Kadangkala menolak tanggungjawab kerja dan berpura-pura/berdiam diri walaupun tahu apa cara untuk membuat kerja/menyelesaikan masalah.<br /><br /><em>Contoh: Tidak berusaha untuk belajar dan memahami pembacaan pelan kerja dan ukuran serta memerlukan seseorang mengawasi di tepi dan selalu memberi penjelasan boleh baru dapat menghasilkan kerja yang ditugaskan.</em></p>', NULL, NULL, '2024-11-22 10:59:55', '2024-11-22 10:59:55', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1613, 493, 3, '<p>Sudah faham dan boleh terus bertindak/bergerak ke atas kerja yang telah diselesaikan.&nbsp;<br /><br /><em>Contoh: Sudah tahu membuat kerja/menyelesaikan masalah dan tidak menolak tanggungjawab.</em></p>', NULL, NULL, '2024-11-22 11:00:04', '2024-11-22 11:00:04', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1614, 493, 4, '<p>Sudah faham dan boleh bertindak cepat ke atas semua tugasan serta tidak perlu pengawasan/bimbingan dan akan lapor balik apabila kerja telah siap.<br /><br /><em>Contoh: Bertanggungjawab dan tidak berpura-pura atau berdiam diri dalam membuat kerja/menyelesaikan masalah dan tidak perlu pengawasan/bimbingan dan akan bertindak/bergerak ke atas kerja yang ditugaskan serta lapor balik apabila kerja telah siap.</em></p>', NULL, NULL, '2024-11-22 11:00:18', '2024-11-22 11:00:18', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1615, 493, 5, '<p>Sudah faham dan boleh bertindak cepat ke atas semua tugasan serta tidak perlu pengawasan/bimbingan dan akan lapor balik apabila kerja telah siap. Selain itu, dapat memberi nasihat kepada rakan sekerja yang lain supaya cepat bertindak dalam kerja.<br /><br /><em>Contoh: Bertanggungjawab dan tidak berpura-pura atau berdiam diri dalam membuat kerja/menyelesaikan masalah dan tidak perlu pengawasan/bimbingan dan akan bertindak/bergerak ke atas kerja yang ditugaskan serta lapor balik apabila kerja telah siap. Selain itu, juga memotivasikan rakan sekerja supaya tidak berpura-pura/berdiam diri dalam &nbsp;membuat kerja/menyelesaikan masalah.</em></p>', NULL, NULL, '2024-11-22 11:01:43', '2024-11-22 11:01:43', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1616, 494, 1, '<p>Tidak membuat kerja secara sistematik dan tidak tahu membezakan kepentingan kerja.<br /><br /><em>Contoh: Tidak tahu membezakan kepentingan kerja dan tidak buat perancangan kerja.</em></p>', NULL, NULL, '2024-11-22 11:02:15', '2024-11-22 11:02:15', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1617, 494, 2, '<p>Kadangkala ada membuat kerja secara sistematik dan kadangkala tahu membezakan kepentingan kerja tetapi keadaan tidak ketara.<br /><br /><em>Contoh: Kadangkala tahu membezakan kepentingan kerja dan buat perancangan kerja tetapi tidak selalu dan ikut mood sendiri.</em></p>', NULL, NULL, '2024-11-22 11:02:24', '2024-11-22 11:02:24', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1618, 494, 3, '<p>Tidak perlu seseorang mengawasi di tepi dan tahu membuat kerja secara sistematik dan tahu membezakan kepentingan kerja dengan penjelasan yang ringkas sahaja.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan memerlukan penjelasan kerja yang ringkas sahaja.</em></p>', NULL, NULL, '2024-11-22 11:02:34', '2024-11-22 11:02:34', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1619, 494, 4, '<p>Hanya memerlukan penjelasan yang ringkas dan tahu membuat kerja secara sistematik dan tahu membezakan kepentingan kerja. Berhati-hati dan tiada kesilapan dalam kerja yang dihasilkan.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan hanya memerlukan penjelasan kerja yang ringkas sahaja dan memberi tumpuan dalam kerja dan mengeluarkan hasil kerja yang baik.</em></p>', NULL, NULL, '2024-11-22 11:02:43', '2024-11-22 11:02:43', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1620, 494, 5, '<p>Hanya memerlukan penjelasan yang sangat ringkas sahaja untuk membuat kerja secara sistematik dan tahu membezakan kepentingan kerja dan dapat memberi tunjuk ajar kepada rakan sekerja.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan hanya memerlukan penjelasan kerja yang ringkas sahaja dan memberi tumpuan dalam kerja dan mengeluarkan hasil kerja yang baik dan turut memberi tunjuk ajar kepada rakan sekerja.</em></p>', NULL, NULL, '2024-11-22 11:02:54', '2024-11-22 11:02:54', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1621, 495, 1, '<p>Hasil kerja yang tidak boleh diterima dan selalu membuat kesilapan.<br /><br /><em>Contoh: Tidak menumpu perhatian semasa bekerja dan selalu membuat kesilapan yang sama. Tidak pernah berubah walaupun &nbsp;sudah diberi bimbingan/teguran seperti selalu mengulangi kesilapan yang sama walaupun sudah banyak kali memasang mesin yang sama model.</em></p>', NULL, NULL, '2024-11-22 11:03:13', '2024-11-22 11:03:13', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1622, 495, 2, '<p>Cuai dan mengakibatkan kesilapan kerja.<br /><br /><em>Contoh: Kadangkala cuai semasa bekerja dan mengakibatkan kesilapan kerja kerana tindakan yang lambat untuk berubah setelah diberi bimbingan/teguran.</em></p>', NULL, NULL, '2024-11-22 11:03:23', '2024-11-22 11:03:23', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1623, 495, 3, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan meminimumkan tahap kesilapan kepada yang terendah.<br /><br /><em>Contoh: Kadangkala ada membuat kesilapan tetapi mengambil tindakan yang cepat untuk berubah setelah diberi bimbingan/teguran.</em></p>', NULL, NULL, '2024-11-22 11:03:32', '2024-11-22 11:03:32', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1624, 495, 4, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan apa-apa kesilapan dalam kerja harian.<br /><br /><em>Contoh: Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan. Selain itu, juga berinisiatif untuk menjaga barangan/bahan dan tidak membazir.</em></p>', NULL, NULL, '2024-11-22 11:03:40', '2024-11-22 11:03:40', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1625, 495, 5, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan kerja dan berinisiatif untuk memberi pendapat dan memperbaiki cara kerja yang lebih baik untuk meminimumkan tahap kesilapan kerja.<br /><br /><em>Contoh: Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan dan berinisiatif untuk memberi pendapat dan memperbaiki cara kerja untuk meminimumkan tahap kesilapan kerja seperti berinisiatif untuk mengetahui masalah semasa pemasangan mesin dan turut memberi pendapat untuk memperbaiki cara kerja/menyelesaikan masalah.</em></p>', NULL, NULL, '2024-11-22 11:03:49', '2024-11-22 11:03:49', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1626, 496, 1, '<p>Langsung tidak memahami permintaan kualiti kerja dan tidak memberi perhatian kepada kerja yang dilakukan.<br /><br /><em>Contoh: Langsung tidak memahami permintaan kualiti kerja dan tidak memberi perhatian terhadap semua kerja yang dilakukan seperti membuat pemasangan Control Panel tetapi langsung tidak mengikut diagram yang diberi.</em></p>', NULL, NULL, '2024-11-22 11:04:15', '2024-11-22 11:04:15', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1627, 496, 2, '<p>Kadangkala tidak faham spesifikasi kerja yang diberi dan tidak berinisiatif mengambil langkah untuk mengetahui untuk menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Tidak berinisiatif untuk bertanya/kurang bertanya apabila tidak tahu semasa memasang Control Panel dan pasang ikut sendiri dan tidak ikut cara kerja yang betul.</em></p>', NULL, NULL, '2024-11-22 11:04:25', '2024-11-22 11:04:25', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1628, 496, 3, '<p>Memahami permintaan kualiti kerja dan dapat menghasilkan kerja yang berkualiti secara individu tanpa pengawasan pegawai atasan tetapi tidak mengambil perhatian dan abaikan kerja yang remeh temeh serta tidak mengambil perhatian terhadap kekemasan hasil kerja.<br /><br /><em>Contoh: Tahu pasang Control Panel tetapi tidak terfikir tentang kekemasan. Wayar sudah ditarik dengan betul tetapi tidak diikat dengan cable tie/tidak tersusun/tidak label semasa membuat pemasangan.</em></p>', NULL, NULL, '2024-11-22 11:06:46', '2024-11-22 11:06:46', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1629, 496, 4, '<p>Faham tentang kualiti dan dapat menghasilkan kerja yang berkualiti dan memenuhi kehendak syarikat dan dapat memastikan kerja yang dihasilkan tidak bermasalah.<br /><br /><em>Contoh: Faham tentang kualiti kerja dan ikut semua spesifikasi yang diminta. Boleh berfikir dan nampak (meramalkan) ke hadapan dan memastikan kerja yang dihasilkan tidak bermasalah seperti tahu pasang Control Panel dan semua litar boleh berfungsi dengan baik dan pemasangan yang kemas dan melaporkan keadaan kepada Leader/Supervisor apabila litar tidak berfungsi/bernyala.</em></p>', NULL, NULL, '2024-11-22 11:06:57', '2024-11-22 11:06:57', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1630, 496, 5, '<p>Sangat faham tentang kualiti kerja dan dapat menghasilkan kerja yang berkualiti dan memenuhi kehendak syarikat dan dapat memastikan kerja yang dihasilkan tidak bermasalah serta turut memberi tunjuk ajar kepada rakan kerja yang lain.&nbsp;<br /><br /><em>Contoh: Sangat faham tentang kualiti kerja dan ikut semua spesifikasi yang diminta. Boleh berfikir dan nampak (meramalkan) ke hadapan dan memastikan kerja yang dihasilkan tidak bermasalah. Selain itu, juga dapat memberi tunjuk ajar kepada rakan sekerja yang lain seperti tahu pasang Control Panel dan semua litar boleh berfungsi dengan baik dan pemasangan yang kemas dan melaporkan keadaan kepada Leader/Supervisor apabila litar tidak berfungsi/bernyala. Selain itu, dia juga memberi tunjuk ajar kepada rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-22 11:07:06', '2024-11-22 11:07:06', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1631, 497, 1, '<p>Sentiasa membazirkan/merosakkan sumber syarikat.<br /><br /><em>Contoh: Tidak pernah berhati-hati dalam spesifikasi kerja yang diberi dan sentiasa mengakibatkan pembaziran bahan.</em></p>', NULL, NULL, '2024-11-22 11:07:28', '2024-11-22 11:07:28', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1632, 497, 2, '<p>Ada bersikap mahu menjimatkan sumber syarikat tetapi kadangkala menyebabkan pembaziran di atas kecuaiannya.<br /><br /><em>Contoh: Cuai dalam pembacaan spesifikasi kerja yang diberi dan silap ambil bahan dan menyebabkan kesilapan dan membazirkan bahan serta perlu &ldquo;rework&rdquo;.</em></p>', NULL, NULL, '2024-11-22 11:07:37', '2024-11-22 11:07:37', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1633, 497, 3, '<p>Berhati-hati semasa bekerja dan menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dan memastikan betul supaya tidak berlaku kesilapan yang mengakibatkan pembaziran bahan dan buang masa.</em></p>', NULL, NULL, '2024-11-22 11:07:49', '2024-11-22 11:07:49', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1634, 497, 4, '<p>Berhati-hati semasa bekerja dan berinisiatif menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya. Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dengan pelan kerja dan memastikan semua barang yang ambil adalah betul. Ada pemikiran tidak membazir seperti dalam menghasilkan sesuatu barang yang sangat kecil, dia akan cari scrap dahulu dan tidak guna bahan yang baru atau bahan yang besar.Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan.</em></p>', NULL, NULL, '2024-11-22 11:08:01', '2024-11-22 11:08:01', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1635, 497, 5, '<p>Berhati-hati semasa bekerja dan berinisiatif menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya. Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan dan juga menyedarkan dan membetulkan kesilapan rakan sekerja yang lain.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dengan pelan kerja dan memastikan semua barang yang ambil adalah betul. Ada pemikiran tidak membazir seperti dalam menghasilkan sesuatu barang yang sangat kecil, dia akan cari scrap dahulu dan tidak guna bahan yang baru atau bahan yang besar.Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan dan menyedarkan dan membetulkan kesilapan rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-22 11:08:11', '2024-11-22 11:08:11', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1636, 498, 1, '<p>Pengetahuan atau kemahiran adalah terhad dan tidak dapat menyelesaikan tugasan dan menggunakan masa yang panjang untuk mempelajari pengetahuan dan cara kerja yang agak senang.<br /><br /><em>Contoh: Tidak ada pengetahuan dan kemahiran kerja dan menggunakan masa yang panjang untuk mempelajari cara kerja yang senang walaupun bimbingan telah diberi seperti membuat kerja kimpalan yang paling senang iaitu mengimpal besi dalam kedudukan rata.</em></p>', NULL, NULL, '2024-11-22 11:08:32', '2024-11-22 11:08:32', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1637, 498, 2, '<p>Kurang pengetahuan atau kemahiran yang cukup untuk mengendalikan tugasan.<br /><br /><em>Contoh: Hasil kimpalan yang teruk dan bimbingan masih diperlukan walaupun diminta menghasilkan kerja kimpalan yang agak senang seperti mengimpal besi dalam kedudukan rata dan mendatar.</em></p>', NULL, NULL, '2024-11-22 11:08:41', '2024-11-22 11:08:41', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1638, 498, 3, '<p>Mempunyai pengetahuan dan kemahiran untuk mengendalikan tugasan dan mempunyai sikap mahu belajar dan mempelajari pengetahuan kerja yang baru dalam masa yang singkat dan mengimplikasikan dalam kerja harian.<br /><br /><em>Contoh: Ada pengetahuan dan kemahiran kimpalan tetapi tidak dapat meneruskan kerja apabila menghadapi kerja yang tidak biasa dan memerlukan bimbingan seperti: boleh mengimpal besi yang nipis tetapi tidak apabila diminta mengimpal besi yang lagi nipis / boleh mengimpal dalam kedudukan rata, mendatar dan menegak tetapi tidak apabila dalam keadaan overhead atau dalam keadaan 45 darjah.</em></p>', NULL, NULL, '2024-11-22 11:08:50', '2024-11-22 11:08:50', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1639, 498, 4, '<p>Boleh menguasai pengetahuan dan kemahiran untuk mengendalikan tugasan dan pencapaian yang agak memuaskan dan dapat menggunakan pengetahuannya untuk meningkatkan kualiti kerja.<br /><br /><em>Contoh: Mempunyai pengetahuan dan kemahiran yang luas serta jelas dengan semua keperluan/permintaan kerja seperti memilih kaedah yang bersesuaian untuk menghasilkan kerja dan tahu mengawal had api untuk mencegah hasil kerja dari kerosakan.</em></p>', NULL, NULL, '2024-11-22 11:09:02', '2024-11-22 11:09:02', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1640, 498, 5, '<p>Menguasai pengetahuan dan kemahiran untuk mengendalikan tugasan dan boleh menggabungkan pengetahuan untuk meningkatkan kualiti kerja serta mencari cara kerja baru untuk menyelesaikan masalah kerja dengan pengetahuannya.<br /><br /><em>Contoh: Mempunyai pengetahuan dan kemahiran yang luas serta jelas dengan semua keperluan/permintaan kerja dan berinisiatif memberi cadangan untuk menyelesaikan masalah kerja.&nbsp;</em></p>', NULL, NULL, '2024-11-22 11:09:16', '2024-11-22 11:09:16', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1641, 499, 1, '<p>Tidak pernah mengemas dan membersihkan tempat kerja sendiri dan sentiasa mengotorkan tempat kerja sendiri dan rakan sekerja yang lain.<br /><br /><em>Contoh: Tidak pernah terfikir kebaikan bersama dan terus membuang sisa kerja ke lantai dan menganggap ini kerja cleaner untuk membersihkan.</em></p>', NULL, NULL, '2024-11-22 11:09:49', '2024-11-22 11:09:49', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1642, 499, 2, '<p>Kadangkala ada mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya tidak kemas.<br /><br /><em>Contoh: Tidak selalu mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya tidak kemas seperti kadangkala ada membersihkan tempat kerja dan kadangkala tidak.</em></p>', NULL, NULL, '2024-11-22 11:09:59', '2024-11-22 11:09:59', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1643, 499, 3, '<p>Berinisiatif untuk mengemas dan membersihkan tempat kerja dan kebanyakan masa tempat kerjanya adalah kemas dan bersih.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai.</em></p>', NULL, NULL, '2024-11-22 11:10:09', '2024-11-22 11:10:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1644, 499, 4, '<p>Selalu mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya kemas dan selalu menolong membersihkan kawasan bahagiannya (division) dan kilang.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai serta tolong membersihkan kawasan yang lain.</em></p>', NULL, NULL, '2024-11-22 11:10:18', '2024-11-22 11:10:18', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1645, 499, 5, '<p>Selalu mengemas dan membersihkan tempat kerja dan tempat kerjanya kelihatan kemas dan bersih. Juga selalu menjaga kebersihan seluruh kawasan kilang dan dapat menegur rakan sekerja untuk menjaga kebersihan kilang.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai serta tolong menjaga kebersihan kawasan yang lain dan menegur rakan sekerja yang tidak menjaga kebersihan kilang.</em></p>', NULL, NULL, '2024-11-22 11:10:28', '2024-11-22 11:10:28', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1646, 500, 1, '<p>Tidak menjaga peralatan dan kemudahan syarikat.<br /><br /><em>Contoh: Tidak menjaga peralatan dan kemudahan syarikat seperti tidak menjaga forklift dan tidak pernah meletakkkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-22 11:10:49', '2024-11-22 11:10:49', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1647, 500, 2, '<p>Kadangkala bersikap cuai dalam mengendali peralatan dan kemudahan syarikat dan mengakibatkan kerosakan.<br /><br /><em>Contoh: Tidak selalu menjaga peralatan dan kemudahan syarikat dan mengakibatkan kerosakan seperti forklift terus jalan setelah enjin dihidupkan. Tidak mengambil berat tentang barang yang diangkat dan masuk ke ruang yang kecil. Selalu tidak meletakkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-22 11:10:59', '2024-11-22 11:10:59', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1648, 500, 3, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat dengan cara yang betul.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-22 11:11:09', '2024-11-22 11:11:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1649, 500, 4, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat demi kebaikan bersama. Selain itu, &nbsp;melaporkan kepada pihak atasan bila nampak rakan sekerja salahguna dan memberi cara penyelesaian yang bermanfaat.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna dan melapor jika ada kerosakan dan memberi cadangan untuk memperbaiki cara penggunaan dan penjagaan alatan.</em></p>', NULL, NULL, '2024-11-22 11:11:18', '2024-11-22 11:11:18', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1650, 500, 5, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat demi kebaikan bersama. Selain itu, &nbsp;melaporkan kepada pihak atasan bila nampak pekerja salahguna dan memberi cara penyelesaian yang bermanfaat. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna dan melapor jika ada kerosakan dan memberi cadangan untuk memperbaiki cara penggunaan dan penjagaan alatan.Selain itu, akan menyedarkan dan menasihati rakan sekerja yang tidak menjaga forklift semasa mengguna.</em></p>', NULL, NULL, '2024-11-22 11:11:29', '2024-11-22 11:11:29', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1651, 501, 1, '<p>Tidak mengutamakan keselamatan semasa bekerja.<br /><br /><em>Contoh: Tidak mengutamakan keselamatan semasa bekerja seperti tidak memakai PPE semasa bekerja.</em></p>', NULL, NULL, '2024-11-22 11:11:50', '2024-11-22 11:11:50', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1652, 501, 2, '<p>Ada sikap mengutamakan keselamatan tetapi kadangkala tidak.<br /><br /><em>Contoh: Ada memakai PPE semasa bekerja tetapi kadangkala tidak.</em></p>', NULL, NULL, '2024-11-22 11:12:00', '2024-11-22 11:12:00', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1653, 501, 3, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja.</em></p>', NULL, NULL, '2024-11-22 11:12:14', '2024-11-22 11:12:14', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1654, 501, 4, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan.</em></p>', NULL, NULL, '2024-11-22 11:12:23', '2024-11-22 11:12:23', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1655, 501, 5, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja dan melaporkan kepada pihak atasan serta turut memberi cara atau cara penyelesaian yang bermanfaat.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan serta turut memberi cara atau cara penyelesaian yang bermanfaat.</em></p>', NULL, NULL, '2024-11-22 11:12:34', '2024-11-22 11:12:34', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1656, 502, 1, '<p>Menerima tugasan tetapi tidak memikul tanggungjawab kerja dan tidak dapat bekerja di bawah tekanan.<br /><br /><em>Contoh: Dia terima kerja yang diberi tetapi sentiasa bersembang dengan rakan sekerja dan tidak buat kerja sehingga tidak nampak hasil kerja.</em></p>', NULL, NULL, '2024-11-22 11:13:05', '2024-11-22 11:13:05', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1657, 502, 2, '<p>Boleh menerima dan memikul tanggungjawab dan cuba untuk bekerja di bawah tekanan tetapi kadangkala tidak dapat menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Dia boleh buat kerja dan cuba elakkan diri dari tidak masuk kerja/tidak memberi alasan untuk bercuti tetapi kadangkala masih perlu dalam bimbingan.</em></p>', NULL, NULL, '2024-11-22 11:13:15', '2024-11-22 11:13:15', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1658, 502, 3, '<p>Boleh menerima dan memikul tanggungjawab dan dapat menghabiskan setiap kerja yang diamanahkan dengan baik di bawah tekanan dan melaporkan kerja yang telah dilakukan kepada pegawai atasan.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia masih menepati target dan ikut piawai kerja yang ditetapkan oleh syarikat. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia juga akan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-22 11:13:25', '2024-11-22 11:13:25', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1659, 502, 4, '<p>Rela menerima dan memikul tanggungjawab dan sentiasa dapat menghasilkan kerja yang berkualiti di bawah tekanan dan dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang dilakukan kepada pegawai atasan.Boleh buat kerja lebih masa sehingga kerja siap.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia akan menawarkan diri secara sukarela untuk kerja tersebut serta menepati target dan ikut piawai kerja yang ditetapkan oleh syarikat. Boleh buat kerja lebih masa sehingga kerja siap. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-22 11:13:36', '2024-11-22 11:13:36', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1660, 502, 5, '<p>Rela menerima dan memikul tanggungjawab serta tahu kepentingan dan deadline kerja. Dapat memanggil rakan sekerja untuk menyiapkan kerja bersama. Sentiasa dapat menghasilkan kerja yang berkualiti di bawah tekanan dan dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang dilakukan kepada pegawai atasan.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia tahu kepentingan dan deadline kerja tersebut serta dapat memanggil rakan sekerja untuk menyiapkan kerja bersama. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-22 11:13:47', '2024-11-22 11:13:47', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1661, 503, 1, '<p>Tidak rela mengaku kesilapan dan suka menolak tanggungjawab kepada orang lain.<br /><br /><em>Contoh: Telah melakukan kesilapan seperti tidak mengikuti spesifikasi kerja yang diberi oleh Leader / tidak tanya Leader apabila tidak faham / tanya rakan sekerja yang tidak dipertanggungjawabkan dan tidak pernah mengakui kesilapan apabila ditegur oleh Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-22 11:14:07', '2024-11-22 11:14:07', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1662, 503, 2, '<p>Kadangkala tidak rela mengaku kesilapan dan suka membuat perbandingan diri dengan orang lain dalam kesilapan yang telah dibuat.<br /><br /><em>Contoh: Telah melakukan kesilapan seperti tidak mengikuti spesifikasi kerja yang diberi oleh Leader / tidak tanya Leader apabila tidak faham / tanya rakan sekerja yang tidak dipertanggungjawabkan dan kadangkala tidak mengakui kesilapan apabila ditegur oleh Leader/Supervisor malah menyatakan Leader/Supervisor ada prasangka terhadap dia.</em></p>', NULL, NULL, '2024-11-22 11:14:16', '2024-11-22 11:14:16', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1663, 503, 3, '<p>Mengaku kesilapan dan tidak menolak tanggungjawab kepada orang lain.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan. Dia terima dan mengakui kesilapan.</em></p>', NULL, NULL, '2024-11-22 11:15:07', '2024-11-22 11:15:07', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1664, 503, 4, '<p>Tidak melarikan diri dari tanggungjawab dan terus berjumpa dengan pihak atasan untuk mengakui kesilapan dan berinisiatif untuk memperbaiki kesilapan yang telah dilakukan.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan. Dia tidak melarikan diri dari tanggungjawab dan terus berjumpa dengan Leader/Supervisor dan mengakui kesilapan. Selain itu, dia juga memberi cadangan dan sama-sama memperbaiki kesilapan yang telah dilakukan.</em></p>', NULL, NULL, '2024-11-22 11:15:16', '2024-11-22 11:15:16', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1665, 503, 5, '<p>Berani mengaku kesilapan dan tidak menolak tanggungjawab dan memastikan kesilapan tidak berlaku lagi. Berinisiatif untuk memperbetulkan kesilapan dan dapat memberi cadangan yang bermanfaat untuk mengelakkan kesilapan berlaku lagi.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan yang agak besar. Dia berani mengakui kesilapan dan terus berjumpa dengan Leader/Supervisor untuk mengakui kesilapan. Dia mengambil pengalaman tersebut sebagai satu pengajaran dan tidak mengulangi kesilapan tersebut lagi. Selain itu, dia &nbsp;memberi cadangan dan sama-sama memperbaiki kesilapan yang telah dilakukan serta memberi cadangan yang bermanfaat untuk mengelakkan kesilapan berlaku lagi.</em></p>', NULL, NULL, '2024-11-22 11:15:28', '2024-11-22 11:15:28', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1666, 504, 1, '<p>Membuat kerja alah kadar dan setakat membuat kerja sahaja dan tidak menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Tidak menunjukkan sikap ingin belajar dan tidak menumpukan perhatian semasa bekerja seperti dia boleh mengambil masa yang panjang untuk memasang beberapa nut pada mesin.</em></p>', NULL, NULL, '2024-11-22 11:15:52', '2024-11-22 11:15:52', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1667, 504, 2, '<p>Boleh membuat kerja tetapi mudah dipengaruhi orang lain dan kadangkala tidak dapat menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Dia boleh pasang nut pada mesin tetapi mudah dipengaruhi oleh rakan sekerja yang lain seperti dia akan melambatkan proses kerjanya dan sambil kerja sambil bersembang apabila ada rakan sekerja yang bersembang dengannya semasa bekerja.</em></p>', NULL, NULL, '2024-11-22 11:16:01', '2024-11-22 11:16:01', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1668, 504, 3, '<p>Lebih agresif dan sikap kerja juga serius dan dapat menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak mengangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja.</em></p>', NULL, NULL, '2024-11-22 11:16:11', '2024-11-22 11:16:11', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1669, 504, 4, '<p>Bersemangat kerja dan menumpukan perhatian sepenuhnya dalam kerja. Sentiasa mengutamakan kualiti kerja dan menghasilkan kerja yang halus dan teliti dan tidak melakukan kesilapan.<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak menggangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja. Dia sentiasa mengutamakan kualiti kerja dan memastikan nut yang dipasang itu betul dan kemas.</em></p>', NULL, NULL, '2024-11-22 11:16:20', '2024-11-22 11:16:20', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1670, 504, 5, '<p>Matlamat untuk berjaya sangat jelas. Menumpukan perhatian sepenuhnya dalam kerja. Sentiasa mengutamakan kualiti kerja dan menghasilkan kerja yang halus dan teliti dan tidak melakukan kesilapan. Selain itu turut memberi cadangan dan cara kerja untuk memastikan kerja berkualiti dihasilkan setiap kali.&nbsp;<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak menggangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja. Dia sentiasa mengutamakan kualiti kerja dan memastikan nut yang dipasang itu betul dan kemas. Selain itu, dia juga akan memberi cadangan untuk memastikan kerja berkualiti dapat dihasilkan.</em></p>', NULL, NULL, '2024-11-22 11:16:32', '2024-11-22 11:16:32', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1671, 505, 1, '<p>Langsung tidak mahu memahami dan menerima peraturan dan polisi syarikat dan sentiasa membuat aduan terhadap dasar syarikat.<br /><br /><em>Contoh: Selalu tidak menutup lampu setelah mengguna tandas dan membuat aduan apabila pihak syarikat mengambil tindakan.</em></p>', NULL, NULL, '2024-11-22 11:17:11', '2024-11-22 11:17:11', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1672, 505, 2, '<p>Kadangkala sahaja mahu menerima dan mematuhi peraturan dan polisi syarikat.<br /><br /><em>Contoh: Kadangkala ada menutup lampu setelah mengguna tandas kadangkala tidak.</em></p>', NULL, NULL, '2024-11-22 11:17:20', '2024-11-22 11:17:20', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1673, 505, 3, '<p>Menerima dan mematuhi setiap peraturan dan polisi syarikat.<br /><br /><em>Contoh: Setiap kali akan menutup lampu setelah mengguna tandas.</em></p>', NULL, NULL, '2024-11-22 11:17:30', '2024-11-22 11:17:30', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1674, 505, 4, '<p>Tidak melanggar peraturan dan sentiasa dapat menasihatkan rakan sekerja untuk menerima dan mematuhi peraturan dan polisi syarikat untuk kebaikan bersama.<br /><br /><em>Contoh: Sentiasa menutup lampu setelah mengguna tandas dan &nbsp;menasihati dan menerang kepada rakan sekerja yang tidak mematuhi peraturan.</em></p>', NULL, NULL, '2024-11-22 11:17:41', '2024-11-22 11:17:41', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1675, 505, 5, '<p>Memahami dan menerima setiap peraturan dan polisi syarikat dan sentiasa menasihatkan rakan sekerja yang melanggar peraturan serta melaporkan masalah disiplin kepada pegawai atasan untuk kebaikan bersama.<br /><br /><em>Contoh: &nbsp;Sentiasa menutup lampu setelah mengguna tandas dan &nbsp;menasihati dan menerang kepada rakan sekerja yang tidak mematuhi peraturan. Selain itu, juga akan melaporkan nama pekerja yang tidak menutup lampu setelah mengguna tandas.</em></p>', NULL, NULL, '2024-11-22 11:17:51', '2024-11-22 11:17:51', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1676, 506, 1, '<p>Selalu tidak tepat masuk kerja dan menunjukkan kedatangan yang tidak baik.<br /><br /><em>Contoh: Masih berada di tempat berehat semasa siren berbunyi dan jalan perlahan ke tempat kerja.</em></p>', NULL, NULL, '2024-11-22 11:18:10', '2024-11-22 11:18:10', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1677, 506, 2, '<p>Kadangkala ada masuk kerja pada masa yang ditetapkan tetapi keadaan tidak ketara.<br /><br /><em>Contoh: Kadangkala ada tepat masuk kerja semasa siren berbunyi tetapi kebanyakan masa tidak masuk kerja pada masa yang tepat.</em></p>', NULL, NULL, '2024-11-22 11:18:20', '2024-11-22 11:18:20', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1678, 506, 3, '<p>Kebanyakan masa masuk kerja pada masa yang ditetapkan tetapi kadangkala ada lewat juga.<br /><br /><em>Contoh: Kebanyakan masa masuk kerja semasa siren berbunyi tetapi sekali kala masih lewat masuk kerja.</em></p>', NULL, NULL, '2024-11-22 11:18:29', '2024-11-22 11:18:29', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1679, 506, 4, '<p>Mementingkan ketepatan masa masuk kerja dan masuk kerja tepat pada masa atau lebih awal.<br /><br /><em>Contoh: Sentiasa masa masuk kerja sebelum siren berbunyi atau lebih awal.</em></p>', NULL, NULL, '2024-11-22 11:18:38', '2024-11-22 11:18:38', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1680, 506, 5, '<p>Mementingkan ketepatan masa masuk kerja dan masuk kerja tepat pada masa atau lebih awal serta memberi nasihat kepada rakan sekerja yang lewat.<br /><br /><em>Contoh: Sentiasa masa masuk kerja sebelum siren berbunyi atau lebih awal serta memberi nasihat kepada rakan sekerja yang lewat.</em></p>', NULL, NULL, '2024-11-22 11:18:48', '2024-11-22 11:18:48', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1681, 507, 1, '<p>Disiplin diri yang tidak memuaskan dan sering meninggalkan tempat kerja dengan berkeliaran tanpa tujuan dan sering membazirkan masa serta curi tulang.<br /><br /><em>Contoh: Sering meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja (banyak kali sehari) dan mengambil masa yang panjang dalam tandas serta membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-22 11:19:15', '2024-11-22 11:19:15', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1682, 507, 2, '<p>Kadangkala membazirkan masa dan curi tulang serta meninggalkan tempat kerja dengan berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Kadangkala meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja (banyak kali sehari) dan mengambil masa yang panjang dalam tandas serta membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-22 11:19:25', '2024-11-22 11:19:25', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1683, 507, 3, '<p>Tidak membazirkan masa dan ringan tulang serta menumpukan perhatian semasa bekerja. Tidak meninggalkan tempat kerja dengan berkeliaran tanpa tujuan.<br /><br /><em>Contoh: Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-22 11:19:34', '2024-11-22 11:19:34', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1684, 507, 4, '<p>Teladan yang baik dan tumpuan perhatian sepenuhnya semasa bekerja. Tidak berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Seorang teladan yang baik dan memberi tumpuan sepenuhnya semasa bekerja. Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-22 11:19:44', '2024-11-22 11:19:44', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1685, 507, 5, '<p>Teladan yang baik dan tumpuan perhatian sepenuhnya semasa bekerja dan juga selalu memberi nasihat kepada rakan sekerja supaya melahirkan keadaan kerja yang lebih agresif. Tidak berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Seorang teladan yang baik dan memberi tumpuan sepenuhnya semasa bekerja. Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja. Selalu memberi nasihat kepada rakan sekerja yang selalu pergi ke tandas sebagai alasan.</em></p>', NULL, NULL, '2024-11-22 11:19:55', '2024-11-22 11:19:55', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1686, 508, 1, '<p>Tidak pernah berada di tempat kerja semasa pembersihan kawasan dijalankan.<br /><br /><em>Contoh: Tidak berada di tempat kerja dan pergi ke tandas semasa pembersihan kawasan dijalankan.</em></p>', NULL, NULL, '2024-11-22 11:20:19', '2024-11-22 11:20:19', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1687, 508, 2, '<p>Memulakan kerja pembersihan kawasan walaupun masa yang ditetapkan belum sampai lagi.<br /><br /><em>Contoh: Memulakan kerja pembersihan kawasan walaupun masa yang ditetapkan belum sampai lagi dan rakan sekerja yang lain masih bekerja lagi.</em></p>', NULL, NULL, '2024-11-22 11:20:28', '2024-11-22 11:20:28', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1688, 508, 3, '<p>Kebanyakan masa membersihkan kawasan production pada masa yang ditetapkan.</p><p>Kadangkala membersihkan kawasan production pada masa yang ditetapkan tetapi keadaan tidak ketara.</p><p><br />\nContoh: Kadangkala ada berada di production semasa pembersihan kawasan dijalankan tetapi kebanyakan masa tidak nampak orang.</p>', NULL, NULL, '2024-11-22 11:20:37', '2024-11-22 11:20:37', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1689, 508, 4, '<p>Sentiasa mengutamakan dan membersihkan kawasan production pada masa yang ditetapkan.<br /><br /><em>Contoh: Sentiasa membersihkan kawasan production pada masa yang ditetapkan.</em></p>', NULL, NULL, '2024-11-22 11:20:48', '2024-11-22 11:20:48', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1690, 508, 5, '<p>Mengutamakan dan membersihkan kawasan production pada masa yang ditetapkan serta memberi nasihat kepada rakan sekerja yang tidak berbuat demikian.<br /><br /><em>Contoh: Sentiasa membersihkan kawasan production pada masa yang ditetapkan dan memberi nasihat kepada rakan sekerja yang tidak berbuat demikian.</em></p>', NULL, NULL, '2024-11-22 11:20:58', '2024-11-22 11:20:58', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1691, 509, 1, '<p>Hanya menghormati pegawai atasan dan tidak bersopan dengan rakan sekerja.<br /><br /><em>Contoh: Hanya menghormati Leader/Supervisor atau pangkat kerja yang lebih tinggi tetapi tidak bersopan dengan rakan sekerja yang berpangkat rendah/masih baru.</em></p>', NULL, NULL, '2024-11-22 11:21:23', '2024-11-22 11:21:23', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1692, 509, 2, '<p>Biasanya akan bersopan dan menghormati orang lain tetapi kadangkala beremosi.<br /><br /><em>Contoh: Biasanya bersopan dan menghormati rakan sekerja yang lain tetapi kadangkala beremosi dan lawan cakap.</em></p>', NULL, NULL, '2024-11-22 11:21:33', '2024-11-22 11:21:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1693, 509, 3, '<p>Sering bersopan dan menghormati orang lain dan tidak bertindak mengikut perasaan.<br /><br /><em>Contoh: Sering bersopan dan menghormati rakan sekerja lain dan tidak bertindak mengikut perasaan.</em></p>', NULL, NULL, '2024-11-22 11:21:43', '2024-11-22 11:21:43', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1694, 509, 4, '<p>Bersopan dan menghormati orang lain pada setiap masa dan tidak bertindak mengikut perasaan dan berbahasa sopan.<br /><br /><em>Contoh: Bersopan dan setiap masa menghormati rakan sekerja yang lain dan tidak bertindak mengikut perasaan dan berbahasa sopan serta jaga perasaan rakan lain.</em></p>', NULL, NULL, '2024-11-22 11:21:55', '2024-11-22 11:21:55', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1695, 509, 5, '<p>Bersopan dan menghormati orang lain pada setiap masa dan masih bercakap dengan sopan walaupun sendiri telah dipersalahkan dalam proses penyelesaian masalah.<br /><br /><em>Contoh: Bersopan dan setiap masa menghormati rakan sekerja yang lain dan masih bercakap dengan sopan walaupun sendiri telah dipersalahkan dalam proses penyelesaian masalah.</em></p>', NULL, NULL, '2024-11-22 11:22:07', '2024-11-22 11:22:07', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1696, 510, 1, '<p>Memang mengetahui arahan yang diberi mempunyai kesilapan tetapi tidak mendapatkan kepastian kerana berpendapat itu adalah tanggungjawab pegawai atasan.<br /><br /><em>Contoh: Tidak mendapatkan kepastian daripada Leader/Supervisor tentang spesifikasi kerja yang diberi walaupun sudah tahu arahan yang diberi mempunyai kesilapan/tidak jelas dan beranggap itu adalah tanggungjawab Leader/Supervisor dan bukan dia.</em></p>', NULL, NULL, '2024-11-22 11:22:48', '2024-11-22 11:22:48', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1697, 510, 2, '<p>Jarang berinisiatif untuk mendapatkan kepastian daripada pegawai atasan walaupun arahan yang diberi tidak jelas atau silap.<br /><br /><em>Contoh: Menunjukkan sikap sudah tahu tetapi tidak ingin peduli dan tidak mendapatkan kepastian daripada Leader/Supervisor walapun arahan yang diberi ada kesilapan/kurang jelas.</em></p>', NULL, NULL, '2024-11-22 11:22:58', '2024-11-22 11:22:58', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1698, 510, 3, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap tetapi tidak pernah melapor balik kepada pegawai atasan tentang tugasan tersebut.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi ada kesilapan/tidak jelas tetapi tidak pernah melapor balik tugasan tersebut.</em></p>', NULL, NULL, '2024-11-22 11:23:08', '2024-11-22 11:23:08', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1699, 510, 4, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi tidak jelas/silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut.</em></p>', NULL, NULL, '2024-11-22 11:23:18', '2024-11-22 11:23:18', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1700, 510, 5, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut serta memberi pendapat yang bermanfaat.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi tidak jelas/silap dan selalu melapor balik kepada Leader/Supervisor dan turut mengambil bahagian untuk memberi pendapat yang bermanfaat.</em></p>', NULL, NULL, '2024-11-22 11:23:29', '2024-11-22 11:23:29', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1701, 511, 1, '<p>Degil dan berpegang teguh dengan pendapat sendiri dan tidak menuruti arahan pegawai atasan.<br /><br /><em>Contoh: Tidak menerima dan melawan percakapan Leader/Supervisor semasa diberi tugasan.</em></p>', NULL, NULL, '2024-11-22 11:24:26', '2024-11-22 11:24:26', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1702, 511, 2, '<p>Kebanyakan masa akan menuruti arahan pegawai atasan tetapi kadangkala akan beremosi dan meluahkan ketidakpuasan.<br /><br /><em>Contoh: Kebanyakan masa akan menerima tugasan Leader/Supervisor dengan baik tetapi kadangkala tidak.</em></p>', NULL, NULL, '2024-11-22 11:24:37', '2024-11-22 11:24:37', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1703, 511, 3, '<p>Mengambil berat dan menuruti arahan pegawai atasan dan tidak pernah membuat hal sesuka hati.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati dan akan bertanya jika tidak faham.</em></p>', NULL, NULL, '2024-11-22 11:24:47', '2024-11-22 11:24:47', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1704, 511, 4, '<p>Mengambil berat dan menuruti arahan pegawai atasan dan tidak pernah membuat hal sesuka hati. Kadangkala turut memberikan pendapat yang bermanfaat dalan kerja yang diberi.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati dan akan bertanya jika tidak faham. Kadangkala turut memberi cadangan/pandangan dalam kerja yang diberi.</em></p>', NULL, NULL, '2024-11-22 11:25:02', '2024-11-22 11:25:02', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1705, 511, 5, '<p>Bersikap positif dan menuruti semua arahan pegawai atasan, tidak membuat hal malah dapat menyampaikan objektif dan kehendak arahan secara positif kepada semua rakan sekerja.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati. Turut menyampaikan maksud dan kehendak mengikuti arahan Leader/Supervisor secara positif kepada rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-22 11:25:16', '2024-11-22 11:25:16', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1706, 512, 1, '<p>Ego dan tidak sudi berbincang tugasan sesama rakan sekerja dan pegawai atasan, sangat keras kepala dan tidak dapat menerima cadangan orang lain.<br /><br /><em>Contoh: Buat kerja tanpa ikut pelan kerja seperti menebuk drill pada kelajuan yang tinggi dan telah membesarkan lubang 3mm kepada 3.20 mm. Dia tidak dapat menerima apabila diminta buat semula pada kelajuan drill yang rendah.</em></p>', NULL, NULL, '2024-11-22 11:26:04', '2024-11-22 11:26:04', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1707, 512, 2, '<p>Jarang berbincang tugasan sesama rakan sekerja dan pegawai atasan dan tidak begitu rela berkongsi maklumat, kadangkala keras kepala dan tidak dapat menerima cadangan orang lain.<br /><br /><em>Contoh: Dia menunjukkan sikap yang tidak begitu gembira apabila diminta buat semula pada kelajuan drill yang rendah.</em></p>', NULL, NULL, '2024-11-22 11:26:17', '2024-11-22 11:26:17', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1708, 512, 3, '<p>Sudi berbincang dan menerima cadangan rakan sekerja dan pegawai atasan, dapat memberi pertolongan apabila diminta.<br /><br /><em>Contoh: Dia sudi membuat semula pada kelajuan drill yang rendah setelah berbincang dan diminta berubah.</em></p>', NULL, NULL, '2024-11-22 11:26:26', '2024-11-22 11:26:26', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1709, 512, 4, '<p>Sudi berbincang dan berinisiatif memberi pertolongan sesama rakan sekerja dan pegawai atasan dengan tidak berkira kerja. Boleh menerima cadangan orang lain dan tidak berkeras kepala.<br /><br /><em>Contoh: Dia sudi membuat semula pada kelajuan drill yang rendah dan dia turut memberi cadangan untuk mengatasi masalah tersebut.</em></p>', NULL, NULL, '2024-11-22 11:26:36', '2024-11-22 11:26:36', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1710, 512, 5, '<p>Sudi berbincang dan berinisiatif memberi pertolongan sesama rakan sekerja dan pegawai atasan dengan tidak berkira kerja. Boleh menerima cadangan orang lain dan tidak berkeras kepala. Selain itu, turut boleh memanggil rakan sekerja untuk sama-sama menyiapkan kerja tersebut.<br /><br /><em>Contoh: Dia ialah orang yang sangat agresif dan sudi membuat semula dan dia turut boleh meminta rakan sekerja untuk sama-sama menyiapkan kerja.</em></p>', NULL, NULL, '2024-11-22 11:26:47', '2024-11-22 11:26:47', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1711, 513, 1, '<p>Menolak tugasan selain dari bidang sendiri dan langsung tidak dapat menerima tugasan tambahan atau di luar bidang kerja, amat mementingkan diri sendiri.<br /><br /><em>Contoh: Tidak mahu backup rakan sekerja yang bercuti dan selalu dipengaruhi oleh rakan sekerja yang lain dimana orang yang berbuat banyak tidak dapat apa-apa.</em></p>', NULL, NULL, '2024-11-22 11:27:18', '2024-11-22 11:27:18', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1712, 513, 2, '<p>Kadangkala menerima tugasan tambahan atau di luar bidang kerja tetapi dengan hati yang tidak rela dan mementingkan kepentingan diri sendiri.<br /><br /><em>Contoh: Kadangkala akan diminta untuk backup rakan sekerja yang bercuti tetapi dia akan membuat kerja secara tidak rela / memberi alasan bahawa dia tidak tahu buat kerja tersebut.</em></p>', NULL, NULL, '2024-11-22 11:27:27', '2024-11-22 11:27:27', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1713, 513, 3, '<p>Rela menerima tugasan tambahan atau di luar bidang dan tidak menolak apabila tugas diberi.<br /><br /><em>Contoh: Rela backup rakan sekerja yang bercuti dan tidak menolak apabila tugas diberi oleh Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-22 11:27:39', '2024-11-22 11:27:39', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1714, 513, 4, '<p>Rela menerima tugasan tambahan atau di luar bidang dan tidak menolak apabila tugas diberi serta cuba mencari cara untuk menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Rela backup rakan sekerja yang bercuti dan tidak menolak apabila tugas diberi oleh Leader / Supervisor. Selain itu, dia juga cari jalan untuk mengeluarkan hasil kerja yang baik / membuat kerja tersebut dengan bersungguh-sungguh.</em></p>', NULL, NULL, '2024-11-22 11:27:50', '2024-11-22 11:27:50', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1715, 513, 5, '<p>Amat rela menerima tugasan tambahan atau di luar bidang dan menerimanya sebagai satu cabaran. Berusaha dan bertanggungjawab sepenuhnya sehingga tugasan selesai dengan sempurna.<br /><br /><em>Contoh: Sangat rela backup rakan sekerja yang bercuti dan menganggap tugas yang diberi tersebut sebagai satu cabaran / tugas sendiri. Dia membuat kerja dengan sepenuh hati dan mengambil tanggungjawab sehingga tugasan tersebut selesai dengan sempurnanya.</em></p>', NULL, NULL, '2024-11-22 11:28:05', '2024-11-22 11:28:05', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1716, 526, 1, '<p>Tidak dapat menyiapkan tugasan mengikut masa yang ditetapkan dan selalu dibuat semula oleh rakan sekerja yang lain dan menyebabkan kelewatan.<br /><br /><em>Contoh: Kerja yang sepatutnya boleh disiapkan dalam sehari tetapi dia selalu tidak hadir bekerja dan kerjanya perlu disambung / dibuat semula oleh rakan sekerja yang lain dan menyebabkan kelewatan.</em></p>', NULL, NULL, '2024-11-22 16:26:42', '2024-11-22 16:26:42', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1717, 526, 2, '<p>Selalu mengambil masa yang panjang untuk menyiapkan kerja walaupun bimbingan sudah diberi.<br /><br /><em>Contoh: Kerja yang sepatutnya boleh disiapkan dalam sehari tetapi dia mengambil masa yang panjang walaupun bimbingan sudah diberi.</em></p>', NULL, NULL, '2024-11-22 16:28:07', '2024-11-22 16:28:07', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1718, 526, 3, '<p>Tugasan biasanya dapat disiapkan dengan sedikit bimbingan dan siap dalam masa yang ditetapkan mahupun lebih awal dan hasil kerja yang masih boleh diterima.<br /><br /><em>Contoh: Boleh menghasilkan kerja dalam masa yang ditetapkan tetapi masih perlu dalam pengawasan/bimbingan.</em></p>', NULL, NULL, '2024-11-22 16:28:17', '2024-11-22 16:28:17', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1719, 526, 4, '<p>Tugasan sentiasa disiapkan tanpa bimbingan dan mengikut jadual mahupun lebih awal dan hasil kerja yang agar memuaskan.<br /><br /><em>Contoh: Boleh menghasilkan kerja dalam masa yang pendek dan tanpa sebarang pengawasan/bimbingan seperti dia cuma perlu 5 jam untuk menghasilkan kerja yang dijangka siap dalam sehari dan dia boleh menghasilkan lebih dalam satu hari.</em></p>', NULL, NULL, '2024-11-22 16:28:27', '2024-11-22 16:28:27', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1720, 526, 5, '<p>Mengutamakan masa dan pantas dalam menyiapkan tugasan yang diberi dan hasil kerja sangat bagus dan boleh diharapkan.<br /><br /><em>Contoh:Boleh membuat apa kerja yang dirancang dan menepati masa yang ditetapkan atau lebih awal tanpa pengawasan/bimbingan. Individu yang teliti dan prihatin dan menguasa masa dan memberi hasil kerja yang sangat bagus dan halus.</em></p>', NULL, NULL, '2024-11-22 16:28:38', '2024-11-22 16:28:38', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1721, 527, 1, '<p>Suka menolak tanggungjawab kerja dan berpura-pura/berdiam diri walaupun tahu apa cara untuk membuat kerja/menyelesaikan masalah.<br /><br /><em>Contoh: Langsung tidak bergerak dan pakai duduk dan tunggu sahaja walaupun sudah diberi penjelasan dalam pelan kerja.</em></p>', NULL, NULL, '2024-11-22 16:29:09', '2024-11-22 16:29:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1722, 527, 2, '<p>Kadangkala menolak tanggungjawab kerja dan berpura-pura/berdiam diri walaupun tahu apa cara untuk membuat kerja/menyelesaikan masalah.<br /><br /><em>Contoh: Tidak berusaha untuk belajar dan memahami pembacaan pelan kerja dan ukuran serta memerlukan seseorang mengawasi di tepi dan selalu memberi penjelasan boleh baru dapat menghasilkan kerja yang ditugaskan.</em></p>', NULL, NULL, '2024-11-22 16:34:44', '2024-11-22 16:34:44', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1723, 527, 3, '<p>Sudah faham dan boleh terus bertindak/bergerak ke atas kerja yang telah diselesaikan.&nbsp;<br /><br /><em>Contoh: Sudah tahu membuat kerja/menyelesaikan masalah dan tidak menolak tanggungjawab.</em></p>', NULL, NULL, '2024-11-22 16:34:54', '2024-11-22 16:34:54', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1724, 527, 4, '<p>Sudah faham dan boleh bertindak cepat ke atas semua tugasan serta tidak perlu pengawasan/bimbingan dan akan lapor balik apabila kerja telah siap.<br /><br /><em>Contoh: Bertanggungjawab dan tidak berpura-pura atau berdiam diri dalam membuat kerja/menyelesaikan masalah dan tidak perlu pengawasan/bimbingan dan akan bertindak/bergerak ke atas kerja yang ditugaskan serta lapor balik apabila kerja telah siap.</em></p>', NULL, NULL, '2024-11-22 16:35:04', '2024-11-22 16:35:04', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1725, 527, 5, '<p>Sudah faham dan boleh bertindak cepat ke atas semua tugasan serta tidak perlu pengawasan/bimbingan dan akan lapor balik apabila kerja telah siap. Selain itu, dapat memberi nasihat kepada rakan sekerja yang lain supaya cepat bertindak dalam kerja.<br /><br /><em>Contoh: Bertanggungjawab dan tidak berpura-pura atau berdiam diri dalam membuat kerja/menyelesaikan masalah dan tidak perlu pengawasan/bimbingan dan akan bertindak/bergerak ke atas kerja yang ditugaskan serta lapor balik apabila kerja telah siap. Selain itu, juga memotivasikan rakan sekerja supaya tidak berpura-pura/berdiam diri dalam &nbsp;membuat kerja/menyelesaikan masalah.</em></p>', NULL, NULL, '2024-11-22 16:35:16', '2024-11-22 16:35:16', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1726, 528, 1, '<p>Tidak membuat kerja secara sistematik dan tidak tahu membezakan kepentingan kerja.<br /><br /><em>Contoh: Tidak tahu membezakan kepentingan kerja dan tidak buat perancangan kerja.</em></p>', NULL, NULL, '2024-11-22 16:35:46', '2024-11-22 16:35:46', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1727, 528, 2, '<p>Kadangkala ada membuat kerja secara sistematik dan kadangkala tahu membezakan kepentingan kerja tetapi keadaan tidak ketara.<br /><br /><em>Contoh: Kadangkala tahu membezakan kepentingan kerja dan buat perancangan kerja tetapi tidak selalu dan ikut mood sendiri.</em></p>', NULL, NULL, '2024-11-22 16:35:55', '2024-11-22 16:35:55', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1728, 528, 3, '<p>Tidak perlu seseorang mengawasi di tepi dan tahu membuat kerja secara sistematik dan tahu membezakan kepentingan kerja dengan penjelasan yang ringkas sahaja.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan memerlukan penjelasan kerja yang ringkas sahaja.</em></p>', NULL, NULL, '2024-11-22 16:36:03', '2024-11-22 16:36:03', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1729, 528, 4, '<p>Hanya memerlukan penjelasan yang ringkas dan tahu membuat kerja secara sistematik dan tahu membezakan kepentingan kerja. Berhati-hati dan tiada kesilapan dalam kerja yang dihasilkan.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan hanya memerlukan penjelasan kerja yang ringkas sahaja dan memberi tumpuan dalam kerja dan mengeluarkan hasil kerja yang baik.</em></p>', NULL, NULL, '2024-11-22 16:36:14', '2024-11-22 16:36:14', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1730, 528, 5, '<p>Hanya memerlukan penjelasan yang sangat ringkas sahaja untuk membuat kerja secara sistematik dan tahu membezakan kepentingan kerja dan dapat memberi tunjuk ajar kepada rakan sekerja.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan hanya memerlukan penjelasan kerja yang ringkas sahaja dan memberi tumpuan dalam kerja dan mengeluarkan hasil kerja yang baik dan turut memberi tunjuk ajar kepada rakan sekerja.</em></p>', NULL, NULL, '2024-11-22 16:36:24', '2024-11-22 16:36:24', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1731, 529, 1, '<p>Hasil kerja yang tidak boleh diterima dan selalu membuat kesilapan.<br /><br /><em>Contoh: Tidak menumpu perhatian semasa bekerja dan selalu membuat kesilapan yang sama. Tidak pernah berubah walaupun &nbsp;sudah diberi bimbingan/teguran seperti selalu mengulangi kesilapan yang sama walaupun sudah banyak kali memasang mesin yang sama model.</em></p>', NULL, NULL, '2024-11-22 16:37:20', '2024-11-22 16:37:20', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1732, 529, 2, '<p>Cuai dan mengakibatkan kesilapan kerja.<br /><br /><em>Contoh: Kadangkala cuai semasa bekerja dan mengakibatkan kesilapan kerja kerana tindakan yang lambat untuk berubah setelah diberi bimbingan/teguran.</em></p>', NULL, NULL, '2024-11-22 16:37:29', '2024-11-22 16:37:29', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1733, 529, 3, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan meminimumkan tahap kesilapan kepada yang terendah.<br /><br /><em>Contoh: Kadangkala ada membuat kesilapan tetapi mengambil tindakan yang cepat untuk berubah setelah diberi bimbingan/teguran.</em></p>', NULL, NULL, '2024-11-22 16:37:39', '2024-11-22 16:37:39', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1734, 529, 4, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan apa-apa kesilapan dalam kerja harian.<br /><br /><em>Contoh: Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan. Selain itu, juga berinisiatif untuk menjaga barangan/bahan dan tidak membazir.</em></p>', NULL, NULL, '2024-11-22 16:37:51', '2024-11-22 16:37:51', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1735, 529, 5, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan kerja dan berinisiatif untuk memberi pendapat dan memperbaiki cara kerja yang lebih baik untuk meminimumkan tahap kesilapan kerja.<br /><br /><em>Contoh: Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan dan berinisiatif untuk memberi pendapat dan memperbaiki cara kerja untuk meminimumkan tahap kesilapan kerja seperti berinisiatif untuk mengetahui masalah semasa pemasangan mesin dan turut memberi pendapat untuk memperbaiki cara kerja/menyelesaikan masalah.</em></p>', NULL, NULL, '2024-11-22 16:38:02', '2024-11-22 16:38:02', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1736, 530, 1, '<p>Langsung tidak memahami permintaan kualiti kerja dan tidak memberi perhatian kepada kerja yang dilakukan.<br /><br /><em>Contoh: Langsung tidak memahami permintaan kualiti kerja dan tidak memberi perhatian terhadap semua kerja yang dilakukan seperti membuat pemasangan Control Panel tetapi langsung tidak mengikut diagram yang diberi.</em></p>', NULL, NULL, '2024-11-22 16:54:12', '2024-11-22 16:54:12', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1737, 530, 2, '<p>Kadangkala tidak faham spesifikasi kerja yang diberi dan tidak berinisiatif mengambil langkah untuk mengetahui untuk menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Tidak berinisiatif untuk bertanya/kurang bertanya apabila tidak tahu semasa memasang Control Panel dan pasang ikut sendiri dan tidak ikut cara kerja yang betul.</em></p>', NULL, NULL, '2024-11-22 16:54:22', '2024-11-22 16:54:22', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1738, 530, 3, '<p>Memahami permintaan kualiti kerja dan dapat menghasilkan kerja yang berkualiti secara individu tanpa pengawasan pegawai atasan tetapi tidak mengambil perhatian dan abaikan kerja yang remeh temeh serta tidak mengambil perhatian terhadap kekemasan hasil kerja.<br /><br /><em>Contoh: Tahu pasang Control Panel tetapi tidak terfikir tentang kekemasan. Wayar sudah ditarik dengan betul tetapi tidak diikat dengan cable tie/tidak tersusun/tidak label semasa membuat pemasangan.</em></p>', NULL, NULL, '2024-11-22 16:54:33', '2024-11-22 16:54:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1739, 530, 4, '<p>Faham tentang kualiti dan dapat menghasilkan kerja yang berkualiti dan memenuhi kehendak syarikat dan dapat memastikan kerja yang dihasilkan tidak bermasalah.<br /><br /><em>Contoh: Faham tentang kualiti kerja dan ikut semua spesifikasi yang diminta. Boleh berfikir dan nampak (meramalkan) ke hadapan dan memastikan kerja yang dihasilkan tidak bermasalah seperti tahu pasang Control Panel dan semua litar boleh berfungsi dengan baik dan pemasangan yang kemas dan melaporkan keadaan kepada Leader/Supervisor apabila litar tidak berfungsi/bernyala.</em></p>', NULL, NULL, '2024-11-22 16:54:43', '2024-11-22 16:54:43', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1740, 530, 5, '<p>Sangat faham tentang kualiti kerja dan dapat menghasilkan kerja yang berkualiti dan memenuhi kehendak syarikat dan dapat memastikan kerja yang dihasilkan tidak bermasalah serta turut memberi tunjuk ajar kepada rakan kerja yang lain.&nbsp;<br /><br /><em>Contoh: Sangat faham tentang kualiti kerja dan ikut semua spesifikasi yang diminta. Boleh berfikir dan nampak (meramalkan) ke hadapan dan memastikan kerja yang dihasilkan tidak bermasalah. Selain itu, juga dapat memberi tunjuk ajar kepada rakan sekerja yang lain seperti tahu pasang Control Panel dan semua litar boleh berfungsi dengan baik dan pemasangan yang kemas dan melaporkan keadaan kepada Leader/Supervisor apabila litar tidak berfungsi/bernyala. Selain itu, dia juga memberi tunjuk ajar kepada rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-22 16:54:54', '2024-11-22 16:54:54', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1741, 531, 1, '<p>Sentiasa membazirkan/merosakkan sumber syarikat.<br /><br /><em>Contoh: Tidak pernah berhati-hati dalam spesifikasi kerja yang diberi dan sentiasa mengakibatkan pembaziran bahan.</em></p>', NULL, NULL, '2024-11-22 17:18:42', '2024-11-22 17:18:42', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1742, 531, 2, '<p>Ada bersikap mahu menjimatkan sumber syarikat tetapi kadangkala menyebabkan pembaziran di atas kecuaiannya.<br /><br /><em>Contoh: Cuai dalam pembacaan spesifikasi kerja yang diberi dan silap ambil bahan dan menyebabkan kesilapan dan membazirkan bahan serta perlu &ldquo;rework&rdquo;.</em></p>', NULL, NULL, '2024-11-22 17:18:51', '2024-11-22 17:18:51', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1743, 531, 3, '<p>Berhati-hati semasa bekerja dan menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dan memastikan betul supaya tidak berlaku kesilapan yang mengakibatkan pembaziran bahan dan buang masa.</em></p>', NULL, NULL, '2024-11-22 17:19:01', '2024-11-22 17:19:01', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1744, 531, 4, '<p>Berhati-hati semasa bekerja dan berinisiatif menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya. Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dengan pelan kerja dan memastikan semua barang yang ambil adalah betul. Ada pemikiran tidak membazir seperti dalam menghasilkan sesuatu barang yang sangat kecil, dia akan cari scrap dahulu dan tidak guna bahan yang baru atau bahan yang besar.Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan.</em></p>', NULL, NULL, '2024-11-22 17:19:15', '2024-11-22 17:19:15', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1745, 531, 5, '<p>Berhati-hati semasa bekerja dan berinisiatif menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya. Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan dan juga menyedarkan dan membetulkan kesilapan rakan sekerja yang lain.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dengan pelan kerja dan memastikan semua barang yang ambil adalah betul. Ada pemikiran tidak membazir seperti dalam menghasilkan sesuatu barang yang sangat kecil, dia akan cari scrap dahulu dan tidak guna bahan yang baru atau bahan yang besar.Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan dan menyedarkan dan membetulkan kesilapan rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-22 17:19:27', '2024-11-22 17:19:27', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1746, 532, 1, '<p>Pengetahuan atau kemahiran adalah terhad dan tidak dapat menyelesaikan tugasan dan menggunakan masa yang panjang untuk mempelajari pengetahuan dan cara kerja yang agak senang.<br /><br /><em>Contoh: Tidak ada pengetahuan dan kemahiran kerja dan menggunakan masa yang panjang untuk mempelajari cara kerja yang senang walaupun bimbingan telah diberi seperti membuat kerja kimpalan yang paling senang iaitu mengimpal besi dalam kedudukan rata.</em></p>', NULL, NULL, '2024-11-22 17:20:52', '2024-11-22 17:20:52', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1747, 532, 2, '<p>Kurang pengetahuan atau kemahiran yang cukup untuk mengendalikan tugasan.<br /><br /><em>Contoh: Hasil kimpalan yang teruk dan bimbingan masih diperlukan walaupun diminta menghasilkan kerja kimpalan yang agak senang seperti mengimpal besi dalam kedudukan rata dan mendatar.</em></p>', NULL, NULL, '2024-11-22 17:21:01', '2024-11-22 17:21:01', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1748, 532, 3, '<p>Mempunyai pengetahuan dan kemahiran untuk mengendalikan tugasan dan mempunyai sikap mahu belajar dan mempelajari pengetahuan kerja yang baru dalam masa yang singkat dan mengimplikasikan dalam kerja harian.<br /><br /><em>Contoh: Ada pengetahuan dan kemahiran kimpalan tetapi tidak dapat meneruskan kerja apabila menghadapi kerja yang tidak biasa dan memerlukan bimbingan seperti: boleh mengimpal besi yang nipis tetapi tidak apabila diminta mengimpal besi yang lagi nipis / boleh mengimpal dalam kedudukan rata, mendatar dan menegak tetapi tidak apabila dalam keadaan overhead atau dalam keadaan 45 darjah.</em></p>', NULL, NULL, '2024-11-22 17:21:11', '2024-11-22 17:21:11', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1749, 532, 4, '<p>Boleh menguasai pengetahuan dan kemahiran untuk mengendalikan tugasan dan pencapaian yang agak memuaskan dan dapat menggunakan pengetahuannya untuk meningkatkan kualiti kerja.<br /><br /><em>Contoh: Mempunyai pengetahuan dan kemahiran yang luas serta jelas dengan semua keperluan/permintaan kerja seperti memilih kaedah yang bersesuaian untuk menghasilkan kerja dan tahu mengawal had api untuk mencegah hasil kerja dari kerosakan.</em></p>', NULL, NULL, '2024-11-22 17:21:23', '2024-11-22 17:21:23', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1750, 532, 5, '<p>Menguasai pengetahuan dan kemahiran untuk mengendalikan tugasan dan boleh menggabungkan pengetahuan untuk meningkatkan kualiti kerja serta mencari cara kerja baru untuk menyelesaikan masalah kerja dengan pengetahuannya.<br /><br /><em>Contoh: Mempunyai pengetahuan dan kemahiran yang luas serta jelas dengan semua keperluan/permintaan kerja dan berinisiatif memberi cadangan untuk menyelesaikan masalah kerja.&nbsp;</em></p>', NULL, NULL, '2024-11-22 17:21:41', '2024-11-22 17:21:41', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1751, 533, 1, '<p>Tidak pernah mengemas dan membersihkan tempat kerja sendiri dan sentiasa mengotorkan tempat kerja sendiri dan rakan sekerja yang lain.<br /><br /><em>Contoh: Tidak pernah terfikir kebaikan bersama dan terus membuang sisa kerja ke lantai dan menganggap ini kerja cleaner untuk membersihkan.</em></p>', NULL, NULL, '2024-11-22 17:22:21', '2024-11-22 17:22:31', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1752, 533, 2, '<p>Kadangkala ada mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya tidak kemas.<br /><br /><em>Contoh: Tidak selalu mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya tidak kemas seperti kadangkala ada membersihkan tempat kerja dan kadangkala tidak.</em></p>', NULL, NULL, '2024-11-22 17:22:40', '2024-11-22 17:22:40', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1753, 533, 3, '<p>Berinisiatif untuk mengemas dan membersihkan tempat kerja dan kebanyakan masa tempat kerjanya adalah kemas dan bersih.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai.</em></p>', NULL, NULL, '2024-11-22 17:22:49', '2024-11-22 17:22:49', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1754, 533, 4, '<p>Selalu mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya kemas dan selalu menolong membersihkan kawasan bahagiannya (division) dan kilang.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai serta tolong membersihkan kawasan yang lain.</em></p>', NULL, NULL, '2024-11-22 17:22:59', '2024-11-22 17:22:59', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1755, 533, 5, '<p>Selalu mengemas dan membersihkan tempat kerja dan tempat kerjanya kelihatan kemas dan bersih. Juga selalu menjaga kebersihan seluruh kawasan kilang dan dapat menegur rakan sekerja untuk menjaga kebersihan kilang.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai serta tolong menjaga kebersihan kawasan yang lain dan menegur rakan sekerja yang tidak menjaga kebersihan kilang.</em></p>', NULL, NULL, '2024-11-22 17:23:09', '2024-11-22 17:23:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1756, 534, 1, '<p>Tidak menjaga peralatan dan kemudahan syarikat.<br /><br /><em>Contoh: Tidak menjaga peralatan dan kemudahan syarikat seperti tidak menjaga forklift dan tidak pernah meletakkkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-22 17:23:36', '2024-11-22 17:23:36', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1757, 534, 2, '<p>Kadangkala bersikap cuai dalam mengendali peralatan dan kemudahan syarikat dan mengakibatkan kerosakan.<br /><br /><em>Contoh: Tidak selalu menjaga peralatan dan kemudahan syarikat dan mengakibatkan kerosakan seperti forklift terus jalan setelah enjin dihidupkan. Tidak mengambil berat tentang barang yang diangkat dan masuk ke ruang yang kecil. Selalu tidak meletakkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-22 17:43:51', '2024-11-22 17:43:51', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1758, 534, 3, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat dengan cara yang betul.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-22 17:44:22', '2024-11-22 17:44:22', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1759, 534, 4, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat demi kebaikan bersama. Selain itu, &nbsp;melaporkan kepada pihak atasan bila nampak rakan sekerja salahguna dan memberi cara penyelesaian yang bermanfaat.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna dan melapor jika ada kerosakan dan memberi cadangan untuk memperbaiki cara penggunaan dan penjagaan alatan.</em></p>', NULL, NULL, '2024-11-22 17:44:32', '2024-11-22 17:44:32', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1760, 534, 5, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat demi kebaikan bersama. Selain itu, &nbsp;melaporkan kepada pihak atasan bila nampak pekerja salahguna dan memberi cara penyelesaian yang bermanfaat. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna dan melapor jika ada kerosakan dan memberi cadangan untuk memperbaiki cara penggunaan dan penjagaan alatan.Selain itu, akan menyedarkan dan menasihati rakan sekerja yang tidak menjaga forklift semasa mengguna.</em></p>', NULL, NULL, '2024-11-22 17:44:50', '2024-11-22 17:44:50', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1761, 535, 1, '<p>Tidak mengutamakan keselamatan semasa bekerja.<br /><br /><em>Contoh: Tidak mengutamakan keselamatan semasa bekerja seperti tidak memakai PPE semasa bekerja.</em></p>', NULL, NULL, '2024-11-22 17:45:41', '2024-11-22 17:45:41', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1762, 535, 2, '<p>Ada sikap mengutamakan keselamatan tetapi kadangkala tidak.<br /><br /><em>Contoh: Ada memakai PPE semasa bekerja tetapi kadangkala tidak.</em></p>', NULL, NULL, '2024-11-22 17:45:51', '2024-11-22 17:45:51', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1763, 535, 3, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja.</em></p>', NULL, NULL, '2024-11-22 17:46:03', '2024-11-22 17:46:03', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1764, 535, 4, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan.</em></p>', NULL, NULL, '2024-11-22 17:46:13', '2024-11-22 17:46:13', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1765, 535, 5, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja dan melaporkan kepada pihak atasan serta turut memberi cara atau cara penyelesaian yang bermanfaat.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan serta turut memberi cara atau cara penyelesaian yang bermanfaat.</em></p>', NULL, NULL, '2024-11-22 17:46:26', '2024-11-22 17:46:26', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1766, 536, 1, '<p>Menerima tugasan tetapi tidak memikul tanggungjawab kerja dan tidak dapat bekerja di bawah tekanan.<br /><br /><em>Contoh: Dia terima kerja yang diberi tetapi sentiasa bersembang dengan rakan sekerja dan tidak buat kerja sehingga tidak nampak hasil kerja.</em></p>', NULL, NULL, '2024-11-22 17:55:34', '2024-11-22 17:55:34', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1767, 536, 2, '<p>Boleh menerima dan memikul tanggungjawab dan cuba untuk bekerja di bawah tekanan tetapi kadangkala tidak dapat menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Dia boleh buat kerja dan cuba elakkan diri dari tidak masuk kerja/tidak memberi alasan untuk bercuti tetapi kadangkala masih perlu dalam bimbingan.</em></p>', NULL, NULL, '2024-11-22 17:55:45', '2024-11-22 17:55:45', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1768, 536, 3, '<p>Boleh menerima dan memikul tanggungjawab dan dapat menghabiskan setiap kerja yang diamanahkan dengan baik di bawah tekanan dan melaporkan kerja yang telah dilakukan kepada pegawai atasan.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia masih menepati target dan ikut piawai kerja yang ditetapkan oleh syarikat. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia juga akan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-22 17:56:10', '2024-11-22 17:56:10', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1769, 536, 4, '<p>Rela menerima dan memikul tanggungjawab dan sentiasa dapat menghasilkan kerja yang berkualiti di bawah tekanan dan dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang dilakukan kepada pegawai atasan.Boleh buat kerja lebih masa sehingga kerja siap.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia akan menawarkan diri secara sukarela untuk kerja tersebut serta menepati target dan ikut piawai kerja yang ditetapkan oleh syarikat. Boleh buat kerja lebih masa sehingga kerja siap. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-22 17:56:20', '2024-11-22 17:56:20', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1770, 536, 5, '<p>Rela menerima dan memikul tanggungjawab serta tahu kepentingan dan deadline kerja. Dapat memanggil rakan sekerja untuk menyiapkan kerja bersama. Sentiasa dapat menghasilkan kerja yang berkualiti di bawah tekanan dan dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang dilakukan kepada pegawai atasan.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia tahu kepentingan dan deadline kerja tersebut serta dapat memanggil rakan sekerja untuk menyiapkan kerja bersama. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-22 17:56:31', '2024-11-22 17:56:31', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1771, 537, 1, '<p>Tidak rela mengaku kesilapan dan suka menolak tanggungjawab kepada orang lain.<br /><br /><em>Contoh: Telah melakukan kesilapan seperti tidak mengikuti spesifikasi kerja yang diberi oleh Leader / tidak tanya Leader apabila tidak faham / tanya rakan sekerja yang tidak dipertanggungjawabkan dan tidak pernah mengakui kesilapan apabila ditegur oleh Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-22 17:58:22', '2024-11-22 17:58:22', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1772, 537, 2, '<p>Kadangkala tidak rela mengaku kesilapan dan suka membuat perbandingan diri dengan orang lain dalam kesilapan yang telah dibuat.<br /><br /><em>Contoh: Telah melakukan kesilapan seperti tidak mengikuti spesifikasi kerja yang diberi oleh Leader / tidak tanya Leader apabila tidak faham / tanya rakan sekerja yang tidak dipertanggungjawabkan dan kadangkala tidak mengakui kesilapan apabila ditegur oleh Leader/Supervisor malah menyatakan Leader/Supervisor ada prasangka terhadap dia.</em></p>', NULL, NULL, '2024-11-22 17:58:37', '2024-11-22 17:58:37', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1773, 537, 3, '<p>Mengaku kesilapan dan tidak menolak tanggungjawab kepada orang lain.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan. Dia terima dan mengakui kesilapan.</em></p>', NULL, NULL, '2024-11-22 17:58:49', '2024-11-22 17:58:49', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1774, 537, 4, '<p>Tidak melarikan diri dari tanggungjawab dan terus berjumpa dengan pihak atasan untuk mengakui kesilapan dan berinisiatif untuk memperbaiki kesilapan yang telah dilakukan.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan. Dia tidak melarikan diri dari tanggungjawab dan terus berjumpa dengan Leader/Supervisor dan mengakui kesilapan. Selain itu, dia juga memberi cadangan dan sama-sama memperbaiki kesilapan yang telah dilakukan.</em></p>', NULL, NULL, '2024-11-22 17:58:58', '2024-11-22 17:58:58', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1775, 537, 5, '<p>Berani mengaku kesilapan dan tidak menolak tanggungjawab dan memastikan kesilapan tidak berlaku lagi. Berinisiatif untuk memperbetulkan kesilapan dan dapat memberi cadangan yang bermanfaat untuk mengelakkan kesilapan berlaku lagi.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan yang agak besar. Dia berani mengakui kesilapan dan terus berjumpa dengan Leader/Supervisor untuk mengakui kesilapan. Dia mengambil pengalaman tersebut sebagai satu pengajaran dan tidak mengulangi kesilapan tersebut lagi. Selain itu, dia &nbsp;memberi cadangan dan sama-sama memperbaiki kesilapan yang telah dilakukan serta memberi cadangan yang bermanfaat untuk mengelakkan kesilapan berlaku lagi.</em></p>', NULL, NULL, '2024-11-22 17:59:09', '2024-11-22 17:59:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1776, 538, 1, '<p>Membuat kerja alah kadar dan setakat membuat kerja sahaja dan tidak menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Tidak menunjukkan sikap ingin belajar dan tidak menumpukan perhatian semasa bekerja seperti dia boleh mengambil masa yang panjang untuk memasang beberapa nut pada mesin.</em></p>', NULL, NULL, '2024-11-23 11:52:26', '2024-11-23 11:52:26', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1777, 538, 2, '<p>Boleh membuat kerja tetapi mudah dipengaruhi orang lain dan kadangkala tidak dapat menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Dia boleh pasang nut pada mesin tetapi mudah dipengaruhi oleh rakan sekerja yang lain seperti dia akan melambatkan proses kerjanya dan sambil kerja sambil bersembang apabila ada rakan sekerja yang bersembang dengannya semasa bekerja.</em></p>', NULL, NULL, '2024-11-23 11:52:35', '2024-11-23 11:52:35', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1778, 538, 3, '<p>Lebih agresif dan sikap kerja juga serius dan dapat menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak mengangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja.</em></p>', NULL, NULL, '2024-11-23 11:52:46', '2024-11-23 11:52:46', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1779, 538, 4, '<p>Bersemangat kerja dan menumpukan perhatian sepenuhnya dalam kerja. Sentiasa mengutamakan kualiti kerja dan menghasilkan kerja yang halus dan teliti dan tidak melakukan kesilapan.<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak menggangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja. Dia sentiasa mengutamakan kualiti kerja dan memastikan nut yang dipasang itu betul dan kemas.</em></p>', NULL, NULL, '2024-11-23 11:52:59', '2024-11-23 11:52:59', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1780, 538, 5, '<p>Matlamat untuk berjaya sangat jelas. Menumpukan perhatian sepenuhnya dalam kerja. Sentiasa mengutamakan kualiti kerja dan menghasilkan kerja yang halus dan teliti dan tidak melakukan kesilapan. Selain itu turut memberi cadangan dan cara kerja untuk memastikan kerja berkualiti dihasilkan setiap kali.&nbsp;<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak menggangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja. Dia sentiasa mengutamakan kualiti kerja dan memastikan nut yang dipasang itu betul dan kemas. Selain itu, dia juga akan memberi cadangan untuk memastikan kerja berkualiti dapat dihasilkan.</em></p>', NULL, NULL, '2024-11-23 11:53:09', '2024-11-23 11:53:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1781, 539, 1, '<p>Langsung tidak mahu memahami dan menerima peraturan dan polisi syarikat dan sentiasa membuat aduan terhadap dasar syarikat.<br /><br /><em>Contoh: Selalu tidak menutup lampu setelah mengguna tandas dan membuat aduan apabila pihak syarikat mengambil tindakan.</em></p>', NULL, NULL, '2024-11-23 11:53:41', '2024-11-23 11:53:41', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1782, 539, 2, '<p>Kadangkala sahaja mahu menerima dan mematuhi peraturan dan polisi syarikat.<br /><br /><em>Contoh: Kadangkala ada menutup lampu setelah mengguna tandas kadangkala tidak.</em></p>', NULL, NULL, '2024-11-23 11:53:54', '2024-11-23 11:53:54', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1783, 539, 3, '<p>Menerima dan mematuhi setiap peraturan dan polisi syarikat.<br /><br /><em>Contoh: Setiap kali akan menutup lampu setelah mengguna tandas.</em></p>', NULL, NULL, '2024-11-23 11:54:08', '2024-11-23 11:54:08', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1784, 539, 4, '<p>Tidak melanggar peraturan dan sentiasa dapat menasihatkan rakan sekerja untuk menerima dan mematuhi peraturan dan polisi syarikat untuk kebaikan bersama.<br /><br /><em>Contoh: Sentiasa menutup lampu setelah mengguna tandas dan &nbsp;menasihati dan menerang kepada rakan sekerja yang tidak mematuhi peraturan.</em></p>', NULL, NULL, '2024-11-23 11:54:25', '2024-11-23 11:54:25', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1785, 539, 5, '<p>Memahami dan menerima setiap peraturan dan polisi syarikat dan sentiasa menasihatkan rakan sekerja yang melanggar peraturan serta melaporkan masalah disiplin kepada pegawai atasan untuk kebaikan bersama.<br /><br /><em>Contoh: &nbsp;Sentiasa menutup lampu setelah mengguna tandas dan &nbsp;menasihati dan menerang kepada rakan sekerja yang tidak mematuhi peraturan. Selain itu, juga akan melaporkan nama pekerja yang tidak menutup lampu setelah mengguna tandas.</em></p>', NULL, NULL, '2024-11-23 11:54:38', '2024-11-23 11:54:38', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1786, 540, 1, '<p>Selalu tidak tepat masuk kerja dan menunjukkan kedatangan yang tidak baik.<br /><br /><em>Contoh: Masih berada di tempat berehat semasa siren berbunyi dan jalan perlahan ke tempat kerja.</em></p>', NULL, NULL, '2024-11-23 11:55:04', '2024-11-23 11:55:04', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1787, 540, 2, '<p>Kadangkala ada masuk kerja pada masa yang ditetapkan tetapi keadaan tidak ketara.<br /><br /><em>Contoh: Kadangkala ada tepat masuk kerja semasa siren berbunyi tetapi kebanyakan masa tidak masuk kerja pada masa yang tepat.</em></p>', NULL, NULL, '2024-11-23 11:55:21', '2024-11-23 11:55:21', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1788, 540, 3, '<p>Kebanyakan masa masuk kerja pada masa yang ditetapkan tetapi kadangkala ada lewat juga.<br /><br /><em>Contoh: Kebanyakan masa masuk kerja semasa siren berbunyi tetapi sekali kala masih lewat masuk kerja.</em></p>', NULL, NULL, '2024-11-23 11:55:32', '2024-11-23 11:55:32', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1789, 540, 4, '<p>Mementingkan ketepatan masa masuk kerja dan masuk kerja tepat pada masa atau lebih awal.<br /><br /><em>Contoh: Sentiasa masa masuk kerja sebelum siren berbunyi atau lebih awal.</em></p>', NULL, NULL, '2024-11-23 11:55:42', '2024-11-23 11:55:42', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1790, 540, 5, '<p>Mementingkan ketepatan masa masuk kerja dan masuk kerja tepat pada masa atau lebih awal serta memberi nasihat kepada rakan sekerja yang lewat.<br /><br /><em>Contoh: Sentiasa masa masuk kerja sebelum siren berbunyi atau lebih awal serta memberi nasihat kepada rakan sekerja yang lewat.</em></p>', NULL, NULL, '2024-11-23 11:55:55', '2024-11-23 11:55:55', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1791, 541, 1, '<p>Disiplin diri yang tidak memuaskan dan sering meninggalkan tempat kerja dengan berkeliaran tanpa tujuan dan sering membazirkan masa serta curi tulang.<br /><br /><em>Contoh: Sering meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja (banyak kali sehari) dan mengambil masa yang panjang dalam tandas serta membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-23 11:56:18', '2024-11-23 11:56:18', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1792, 541, 2, '<p>Kadangkala membazirkan masa dan curi tulang serta meninggalkan tempat kerja dengan berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Kadangkala meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja (banyak kali sehari) dan mengambil masa yang panjang dalam tandas serta membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-23 11:56:28', '2024-11-23 11:56:28', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1793, 541, 3, '<p>Tidak membazirkan masa dan ringan tulang serta menumpukan perhatian semasa bekerja. Tidak meninggalkan tempat kerja dengan berkeliaran tanpa tujuan.<br /><br /><em>Contoh: Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-23 11:56:38', '2024-11-23 11:56:38', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1794, 541, 4, '<p>Teladan yang baik dan tumpuan perhatian sepenuhnya semasa bekerja. Tidak berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Seorang teladan yang baik dan memberi tumpuan sepenuhnya semasa bekerja. Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-23 11:56:47', '2024-11-23 11:56:47', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1795, 541, 5, '<p>Teladan yang baik dan tumpuan perhatian sepenuhnya semasa bekerja dan juga selalu memberi nasihat kepada rakan sekerja supaya melahirkan keadaan kerja yang lebih agresif. Tidak berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Seorang teladan yang baik dan memberi tumpuan sepenuhnya semasa bekerja. Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja. Selalu memberi nasihat kepada rakan sekerja yang selalu pergi ke tandas sebagai alasan.</em></p>', NULL, NULL, '2024-11-23 11:57:02', '2024-11-23 11:57:02', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1796, 542, 1, '<p>Tidak pernah berada di tempat kerja semasa pembersihan kawasan dijalankan.<br /><br /><em>Contoh: Tidak berada di tempat kerja dan pergi ke tandas semasa pembersihan kawasan dijalankan.</em></p>', NULL, NULL, '2024-11-23 11:57:27', '2024-11-23 11:57:27', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1797, 542, 2, '<p>Memulakan kerja pembersihan kawasan walaupun masa yang ditetapkan belum sampai lagi.<br /><br /><em>Contoh: Memulakan kerja pembersihan kawasan walaupun masa yang ditetapkan belum sampai lagi dan rakan sekerja yang lain masih bekerja lagi.</em></p>', NULL, NULL, '2024-11-23 11:57:39', '2024-11-23 11:57:39', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1798, 542, 3, '<p>Kebanyakan masa membersihkan kawasan production pada masa yang ditetapkan.</p><p>Kadangkala membersihkan kawasan production pada masa yang ditetapkan tetapi keadaan tidak ketara.</p><p><br />\nContoh: Kadangkala ada berada di production semasa pembersihan kawasan dijalankan tetapi kebanyakan masa tidak nampak orang.</p>', NULL, NULL, '2024-11-23 11:57:49', '2024-11-23 11:57:49', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1799, 542, 4, '<p>Sentiasa mengutamakan dan membersihkan kawasan production pada masa yang ditetapkan.<br /><br /><em>Contoh: Sentiasa membersihkan kawasan production pada masa yang ditetapkan.</em></p>', NULL, NULL, '2024-11-23 11:58:46', '2024-11-23 11:58:46', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1800, 542, 5, '<p>Mengutamakan dan membersihkan kawasan production pada masa yang ditetapkan serta memberi nasihat kepada rakan sekerja yang tidak berbuat demikian.<br /><br /><em>Contoh: Sentiasa membersihkan kawasan production pada masa yang ditetapkan dan memberi nasihat kepada rakan sekerja yang tidak berbuat demikian.</em></p>', NULL, NULL, '2024-11-23 11:59:01', '2024-11-23 11:59:01', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1801, 543, 1, '<p>Hanya menghormati pegawai atasan dan tidak bersopan dengan rakan sekerja.<br /><br /><em>Contoh: Hanya menghormati Leader/Supervisor atau pangkat kerja yang lebih tinggi tetapi tidak bersopan dengan rakan sekerja yang berpangkat rendah/masih baru.</em></p>', NULL, NULL, '2024-11-23 11:59:31', '2024-11-23 11:59:31', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1802, 543, 2, '<p>Biasanya akan bersopan dan menghormati orang lain tetapi kadangkala beremosi.<br /><br /><em>Contoh: Biasanya bersopan dan menghormati rakan sekerja yang lain tetapi kadangkala beremosi dan lawan cakap.</em></p>', NULL, NULL, '2024-11-23 11:59:41', '2024-11-23 11:59:41', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1803, 543, 3, '<p>Sering bersopan dan menghormati orang lain dan tidak bertindak mengikut perasaan.<br /><br /><em>Contoh: Sering bersopan dan menghormati rakan sekerja lain dan tidak bertindak mengikut perasaan.</em></p>', NULL, NULL, '2024-11-23 11:59:51', '2024-11-23 11:59:51', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1804, 543, 4, '<p>Bersopan dan menghormati orang lain pada setiap masa dan tidak bertindak mengikut perasaan dan berbahasa sopan.<br /><br /><em>Contoh: Bersopan dan setiap masa menghormati rakan sekerja yang lain dan tidak bertindak mengikut perasaan dan berbahasa sopan serta jaga perasaan rakan lain.</em></p>', NULL, NULL, '2024-11-23 12:00:02', '2024-11-23 12:00:02', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1805, 543, 5, '<p>Bersopan dan menghormati orang lain pada setiap masa dan masih bercakap dengan sopan walaupun sendiri telah dipersalahkan dalam proses penyelesaian masalah.<br /><br /><em>Contoh: Bersopan dan setiap masa menghormati rakan sekerja yang lain dan masih bercakap dengan sopan walaupun sendiri telah dipersalahkan dalam proses penyelesaian masalah.</em></p>', NULL, NULL, '2024-11-23 12:00:17', '2024-11-23 12:00:17', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1806, 544, 1, '<p>Memang mengetahui arahan yang diberi mempunyai kesilapan tetapi tidak mendapatkan kepastian kerana berpendapat itu adalah tanggungjawab pegawai atasan.<br /><br /><em>Contoh: Tidak mendapatkan kepastian daripada Leader/Supervisor tentang spesifikasi kerja yang diberi walaupun sudah tahu arahan yang diberi mempunyai kesilapan/tidak jelas dan beranggap itu adalah tanggungjawab Leader/Supervisor dan bukan dia.</em></p>', NULL, NULL, '2024-11-23 12:00:57', '2024-11-23 12:00:57', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1807, 544, 2, '<p>Jarang berinisiatif untuk mendapatkan kepastian daripada pegawai atasan walaupun arahan yang diberi tidak jelas atau silap.<br /><br /><em>Contoh: Menunjukkan sikap sudah tahu tetapi tidak ingin peduli dan tidak mendapatkan kepastian daripada Leader/Supervisor walapun arahan yang diberi ada kesilapan/kurang jelas.</em></p>', NULL, NULL, '2024-11-23 12:01:06', '2024-11-23 12:01:06', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1808, 544, 3, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap tetapi tidak pernah melapor balik kepada pegawai atasan tentang tugasan tersebut.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi ada kesilapan/tidak jelas tetapi tidak pernah melapor balik tugasan tersebut.</em></p>', NULL, NULL, '2024-11-23 12:01:15', '2024-11-23 12:01:15', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1809, 544, 4, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi tidak jelas/silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut.</em></p>', NULL, NULL, '2024-11-23 12:01:25', '2024-11-23 12:01:25', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1810, 544, 5, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut serta memberi pendapat yang bermanfaat.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi tidak jelas/silap dan selalu melapor balik kepada Leader/Supervisor dan turut mengambil bahagian untuk memberi pendapat yang bermanfaat.</em></p>', NULL, NULL, '2024-11-23 12:01:36', '2024-11-23 12:01:36', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1811, 545, 1, '<p>Degil dan berpegang teguh dengan pendapat sendiri dan tidak menuruti arahan pegawai atasan.<br /><br /><em>Contoh: Tidak menerima dan melawan percakapan Leader/Supervisor semasa diberi tugasan.</em></p>', NULL, NULL, '2024-11-23 12:02:41', '2024-11-23 12:02:41', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1812, 545, 2, '<p>Kebanyakan masa akan menuruti arahan pegawai atasan tetapi kadangkala akan beremosi dan meluahkan ketidakpuasan.<br /><br /><em>Contoh: Kebanyakan masa akan menerima tugasan Leader/Supervisor dengan baik tetapi kadangkala tidak.</em></p>', NULL, NULL, '2024-11-23 12:02:53', '2024-11-23 12:02:53', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1813, 545, 3, '<p>Mengambil berat dan menuruti arahan pegawai atasan dan tidak pernah membuat hal sesuka hati.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati dan akan bertanya jika tidak faham.</em></p>', NULL, NULL, '2024-11-23 12:03:02', '2024-11-23 12:03:02', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1814, 545, 4, '<p>Mengambil berat dan menuruti arahan pegawai atasan dan tidak pernah membuat hal sesuka hati. Kadangkala turut memberikan pendapat yang bermanfaat dalan kerja yang diberi.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati dan akan bertanya jika tidak faham. Kadangkala turut memberi cadangan/pandangan dalam kerja yang diberi.</em></p>', NULL, NULL, '2024-11-23 12:03:12', '2024-11-23 12:03:12', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1815, 545, 5, '<p>Bersikap positif dan menuruti semua arahan pegawai atasan, tidak membuat hal malah dapat menyampaikan objektif dan kehendak arahan secara positif kepada semua rakan sekerja.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati. Turut menyampaikan maksud dan kehendak mengikuti arahan Leader/Supervisor secara positif kepada rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-23 12:03:23', '2024-11-23 12:03:23', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1816, 546, 1, '<p>Ego dan tidak sudi berbincang tugasan sesama rakan sekerja dan pegawai atasan, sangat keras kepala dan tidak dapat menerima cadangan orang lain.<br /><br /><em>Contoh: Buat kerja tanpa ikut pelan kerja seperti menebuk drill pada kelajuan yang tinggi dan telah membesarkan lubang 3mm kepada 3.20 mm. Dia tidak dapat menerima apabila diminta buat semula pada kelajuan drill yang rendah.</em></p>', NULL, NULL, '2024-11-23 12:04:17', '2024-11-23 12:04:17', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1817, 546, 2, '<p>Jarang berbincang tugasan sesama rakan sekerja dan pegawai atasan dan tidak begitu rela berkongsi maklumat, kadangkala keras kepala dan tidak dapat menerima cadangan orang lain.<br /><br /><em>Contoh: Dia menunjukkan sikap yang tidak begitu gembira apabila diminta buat semula pada kelajuan drill yang rendah.</em></p>', NULL, NULL, '2024-11-23 12:04:27', '2024-11-23 12:04:27', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1818, 546, 3, '<p>Sudi berbincang dan menerima cadangan rakan sekerja dan pegawai atasan, dapat memberi pertolongan apabila diminta.<br /><br /><em>Contoh: Dia sudi membuat semula pada kelajuan drill yang rendah setelah berbincang dan diminta berubah.</em></p>', NULL, NULL, '2024-11-23 12:04:44', '2024-11-23 12:04:44', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1819, 546, 4, '<p>Sudi berbincang dan berinisiatif memberi pertolongan sesama rakan sekerja dan pegawai atasan dengan tidak berkira kerja. Boleh menerima cadangan orang lain dan tidak berkeras kepala.<br /><br /><em>Contoh: Dia sudi membuat semula pada kelajuan drill yang rendah dan dia turut memberi cadangan untuk mengatasi masalah tersebut.</em></p>', NULL, NULL, '2024-11-23 12:04:53', '2024-11-23 12:04:53', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1820, 546, 5, '<p>Sudi berbincang dan berinisiatif memberi pertolongan sesama rakan sekerja dan pegawai atasan dengan tidak berkira kerja. Boleh menerima cadangan orang lain dan tidak berkeras kepala. Selain itu, turut boleh memanggil rakan sekerja untuk sama-sama menyiapkan kerja tersebut.<br /><br /><em>Contoh: Dia ialah orang yang sangat agresif dan sudi membuat semula dan dia turut boleh meminta rakan sekerja untuk sama-sama menyiapkan kerja.</em></p>', NULL, NULL, '2024-11-23 12:05:05', '2024-11-23 12:05:05', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1821, 547, 1, '<p>Menolak tugasan selain dari bidang sendiri dan langsung tidak dapat menerima tugasan tambahan atau di luar bidang kerja, amat mementingkan diri sendiri.<br /><br /><em>Contoh: Tidak mahu backup rakan sekerja yang bercuti dan selalu dipengaruhi oleh rakan sekerja yang lain dimana orang yang berbuat banyak tidak dapat apa-apa.</em></p>', NULL, NULL, '2024-11-23 12:05:33', '2024-11-23 12:05:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1822, 547, 2, '<p>Kadangkala menerima tugasan tambahan atau di luar bidang kerja tetapi dengan hati yang tidak rela dan mementingkan kepentingan diri sendiri.<br /><br /><em>Contoh: Kadangkala akan diminta untuk backup rakan sekerja yang bercuti tetapi dia akan membuat kerja secara tidak rela / memberi alasan bahawa dia tidak tahu buat kerja tersebut.</em></p>', NULL, NULL, '2024-11-23 12:05:46', '2024-11-23 12:05:46', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1823, 547, 3, '<p>Rela menerima tugasan tambahan atau di luar bidang dan tidak menolak apabila tugas diberi.<br /><br /><em>Contoh: Rela backup rakan sekerja yang bercuti dan tidak menolak apabila tugas diberi oleh Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-23 12:05:56', '2024-11-23 12:05:56', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1824, 547, 4, '<p>Rela menerima tugasan tambahan atau di luar bidang dan tidak menolak apabila tugas diberi serta cuba mencari cara untuk menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Rela backup rakan sekerja yang bercuti dan tidak menolak apabila tugas diberi oleh Leader / Supervisor. Selain itu, dia juga cari jalan untuk mengeluarkan hasil kerja yang baik / membuat kerja tersebut dengan bersungguh-sungguh.</em></p>', NULL, NULL, '2024-11-23 12:06:06', '2024-11-23 12:06:06', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1825, 547, 5, '<p>Amat rela menerima tugasan tambahan atau di luar bidang dan menerimanya sebagai satu cabaran. Berusaha dan bertanggungjawab sepenuhnya sehingga tugasan selesai dengan sempurna.<br /><br /><em>Contoh: Sangat rela backup rakan sekerja yang bercuti dan menganggap tugas yang diberi tersebut sebagai satu cabaran / tugas sendiri. Dia membuat kerja dengan sepenuh hati dan mengambil tanggungjawab sehingga tugasan tersebut selesai dengan sempurnanya.</em></p>', NULL, NULL, '2024-11-23 12:06:31', '2024-11-23 12:06:31', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1826, 560, 1, '<p>Tidak dapat menyiapkan tugasan mengikut masa yang ditetapkan dan selalu dibuat semula oleh rakan sekerja yang lain dan menyebabkan kelewatan.<br /><br /><em>Contoh: Kerja yang sepatutnya boleh disiapkan dalam sehari tetapi dia selalu tidak hadir bekerja dan kerjanya perlu disambung / dibuat semula oleh rakan sekerja yang lain dan menyebabkan kelewatan.</em></p>', NULL, NULL, '2024-11-23 12:14:50', '2024-11-23 12:14:50', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1827, 560, 2, '<p>Selalu mengambil masa yang panjang untuk menyiapkan kerja walaupun bimbingan sudah diberi.<br /><br /><em>Contoh: Kerja yang sepatutnya boleh disiapkan dalam sehari tetapi dia mengambil masa yang panjang walaupun bimbingan sudah diberi.</em></p>', NULL, NULL, '2024-11-23 12:14:59', '2024-11-23 12:14:59', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1828, 560, 3, '<p>Tugasan biasanya dapat disiapkan dengan sedikit bimbingan dan siap dalam masa yang ditetapkan mahupun lebih awal dan hasil kerja yang masih boleh diterima.<br /><br /><em>Contoh: Boleh menghasilkan kerja dalam masa yang ditetapkan tetapi masih perlu dalam pengawasan/bimbingan.</em></p>', NULL, NULL, '2024-11-23 12:15:08', '2024-11-23 12:15:08', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1829, 560, 4, '<p>Tugasan sentiasa disiapkan tanpa bimbingan dan mengikut jadual mahupun lebih awal dan hasil kerja yang agar memuaskan.<br /><br /><em>Contoh: Boleh menghasilkan kerja dalam masa yang pendek dan tanpa sebarang pengawasan/bimbingan seperti dia cuma perlu 5 jam untuk menghasilkan kerja yang dijangka siap dalam sehari dan dia boleh menghasilkan lebih dalam satu hari.</em></p>', NULL, NULL, '2024-11-23 12:15:21', '2024-11-23 12:15:21', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1830, 560, 5, '<p>Mengutamakan masa dan pantas dalam menyiapkan tugasan yang diberi dan hasil kerja sangat bagus dan boleh diharapkan.<br /><br /><em>Contoh:Boleh membuat apa kerja yang dirancang dan menepati masa yang ditetapkan atau lebih awal tanpa pengawasan/bimbingan. Individu yang teliti dan prihatin dan menguasa masa dan memberi hasil kerja yang sangat bagus dan halus.</em></p>', NULL, NULL, '2024-11-23 12:15:31', '2024-11-23 12:15:31', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1831, 561, 1, '<p>Suka menolak tanggungjawab kerja dan berpura-pura/berdiam diri walaupun tahu apa cara untuk membuat kerja/menyelesaikan masalah.<br /><br /><em>Contoh: Langsung tidak bergerak dan pakai duduk dan tunggu sahaja walaupun sudah diberi penjelasan dalam pelan kerja.</em></p>', NULL, NULL, '2024-11-23 12:16:12', '2024-11-23 12:16:12', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1832, 561, 2, '<p>Kadangkala menolak tanggungjawab kerja dan berpura-pura/berdiam diri walaupun tahu apa cara untuk membuat kerja/menyelesaikan masalah.<br /><br /><em>Contoh: Tidak berusaha untuk belajar dan memahami pembacaan pelan kerja dan ukuran serta memerlukan seseorang mengawasi di tepi dan selalu memberi penjelasan boleh baru dapat menghasilkan kerja yang ditugaskan.</em></p>', NULL, NULL, '2024-11-23 12:16:20', '2024-11-23 12:16:20', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1833, 561, 3, '<p>Sudah faham dan boleh terus bertindak/bergerak ke atas kerja yang telah diselesaikan.&nbsp;<br /><br /><em>Contoh: Sudah tahu membuat kerja/menyelesaikan masalah dan tidak menolak tanggungjawab.</em></p>', NULL, NULL, '2024-11-23 12:16:31', '2024-11-23 12:16:31', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1834, 561, 4, '<p>Sudah faham dan boleh bertindak cepat ke atas semua tugasan serta tidak perlu pengawasan/bimbingan dan akan lapor balik apabila kerja telah siap.<br /><br /><em>Contoh: Bertanggungjawab dan tidak berpura-pura atau berdiam diri dalam membuat kerja/menyelesaikan masalah dan tidak perlu pengawasan/bimbingan dan akan bertindak/bergerak ke atas kerja yang ditugaskan serta lapor balik apabila kerja telah siap.</em></p>', NULL, NULL, '2024-11-23 12:16:42', '2024-11-23 12:16:42', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1835, 561, 5, '<p>Sudah faham dan boleh bertindak cepat ke atas semua tugasan serta tidak perlu pengawasan/bimbingan dan akan lapor balik apabila kerja telah siap. Selain itu, dapat memberi nasihat kepada rakan sekerja yang lain supaya cepat bertindak dalam kerja.<br /><br /><em>Contoh: Bertanggungjawab dan tidak berpura-pura atau berdiam diri dalam membuat kerja/menyelesaikan masalah dan tidak perlu pengawasan/bimbingan dan akan bertindak/bergerak ke atas kerja yang ditugaskan serta lapor balik apabila kerja telah siap. Selain itu, juga memotivasikan rakan sekerja supaya tidak berpura-pura/berdiam diri dalam &nbsp;membuat kerja/menyelesaikan masalah.</em></p>', NULL, NULL, '2024-11-23 12:16:52', '2024-11-23 12:16:52', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1836, 562, 1, '<p>Tidak membuat kerja secara sistematik dan tidak tahu membezakan kepentingan kerja.<br /><br /><em>Contoh: Tidak tahu membezakan kepentingan kerja dan tidak buat perancangan kerja.</em></p>', NULL, NULL, '2024-11-23 12:17:35', '2024-11-23 12:17:35', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1837, 562, 2, '<p>Kadangkala ada membuat kerja secara sistematik dan kadangkala tahu membezakan kepentingan kerja tetapi keadaan tidak ketara.<br /><br /><em>Contoh: Kadangkala tahu membezakan kepentingan kerja dan buat perancangan kerja tetapi tidak selalu dan ikut mood sendiri.</em></p>', NULL, NULL, '2024-11-23 12:18:08', '2024-11-23 12:18:08', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1838, 562, 3, '<p>Tidak perlu seseorang mengawasi di tepi dan tahu membuat kerja secara sistematik dan tahu membezakan kepentingan kerja dengan penjelasan yang ringkas sahaja.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan memerlukan penjelasan kerja yang ringkas sahaja.</em></p>', NULL, NULL, '2024-11-23 12:18:18', '2024-11-23 12:18:18', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1839, 562, 4, '<p>Hanya memerlukan penjelasan yang ringkas dan tahu membuat kerja secara sistematik dan tahu membezakan kepentingan kerja. Berhati-hati dan tiada kesilapan dalam kerja yang dihasilkan.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan hanya memerlukan penjelasan kerja yang ringkas sahaja dan memberi tumpuan dalam kerja dan mengeluarkan hasil kerja yang baik.</em></p>', NULL, NULL, '2024-11-23 12:18:28', '2024-11-23 12:18:28', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1840, 562, 5, '<p>Hanya memerlukan penjelasan yang sangat ringkas sahaja untuk membuat kerja secara sistematik dan tahu membezakan kepentingan kerja dan dapat memberi tunjuk ajar kepada rakan sekerja.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan hanya memerlukan penjelasan kerja yang ringkas sahaja dan memberi tumpuan dalam kerja dan mengeluarkan hasil kerja yang baik dan turut memberi tunjuk ajar kepada rakan sekerja.</em></p>', NULL, NULL, '2024-11-23 12:18:40', '2024-11-23 12:18:40', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1841, 563, 1, '<p>Hasil kerja yang tidak boleh diterima dan selalu membuat kesilapan.<br /><br /><em>Contoh: Tidak menumpu perhatian semasa bekerja dan selalu membuat kesilapan yang sama. Tidak pernah berubah walaupun &nbsp;sudah diberi bimbingan/teguran seperti selalu mengulangi kesilapan yang sama walaupun sudah banyak kali memasang mesin yang sama model.</em></p>', NULL, NULL, '2024-11-23 12:22:10', '2024-11-23 12:22:10', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1842, 563, 2, '<p>Cuai dan mengakibatkan kesilapan kerja.<br /><br /><em>Contoh: Kadangkala cuai semasa bekerja dan mengakibatkan kesilapan kerja kerana tindakan yang lambat untuk berubah setelah diberi bimbingan/teguran.</em></p>', NULL, NULL, '2024-11-23 12:22:23', '2024-11-23 12:22:23', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1843, 563, 3, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan meminimumkan tahap kesilapan kepada yang terendah.<br /><br /><em>Contoh: Kadangkala ada membuat kesilapan tetapi mengambil tindakan yang cepat untuk berubah setelah diberi bimbingan/teguran.</em></p>', NULL, NULL, '2024-11-23 12:22:34', '2024-11-23 12:22:34', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1844, 563, 4, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan apa-apa kesilapan dalam kerja harian.<br /><br /><em>Contoh: Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan. Selain itu, juga berinisiatif untuk menjaga barangan/bahan dan tidak membazir.</em></p>', NULL, NULL, '2024-11-23 12:22:45', '2024-11-23 12:22:45', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1845, 563, 5, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan kerja dan berinisiatif untuk memberi pendapat dan memperbaiki cara kerja yang lebih baik untuk meminimumkan tahap kesilapan kerja.<br /><br /><em>Contoh: Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan dan berinisiatif untuk memberi pendapat dan memperbaiki cara kerja untuk meminimumkan tahap kesilapan kerja seperti berinisiatif untuk mengetahui masalah semasa pemasangan mesin dan turut memberi pendapat untuk memperbaiki cara kerja/menyelesaikan masalah.</em></p>', NULL, NULL, '2024-11-23 12:22:56', '2024-11-23 12:22:56', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1846, 564, 1, '<p>Langsung tidak memahami permintaan kualiti kerja dan tidak memberi perhatian kepada kerja yang dilakukan.<br /><br /><em>Contoh: Langsung tidak memahami permintaan kualiti kerja dan tidak memberi perhatian terhadap semua kerja yang dilakukan seperti membuat pemasangan Control Panel tetapi langsung tidak mengikut diagram yang diberi.</em></p>', NULL, NULL, '2024-11-23 12:23:32', '2024-11-23 12:23:32', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1847, 564, 2, '<p>Kadangkala tidak faham spesifikasi kerja yang diberi dan tidak berinisiatif mengambil langkah untuk mengetahui untuk menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Tidak berinisiatif untuk bertanya/kurang bertanya apabila tidak tahu semasa memasang Control Panel dan pasang ikut sendiri dan tidak ikut cara kerja yang betul.</em></p>', NULL, NULL, '2024-11-23 12:23:45', '2024-11-23 12:23:45', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1848, 564, 3, '<p>Memahami permintaan kualiti kerja dan dapat menghasilkan kerja yang berkualiti secara individu tanpa pengawasan pegawai atasan tetapi tidak mengambil perhatian dan abaikan kerja yang remeh temeh serta tidak mengambil perhatian terhadap kekemasan hasil kerja.<br /><br /><em>Contoh: Tahu pasang Control Panel tetapi tidak terfikir tentang kekemasan. Wayar sudah ditarik dengan betul tetapi tidak diikat dengan cable tie/tidak tersusun/tidak label semasa membuat pemasangan.</em></p>', NULL, NULL, '2024-11-23 12:23:56', '2024-11-23 12:23:56', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1849, 564, 4, '<p>Faham tentang kualiti dan dapat menghasilkan kerja yang berkualiti dan memenuhi kehendak syarikat dan dapat memastikan kerja yang dihasilkan tidak bermasalah.<br /><br /><em>Contoh: Faham tentang kualiti kerja dan ikut semua spesifikasi yang diminta. Boleh berfikir dan nampak (meramalkan) ke hadapan dan memastikan kerja yang dihasilkan tidak bermasalah seperti tahu pasang Control Panel dan semua litar boleh berfungsi dengan baik dan pemasangan yang kemas dan melaporkan keadaan kepada Leader/Supervisor apabila litar tidak berfungsi/bernyala.</em></p>', NULL, NULL, '2024-11-23 12:24:07', '2024-11-23 12:24:07', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1850, 564, 5, '<p>Sangat faham tentang kualiti kerja dan dapat menghasilkan kerja yang berkualiti dan memenuhi kehendak syarikat dan dapat memastikan kerja yang dihasilkan tidak bermasalah serta turut memberi tunjuk ajar kepada rakan kerja yang lain.&nbsp;<br /><br /><em>Contoh: Sangat faham tentang kualiti kerja dan ikut semua spesifikasi yang diminta. Boleh berfikir dan nampak (meramalkan) ke hadapan dan memastikan kerja yang dihasilkan tidak bermasalah. Selain itu, juga dapat memberi tunjuk ajar kepada rakan sekerja yang lain seperti tahu pasang Control Panel dan semua litar boleh berfungsi dengan baik dan pemasangan yang kemas dan melaporkan keadaan kepada Leader/Supervisor apabila litar tidak berfungsi/bernyala. Selain itu, dia juga memberi tunjuk ajar kepada rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-23 12:24:26', '2024-11-23 12:24:26', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1851, 565, 1, '<p>Sentiasa membazirkan/merosakkan sumber syarikat.<br /><br /><em>Contoh: Tidak pernah berhati-hati dalam spesifikasi kerja yang diberi dan sentiasa mengakibatkan pembaziran bahan.</em></p>', NULL, NULL, '2024-11-23 12:24:49', '2024-11-23 12:24:49', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1852, 565, 2, '<p>Ada bersikap mahu menjimatkan sumber syarikat tetapi kadangkala menyebabkan pembaziran di atas kecuaiannya.<br /><br /><em>Contoh: Cuai dalam pembacaan spesifikasi kerja yang diberi dan silap ambil bahan dan menyebabkan kesilapan dan membazirkan bahan serta perlu &ldquo;rework&rdquo;.</em></p>', NULL, NULL, '2024-11-23 12:25:12', '2024-11-23 12:25:12', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1853, 565, 3, '<p>Berhati-hati semasa bekerja dan menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dan memastikan betul supaya tidak berlaku kesilapan yang mengakibatkan pembaziran bahan dan buang masa.</em></p>', NULL, NULL, '2024-11-23 12:25:22', '2024-11-23 12:25:22', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1854, 565, 4, '<p>Berhati-hati semasa bekerja dan berinisiatif menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya. Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dengan pelan kerja dan memastikan semua barang yang ambil adalah betul. Ada pemikiran tidak membazir seperti dalam menghasilkan sesuatu barang yang sangat kecil, dia akan cari scrap dahulu dan tidak guna bahan yang baru atau bahan yang besar.Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan.</em></p>', NULL, NULL, '2024-11-23 12:25:33', '2024-11-23 12:25:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1855, 565, 5, '<p>Berhati-hati semasa bekerja dan berinisiatif menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya. Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan dan juga menyedarkan dan membetulkan kesilapan rakan sekerja yang lain.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dengan pelan kerja dan memastikan semua barang yang ambil adalah betul. Ada pemikiran tidak membazir seperti dalam menghasilkan sesuatu barang yang sangat kecil, dia akan cari scrap dahulu dan tidak guna bahan yang baru atau bahan yang besar.Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan dan menyedarkan dan membetulkan kesilapan rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-23 12:25:43', '2024-11-23 12:25:43', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1856, 566, 1, '<p>Pengetahuan atau kemahiran adalah terhad dan tidak dapat menyelesaikan tugasan dan menggunakan masa yang panjang untuk mempelajari pengetahuan dan cara kerja yang agak senang.<br /><br /><em>Contoh: Tidak ada pengetahuan dan kemahiran kerja dan menggunakan masa yang panjang untuk mempelajari cara kerja yang senang walaupun bimbingan telah diberi seperti membuat kerja kimpalan yang paling senang iaitu mengimpal besi dalam kedudukan rata.</em></p>', NULL, NULL, '2024-11-23 12:26:12', '2024-11-23 12:26:12', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1857, 566, 2, '<p>Kurang pengetahuan atau kemahiran yang cukup untuk mengendalikan tugasan.<br /><br /><em>Contoh: Hasil kimpalan yang teruk dan bimbingan masih diperlukan walaupun diminta menghasilkan kerja kimpalan yang agak senang seperti mengimpal besi dalam kedudukan rata dan mendatar.</em></p>', NULL, NULL, '2024-11-23 12:26:21', '2024-11-23 12:26:21', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1858, 566, 3, '<p>Mempunyai pengetahuan dan kemahiran untuk mengendalikan tugasan dan mempunyai sikap mahu belajar dan mempelajari pengetahuan kerja yang baru dalam masa yang singkat dan mengimplikasikan dalam kerja harian.<br /><br /><em>Contoh: Ada pengetahuan dan kemahiran kimpalan tetapi tidak dapat meneruskan kerja apabila menghadapi kerja yang tidak biasa dan memerlukan bimbingan seperti: boleh mengimpal besi yang nipis tetapi tidak apabila diminta mengimpal besi yang lagi nipis / boleh mengimpal dalam kedudukan rata, mendatar dan menegak tetapi tidak apabila dalam keadaan overhead atau dalam keadaan 45 darjah.</em></p>', NULL, NULL, '2024-11-23 12:26:30', '2024-11-23 12:26:30', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1859, 566, 4, '<p>Boleh menguasai pengetahuan dan kemahiran untuk mengendalikan tugasan dan pencapaian yang agak memuaskan dan dapat menggunakan pengetahuannya untuk meningkatkan kualiti kerja.<br /><br /><em>Contoh: Mempunyai pengetahuan dan kemahiran yang luas serta jelas dengan semua keperluan/permintaan kerja seperti memilih kaedah yang bersesuaian untuk menghasilkan kerja dan tahu mengawal had api untuk mencegah hasil kerja dari kerosakan.</em></p>', NULL, NULL, '2024-11-23 12:26:40', '2024-11-23 12:26:40', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1860, 566, 5, '<p>Menguasai pengetahuan dan kemahiran untuk mengendalikan tugasan dan boleh menggabungkan pengetahuan untuk meningkatkan kualiti kerja serta mencari cara kerja baru untuk menyelesaikan masalah kerja dengan pengetahuannya.<br /><br /><em>Contoh: Mempunyai pengetahuan dan kemahiran yang luas serta jelas dengan semua keperluan/permintaan kerja dan berinisiatif memberi cadangan untuk menyelesaikan masalah kerja.&nbsp;</em></p>', NULL, NULL, '2024-11-23 12:26:51', '2024-11-23 12:26:51', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1861, 567, 1, '<p>Tidak pernah mengemas dan membersihkan tempat kerja sendiri dan sentiasa mengotorkan tempat kerja sendiri dan rakan sekerja yang lain.<br /><br /><em>Contoh: Tidak pernah terfikir kebaikan bersama dan terus membuang sisa kerja ke lantai dan menganggap ini kerja cleaner untuk membersihkan.</em></p>', NULL, NULL, '2024-11-23 12:27:50', '2024-11-23 12:27:50', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1862, 567, 2, '<p>Kadangkala ada mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya tidak kemas.<br /><br /><em>Contoh: Tidak selalu mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya tidak kemas seperti kadangkala ada membersihkan tempat kerja dan kadangkala tidak.</em></p>', NULL, NULL, '2024-11-23 12:28:32', '2024-11-23 12:28:32', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1863, 567, 3, '<p>Berinisiatif untuk mengemas dan membersihkan tempat kerja dan kebanyakan masa tempat kerjanya adalah kemas dan bersih.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai.</em></p>', NULL, NULL, '2024-11-23 12:28:43', '2024-11-23 12:28:43', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1864, 567, 4, '<p>Selalu mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya kemas dan selalu menolong membersihkan kawasan bahagiannya (division) dan kilang.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai serta tolong membersihkan kawasan yang lain.</em></p>', NULL, NULL, '2024-11-23 12:28:53', '2024-11-23 12:28:53', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1865, 567, 5, '<p>Selalu mengemas dan membersihkan tempat kerja dan tempat kerjanya kelihatan kemas dan bersih. Juga selalu menjaga kebersihan seluruh kawasan kilang dan dapat menegur rakan sekerja untuk menjaga kebersihan kilang.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai serta tolong menjaga kebersihan kawasan yang lain dan menegur rakan sekerja yang tidak menjaga kebersihan kilang.</em></p>', NULL, NULL, '2024-11-23 12:29:04', '2024-11-23 12:29:04', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1866, 568, 1, '<p>Tidak menjaga peralatan dan kemudahan syarikat.<br /><br /><em>Contoh: Tidak menjaga peralatan dan kemudahan syarikat seperti tidak menjaga forklift dan tidak pernah meletakkkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-23 12:30:26', '2024-11-23 12:30:26', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1867, 568, 2, '<p>Kadangkala bersikap cuai dalam mengendali peralatan dan kemudahan syarikat dan mengakibatkan kerosakan.<br /><br /><em>Contoh: Tidak selalu menjaga peralatan dan kemudahan syarikat dan mengakibatkan kerosakan seperti forklift terus jalan setelah enjin dihidupkan. Tidak mengambil berat tentang barang yang diangkat dan masuk ke ruang yang kecil. Selalu tidak meletakkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-23 12:30:35', '2024-11-23 12:30:41', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1868, 568, 3, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat dengan cara yang betul.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-23 12:30:53', '2024-11-23 12:30:53', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1869, 568, 4, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat demi kebaikan bersama. Selain itu, melaporkan kepada pihak atasan bila nampak rakan sekerja salahguna dan memberi cara penyelesaian yang bermanfaat.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna dan melapor jika ada kerosakan dan memberi cadangan untuk memperbaiki cara penggunaan dan penjagaan alatan.</em></p>', NULL, NULL, '2024-11-23 12:31:11', '2024-11-23 12:31:50', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1870, 568, 5, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat demi kebaikan bersama. Selain itu, melaporkan kepada pihak atasan bila nampak pekerja salahguna dan memberi cara penyelesaian yang bermanfaat. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna dan melapor jika ada kerosakan dan memberi cadangan untuk memperbaiki cara penggunaan dan penjagaan alatan.Selain itu, akan menyedarkan dan menasihati rakan sekerja yang tidak menjaga forklift semasa mengguna.</em></p>', NULL, NULL, '2024-11-23 12:31:25', '2024-11-23 12:31:40', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1871, 569, 1, '<p>Tidak mengutamakan keselamatan semasa bekerja.<br /><br /><em>Contoh: Tidak mengutamakan keselamatan semasa bekerja seperti tidak memakai PPE semasa bekerja.</em></p>', NULL, NULL, '2024-11-23 12:34:30', '2024-11-23 12:34:30', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1872, 569, 2, '<p>Ada sikap mengutamakan keselamatan tetapi kadangkala tidak.<br /><br /><em>Contoh: Ada memakai PPE semasa bekerja tetapi kadangkala tidak.</em></p>', NULL, NULL, '2024-11-23 12:34:38', '2024-11-23 12:34:38', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1873, 569, 3, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja.</em></p>', NULL, NULL, '2024-11-23 12:34:49', '2024-11-23 12:34:49', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1874, 569, 4, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan.</em></p>', NULL, NULL, '2024-11-23 12:35:07', '2024-11-23 12:35:07', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1875, 569, 5, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja dan melaporkan kepada pihak atasan serta turut memberi cara atau cara penyelesaian yang bermanfaat.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan serta turut memberi cara atau cara penyelesaian yang bermanfaat.</em></p>', NULL, NULL, '2024-11-23 12:35:21', '2024-11-23 12:35:21', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1876, 570, 1, '<p>Menerima tugasan tetapi tidak memikul tanggungjawab kerja dan tidak dapat bekerja di bawah tekanan.<br /><br /><em>Contoh: Dia terima kerja yang diberi tetapi sentiasa bersembang dengan rakan sekerja dan tidak buat kerja sehingga tidak nampak hasil kerja.</em></p>', NULL, NULL, '2024-11-23 12:36:10', '2024-11-23 12:36:10', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1877, 570, 2, '<p>Boleh menerima dan memikul tanggungjawab dan cuba untuk bekerja di bawah tekanan tetapi kadangkala tidak dapat menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Dia boleh buat kerja dan cuba elakkan diri dari tidak masuk kerja/tidak memberi alasan untuk bercuti tetapi kadangkala masih perlu dalam bimbingan.</em></p>', NULL, NULL, '2024-11-23 12:36:20', '2024-11-23 12:36:20', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1878, 570, 3, '<p>Boleh menerima dan memikul tanggungjawab dan dapat menghabiskan setiap kerja yang diamanahkan dengan baik di bawah tekanan dan melaporkan kerja yang telah dilakukan kepada pegawai atasan.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia masih menepati target dan ikut piawai kerja yang ditetapkan oleh syarikat. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia juga akan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-23 12:36:30', '2024-11-23 12:36:30', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1879, 570, 4, '<p>Rela menerima dan memikul tanggungjawab dan sentiasa dapat menghasilkan kerja yang berkualiti di bawah tekanan dan dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang dilakukan kepada pegawai atasan.Boleh buat kerja lebih masa sehingga kerja siap.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia akan menawarkan diri secara sukarela untuk kerja tersebut serta menepati target dan ikut piawai kerja yang ditetapkan oleh syarikat. Boleh buat kerja lebih masa sehingga kerja siap. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-23 12:36:42', '2024-11-23 12:36:42', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1880, 570, 5, '<p>Rela menerima dan memikul tanggungjawab serta tahu kepentingan dan deadline kerja. Dapat memanggil rakan sekerja untuk menyiapkan kerja bersama. Sentiasa dapat menghasilkan kerja yang berkualiti di bawah tekanan dan dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang dilakukan kepada pegawai atasan.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia tahu kepentingan dan deadline kerja tersebut serta dapat memanggil rakan sekerja untuk menyiapkan kerja bersama. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-23 12:36:59', '2024-11-23 12:36:59', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1881, 571, 1, '<p>Tidak rela mengaku kesilapan dan suka menolak tanggungjawab kepada orang lain.<br /><br /><em>Contoh: Telah melakukan kesilapan seperti tidak mengikuti spesifikasi kerja yang diberi oleh Leader / tidak tanya Leader apabila tidak faham / tanya rakan sekerja yang tidak dipertanggungjawabkan dan tidak pernah mengakui kesilapan apabila ditegur oleh Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-23 12:37:28', '2024-11-23 12:37:28', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1882, 571, 2, '<p>Kadangkala tidak rela mengaku kesilapan dan suka membuat perbandingan diri dengan orang lain dalam kesilapan yang telah dibuat.<br /><br /><em>Contoh: Telah melakukan kesilapan seperti tidak mengikuti spesifikasi kerja yang diberi oleh Leader / tidak tanya Leader apabila tidak faham / tanya rakan sekerja yang tidak dipertanggungjawabkan dan kadangkala tidak mengakui kesilapan apabila ditegur oleh Leader/Supervisor malah menyatakan Leader/Supervisor ada prasangka terhadap dia.</em></p>', NULL, NULL, '2024-11-23 12:37:37', '2024-11-23 12:37:37', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1883, 571, 3, '<p>Mengaku kesilapan dan tidak menolak tanggungjawab kepada orang lain.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan. Dia terima dan mengakui kesilapan.</em></p>', NULL, NULL, '2024-11-23 12:37:48', '2024-11-23 12:37:48', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1884, 571, 4, '<p>Tidak melarikan diri dari tanggungjawab dan terus berjumpa dengan pihak atasan untuk mengakui kesilapan dan berinisiatif untuk memperbaiki kesilapan yang telah dilakukan.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan. Dia tidak melarikan diri dari tanggungjawab dan terus berjumpa dengan Leader/Supervisor dan mengakui kesilapan. Selain itu, dia juga memberi cadangan dan sama-sama memperbaiki kesilapan yang telah dilakukan.</em></p>', NULL, NULL, '2024-11-23 12:37:59', '2024-11-23 12:37:59', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1885, 571, 5, '<p>Berani mengaku kesilapan dan tidak menolak tanggungjawab dan memastikan kesilapan tidak berlaku lagi. Berinisiatif untuk memperbetulkan kesilapan dan dapat memberi cadangan yang bermanfaat untuk mengelakkan kesilapan berlaku lagi.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan yang agak besar. Dia berani mengakui kesilapan dan terus berjumpa dengan Leader/Supervisor untuk mengakui kesilapan. Dia mengambil pengalaman tersebut sebagai satu pengajaran dan tidak mengulangi kesilapan tersebut lagi. Selain itu, dia &nbsp;memberi cadangan dan sama-sama memperbaiki kesilapan yang telah dilakukan serta memberi cadangan yang bermanfaat untuk mengelakkan kesilapan berlaku lagi.</em></p>', NULL, NULL, '2024-11-23 12:38:13', '2024-11-23 12:38:13', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1886, 572, 1, '<p>Membuat kerja alah kadar dan setakat membuat kerja sahaja dan tidak menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Tidak menunjukkan sikap ingin belajar dan tidak menumpukan perhatian semasa bekerja seperti dia boleh mengambil masa yang panjang untuk memasang beberapa nut pada mesin.</em></p>', NULL, NULL, '2024-11-23 12:38:46', '2024-11-23 12:38:46', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1887, 572, 2, '<p>Boleh membuat kerja tetapi mudah dipengaruhi orang lain dan kadangkala tidak dapat menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Dia boleh pasang nut pada mesin tetapi mudah dipengaruhi oleh rakan sekerja yang lain seperti dia akan melambatkan proses kerjanya dan sambil kerja sambil bersembang apabila ada rakan sekerja yang bersembang dengannya semasa bekerja.</em></p>', NULL, NULL, '2024-11-23 12:38:59', '2024-11-23 12:38:59', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1888, 572, 3, '<p>Lebih agresif dan sikap kerja juga serius dan dapat menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak mengangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja.</em></p>', NULL, NULL, '2024-11-23 12:39:10', '2024-11-23 12:39:10', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1889, 572, 4, '<p>Bersemangat kerja dan menumpukan perhatian sepenuhnya dalam kerja. Sentiasa mengutamakan kualiti kerja dan menghasilkan kerja yang halus dan teliti dan tidak melakukan kesilapan.<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak menggangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja. Dia sentiasa mengutamakan kualiti kerja dan memastikan nut yang dipasang itu betul dan kemas.</em></p>', NULL, NULL, '2024-11-23 12:39:25', '2024-11-23 12:39:25', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1890, 572, 5, '<p>Matlamat untuk berjaya sangat jelas. Menumpukan perhatian sepenuhnya dalam kerja. Sentiasa mengutamakan kualiti kerja dan menghasilkan kerja yang halus dan teliti dan tidak melakukan kesilapan. Selain itu turut memberi cadangan dan cara kerja untuk memastikan kerja berkualiti dihasilkan setiap kali.&nbsp;<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak menggangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja. Dia sentiasa mengutamakan kualiti kerja dan memastikan nut yang dipasang itu betul dan kemas. Selain itu, dia juga akan memberi cadangan untuk memastikan kerja berkualiti dapat dihasilkan.</em></p>', NULL, NULL, '2024-11-23 12:39:41', '2024-11-23 12:39:41', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1891, 573, 1, '<p>Langsung tidak mahu memahami dan menerima peraturan dan polisi syarikat dan sentiasa membuat aduan terhadap dasar syarikat.<br /><br /><em>Contoh: Selalu tidak menutup lampu setelah mengguna tandas dan membuat aduan apabila pihak syarikat mengambil tindakan.</em></p>', NULL, NULL, '2024-11-23 12:40:33', '2024-11-23 12:40:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1892, 573, 2, '<p>Kadangkala sahaja mahu menerima dan mematuhi peraturan dan polisi syarikat.<br /><br /><em>Contoh: Kadangkala ada menutup lampu setelah mengguna tandas kadangkala tidak.</em></p>', NULL, NULL, '2024-11-23 12:40:46', '2024-11-23 12:40:46', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1893, 573, 3, '<p>Menerima dan mematuhi setiap peraturan dan polisi syarikat.<br /><br /><em>Contoh: Setiap kali akan menutup lampu setelah mengguna tandas.</em></p>', NULL, NULL, '2024-11-23 12:40:55', '2024-11-23 12:40:55', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1894, 573, 4, '<p>Tidak melanggar peraturan dan sentiasa dapat menasihatkan rakan sekerja untuk menerima dan mematuhi peraturan dan polisi syarikat untuk kebaikan bersama.<br /><br /><em>Contoh: Sentiasa menutup lampu setelah mengguna tandas dan &nbsp;menasihati dan menerang kepada rakan sekerja yang tidak mematuhi peraturan.</em></p>', NULL, NULL, '2024-11-23 12:41:07', '2024-11-23 12:41:07', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1895, 573, 5, '<p>Memahami dan menerima setiap peraturan dan polisi syarikat dan sentiasa menasihatkan rakan sekerja yang melanggar peraturan serta melaporkan masalah disiplin kepada pegawai atasan untuk kebaikan bersama.<br /><br /><em>Contoh: &nbsp;Sentiasa menutup lampu setelah mengguna tandas dan &nbsp;menasihati dan menerang kepada rakan sekerja yang tidak mematuhi peraturan. Selain itu, juga akan melaporkan nama pekerja yang tidak menutup lampu setelah mengguna tandas.</em></p>', NULL, NULL, '2024-11-23 12:41:20', '2024-11-23 12:41:20', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1896, 574, 1, '<p>Selalu tidak tepat masuk kerja dan menunjukkan kedatangan yang tidak baik.<br /><br /><em>Contoh: Masih berada di tempat berehat semasa siren berbunyi dan jalan perlahan ke tempat kerja.</em></p>', NULL, NULL, '2024-11-23 14:02:09', '2024-11-23 14:02:14', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1897, 574, 2, '<p>Kadangkala ada masuk kerja pada masa yang ditetapkan tetapi keadaan tidak ketara.<br /><br /><em>Contoh: Kadangkala ada tepat masuk kerja semasa siren berbunyi tetapi kebanyakan masa tidak masuk kerja pada masa yang tepat.</em></p>', NULL, NULL, '2024-11-23 14:02:25', '2024-11-23 14:02:25', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1898, 574, 3, '<p>Kebanyakan masa masuk kerja pada masa yang ditetapkan tetapi kadangkala ada lewat juga.<br /><br /><em>Contoh: Kebanyakan masa masuk kerja semasa siren berbunyi tetapi sekali kala masih lewat masuk kerja.</em></p>', NULL, NULL, '2024-11-23 14:02:34', '2024-11-23 14:02:34', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1899, 574, 4, '<p>Mementingkan ketepatan masa masuk kerja dan masuk kerja tepat pada masa atau lebih awal.<br /><br /><em>Contoh: Sentiasa masa masuk kerja sebelum siren berbunyi atau lebih awal.</em></p>', NULL, NULL, '2024-11-23 14:02:44', '2024-11-23 14:02:44', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1900, 574, 5, '<p>Mementingkan ketepatan masa masuk kerja dan masuk kerja tepat pada masa atau lebih awal serta memberi nasihat kepada rakan sekerja yang lewat.<br /><br /><em>Contoh: Sentiasa masa masuk kerja sebelum siren berbunyi atau lebih awal serta memberi nasihat kepada rakan sekerja yang lewat.</em></p>', NULL, NULL, '2024-11-23 14:02:57', '2024-11-23 14:02:57', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1901, 575, 1, '<p>Disiplin diri yang tidak memuaskan dan sering meninggalkan tempat kerja dengan berkeliaran tanpa tujuan dan sering membazirkan masa serta curi tulang.<br /><br /><em>Contoh: Sering meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja (banyak kali sehari) dan mengambil masa yang panjang dalam tandas serta membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-23 14:03:25', '2024-11-23 14:03:25', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1902, 575, 2, '<p>Kadangkala membazirkan masa dan curi tulang serta meninggalkan tempat kerja dengan berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Kadangkala meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja (banyak kali sehari) dan mengambil masa yang panjang dalam tandas serta membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-23 14:03:36', '2024-11-23 14:03:36', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1903, 575, 3, '<p>Tidak membazirkan masa dan ringan tulang serta menumpukan perhatian semasa bekerja. Tidak meninggalkan tempat kerja dengan berkeliaran tanpa tujuan.<br /><br /><em>Contoh: Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-23 14:03:46', '2024-11-23 14:03:46', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1904, 575, 4, '<p>Teladan yang baik dan tumpuan perhatian sepenuhnya semasa bekerja. Tidak berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Seorang teladan yang baik dan memberi tumpuan sepenuhnya semasa bekerja. Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-23 14:03:57', '2024-11-23 14:03:57', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1905, 575, 5, '<p>Teladan yang baik dan tumpuan perhatian sepenuhnya semasa bekerja dan juga selalu memberi nasihat kepada rakan sekerja supaya melahirkan keadaan kerja yang lebih agresif. Tidak berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Seorang teladan yang baik dan memberi tumpuan sepenuhnya semasa bekerja. Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja. Selalu memberi nasihat kepada rakan sekerja yang selalu pergi ke tandas sebagai alasan.</em></p>', NULL, NULL, '2024-11-23 14:04:11', '2024-11-23 14:04:11', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1906, 576, 1, '<p>Tidak pernah berada di tempat kerja semasa pembersihan kawasan dijalankan.<br /><br /><em>Contoh: Tidak berada di tempat kerja dan pergi ke tandas semasa pembersihan kawasan dijalankan.</em></p>', NULL, NULL, '2024-11-23 14:04:42', '2024-11-23 14:04:42', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1907, 576, 2, '<p>Memulakan kerja pembersihan kawasan walaupun masa yang ditetapkan belum sampai lagi.<br /><br /><em>Contoh: Memulakan kerja pembersihan kawasan walaupun masa yang ditetapkan belum sampai lagi dan rakan sekerja yang lain masih bekerja lagi.</em></p>', NULL, NULL, '2024-11-23 14:04:52', '2024-11-23 14:04:52', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1908, 576, 3, '<p>Kebanyakan masa membersihkan kawasan production pada masa yang ditetapkan.</p><p>Kadangkala membersihkan kawasan production pada masa yang ditetapkan tetapi keadaan tidak ketara.</p><p><br />\nContoh: Kadangkala ada berada di production semasa pembersihan kawasan dijalankan tetapi kebanyakan masa tidak nampak orang.</p>', NULL, NULL, '2024-11-23 14:05:02', '2024-11-23 14:05:02', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1909, 576, 4, '<p>Sentiasa mengutamakan dan membersihkan kawasan production pada masa yang ditetapkan.<br /><br /><em>Contoh: Sentiasa membersihkan kawasan production pada masa yang ditetapkan.</em></p>', NULL, NULL, '2024-11-23 14:05:12', '2024-11-23 14:05:12', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1910, 576, 5, '<p>Mengutamakan dan membersihkan kawasan production pada masa yang ditetapkan serta memberi nasihat kepada rakan sekerja yang tidak berbuat demikian.<br /><br /><em>Contoh: Sentiasa membersihkan kawasan production pada masa yang ditetapkan dan memberi nasihat kepada rakan sekerja yang tidak berbuat demikian.</em></p>', NULL, NULL, '2024-11-23 14:05:22', '2024-11-23 14:05:22', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1911, 577, 1, '<p>Hanya menghormati pegawai atasan dan tidak bersopan dengan rakan sekerja.<br /><br /><em>Contoh: Hanya menghormati Leader/Supervisor atau pangkat kerja yang lebih tinggi tetapi tidak bersopan dengan rakan sekerja yang berpangkat rendah/masih baru.</em></p>', NULL, NULL, '2024-11-23 14:05:49', '2024-11-23 14:05:49', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1912, 577, 2, '<p>Biasanya akan bersopan dan menghormati orang lain tetapi kadangkala beremosi.<br /><br /><em>Contoh: Biasanya bersopan dan menghormati rakan sekerja yang lain tetapi kadangkala beremosi dan lawan cakap.</em></p>', NULL, NULL, '2024-11-23 14:06:02', '2024-11-23 14:06:02', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1913, 577, 3, '<p>Sering bersopan dan menghormati orang lain dan tidak bertindak mengikut perasaan.<br /><br /><em>Contoh: Sering bersopan dan menghormati rakan sekerja lain dan tidak bertindak mengikut perasaan.</em></p>', NULL, NULL, '2024-11-23 14:06:12', '2024-11-23 14:06:12', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1914, 577, 4, '<p>Bersopan dan menghormati orang lain pada setiap masa dan tidak bertindak mengikut perasaan dan berbahasa sopan.<br /><br /><em>Contoh: Bersopan dan setiap masa menghormati rakan sekerja yang lain dan tidak bertindak mengikut perasaan dan berbahasa sopan serta jaga perasaan rakan lain.</em></p>', NULL, NULL, '2024-11-23 14:06:23', '2024-11-23 14:06:23', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1915, 577, 5, '<p>Bersopan dan menghormati orang lain pada setiap masa dan masih bercakap dengan sopan walaupun sendiri telah dipersalahkan dalam proses penyelesaian masalah.<br /><br /><em>Contoh: Bersopan dan setiap masa menghormati rakan sekerja yang lain dan masih bercakap dengan sopan walaupun sendiri telah dipersalahkan dalam proses penyelesaian masalah.</em></p>', NULL, NULL, '2024-11-23 14:06:36', '2024-11-23 14:06:36', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1916, 578, 1, '<p>Memang mengetahui arahan yang diberi mempunyai kesilapan tetapi tidak mendapatkan kepastian kerana berpendapat itu adalah tanggungjawab pegawai atasan.<br /><br /><em>Contoh: Tidak mendapatkan kepastian daripada Leader/Supervisor tentang spesifikasi kerja yang diberi walaupun sudah tahu arahan yang diberi mempunyai kesilapan/tidak jelas dan beranggap itu adalah tanggungjawab Leader/Supervisor dan bukan dia.</em></p>', NULL, NULL, '2024-11-23 14:07:19', '2024-11-23 14:07:19', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1917, 578, 2, '<p>Jarang berinisiatif untuk mendapatkan kepastian daripada pegawai atasan walaupun arahan yang diberi tidak jelas atau silap.<br /><br /><em>Contoh: Menunjukkan sikap sudah tahu tetapi tidak ingin peduli dan tidak mendapatkan kepastian daripada Leader/Supervisor walapun arahan yang diberi ada kesilapan/kurang jelas.</em></p>', NULL, NULL, '2024-11-23 14:07:28', '2024-11-23 14:07:28', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1918, 578, 3, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap tetapi tidak pernah melapor balik kepada pegawai atasan tentang tugasan tersebut.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi ada kesilapan/tidak jelas tetapi tidak pernah melapor balik tugasan tersebut.</em></p>', NULL, NULL, '2024-11-23 14:07:37', '2024-11-23 14:07:37', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1919, 578, 4, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi tidak jelas/silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut.</em></p>', NULL, NULL, '2024-11-23 14:07:50', '2024-11-23 14:07:50', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1920, 578, 5, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut serta memberi pendapat yang bermanfaat.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi tidak jelas/silap dan selalu melapor balik kepada Leader/Supervisor dan turut mengambil bahagian untuk memberi pendapat yang bermanfaat.</em></p>', NULL, NULL, '2024-11-23 15:44:57', '2024-11-23 15:44:57', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1921, 579, 1, '<p>Degil dan berpegang teguh dengan pendapat sendiri dan tidak menuruti arahan pegawai atasan.<br /><br /><em>Contoh: Tidak menerima dan melawan percakapan Leader/Supervisor semasa diberi tugasan.</em></p>', NULL, NULL, '2024-11-23 15:45:21', '2024-11-23 15:45:21', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1922, 579, 2, '<p>Kebanyakan masa akan menuruti arahan pegawai atasan tetapi kadangkala akan beremosi dan meluahkan ketidakpuasan.<br /><br /><em>Contoh: Kebanyakan masa akan menerima tugasan Leader/Supervisor dengan baik tetapi kadangkala tidak.</em></p>', NULL, NULL, '2024-11-23 15:45:32', '2024-11-23 15:45:32', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1923, 579, 3, '<p>Mengambil berat dan menuruti arahan pegawai atasan dan tidak pernah membuat hal sesuka hati.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati dan akan bertanya jika tidak faham.</em></p>', NULL, NULL, '2024-11-23 15:45:41', '2024-11-23 15:45:41', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1924, 579, 4, '<p>Mengambil berat dan menuruti arahan pegawai atasan dan tidak pernah membuat hal sesuka hati. Kadangkala turut memberikan pendapat yang bermanfaat dalan kerja yang diberi.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati dan akan bertanya jika tidak faham. Kadangkala turut memberi cadangan/pandangan dalam kerja yang diberi.</em></p>', NULL, NULL, '2024-11-23 15:45:50', '2024-11-23 15:45:50', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1925, 579, 5, '<p>Bersikap positif dan menuruti semua arahan pegawai atasan, tidak membuat hal malah dapat menyampaikan objektif dan kehendak arahan secara positif kepada semua rakan sekerja.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati. Turut menyampaikan maksud dan kehendak mengikuti arahan Leader/Supervisor secara positif kepada rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-23 15:46:02', '2024-11-23 15:46:02', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1926, 580, 1, '<p>Ego dan tidak sudi berbincang tugasan sesama rakan sekerja dan pegawai atasan, sangat keras kepala dan tidak dapat menerima cadangan orang lain.<br /><br /><em>Contoh: Buat kerja tanpa ikut pelan kerja seperti menebuk drill pada kelajuan yang tinggi dan telah membesarkan lubang 3mm kepada 3.20 mm. Dia tidak dapat menerima apabila diminta buat semula pada kelajuan drill yang rendah.</em></p>', NULL, NULL, '2024-11-23 15:46:44', '2024-11-23 15:46:44', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1927, 580, 2, '<p>Jarang berbincang tugasan sesama rakan sekerja dan pegawai atasan dan tidak begitu rela berkongsi maklumat, kadangkala keras kepala dan tidak dapat menerima cadangan orang lain.<br /><br /><em>Contoh: Dia menunjukkan sikap yang tidak begitu gembira apabila diminta buat semula pada kelajuan drill yang rendah.</em></p>', NULL, NULL, '2024-11-23 15:46:57', '2024-11-23 15:46:57', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1928, 580, 3, '<p>Sudi berbincang dan menerima cadangan rakan sekerja dan pegawai atasan, dapat memberi pertolongan apabila diminta.<br /><br /><em>Contoh: Dia sudi membuat semula pada kelajuan drill yang rendah setelah berbincang dan diminta berubah.</em></p>', NULL, NULL, '2024-11-23 15:47:06', '2024-11-23 15:47:06', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1929, 580, 4, '<p>Sudi berbincang dan berinisiatif memberi pertolongan sesama rakan sekerja dan pegawai atasan dengan tidak berkira kerja. Boleh menerima cadangan orang lain dan tidak berkeras kepala.<br /><br /><em>Contoh: Dia sudi membuat semula pada kelajuan drill yang rendah dan dia turut memberi cadangan untuk mengatasi masalah tersebut.</em></p>', NULL, NULL, '2024-11-23 15:47:16', '2024-11-23 15:47:16', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1930, 580, 5, '<p>Sudi berbincang dan berinisiatif memberi pertolongan sesama rakan sekerja dan pegawai atasan dengan tidak berkira kerja. Boleh menerima cadangan orang lain dan tidak berkeras kepala. Selain itu, turut boleh memanggil rakan sekerja untuk sama-sama menyiapkan kerja tersebut.<br /><br /><em>Contoh: Dia ialah orang yang sangat agresif dan sudi membuat semula dan dia turut boleh meminta rakan sekerja untuk sama-sama menyiapkan kerja.</em></p>', NULL, NULL, '2024-11-23 15:47:26', '2024-11-23 15:47:26', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1931, 581, 1, '<p>Menolak tugasan selain dari bidang sendiri dan langsung tidak dapat menerima tugasan tambahan atau di luar bidang kerja, amat mementingkan diri sendiri.<br /><br /><em>Contoh: Tidak mahu backup rakan sekerja yang bercuti dan selalu dipengaruhi oleh rakan sekerja yang lain dimana orang yang berbuat banyak tidak dapat apa-apa.</em></p>', NULL, NULL, '2024-11-23 15:48:10', '2024-11-23 15:48:10', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1932, 581, 2, '<p>Kadangkala menerima tugasan tambahan atau di luar bidang kerja tetapi dengan hati yang tidak rela dan mementingkan kepentingan diri sendiri.<br /><br /><em>Contoh: Kadangkala akan diminta untuk backup rakan sekerja yang bercuti tetapi dia akan membuat kerja secara tidak rela / memberi alasan bahawa dia tidak tahu buat kerja tersebut.</em></p>', NULL, NULL, '2024-11-23 15:48:19', '2024-11-23 15:48:19', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1933, 581, 3, '<p>Rela menerima tugasan tambahan atau di luar bidang dan tidak menolak apabila tugas diberi.<br /><br /><em>Contoh: Rela backup rakan sekerja yang bercuti dan tidak menolak apabila tugas diberi oleh Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-23 15:48:30', '2024-11-23 15:48:30', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1934, 581, 4, '<p>Rela menerima tugasan tambahan atau di luar bidang dan tidak menolak apabila tugas diberi serta cuba mencari cara untuk menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Rela backup rakan sekerja yang bercuti dan tidak menolak apabila tugas diberi oleh Leader / Supervisor. Selain itu, dia juga cari jalan untuk mengeluarkan hasil kerja yang baik / membuat kerja tersebut dengan bersungguh-sungguh.</em></p>', NULL, NULL, '2024-11-23 15:48:41', '2024-11-23 15:48:41', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1935, 581, 5, '<p>Amat rela menerima tugasan tambahan atau di luar bidang dan menerimanya sebagai satu cabaran. Berusaha dan bertanggungjawab sepenuhnya sehingga tugasan selesai dengan sempurna.<br /><br /><em>Contoh: Sangat rela backup rakan sekerja yang bercuti dan menganggap tugas yang diberi tersebut sebagai satu cabaran / tugas sendiri. Dia membuat kerja dengan sepenuh hati dan mengambil tanggungjawab sehingga tugasan tersebut selesai dengan sempurnanya.</em></p>', NULL, NULL, '2024-11-23 15:48:51', '2024-11-23 15:48:51', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1936, 594, 1, '<p>Tidak dapat menyiapkan tugasan mengikut masa yang ditetapkan dan selalu dibuat semula oleh rakan sekerja yang lain dan menyebabkan kelewatan.<br /><br /><em>Contoh: Kerja yang sepatutnya boleh disiapkan dalam sehari tetapi dia selalu tidak hadir bekerja dan kerjanya perlu disambung / dibuat semula oleh rakan sekerja yang lain dan menyebabkan kelewatan.</em></p>', NULL, NULL, '2024-11-23 15:57:59', '2024-11-23 15:57:59', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1937, 594, 2, '<p>Selalu mengambil masa yang panjang untuk menyiapkan kerja walaupun bimbingan sudah diberi.<br /><br /><em>Contoh: Kerja yang sepatutnya boleh disiapkan dalam sehari tetapi dia mengambil masa yang panjang walaupun bimbingan sudah diberi.</em></p>', NULL, NULL, '2024-11-23 15:58:09', '2024-11-23 15:58:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1938, 594, 3, '<p>Tugasan biasanya dapat disiapkan dengan sedikit bimbingan dan siap dalam masa yang ditetapkan mahupun lebih awal dan hasil kerja yang masih boleh diterima.<br /><br /><em>Contoh: Boleh menghasilkan kerja dalam masa yang ditetapkan tetapi masih perlu dalam pengawasan/bimbingan.</em></p>', NULL, NULL, '2024-11-23 15:58:18', '2024-11-23 15:58:18', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1939, 594, 4, '<p>Tugasan sentiasa disiapkan tanpa bimbingan dan mengikut jadual mahupun lebih awal dan hasil kerja yang agar memuaskan.<br /><br /><em>Contoh: Boleh menghasilkan kerja dalam masa yang pendek dan tanpa sebarang pengawasan/bimbingan seperti dia cuma perlu 5 jam untuk menghasilkan kerja yang dijangka siap dalam sehari dan dia boleh menghasilkan lebih dalam satu hari.</em></p>', NULL, NULL, '2024-11-23 15:58:28', '2024-11-23 15:58:28', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1940, 594, 5, '<p>Mengutamakan masa dan pantas dalam menyiapkan tugasan yang diberi dan hasil kerja sangat bagus dan boleh diharapkan.<br /><br /><em>Contoh:Boleh membuat apa kerja yang dirancang dan menepati masa yang ditetapkan atau lebih awal tanpa pengawasan/bimbingan. Individu yang teliti dan prihatin dan menguasa masa dan memberi hasil kerja yang sangat bagus dan halus.</em></p>', NULL, NULL, '2024-11-23 15:58:38', '2024-11-23 15:58:38', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1941, 595, 1, '<p>Suka menolak tanggungjawab kerja dan berpura-pura/berdiam diri walaupun tahu apa cara untuk membuat kerja/menyelesaikan masalah.<br /><br /><em>Contoh: Langsung tidak bergerak dan pakai duduk dan tunggu sahaja walaupun sudah diberi penjelasan dalam pelan kerja.</em></p>', NULL, NULL, '2024-11-23 15:59:22', '2024-11-23 15:59:22', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1942, 595, 2, '<p>Kadangkala menolak tanggungjawab kerja dan berpura-pura/berdiam diri walaupun tahu apa cara untuk membuat kerja/menyelesaikan masalah.<br /><br /><em>Contoh: Tidak berusaha untuk belajar dan memahami pembacaan pelan kerja dan ukuran serta memerlukan seseorang mengawasi di tepi dan selalu memberi penjelasan boleh baru dapat menghasilkan kerja yang ditugaskan.</em></p>', NULL, NULL, '2024-11-23 15:59:31', '2024-11-23 15:59:31', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1943, 595, 3, '<p>Sudah faham dan boleh terus bertindak/bergerak ke atas kerja yang telah diselesaikan.&nbsp;<br /><br /><em>Contoh: Sudah tahu membuat kerja/menyelesaikan masalah dan tidak menolak tanggungjawab.</em></p>', NULL, NULL, '2024-11-23 15:59:53', '2024-11-23 16:00:06', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1944, 595, 4, '<p>Sudah faham dan boleh bertindak cepat ke atas semua tugasan serta tidak perlu pengawasan/bimbingan dan akan lapor balik apabila kerja telah siap.<br /><br /><em>Contoh: Bertanggungjawab dan tidak berpura-pura atau berdiam diri dalam membuat kerja/menyelesaikan masalah dan tidak perlu pengawasan/bimbingan dan akan bertindak/bergerak ke atas kerja yang ditugaskan serta lapor balik apabila kerja telah siap.</em></p>', NULL, NULL, '2024-11-23 16:00:16', '2024-11-23 16:00:16', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1945, 595, 5, '<p>Sudah faham dan boleh bertindak cepat ke atas semua tugasan serta tidak perlu pengawasan/bimbingan dan akan lapor balik apabila kerja telah siap. Selain itu, dapat memberi nasihat kepada rakan sekerja yang lain supaya cepat bertindak dalam kerja.<br /><br /><em>Contoh: Bertanggungjawab dan tidak berpura-pura atau berdiam diri dalam membuat kerja/menyelesaikan masalah dan tidak perlu pengawasan/bimbingan dan akan bertindak/bergerak ke atas kerja yang ditugaskan serta lapor balik apabila kerja telah siap. Selain itu, juga memotivasikan rakan sekerja supaya tidak berpura-pura/berdiam diri dalam &nbsp;membuat kerja/menyelesaikan masalah.</em></p>', NULL, NULL, '2024-11-23 16:00:26', '2024-11-23 16:00:26', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1946, 596, 1, '<p>Tidak membuat kerja secara sistematik dan tidak tahu membezakan kepentingan kerja.<br /><br /><em>Contoh: Tidak tahu membezakan kepentingan kerja dan tidak buat perancangan kerja.</em></p>', NULL, NULL, '2024-11-23 16:01:18', '2024-11-23 16:01:18', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1947, 596, 2, '<p>Kadangkala ada membuat kerja secara sistematik dan kadangkala tahu membezakan kepentingan kerja tetapi keadaan tidak ketara.<br /><br /><em>Contoh: Kadangkala tahu membezakan kepentingan kerja dan buat perancangan kerja tetapi tidak selalu dan ikut mood sendiri.</em></p>', NULL, NULL, '2024-11-23 16:01:33', '2024-11-23 16:01:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1948, 596, 3, '<p>Tidak perlu seseorang mengawasi di tepi dan tahu membuat kerja secara sistematik dan tahu membezakan kepentingan kerja dengan penjelasan yang ringkas sahaja.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan memerlukan penjelasan kerja yang ringkas sahaja.</em></p>', NULL, NULL, '2024-11-23 16:01:43', '2024-11-23 16:01:43', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1949, 596, 4, '<p>Hanya memerlukan penjelasan yang ringkas dan tahu membuat kerja secara sistematik dan tahu membezakan kepentingan kerja. Berhati-hati dan tiada kesilapan dalam kerja yang dihasilkan.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan hanya memerlukan penjelasan kerja yang ringkas sahaja dan memberi tumpuan dalam kerja dan mengeluarkan hasil kerja yang baik.</em></p>', NULL, NULL, '2024-11-23 16:01:54', '2024-11-23 16:01:54', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1950, 596, 5, '<p>Hanya memerlukan penjelasan yang sangat ringkas sahaja untuk membuat kerja secara sistematik dan tahu membezakan kepentingan kerja dan dapat memberi tunjuk ajar kepada rakan sekerja.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan hanya memerlukan penjelasan kerja yang ringkas sahaja dan memberi tumpuan dalam kerja dan mengeluarkan hasil kerja yang baik dan turut memberi tunjuk ajar kepada rakan sekerja.</em></p>', NULL, NULL, '2024-11-23 16:02:05', '2024-11-23 16:02:05', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1951, 597, 1, '<p>Hasil kerja yang tidak boleh diterima dan selalu membuat kesilapan.<br /><br /><em>Contoh: Tidak menumpu perhatian semasa bekerja dan selalu membuat kesilapan yang sama. Tidak pernah berubah walaupun &nbsp;sudah diberi bimbingan/teguran seperti selalu mengulangi kesilapan yang sama walaupun sudah banyak kali memasang mesin yang sama model.</em></p>', NULL, NULL, '2024-11-23 16:02:52', '2024-11-23 16:02:52', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1952, 597, 2, '<p>Cuai dan mengakibatkan kesilapan kerja.<br /><br /><em>Contoh: Kadangkala cuai semasa bekerja dan mengakibatkan kesilapan kerja kerana tindakan yang lambat untuk berubah setelah diberi bimbingan/teguran.</em></p>', NULL, NULL, '2024-11-23 16:03:02', '2024-11-23 16:03:02', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1953, 597, 3, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan meminimumkan tahap kesilapan kepada yang terendah.<br /><br /><em>Contoh: Kadangkala ada membuat kesilapan tetapi mengambil tindakan yang cepat untuk berubah setelah diberi bimbingan/teguran.</em></p>', NULL, NULL, '2024-11-23 16:03:12', '2024-11-23 16:03:12', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1954, 597, 4, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan apa-apa kesilapan dalam kerja harian.<br /><br /><em>Contoh: Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan. Selain itu, juga berinisiatif untuk menjaga barangan/bahan dan tidak membazir.</em></p>', NULL, NULL, '2024-11-23 16:03:24', '2024-11-23 16:03:24', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1955, 597, 5, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan kerja dan berinisiatif untuk memberi pendapat dan memperbaiki cara kerja yang lebih baik untuk meminimumkan tahap kesilapan kerja.<br /><br /><em>Contoh: Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan dan berinisiatif untuk memberi pendapat dan memperbaiki cara kerja untuk meminimumkan tahap kesilapan kerja seperti berinisiatif untuk mengetahui masalah semasa pemasangan mesin dan turut memberi pendapat untuk memperbaiki cara kerja/menyelesaikan masalah.</em></p>', NULL, NULL, '2024-11-23 16:03:35', '2024-11-23 16:03:35', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1956, 598, 1, '<p>Langsung tidak memahami permintaan kualiti kerja dan tidak memberi perhatian kepada kerja yang dilakukan.<br /><br /><em>Contoh: Langsung tidak memahami permintaan kualiti kerja dan tidak memberi perhatian terhadap semua kerja yang dilakukan seperti membuat pemasangan Control Panel tetapi langsung tidak mengikut diagram yang diberi.</em></p>', NULL, NULL, '2024-11-23 16:10:20', '2024-11-23 16:10:20', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1957, 598, 2, '<p>Kadangkala tidak faham spesifikasi kerja yang diberi dan tidak berinisiatif mengambil langkah untuk mengetahui untuk menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Tidak berinisiatif untuk bertanya/kurang bertanya apabila tidak tahu semasa memasang Control Panel dan pasang ikut sendiri dan tidak ikut cara kerja yang betul.</em></p>', NULL, NULL, '2024-11-23 16:10:29', '2024-11-23 16:10:29', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1958, 598, 3, '<p>Memahami permintaan kualiti kerja dan dapat menghasilkan kerja yang berkualiti secara individu tanpa pengawasan pegawai atasan tetapi tidak mengambil perhatian dan abaikan kerja yang remeh temeh serta tidak mengambil perhatian terhadap kekemasan hasil kerja.<br /><br /><em>Contoh: Tahu pasang Control Panel tetapi tidak terfikir tentang kekemasan. Wayar sudah ditarik dengan betul tetapi tidak diikat dengan cable tie/tidak tersusun/tidak label semasa membuat pemasangan.</em></p>', NULL, NULL, '2024-11-23 16:11:19', '2024-11-23 16:11:19', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1959, 598, 4, '<p>Faham tentang kualiti dan dapat menghasilkan kerja yang berkualiti dan memenuhi kehendak syarikat dan dapat memastikan kerja yang dihasilkan tidak bermasalah.<br /><br /><em>Contoh: Faham tentang kualiti kerja dan ikut semua spesifikasi yang diminta. Boleh berfikir dan nampak (meramalkan) ke hadapan dan memastikan kerja yang dihasilkan tidak bermasalah seperti tahu pasang Control Panel dan semua litar boleh berfungsi dengan baik dan pemasangan yang kemas dan melaporkan keadaan kepada Leader/Supervisor apabila litar tidak berfungsi/bernyala.</em></p>', NULL, NULL, '2024-11-23 16:11:30', '2024-11-23 16:11:30', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1960, 598, 5, '<p>Sangat faham tentang kualiti kerja dan dapat menghasilkan kerja yang berkualiti dan memenuhi kehendak syarikat dan dapat memastikan kerja yang dihasilkan tidak bermasalah serta turut memberi tunjuk ajar kepada rakan kerja yang lain.&nbsp;<br /><br /><em>Contoh: Sangat faham tentang kualiti kerja dan ikut semua spesifikasi yang diminta. Boleh berfikir dan nampak (meramalkan) ke hadapan dan memastikan kerja yang dihasilkan tidak bermasalah. Selain itu, juga dapat memberi tunjuk ajar kepada rakan sekerja yang lain seperti tahu pasang Control Panel dan semua litar boleh berfungsi dengan baik dan pemasangan yang kemas dan melaporkan keadaan kepada Leader/Supervisor apabila litar tidak berfungsi/bernyala. Selain itu, dia juga memberi tunjuk ajar kepada rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-23 16:11:40', '2024-11-23 16:11:40', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1961, 599, 1, '<p>Sentiasa membazirkan/merosakkan sumber syarikat.<br /><br /><em>Contoh: Tidak pernah berhati-hati dalam spesifikasi kerja yang diberi dan sentiasa mengakibatkan pembaziran bahan.</em></p>', NULL, NULL, '2024-11-23 16:12:14', '2024-11-23 16:12:14', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1962, 599, 2, '<p>Ada bersikap mahu menjimatkan sumber syarikat tetapi kadangkala menyebabkan pembaziran di atas kecuaiannya.<br /><br /><em>Contoh: Cuai dalam pembacaan spesifikasi kerja yang diberi dan silap ambil bahan dan menyebabkan kesilapan dan membazirkan bahan serta perlu &ldquo;rework&rdquo;.</em></p>', NULL, NULL, '2024-11-23 16:12:28', '2024-11-23 16:12:28', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1963, 599, 3, '<p>Berhati-hati semasa bekerja dan menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dan memastikan betul supaya tidak berlaku kesilapan yang mengakibatkan pembaziran bahan dan buang masa.</em></p>', NULL, NULL, '2024-11-23 16:12:39', '2024-11-23 16:12:39', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1964, 599, 4, '<p>Berhati-hati semasa bekerja dan berinisiatif menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya. Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dengan pelan kerja dan memastikan semua barang yang ambil adalah betul. Ada pemikiran tidak membazir seperti dalam menghasilkan sesuatu barang yang sangat kecil, dia akan cari scrap dahulu dan tidak guna bahan yang baru atau bahan yang besar.Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan.</em></p>', NULL, NULL, '2024-11-23 16:12:52', '2024-11-23 16:12:52', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1965, 599, 5, '<p>Berhati-hati semasa bekerja dan berinisiatif menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya. Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan dan juga menyedarkan dan membetulkan kesilapan rakan sekerja yang lain.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dengan pelan kerja dan memastikan semua barang yang ambil adalah betul. Ada pemikiran tidak membazir seperti dalam menghasilkan sesuatu barang yang sangat kecil, dia akan cari scrap dahulu dan tidak guna bahan yang baru atau bahan yang besar.Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan dan menyedarkan dan membetulkan kesilapan rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-23 16:13:07', '2024-11-23 16:13:07', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1966, 600, 1, '<p>Pengetahuan atau kemahiran adalah terhad dan tidak dapat menyelesaikan tugasan dan menggunakan masa yang panjang untuk mempelajari pengetahuan dan cara kerja yang agak senang.<br /><br /><em>Contoh: Tidak ada pengetahuan dan kemahiran kerja dan menggunakan masa yang panjang untuk mempelajari cara kerja yang senang walaupun bimbingan telah diberi seperti membuat kerja kimpalan yang paling senang iaitu mengimpal besi dalam kedudukan rata.</em></p>', NULL, NULL, '2024-11-23 16:13:42', '2024-11-23 16:13:42', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1967, 600, 2, '<p>Kurang pengetahuan atau kemahiran yang cukup untuk mengendalikan tugasan.<br /><br /><em>Contoh: Hasil kimpalan yang teruk dan bimbingan masih diperlukan walaupun diminta menghasilkan kerja kimpalan yang agak senang seperti mengimpal besi dalam kedudukan rata dan mendatar.</em></p>', NULL, NULL, '2024-11-23 16:13:53', '2024-11-23 16:13:53', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1968, 600, 3, '<p>Mempunyai pengetahuan dan kemahiran untuk mengendalikan tugasan dan mempunyai sikap mahu belajar dan mempelajari pengetahuan kerja yang baru dalam masa yang singkat dan mengimplikasikan dalam kerja harian.<br /><br /><em>Contoh: Ada pengetahuan dan kemahiran kimpalan tetapi tidak dapat meneruskan kerja apabila menghadapi kerja yang tidak biasa dan memerlukan bimbingan seperti: boleh mengimpal besi yang nipis tetapi tidak apabila diminta mengimpal besi yang lagi nipis / boleh mengimpal dalam kedudukan rata, mendatar dan menegak tetapi tidak apabila dalam keadaan overhead atau dalam keadaan 45 darjah.</em></p>', NULL, NULL, '2024-11-23 16:14:04', '2024-11-23 16:14:04', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1969, 600, 4, '<p>Boleh menguasai pengetahuan dan kemahiran untuk mengendalikan tugasan dan pencapaian yang agak memuaskan dan dapat menggunakan pengetahuannya untuk meningkatkan kualiti kerja.<br /><br /><em>Contoh: Mempunyai pengetahuan dan kemahiran yang luas serta jelas dengan semua keperluan/permintaan kerja seperti memilih kaedah yang bersesuaian untuk menghasilkan kerja dan tahu mengawal had api untuk mencegah hasil kerja dari kerosakan.</em></p>', NULL, NULL, '2024-11-23 16:14:16', '2024-11-23 16:14:16', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1970, 600, 5, '<p>Menguasai pengetahuan dan kemahiran untuk mengendalikan tugasan dan boleh menggabungkan pengetahuan untuk meningkatkan kualiti kerja serta mencari cara kerja baru untuk menyelesaikan masalah kerja dengan pengetahuannya.<br /><br /><em>Contoh: Mempunyai pengetahuan dan kemahiran yang luas serta jelas dengan semua keperluan/permintaan kerja dan berinisiatif memberi cadangan untuk menyelesaikan masalah kerja.&nbsp;</em></p>', NULL, NULL, '2024-11-23 16:14:28', '2024-11-23 16:14:28', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1971, 601, 1, '<p>Tidak pernah mengemas dan membersihkan tempat kerja sendiri dan sentiasa mengotorkan tempat kerja sendiri dan rakan sekerja yang lain.<br /><br /><em>Contoh: Tidak pernah terfikir kebaikan bersama dan terus membuang sisa kerja ke lantai dan menganggap ini kerja cleaner untuk membersihkan.</em></p>', NULL, NULL, '2024-11-23 16:15:08', '2024-11-23 16:15:08', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1972, 601, 2, '<p>Kadangkala ada mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya tidak kemas.<br /><br /><em>Contoh: Tidak selalu mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya tidak kemas seperti kadangkala ada membersihkan tempat kerja dan kadangkala tidak.</em></p>', NULL, NULL, '2024-11-23 16:15:21', '2024-11-23 16:15:21', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1973, 601, 3, '<p>Berinisiatif untuk mengemas dan membersihkan tempat kerja dan kebanyakan masa tempat kerjanya adalah kemas dan bersih.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai.</em></p>', NULL, NULL, '2024-11-23 16:15:30', '2024-11-23 16:15:30', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1974, 601, 4, '<p>Selalu mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya kemas dan selalu menolong membersihkan kawasan bahagiannya (division) dan kilang.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai serta tolong membersihkan kawasan yang lain.</em></p>', NULL, NULL, '2024-11-23 16:16:12', '2024-11-23 16:16:12', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1975, 601, 5, '<p>Selalu mengemas dan membersihkan tempat kerja dan tempat kerjanya kelihatan kemas dan bersih. Juga selalu menjaga kebersihan seluruh kawasan kilang dan dapat menegur rakan sekerja untuk menjaga kebersihan kilang.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai serta tolong menjaga kebersihan kawasan yang lain dan menegur rakan sekerja yang tidak menjaga kebersihan kilang.</em></p>', NULL, NULL, '2024-11-23 16:16:23', '2024-11-23 16:16:23', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1976, 602, 1, '<p>Tidak menjaga peralatan dan kemudahan syarikat.<br /><br /><em>Contoh: Tidak menjaga peralatan dan kemudahan syarikat seperti tidak menjaga forklift dan tidak pernah meletakkkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-23 16:16:51', '2024-11-23 16:16:51', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1977, 602, 2, '<p>Kadangkala bersikap cuai dalam mengendali peralatan dan kemudahan syarikat dan mengakibatkan kerosakan.<br /><br /><em>Contoh: Tidak selalu menjaga peralatan dan kemudahan syarikat dan mengakibatkan kerosakan seperti forklift terus jalan setelah enjin dihidupkan. Tidak mengambil berat tentang barang yang diangkat dan masuk ke ruang yang kecil. Selalu tidak meletakkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-23 16:17:02', '2024-11-23 16:17:02', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1978, 602, 3, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat dengan cara yang betul.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-23 16:17:18', '2024-11-23 16:17:18', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1979, 602, 4, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat demi kebaikan bersama. Selain itu, &nbsp;melaporkan kepada pihak atasan bila nampak rakan sekerja salahguna dan memberi cara penyelesaian yang bermanfaat.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna dan melapor jika ada kerosakan dan memberi cadangan untuk memperbaiki cara penggunaan dan penjagaan alatan.</em></p>', NULL, NULL, '2024-11-23 16:17:30', '2024-11-23 16:17:30', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1980, 602, 5, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat demi kebaikan bersama. Selain itu, &nbsp;melaporkan kepada pihak atasan bila nampak pekerja salahguna dan memberi cara penyelesaian yang bermanfaat. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna dan melapor jika ada kerosakan dan memberi cadangan untuk memperbaiki cara penggunaan dan penjagaan alatan.Selain itu, akan menyedarkan dan menasihati rakan sekerja yang tidak menjaga forklift semasa mengguna.</em></p>', NULL, NULL, '2024-11-23 16:17:55', '2024-11-23 16:17:55', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1981, 603, 1, '<p>Tidak mengutamakan keselamatan semasa bekerja.<br /><br /><em>Contoh: Tidak mengutamakan keselamatan semasa bekerja seperti tidak memakai PPE semasa bekerja.</em></p>', NULL, NULL, '2024-11-23 16:18:25', '2024-11-23 16:18:25', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1982, 603, 2, '<p>Ada sikap mengutamakan keselamatan tetapi kadangkala tidak.<br /><br /><em>Contoh: Ada memakai PPE semasa bekerja tetapi kadangkala tidak.</em></p>', NULL, NULL, '2024-11-23 16:18:35', '2024-11-23 16:18:35', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1983, 603, 3, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja.</em></p>', NULL, NULL, '2024-11-23 16:18:46', '2024-11-23 16:18:46', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1984, 603, 4, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan.</em></p>', NULL, NULL, '2024-11-23 16:18:58', '2024-11-23 16:18:58', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1985, 603, 5, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja dan melaporkan kepada pihak atasan serta turut memberi cara atau cara penyelesaian yang bermanfaat.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan serta turut memberi cara atau cara penyelesaian yang bermanfaat.</em></p>', NULL, NULL, '2024-11-23 16:19:09', '2024-11-23 16:19:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1986, 604, 1, '<p>Menerima tugasan tetapi tidak memikul tanggungjawab kerja dan tidak dapat bekerja di bawah tekanan.<br /><br /><em>Contoh: Dia terima kerja yang diberi tetapi sentiasa bersembang dengan rakan sekerja dan tidak buat kerja sehingga tidak nampak hasil kerja.</em></p>', NULL, NULL, '2024-11-23 16:19:48', '2024-11-23 16:19:48', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1987, 604, 2, '<p>Boleh menerima dan memikul tanggungjawab dan cuba untuk bekerja di bawah tekanan tetapi kadangkala tidak dapat menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Dia boleh buat kerja dan cuba elakkan diri dari tidak masuk kerja/tidak memberi alasan untuk bercuti tetapi kadangkala masih perlu dalam bimbingan.</em></p>', NULL, NULL, '2024-11-23 16:19:58', '2024-11-23 16:19:58', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1988, 604, 3, '<p>Boleh menerima dan memikul tanggungjawab dan dapat menghabiskan setiap kerja yang diamanahkan dengan baik di bawah tekanan dan melaporkan kerja yang telah dilakukan kepada pegawai atasan.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia masih menepati target dan ikut piawai kerja yang ditetapkan oleh syarikat. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia juga akan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-23 16:20:11', '2024-11-23 16:20:11', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1989, 604, 4, '<p>Rela menerima dan memikul tanggungjawab dan sentiasa dapat menghasilkan kerja yang berkualiti di bawah tekanan dan dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang dilakukan kepada pegawai atasan.Boleh buat kerja lebih masa sehingga kerja siap.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia akan menawarkan diri secara sukarela untuk kerja tersebut serta menepati target dan ikut piawai kerja yang ditetapkan oleh syarikat. Boleh buat kerja lebih masa sehingga kerja siap. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-23 16:20:22', '2024-11-23 16:20:22', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1990, 604, 5, '<p>Rela menerima dan memikul tanggungjawab serta tahu kepentingan dan deadline kerja. Dapat memanggil rakan sekerja untuk menyiapkan kerja bersama. Sentiasa dapat menghasilkan kerja yang berkualiti di bawah tekanan dan dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang dilakukan kepada pegawai atasan.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia tahu kepentingan dan deadline kerja tersebut serta dapat memanggil rakan sekerja untuk menyiapkan kerja bersama. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-23 16:20:36', '2024-11-23 16:20:36', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1991, 605, 1, '<p>Tidak rela mengaku kesilapan dan suka menolak tanggungjawab kepada orang lain.<br /><br /><em>Contoh: Telah melakukan kesilapan seperti tidak mengikuti spesifikasi kerja yang diberi oleh Leader / tidak tanya Leader apabila tidak faham / tanya rakan sekerja yang tidak dipertanggungjawabkan dan tidak pernah mengakui kesilapan apabila ditegur oleh Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-23 16:21:03', '2024-11-23 16:21:10', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1992, 605, 2, '<p>Kadangkala tidak rela mengaku kesilapan dan suka membuat perbandingan diri dengan orang lain dalam kesilapan yang telah dibuat.<br /><br /><em>Contoh: Telah melakukan kesilapan seperti tidak mengikuti spesifikasi kerja yang diberi oleh Leader / tidak tanya Leader apabila tidak faham / tanya rakan sekerja yang tidak dipertanggungjawabkan dan kadangkala tidak mengakui kesilapan apabila ditegur oleh Leader/Supervisor malah menyatakan Leader/Supervisor ada prasangka terhadap dia.</em></p>', NULL, NULL, '2024-11-23 16:21:29', '2024-11-23 16:21:29', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1993, 605, 3, '<p>Mengaku kesilapan dan tidak menolak tanggungjawab kepada orang lain.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan. Dia terima dan mengakui kesilapan.</em></p>', NULL, NULL, '2024-11-23 16:21:45', '2024-11-23 16:21:45', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1994, 605, 4, '<p>Tidak melarikan diri dari tanggungjawab dan terus berjumpa dengan pihak atasan untuk mengakui kesilapan dan berinisiatif untuk memperbaiki kesilapan yang telah dilakukan.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan. Dia tidak melarikan diri dari tanggungjawab dan terus berjumpa dengan Leader/Supervisor dan mengakui kesilapan. Selain itu, dia juga memberi cadangan dan sama-sama memperbaiki kesilapan yang telah dilakukan.</em></p>', NULL, NULL, '2024-11-23 16:21:54', '2024-11-23 16:21:54', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1995, 605, 5, '<p>Berani mengaku kesilapan dan tidak menolak tanggungjawab dan memastikan kesilapan tidak berlaku lagi. Berinisiatif untuk memperbetulkan kesilapan dan dapat memberi cadangan yang bermanfaat untuk mengelakkan kesilapan berlaku lagi.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan yang agak besar. Dia berani mengakui kesilapan dan terus berjumpa dengan Leader/Supervisor untuk mengakui kesilapan. Dia mengambil pengalaman tersebut sebagai satu pengajaran dan tidak mengulangi kesilapan tersebut lagi. Selain itu, dia &nbsp;memberi cadangan dan sama-sama memperbaiki kesilapan yang telah dilakukan serta memberi cadangan yang bermanfaat untuk mengelakkan kesilapan berlaku lagi.</em></p>', NULL, NULL, '2024-11-23 16:22:08', '2024-11-23 16:22:08', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1996, 606, 1, '<p>Membuat kerja alah kadar dan setakat membuat kerja sahaja dan tidak menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Tidak menunjukkan sikap ingin belajar dan tidak menumpukan perhatian semasa bekerja seperti dia boleh mengambil masa yang panjang untuk memasang beberapa nut pada mesin.</em></p>', NULL, NULL, '2024-11-23 16:22:38', '2024-11-23 16:22:38', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1997, 606, 2, '<p>Boleh membuat kerja tetapi mudah dipengaruhi orang lain dan kadangkala tidak dapat menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Dia boleh pasang nut pada mesin tetapi mudah dipengaruhi oleh rakan sekerja yang lain seperti dia akan melambatkan proses kerjanya dan sambil kerja sambil bersembang apabila ada rakan sekerja yang bersembang dengannya semasa bekerja.</em></p>', NULL, NULL, '2024-11-23 16:22:49', '2024-11-23 16:22:49', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1998, 606, 3, '<p>Lebih agresif dan sikap kerja juga serius dan dapat menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak mengangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja.</em></p>', NULL, NULL, '2024-11-23 16:22:59', '2024-11-23 16:22:59', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (1999, 606, 4, '<p>Bersemangat kerja dan menumpukan perhatian sepenuhnya dalam kerja. Sentiasa mengutamakan kualiti kerja dan menghasilkan kerja yang halus dan teliti dan tidak melakukan kesilapan.<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak menggangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja. Dia sentiasa mengutamakan kualiti kerja dan memastikan nut yang dipasang itu betul dan kemas.</em></p>', NULL, NULL, '2024-11-23 16:23:09', '2024-11-23 16:23:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2000, 606, 5, '<p>Matlamat untuk berjaya sangat jelas. Menumpukan perhatian sepenuhnya dalam kerja. Sentiasa mengutamakan kualiti kerja dan menghasilkan kerja yang halus dan teliti dan tidak melakukan kesilapan. Selain itu turut memberi cadangan dan cara kerja untuk memastikan kerja berkualiti dihasilkan setiap kali.&nbsp;<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak menggangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja. Dia sentiasa mengutamakan kualiti kerja dan memastikan nut yang dipasang itu betul dan kemas. Selain itu, dia juga akan memberi cadangan untuk memastikan kerja berkualiti dapat dihasilkan.</em></p>', NULL, NULL, '2024-11-23 16:23:22', '2024-11-23 16:23:22', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2001, 607, 1, '<p>Langsung tidak mahu memahami dan menerima peraturan dan polisi syarikat dan sentiasa membuat aduan terhadap dasar syarikat.<br /><br /><em>Contoh: Selalu tidak menutup lampu setelah mengguna tandas dan membuat aduan apabila pihak syarikat mengambil tindakan.</em></p>', NULL, NULL, '2024-11-23 16:24:22', '2024-11-23 16:24:22', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2002, 607, 2, '<p>Kadangkala sahaja mahu menerima dan mematuhi peraturan dan polisi syarikat.<br /><br /><em>Contoh: Kadangkala ada menutup lampu setelah mengguna tandas kadangkala tidak.</em></p>', NULL, NULL, '2024-11-23 16:24:39', '2024-11-23 16:24:39', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2003, 607, 3, '<p>Menerima dan mematuhi setiap peraturan dan polisi syarikat.<br /><br /><em>Contoh: Setiap kali akan menutup lampu setelah mengguna tandas.</em></p>', NULL, NULL, '2024-11-23 16:24:51', '2024-11-23 16:24:51', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2004, 607, 4, '<p>Tidak melanggar peraturan dan sentiasa dapat menasihatkan rakan sekerja untuk menerima dan mematuhi peraturan dan polisi syarikat untuk kebaikan bersama.<br /><br /><em>Contoh: Sentiasa menutup lampu setelah mengguna tandas dan &nbsp;menasihati dan menerang kepada rakan sekerja yang tidak mematuhi peraturan.</em></p>', NULL, NULL, '2024-11-23 16:25:01', '2024-11-23 16:25:01', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2005, 607, 5, '<p>Memahami dan menerima setiap peraturan dan polisi syarikat dan sentiasa menasihatkan rakan sekerja yang melanggar peraturan serta melaporkan masalah disiplin kepada pegawai atasan untuk kebaikan bersama.<br /><br /><em>Contoh: &nbsp;Sentiasa menutup lampu setelah mengguna tandas dan &nbsp;menasihati dan menerang kepada rakan sekerja yang tidak mematuhi peraturan. Selain itu, juga akan melaporkan nama pekerja yang tidak menutup lampu setelah mengguna tandas.</em></p>', NULL, NULL, '2024-11-23 16:25:12', '2024-11-23 16:25:12', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2006, 608, 1, '<p>Selalu tidak tepat masuk kerja dan menunjukkan kedatangan yang tidak baik.<br /><br /><em>Contoh: Masih berada di tempat berehat semasa siren berbunyi dan jalan perlahan ke tempat kerja.</em></p>', NULL, NULL, '2024-11-23 16:25:47', '2024-11-23 16:25:47', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2007, 608, 2, '<p>Kadangkala ada masuk kerja pada masa yang ditetapkan tetapi keadaan tidak ketara.<br /><br /><em>Contoh: Kadangkala ada tepat masuk kerja semasa siren berbunyi tetapi kebanyakan masa tidak masuk kerja pada masa yang tepat.</em></p>', NULL, NULL, '2024-11-23 16:26:11', '2024-11-23 16:26:11', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2008, 608, 3, '<p>Kebanyakan masa masuk kerja pada masa yang ditetapkan tetapi kadangkala ada lewat juga.<br /><br /><em>Contoh: Kebanyakan masa masuk kerja semasa siren berbunyi tetapi sekali kala masih lewat masuk kerja.</em></p>', NULL, NULL, '2024-11-23 16:26:21', '2024-11-23 16:26:21', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2009, 608, 4, '<p>Mementingkan ketepatan masa masuk kerja dan masuk kerja tepat pada masa atau lebih awal.<br /><br /><em>Contoh: Sentiasa masa masuk kerja sebelum siren berbunyi atau lebih awal.</em></p>', NULL, NULL, '2024-11-23 16:26:31', '2024-11-23 16:26:31', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2010, 608, 5, '<p>Mementingkan ketepatan masa masuk kerja dan masuk kerja tepat pada masa atau lebih awal serta memberi nasihat kepada rakan sekerja yang lewat.<br /><br /><em>Contoh: Sentiasa masa masuk kerja sebelum siren berbunyi atau lebih awal serta memberi nasihat kepada rakan sekerja yang lewat.</em></p>', NULL, NULL, '2024-11-23 16:26:41', '2024-11-23 16:26:41', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2011, 609, 1, '<p>Disiplin diri yang tidak memuaskan dan sering meninggalkan tempat kerja dengan berkeliaran tanpa tujuan dan sering membazirkan masa serta curi tulang.<br /><br /><em>Contoh: Sering meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja (banyak kali sehari) dan mengambil masa yang panjang dalam tandas serta membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-23 16:27:36', '2024-11-23 16:27:36', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2012, 609, 2, '<p>Kadangkala membazirkan masa dan curi tulang serta meninggalkan tempat kerja dengan berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Kadangkala meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja (banyak kali sehari) dan mengambil masa yang panjang dalam tandas serta membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-23 16:27:49', '2024-11-23 16:27:49', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2013, 609, 3, '<p>Tidak membazirkan masa dan ringan tulang serta menumpukan perhatian semasa bekerja. Tidak meninggalkan tempat kerja dengan berkeliaran tanpa tujuan.<br /><br /><em>Contoh: Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-23 16:28:14', '2024-11-23 16:28:14', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2014, 609, 4, '<p>Teladan yang baik dan tumpuan perhatian sepenuhnya semasa bekerja. Tidak berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Seorang teladan yang baik dan memberi tumpuan sepenuhnya semasa bekerja. Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-23 16:30:33', '2024-11-23 16:30:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2015, 609, 5, '<p>Teladan yang baik dan tumpuan perhatian sepenuhnya semasa bekerja dan juga selalu memberi nasihat kepada rakan sekerja supaya melahirkan keadaan kerja yang lebih agresif. Tidak berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Seorang teladan yang baik dan memberi tumpuan sepenuhnya semasa bekerja. Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja. Selalu memberi nasihat kepada rakan sekerja yang selalu pergi ke tandas sebagai alasan.</em></p>', NULL, NULL, '2024-11-23 16:30:54', '2024-11-23 16:30:54', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2016, 610, 1, '<p>Tidak pernah berada di tempat kerja semasa pembersihan kawasan dijalankan.<br /><br /><em>Contoh: Tidak berada di tempat kerja dan pergi ke tandas semasa pembersihan kawasan dijalankan.</em></p>', NULL, NULL, '2024-11-23 16:32:01', '2024-11-23 16:32:01', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2017, 610, 2, '<p>Memulakan kerja pembersihan kawasan walaupun masa yang ditetapkan belum sampai lagi.<br /><br /><em>Contoh: Memulakan kerja pembersihan kawasan walaupun masa yang ditetapkan belum sampai lagi dan rakan sekerja yang lain masih bekerja lagi.</em></p>', NULL, NULL, '2024-11-23 16:32:12', '2024-11-23 16:32:12', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2018, 610, 3, '<p>Kebanyakan masa membersihkan kawasan production pada masa yang ditetapkan.</p><p>Kadangkala membersihkan kawasan production pada masa yang ditetapkan tetapi keadaan tidak ketara.</p><p><br />\nContoh: Kadangkala ada berada di production semasa pembersihan kawasan dijalankan tetapi kebanyakan masa tidak nampak orang.</p>', NULL, NULL, '2024-11-23 16:32:23', '2024-11-23 16:32:23', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2019, 610, 4, '<p>Sentiasa mengutamakan dan membersihkan kawasan production pada masa yang ditetapkan.<br /><br /><em>Contoh: Sentiasa membersihkan kawasan production pada masa yang ditetapkan.</em></p>', NULL, NULL, '2024-11-23 16:32:34', '2024-11-23 16:32:34', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2020, 610, 5, '<p>Mengutamakan dan membersihkan kawasan production pada masa yang ditetapkan serta memberi nasihat kepada rakan sekerja yang tidak berbuat demikian.<br /><br /><em>Contoh: Sentiasa membersihkan kawasan production pada masa yang ditetapkan dan memberi nasihat kepada rakan sekerja yang tidak berbuat demikian.</em></p>', NULL, NULL, '2024-11-23 16:32:47', '2024-11-23 16:32:47', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2021, 611, 1, '<p>Hanya menghormati pegawai atasan dan tidak bersopan dengan rakan sekerja.<br /><br /><em>Contoh: Hanya menghormati Leader/Supervisor atau pangkat kerja yang lebih tinggi tetapi tidak bersopan dengan rakan sekerja yang berpangkat rendah/masih baru.</em></p>', NULL, NULL, '2024-11-23 17:45:59', '2024-11-23 17:45:59', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2022, 611, 2, '<p>Biasanya akan bersopan dan menghormati orang lain tetapi kadangkala beremosi.<br /><br /><em>Contoh: Biasanya bersopan dan menghormati rakan sekerja yang lain tetapi kadangkala beremosi dan lawan cakap.</em></p>', NULL, NULL, '2024-11-23 17:46:12', '2024-11-23 17:46:12', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2023, 611, 3, '<p>Sering bersopan dan menghormati orang lain dan tidak bertindak mengikut perasaan.<br /><br /><em>Contoh: Sering bersopan dan menghormati rakan sekerja lain dan tidak bertindak mengikut perasaan.</em></p>', NULL, NULL, '2024-11-23 17:46:22', '2024-11-23 17:46:22', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2024, 611, 4, '<p>Bersopan dan menghormati orang lain pada setiap masa dan tidak bertindak mengikut perasaan dan berbahasa sopan.<br /><br /><em>Contoh: Bersopan dan setiap masa menghormati rakan sekerja yang lain dan tidak bertindak mengikut perasaan dan berbahasa sopan serta jaga perasaan rakan lain.</em></p>', NULL, NULL, '2024-11-23 17:46:51', '2024-11-23 17:46:51', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2025, 611, 5, '<p>Bersopan dan menghormati orang lain pada setiap masa dan masih bercakap dengan sopan walaupun sendiri telah dipersalahkan dalam proses penyelesaian masalah.<br /><br /><em>Contoh: Bersopan dan setiap masa menghormati rakan sekerja yang lain dan masih bercakap dengan sopan walaupun sendiri telah dipersalahkan dalam proses penyelesaian masalah.</em></p>', NULL, NULL, '2024-11-23 17:47:00', '2024-11-23 17:47:00', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2026, 612, 1, '<p>Memang mengetahui arahan yang diberi mempunyai kesilapan tetapi tidak mendapatkan kepastian kerana berpendapat itu adalah tanggungjawab pegawai atasan.<br /><br /><em>Contoh: Tidak mendapatkan kepastian daripada Leader/Supervisor tentang spesifikasi kerja yang diberi walaupun sudah tahu arahan yang diberi mempunyai kesilapan/tidak jelas dan beranggap itu adalah tanggungjawab Leader/Supervisor dan bukan dia.</em></p>', NULL, NULL, '2024-11-23 17:47:38', '2024-11-23 17:47:38', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2027, 612, 2, '<p>Jarang berinisiatif untuk mendapatkan kepastian daripada pegawai atasan walaupun arahan yang diberi tidak jelas atau silap.<br /><br /><em>Contoh: Menunjukkan sikap sudah tahu tetapi tidak ingin peduli dan tidak mendapatkan kepastian daripada Leader/Supervisor walapun arahan yang diberi ada kesilapan/kurang jelas.</em></p>', NULL, NULL, '2024-11-23 17:47:47', '2024-11-23 17:47:47', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2028, 612, 3, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap tetapi tidak pernah melapor balik kepada pegawai atasan tentang tugasan tersebut.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi ada kesilapan/tidak jelas tetapi tidak pernah melapor balik tugasan tersebut.</em></p>', NULL, NULL, '2024-11-23 17:47:58', '2024-11-23 17:47:58', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2029, 612, 4, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi tidak jelas/silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut.</em></p>', NULL, NULL, '2024-11-23 17:48:07', '2024-11-23 17:48:07', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2030, 612, 5, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut serta memberi pendapat yang bermanfaat.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi tidak jelas/silap dan selalu melapor balik kepada Leader/Supervisor dan turut mengambil bahagian untuk memberi pendapat yang bermanfaat.</em></p>', NULL, NULL, '2024-11-23 17:48:18', '2024-11-23 17:48:18', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2031, 613, 1, '<p>Degil dan berpegang teguh dengan pendapat sendiri dan tidak menuruti arahan pegawai atasan.<br /><br /><em>Contoh: Tidak menerima dan melawan percakapan Leader/Supervisor semasa diberi tugasan.</em></p>', NULL, NULL, '2024-11-23 17:48:48', '2024-11-23 17:48:48', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2032, 613, 2, '<p>Kebanyakan masa akan menuruti arahan pegawai atasan tetapi kadangkala akan beremosi dan meluahkan ketidakpuasan.<br /><br /><em>Contoh: Kebanyakan masa akan menerima tugasan Leader/Supervisor dengan baik tetapi kadangkala tidak.</em></p>', NULL, NULL, '2024-11-23 17:48:57', '2024-11-23 17:48:57', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2033, 613, 3, '<p>Mengambil berat dan menuruti arahan pegawai atasan dan tidak pernah membuat hal sesuka hati.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati dan akan bertanya jika tidak faham.</em></p>', NULL, NULL, '2024-11-23 17:49:06', '2024-11-23 17:49:06', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2034, 613, 4, '<p>Mengambil berat dan menuruti arahan pegawai atasan dan tidak pernah membuat hal sesuka hati. Kadangkala turut memberikan pendapat yang bermanfaat dalan kerja yang diberi.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati dan akan bertanya jika tidak faham. Kadangkala turut memberi cadangan/pandangan dalam kerja yang diberi.</em></p>', NULL, NULL, '2024-11-23 17:49:15', '2024-11-23 17:49:15', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2035, 613, 5, '<p>Bersikap positif dan menuruti semua arahan pegawai atasan, tidak membuat hal malah dapat menyampaikan objektif dan kehendak arahan secara positif kepada semua rakan sekerja.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati. Turut menyampaikan maksud dan kehendak mengikuti arahan Leader/Supervisor secara positif kepada rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-23 17:49:26', '2024-11-23 17:49:26', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2036, 614, 1, '<p>Ego dan tidak sudi berbincang tugasan sesama rakan sekerja dan pegawai atasan, sangat keras kepala dan tidak dapat menerima cadangan orang lain.<br /><br /><em>Contoh: Buat kerja tanpa ikut pelan kerja seperti menebuk drill pada kelajuan yang tinggi dan telah membesarkan lubang 3mm kepada 3.20 mm. Dia tidak dapat menerima apabila diminta buat semula pada kelajuan drill yang rendah.</em></p>', NULL, NULL, '2024-11-23 17:49:57', '2024-11-23 17:49:57', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2037, 614, 2, '<p>Jarang berbincang tugasan sesama rakan sekerja dan pegawai atasan dan tidak begitu rela berkongsi maklumat, kadangkala keras kepala dan tidak dapat menerima cadangan orang lain.<br /><br /><em>Contoh: Dia menunjukkan sikap yang tidak begitu gembira apabila diminta buat semula pada kelajuan drill yang rendah.</em></p>', NULL, NULL, '2024-11-23 17:50:05', '2024-11-23 17:50:05', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2038, 614, 3, '<p>Sudi berbincang dan menerima cadangan rakan sekerja dan pegawai atasan, dapat memberi pertolongan apabila diminta.<br /><br /><em>Contoh: Dia sudi membuat semula pada kelajuan drill yang rendah setelah berbincang dan diminta berubah.</em></p>', NULL, NULL, '2024-11-23 17:50:14', '2024-11-23 17:50:14', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2039, 614, 4, '<p>Sudi berbincang dan berinisiatif memberi pertolongan sesama rakan sekerja dan pegawai atasan dengan tidak berkira kerja. Boleh menerima cadangan orang lain dan tidak berkeras kepala.<br /><br /><em>Contoh: Dia sudi membuat semula pada kelajuan drill yang rendah dan dia turut memberi cadangan untuk mengatasi masalah tersebut.</em></p>', NULL, NULL, '2024-11-23 17:50:24', '2024-11-23 17:50:24', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2040, 614, 5, '<p>Sudi berbincang dan berinisiatif memberi pertolongan sesama rakan sekerja dan pegawai atasan dengan tidak berkira kerja. Boleh menerima cadangan orang lain dan tidak berkeras kepala. Selain itu, turut boleh memanggil rakan sekerja untuk sama-sama menyiapkan kerja tersebut.<br /><br /><em>Contoh: Dia ialah orang yang sangat agresif dan sudi membuat semula dan dia turut boleh meminta rakan sekerja untuk sama-sama menyiapkan kerja.</em></p>', NULL, NULL, '2024-11-23 17:50:40', '2024-11-23 17:50:40', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2041, 615, 1, '<p>Menolak tugasan selain dari bidang sendiri dan langsung tidak dapat menerima tugasan tambahan atau di luar bidang kerja, amat mementingkan diri sendiri.<br /><br /><em>Contoh: Tidak mahu backup rakan sekerja yang bercuti dan selalu dipengaruhi oleh rakan sekerja yang lain dimana orang yang berbuat banyak tidak dapat apa-apa.</em></p>', NULL, NULL, '2024-11-23 17:51:04', '2024-11-23 17:51:04', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2042, 615, 2, '<p>Kadangkala menerima tugasan tambahan atau di luar bidang kerja tetapi dengan hati yang tidak rela dan mementingkan kepentingan diri sendiri.<br /><br /><em>Contoh: Kadangkala akan diminta untuk backup rakan sekerja yang bercuti tetapi dia akan membuat kerja secara tidak rela / memberi alasan bahawa dia tidak tahu buat kerja tersebut.</em></p>', NULL, NULL, '2024-11-23 17:51:15', '2024-11-23 17:51:15', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2043, 615, 3, '<p>Rela menerima tugasan tambahan atau di luar bidang dan tidak menolak apabila tugas diberi.<br /><br /><em>Contoh: Rela backup rakan sekerja yang bercuti dan tidak menolak apabila tugas diberi oleh Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-25 08:40:54', '2024-11-25 08:40:54', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2044, 615, 4, '<p>Rela menerima tugasan tambahan atau di luar bidang dan tidak menolak apabila tugas diberi serta cuba mencari cara untuk menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Rela backup rakan sekerja yang bercuti dan tidak menolak apabila tugas diberi oleh Leader / Supervisor. Selain itu, dia juga cari jalan untuk mengeluarkan hasil kerja yang baik / membuat kerja tersebut dengan bersungguh-sungguh.</em></p>', NULL, NULL, '2024-11-25 08:41:05', '2024-11-25 08:41:05', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2045, 615, 5, '<p>Amat rela menerima tugasan tambahan atau di luar bidang dan menerimanya sebagai satu cabaran. Berusaha dan bertanggungjawab sepenuhnya sehingga tugasan selesai dengan sempurna.<br /><br /><em>Contoh: Sangat rela backup rakan sekerja yang bercuti dan menganggap tugas yang diberi tersebut sebagai satu cabaran / tugas sendiri. Dia membuat kerja dengan sepenuh hati dan mengambil tanggungjawab sehingga tugasan tersebut selesai dengan sempurnanya.</em></p>', NULL, NULL, '2024-11-25 08:41:20', '2024-11-25 08:41:20', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2047, 628, 1, '<p>Tidak dapat membuat apa-apa analisis dengan data yang ada dan tidak dapat mengenal pasti masalah-masalah.</p>', NULL, NULL, '2024-11-27 16:17:46', '2024-11-27 16:17:46', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2048, 628, 2, '<p>Dapat menganalisis data yand ada dan kadang-kala dapat mencari punca masalah.</p>', NULL, NULL, '2024-11-27 16:17:56', '2024-11-27 16:17:56', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2049, 628, 3, '<p>Dapat menganalisis data yang ada dan mencari punca masalah yang sering berlaku dan cuba memberi cadangan kepada pihak berkenaan untuk menyelesaikan masalah.</p>', NULL, NULL, '2024-11-27 16:18:06', '2024-11-27 16:18:06', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2050, 628, 4, '<p>Dapat menganalisis data yang diperoleh, mengenal pasti masalah dengan tepat dan dapat memberi cadangan dan berusaha melaksanakan pembetulan supaya masalah tidak berlaku lagi.</p>', NULL, NULL, '2024-11-27 16:18:16', '2024-11-27 16:18:16', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2051, 628, 5, '<p>Dapat berfikir untuk mendapat data untuk dianalisis dan menggunakan data yang diperoleh untuk mengkaji punca masalah dan membuat satu piawaian dan memastikan piawaian dapat diikut dan masalah tidak berlaku lagi.</p>', NULL, NULL, '2024-11-27 16:18:26', '2024-11-27 16:18:26', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2052, 629, 1, '<p>Tidak dapat menyelesaikan masalah dan perlu selalu merujuk kepada senior.</p>', NULL, NULL, '2024-11-27 16:18:50', '2024-11-27 16:18:50', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2053, 629, 2, '<p>Hanya dapat menyelesaikan masalah yang ringkas dan tidak dapat membuat keputusan dan perlu merujuk kepada senior.</p>', NULL, NULL, '2024-11-27 16:19:00', '2024-11-27 16:19:00', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2054, 629, 3, '<p>Dapat menyelesaikan masalah-masalah yang dihadapi dengan cermat dan membuat keputusan yang betul untuk menyelesaikan masalah dalam masa tersingkat.</p>', NULL, NULL, '2024-11-27 16:19:09', '2024-11-27 16:19:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2055, 629, 4, '<p>Dapat mengambil keputusan untuk menyelesaikan masalah-masalah yang dihadapi dalam masa tersingkat dan &ldquo;follow up&rdquo; supaya dapat memastikan tiada lagi masalah yang tertimbul sehingga masalah diselesaikan dan melaporkan kepada pihak atasan tentang masalah tersebut.</p>', NULL, NULL, '2024-11-27 16:19:21', '2024-11-27 16:19:21', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2056, 629, 5, '<p>Dapat mengambil keputusan untuk menyelesaikan masalah-masalah yang dihadapi dalam masa tersingkat dan &ldquo;follow up&rdquo; sehingga masalah diselesaikan dan melaporkan kepada pihak atasan tentang masalah yang dihadapi. Di samping itu, dapat memberi pendapat dan cadangan supaya perkara tersebut tidak berlaku lagi.</p>', NULL, NULL, '2024-11-27 16:19:34', '2024-11-27 16:19:34', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2057, 630, 1, '<p>Kerja tidak sistematik dan selalu terlupa kerja yang diberikan. Rekod kerja juga tidak dibuat dan tidak dapat kesan balik rekod kerja.</p>', NULL, NULL, '2024-11-27 16:19:57', '2024-11-27 16:19:57', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2058, 630, 2, '<p>Kerja dilakukan tidak bersistematik dan kadang-kala terlupa akan kerja yang diberikan. Di samping itu, kerja yang dibuat tidak di rekod dengan teliti dan susah untuk dikesan balik.</p>', NULL, NULL, '2024-11-27 16:20:08', '2024-11-27 16:20:08', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2059, 630, 3, '<p>Dapat melakukan kerja dengan sistematik, satu demi satu dan merekodkan semua kerja yang diberikan.</p>', NULL, NULL, '2024-11-27 16:20:17', '2024-11-27 16:20:17', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2060, 630, 4, '<p>Dapat melakukan kerja dengan sistematik, merekodkan semua kerja yang diberikan dan dapat dikesan balik setiap rekod. Di samping itu, &ldquo;follow up&rdquo; setiap rekod dan pastikan setiap rekod sempurna.</p>', NULL, NULL, '2024-11-27 16:20:27', '2024-11-27 16:20:27', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2061, 630, 5, '<p>Dapat merancang kerja sendiri dengan sistematik, mencipta dan membuat rekod dan sistem sendiri untuk pastikan kerja direkodkan dan dapat dikesan balik apabila diperlukan.</p>', NULL, NULL, '2024-11-27 16:20:40', '2024-11-27 16:20:40', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2062, 631, 1, '<p>Seorang yang tidak bertanggungjawab dan tidak berusaha dalam kerjayanya.</p>', NULL, NULL, '2024-11-27 16:21:24', '2024-11-27 16:21:24', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2063, 631, 2, '<p>Seorang yang bertanggungjawab tetapi tidak berkepercayaan kuat terhadap setiap tujuan dan hala organisasi.</p>', NULL, NULL, '2024-11-27 16:21:33', '2024-11-27 16:21:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2064, 631, 3, '<p>Seorang yang bersikap positif dan bertanggungjawab. Berkepercayaan kuat terhadap setiap tujuan dan hala organisasi dan berkemahuan berusaha untuk kepentingan organisasi dan berkeinginan yang kuat (loyalty) untuk mempertahankan kedudukan sebagai anggota organisasi.</p>', NULL, NULL, '2024-11-27 16:21:42', '2024-11-27 16:21:42', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2065, 631, 4, '<p>Seorang yang bersikap positif dan bertanggungjawab. Berkepercayaan kuat terhadap setiap tujuan dan hala organisasi dan berkemahuan berusaha untuk kepentingan organisasi dan berkeinginan yang kuat (loyalty) untuk mempertahankan kedudukan sebagai anggota organisasi. Selain itu, turut memberi nasihat jika terdapat rakan sekerja yang tidak sehaluan dengan pihak syarikat.</p>', NULL, NULL, '2024-11-27 16:21:51', '2024-11-27 16:21:51', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2066, 631, 5, '<p>Seorang yang bersikap positif dan bertanggungjawab. Berkepercayaan kuat terhadap setiap tujuan dan hala organisasi dan berkemahuan berusaha untuk kepentingan organisasi dan berkeinginan yang kuat (loyalty) untuk mempertahankan kedudukan sebagai anggota organisasi. Selain itu, turut memberi nasihat jika terdapat rakan sekerja yang tidak sehaluan dengan pihak syarikat dan sentiasa mempengaruhi rakan sekerja yang lain komitmen terhadap kerja demi kebaikan bersama.</p>', NULL, NULL, '2024-11-27 16:22:01', '2024-11-27 16:22:01', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2067, 632, 1, '<p>Bersikap negatif dan sentiasa mengadu dan membawa pengaruh negatif di kalangan rakan sekerja.</p>', NULL, NULL, '2024-11-27 16:22:26', '2024-11-27 16:22:26', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2068, 632, 2, '<p>Memerlukan motivasi daripada rakan sekerja tetapi tidak pernah membawa pengaruh negatif di kalangan rakan sekerja.</p>', NULL, NULL, '2024-11-27 16:22:34', '2024-11-27 16:22:34', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2069, 632, 3, '<p>Boleh memotivasikan rakan sekerja tetapi hasilnya tidak begitu besar.</p>', NULL, NULL, '2024-11-27 16:22:44', '2024-11-27 16:22:44', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2070, 632, 4, '<p>Boleh memotivasikan rakan sekerja dengan membawa hasil yang baik di mana tahu menggunakan keadaan dan kandungan kerja sebagai panduan memotivasikan orang lain.</p>', NULL, NULL, '2024-11-27 16:22:56', '2024-11-27 16:22:56', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2071, 632, 5, '<p>Boleh memotivasikan rakan sekerja dengan membawa hasil yang baik di mana tahu menggunakan keadaan dan kandungan kerja sebagai panduan memotivasikan orang lain. Selain itu akan melaporkan kesilapan rakan sekerja yang tidak mematuhi peraturan syarikat demi kebaikan bersama supaya tidak membawa pengaruh negatif kepada rakan sekerja yang lain.</p>', NULL, NULL, '2024-11-27 16:23:06', '2024-11-27 16:23:06', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2072, 633, 1, '<p>Tidak dapat menyiapkan tugasan mengikut masa yang ditetapkan dan selalu dibuat semula oleh rakan sekerja yang lain dan menyebabkan kelewatan.<br /><br /><em>Contoh: Kerja yang sepatutnya boleh disiapkan dalam sehari tetapi dia selalu tidak hadir bekerja dan kerjanya perlu disambung / dibuat semula oleh rakan sekerja yang lain dan menyebabkan kelewatan.</em></p>', NULL, NULL, '2024-11-27 16:23:39', '2024-11-27 16:23:39', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2073, 633, 2, '<p>Selalu mengambil masa yang panjang untuk menyiapkan kerja walaupun bimbingan sudah diberi.<br /><br /><em>Contoh: Kerja yang sepatutnya boleh disiapkan dalam sehari tetapi dia mengambil masa yang panjang walaupun bimbingan sudah diberi.</em></p>', NULL, NULL, '2024-11-27 16:23:48', '2024-11-27 16:23:48', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2074, 633, 3, '<p>Tugasan biasanya dapat disiapkan dengan sedikit bimbingan dan siap dalam masa yang ditetapkan mahupun lebih awal dan hasil kerja yang masih boleh diterima.<br /><br /><em>Contoh: Boleh menghasilkan kerja dalam masa yang ditetapkan tetapi masih perlu dalam pengawasan/bimbingan.</em></p>', NULL, NULL, '2024-11-27 16:24:20', '2024-11-27 16:24:20', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2075, 633, 4, '<p>Tugasan sentiasa disiapkan tanpa bimbingan dan mengikut jadual mahupun lebih awal dan hasil kerja yang agar memuaskan.<br /><br /><em>Contoh: Boleh menghasilkan kerja dalam masa yang pendek dan tanpa sebarang pengawasan/bimbingan seperti dia cuma perlu 5 jam untuk menghasilkan kerja yang dijangka siap dalam sehari dan dia boleh menghasilkan lebih dalam satu hari.</em></p>', NULL, NULL, '2024-11-27 16:24:30', '2024-11-27 16:24:30', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2076, 633, 5, '<p>Mengutamakan masa dan pantas dalam menyiapkan tugasan yang diberi dan hasil kerja sangat bagus dan boleh diharapkan.<br /><br /><em>Contoh:Boleh membuat apa kerja yang dirancang dan menepati masa yang ditetapkan atau lebih awal tanpa pengawasan/bimbingan. Individu yang teliti dan prihatin dan menguasa masa dan memberi hasil kerja yang sangat bagus dan halus.</em></p>', NULL, NULL, '2024-11-27 16:24:39', '2024-11-27 16:24:39', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2077, 634, 1, '<p>Suka menolak tanggungjawab kerja dan berpura-pura/berdiam diri walaupun tahu apa cara untuk membuat kerja/menyelesaikan masalah.<br /><br /><em>Contoh: Langsung tidak bergerak dan pakai duduk dan tunggu sahaja walaupun sudah diberi penjelasan dalam pelan kerja.</em></p>', NULL, NULL, '2024-11-27 16:25:00', '2024-11-27 16:25:00', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2078, 634, 2, '<p>Kadangkala menolak tanggungjawab kerja dan berpura-pura/berdiam diri walaupun tahu apa cara untuk membuat kerja/menyelesaikan masalah.<br /><br /><em>Contoh: Tidak berusaha untuk belajar dan memahami pembacaan pelan kerja dan ukuran serta memerlukan seseorang mengawasi di tepi dan selalu memberi penjelasan boleh baru dapat menghasilkan kerja yang ditugaskan.</em></p>', NULL, NULL, '2024-11-27 16:25:09', '2024-11-27 16:25:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2079, 634, 3, '<p>Sudah faham dan boleh terus bertindak/bergerak ke atas kerja yang telah diselesaikan.&nbsp;<br /><br /><em>Contoh: Sudah tahu membuat kerja/menyelesaikan masalah dan tidak menolak tanggungjawab.</em></p>', NULL, NULL, '2024-11-27 16:25:24', '2024-11-27 16:25:24', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2080, 634, 4, '<p>Sudah faham dan boleh bertindak cepat ke atas semua tugasan serta tidak perlu pengawasan/bimbingan dan akan lapor balik apabila kerja telah siap.<br /><br /><em>Contoh: Bertanggungjawab dan tidak berpura-pura atau berdiam diri dalam membuat kerja/menyelesaikan masalah dan tidak perlu pengawasan/bimbingan dan akan bertindak/bergerak ke atas kerja yang ditugaskan serta lapor balik apabila kerja telah siap.</em></p>', NULL, NULL, '2024-11-27 16:25:34', '2024-11-27 16:25:34', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2081, 634, 5, '<p>Sudah faham dan boleh bertindak cepat ke atas semua tugasan serta tidak perlu pengawasan/bimbingan dan akan lapor balik apabila kerja telah siap. Selain itu, dapat memberi nasihat kepada rakan sekerja yang lain supaya cepat bertindak dalam kerja.<br /><br /><em>Contoh: Bertanggungjawab dan tidak berpura-pura atau berdiam diri dalam membuat kerja/menyelesaikan masalah dan tidak perlu pengawasan/bimbingan dan akan bertindak/bergerak ke atas kerja yang ditugaskan serta lapor balik apabila kerja telah siap. Selain itu, juga memotivasikan rakan sekerja supaya tidak berpura-pura/berdiam diri dalam &nbsp;membuat kerja/menyelesaikan masalah.</em></p>', NULL, NULL, '2024-11-27 16:25:45', '2024-11-27 16:25:45', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2082, 635, 1, '<p>Tidak membuat kerja secara sistematik dan tidak tahu membezakan kepentingan kerja.<br /><br /><em>Contoh: Tidak tahu membezakan kepentingan kerja dan tidak buat perancangan kerja.</em></p>', NULL, NULL, '2024-11-27 16:26:43', '2024-11-27 16:26:43', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2083, 635, 2, '<p>Kadangkala ada membuat kerja secara sistematik dan kadangkala tahu membezakan kepentingan kerja tetapi keadaan tidak ketara.<br /><br /><em>Contoh: Kadangkala tahu membezakan kepentingan kerja dan buat perancangan kerja tetapi tidak selalu dan ikut mood sendiri.</em></p>', NULL, NULL, '2024-11-27 16:26:53', '2024-11-27 16:26:53', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2084, 635, 3, '<p>Tidak perlu seseorang mengawasi di tepi dan tahu membuat kerja secara sistematik dan tahu membezakan kepentingan kerja dengan penjelasan yang ringkas sahaja.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan memerlukan penjelasan kerja yang ringkas sahaja.</em></p>', NULL, NULL, '2024-11-27 16:27:01', '2024-11-27 16:27:01', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2085, 635, 4, '<p>Hanya memerlukan penjelasan yang ringkas dan tahu membuat kerja secara sistematik dan tahu membezakan kepentingan kerja. Berhati-hati dan tiada kesilapan dalam kerja yang dihasilkan.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan hanya memerlukan penjelasan kerja yang ringkas sahaja dan memberi tumpuan dalam kerja dan mengeluarkan hasil kerja yang baik.</em></p>', NULL, NULL, '2024-11-27 16:27:15', '2024-11-27 16:27:15', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2086, 635, 5, '<p>Hanya memerlukan penjelasan yang sangat ringkas sahaja untuk membuat kerja secara sistematik dan tahu membezakan kepentingan kerja dan dapat memberi tunjuk ajar kepada rakan sekerja.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan hanya memerlukan penjelasan kerja yang ringkas sahaja dan memberi tumpuan dalam kerja dan mengeluarkan hasil kerja yang baik dan turut memberi tunjuk ajar kepada rakan sekerja.</em></p>', NULL, NULL, '2024-11-27 17:18:53', '2024-11-27 17:18:53', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2087, 636, 1, '<p>Hasil kerja yang tidak boleh diterima dan selalu membuat kesilapan.<br /><br /><em>Contoh: Tidak menumpu perhatian semasa bekerja dan selalu membuat kesilapan yang sama. Tidak pernah berubah walaupun &nbsp;sudah diberi bimbingan/teguran seperti selalu mengulangi kesilapan yang sama walaupun sudah banyak kali memasang mesin yang sama model.</em></p>', NULL, NULL, '2024-11-27 17:21:53', '2024-11-27 17:21:53', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2088, 636, 2, '<p>Cuai dan mengakibatkan kesilapan kerja.<br /><br /><em>Contoh: Kadangkala cuai semasa bekerja dan mengakibatkan kesilapan kerja kerana tindakan yang lambat untuk berubah setelah diberi bimbingan/teguran.</em></p>', NULL, NULL, '2024-11-27 17:22:02', '2024-11-27 17:22:02', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2089, 636, 3, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan meminimumkan tahap kesilapan kepada yang terendah.<br /><br /><em>Contoh: Kadangkala ada membuat kesilapan tetapi mengambil tindakan yang cepat untuk berubah setelah diberi bimbingan/teguran.</em></p>', NULL, NULL, '2024-11-27 17:22:11', '2024-11-27 17:22:11', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2090, 636, 4, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan apa-apa kesilapan dalam kerja harian.<br /><br /><em>Contoh: Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan. Selain itu, juga berinisiatif untuk menjaga barangan/bahan dan tidak membazir.</em></p>', NULL, NULL, '2024-11-27 17:22:25', '2024-11-27 17:22:25', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2091, 636, 5, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan kerja dan berinisiatif untuk memberi pendapat dan memperbaiki cara kerja yang lebih baik untuk meminimumkan tahap kesilapan kerja.<br /><br /><em>Contoh: Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan dan berinisiatif untuk memberi pendapat dan memperbaiki cara kerja untuk meminimumkan tahap kesilapan kerja seperti berinisiatif untuk mengetahui masalah semasa pemasangan mesin dan turut memberi pendapat untuk memperbaiki cara kerja/menyelesaikan masalah.</em></p>', NULL, NULL, '2024-11-27 17:22:35', '2024-11-27 17:22:35', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2092, 637, 1, '<p>Langsung tidak memahami permintaan kualiti kerja dan tidak memberi perhatian kepada kerja yang dilakukan.<br /><br /><em>Contoh: Langsung tidak memahami permintaan kualiti kerja dan tidak memberi perhatian terhadap semua kerja yang dilakukan seperti membuat pemasangan Control Panel tetapi langsung tidak mengikut diagram yang diberi.</em></p>', NULL, NULL, '2024-11-27 17:23:23', '2024-11-27 17:23:23', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2093, 637, 2, '<p>Kadangkala tidak faham spesifikasi kerja yang diberi dan tidak berinisiatif mengambil langkah untuk mengetahui untuk menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Tidak berinisiatif untuk bertanya/kurang bertanya apabila tidak tahu semasa memasang Control Panel dan pasang ikut sendiri dan tidak ikut cara kerja yang betul.</em></p>', NULL, NULL, '2024-11-27 17:23:32', '2024-11-27 17:23:32', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2094, 637, 3, '<p>Memahami permintaan kualiti kerja dan dapat menghasilkan kerja yang berkualiti secara individu tanpa pengawasan pegawai atasan tetapi tidak mengambil perhatian dan abaikan kerja yang remeh temeh serta tidak mengambil perhatian terhadap kekemasan hasil kerja.<br /><br /><em>Contoh: Tahu pasang Control Panel tetapi tidak terfikir tentang kekemasan. Wayar sudah ditarik dengan betul tetapi tidak diikat dengan cable tie/tidak tersusun/tidak label semasa membuat pemasangan.</em></p>', NULL, NULL, '2024-11-27 17:23:44', '2024-11-27 17:23:44', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2095, 637, 4, '<p>Faham tentang kualiti dan dapat menghasilkan kerja yang berkualiti dan memenuhi kehendak syarikat dan dapat memastikan kerja yang dihasilkan tidak bermasalah.<br /><br /><em>Contoh: Faham tentang kualiti kerja dan ikut semua spesifikasi yang diminta. Boleh berfikir dan nampak (meramalkan) ke hadapan dan memastikan kerja yang dihasilkan tidak bermasalah seperti tahu pasang Control Panel dan semua litar boleh berfungsi dengan baik dan pemasangan yang kemas dan melaporkan keadaan kepada Leader/Supervisor apabila litar tidak berfungsi/bernyala.</em></p>', NULL, NULL, '2024-11-27 17:23:53', '2024-11-27 17:23:53', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2096, 637, 5, '<p>Sangat faham tentang kualiti kerja dan dapat menghasilkan kerja yang berkualiti dan memenuhi kehendak syarikat dan dapat memastikan kerja yang dihasilkan tidak bermasalah serta turut memberi tunjuk ajar kepada rakan kerja yang lain.&nbsp;<br /><br /><em>Contoh: Sangat faham tentang kualiti kerja dan ikut semua spesifikasi yang diminta. Boleh berfikir dan nampak (meramalkan) ke hadapan dan memastikan kerja yang dihasilkan tidak bermasalah. Selain itu, juga dapat memberi tunjuk ajar kepada rakan sekerja yang lain seperti tahu pasang Control Panel dan semua litar boleh berfungsi dengan baik dan pemasangan yang kemas dan melaporkan keadaan kepada Leader/Supervisor apabila litar tidak berfungsi/bernyala. Selain itu, dia juga memberi tunjuk ajar kepada rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-27 17:24:06', '2024-11-27 17:24:06', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2097, 638, 1, '<p>Sentiasa membazirkan/merosakkan sumber syarikat.<br /><br /><em>Contoh: Tidak pernah berhati-hati dalam spesifikasi kerja yang diberi dan sentiasa mengakibatkan pembaziran bahan.</em></p>', NULL, NULL, '2024-11-27 17:24:31', '2024-11-27 17:24:31', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2098, 638, 2, '<p>Ada bersikap mahu menjimatkan sumber syarikat tetapi kadangkala menyebabkan pembaziran di atas kecuaiannya.<br /><br /><em>Contoh: Cuai dalam pembacaan spesifikasi kerja yang diberi dan silap ambil bahan dan menyebabkan kesilapan dan membazirkan bahan serta perlu &ldquo;rework&rdquo;.</em></p>', NULL, NULL, '2024-11-27 17:32:17', '2024-11-27 17:32:17', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2099, 638, 3, '<p>Berhati-hati semasa bekerja dan menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dan memastikan betul supaya tidak berlaku kesilapan yang mengakibatkan pembaziran bahan dan buang masa.</em></p>', NULL, NULL, '2024-11-27 17:33:13', '2024-11-27 17:33:13', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2100, 638, 4, '<p>Berhati-hati semasa bekerja dan berinisiatif menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya. Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dengan pelan kerja dan memastikan semua barang yang ambil adalah betul. Ada pemikiran tidak membazir seperti dalam menghasilkan sesuatu barang yang sangat kecil, dia akan cari scrap dahulu dan tidak guna bahan yang baru atau bahan yang besar.Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan.</em></p>', NULL, NULL, '2024-11-27 17:33:16', '2024-11-27 17:33:29', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2101, 638, 5, '<p>Berhati-hati semasa bekerja dan berinisiatif menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya. Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan dan juga menyedarkan dan membetulkan kesilapan rakan sekerja yang lain.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dengan pelan kerja dan memastikan semua barang yang ambil adalah betul. Ada pemikiran tidak membazir seperti dalam menghasilkan sesuatu barang yang sangat kecil, dia akan cari scrap dahulu dan tidak guna bahan yang baru atau bahan yang besar.Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan dan menyedarkan dan membetulkan kesilapan rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-27 17:33:40', '2024-11-27 17:33:40', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2102, 639, 1, '<p>Pengetahuan atau kemahiran adalah terhad dan tidak dapat menyelesaikan tugasan dan menggunakan masa yang panjang untuk mempelajari pengetahuan dan cara kerja yang agak senang.<br /><br /><em>Contoh: Tidak ada pengetahuan dan kemahiran kerja dan menggunakan masa yang panjang untuk mempelajari cara kerja yang senang walaupun bimbingan telah diberi seperti membuat kerja kimpalan yang paling senang iaitu mengimpal besi dalam kedudukan rata.</em></p>', NULL, NULL, '2024-11-27 17:35:45', '2024-11-27 17:35:45', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2103, 639, 2, '<p>Kurang pengetahuan atau kemahiran yang cukup untuk mengendalikan tugasan.<br /><br /><em>Contoh: Hasil kimpalan yang teruk dan bimbingan masih diperlukan walaupun diminta menghasilkan kerja kimpalan yang agak senang seperti mengimpal besi dalam kedudukan rata dan mendatar.</em></p>', NULL, NULL, '2024-11-27 17:39:01', '2024-11-27 17:39:01', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2104, 639, 3, '<p>Mempunyai pengetahuan dan kemahiran untuk mengendalikan tugasan dan mempunyai sikap mahu belajar dan mempelajari pengetahuan kerja yang baru dalam masa yang singkat dan mengimplikasikan dalam kerja harian.<br /><br /><em>Contoh: Ada pengetahuan dan kemahiran kimpalan tetapi tidak dapat meneruskan kerja apabila menghadapi kerja yang tidak biasa dan memerlukan bimbingan seperti: boleh mengimpal besi yang nipis tetapi tidak apabila diminta mengimpal besi yang lagi nipis / boleh mengimpal dalam kedudukan rata, mendatar dan menegak tetapi tidak apabila dalam keadaan overhead atau dalam keadaan 45 darjah.</em></p>', NULL, NULL, '2024-11-27 17:39:11', '2024-11-27 17:39:11', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2105, 639, 4, '<p>Boleh menguasai pengetahuan dan kemahiran untuk mengendalikan tugasan dan pencapaian yang agak memuaskan dan dapat menggunakan pengetahuannya untuk meningkatkan kualiti kerja.<br /><br /><em>Contoh: Mempunyai pengetahuan dan kemahiran yang luas serta jelas dengan semua keperluan/permintaan kerja seperti memilih kaedah yang bersesuaian untuk menghasilkan kerja dan tahu mengawal had api untuk mencegah hasil kerja dari kerosakan.</em></p>', NULL, NULL, '2024-11-27 17:39:20', '2024-11-27 17:39:20', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2106, 639, 5, '<p>Menguasai pengetahuan dan kemahiran untuk mengendalikan tugasan dan boleh menggabungkan pengetahuan untuk meningkatkan kualiti kerja serta mencari cara kerja baru untuk menyelesaikan masalah kerja dengan pengetahuannya.<br /><br /><em>Contoh: Mempunyai pengetahuan dan kemahiran yang luas serta jelas dengan semua keperluan/permintaan kerja dan berinisiatif memberi cadangan untuk menyelesaikan masalah kerja.&nbsp;</em></p>', NULL, NULL, '2024-11-27 17:39:34', '2024-11-27 17:39:34', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2107, 640, 1, '<p>Tidak pernah mengemas dan membersihkan tempat kerja sendiri dan sentiasa mengotorkan tempat kerja sendiri dan rakan sekerja yang lain.<br /><br /><em>Contoh: Tidak pernah terfikir kebaikan bersama dan terus membuang sisa kerja ke lantai dan menganggap ini kerja cleaner untuk membersihkan.</em></p>', NULL, NULL, '2024-11-27 17:42:08', '2024-11-27 17:42:08', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2108, 640, 2, '<p>Kadangkala ada mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya tidak kemas.<br /><br /><em>Contoh: Tidak selalu mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya tidak kemas seperti kadangkala ada membersihkan tempat kerja dan kadangkala tidak.</em></p>', NULL, NULL, '2024-11-29 11:48:43', '2024-11-29 11:48:43', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2109, 640, 3, '<p>Berinisiatif untuk mengemas dan membersihkan tempat kerja dan kebanyakan masa tempat kerjanya adalah kemas dan bersih.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai.</em></p>', NULL, NULL, '2024-11-29 11:48:53', '2024-11-29 11:48:53', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2110, 640, 4, '<p>Selalu mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya kemas dan selalu menolong membersihkan kawasan bahagiannya (division) dan kilang.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai serta tolong membersihkan kawasan yang lain.</em></p>', NULL, NULL, '2024-11-29 11:49:05', '2024-11-29 11:49:05', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2111, 640, 5, '<p>Selalu mengemas dan membersihkan tempat kerja dan tempat kerjanya kelihatan kemas dan bersih. Juga selalu menjaga kebersihan seluruh kawasan kilang dan dapat menegur rakan sekerja untuk menjaga kebersihan kilang.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai serta tolong menjaga kebersihan kawasan yang lain dan menegur rakan sekerja yang tidak menjaga kebersihan kilang.</em></p>', NULL, NULL, '2024-11-29 11:55:06', '2024-11-29 11:55:06', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2112, 641, 1, '<p>Tidak menjaga peralatan dan kemudahan syarikat.<br /><br /><em>Contoh: Tidak menjaga peralatan dan kemudahan syarikat seperti tidak menjaga forklift dan tidak pernah meletakkkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-29 11:55:32', '2024-11-29 11:55:32', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2113, 641, 2, '<p>Kadangkala bersikap cuai dalam mengendali peralatan dan kemudahan syarikat dan mengakibatkan kerosakan.<br /><br /><em>Contoh: Tidak selalu menjaga peralatan dan kemudahan syarikat dan mengakibatkan kerosakan seperti forklift terus jalan setelah enjin dihidupkan. Tidak mengambil berat tentang barang yang diangkat dan masuk ke ruang yang kecil. Selalu tidak meletakkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-29 11:55:42', '2024-11-29 11:55:42', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2114, 641, 3, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat dengan cara yang betul.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-11-29 11:55:53', '2024-11-29 11:55:53', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2115, 641, 4, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat demi kebaikan bersama. Selain itu, &nbsp;melaporkan kepada pihak atasan bila nampak rakan sekerja salahguna dan memberi cara penyelesaian yang bermanfaat.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna dan melapor jika ada kerosakan dan memberi cadangan untuk memperbaiki cara penggunaan dan penjagaan alatan.</em></p>', NULL, NULL, '2024-11-29 11:56:03', '2024-11-29 11:56:03', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2116, 641, 5, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat demi kebaikan bersama. Selain itu, &nbsp;melaporkan kepada pihak atasan bila nampak pekerja salahguna dan memberi cara penyelesaian yang bermanfaat. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna dan melapor jika ada kerosakan dan memberi cadangan untuk memperbaiki cara penggunaan dan penjagaan alatan.Selain itu, akan menyedarkan dan menasihati rakan sekerja yang tidak menjaga forklift semasa mengguna.</em></p>', NULL, NULL, '2024-11-29 11:56:21', '2024-11-29 11:56:21', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2117, 642, 1, '<p>Tidak mengutamakan keselamatan semasa bekerja.<br /><br /><em>Contoh: Tidak mengutamakan keselamatan semasa bekerja seperti tidak memakai PPE semasa bekerja.</em></p>', NULL, NULL, '2024-11-29 11:56:42', '2024-11-29 11:56:42', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2118, 642, 2, '<p>Ada sikap mengutamakan keselamatan tetapi kadangkala tidak.<br /><br /><em>Contoh: Ada memakai PPE semasa bekerja tetapi kadangkala tidak.</em></p>', NULL, NULL, '2024-11-29 11:56:52', '2024-11-29 11:56:52', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2119, 642, 3, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja.</em></p>', NULL, NULL, '2024-11-29 11:57:01', '2024-11-29 11:57:01', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2120, 642, 4, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan.</em></p>', NULL, NULL, '2024-11-29 11:57:10', '2024-11-29 11:57:10', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2121, 642, 5, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja dan melaporkan kepada pihak atasan serta turut memberi cara atau cara penyelesaian yang bermanfaat.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan serta turut memberi cara atau cara penyelesaian yang bermanfaat.</em></p>', NULL, NULL, '2024-11-29 11:57:20', '2024-11-29 11:57:20', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2122, 643, 1, '<p>Menerima tugasan tetapi tidak memikul tanggungjawab kerja dan tidak dapat bekerja di bawah tekanan.<br /><br /><em>Contoh: Dia terima kerja yang diberi tetapi sentiasa bersembang dengan rakan sekerja dan tidak buat kerja sehingga tidak nampak hasil kerja.</em></p>', NULL, NULL, '2024-11-29 12:03:16', '2024-11-29 12:03:16', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2123, 643, 2, '<p>Boleh menerima dan memikul tanggungjawab dan cuba untuk bekerja di bawah tekanan tetapi kadangkala tidak dapat menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Dia boleh buat kerja dan cuba elakkan diri dari tidak masuk kerja/tidak memberi alasan untuk bercuti tetapi kadangkala masih perlu dalam bimbingan.</em></p>', NULL, NULL, '2024-11-29 12:04:14', '2024-11-29 12:04:14', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2124, 643, 3, '<p>Boleh menerima dan memikul tanggungjawab dan dapat menghabiskan setiap kerja yang diamanahkan dengan baik di bawah tekanan dan melaporkan kerja yang telah dilakukan kepada pegawai atasan.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia masih menepati target dan ikut piawai kerja yang ditetapkan oleh syarikat. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia juga akan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-29 12:04:23', '2024-11-29 12:04:23', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2125, 643, 4, '<p>Rela menerima dan memikul tanggungjawab dan sentiasa dapat menghasilkan kerja yang berkualiti di bawah tekanan dan dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang dilakukan kepada pegawai atasan.Boleh buat kerja lebih masa sehingga kerja siap.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia akan menawarkan diri secara sukarela untuk kerja tersebut serta menepati target dan ikut piawai kerja yang ditetapkan oleh syarikat. Boleh buat kerja lebih masa sehingga kerja siap. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-29 12:04:32', '2024-11-29 12:04:32', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2126, 643, 5, '<p>Rela menerima dan memikul tanggungjawab serta tahu kepentingan dan deadline kerja. Dapat memanggil rakan sekerja untuk menyiapkan kerja bersama. Sentiasa dapat menghasilkan kerja yang berkualiti di bawah tekanan dan dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang dilakukan kepada pegawai atasan.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia tahu kepentingan dan deadline kerja tersebut serta dapat memanggil rakan sekerja untuk menyiapkan kerja bersama. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-29 12:05:12', '2024-11-29 12:05:12', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2127, 644, 1, '<p>Tidak rela mengaku kesilapan dan suka menolak tanggungjawab kepada orang lain.<br /><br /><em>Contoh: Telah melakukan kesilapan seperti tidak mengikuti spesifikasi kerja yang diberi oleh Leader / tidak tanya Leader apabila tidak faham / tanya rakan sekerja yang tidak dipertanggungjawabkan dan tidak pernah mengakui kesilapan apabila ditegur oleh Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-29 12:16:56', '2024-11-29 12:16:56', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2128, 644, 2, '<p>Kadangkala tidak rela mengaku kesilapan dan suka membuat perbandingan diri dengan orang lain dalam kesilapan yang telah dibuat.<br /><br /><em>Contoh: Telah melakukan kesilapan seperti tidak mengikuti spesifikasi kerja yang diberi oleh Leader / tidak tanya Leader apabila tidak faham / tanya rakan sekerja yang tidak dipertanggungjawabkan dan kadangkala tidak mengakui kesilapan apabila ditegur oleh Leader/Supervisor malah menyatakan Leader/Supervisor ada prasangka terhadap dia.</em></p>', NULL, NULL, '2024-11-29 12:17:07', '2024-11-29 12:17:07', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2129, 644, 3, '<p>Mengaku kesilapan dan tidak menolak tanggungjawab kepada orang lain.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan. Dia terima dan mengakui kesilapan.</em></p>', NULL, NULL, '2024-11-29 12:17:18', '2024-11-29 12:17:18', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2130, 644, 4, '<p>Tidak melarikan diri dari tanggungjawab dan terus berjumpa dengan pihak atasan untuk mengakui kesilapan dan berinisiatif untuk memperbaiki kesilapan yang telah dilakukan.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan. Dia tidak melarikan diri dari tanggungjawab dan terus berjumpa dengan Leader/Supervisor dan mengakui kesilapan. Selain itu, dia juga memberi cadangan dan sama-sama memperbaiki kesilapan yang telah dilakukan.</em></p>', NULL, NULL, '2024-11-29 12:17:27', '2024-11-29 12:17:27', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2131, 644, 5, '<p>Berani mengaku kesilapan dan tidak menolak tanggungjawab dan memastikan kesilapan tidak berlaku lagi. Berinisiatif untuk memperbetulkan kesilapan dan dapat memberi cadangan yang bermanfaat untuk mengelakkan kesilapan berlaku lagi.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan yang agak besar. Dia berani mengakui kesilapan dan terus berjumpa dengan Leader/Supervisor untuk mengakui kesilapan. Dia mengambil pengalaman tersebut sebagai satu pengajaran dan tidak mengulangi kesilapan tersebut lagi. Selain itu, dia &nbsp;memberi cadangan dan sama-sama memperbaiki kesilapan yang telah dilakukan serta memberi cadangan yang bermanfaat untuk mengelakkan kesilapan berlaku lagi.</em></p>', NULL, NULL, '2024-11-29 12:17:39', '2024-11-29 12:17:39', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2132, 645, 1, '<p>Membuat kerja alah kadar dan setakat membuat kerja sahaja dan tidak menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Tidak menunjukkan sikap ingin belajar dan tidak menumpukan perhatian semasa bekerja seperti dia boleh mengambil masa yang panjang untuk memasang beberapa nut pada mesin.</em></p>', NULL, NULL, '2024-11-29 12:17:57', '2024-11-29 12:17:57', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2133, 645, 2, '<p>Boleh membuat kerja tetapi mudah dipengaruhi orang lain dan kadangkala tidak dapat menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Dia boleh pasang nut pada mesin tetapi mudah dipengaruhi oleh rakan sekerja yang lain seperti dia akan melambatkan proses kerjanya dan sambil kerja sambil bersembang apabila ada rakan sekerja yang bersembang dengannya semasa bekerja.</em></p>', NULL, NULL, '2024-11-29 12:18:06', '2024-11-29 12:18:06', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2134, 645, 3, '<p>Lebih agresif dan sikap kerja juga serius dan dapat menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak mengangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja.</em></p>', NULL, NULL, '2024-11-29 12:18:16', '2024-11-29 12:18:16', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2135, 645, 4, '<p>Bersemangat kerja dan menumpukan perhatian sepenuhnya dalam kerja. Sentiasa mengutamakan kualiti kerja dan menghasilkan kerja yang halus dan teliti dan tidak melakukan kesilapan.<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak menggangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja. Dia sentiasa mengutamakan kualiti kerja dan memastikan nut yang dipasang itu betul dan kemas.</em></p>', NULL, NULL, '2024-11-29 12:18:27', '2024-11-29 12:18:27', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2136, 645, 5, '<p>Matlamat untuk berjaya sangat jelas. Menumpukan perhatian sepenuhnya dalam kerja. Sentiasa mengutamakan kualiti kerja dan menghasilkan kerja yang halus dan teliti dan tidak melakukan kesilapan. Selain itu turut memberi cadangan dan cara kerja untuk memastikan kerja berkualiti dihasilkan setiap kali.&nbsp;<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak menggangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja. Dia sentiasa mengutamakan kualiti kerja dan memastikan nut yang dipasang itu betul dan kemas. Selain itu, dia juga akan memberi cadangan untuk memastikan kerja berkualiti dapat dihasilkan.</em></p>', NULL, NULL, '2024-11-29 12:18:36', '2024-11-29 12:18:36', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2137, 646, 1, '<p>Langsung tidak mahu memahami dan menerima peraturan dan polisi syarikat dan sentiasa membuat aduan terhadap dasar syarikat.<br /><br /><em>Contoh: Selalu tidak menutup lampu setelah mengguna tandas dan membuat aduan apabila pihak syarikat mengambil tindakan.</em></p>', NULL, NULL, '2024-11-29 12:19:47', '2024-11-29 12:19:47', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2138, 646, 2, '<p>Kadangkala sahaja mahu menerima dan mematuhi peraturan dan polisi syarikat.<br /><br /><em>Contoh: Kadangkala ada menutup lampu setelah mengguna tandas kadangkala tidak.</em></p>', NULL, NULL, '2024-11-29 12:19:56', '2024-11-29 12:19:56', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2139, 646, 3, '<p>Menerima dan mematuhi setiap peraturan dan polisi syarikat.<br /><br /><em>Contoh: Setiap kali akan menutup lampu setelah mengguna tandas.</em></p>', NULL, NULL, '2024-11-29 12:20:33', '2024-11-29 12:20:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2140, 646, 4, '<p>Tidak melanggar peraturan dan sentiasa dapat menasihatkan rakan sekerja untuk menerima dan mematuhi peraturan dan polisi syarikat untuk kebaikan bersama.<br /><br /><em>Contoh: Sentiasa menutup lampu setelah mengguna tandas dan &nbsp;menasihati dan menerang kepada rakan sekerja yang tidak mematuhi peraturan.</em></p>', NULL, NULL, '2024-11-29 12:20:43', '2024-11-29 12:20:43', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2141, 646, 5, '<p>Memahami dan menerima setiap peraturan dan polisi syarikat dan sentiasa menasihatkan rakan sekerja yang melanggar peraturan serta melaporkan masalah disiplin kepada pegawai atasan untuk kebaikan bersama.<br /><br /><em>Contoh: &nbsp;Sentiasa menutup lampu setelah mengguna tandas dan &nbsp;menasihati dan menerang kepada rakan sekerja yang tidak mematuhi peraturan. Selain itu, juga akan melaporkan nama pekerja yang tidak menutup lampu setelah mengguna tandas.</em></p>', NULL, NULL, '2024-11-29 12:20:54', '2024-11-29 12:20:54', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2142, 647, 1, '<p>Selalu tidak tepat masuk kerja dan menunjukkan kedatangan yang tidak baik.<br /><br /><em>Contoh: Masih berada di tempat berehat semasa siren berbunyi dan jalan perlahan ke tempat kerja.</em></p>', NULL, NULL, '2024-11-29 12:21:33', '2024-11-29 12:21:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2143, 647, 2, '<p>Kadangkala ada masuk kerja pada masa yang ditetapkan tetapi keadaan tidak ketara.<br /><br /><em>Contoh: Kadangkala ada tepat masuk kerja semasa siren berbunyi tetapi kebanyakan masa tidak masuk kerja pada masa yang tepat.</em></p>', NULL, NULL, '2024-11-29 12:21:42', '2024-11-29 12:21:42', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2144, 647, 3, '<p>Kebanyakan masa masuk kerja pada masa yang ditetapkan tetapi kadangkala ada lewat juga.<br /><br /><em>Contoh: Kebanyakan masa masuk kerja semasa siren berbunyi tetapi sekali kala masih lewat masuk kerja.</em></p>', NULL, NULL, '2024-11-29 12:21:51', '2024-11-29 12:21:51', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2145, 647, 4, '<p>Mementingkan ketepatan masa masuk kerja dan masuk kerja tepat pada masa atau lebih awal.<br /><br /><em>Contoh: Sentiasa masa masuk kerja sebelum siren berbunyi atau lebih awal.</em></p>', NULL, NULL, '2024-11-29 12:22:00', '2024-11-29 12:22:00', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2146, 647, 5, '<p>Mementingkan ketepatan masa masuk kerja dan masuk kerja tepat pada masa atau lebih awal serta memberi nasihat kepada rakan sekerja yang lewat.<br /><br /><em>Contoh: Sentiasa masa masuk kerja sebelum siren berbunyi atau lebih awal serta memberi nasihat kepada rakan sekerja yang lewat.</em></p>', NULL, NULL, '2024-11-29 12:22:10', '2024-11-29 12:22:10', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2147, 648, 1, '<p>Disiplin diri yang tidak memuaskan dan sering meninggalkan tempat kerja dengan berkeliaran tanpa tujuan dan sering membazirkan masa serta curi tulang.<br /><br /><em>Contoh: Sering meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja (banyak kali sehari) dan mengambil masa yang panjang dalam tandas serta membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-29 12:22:30', '2024-11-29 12:22:30', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2148, 648, 2, '<p>Kadangkala membazirkan masa dan curi tulang serta meninggalkan tempat kerja dengan berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Kadangkala meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja (banyak kali sehari) dan mengambil masa yang panjang dalam tandas serta membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-29 12:22:39', '2024-11-29 12:22:39', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2149, 648, 3, '<p>Tidak membazirkan masa dan ringan tulang serta menumpukan perhatian semasa bekerja. Tidak meninggalkan tempat kerja dengan berkeliaran tanpa tujuan.<br /><br /><em>Contoh: Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-29 12:22:48', '2024-11-29 12:22:48', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2150, 648, 4, '<p>Teladan yang baik dan tumpuan perhatian sepenuhnya semasa bekerja. Tidak berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Seorang teladan yang baik dan memberi tumpuan sepenuhnya semasa bekerja. Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-11-29 12:23:01', '2024-11-29 12:23:01', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2151, 648, 5, '<p>Teladan yang baik dan tumpuan perhatian sepenuhnya semasa bekerja dan juga selalu memberi nasihat kepada rakan sekerja supaya melahirkan keadaan kerja yang lebih agresif. Tidak berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Seorang teladan yang baik dan memberi tumpuan sepenuhnya semasa bekerja. Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja. Selalu memberi nasihat kepada rakan sekerja yang selalu pergi ke tandas sebagai alasan.</em></p>', NULL, NULL, '2024-11-29 12:25:13', '2024-11-29 12:25:13', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2152, 649, 1, '<p>Tidak pernah berada di tempat kerja semasa pembersihan kawasan dijalankan.<br /><br /><em>Contoh: Tidak berada di tempat kerja dan pergi ke tandas semasa pembersihan kawasan dijalankan.</em></p>', NULL, NULL, '2024-11-29 12:26:45', '2024-11-29 12:26:45', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2153, 649, 2, '<p>Memulakan kerja pembersihan kawasan walaupun masa yang ditetapkan belum sampai lagi.<br /><br /><em>Contoh: Memulakan kerja pembersihan kawasan walaupun masa yang ditetapkan belum sampai lagi dan rakan sekerja yang lain masih bekerja lagi.</em></p>', NULL, NULL, '2024-11-29 12:26:55', '2024-11-29 12:26:55', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2154, 649, 3, '<p>Kebanyakan masa membersihkan kawasan production pada masa yang ditetapkan.</p><p>Kadangkala membersihkan kawasan production pada masa yang ditetapkan tetapi keadaan tidak ketara.</p><p><br />\nContoh: Kadangkala ada berada di production semasa pembersihan kawasan dijalankan tetapi kebanyakan masa tidak nampak orang.</p>', NULL, NULL, '2024-11-29 12:27:05', '2024-11-29 12:27:05', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2155, 649, 4, '<p>Sentiasa mengutamakan dan membersihkan kawasan production pada masa yang ditetapkan.<br /><br /><em>Contoh: Sentiasa membersihkan kawasan production pada masa yang ditetapkan.</em></p>', NULL, NULL, '2024-11-29 12:27:16', '2024-11-29 12:27:16', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2156, 649, 5, '<p>Mengutamakan dan membersihkan kawasan production pada masa yang ditetapkan serta memberi nasihat kepada rakan sekerja yang tidak berbuat demikian.<br /><br /><em>Contoh: Sentiasa membersihkan kawasan production pada masa yang ditetapkan dan memberi nasihat kepada rakan sekerja yang tidak berbuat demikian.</em></p>', NULL, NULL, '2024-11-29 12:27:26', '2024-11-29 12:27:26', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2157, 650, 1, '<p>Hanya menghormati pegawai atasan dan tidak bersopan dengan rakan sekerja.<br /><br /><em>Contoh: Hanya menghormati Leader/Supervisor atau pangkat kerja yang lebih tinggi tetapi tidak bersopan dengan rakan sekerja yang berpangkat rendah/masih baru.</em></p>', NULL, NULL, '2024-11-29 12:28:45', '2024-11-29 12:28:45', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2158, 650, 2, '<p>Biasanya akan bersopan dan menghormati orang lain tetapi kadangkala beremosi.<br /><br /><em>Contoh: Biasanya bersopan dan menghormati rakan sekerja yang lain tetapi kadangkala beremosi dan lawan cakap.</em></p>', NULL, NULL, '2024-11-29 12:28:55', '2024-11-29 12:28:55', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2159, 650, 3, '<p>Sering bersopan dan menghormati orang lain dan tidak bertindak mengikut perasaan.<br /><br /><em>Contoh: Sering bersopan dan menghormati rakan sekerja lain dan tidak bertindak mengikut perasaan.</em></p>', NULL, NULL, '2024-11-29 12:29:08', '2024-11-29 12:29:08', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2160, 650, 4, '<p>Bersopan dan menghormati orang lain pada setiap masa dan tidak bertindak mengikut perasaan dan berbahasa sopan.<br /><br /><em>Contoh: Bersopan dan setiap masa menghormati rakan sekerja yang lain dan tidak bertindak mengikut perasaan dan berbahasa sopan serta jaga perasaan rakan lain.</em></p>', NULL, NULL, '2024-11-29 12:29:17', '2024-11-29 12:29:17', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2161, 650, 5, '<p>Bersopan dan menghormati orang lain pada setiap masa dan masih bercakap dengan sopan walaupun sendiri telah dipersalahkan dalam proses penyelesaian masalah.<br /><br /><em>Contoh: Bersopan dan setiap masa menghormati rakan sekerja yang lain dan masih bercakap dengan sopan walaupun sendiri telah dipersalahkan dalam proses penyelesaian masalah.</em></p>', NULL, NULL, '2024-11-29 12:29:27', '2024-12-04 11:34:16', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2162, 651, 1, '<p>Memang mengetahui arahan yang diberi mempunyai kesilapan tetapi tidak mendapatkan kepastian kerana berpendapat itu adalah tanggungjawab pegawai atasan.<br /><br /><em>Contoh: Tidak mendapatkan kepastian daripada Leader/Supervisor tentang spesifikasi kerja yang diberi walaupun sudah tahu arahan yang diberi mempunyai kesilapan/tidak jelas dan beranggap itu adalah tanggungjawab Leader/Supervisor dan bukan dia.</em></p>', NULL, NULL, '2024-11-29 12:29:57', '2024-11-29 12:29:57', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2163, 651, 2, '<p>Jarang berinisiatif untuk mendapatkan kepastian daripada pegawai atasan walaupun arahan yang diberi tidak jelas atau silap.<br /><br /><em>Contoh: Menunjukkan sikap sudah tahu tetapi tidak ingin peduli dan tidak mendapatkan kepastian daripada Leader/Supervisor walapun arahan yang diberi ada kesilapan/kurang jelas.</em></p>', NULL, NULL, '2024-11-29 12:30:07', '2024-11-29 12:30:07', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2164, 651, 3, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap tetapi tidak pernah melapor balik kepada pegawai atasan tentang tugasan tersebut.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi ada kesilapan/tidak jelas tetapi tidak pernah melapor balik tugasan tersebut.</em></p>', NULL, NULL, '2024-11-29 12:30:16', '2024-11-29 12:30:16', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2165, 651, 4, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi tidak jelas/silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut.</em></p>', NULL, NULL, '2024-11-29 12:30:26', '2024-11-29 12:30:26', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2166, 651, 5, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut serta memberi pendapat yang bermanfaat.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi tidak jelas/silap dan selalu melapor balik kepada Leader/Supervisor dan turut mengambil bahagian untuk memberi pendapat yang bermanfaat.</em></p>', NULL, NULL, '2024-11-29 12:30:37', '2024-11-29 12:30:37', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2167, 652, 1, '<p>Degil dan berpegang teguh dengan pendapat sendiri dan tidak menuruti arahan pegawai atasan.<br /><br /><em>Contoh: Tidak menerima dan melawan percakapan Leader/Supervisor semasa diberi tugasan.</em></p>', NULL, NULL, '2024-11-29 12:30:55', '2024-11-29 12:30:55', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2168, 652, 2, '<p>Kebanyakan masa akan menuruti arahan pegawai atasan tetapi kadangkala akan beremosi dan meluahkan ketidakpuasan.<br /><br /><em>Contoh: Kebanyakan masa akan menerima tugasan Leader/Supervisor dengan baik tetapi kadangkala tidak.</em></p>', NULL, NULL, '2024-11-29 12:31:05', '2024-11-29 12:31:05', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2169, 652, 3, '<p>Mengambil berat dan menuruti arahan pegawai atasan dan tidak pernah membuat hal sesuka hati.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati dan akan bertanya jika tidak faham.</em></p>', NULL, NULL, '2024-11-29 12:31:14', '2024-11-29 12:31:14', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2170, 652, 4, '<p>Mengambil berat dan menuruti arahan pegawai atasan dan tidak pernah membuat hal sesuka hati. Kadangkala turut memberikan pendapat yang bermanfaat dalan kerja yang diberi.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati dan akan bertanya jika tidak faham. Kadangkala turut memberi cadangan/pandangan dalam kerja yang diberi.</em></p>', NULL, NULL, '2024-11-29 12:31:23', '2024-11-29 12:31:23', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2171, 652, 5, '<p>Bersikap positif dan menuruti semua arahan pegawai atasan, tidak membuat hal malah dapat menyampaikan objektif dan kehendak arahan secara positif kepada semua rakan sekerja.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati. Turut menyampaikan maksud dan kehendak mengikuti arahan Leader/Supervisor secara positif kepada rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-11-29 12:31:33', '2024-11-29 12:31:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2172, 653, 1, '<p>Ego dan tidak sudi berbincang tugasan sesama rakan sekerja dan pegawai atasan, sangat keras kepala dan tidak dapat menerima cadangan orang lain.<br /><br /><em>Contoh: Buat kerja tanpa ikut pelan kerja seperti menebuk drill pada kelajuan yang tinggi dan telah membesarkan lubang 3mm kepada 3.20 mm. Dia tidak dapat menerima apabila diminta buat semula pada kelajuan drill yang rendah.</em></p>', NULL, NULL, '2024-11-29 12:32:06', '2024-11-29 12:32:06', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2173, 653, 2, '<p>Jarang berbincang tugasan sesama rakan sekerja dan pegawai atasan dan tidak begitu rela berkongsi maklumat, kadangkala keras kepala dan tidak dapat menerima cadangan orang lain.<br /><br /><em>Contoh: Dia menunjukkan sikap yang tidak begitu gembira apabila diminta buat semula pada kelajuan drill yang rendah.</em></p>', NULL, NULL, '2024-11-29 12:32:14', '2024-11-29 12:32:14', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2174, 653, 3, '<p>Sudi berbincang dan menerima cadangan rakan sekerja dan pegawai atasan, dapat memberi pertolongan apabila diminta.<br /><br /><em>Contoh: Dia sudi membuat semula pada kelajuan drill yang rendah setelah berbincang dan diminta berubah.</em></p>', NULL, NULL, '2024-11-29 12:32:25', '2024-11-29 12:32:25', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2175, 653, 4, '<p>Sudi berbincang dan berinisiatif memberi pertolongan sesama rakan sekerja dan pegawai atasan dengan tidak berkira kerja. Boleh menerima cadangan orang lain dan tidak berkeras kepala.<br /><br /><em>Contoh: Dia sudi membuat semula pada kelajuan drill yang rendah dan dia turut memberi cadangan untuk mengatasi masalah tersebut.</em></p>', NULL, NULL, '2024-11-29 12:32:34', '2024-11-29 12:32:34', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2176, 653, 5, '<p>Sudi berbincang dan berinisiatif memberi pertolongan sesama rakan sekerja dan pegawai atasan dengan tidak berkira kerja. Boleh menerima cadangan orang lain dan tidak berkeras kepala. Selain itu, turut boleh memanggil rakan sekerja untuk sama-sama menyiapkan kerja tersebut.<br /><br /><em>Contoh: Dia ialah orang yang sangat agresif dan sudi membuat semula dan dia turut boleh meminta rakan sekerja untuk sama-sama menyiapkan kerja.</em></p>', NULL, NULL, '2024-11-29 12:32:45', '2024-11-29 12:32:45', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2177, 654, 1, '<p>Menolak tugasan selain dari bidang sendiri dan langsung tidak dapat menerima tugasan tambahan atau di luar bidang kerja, amat mementingkan diri sendiri.<br /><br /><em>Contoh: Tidak mahu backup rakan sekerja yang bercuti dan selalu dipengaruhi oleh rakan sekerja yang lain dimana orang yang berbuat banyak tidak dapat apa-apa.</em></p>', NULL, NULL, '2024-11-29 12:33:13', '2024-11-29 12:33:13', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2178, 654, 2, '<p>Kadangkala menerima tugasan tambahan atau di luar bidang kerja tetapi dengan hati yang tidak rela dan mementingkan kepentingan diri sendiri.<br /><br /><em>Contoh: Kadangkala akan diminta untuk backup rakan sekerja yang bercuti tetapi dia akan membuat kerja secara tidak rela / memberi alasan bahawa dia tidak tahu buat kerja tersebut.</em></p>', NULL, NULL, '2024-11-29 12:33:22', '2024-11-29 12:33:22', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2179, 654, 3, '<p>Rela menerima tugasan tambahan atau di luar bidang dan tidak menolak apabila tugas diberi.<br /><br /><em>Contoh: Rela backup rakan sekerja yang bercuti dan tidak menolak apabila tugas diberi oleh Leader/Supervisor.</em></p>', NULL, NULL, '2024-11-29 12:33:32', '2024-11-29 12:33:32', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2180, 654, 4, '<p>Rela menerima tugasan tambahan atau di luar bidang dan tidak menolak apabila tugas diberi serta cuba mencari cara untuk menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Rela backup rakan sekerja yang bercuti dan tidak menolak apabila tugas diberi oleh Leader / Supervisor. Selain itu, dia juga cari jalan untuk mengeluarkan hasil kerja yang baik / membuat kerja tersebut dengan bersungguh-sungguh.</em></p>', NULL, NULL, '2024-11-29 12:33:41', '2024-11-29 12:33:41', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2181, 654, 5, '<p>Amat rela menerima tugasan tambahan atau di luar bidang dan menerimanya sebagai satu cabaran. Berusaha dan bertanggungjawab sepenuhnya sehingga tugasan selesai dengan sempurna.<br /><br /><em>Contoh: Sangat rela backup rakan sekerja yang bercuti dan menganggap tugas yang diberi tersebut sebagai satu cabaran / tugas sendiri. Dia membuat kerja dengan sepenuh hati dan mengambil tanggungjawab sehingga tugasan tersebut selesai dengan sempurnanya.</em></p>', NULL, NULL, '2024-11-29 12:33:51', '2024-11-29 12:33:51', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2182, 667, 1, '<p>Tidak dapat membuat apa-apa analisis dengan data yang ada dan tidak dapat mengenal pasti masalah-masalah.</p>', NULL, NULL, '2024-12-03 17:45:57', '2024-12-03 17:45:57', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2183, 667, 2, '<p>Dapat menganalisis data yand ada dan kadang-kala dapat mencari punca masalah.</p>', NULL, NULL, '2024-12-03 17:46:09', '2024-12-03 17:46:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2184, 667, 3, '<p>Dapat menganalisis data yang ada dan mencari punca masalah yang sering berlaku dan cuba memberi cadangan kepada pihak berkenaan untuk menyelesaikan masalah.</p>', NULL, NULL, '2024-12-03 17:46:20', '2024-12-03 17:46:20', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2185, 667, 4, '<p>Dapat menganalisis data yang diperoleh, mengenal pasti masalah dengan tepat dan dapat memberi cadangan dan berusaha melaksanakan pembetulan supaya masalah tidak berlaku lagi.</p>', NULL, NULL, '2024-12-03 17:46:28', '2024-12-03 17:46:28', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2186, 667, 5, '<p>Dapat berfikir untuk mendapat data untuk dianalisis dan menggunakan data yang diperoleh untuk mengkaji punca masalah dan membuat satu piawaian dan memastikan piawaian dapat diikut dan masalah tidak berlaku lagi.</p>', NULL, NULL, '2024-12-03 17:46:39', '2024-12-03 17:46:39', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2187, 668, 1, '<p>Tidak dapat menyelesaikan masalah dan perlu selalu merujuk kepada senior.</p>', NULL, NULL, '2024-12-03 17:47:12', '2024-12-03 17:47:12', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2188, 668, 2, '<p>Hanya dapat menyelesaikan masalah yang ringkas dan tidak dapat membuat keputusan dan perlu merujuk kepada senior.</p>', NULL, NULL, '2024-12-03 17:47:25', '2024-12-03 17:47:25', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2189, 668, 3, '<p>Dapat menyelesaikan masalah-masalah yang dihadapi dengan cermat dan membuat keputusan yang betul untuk menyelesaikan masalah dalam masa tersingkat.</p>', NULL, NULL, '2024-12-03 17:47:35', '2024-12-03 17:47:35', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2190, 668, 4, '<p>Dapat mengambil keputusan untuk menyelesaikan masalah-masalah yang dihadapi dalam masa tersingkat dan &ldquo;follow up&rdquo; supaya dapat memastikan tiada lagi masalah yang tertimbul sehingga masalah diselesaikan dan melaporkan kepada pihak atasan tentang masalah tersebut.</p>', NULL, NULL, '2024-12-03 17:49:58', '2024-12-03 17:49:58', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2191, 668, 5, '<p>Dapat mengambil keputusan untuk menyelesaikan masalah-masalah yang dihadapi dalam masa tersingkat dan &ldquo;follow up&rdquo; sehingga masalah diselesaikan dan melaporkan kepada pihak atasan tentang masalah yang dihadapi. Di samping itu, dapat memberi pendapat dan cadangan supaya perkara tersebut tidak berlaku lagi.</p>', NULL, NULL, '2024-12-03 17:50:17', '2024-12-03 17:50:17', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2192, 669, 1, '<p>Kerja tidak sistematik dan selalu terlupa kerja yang diberikan. Rekod kerja juga tidak dibuat dan tidak dapat kesan balik rekod kerja.</p>', NULL, NULL, '2024-12-03 17:56:17', '2024-12-03 17:56:17', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2193, 669, 2, '<p>Kerja dilakukan tidak bersistematik dan kadang-kala terlupa akan kerja yang diberikan. Di samping itu, kerja yang dibuat tidak di rekod dengan teliti dan susah untuk dikesan balik.</p>', NULL, NULL, '2024-12-03 17:56:26', '2024-12-03 17:56:26', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2194, 669, 3, '<p>Dapat melakukan kerja dengan sistematik, satu demi satu dan merekodkan semua kerja yang diberikan.</p>', NULL, NULL, '2024-12-03 17:56:37', '2024-12-03 17:56:37', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2195, 669, 4, '<p>Dapat melakukan kerja dengan sistematik, merekodkan semua kerja yang diberikan dan dapat dikesan balik setiap rekod. Di samping itu, &ldquo;follow up&rdquo; setiap rekod dan pastikan setiap rekod sempurna.</p>', NULL, NULL, '2024-12-03 17:56:52', '2024-12-03 17:56:52', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2196, 669, 5, '<p>Dapat merancang kerja sendiri dengan sistematik, mencipta dan membuat rekod dan sistem sendiri untuk pastikan kerja direkodkan dan dapat dikesan balik apabila diperlukan.</p>', NULL, NULL, '2024-12-03 17:57:03', '2024-12-03 17:57:03', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2197, 670, 1, '<p>Seorang yang tidak bertanggungjawab dan tidak berusaha dalam kerjayanya.</p>', NULL, NULL, '2024-12-03 17:57:26', '2024-12-03 17:57:26', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2198, 670, 2, '<p>Seorang yang bertanggungjawab tetapi tidak berkepercayaan kuat terhadap setiap tujuan dan hala organisasi.</p>', NULL, NULL, '2024-12-03 17:57:36', '2024-12-03 17:57:36', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2199, 670, 3, '<p>Seorang yang bersikap positif dan bertanggungjawab. Berkepercayaan kuat terhadap setiap tujuan dan hala organisasi dan berkemahuan berusaha untuk kepentingan organisasi dan berkeinginan yang kuat (loyalty) untuk mempertahankan kedudukan sebagai anggota organisasi.</p>', NULL, NULL, '2024-12-03 17:57:44', '2024-12-03 17:57:44', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2200, 670, 4, '<p>Seorang yang bersikap positif dan bertanggungjawab. Berkepercayaan kuat terhadap setiap tujuan dan hala organisasi dan berkemahuan berusaha untuk kepentingan organisasi dan berkeinginan yang kuat (loyalty) untuk mempertahankan kedudukan sebagai anggota organisasi. Selain itu, turut memberi nasihat jika terdapat rakan sekerja yang tidak sehaluan dengan pihak syarikat.</p>', NULL, NULL, '2024-12-03 17:57:53', '2024-12-03 17:57:53', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2201, 670, 5, '<p>Seorang yang bersikap positif dan bertanggungjawab. Berkepercayaan kuat terhadap setiap tujuan dan hala organisasi dan berkemahuan berusaha untuk kepentingan organisasi dan berkeinginan yang kuat (loyalty) untuk mempertahankan kedudukan sebagai anggota organisasi. Selain itu, turut memberi nasihat jika terdapat rakan sekerja yang tidak sehaluan dengan pihak syarikat dan sentiasa mempengaruhi rakan sekerja yang lain komitmen terhadap kerja demi kebaikan bersama.</p>', NULL, NULL, '2024-12-03 17:58:03', '2024-12-03 17:58:03', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2202, 671, 1, '<p>Bersikap negatif dan sentiasa mengadu dan membawa pengaruh negatif di kalangan rakan sekerja.</p>', NULL, NULL, '2024-12-03 17:58:23', '2024-12-03 17:58:23', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2203, 671, 2, '<p>Memerlukan motivasi daripada rakan sekerja tetapi tidak pernah membawa pengaruh negatif di kalangan rakan sekerja.</p>', NULL, NULL, '2024-12-03 17:58:32', '2024-12-03 17:58:32', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2204, 671, 3, '<p>Boleh memotivasikan rakan sekerja tetapi hasilnya tidak begitu besar.</p>', NULL, NULL, '2024-12-03 17:58:42', '2024-12-03 17:58:42', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2205, 671, 4, '<p>Boleh memotivasikan rakan sekerja dengan membawa hasil yang baik di mana tahu menggunakan keadaan dan kandungan kerja sebagai panduan memotivasikan orang lain.</p>', NULL, NULL, '2024-12-03 17:58:52', '2024-12-03 17:58:52', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2206, 671, 5, '<p>Boleh memotivasikan rakan sekerja dengan membawa hasil yang baik di mana tahu menggunakan keadaan dan kandungan kerja sebagai panduan memotivasikan orang lain. Selain itu akan melaporkan kesilapan rakan sekerja yang tidak mematuhi peraturan syarikat demi kebaikan bersama supaya tidak membawa pengaruh negatif kepada rakan sekerja yang lain.</p>', NULL, NULL, '2024-12-03 17:59:02', '2024-12-03 17:59:02', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2207, 672, 1, '<p>Tidak dapat menyiapkan tugasan mengikut masa yang ditetapkan dan selalu dibuat semula oleh rakan sekerja yang lain dan menyebabkan kelewatan.<br /><br /><em>Contoh: Kerja yang sepatutnya boleh disiapkan dalam sehari tetapi dia selalu tidak hadir bekerja dan kerjanya perlu disambung / dibuat semula oleh rakan sekerja yang lain dan menyebabkan kelewatan.</em></p>', NULL, NULL, '2024-12-03 17:59:31', '2024-12-03 17:59:31', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2208, 672, 2, '<p>Selalu mengambil masa yang panjang untuk menyiapkan kerja walaupun bimbingan sudah diberi.<br /><br /><em>Contoh: Kerja yang sepatutnya boleh disiapkan dalam sehari tetapi dia mengambil masa yang panjang walaupun bimbingan sudah diberi.</em></p>', NULL, NULL, '2024-12-03 17:59:40', '2024-12-03 17:59:40', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2209, 672, 3, '<p>Tugasan biasanya dapat disiapkan dengan sedikit bimbingan dan siap dalam masa yang ditetapkan mahupun lebih awal dan hasil kerja yang masih boleh diterima.<br /><br /><em>Contoh: Boleh menghasilkan kerja dalam masa yang ditetapkan tetapi masih perlu dalam pengawasan/bimbingan.</em></p>', NULL, NULL, '2024-12-03 17:59:50', '2024-12-03 17:59:50', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2210, 672, 4, '<p>Tugasan sentiasa disiapkan tanpa bimbingan dan mengikut jadual mahupun lebih awal dan hasil kerja yang agar memuaskan.<br /><br /><em>Contoh: Boleh menghasilkan kerja dalam masa yang pendek dan tanpa sebarang pengawasan/bimbingan seperti dia cuma perlu 5 jam untuk menghasilkan kerja yang dijangka siap dalam sehari dan dia boleh menghasilkan lebih dalam satu hari.</em></p>', NULL, NULL, '2024-12-03 18:00:01', '2024-12-03 18:00:01', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2211, 672, 5, '<p>Mengutamakan masa dan pantas dalam menyiapkan tugasan yang diberi dan hasil kerja sangat bagus dan boleh diharapkan.<br /><br /><em>Contoh:Boleh membuat apa kerja yang dirancang dan menepati masa yang ditetapkan atau lebih awal tanpa pengawasan/bimbingan. Individu yang teliti dan prihatin dan menguasa masa dan memberi hasil kerja yang sangat bagus dan halus.</em></p>', NULL, NULL, '2024-12-03 18:00:12', '2024-12-03 18:00:12', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2212, 673, 1, '<p>Suka menolak tanggungjawab kerja dan berpura-pura/berdiam diri walaupun tahu apa cara untuk membuat kerja/menyelesaikan masalah.<br /><br /><em>Contoh: Langsung tidak bergerak dan pakai duduk dan tunggu sahaja walaupun sudah diberi penjelasan dalam pelan kerja.</em></p>', NULL, NULL, '2024-12-03 18:00:37', '2024-12-03 18:00:37', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2213, 673, 2, '<p>Kadangkala menolak tanggungjawab kerja dan berpura-pura/berdiam diri walaupun tahu apa cara untuk membuat kerja/menyelesaikan masalah.<br /><br /><em>Contoh: Tidak berusaha untuk belajar dan memahami pembacaan pelan kerja dan ukuran serta memerlukan seseorang mengawasi di tepi dan selalu memberi penjelasan boleh baru dapat menghasilkan kerja yang ditugaskan.</em></p>', NULL, NULL, '2024-12-03 18:00:47', '2024-12-03 18:00:47', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2214, 673, 3, '<p>Sudah faham dan boleh terus bertindak/bergerak ke atas kerja yang telah diselesaikan.&nbsp;<br /><br /><em>Contoh: Sudah tahu membuat kerja/menyelesaikan masalah dan tidak menolak tanggungjawab.</em></p>', NULL, NULL, '2024-12-03 18:00:55', '2024-12-03 18:00:55', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2215, 673, 4, '<p>Sudah faham dan boleh bertindak cepat ke atas semua tugasan serta tidak perlu pengawasan/bimbingan dan akan lapor balik apabila kerja telah siap.<br /><br /><em>Contoh: Bertanggungjawab dan tidak berpura-pura atau berdiam diri dalam membuat kerja/menyelesaikan masalah dan tidak perlu pengawasan/bimbingan dan akan bertindak/bergerak ke atas kerja yang ditugaskan serta lapor balik apabila kerja telah siap.</em></p>', NULL, NULL, '2024-12-03 18:01:05', '2024-12-03 18:01:05', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2216, 673, 5, '<p>Sudah faham dan boleh bertindak cepat ke atas semua tugasan serta tidak perlu pengawasan/bimbingan dan akan lapor balik apabila kerja telah siap. Selain itu, dapat memberi nasihat kepada rakan sekerja yang lain supaya cepat bertindak dalam kerja.<br /><br /><em>Contoh: Bertanggungjawab dan tidak berpura-pura atau berdiam diri dalam membuat kerja/menyelesaikan masalah dan tidak perlu pengawasan/bimbingan dan akan bertindak/bergerak ke atas kerja yang ditugaskan serta lapor balik apabila kerja telah siap. Selain itu, juga memotivasikan rakan sekerja supaya tidak berpura-pura/berdiam diri dalam &nbsp;membuat kerja/menyelesaikan masalah.</em></p>', NULL, NULL, '2024-12-03 18:01:15', '2024-12-03 18:01:15', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2217, 674, 1, '<p>Tidak membuat kerja secara sistematik dan tidak tahu membezakan kepentingan kerja.<br /><br /><em>Contoh: Tidak tahu membezakan kepentingan kerja dan tidak buat perancangan kerja.</em></p>', NULL, NULL, '2024-12-03 18:01:48', '2024-12-03 18:01:48', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2218, 674, 2, '<p>Kadangkala ada membuat kerja secara sistematik dan kadangkala tahu membezakan kepentingan kerja tetapi keadaan tidak ketara.<br /><br /><em>Contoh: Kadangkala tahu membezakan kepentingan kerja dan buat perancangan kerja tetapi tidak selalu dan ikut mood sendiri.</em></p>', NULL, NULL, '2024-12-04 09:37:30', '2024-12-04 09:37:30', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2219, 674, 3, '<p>Tidak perlu seseorang mengawasi di tepi dan tahu membuat kerja secara sistematik dan tahu membezakan kepentingan kerja dengan penjelasan yang ringkas sahaja.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan memerlukan penjelasan kerja yang ringkas sahaja.</em></p>', NULL, NULL, '2024-12-04 09:37:40', '2024-12-04 09:37:40', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2220, 674, 4, '<p>Hanya memerlukan penjelasan yang ringkas dan tahu membuat kerja secara sistematik dan tahu membezakan kepentingan kerja. Berhati-hati dan tiada kesilapan dalam kerja yang dihasilkan.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan hanya memerlukan penjelasan kerja yang ringkas sahaja dan memberi tumpuan dalam kerja dan mengeluarkan hasil kerja yang baik.</em></p>', NULL, NULL, '2024-12-04 09:37:49', '2024-12-04 09:37:49', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2221, 674, 5, '<p>Hanya memerlukan penjelasan yang sangat ringkas sahaja untuk membuat kerja secara sistematik dan tahu membezakan kepentingan kerja dan dapat memberi tunjuk ajar kepada rakan sekerja.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan hanya memerlukan penjelasan kerja yang ringkas sahaja dan memberi tumpuan dalam kerja dan mengeluarkan hasil kerja yang baik dan turut memberi tunjuk ajar kepada rakan sekerja.</em></p>', NULL, NULL, '2024-12-04 09:37:59', '2024-12-04 09:37:59', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2222, 675, 1, '<p>Hasil kerja yang tidak boleh diterima dan selalu membuat kesilapan.<br /><br /><em>Contoh: Tidak menumpu perhatian semasa bekerja dan selalu membuat kesilapan yang sama. Tidak pernah berubah walaupun &nbsp;sudah diberi bimbingan/teguran seperti selalu mengulangi kesilapan yang sama walaupun sudah banyak kali memasang mesin yang sama model.</em></p>', NULL, NULL, '2024-12-04 09:38:20', '2024-12-04 09:38:20', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2223, 675, 2, '<p>Cuai dan mengakibatkan kesilapan kerja.<br /><br /><em>Contoh: Kadangkala cuai semasa bekerja dan mengakibatkan kesilapan kerja kerana tindakan yang lambat untuk berubah setelah diberi bimbingan/teguran.</em></p>', NULL, NULL, '2024-12-04 09:38:31', '2024-12-04 09:38:31', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2224, 675, 3, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan meminimumkan tahap kesilapan kepada yang terendah.<br /><br /><em>Contoh: Kadangkala ada membuat kesilapan tetapi mengambil tindakan yang cepat untuk berubah setelah diberi bimbingan/teguran.</em></p>', NULL, NULL, '2024-12-04 09:38:41', '2024-12-04 09:38:41', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2225, 675, 4, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan apa-apa kesilapan dalam kerja harian.<br /><br /><em>Contoh: Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan. Selain itu, juga berinisiatif untuk menjaga barangan/bahan dan tidak membazir.</em></p>', NULL, NULL, '2024-12-04 09:38:53', '2024-12-04 09:38:53', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2226, 675, 5, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan kerja dan berinisiatif untuk memberi pendapat dan memperbaiki cara kerja yang lebih baik untuk meminimumkan tahap kesilapan kerja.<br /><br /><em>Contoh: Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan dan berinisiatif untuk memberi pendapat dan memperbaiki cara kerja untuk meminimumkan tahap kesilapan kerja seperti berinisiatif untuk mengetahui masalah semasa pemasangan mesin dan turut memberi pendapat untuk memperbaiki cara kerja/menyelesaikan masalah.</em></p>', NULL, NULL, '2024-12-04 09:39:04', '2024-12-04 09:39:04', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2227, 676, 1, '<p>Langsung tidak memahami permintaan kualiti kerja dan tidak memberi perhatian kepada kerja yang dilakukan.<br /><br /><em>Contoh: Langsung tidak memahami permintaan kualiti kerja dan tidak memberi perhatian terhadap semua kerja yang dilakukan seperti membuat pemasangan Control Panel tetapi langsung tidak mengikut diagram yang diberi.</em></p>', NULL, NULL, '2024-12-04 09:39:25', '2024-12-04 09:39:25', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2228, 676, 2, '<p>Kadangkala tidak faham spesifikasi kerja yang diberi dan tidak berinisiatif mengambil langkah untuk mengetahui untuk menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Tidak berinisiatif untuk bertanya/kurang bertanya apabila tidak tahu semasa memasang Control Panel dan pasang ikut sendiri dan tidak ikut cara kerja yang betul.</em></p>', NULL, NULL, '2024-12-04 09:39:34', '2024-12-04 09:39:34', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2229, 676, 3, '<p>Memahami permintaan kualiti kerja dan dapat menghasilkan kerja yang berkualiti secara individu tanpa pengawasan pegawai atasan tetapi tidak mengambil perhatian dan abaikan kerja yang remeh temeh serta tidak mengambil perhatian terhadap kekemasan hasil kerja.<br /><br /><em>Contoh: Tahu pasang Control Panel tetapi tidak terfikir tentang kekemasan. Wayar sudah ditarik dengan betul tetapi tidak diikat dengan cable tie/tidak tersusun/tidak label semasa membuat pemasangan.</em></p>', NULL, NULL, '2024-12-04 09:39:42', '2024-12-04 09:40:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2230, 676, 4, '<p>Faham tentang kualiti dan dapat menghasilkan kerja yang berkualiti dan memenuhi kehendak syarikat dan dapat memastikan kerja yang dihasilkan tidak bermasalah.<br /><br /><em>Contoh: Faham tentang kualiti kerja dan ikut semua spesifikasi yang diminta. Boleh berfikir dan nampak (meramalkan) ke hadapan dan memastikan kerja yang dihasilkan tidak bermasalah seperti tahu pasang Control Panel dan semua litar boleh berfungsi dengan baik dan pemasangan yang kemas dan melaporkan keadaan kepada Leader/Supervisor apabila litar tidak berfungsi/bernyala.</em></p>', NULL, NULL, '2024-12-04 09:39:52', '2024-12-04 09:39:52', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2231, 676, 5, '<p>Sangat faham tentang kualiti kerja dan dapat menghasilkan kerja yang berkualiti dan memenuhi kehendak syarikat dan dapat memastikan kerja yang dihasilkan tidak bermasalah serta turut memberi tunjuk ajar kepada rakan kerja yang lain.&nbsp;<br /><br /><em>Contoh: Sangat faham tentang kualiti kerja dan ikut semua spesifikasi yang diminta. Boleh berfikir dan nampak (meramalkan) ke hadapan dan memastikan kerja yang dihasilkan tidak bermasalah. Selain itu, juga dapat memberi tunjuk ajar kepada rakan sekerja yang lain seperti tahu pasang Control Panel dan semua litar boleh berfungsi dengan baik dan pemasangan yang kemas dan melaporkan keadaan kepada Leader/Supervisor apabila litar tidak berfungsi/bernyala. Selain itu, dia juga memberi tunjuk ajar kepada rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-12-04 09:40:23', '2024-12-04 09:40:23', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2232, 677, 1, '<p>Sentiasa membazirkan/merosakkan sumber syarikat.<br /><br /><em>Contoh: Tidak pernah berhati-hati dalam spesifikasi kerja yang diberi dan sentiasa mengakibatkan pembaziran bahan.</em></p>', NULL, NULL, '2024-12-04 09:44:10', '2024-12-04 09:44:10', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2233, 677, 2, '<p>Ada bersikap mahu menjimatkan sumber syarikat tetapi kadangkala menyebabkan pembaziran di atas kecuaiannya.<br /><br /><em>Contoh: Cuai dalam pembacaan spesifikasi kerja yang diberi dan silap ambil bahan dan menyebabkan kesilapan dan membazirkan bahan serta perlu &ldquo;rework&rdquo;.</em></p>', NULL, NULL, '2024-12-04 09:44:19', '2024-12-04 09:44:19', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2234, 677, 3, '<p>Berhati-hati semasa bekerja dan menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dan memastikan betul supaya tidak berlaku kesilapan yang mengakibatkan pembaziran bahan dan buang masa.</em></p>', NULL, NULL, '2024-12-04 09:44:28', '2024-12-04 09:44:28', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2235, 677, 4, '<p>Berhati-hati semasa bekerja dan berinisiatif menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya. Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dengan pelan kerja dan memastikan semua barang yang ambil adalah betul. Ada pemikiran tidak membazir seperti dalam menghasilkan sesuatu barang yang sangat kecil, dia akan cari scrap dahulu dan tidak guna bahan yang baru atau bahan yang besar.Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan.</em></p>', NULL, NULL, '2024-12-04 09:44:37', '2024-12-04 09:44:37', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2236, 677, 5, '<p>Berhati-hati semasa bekerja dan berinisiatif menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya. Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan dan juga menyedarkan dan membetulkan kesilapan rakan sekerja yang lain.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dengan pelan kerja dan memastikan semua barang yang ambil adalah betul. Ada pemikiran tidak membazir seperti dalam menghasilkan sesuatu barang yang sangat kecil, dia akan cari scrap dahulu dan tidak guna bahan yang baru atau bahan yang besar.Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan dan menyedarkan dan membetulkan kesilapan rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-12-04 09:44:47', '2024-12-04 09:44:47', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2237, 678, 1, '<p>Pengetahuan atau kemahiran adalah terhad dan tidak dapat menyelesaikan tugasan dan menggunakan masa yang panjang untuk mempelajari pengetahuan dan cara kerja yang agak senang.<br /><br /><em>Contoh: Tidak ada pengetahuan dan kemahiran kerja dan menggunakan masa yang panjang untuk mempelajari cara kerja yang senang walaupun bimbingan telah diberi seperti membuat kerja kimpalan yang paling senang iaitu mengimpal besi dalam kedudukan rata.</em></p>', NULL, NULL, '2024-12-04 09:49:10', '2024-12-04 09:49:10', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2238, 678, 2, '<p>Kurang pengetahuan atau kemahiran yang cukup untuk mengendalikan tugasan.<br /><br /><em>Contoh: Hasil kimpalan yang teruk dan bimbingan masih diperlukan walaupun diminta menghasilkan kerja kimpalan yang agak senang seperti mengimpal besi dalam kedudukan rata dan mendatar.</em></p>', NULL, NULL, '2024-12-04 09:49:19', '2024-12-04 09:49:19', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2239, 678, 3, '<p>Mempunyai pengetahuan dan kemahiran untuk mengendalikan tugasan dan mempunyai sikap mahu belajar dan mempelajari pengetahuan kerja yang baru dalam masa yang singkat dan mengimplikasikan dalam kerja harian.<br /><br /><em>Contoh: Ada pengetahuan dan kemahiran kimpalan tetapi tidak dapat meneruskan kerja apabila menghadapi kerja yang tidak biasa dan memerlukan bimbingan seperti: boleh mengimpal besi yang nipis tetapi tidak apabila diminta mengimpal besi yang lagi nipis / boleh mengimpal dalam kedudukan rata, mendatar dan menegak tetapi tidak apabila dalam keadaan overhead atau dalam keadaan 45 darjah.</em></p>', NULL, NULL, '2024-12-04 09:49:31', '2024-12-04 09:49:31', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2240, 678, 4, '<p>Boleh menguasai pengetahuan dan kemahiran untuk mengendalikan tugasan dan pencapaian yang agak memuaskan dan dapat menggunakan pengetahuannya untuk meningkatkan kualiti kerja.<br /><br /><em>Contoh: Mempunyai pengetahuan dan kemahiran yang luas serta jelas dengan semua keperluan/permintaan kerja seperti memilih kaedah yang bersesuaian untuk menghasilkan kerja dan tahu mengawal had api untuk mencegah hasil kerja dari kerosakan.</em></p>', NULL, NULL, '2024-12-04 09:49:41', '2024-12-04 09:49:41', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2241, 678, 5, '<p>Menguasai pengetahuan dan kemahiran untuk mengendalikan tugasan dan boleh menggabungkan pengetahuan untuk meningkatkan kualiti kerja serta mencari cara kerja baru untuk menyelesaikan masalah kerja dengan pengetahuannya.<br /><br /><em>Contoh: Mempunyai pengetahuan dan kemahiran yang luas serta jelas dengan semua keperluan/permintaan kerja dan berinisiatif memberi cadangan untuk menyelesaikan masalah kerja.&nbsp;</em></p>', NULL, NULL, '2024-12-04 09:49:52', '2024-12-04 09:49:52', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2242, 679, 1, '<p>Tidak pernah mengemas dan membersihkan tempat kerja sendiri dan sentiasa mengotorkan tempat kerja sendiri dan rakan sekerja yang lain.<br /><br /><em>Contoh: Tidak pernah terfikir kebaikan bersama dan terus membuang sisa kerja ke lantai dan menganggap ini kerja cleaner untuk membersihkan.</em></p>', NULL, NULL, '2024-12-04 09:50:21', '2024-12-04 09:50:21', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2243, 679, 2, '<p>Kadangkala ada mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya tidak kemas.<br /><br /><em>Contoh: Tidak selalu mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya tidak kemas seperti kadangkala ada membersihkan tempat kerja dan kadangkala tidak.</em></p>', NULL, NULL, '2024-12-04 09:50:29', '2024-12-04 09:50:29', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2244, 679, 3, '<p>Berinisiatif untuk mengemas dan membersihkan tempat kerja dan kebanyakan masa tempat kerjanya adalah kemas dan bersih.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai.</em></p>', NULL, NULL, '2024-12-04 09:50:38', '2024-12-04 09:50:38', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2245, 679, 4, '<p>Selalu mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya kemas dan selalu menolong membersihkan kawasan bahagiannya (division) dan kilang.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai serta tolong membersihkan kawasan yang lain.</em></p>', NULL, NULL, '2024-12-04 09:54:42', '2024-12-04 09:54:42', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2246, 679, 5, '<p>Selalu mengemas dan membersihkan tempat kerja dan tempat kerjanya kelihatan kemas dan bersih. Juga selalu menjaga kebersihan seluruh kawasan kilang dan dapat menegur rakan sekerja untuk menjaga kebersihan kilang.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai serta tolong menjaga kebersihan kawasan yang lain dan menegur rakan sekerja yang tidak menjaga kebersihan kilang.</em></p>', NULL, NULL, '2024-12-04 09:54:51', '2024-12-04 09:54:51', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2247, 680, 1, '<p>Tidak menjaga peralatan dan kemudahan syarikat.<br /><br /><em>Contoh: Tidak menjaga peralatan dan kemudahan syarikat seperti tidak menjaga forklift dan tidak pernah meletakkkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-12-04 09:55:17', '2024-12-04 09:55:17', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2248, 680, 2, '<p>Kadangkala bersikap cuai dalam mengendali peralatan dan kemudahan syarikat dan mengakibatkan kerosakan.<br /><br /><em>Contoh: Tidak selalu menjaga peralatan dan kemudahan syarikat dan mengakibatkan kerosakan seperti forklift terus jalan setelah enjin dihidupkan. Tidak mengambil berat tentang barang yang diangkat dan masuk ke ruang yang kecil. Selalu tidak meletakkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-12-04 09:55:28', '2024-12-04 09:55:28', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2249, 680, 3, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat dengan cara yang betul.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-12-04 09:55:38', '2024-12-04 09:55:38', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2250, 680, 4, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat demi kebaikan bersama. Selain itu, &nbsp;melaporkan kepada pihak atasan bila nampak rakan sekerja salahguna dan memberi cara penyelesaian yang bermanfaat.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna dan melapor jika ada kerosakan dan memberi cadangan untuk memperbaiki cara penggunaan dan penjagaan alatan.</em></p>', NULL, NULL, '2024-12-04 09:55:47', '2024-12-04 09:55:47', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2251, 680, 5, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat demi kebaikan bersama. Selain itu, &nbsp;melaporkan kepada pihak atasan bila nampak pekerja salahguna dan memberi cara penyelesaian yang bermanfaat. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna dan melapor jika ada kerosakan dan memberi cadangan untuk memperbaiki cara penggunaan dan penjagaan alatan.Selain itu, akan menyedarkan dan menasihati rakan sekerja yang tidak menjaga forklift semasa mengguna.</em></p>', NULL, NULL, '2024-12-04 09:55:57', '2024-12-04 09:55:57', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2252, 681, 1, '<p>Tidak mengutamakan keselamatan semasa bekerja.<br /><br /><em>Contoh: Tidak mengutamakan keselamatan semasa bekerja seperti tidak memakai PPE semasa bekerja.</em></p>', NULL, NULL, '2024-12-04 09:56:19', '2024-12-04 09:56:19', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2253, 681, 2, '<p>Ada sikap mengutamakan keselamatan tetapi kadangkala tidak.<br /><br /><em>Contoh: Ada memakai PPE semasa bekerja tetapi kadangkala tidak.</em></p>', NULL, NULL, '2024-12-04 09:57:18', '2024-12-04 09:57:18', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2254, 681, 3, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja.</em></p>', NULL, NULL, '2024-12-04 09:57:28', '2024-12-04 09:57:28', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2255, 681, 4, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan.</em></p>', NULL, NULL, '2024-12-04 09:57:38', '2024-12-04 09:57:38', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2256, 681, 5, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja dan melaporkan kepada pihak atasan serta turut memberi cara atau cara penyelesaian yang bermanfaat.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan serta turut memberi cara atau cara penyelesaian yang bermanfaat.</em></p>', NULL, NULL, '2024-12-04 09:57:48', '2024-12-04 09:57:48', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2257, 682, 1, '<p>Menerima tugasan tetapi tidak memikul tanggungjawab kerja dan tidak dapat bekerja di bawah tekanan.<br /><br /><em>Contoh: Dia terima kerja yang diberi tetapi sentiasa bersembang dengan rakan sekerja dan tidak buat kerja sehingga tidak nampak hasil kerja.</em></p>', NULL, NULL, '2024-12-04 09:58:22', '2024-12-04 09:58:22', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2258, 682, 2, '<p>Boleh menerima dan memikul tanggungjawab dan cuba untuk bekerja di bawah tekanan tetapi kadangkala tidak dapat menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Dia boleh buat kerja dan cuba elakkan diri dari tidak masuk kerja/tidak memberi alasan untuk bercuti tetapi kadangkala masih perlu dalam bimbingan.</em></p>', NULL, NULL, '2024-12-04 09:58:33', '2024-12-04 09:58:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2259, 682, 3, '<p>Boleh menerima dan memikul tanggungjawab dan dapat menghabiskan setiap kerja yang diamanahkan dengan baik di bawah tekanan dan melaporkan kerja yang telah dilakukan kepada pegawai atasan.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia masih menepati target dan ikut piawai kerja yang ditetapkan oleh syarikat. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia juga akan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-12-04 09:58:43', '2024-12-04 09:58:43', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2260, 682, 4, '<p>Rela menerima dan memikul tanggungjawab dan sentiasa dapat menghasilkan kerja yang berkualiti di bawah tekanan dan dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang dilakukan kepada pegawai atasan.Boleh buat kerja lebih masa sehingga kerja siap.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia akan menawarkan diri secara sukarela untuk kerja tersebut serta menepati target dan ikut piawai kerja yang ditetapkan oleh syarikat. Boleh buat kerja lebih masa sehingga kerja siap. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-12-04 09:58:53', '2024-12-04 09:58:53', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2261, 682, 5, '<p>Rela menerima dan memikul tanggungjawab serta tahu kepentingan dan deadline kerja. Dapat memanggil rakan sekerja untuk menyiapkan kerja bersama. Sentiasa dapat menghasilkan kerja yang berkualiti di bawah tekanan dan dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang dilakukan kepada pegawai atasan.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia tahu kepentingan dan deadline kerja tersebut serta dapat memanggil rakan sekerja untuk menyiapkan kerja bersama. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-12-04 09:59:04', '2024-12-04 09:59:04', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2262, 683, 1, '<p>Tidak rela mengaku kesilapan dan suka menolak tanggungjawab kepada orang lain.<br /><br /><em>Contoh: Telah melakukan kesilapan seperti tidak mengikuti spesifikasi kerja yang diberi oleh Leader / tidak tanya Leader apabila tidak faham / tanya rakan sekerja yang tidak dipertanggungjawabkan dan tidak pernah mengakui kesilapan apabila ditegur oleh Leader/Supervisor.</em></p>', NULL, NULL, '2024-12-04 09:59:23', '2024-12-04 09:59:23', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2263, 683, 2, '<p>Kadangkala tidak rela mengaku kesilapan dan suka membuat perbandingan diri dengan orang lain dalam kesilapan yang telah dibuat.<br /><br /><em>Contoh: Telah melakukan kesilapan seperti tidak mengikuti spesifikasi kerja yang diberi oleh Leader / tidak tanya Leader apabila tidak faham / tanya rakan sekerja yang tidak dipertanggungjawabkan dan kadangkala tidak mengakui kesilapan apabila ditegur oleh Leader/Supervisor malah menyatakan Leader/Supervisor ada prasangka terhadap dia.</em></p>', NULL, NULL, '2024-12-04 09:59:32', '2024-12-04 09:59:32', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2264, 683, 3, '<p>Mengaku kesilapan dan tidak menolak tanggungjawab kepada orang lain.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan. Dia terima dan mengakui kesilapan.</em></p>', NULL, NULL, '2024-12-04 09:59:42', '2024-12-04 09:59:42', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2265, 683, 4, '<p>Tidak melarikan diri dari tanggungjawab dan terus berjumpa dengan pihak atasan untuk mengakui kesilapan dan berinisiatif untuk memperbaiki kesilapan yang telah dilakukan.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan. Dia tidak melarikan diri dari tanggungjawab dan terus berjumpa dengan Leader/Supervisor dan mengakui kesilapan. Selain itu, dia juga memberi cadangan dan sama-sama memperbaiki kesilapan yang telah dilakukan.</em></p>', NULL, NULL, '2024-12-04 09:59:53', '2024-12-04 09:59:53', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2266, 683, 5, '<p>Berani mengaku kesilapan dan tidak menolak tanggungjawab dan memastikan kesilapan tidak berlaku lagi. Berinisiatif untuk memperbetulkan kesilapan dan dapat memberi cadangan yang bermanfaat untuk mengelakkan kesilapan berlaku lagi.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan yang agak besar. Dia berani mengakui kesilapan dan terus berjumpa dengan Leader/Supervisor untuk mengakui kesilapan. Dia mengambil pengalaman tersebut sebagai satu pengajaran dan tidak mengulangi kesilapan tersebut lagi. Selain itu, dia &nbsp;memberi cadangan dan sama-sama memperbaiki kesilapan yang telah dilakukan serta memberi cadangan yang bermanfaat untuk mengelakkan kesilapan berlaku lagi.</em></p>', NULL, NULL, '2024-12-04 10:00:04', '2024-12-04 10:00:04', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2267, 684, 1, '<p>Membuat kerja alah kadar dan setakat membuat kerja sahaja dan tidak menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Tidak menunjukkan sikap ingin belajar dan tidak menumpukan perhatian semasa bekerja seperti dia boleh mengambil masa yang panjang untuk memasang beberapa nut pada mesin.</em></p>', NULL, NULL, '2024-12-04 10:00:27', '2024-12-04 10:00:27', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2268, 684, 2, '<p>Boleh membuat kerja tetapi mudah dipengaruhi orang lain dan kadangkala tidak dapat menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Dia boleh pasang nut pada mesin tetapi mudah dipengaruhi oleh rakan sekerja yang lain seperti dia akan melambatkan proses kerjanya dan sambil kerja sambil bersembang apabila ada rakan sekerja yang bersembang dengannya semasa bekerja.</em></p>', NULL, NULL, '2024-12-04 10:00:35', '2024-12-04 10:00:35', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2269, 684, 3, '<p>Lebih agresif dan sikap kerja juga serius dan dapat menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak mengangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja.</em></p>', NULL, NULL, '2024-12-04 10:00:45', '2024-12-04 10:00:45', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2270, 684, 4, '<p>Bersemangat kerja dan menumpukan perhatian sepenuhnya dalam kerja. Sentiasa mengutamakan kualiti kerja dan menghasilkan kerja yang halus dan teliti dan tidak melakukan kesilapan.<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak menggangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja. Dia sentiasa mengutamakan kualiti kerja dan memastikan nut yang dipasang itu betul dan kemas.</em></p>', NULL, NULL, '2024-12-04 10:00:55', '2024-12-04 10:01:07', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2271, 684, 5, '<p>Matlamat untuk berjaya sangat jelas. Menumpukan perhatian sepenuhnya dalam kerja. Sentiasa mengutamakan kualiti kerja dan menghasilkan kerja yang halus dan teliti dan tidak melakukan kesilapan. Selain itu turut memberi cadangan dan cara kerja untuk memastikan kerja berkualiti dihasilkan setiap kali.&nbsp;<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak menggangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja. Dia sentiasa mengutamakan kualiti kerja dan memastikan nut yang dipasang itu betul dan kemas. Selain itu, dia juga akan memberi cadangan untuk memastikan kerja berkualiti dapat dihasilkan.</em></p>', NULL, NULL, '2024-12-04 10:01:18', '2024-12-04 10:01:18', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2272, 685, 1, '<p>Langsung tidak mahu memahami dan menerima peraturan dan polisi syarikat dan sentiasa membuat aduan terhadap dasar syarikat.<br /><br /><em>Contoh: Selalu tidak menutup lampu setelah mengguna tandas dan membuat aduan apabila pihak syarikat mengambil tindakan.</em></p>', NULL, NULL, '2024-12-04 11:27:19', '2024-12-04 11:27:19', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2273, 685, 2, '<p>Kadangkala sahaja mahu menerima dan mematuhi peraturan dan polisi syarikat.<br /><br /><em>Contoh: Kadangkala ada menutup lampu setelah mengguna tandas kadangkala tidak.</em></p>', NULL, NULL, '2024-12-04 11:27:29', '2024-12-04 11:27:29', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2274, 685, 3, '<p>Menerima dan mematuhi setiap peraturan dan polisi syarikat.<br /><br /><em>Contoh: Setiap kali akan menutup lampu setelah mengguna tandas.</em></p>', NULL, NULL, '2024-12-04 11:27:37', '2024-12-04 11:27:37', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2275, 685, 4, '<p>Tidak melanggar peraturan dan sentiasa dapat menasihatkan rakan sekerja untuk menerima dan mematuhi peraturan dan polisi syarikat untuk kebaikan bersama.<br /><br /><em>Contoh: Sentiasa menutup lampu setelah mengguna tandas dan &nbsp;menasihati dan menerang kepada rakan sekerja yang tidak mematuhi peraturan.</em></p>', NULL, NULL, '2024-12-04 11:27:46', '2024-12-04 11:27:46', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2276, 685, 5, '<p>Memahami dan menerima setiap peraturan dan polisi syarikat dan sentiasa menasihatkan rakan sekerja yang melanggar peraturan serta melaporkan masalah disiplin kepada pegawai atasan untuk kebaikan bersama.<br /><br /><em>Contoh: &nbsp;Sentiasa menutup lampu setelah mengguna tandas dan &nbsp;menasihati dan menerang kepada rakan sekerja yang tidak mematuhi peraturan. Selain itu, juga akan melaporkan nama pekerja yang tidak menutup lampu setelah mengguna tandas.</em></p>', NULL, NULL, '2024-12-04 11:27:56', '2024-12-04 11:27:56', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2277, 686, 1, '<p>Selalu tidak tepat masuk kerja dan menunjukkan kedatangan yang tidak baik.<br /><br /><em>Contoh: Masih berada di tempat berehat semasa siren berbunyi dan jalan perlahan ke tempat kerja.</em></p>', NULL, NULL, '2024-12-04 11:28:14', '2024-12-04 11:28:14', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2278, 686, 2, '<p>Kadangkala ada masuk kerja pada masa yang ditetapkan tetapi keadaan tidak ketara.<br /><br /><em>Contoh: Kadangkala ada tepat masuk kerja semasa siren berbunyi tetapi kebanyakan masa tidak masuk kerja pada masa yang tepat.</em></p>', NULL, NULL, '2024-12-04 11:28:23', '2024-12-04 11:28:23', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2279, 686, 3, '<p>Kebanyakan masa masuk kerja pada masa yang ditetapkan tetapi kadangkala ada lewat juga.<br /><br /><em>Contoh: Kebanyakan masa masuk kerja semasa siren berbunyi tetapi sekali kala masih lewat masuk kerja.</em></p>', NULL, NULL, '2024-12-04 11:28:31', '2024-12-04 11:28:31', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2280, 686, 4, '<p>Mementingkan ketepatan masa masuk kerja dan masuk kerja tepat pada masa atau lebih awal.<br /><br /><em>Contoh: Sentiasa masa masuk kerja sebelum siren berbunyi atau lebih awal.</em></p>', NULL, NULL, '2024-12-04 11:28:40', '2024-12-04 11:28:40', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2281, 686, 5, '<p>Mementingkan ketepatan masa masuk kerja dan masuk kerja tepat pada masa atau lebih awal serta memberi nasihat kepada rakan sekerja yang lewat.<br /><br /><em>Contoh: Sentiasa masa masuk kerja sebelum siren berbunyi atau lebih awal serta memberi nasihat kepada rakan sekerja yang lewat.</em></p>', NULL, NULL, '2024-12-04 11:28:50', '2024-12-04 11:28:50', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2282, 687, 1, '<p>Disiplin diri yang tidak memuaskan dan sering meninggalkan tempat kerja dengan berkeliaran tanpa tujuan dan sering membazirkan masa serta curi tulang.<br /><br /><em>Contoh: Sering meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja (banyak kali sehari) dan mengambil masa yang panjang dalam tandas serta membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-12-04 11:29:10', '2024-12-04 11:29:10', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2283, 687, 2, '<p>Kadangkala membazirkan masa dan curi tulang serta meninggalkan tempat kerja dengan berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Kadangkala meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja (banyak kali sehari) dan mengambil masa yang panjang dalam tandas serta membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-12-04 11:29:20', '2024-12-04 11:29:20', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2284, 687, 3, '<p>Tidak membazirkan masa dan ringan tulang serta menumpukan perhatian semasa bekerja. Tidak meninggalkan tempat kerja dengan berkeliaran tanpa tujuan.<br /><br /><em>Contoh: Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-12-04 11:29:30', '2024-12-04 11:29:30', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2285, 687, 4, '<p>Teladan yang baik dan tumpuan perhatian sepenuhnya semasa bekerja. Tidak berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Seorang teladan yang baik dan memberi tumpuan sepenuhnya semasa bekerja. Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-12-04 11:29:39', '2024-12-04 11:29:39', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2286, 687, 5, '<p>Teladan yang baik dan tumpuan perhatian sepenuhnya semasa bekerja dan juga selalu memberi nasihat kepada rakan sekerja supaya melahirkan keadaan kerja yang lebih agresif. Tidak berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Seorang teladan yang baik dan memberi tumpuan sepenuhnya semasa bekerja. Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja. Selalu memberi nasihat kepada rakan sekerja yang selalu pergi ke tandas sebagai alasan.</em></p>', NULL, NULL, '2024-12-04 11:29:48', '2024-12-04 11:29:48', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2287, 688, 1, '<p>Tidak pernah berada di tempat kerja semasa pembersihan kawasan dijalankan.<br /><br /><em>Contoh: Tidak berada di tempat kerja dan pergi ke tandas semasa pembersihan kawasan dijalankan.</em></p>', NULL, NULL, '2024-12-04 11:30:09', '2024-12-04 11:30:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2288, 688, 2, '<p>Memulakan kerja pembersihan kawasan walaupun masa yang ditetapkan belum sampai lagi.<br /><br /><em>Contoh: Memulakan kerja pembersihan kawasan walaupun masa yang ditetapkan belum sampai lagi dan rakan sekerja yang lain masih bekerja lagi.</em></p>', NULL, NULL, '2024-12-04 11:30:18', '2024-12-04 11:30:18', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2289, 688, 3, '<p>Kebanyakan masa membersihkan kawasan production pada masa yang ditetapkan.</p><p>Kadangkala membersihkan kawasan production pada masa yang ditetapkan tetapi keadaan tidak ketara.</p><p><br />\nContoh: Kadangkala ada berada di production semasa pembersihan kawasan dijalankan tetapi kebanyakan masa tidak nampak orang.</p>', NULL, NULL, '2024-12-04 11:30:28', '2024-12-04 11:30:28', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2290, 688, 4, '<p>Sentiasa mengutamakan dan membersihkan kawasan production pada masa yang ditetapkan.<br /><br /><em>Contoh: Sentiasa membersihkan kawasan production pada masa yang ditetapkan.</em></p>', NULL, NULL, '2024-12-04 11:30:37', '2024-12-04 11:30:37', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2291, 688, 5, '<p>Mengutamakan dan membersihkan kawasan production pada masa yang ditetapkan serta memberi nasihat kepada rakan sekerja yang tidak berbuat demikian.<br /><br /><em>Contoh: Sentiasa membersihkan kawasan production pada masa yang ditetapkan dan memberi nasihat kepada rakan sekerja yang tidak berbuat demikian.</em></p>', NULL, NULL, '2024-12-04 11:30:46', '2024-12-04 11:30:46', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2292, 689, 1, '<p>Hanya menghormati pegawai atasan dan tidak bersopan dengan rakan sekerja.<br /><br /><em>Contoh: Hanya menghormati Leader/Supervisor atau pangkat kerja yang lebih tinggi tetapi tidak bersopan dengan rakan sekerja yang berpangkat rendah/masih baru.</em></p>', NULL, NULL, '2024-12-04 11:31:07', '2024-12-04 11:31:07', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2293, 689, 2, '<p>Biasanya akan bersopan dan menghormati orang lain tetapi kadangkala beremosi.<br /><br /><em>Contoh: Biasanya bersopan dan menghormati rakan sekerja yang lain tetapi kadangkala beremosi dan lawan cakap.</em></p>', NULL, NULL, '2024-12-04 11:31:15', '2024-12-04 11:31:15', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2294, 689, 3, '<p>Sering bersopan dan menghormati orang lain dan tidak bertindak mengikut perasaan.<br /><br /><em>Contoh: Sering bersopan dan menghormati rakan sekerja lain dan tidak bertindak mengikut perasaan.</em></p>', NULL, NULL, '2024-12-04 11:31:42', '2024-12-04 11:31:42', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2295, 689, 4, '<p>Bersopan dan menghormati orang lain pada setiap masa dan tidak bertindak mengikut perasaan dan berbahasa sopan.<br /><br /><em>Contoh: Bersopan dan setiap masa menghormati rakan sekerja yang lain dan tidak bertindak mengikut perasaan dan berbahasa sopan serta jaga perasaan rakan lain.</em></p>', NULL, NULL, '2024-12-04 11:31:55', '2024-12-04 11:31:55', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2296, 689, 5, '<p>Bersopan dan menghormati orang lain pada setiap masa dan masih bercakap dengan sopan walaupun sendiri telah dipersalahkan dalam proses penyelesaian masalah.<br /><br /><em>Contoh: Bersopan dan setiap masa menghormati rakan sekerja yang lain dan masih bercakap dengan sopan walaupun sendiri telah dipersalahkan dalam proses penyelesaian masalah.</em></p>', NULL, NULL, '2024-12-04 11:32:04', '2024-12-04 11:34:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2297, 690, 1, '<p>Memang mengetahui arahan yang diberi mempunyai kesilapan tetapi tidak mendapatkan kepastian kerana berpendapat itu adalah tanggungjawab pegawai atasan.<br /><br /><em>Contoh: Tidak mendapatkan kepastian daripada Leader/Supervisor tentang spesifikasi kerja yang diberi walaupun sudah tahu arahan yang diberi mempunyai kesilapan/tidak jelas dan beranggap itu adalah tanggungjawab Leader/Supervisor dan bukan dia.</em></p>', NULL, NULL, '2024-12-04 11:36:06', '2024-12-04 11:36:06', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2298, 690, 2, '<p>Jarang berinisiatif untuk mendapatkan kepastian daripada pegawai atasan walaupun arahan yang diberi tidak jelas atau silap.<br /><br /><em>Contoh: Menunjukkan sikap sudah tahu tetapi tidak ingin peduli dan tidak mendapatkan kepastian daripada Leader/Supervisor walapun arahan yang diberi ada kesilapan/kurang jelas.</em></p>', NULL, NULL, '2024-12-04 11:36:15', '2024-12-04 11:36:15', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2299, 690, 3, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap tetapi tidak pernah melapor balik kepada pegawai atasan tentang tugasan tersebut.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi ada kesilapan/tidak jelas tetapi tidak pernah melapor balik tugasan tersebut.</em></p>', NULL, NULL, '2024-12-04 11:36:25', '2024-12-04 11:36:25', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2300, 690, 4, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi tidak jelas/silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut.</em></p>', NULL, NULL, '2024-12-04 11:36:36', '2024-12-04 11:36:36', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2301, 690, 5, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut serta memberi pendapat yang bermanfaat.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi tidak jelas/silap dan selalu melapor balik kepada Leader/Supervisor dan turut mengambil bahagian untuk memberi pendapat yang bermanfaat.</em></p>', NULL, NULL, '2024-12-04 11:36:51', '2024-12-04 11:36:51', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2302, 691, 1, '<p>Degil dan berpegang teguh dengan pendapat sendiri dan tidak menuruti arahan pegawai atasan.<br /><br /><em>Contoh: Tidak menerima dan melawan percakapan Leader/Supervisor semasa diberi tugasan.</em></p>', NULL, NULL, '2024-12-04 11:37:15', '2024-12-04 11:37:15', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2303, 691, 2, '<p>Kebanyakan masa akan menuruti arahan pegawai atasan tetapi kadangkala akan beremosi dan meluahkan ketidakpuasan.<br /><br /><em>Contoh: Kebanyakan masa akan menerima tugasan Leader/Supervisor dengan baik tetapi kadangkala tidak.</em></p>', NULL, NULL, '2024-12-04 11:37:24', '2024-12-04 11:37:24', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2304, 691, 3, '<p>Mengambil berat dan menuruti arahan pegawai atasan dan tidak pernah membuat hal sesuka hati.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati dan akan bertanya jika tidak faham.</em></p>', NULL, NULL, '2024-12-04 11:37:33', '2024-12-04 11:37:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2305, 691, 4, '<p>Mengambil berat dan menuruti arahan pegawai atasan dan tidak pernah membuat hal sesuka hati. Kadangkala turut memberikan pendapat yang bermanfaat dalan kerja yang diberi.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati dan akan bertanya jika tidak faham. Kadangkala turut memberi cadangan/pandangan dalam kerja yang diberi.</em></p>', NULL, NULL, '2024-12-04 11:37:41', '2024-12-04 11:37:41', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2306, 691, 5, '<p>Bersikap positif dan menuruti semua arahan pegawai atasan, tidak membuat hal malah dapat menyampaikan objektif dan kehendak arahan secara positif kepada semua rakan sekerja.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati. Turut menyampaikan maksud dan kehendak mengikuti arahan Leader/Supervisor secara positif kepada rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-12-04 11:37:51', '2024-12-04 11:37:51', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2307, 692, 1, '<p>Ego dan tidak sudi berbincang tugasan sesama rakan sekerja dan pegawai atasan, sangat keras kepala dan tidak dapat menerima cadangan orang lain.<br /><br /><em>Contoh: Buat kerja tanpa ikut pelan kerja seperti menebuk drill pada kelajuan yang tinggi dan telah membesarkan lubang 3mm kepada 3.20 mm. Dia tidak dapat menerima apabila diminta buat semula pada kelajuan drill yang rendah.</em></p>', NULL, NULL, '2024-12-04 11:38:20', '2024-12-04 11:38:20', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2308, 692, 2, '<p>Jarang berbincang tugasan sesama rakan sekerja dan pegawai atasan dan tidak begitu rela berkongsi maklumat, kadangkala keras kepala dan tidak dapat menerima cadangan orang lain.<br /><br /><em>Contoh: Dia menunjukkan sikap yang tidak begitu gembira apabila diminta buat semula pada kelajuan drill yang rendah.</em></p>', NULL, NULL, '2024-12-04 11:38:30', '2024-12-04 11:38:30', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2309, 692, 3, '<p>Sudi berbincang dan menerima cadangan rakan sekerja dan pegawai atasan, dapat memberi pertolongan apabila diminta.<br /><br /><em>Contoh: Dia sudi membuat semula pada kelajuan drill yang rendah setelah berbincang dan diminta berubah.</em></p>', NULL, NULL, '2024-12-04 11:38:40', '2024-12-04 11:38:40', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2310, 692, 4, '<p>Sudi berbincang dan berinisiatif memberi pertolongan sesama rakan sekerja dan pegawai atasan dengan tidak berkira kerja. Boleh menerima cadangan orang lain dan tidak berkeras kepala.<br /><br /><em>Contoh: Dia sudi membuat semula pada kelajuan drill yang rendah dan dia turut memberi cadangan untuk mengatasi masalah tersebut.</em></p>', NULL, NULL, '2024-12-04 11:38:49', '2024-12-04 11:38:49', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2311, 692, 5, '<p>Sudi berbincang dan berinisiatif memberi pertolongan sesama rakan sekerja dan pegawai atasan dengan tidak berkira kerja. Boleh menerima cadangan orang lain dan tidak berkeras kepala. Selain itu, turut boleh memanggil rakan sekerja untuk sama-sama menyiapkan kerja tersebut.<br /><br /><em>Contoh: Dia ialah orang yang sangat agresif dan sudi membuat semula dan dia turut boleh meminta rakan sekerja untuk sama-sama menyiapkan kerja.</em></p>', NULL, NULL, '2024-12-04 11:38:59', '2024-12-04 11:38:59', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2312, 693, 1, '<p>Menolak tugasan selain dari bidang sendiri dan langsung tidak dapat menerima tugasan tambahan atau di luar bidang kerja, amat mementingkan diri sendiri.<br /><br /><em>Contoh: Tidak mahu backup rakan sekerja yang bercuti dan selalu dipengaruhi oleh rakan sekerja yang lain dimana orang yang berbuat banyak tidak dapat apa-apa.</em></p>', NULL, NULL, '2024-12-04 11:39:19', '2024-12-04 11:39:19', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2313, 693, 2, '<p>Kadangkala menerima tugasan tambahan atau di luar bidang kerja tetapi dengan hati yang tidak rela dan mementingkan kepentingan diri sendiri.<br /><br /><em>Contoh: Kadangkala akan diminta untuk backup rakan sekerja yang bercuti tetapi dia akan membuat kerja secara tidak rela / memberi alasan bahawa dia tidak tahu buat kerja tersebut.</em></p>', NULL, NULL, '2024-12-04 11:39:28', '2024-12-04 11:39:28', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2314, 693, 3, '<p>Rela menerima tugasan tambahan atau di luar bidang dan tidak menolak apabila tugas diberi.<br /><br /><em>Contoh: Rela backup rakan sekerja yang bercuti dan tidak menolak apabila tugas diberi oleh Leader/Supervisor.</em></p>', NULL, NULL, '2024-12-04 11:39:36', '2024-12-04 11:39:36', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2315, 693, 4, '<p>Rela menerima tugasan tambahan atau di luar bidang dan tidak menolak apabila tugas diberi serta cuba mencari cara untuk menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Rela backup rakan sekerja yang bercuti dan tidak menolak apabila tugas diberi oleh Leader / Supervisor. Selain itu, dia juga cari jalan untuk mengeluarkan hasil kerja yang baik / membuat kerja tersebut dengan bersungguh-sungguh.</em></p>', NULL, NULL, '2024-12-04 11:39:45', '2024-12-04 11:39:45', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2316, 693, 5, '<p>Amat rela menerima tugasan tambahan atau di luar bidang dan menerimanya sebagai satu cabaran. Berusaha dan bertanggungjawab sepenuhnya sehingga tugasan selesai dengan sempurna.<br /><br /><em>Contoh: Sangat rela backup rakan sekerja yang bercuti dan menganggap tugas yang diberi tersebut sebagai satu cabaran / tugas sendiri. Dia membuat kerja dengan sepenuh hati dan mengambil tanggungjawab sehingga tugasan tersebut selesai dengan sempurnanya.</em></p>', NULL, NULL, '2024-12-04 11:39:56', '2024-12-04 11:39:56', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2317, 706, 1, '<p>Tidak dapat membuat apa-apa analisis dengan data yang ada dan tidak dapat mengenal pasti masalah-masalah.</p>', NULL, NULL, '2024-12-04 11:49:28', '2024-12-04 11:49:28', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2318, 706, 2, '<p>Dapat menganalisis data yand ada dan kadang-kala dapat mencari punca masalah.</p>', NULL, NULL, '2024-12-04 11:49:37', '2024-12-04 11:49:37', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2319, 706, 3, '<p>Dapat menganalisis data yang ada dan mencari punca masalah yang sering berlaku dan cuba memberi cadangan kepada pihak berkenaan untuk menyelesaikan masalah.</p>', NULL, NULL, '2024-12-04 11:49:48', '2024-12-04 11:49:48', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2320, 706, 4, '<p>Dapat menganalisis data yang diperoleh, mengenal pasti masalah dengan tepat dan dapat memberi cadangan dan berusaha melaksanakan pembetulan supaya masalah tidak berlaku lagi.</p>', NULL, NULL, '2024-12-04 11:49:57', '2024-12-04 11:49:57', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2321, 706, 5, '<p>Dapat berfikir untuk mendapat data untuk dianalisis dan menggunakan data yang diperoleh untuk mengkaji punca masalah dan membuat satu piawaian dan memastikan piawaian dapat diikut dan masalah tidak berlaku lagi.</p>', NULL, NULL, '2024-12-04 11:50:07', '2024-12-04 11:50:07', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2322, 707, 1, '<p>Tidak dapat menyelesaikan masalah dan perlu selalu merujuk kepada senior.</p>', NULL, NULL, '2024-12-04 11:50:30', '2024-12-04 11:50:30', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2323, 707, 2, '<p>Hanya dapat menyelesaikan masalah yang ringkas dan tidak dapat membuat keputusan dan perlu merujuk kepada senior.</p>', NULL, NULL, '2024-12-04 11:50:39', '2024-12-04 11:50:39', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2324, 707, 3, '<p>Dapat menyelesaikan masalah-masalah yang dihadapi dengan cermat dan membuat keputusan yang betul untuk menyelesaikan masalah dalam masa tersingkat.</p>', NULL, NULL, '2024-12-04 11:50:48', '2024-12-04 11:50:48', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2325, 707, 4, '<p>Dapat mengambil keputusan untuk menyelesaikan masalah-masalah yang dihadapi dalam masa tersingkat dan &ldquo;follow up&rdquo; supaya dapat memastikan tiada lagi masalah yang tertimbul sehingga masalah diselesaikan dan melaporkan kepada pihak atasan tentang masalah tersebut.</p>', NULL, NULL, '2024-12-04 11:51:48', '2024-12-04 11:51:48', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2326, 707, 5, '<p>Dapat mengambil keputusan untuk menyelesaikan masalah-masalah yang dihadapi dalam masa tersingkat dan &ldquo;follow up&rdquo; sehingga masalah diselesaikan dan melaporkan kepada pihak atasan tentang masalah yang dihadapi. Di samping itu, dapat memberi pendapat dan cadangan supaya perkara tersebut tidak berlaku lagi.</p>', NULL, NULL, '2024-12-04 11:51:57', '2024-12-04 11:51:57', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2327, 708, 1, '<p>Kerja tidak sistematik dan selalu terlupa kerja yang diberikan. Rekod kerja juga tidak dibuat dan tidak dapat kesan balik rekod kerja.</p>', NULL, NULL, '2024-12-04 11:52:22', '2024-12-04 11:52:42', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2328, 708, 2, '<p>Kerja dilakukan tidak bersistematik dan kadang-kala terlupa akan kerja yang diberikan. Di samping itu, kerja yang dibuat tidak di rekod dengan teliti dan susah untuk dikesan balik.</p>', NULL, NULL, '2024-12-04 11:52:33', '2024-12-04 11:52:33', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2329, 708, 3, '<p>Dapat melakukan kerja dengan sistematik, satu demi satu dan merekodkan semua kerja yang diberikan.</p>', NULL, NULL, '2024-12-04 11:52:52', '2024-12-04 11:52:52', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2330, 708, 4, '<p>Dapat melakukan kerja dengan sistematik, merekodkan semua kerja yang diberikan dan dapat dikesan balik setiap rekod. Di samping itu, &ldquo;follow up&rdquo; setiap rekod dan pastikan setiap rekod sempurna.</p>', NULL, NULL, '2024-12-04 11:53:00', '2024-12-04 11:53:00', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2331, 708, 5, '<p>Dapat merancang kerja sendiri dengan sistematik, mencipta dan membuat rekod dan sistem sendiri untuk pastikan kerja direkodkan dan dapat dikesan balik apabila diperlukan.</p>', NULL, NULL, '2024-12-04 11:53:09', '2024-12-04 11:53:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2332, 709, 1, '<p>Seorang yang tidak bertanggungjawab dan tidak berusaha dalam kerjayanya.</p>', NULL, NULL, '2024-12-04 11:53:32', '2024-12-04 11:53:32', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2333, 709, 2, '<p>Seorang yang bertanggungjawab tetapi tidak berkepercayaan kuat terhadap setiap tujuan dan hala organisasi.</p>', NULL, NULL, '2024-12-04 11:53:41', '2024-12-04 11:53:41', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2334, 709, 3, '<p>Seorang yang bersikap positif dan bertanggungjawab. Berkepercayaan kuat terhadap setiap tujuan dan hala organisasi dan berkemahuan berusaha untuk kepentingan organisasi dan berkeinginan yang kuat (loyalty) untuk mempertahankan kedudukan sebagai anggota organisasi.</p>', NULL, NULL, '2024-12-04 11:53:49', '2024-12-04 11:53:49', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2335, 709, 4, '<p>Seorang yang bersikap positif dan bertanggungjawab. Berkepercayaan kuat terhadap setiap tujuan dan hala organisasi dan berkemahuan berusaha untuk kepentingan organisasi dan berkeinginan yang kuat (loyalty) untuk mempertahankan kedudukan sebagai anggota organisasi. Selain itu, turut memberi nasihat jika terdapat rakan sekerja yang tidak sehaluan dengan pihak syarikat.</p>', NULL, NULL, '2024-12-04 11:53:58', '2024-12-04 11:53:58', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2336, 709, 5, '<p>Seorang yang bersikap positif dan bertanggungjawab. Berkepercayaan kuat terhadap setiap tujuan dan hala organisasi dan berkemahuan berusaha untuk kepentingan organisasi dan berkeinginan yang kuat (loyalty) untuk mempertahankan kedudukan sebagai anggota organisasi. Selain itu, turut memberi nasihat jika terdapat rakan sekerja yang tidak sehaluan dengan pihak syarikat dan sentiasa mempengaruhi rakan sekerja yang lain komitmen terhadap kerja demi kebaikan bersama.</p>', NULL, NULL, '2024-12-04 11:54:07', '2024-12-04 11:54:07', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2337, 710, 1, '<p>Bersikap negatif dan sentiasa mengadu dan membawa pengaruh negatif di kalangan rakan sekerja.</p>', NULL, NULL, '2024-12-04 11:54:26', '2024-12-04 11:54:26', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2338, 710, 2, '<p>Memerlukan motivasi daripada rakan sekerja tetapi tidak pernah membawa pengaruh negatif di kalangan rakan sekerja.</p>', NULL, NULL, '2024-12-04 11:54:35', '2024-12-04 11:54:35', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2339, 710, 3, '<p>Boleh memotivasikan rakan sekerja tetapi hasilnya tidak begitu besar.</p>', NULL, NULL, '2024-12-04 11:54:45', '2024-12-04 11:54:45', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2340, 710, 4, '<p>Boleh memotivasikan rakan sekerja dengan membawa hasil yang baik di mana tahu menggunakan keadaan dan kandungan kerja sebagai panduan memotivasikan orang lain.</p>', NULL, NULL, '2024-12-04 11:54:53', '2024-12-04 11:54:53', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2341, 710, 5, '<p>Boleh memotivasikan rakan sekerja dengan membawa hasil yang baik di mana tahu menggunakan keadaan dan kandungan kerja sebagai panduan memotivasikan orang lain. Selain itu akan melaporkan kesilapan rakan sekerja yang tidak mematuhi peraturan syarikat demi kebaikan bersama supaya tidak membawa pengaruh negatif kepada rakan sekerja yang lain.</p>', NULL, NULL, '2024-12-04 11:55:05', '2024-12-04 11:55:05', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2342, 711, 1, '<p>Tidak membuat kerja secara sistematik dan tidak tahu membezakan kepentingan kerja.<br /><br /><em>Contoh: Tidak tahu membezakan kepentingan kerja dan tidak buat perancangan kerja.</em></p>', NULL, NULL, '2024-12-04 11:55:55', '2024-12-04 11:55:55', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2343, 711, 2, '<p>Kadangkala ada membuat kerja secara sistematik dan kadangkala tahu membezakan kepentingan kerja tetapi keadaan tidak ketara.<br /><br /><em>Contoh: Kadangkala tahu membezakan kepentingan kerja dan buat perancangan kerja tetapi tidak selalu dan ikut mood sendiri.</em></p>', NULL, NULL, '2024-12-04 11:56:04', '2024-12-04 11:56:04', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2344, 711, 3, '<p>Tidak perlu seseorang mengawasi di tepi dan tahu membuat kerja secara sistematik dan tahu membezakan kepentingan kerja dengan penjelasan yang ringkas sahaja.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan memerlukan penjelasan kerja yang ringkas sahaja.</em></p>', NULL, NULL, '2024-12-04 11:56:17', '2024-12-04 11:56:17', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2345, 711, 4, '<p>Hanya memerlukan penjelasan yang ringkas dan tahu membuat kerja secara sistematik dan tahu membezakan kepentingan kerja. Berhati-hati dan tiada kesilapan dalam kerja yang dihasilkan.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan hanya memerlukan penjelasan kerja yang ringkas sahaja dan memberi tumpuan dalam kerja dan mengeluarkan hasil kerja yang baik.</em></p>', NULL, NULL, '2024-12-04 11:56:26', '2024-12-04 11:56:26', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2346, 711, 5, '<p>Hanya memerlukan penjelasan yang sangat ringkas sahaja untuk membuat kerja secara sistematik dan tahu membezakan kepentingan kerja dan dapat memberi tunjuk ajar kepada rakan sekerja.<br /><br /><em>Contoh: Tahu membezakan kepentingan kerja dan buat perancangan kerja dan hanya memerlukan penjelasan kerja yang ringkas sahaja dan memberi tumpuan dalam kerja dan mengeluarkan hasil kerja yang baik dan turut memberi tunjuk ajar kepada rakan sekerja.</em></p>', NULL, NULL, '2024-12-04 11:56:36', '2024-12-04 11:56:36', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2347, 712, 1, '<p>Hasil kerja yang tidak boleh diterima dan selalu membuat kesilapan.<br /><br /><em>Contoh: Tidak menumpu perhatian semasa bekerja dan selalu membuat kesilapan yang sama. Tidak pernah berubah walaupun &nbsp;sudah diberi bimbingan/teguran seperti selalu mengulangi kesilapan yang sama walaupun sudah banyak kali memasang mesin yang sama model.</em></p>', NULL, NULL, '2024-12-04 11:58:21', '2024-12-04 11:58:21', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2348, 712, 2, '<p>Cuai dan mengakibatkan kesilapan kerja.<br /><br /><em>Contoh: Kadangkala cuai semasa bekerja dan mengakibatkan kesilapan kerja kerana tindakan yang lambat untuk berubah setelah diberi bimbingan/teguran.</em></p>', NULL, NULL, '2024-12-04 11:58:32', '2024-12-04 11:58:32', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2349, 712, 3, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan meminimumkan tahap kesilapan kepada yang terendah.<br /><br /><em>Contoh: Kadangkala ada membuat kesilapan tetapi mengambil tindakan yang cepat untuk berubah setelah diberi bimbingan/teguran.</em></p>', NULL, NULL, '2024-12-04 11:58:42', '2024-12-04 11:58:42', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2350, 712, 4, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan apa-apa kesilapan dalam kerja harian.<br /><br /><em>Contoh: Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan. Selain itu, juga berinisiatif untuk menjaga barangan/bahan dan tidak membazir.</em></p>', NULL, NULL, '2024-12-04 11:58:57', '2024-12-04 11:58:57', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2351, 712, 5, '<p>Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan kerja dan berinisiatif untuk memberi pendapat dan memperbaiki cara kerja yang lebih baik untuk meminimumkan tahap kesilapan kerja.<br /><br /><em>Contoh: Berhati-hati dalam menjalankan setiap tugasan yang diberi dan tidak melakukan kesilapan dan berinisiatif untuk memberi pendapat dan memperbaiki cara kerja untuk meminimumkan tahap kesilapan kerja seperti berinisiatif untuk mengetahui masalah semasa pemasangan mesin dan turut memberi pendapat untuk memperbaiki cara kerja/menyelesaikan masalah.</em></p>', NULL, NULL, '2024-12-04 11:59:08', '2024-12-04 11:59:08', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2352, 713, 1, '<p>Langsung tidak memahami permintaan kualiti kerja dan tidak memberi perhatian kepada kerja yang dilakukan.<br /><br /><em>Contoh: Langsung tidak memahami permintaan kualiti kerja dan tidak memberi perhatian terhadap semua kerja yang dilakukan seperti membuat pemasangan Control Panel tetapi langsung tidak mengikut diagram yang diberi.</em></p>', NULL, NULL, '2024-12-04 11:59:27', '2024-12-04 11:59:27', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2353, 713, 2, '<p>Kadangkala tidak faham spesifikasi kerja yang diberi dan tidak berinisiatif mengambil langkah untuk mengetahui untuk menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Tidak berinisiatif untuk bertanya/kurang bertanya apabila tidak tahu semasa memasang Control Panel dan pasang ikut sendiri dan tidak ikut cara kerja yang betul.</em></p>', NULL, NULL, '2024-12-04 11:59:36', '2024-12-04 11:59:36', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2354, 713, 3, '<p>Memahami permintaan kualiti kerja dan dapat menghasilkan kerja yang berkualiti secara individu tanpa pengawasan pegawai atasan tetapi tidak mengambil perhatian dan abaikan kerja yang remeh temeh serta tidak mengambil perhatian terhadap kekemasan hasil kerja.<br /><br /><em>Contoh: Tahu pasang Control Panel tetapi tidak terfikir tentang kekemasan. Wayar sudah ditarik dengan betul tetapi tidak diikat dengan cable tie/tidak tersusun/tidak label semasa membuat pemasangan.</em></p>', NULL, NULL, '2024-12-04 11:59:45', '2024-12-04 11:59:45', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2355, 713, 4, '<p>Faham tentang kualiti dan dapat menghasilkan kerja yang berkualiti dan memenuhi kehendak syarikat dan dapat memastikan kerja yang dihasilkan tidak bermasalah.<br /><br /><em>Contoh: Faham tentang kualiti kerja dan ikut semua spesifikasi yang diminta. Boleh berfikir dan nampak (meramalkan) ke hadapan dan memastikan kerja yang dihasilkan tidak bermasalah seperti tahu pasang Control Panel dan semua litar boleh berfungsi dengan baik dan pemasangan yang kemas dan melaporkan keadaan kepada Leader/Supervisor apabila litar tidak berfungsi/bernyala.</em></p>', NULL, NULL, '2024-12-04 11:59:54', '2024-12-04 11:59:54', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2356, 713, 5, '<p>Sangat faham tentang kualiti kerja dan dapat menghasilkan kerja yang berkualiti dan memenuhi kehendak syarikat dan dapat memastikan kerja yang dihasilkan tidak bermasalah serta turut memberi tunjuk ajar kepada rakan kerja yang lain.&nbsp;<br /><br /><em>Contoh: Sangat faham tentang kualiti kerja dan ikut semua spesifikasi yang diminta. Boleh berfikir dan nampak (meramalkan) ke hadapan dan memastikan kerja yang dihasilkan tidak bermasalah. Selain itu, juga dapat memberi tunjuk ajar kepada rakan sekerja yang lain seperti tahu pasang Control Panel dan semua litar boleh berfungsi dengan baik dan pemasangan yang kemas dan melaporkan keadaan kepada Leader/Supervisor apabila litar tidak berfungsi/bernyala. Selain itu, dia juga memberi tunjuk ajar kepada rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-12-04 12:00:03', '2024-12-04 12:00:03', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2357, 714, 1, '<p>Sentiasa membazirkan/merosakkan sumber syarikat.<br /><br /><em>Contoh: Tidak pernah berhati-hati dalam spesifikasi kerja yang diberi dan sentiasa mengakibatkan pembaziran bahan.</em></p>', NULL, NULL, '2024-12-04 12:00:24', '2024-12-04 12:00:24', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2358, 714, 2, '<p>Ada bersikap mahu menjimatkan sumber syarikat tetapi kadangkala menyebabkan pembaziran di atas kecuaiannya.<br /><br /><em>Contoh: Cuai dalam pembacaan spesifikasi kerja yang diberi dan silap ambil bahan dan menyebabkan kesilapan dan membazirkan bahan serta perlu &ldquo;rework&rdquo;.</em></p>', NULL, NULL, '2024-12-04 12:00:35', '2024-12-04 12:00:35', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2359, 714, 3, '<p>Berhati-hati semasa bekerja dan menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dan memastikan betul supaya tidak berlaku kesilapan yang mengakibatkan pembaziran bahan dan buang masa.</em></p>', NULL, NULL, '2024-12-04 12:00:45', '2024-12-04 12:00:45', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2360, 714, 4, '<p>Berhati-hati semasa bekerja dan berinisiatif menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya. Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dengan pelan kerja dan memastikan semua barang yang ambil adalah betul. Ada pemikiran tidak membazir seperti dalam menghasilkan sesuatu barang yang sangat kecil, dia akan cari scrap dahulu dan tidak guna bahan yang baru atau bahan yang besar.Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan.</em></p>', NULL, NULL, '2024-12-04 12:00:54', '2024-12-04 12:00:54', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2361, 714, 5, '<p>Berhati-hati semasa bekerja dan berinisiatif menjimatkan sumber syarikat demi kebaikan bersama. Tidak menyebabkan pembaziran di atas sikap kecuaiannya. Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan dan juga menyedarkan dan membetulkan kesilapan rakan sekerja yang lain.<br /><br /><em>Contoh: Memeriksa semua spesifikasi kerja yang diberi dengan pelan kerja dan memastikan semua barang yang ambil adalah betul. Ada pemikiran tidak membazir seperti dalam menghasilkan sesuatu barang yang sangat kecil, dia akan cari scrap dahulu dan tidak guna bahan yang baru atau bahan yang besar.Selain itu, akan melaporkan keadaan pembaziran kepada pihak atasan dan menyedarkan dan membetulkan kesilapan rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-12-04 12:01:06', '2024-12-04 12:01:06', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2362, 715, 1, '<p>Pengetahuan atau kemahiran adalah terhad dan tidak dapat menyelesaikan tugasan dan menggunakan masa yang panjang untuk mempelajari pengetahuan dan cara kerja yang agak senang.<br /><br /><em>Contoh: Tidak ada pengetahuan dan kemahiran kerja dan menggunakan masa yang panjang untuk mempelajari cara kerja yang senang walaupun bimbingan telah diberi seperti membuat kerja kimpalan yang paling senang iaitu mengimpal besi dalam kedudukan rata.</em></p>', NULL, NULL, '2024-12-04 12:01:27', '2024-12-04 12:01:27', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2363, 715, 2, '<p>Kurang pengetahuan atau kemahiran yang cukup untuk mengendalikan tugasan.<br /><br /><em>Contoh: Hasil kimpalan yang teruk dan bimbingan masih diperlukan walaupun diminta menghasilkan kerja kimpalan yang agak senang seperti mengimpal besi dalam kedudukan rata dan mendatar.</em></p>', NULL, NULL, '2024-12-04 12:01:37', '2024-12-04 12:01:37', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2364, 715, 3, '<p>Mempunyai pengetahuan dan kemahiran untuk mengendalikan tugasan dan mempunyai sikap mahu belajar dan mempelajari pengetahuan kerja yang baru dalam masa yang singkat dan mengimplikasikan dalam kerja harian.<br /><br /><em>Contoh: Ada pengetahuan dan kemahiran kimpalan tetapi tidak dapat meneruskan kerja apabila menghadapi kerja yang tidak biasa dan memerlukan bimbingan seperti: boleh mengimpal besi yang nipis tetapi tidak apabila diminta mengimpal besi yang lagi nipis / boleh mengimpal dalam kedudukan rata, mendatar dan menegak tetapi tidak apabila dalam keadaan overhead atau dalam keadaan 45 darjah.</em></p>', NULL, NULL, '2024-12-04 12:01:46', '2024-12-04 12:01:46', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2365, 715, 4, '<p>Boleh menguasai pengetahuan dan kemahiran untuk mengendalikan tugasan dan pencapaian yang agak memuaskan dan dapat menggunakan pengetahuannya untuk meningkatkan kualiti kerja.<br /><br /><em>Contoh: Mempunyai pengetahuan dan kemahiran yang luas serta jelas dengan semua keperluan/permintaan kerja seperti memilih kaedah yang bersesuaian untuk menghasilkan kerja dan tahu mengawal had api untuk mencegah hasil kerja dari kerosakan.</em></p>', NULL, NULL, '2024-12-04 12:01:57', '2024-12-04 12:01:57', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2366, 715, 5, '<p>Menguasai pengetahuan dan kemahiran untuk mengendalikan tugasan dan boleh menggabungkan pengetahuan untuk meningkatkan kualiti kerja serta mencari cara kerja baru untuk menyelesaikan masalah kerja dengan pengetahuannya.<br /><br /><em>Contoh: Mempunyai pengetahuan dan kemahiran yang luas serta jelas dengan semua keperluan/permintaan kerja dan berinisiatif memberi cadangan untuk menyelesaikan masalah kerja.&nbsp;</em></p>', NULL, NULL, '2024-12-04 12:02:06', '2024-12-04 12:02:06', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2367, 716, 1, '<p>Tidak pernah mengemas dan membersihkan tempat kerja sendiri dan sentiasa mengotorkan tempat kerja sendiri dan rakan sekerja yang lain.<br /><br /><em>Contoh: Tidak pernah terfikir kebaikan bersama dan terus membuang sisa kerja ke lantai dan menganggap ini kerja cleaner untuk membersihkan.</em></p>', NULL, NULL, '2024-12-04 12:02:39', '2024-12-04 12:02:39', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2368, 716, 2, '<p>Kadangkala ada mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya tidak kemas.<br /><br /><em>Contoh: Tidak selalu mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya tidak kemas seperti kadangkala ada membersihkan tempat kerja dan kadangkala tidak.</em></p>', NULL, NULL, '2024-12-04 12:02:47', '2024-12-04 12:02:47', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2369, 716, 3, '<p>Berinisiatif untuk mengemas dan membersihkan tempat kerja dan kebanyakan masa tempat kerjanya adalah kemas dan bersih.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai.</em></p>', NULL, NULL, '2024-12-04 12:02:56', '2024-12-04 12:02:56', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2370, 716, 4, '<p>Selalu mengemas dan membersihkan tempat kerja dan kebanyakan masa mendapati tempat kerjanya kemas dan selalu menolong membersihkan kawasan bahagiannya (division) dan kilang.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai serta tolong membersihkan kawasan yang lain.</em></p>', NULL, NULL, '2024-12-04 12:04:59', '2024-12-04 12:04:59', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2371, 716, 5, '<p>Selalu mengemas dan membersihkan tempat kerja dan tempat kerjanya kelihatan kemas dan bersih. Juga selalu menjaga kebersihan seluruh kawasan kilang dan dapat menegur rakan sekerja untuk menjaga kebersihan kilang.<br /><br /><em>Contoh: Menjaga kebersihan tempat kerja dan tidak membuang sisa kerja ke lantai serta tolong menjaga kebersihan kawasan yang lain dan menegur rakan sekerja yang tidak menjaga kebersihan kilang.</em></p>', NULL, NULL, '2024-12-04 12:05:08', '2024-12-04 12:05:08', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2372, 717, 1, '<p>Tidak menjaga peralatan dan kemudahan syarikat.<br /><br /><em>Contoh: Tidak menjaga peralatan dan kemudahan syarikat seperti tidak menjaga forklift dan tidak pernah meletakkkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-12-04 12:05:27', '2024-12-04 12:05:27', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2373, 717, 2, '<p>Kadangkala bersikap cuai dalam mengendali peralatan dan kemudahan syarikat dan mengakibatkan kerosakan.<br /><br /><em>Contoh: Tidak selalu menjaga peralatan dan kemudahan syarikat dan mengakibatkan kerosakan seperti forklift terus jalan setelah enjin dihidupkan. Tidak mengambil berat tentang barang yang diangkat dan masuk ke ruang yang kecil. Selalu tidak meletakkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-12-04 12:05:36', '2024-12-04 12:05:36', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2374, 717, 3, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat dengan cara yang betul.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna.</em></p>', NULL, NULL, '2024-12-04 12:05:45', '2024-12-04 12:05:45', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2375, 717, 4, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat demi kebaikan bersama. Selain itu, &nbsp;melaporkan kepada pihak atasan bila nampak rakan sekerja salahguna dan memberi cara penyelesaian yang bermanfaat.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna dan melapor jika ada kerosakan dan memberi cadangan untuk memperbaiki cara penggunaan dan penjagaan alatan.</em></p>', NULL, NULL, '2024-12-04 12:05:54', '2024-12-04 12:05:54', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2376, 717, 5, '<p>Berhati-hati semasa bekerja dan menjaga peralatan dan kemudahan syarikat demi kebaikan bersama. Selain itu, &nbsp;melaporkan kepada pihak atasan bila nampak pekerja salahguna dan memberi cara penyelesaian yang bermanfaat. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja.<br /><br /><em>Contoh: Menjaga peralatan dan kemudahan syarikat dengan baik dan berhati-hati semasa mengguna seperti memastikan forklift dalam keadaan yang baik. Memahami keupayaan forklift dengan tidak mengangkat barang yang melebihi had, memeriksa minyak hitam forklift sebelum guna dan meletakkan forklift di tempat yang disediakan selepas diguna dan melapor jika ada kerosakan dan memberi cadangan untuk memperbaiki cara penggunaan dan penjagaan alatan.Selain itu, akan menyedarkan dan menasihati rakan sekerja yang tidak menjaga forklift semasa mengguna.</em></p>', NULL, NULL, '2024-12-04 12:07:31', '2024-12-04 12:07:40', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2377, 718, 1, '<p>Tidak mengutamakan keselamatan semasa bekerja.<br /><br /><em>Contoh: Tidak mengutamakan keselamatan semasa bekerja seperti tidak memakai PPE semasa bekerja.</em></p>', NULL, NULL, '2024-12-04 12:08:01', '2024-12-04 12:08:01', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2378, 718, 2, '<p>Ada sikap mengutamakan keselamatan tetapi kadangkala tidak.<br /><br /><em>Contoh: Ada memakai PPE semasa bekerja tetapi kadangkala tidak.</em></p>', NULL, NULL, '2024-12-04 12:08:10', '2024-12-04 12:08:10', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2379, 718, 3, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja.</em></p>', NULL, NULL, '2024-12-04 12:08:20', '2024-12-04 12:08:20', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2380, 718, 4, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan.</em></p>', NULL, NULL, '2024-12-04 12:08:29', '2024-12-04 12:08:29', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2381, 718, 5, '<p>Berhati-hati semasa bekerja dan menjaga kebaikan bersama. Selain itu, juga menyedarkan dan membetulkan kesilapan rakan sekerja dan melaporkan kepada pihak atasan serta turut memberi cara atau cara penyelesaian yang bermanfaat.<br /><br /><em>Contoh: Sentiasa mementingkan keselamatan dan pasti memakai PPE semasa bekerja dan membetulkan kesilapan rakan sekerja yang tidak mematuhi dan melaporkan kepada pihak atasan serta turut memberi cara atau cara penyelesaian yang bermanfaat.</em></p>', NULL, NULL, '2024-12-04 12:08:39', '2024-12-04 12:08:39', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2382, 719, 1, '<p>Menerima tugasan tetapi tidak memikul tanggungjawab kerja dan tidak dapat bekerja di bawah tekanan.<br /><br /><em>Contoh: Dia terima kerja yang diberi tetapi sentiasa bersembang dengan rakan sekerja dan tidak buat kerja sehingga tidak nampak hasil kerja.</em></p>', NULL, NULL, '2024-12-04 12:09:48', '2024-12-04 12:09:48', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2383, 719, 2, '<p>Boleh menerima dan memikul tanggungjawab dan cuba untuk bekerja di bawah tekanan tetapi kadangkala tidak dapat menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Dia boleh buat kerja dan cuba elakkan diri dari tidak masuk kerja/tidak memberi alasan untuk bercuti tetapi kadangkala masih perlu dalam bimbingan.</em></p>', NULL, NULL, '2024-12-04 12:09:56', '2024-12-04 12:09:56', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2384, 719, 3, '<p>Boleh menerima dan memikul tanggungjawab dan dapat menghabiskan setiap kerja yang diamanahkan dengan baik di bawah tekanan dan melaporkan kerja yang telah dilakukan kepada pegawai atasan.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia masih menepati target dan ikut piawai kerja yang ditetapkan oleh syarikat. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia juga akan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-12-04 12:10:05', '2024-12-04 12:10:05', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2385, 719, 4, '<p>Rela menerima dan memikul tanggungjawab dan sentiasa dapat menghasilkan kerja yang berkualiti di bawah tekanan dan dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang dilakukan kepada pegawai atasan.Boleh buat kerja lebih masa sehingga kerja siap.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia akan menawarkan diri secara sukarela untuk kerja tersebut serta menepati target dan ikut piawai kerja yang ditetapkan oleh syarikat. Boleh buat kerja lebih masa sehingga kerja siap. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-12-04 12:10:19', '2024-12-04 12:10:19', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2386, 719, 5, '<p>Rela menerima dan memikul tanggungjawab dan sentiasa dapat menghasilkan kerja yang berkualiti di bawah tekanan dan dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang dilakukan kepada pegawai atasan.Boleh buat kerja lebih masa sehingga kerja siap.<br /><br /><em>Contoh: Walaupun dalam masa yang singkat, dia akan menawarkan diri secara sukarela untuk kerja tersebut serta menepati target dan ikut piawai kerja yang ditetapkan oleh syarikat. Boleh buat kerja lebih masa sehingga kerja siap. Tidak perlu dibimbing dan boleh selesaikan tugasannya secara individu. Selain itu, dia dapat memberi cara penyelesaian yang bermanfaat semasa menghadapi masalah dan melaporkan kerja yang telah dilakukan kepada Leader/Supervisor.</em></p>', NULL, NULL, '2024-12-04 12:10:49', '2024-12-04 12:10:49', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2387, 720, 1, '<p>Tidak rela mengaku kesilapan dan suka menolak tanggungjawab kepada orang lain.<br /><br /><em>Contoh: Telah melakukan kesilapan seperti tidak mengikuti spesifikasi kerja yang diberi oleh Leader / tidak tanya Leader apabila tidak faham / tanya rakan sekerja yang tidak dipertanggungjawabkan dan tidak pernah mengakui kesilapan apabila ditegur oleh Leader/Supervisor.</em></p>', NULL, NULL, '2024-12-04 12:13:21', '2024-12-04 12:13:21', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2388, 720, 2, '<p>Kadangkala tidak rela mengaku kesilapan dan suka membuat perbandingan diri dengan orang lain dalam kesilapan yang telah dibuat.<br /><br /><em>Contoh: Telah melakukan kesilapan seperti tidak mengikuti spesifikasi kerja yang diberi oleh Leader / tidak tanya Leader apabila tidak faham / tanya rakan sekerja yang tidak dipertanggungjawabkan dan kadangkala tidak mengakui kesilapan apabila ditegur oleh Leader/Supervisor malah menyatakan Leader/Supervisor ada prasangka terhadap dia.</em></p>', NULL, NULL, '2024-12-04 12:13:31', '2024-12-04 12:13:31', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2389, 720, 3, '<p>Mengaku kesilapan dan tidak menolak tanggungjawab kepada orang lain.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan. Dia terima dan mengakui kesilapan.</em></p>', NULL, NULL, '2024-12-04 12:13:40', '2024-12-04 12:13:40', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2390, 720, 4, '<p>Tidak melarikan diri dari tanggungjawab dan terus berjumpa dengan pihak atasan untuk mengakui kesilapan dan berinisiatif untuk memperbaiki kesilapan yang telah dilakukan.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan. Dia tidak melarikan diri dari tanggungjawab dan terus berjumpa dengan Leader/Supervisor dan mengakui kesilapan. Selain itu, dia juga memberi cadangan dan sama-sama memperbaiki kesilapan yang telah dilakukan.</em></p>', NULL, NULL, '2024-12-04 12:13:51', '2024-12-04 12:13:51', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2391, 720, 5, '<p>Berani mengaku kesilapan dan tidak menolak tanggungjawab dan memastikan kesilapan tidak berlaku lagi. Berinisiatif untuk memperbetulkan kesilapan dan dapat memberi cadangan yang bermanfaat untuk mengelakkan kesilapan berlaku lagi.<br /><br /><em>Contoh: Salah faham tentang spesifikasi kerja dari Leader dan buat kerja secara anggapan dan telah melakukan kesilapan yang agak besar. Dia berani mengakui kesilapan dan terus berjumpa dengan Leader/Supervisor untuk mengakui kesilapan. Dia mengambil pengalaman tersebut sebagai satu pengajaran dan tidak mengulangi kesilapan tersebut lagi. Selain itu, dia &nbsp;memberi cadangan dan sama-sama memperbaiki kesilapan yang telah dilakukan serta memberi cadangan yang bermanfaat untuk mengelakkan kesilapan berlaku lagi.</em></p>', NULL, NULL, '2024-12-04 12:14:00', '2024-12-04 12:14:00', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2392, 721, 1, '<p>Membuat kerja alah kadar dan setakat membuat kerja sahaja dan tidak menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Tidak menunjukkan sikap ingin belajar dan tidak menumpukan perhatian semasa bekerja seperti dia boleh mengambil masa yang panjang untuk memasang beberapa nut pada mesin.</em></p>', NULL, NULL, '2024-12-04 12:14:26', '2024-12-04 12:14:26', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2393, 721, 2, '<p>Boleh membuat kerja tetapi mudah dipengaruhi orang lain dan kadangkala tidak dapat menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Dia boleh pasang nut pada mesin tetapi mudah dipengaruhi oleh rakan sekerja yang lain seperti dia akan melambatkan proses kerjanya dan sambil kerja sambil bersembang apabila ada rakan sekerja yang bersembang dengannya semasa bekerja.</em></p>', NULL, NULL, '2024-12-04 12:14:34', '2024-12-04 12:14:34', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2394, 721, 3, '<p>Lebih agresif dan sikap kerja juga serius dan dapat menumpukan perhatian dalam kerja.<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak mengangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja.</em></p>', NULL, NULL, '2024-12-04 12:14:43', '2024-12-04 12:14:43', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2395, 721, 4, '<p>Bersemangat kerja dan menumpukan perhatian sepenuhnya dalam kerja. Sentiasa mengutamakan kualiti kerja dan menghasilkan kerja yang halus dan teliti dan tidak melakukan kesilapan.<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak menggangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja. Dia sentiasa mengutamakan kualiti kerja dan memastikan nut yang dipasang itu betul dan kemas.</em></p>', NULL, NULL, '2024-12-04 12:14:52', '2024-12-04 12:14:52', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2396, 721, 5, '<p>Matlamat untuk berjaya sangat jelas. Menumpukan perhatian sepenuhnya dalam kerja. Sentiasa mengutamakan kualiti kerja dan menghasilkan kerja yang halus dan teliti dan tidak melakukan kesilapan. Selain itu turut memberi cadangan dan cara kerja untuk memastikan kerja berkualiti dihasilkan setiap kali.&nbsp;<br /><br /><em>Contoh: Dia bekerja bersungguh-sungguh dan bersikap serius walaupun cuma memasang nut pada mesin. Dia menumpu perhatian dan tidak menggangu rakan sekerja yang lain seperti bersembang dengan mereka semasa bekerja. Dia sentiasa mengutamakan kualiti kerja dan memastikan nut yang dipasang itu betul dan kemas. Selain itu, dia juga akan memberi cadangan untuk memastikan kerja berkualiti dapat dihasilkan.</em></p>', NULL, NULL, '2024-12-04 12:15:01', '2024-12-04 12:15:01', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2397, 722, 1, '<p>Langsung tidak mahu memahami dan menerima peraturan dan polisi syarikat dan sentiasa membuat aduan terhadap dasar syarikat.<br /><br /><em>Contoh: Selalu tidak menutup lampu setelah mengguna tandas dan membuat aduan apabila pihak syarikat mengambil tindakan.</em></p>', NULL, NULL, '2024-12-04 12:15:37', '2024-12-04 12:15:37', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2398, 722, 2, '<p>Kadangkala sahaja mahu menerima dan mematuhi peraturan dan polisi syarikat.<br /><br /><em>Contoh: Kadangkala ada menutup lampu setelah mengguna tandas kadangkala tidak.</em></p>', NULL, NULL, '2024-12-04 12:15:47', '2024-12-04 12:15:47', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2399, 722, 3, '<p>Menerima dan mematuhi setiap peraturan dan polisi syarikat.<br /><br /><em>Contoh: Setiap kali akan menutup lampu setelah mengguna tandas.</em></p>', NULL, NULL, '2024-12-04 12:15:56', '2024-12-04 12:15:56', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2400, 722, 4, '<p>Tidak melanggar peraturan dan sentiasa dapat menasihatkan rakan sekerja untuk menerima dan mematuhi peraturan dan polisi syarikat untuk kebaikan bersama.<br /><br /><em>Contoh: Sentiasa menutup lampu setelah mengguna tandas dan &nbsp;menasihati dan menerang kepada rakan sekerja yang tidak mematuhi peraturan.</em></p>', NULL, NULL, '2024-12-04 12:16:05', '2024-12-04 12:16:05', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2401, 722, 5, '<p>Memahami dan menerima setiap peraturan dan polisi syarikat dan sentiasa menasihatkan rakan sekerja yang melanggar peraturan serta melaporkan masalah disiplin kepada pegawai atasan untuk kebaikan bersama.<br /><br /><em>Contoh: &nbsp;Sentiasa menutup lampu setelah mengguna tandas dan &nbsp;menasihati dan menerang kepada rakan sekerja yang tidak mematuhi peraturan. Selain itu, juga akan melaporkan nama pekerja yang tidak menutup lampu setelah mengguna tandas.</em></p>', NULL, NULL, '2024-12-04 12:16:16', '2024-12-04 12:16:16', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2402, 723, 1, '<p>Selalu tidak tepat masuk kerja dan menunjukkan kedatangan yang tidak baik.<br /><br /><em>Contoh: Masih berada di tempat berehat semasa siren berbunyi dan jalan perlahan ke tempat kerja.</em></p>', NULL, NULL, '2024-12-04 12:16:37', '2024-12-04 12:16:37', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2403, 723, 2, '<p>Kadangkala ada masuk kerja pada masa yang ditetapkan tetapi keadaan tidak ketara.<br /><br /><em>Contoh: Kadangkala ada tepat masuk kerja semasa siren berbunyi tetapi kebanyakan masa tidak masuk kerja pada masa yang tepat.</em></p>', NULL, NULL, '2024-12-04 12:16:48', '2024-12-04 12:16:48', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2404, 723, 3, '<p>Kebanyakan masa masuk kerja pada masa yang ditetapkan tetapi kadangkala ada lewat juga.<br /><br /><em>Contoh: Kebanyakan masa masuk kerja semasa siren berbunyi tetapi sekali kala masih lewat masuk kerja.</em></p>', NULL, NULL, '2024-12-04 12:16:57', '2024-12-04 12:16:57', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2405, 723, 4, '<p>Mementingkan ketepatan masa masuk kerja dan masuk kerja tepat pada masa atau lebih awal.<br /><br /><em>Contoh: Sentiasa masa masuk kerja sebelum siren berbunyi atau lebih awal.</em></p>', NULL, NULL, '2024-12-04 12:17:06', '2024-12-04 12:17:06', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2406, 723, 5, '<p>Mementingkan ketepatan masa masuk kerja dan masuk kerja tepat pada masa atau lebih awal serta memberi nasihat kepada rakan sekerja yang lewat.<br /><br /><em>Contoh: Sentiasa masa masuk kerja sebelum siren berbunyi atau lebih awal serta memberi nasihat kepada rakan sekerja yang lewat.</em></p>', NULL, NULL, '2024-12-04 12:17:17', '2024-12-04 12:17:17', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2407, 724, 1, '<p>Disiplin diri yang tidak memuaskan dan sering meninggalkan tempat kerja dengan berkeliaran tanpa tujuan dan sering membazirkan masa serta curi tulang.<br /><br /><em>Contoh: Sering meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja (banyak kali sehari) dan mengambil masa yang panjang dalam tandas serta membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-12-04 12:17:37', '2024-12-04 12:17:37', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2408, 724, 2, '<p>Kadangkala membazirkan masa dan curi tulang serta meninggalkan tempat kerja dengan berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Kadangkala meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja (banyak kali sehari) dan mengambil masa yang panjang dalam tandas serta membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-12-04 12:17:46', '2024-12-04 12:17:46', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2409, 724, 3, '<p>Tidak membazirkan masa dan ringan tulang serta menumpukan perhatian semasa bekerja. Tidak meninggalkan tempat kerja dengan berkeliaran tanpa tujuan.<br /><br /><em>Contoh: Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-12-04 12:17:56', '2024-12-04 12:17:56', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2410, 724, 4, '<p>Teladan yang baik dan tumpuan perhatian sepenuhnya semasa bekerja. Tidak berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Seorang teladan yang baik dan memberi tumpuan sepenuhnya semasa bekerja. Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja.</em></p>', NULL, NULL, '2024-12-04 12:18:06', '2024-12-04 12:18:06', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2411, 724, 5, '<p>Teladan yang baik dan tumpuan perhatian sepenuhnya semasa bekerja dan juga selalu memberi nasihat kepada rakan sekerja supaya melahirkan keadaan kerja yang lebih agresif. Tidak berkeliaran tanpa tujuan dan mengganggu kerja rakan sekerja.<br /><br /><em>Contoh: Seorang teladan yang baik dan memberi tumpuan sepenuhnya semasa bekerja. Tidak meninggalkan tempat kerja dengan selalu pergi ke tandas semasa bekerja dan tidak mengambil masa yang panjang dalam tandas serta tidak membazir masa dengan berjalan perlahan dari tandas balik ke tempat kerja. Selalu memberi nasihat kepada rakan sekerja yang selalu pergi ke tandas sebagai alasan.</em></p>', NULL, NULL, '2024-12-04 12:18:15', '2024-12-04 12:18:15', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2412, 725, 1, '<p>Tidak pernah berada di tempat kerja semasa pembersihan kawasan dijalankan.<br /><br /><em>Contoh: Tidak berada di tempat kerja dan pergi ke tandas semasa pembersihan kawasan dijalankan.</em></p>', NULL, NULL, '2024-12-04 12:18:37', '2024-12-04 12:18:37', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2413, 725, 2, '<p>Memulakan kerja pembersihan kawasan walaupun masa yang ditetapkan belum sampai lagi.<br /><br /><em>Contoh: Memulakan kerja pembersihan kawasan walaupun masa yang ditetapkan belum sampai lagi dan rakan sekerja yang lain masih bekerja lagi.</em></p>', NULL, NULL, '2024-12-04 12:18:47', '2024-12-04 12:18:47', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2414, 725, 3, '<p>Kebanyakan masa membersihkan kawasan production pada masa yang ditetapkan.</p><p>Kadangkala membersihkan kawasan production pada masa yang ditetapkan tetapi keadaan tidak ketara.</p><p><br />\nContoh: Kadangkala ada berada di production semasa pembersihan kawasan dijalankan tetapi kebanyakan masa tidak nampak orang.</p>', NULL, NULL, '2024-12-04 12:18:58', '2024-12-04 12:18:58', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2415, 725, 4, '<p>Sentiasa mengutamakan dan membersihkan kawasan production pada masa yang ditetapkan.<br /><br /><em>Contoh: Sentiasa membersihkan kawasan production pada masa yang ditetapkan.</em></p>', NULL, NULL, '2024-12-04 12:19:08', '2024-12-04 12:19:08', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2416, 725, 5, '<p>Mengutamakan dan membersihkan kawasan production pada masa yang ditetapkan serta memberi nasihat kepada rakan sekerja yang tidak berbuat demikian.<br /><br /><em>Contoh: Sentiasa membersihkan kawasan production pada masa yang ditetapkan dan memberi nasihat kepada rakan sekerja yang tidak berbuat demikian.</em></p>', NULL, NULL, '2024-12-04 12:19:17', '2024-12-04 12:19:17', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2417, 726, 1, '<p>Hanya menghormati pegawai atasan dan tidak bersopan dengan rakan sekerja.<br /><br /><em>Contoh: Hanya menghormati Leader/Supervisor atau pangkat kerja yang lebih tinggi tetapi tidak bersopan dengan rakan sekerja yang berpangkat rendah/masih baru.</em></p>', NULL, NULL, '2024-12-04 12:19:36', '2024-12-04 12:19:36', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2418, 726, 2, '<p>Biasanya akan bersopan dan menghormati orang lain tetapi kadangkala beremosi.<br /><br /><em>Contoh: Biasanya bersopan dan menghormati rakan sekerja yang lain tetapi kadangkala beremosi dan lawan cakap.</em></p>', NULL, NULL, '2024-12-04 12:19:46', '2024-12-04 12:19:46', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2419, 726, 3, '<p>Sering bersopan dan menghormati orang lain dan tidak bertindak mengikut perasaan.<br /><br /><em>Contoh: Sering bersopan dan menghormati rakan sekerja lain dan tidak bertindak mengikut perasaan.</em></p>', NULL, NULL, '2024-12-04 12:19:55', '2024-12-04 12:19:55', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2420, 726, 4, '<p>Bersopan dan menghormati orang lain pada setiap masa dan tidak bertindak mengikut perasaan dan berbahasa sopan.<br /><br /><em>Contoh: Bersopan dan setiap masa menghormati rakan sekerja yang lain dan tidak bertindak mengikut perasaan dan berbahasa sopan serta jaga perasaan rakan lain.</em></p>', NULL, NULL, '2024-12-04 12:20:05', '2024-12-04 12:20:05', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2421, 726, 5, '<p>Bersopan dan menghormati orang lain pada setiap masa dan masih bercakap dengan sopan walaupun sendiri telah dipersalahkan dalam proses penyelesaian masalah.<br /><br /><em>Contoh: Bersopan dan setiap masa menghormati rakan sekerja yang lain dan masih bercakap dengan sopan walaupun sendiri telah dipersalahkan dalam proses penyelesaian masalah.</em></p>', NULL, NULL, '2024-12-04 12:20:15', '2024-12-04 12:20:15', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2422, 727, 1, '<p>Memang mengetahui arahan yang diberi mempunyai kesilapan tetapi tidak mendapatkan kepastian kerana berpendapat itu adalah tanggungjawab pegawai atasan.<br /><br /><em>Contoh: Tidak mendapatkan kepastian daripada Leader/Supervisor tentang spesifikasi kerja yang diberi walaupun sudah tahu arahan yang diberi mempunyai kesilapan/tidak jelas dan beranggap itu adalah tanggungjawab Leader/Supervisor dan bukan dia.</em></p>', NULL, NULL, '2024-12-04 12:20:50', '2024-12-04 12:20:50', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2423, 727, 2, '<p>Jarang berinisiatif untuk mendapatkan kepastian daripada pegawai atasan walaupun arahan yang diberi tidak jelas atau silap.<br /><br /><em>Contoh: Menunjukkan sikap sudah tahu tetapi tidak ingin peduli dan tidak mendapatkan kepastian daripada Leader/Supervisor walapun arahan yang diberi ada kesilapan/kurang jelas.</em></p>', NULL, NULL, '2024-12-04 12:21:00', '2024-12-04 12:21:00', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2424, 727, 3, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap tetapi tidak pernah melapor balik kepada pegawai atasan tentang tugasan tersebut.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi ada kesilapan/tidak jelas tetapi tidak pernah melapor balik tugasan tersebut.</em></p>', NULL, NULL, '2024-12-04 12:21:09', '2024-12-04 12:21:09', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2425, 727, 4, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi tidak jelas/silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut.</em></p>', NULL, NULL, '2024-12-04 12:21:20', '2024-12-04 12:21:20', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2426, 727, 5, '<p>Sering berinisiatif mendapatkan kepastian daripada pegawai atasan apabila arahan yang diberi tidak jelas atau silap dan selalu melapor balik kepada pegawai atasan tentang tugasan tersebut serta memberi pendapat yang bermanfaat.<br /><br /><em>Contoh: Berinisiatif untuk mendapatkan kepastian daripada Leader/Supervisor apabila spesifikasi kerja yang diberi tidak jelas/silap dan selalu melapor balik kepada Leader/Supervisor dan turut mengambil bahagian untuk memberi pendapat yang bermanfaat.</em></p>', NULL, NULL, '2024-12-04 12:21:45', '2024-12-04 12:21:45', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2427, 728, 1, '<p>Degil dan berpegang teguh dengan pendapat sendiri dan tidak menuruti arahan pegawai atasan.<br /><br /><em>Contoh: Tidak menerima dan melawan percakapan Leader/Supervisor semasa diberi tugasan.</em></p>', NULL, NULL, '2024-12-04 12:22:31', '2024-12-04 12:22:31', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2428, 728, 2, '<p>Kebanyakan masa akan menuruti arahan pegawai atasan tetapi kadangkala akan beremosi dan meluahkan ketidakpuasan.<br /><br /><em>Contoh: Kebanyakan masa akan menerima tugasan Leader/Supervisor dengan baik tetapi kadangkala tidak.</em></p>', NULL, NULL, '2024-12-04 12:22:41', '2024-12-04 12:22:41', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2429, 728, 3, '<p>Mengambil berat dan menuruti arahan pegawai atasan dan tidak pernah membuat hal sesuka hati.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati dan akan bertanya jika tidak faham.</em></p>', NULL, NULL, '2024-12-04 12:22:51', '2024-12-04 12:22:51', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2430, 728, 4, '<p>Mengambil berat dan menuruti arahan pegawai atasan dan tidak pernah membuat hal sesuka hati. Kadangkala turut memberikan pendapat yang bermanfaat dalan kerja yang diberi.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati dan akan bertanya jika tidak faham. Kadangkala turut memberi cadangan/pandangan dalam kerja yang diberi.</em></p>', NULL, NULL, '2024-12-04 12:23:00', '2024-12-04 12:23:00', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2431, 728, 5, '<p>Bersikap positif dan menuruti semua arahan pegawai atasan, tidak membuat hal malah dapat menyampaikan objektif dan kehendak arahan secara positif kepada semua rakan sekerja.<br /><br /><em>Contoh: Menerima semua tugasan daripada Leader/Supervisor dengan baik dan tidak pernah membuat kerja ikut sesuka hati. Turut menyampaikan maksud dan kehendak mengikuti arahan Leader/Supervisor secara positif kepada rakan sekerja yang lain.</em></p>', NULL, NULL, '2024-12-04 12:23:18', '2024-12-04 12:23:18', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2432, 729, 1, '<p>Ego dan tidak sudi berbincang tugasan sesama rakan sekerja dan pegawai atasan, sangat keras kepala dan tidak dapat menerima cadangan orang lain.<br /><br /><em>Contoh: Buat kerja tanpa ikut pelan kerja seperti menebuk drill pada kelajuan yang tinggi dan telah membesarkan lubang 3mm kepada 3.20 mm. Dia tidak dapat menerima apabila diminta buat semula pada kelajuan drill yang rendah.</em></p>', NULL, NULL, '2024-12-04 12:24:12', '2024-12-04 12:24:12', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2433, 729, 2, '<p>Jarang berbincang tugasan sesama rakan sekerja dan pegawai atasan dan tidak begitu rela berkongsi maklumat, kadangkala keras kepala dan tidak dapat menerima cadangan orang lain.<br /><br /><em>Contoh: Dia menunjukkan sikap yang tidak begitu gembira apabila diminta buat semula pada kelajuan drill yang rendah.</em></p>', NULL, NULL, '2024-12-04 12:24:22', '2024-12-04 12:24:22', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2434, 729, 3, '<p>Sudi berbincang dan menerima cadangan rakan sekerja dan pegawai atasan, dapat memberi pertolongan apabila diminta.<br /><br /><em>Contoh: Dia sudi membuat semula pada kelajuan drill yang rendah setelah berbincang dan diminta berubah.</em></p>', NULL, NULL, '2024-12-04 12:24:32', '2024-12-04 12:24:32', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2435, 729, 4, '<p>Sudi berbincang dan berinisiatif memberi pertolongan sesama rakan sekerja dan pegawai atasan dengan tidak berkira kerja. Boleh menerima cadangan orang lain dan tidak berkeras kepala.<br /><br /><em>Contoh: Dia sudi membuat semula pada kelajuan drill yang rendah dan dia turut memberi cadangan untuk mengatasi masalah tersebut.</em></p>', NULL, NULL, '2024-12-04 12:24:41', '2024-12-04 12:24:41', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2436, 729, 5, '<p>Sudi berbincang dan berinisiatif memberi pertolongan sesama rakan sekerja dan pegawai atasan dengan tidak berkira kerja. Boleh menerima cadangan orang lain dan tidak berkeras kepala. Selain itu, turut boleh memanggil rakan sekerja untuk sama-sama menyiapkan kerja tersebut.<br /><br /><em>Contoh: Dia ialah orang yang sangat agresif dan sudi membuat semula dan dia turut boleh meminta rakan sekerja untuk sama-sama menyiapkan kerja.</em></p>', NULL, NULL, '2024-12-04 12:24:52', '2024-12-04 12:24:52', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2437, 730, 1, '<p>Menolak tugasan selain dari bidang sendiri dan langsung tidak dapat menerima tugasan tambahan atau di luar bidang kerja, amat mementingkan diri sendiri.<br /><br /><em>Contoh: Tidak mahu backup rakan sekerja yang bercuti dan selalu dipengaruhi oleh rakan sekerja yang lain dimana orang yang berbuat banyak tidak dapat apa-apa.</em></p>', NULL, NULL, '2024-12-04 12:25:13', '2024-12-04 12:25:13', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2438, 730, 2, '<p>Kadangkala menerima tugasan tambahan atau di luar bidang kerja tetapi dengan hati yang tidak rela dan mementingkan kepentingan diri sendiri.<br /><br /><em>Contoh: Kadangkala akan diminta untuk backup rakan sekerja yang bercuti tetapi dia akan membuat kerja secara tidak rela / memberi alasan bahawa dia tidak tahu buat kerja tersebut.</em></p>', NULL, NULL, '2024-12-04 12:25:23', '2024-12-04 12:25:23', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2439, 730, 3, '<p>Rela menerima tugasan tambahan atau di luar bidang dan tidak menolak apabila tugas diberi.<br /><br /><em>Contoh: Rela backup rakan sekerja yang bercuti dan tidak menolak apabila tugas diberi oleh Leader/Supervisor.</em></p>', NULL, NULL, '2024-12-04 12:25:32', '2024-12-04 12:25:32', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2440, 730, 4, '<p>Rela menerima tugasan tambahan atau di luar bidang dan tidak menolak apabila tugas diberi serta cuba mencari cara untuk menghasilkan kerja yang berkualiti.<br /><br /><em>Contoh: Rela backup rakan sekerja yang bercuti dan tidak menolak apabila tugas diberi oleh Leader / Supervisor. Selain itu, dia juga cari jalan untuk mengeluarkan hasil kerja yang baik / membuat kerja tersebut dengan bersungguh-sungguh.</em></p>', NULL, NULL, '2024-12-04 12:25:46', '2024-12-04 12:25:46', NULL);
INSERT INTO `hr_appraisal_questions` VALUES (2441, 730, 5, '<p>Amat rela menerima tugasan tambahan atau di luar bidang dan menerimanya sebagai satu cabaran. Berusaha dan bertanggungjawab sepenuhnya sehingga tugasan selesai dengan sempurna.<br /><br /><em>Contoh: Sangat rela backup rakan sekerja yang bercuti dan menganggap tugas yang diberi tersebut sebagai satu cabaran / tugas sendiri. Dia membuat kerja dengan sepenuh hati dan mengambil tanggungjawab sehingga tugasan tersebut selesai dengan sempurnanya.</em></p>', NULL, NULL, '2024-12-04 12:25:56', '2024-12-04 12:25:56', NULL);
INSERT INTO `hr_appraisal_section_subs` VALUES (3, 2, '<p><strong>Produktiviti </strong></p>', 2, NULL, '2024-01-09 16:37:30', '2024-12-04 11:48:53', NULL);
INSERT INTO `hr_appraisal_section_subs` VALUES (14, 4, '<p><strong>Sila nyatakan kelebihan pekerja ini. </strong></p>', 1, NULL, '2024-01-09 16:37:30', '2024-01-09 16:37:30', NULL);
INSERT INTO `hr_appraisal_section_subs` VALUES (15, 4, '<p><strong>Sila nyatakan kekurangan pekerja ini. </strong></p>', 2, NULL, '2024-01-09 16:37:30', '2024-01-09 16:37:30', NULL);
INSERT INTO `hr_appraisal_section_subs` VALUES (16, 4, '<p><strong>Faktor-faktor yang perlu diberi perhatian untuk dipertingkatkan/diperbaiki. </strong></p>', 3, NULL, '2024-01-09 16:37:30', '2024-01-09 16:37:30', NULL);
INSERT INTO `hr_appraisal_section_subs` VALUES (17, 5, '<p><strong>Tahap kemahiran</strong></p>', NULL, NULL, '2024-01-09 16:37:30', '2024-01-09 16:37:30', NULL);
INSERT INTO `hr_appraisal_section_subs` VALUES (66, 36, '<p><strong>Kepimpinan</strong></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
INSERT INTO `hr_appraisal_section_subs` VALUES (67, 36, '<p><strong>Produktiviti</strong></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:19:11', NULL);
INSERT INTO `hr_appraisal_section_subs` VALUES (68, 36, '<p><strong>Pengetahuan Kerja</strong></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:19:20', NULL);
INSERT INTO `hr_appraisal_section_subs` VALUES (69, 36, '<p><strong>Housekeeping</strong></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:19:33', NULL);
INSERT INTO `hr_appraisal_section_subs` VALUES (70, 36, '<p><strong>Sikap</strong></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:19:42', NULL);
INSERT INTO `hr_appraisal_section_subs` VALUES (71, 36, '<p><strong>Disiplin/ Tatatertib</strong></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-08 17:18:34', NULL);
INSERT INTO `hr_appraisal_section_subs` VALUES (72, 36, '<p><strong>Komunikasi</strong></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-08 17:19:55', NULL);
INSERT INTO `hr_appraisal_section_subs` VALUES (73, 36, '<p><strong>Bekerjasama</strong></p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-08 17:18:34', NULL);
INSERT INTO `hr_appraisal_section_subs` VALUES (74, 37, '<p>Technical Drawing Skills - Proficiency in creating detailed, accurate, and clear technical drawings using tools such as AutoCAD, SolidWorks, or other drafting software. - Ability to understand and interpret engineering drawings, specifications, and technical documentation.</p>', 1, NULL, '2024-11-08 17:18:34', '2024-11-08 17:20:11', NULL);
INSERT INTO `hr_appraisal_section_subs` VALUES (75, 37, '<p>CAD / CAM Software Proficiency - Familiarity with CAD / CAM software is crucial. This includes knowledge of AutoCAD, SolidWorks, CypCut, Tubest, MasterCAM.</p>', 2, NULL, '2024-11-08 17:18:34', '2024-11-08 17:20:17', NULL);
INSERT INTO `hr_appraisal_section_subs` VALUES (76, 37, '<p>Geometry and Mathematics - Strong mathematical skills and a good understanding of geometry, including the ability to perform calculations related to dimensions, angles, and tolerances.</p>', 3, NULL, '2024-11-08 17:18:34', '2024-11-08 17:18:34', NULL);
INSERT INTO `hr_appraisal_section_subs` VALUES (77, 37, '<p>Knowledge of Materials and Manufacturing Processes - Understanding of various materials and their properties, as well as knowledge of different manufacturing processes, including machining, welding, and assembly.</p>', 4, NULL, '2024-11-08 17:18:34', '2024-11-08 17:20:24', NULL);
INSERT INTO `hr_appraisal_section_subs` VALUES (78, 37, '<p>Attention to Detail - The ability to pay close attention to detail is essential for creating accurate and error-free technical drawings.</p>', 5, NULL, '2024-11-08 17:18:34', '2024-11-08 17:20:30', NULL);
INSERT INTO `hr_appraisal_section_subs` VALUES (79, 37, '<p>Problem-Solving Skills - The capability to identify and solve problems related to design and drafting, including the ability to suggest improvements and optimizations.</p>', 6, NULL, '2024-11-08 17:18:34', '2024-11-08 17:20:35', NULL);
INSERT INTO `hr_appraisal_section_subs` VALUES (80, 37, '<p>Time Management - Efficient time management to meet project deadlines and handle multiple tasks simultaneously.</p>', 7, NULL, '2024-11-08 17:18:34', '2024-11-08 17:20:41', NULL);
INSERT INTO `hr_appraisal_section_subs` VALUES (81, 37, '<p>3D Modeling Skills - Proficiency in creating 3D models of mechanical components and assemblies to provide a comprehensive view of the design.</p>', 8, NULL, '2024-11-08 17:18:34', '2024-11-08 17:18:34', NULL);
INSERT INTO `hr_appraisal_section_subs` VALUES (82, 37, '<p>Continuous Learning - A willingness to stay updated with the latest advancements in CAD software, industry standards, and manufacturing technologies.</p>', 9, NULL, '2024-11-08 17:18:34', '2024-11-08 17:18:34', NULL);
INSERT INTO `hr_appraisal_section_subs` VALUES (83, 37, '<p>Collaboration and Teamwork - Ability to work collaboratively with engineers, architects, and other professionals as part of a multidisciplinary team.</p>', 10, NULL, '2024-11-08 17:18:34', '2024-11-08 17:20:49', NULL);
INSERT INTO `hr_appraisal_section_subs` VALUES (84, 39, '<p>Sila nyatakan kelebihan pekerja.</p>', 1, NULL, '2024-11-08 17:18:34', '2024-11-08 17:22:22', NULL);
INSERT INTO `hr_appraisal_section_subs` VALUES (85, 39, '<p>Sila nyatakan kelemahan pekerja.</p>', 2, NULL, '2024-11-08 17:18:34', '2024-11-08 17:18:34', NULL);
INSERT INTO `hr_appraisal_section_subs` VALUES (86, 39, '<p>Faktor-faktor yang perlu diberi perhatian untuk dipertingkatkan/diperbaiki.</p>', 3, NULL, '2024-11-08 17:18:34', '2024-11-08 17:22:57', NULL);
INSERT INTO `hr_appraisal_section_subs` VALUES (87, 40, '<p>Tahap kemahiran</p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-08 17:23:06', NULL);
INSERT INTO `hr_appraisal_section_subs` VALUES (88, 40, '<p>Potensi Pertumbuhan</p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-08 17:23:25', NULL);
INSERT INTO `hr_appraisal_section_subs` VALUES (89, 40, '<p>Kebolehan Memimpin (Ciri-ciri kepimpinan : Bekerjasama, kebolehan memimpin di kalangan rakan sekerja dan berkomunikasi baik dengan semua lapisan syarikat.)</p>', NULL, NULL, '2024-11-08 17:18:34', '2024-11-08 17:23:39', NULL);
