INSERT INTO `hr_appraisal_sections` VALUES (21, '<p>Kepimpinan</p><p>Kebolehan menganalisis dan mencari punca masalah.<br />\n(Kebolehan dan keupayaan meneliti, mentafsir dan mencerakin fakta, situasi, kejadian dan arah aliran kepada bentuk yang mudah dan realistik serta mengemukakan cadangan tindakan yang sesuai.)</p>', NULL, NULL, '2024-11-07 16:53:56', '2024-11-07 16:53:56', NULL);
INSERT INTO `hr_appraisal_sections` VALUES (22, '<p>Kepimpinan</p><p>Kebolehan menganalisis dan mencari punca masalah.<br />\n(Kebolehan dan keupayaan meneliti, mentafsir dan mencerakin fakta, situasi, kejadian dan arah aliran kepada bentuk yang mudah dan realistik serta mengemukakan cadangan tindakan yang sesuai.)</p>', '1', NULL, '2024-11-07 16:56:13', '2024-11-07 16:56:13', NULL);
INSERT INTO `hr_appraisal_sections` VALUES (30, '<p>Tidak dapat membuat apa-apa analisis dengan data yang ada dan tidak dapat mengenal pasti masalah-masalah.</p>', '1', NULL, '2024-11-07 17:44:15', '2024-11-07 17:44:15', NULL);
INSERT INTO `hr_appraisal_sections` VALUES (31, '<p>Dapat menganalisis data yand ada dan kadang-kala dapat mencari punca masalah.</p>', '2', NULL, '2024-11-07 17:44:31', '2024-11-07 17:44:31', NULL);
INSERT INTO `hr_appraisal_sections` VALUES (32, '<p>Dapat menganalisis data yang ada dan mencari punca masalah yang sering berlaku dan cuba memberi cadangan kepada pihak berkenaan untuk menyelesaikan masalah.</p>', '3', NULL, '2024-11-07 17:44:44', '2024-11-07 17:44:44', NULL);
INSERT INTO `hr_appraisal_sections` VALUES (33, '<p>Dapat menganalisis data yang diperoleh, mengenal pasti masalah dengan tepat dan dapat memberi cadangan dan berusaha melaksanakan pembetulan supaya masalah tidak berlaku lagi.</p>', '4', NULL, '2024-11-07 17:45:01', '2024-11-07 17:45:01', NULL);
INSERT INTO `hr_appraisal_sections` VALUES (34, '<p>Dapat berfikir untuk mendapat data untuk dianalisis dan menggunakan data yang diperoleh untuk mengkaji punca masalah dan membuat satu piawaian dan memastikan piawaian dapat diikut dan masalah tidak berlaku lagi.</p>', '5', NULL, '2024-11-07 17:45:19', '2024-11-07 17:45:19', NULL);
INSERT INTO `hr_appraisal_sections` VALUES (36, '<p><strong>Bahagian 1 - Prestasi Kerja (Sila jawab semua dan pilih yang berkenaan.)</strong></p>', NULL, NULL, '2024-11-08 17:18:33', '2024-11-08 17:18:33', NULL);
