  `half_type_id` int NULL DEFAULT NULL COMMENT 'morning / afternoon',
  `date_time_start` datetime NULL DEFAULT NULL,
  `date_time_end` datetime NULL DEFAULT NULL,
  `reason` text CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NULL,
  `period_day` float(5, 1) NULL DEFAULT NULL COMMENT 'total day',
  `period_time` time NULL DEFAULT NULL COMMENT 'total time',
  `softcopy` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NULL DEFAULT NULL COMMENT 'upload document softcopy',
  `hardcopy` tinyint(1) NULL DEFAULT NULL COMMENT 'receive hardcopy = 1 / not receive hardcopy = null',
  `leave_status_id` int NULL DEFAULT NULL COMMENT 'user self active/reject/cancel',
  `verify_code` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NULL DEFAULT NULL COMMENT 'verification code to accept the leave',
  `remarks` text CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NULL,
  `created_at` datetime NULL DEFAULT NULL,
  `updated_at` datetime NULL DEFAULT NULL,
  `deleted_at` datetime NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `staff_id`(`staff_id` ASC) USING BTREE,
  INDEX `leave_id`(`leave_type_id` ASC) USING BTREE,
  INDEX `active`(`leave_status_id` ASC) USING BTREE,
  INDEX `hr_leaves_ibfk_4`(`half_type_id` ASC) USING BTREE,
  CONSTRAINT `hr_leaves_ibfk_1` FOREIGN KEY (`staff_id`) REFERENCES `staffs` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `hr_leaves_ibfk_2` FOREIGN KEY (`leave_type_id`) REFERENCES `option_leave_types` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `hr_leaves_ibfk_3` FOREIGN KEY (`leave_status_id`) REFERENCES `option_leave_statuses` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `hr_leaves_ibfk_4` FOREIGN KEY (`half_type_id`) REFERENCES `option_halfday_type` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 13805 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_unicode_ci ROW_FORMAT = DYNAMIC;

